app.MapPost("/api/dealdetail/update-cusinvoice", async (DealDetailCusInvoiceDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.DealNo) && !string.IsNullOrWhiteSpace(r.CarId)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Chưa chọn dòng nào." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    int changedNo = 0, changedDate = 0, skipped = 0;
    foreach (var r in rows)
    {
        var carId = r.CarId!.Trim().ToUpperInvariant();
        // Cả hai giá trị mới đều trống ⇒ nguồn bỏ qua dòng này.
        if (string.IsNullOrWhiteSpace(r.CusInvoiceNoNew) && r.CusInvoiceDateNew is null) { skipped++; continue; }

        var d = await db.DealerDeals.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealNo == r.DealNo);
        if (d is null) return Results.BadRequest(new { error = $"Không tìm thấy giao dịch {r.DealNo}." });
        var line = await db.DealerDealDetails.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealId == d.Id && x.CarId == carId);
        if (line is null) return Results.BadRequest(new { error = $"Giao dịch {r.DealNo} không có xe {carId}." });

        var noOld = line.CusInvoiceNo;
        var dateOld = line.CusInvoiceDate;
        // Trống ⇒ giữ nguyên giá trị hiện tại (nguồn gán lại từ bản ghi DB).
        var noNew = string.IsNullOrWhiteSpace(r.CusInvoiceNoNew) ? noOld : r.CusInvoiceNoNew!.Trim();
        var dateNew = r.CusInvoiceDateNew ?? dateOld;

        var noChanged = !string.Equals(noOld ?? "", noNew ?? "", StringComparison.OrdinalIgnoreCase);
        var dateChanged = dateOld != dateNew;
        if (!noChanged && !dateChanged) { skipped++; continue; }

        db.DealDetailCusInvoiceHisUpds.Add(new DealDetailCusInvoiceHisUpd
        {
            OrgId = t.OrgId, DealNo = r.DealNo!, CarId = carId,
            CusInvoiceNoOld = noOld, CusInvoiceNoNew = noNew,
            CusInvoiceDateOld = dateOld, CusInvoiceDateNew = dateNew,
            UpdDTime = now, UpdBy = who,
        });
        if (noChanged) { line.CusInvoiceNo = noNew; changedNo++; }
        if (dateChanged) { line.CusInvoiceDate = dateNew; changedDate++; }
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { rows = rows.Count, changedNo, changedDate, skipped });
}).RequireAuthorization();

// ===== Sửa GIÁ dòng giao dịch bán lẻ (Dls_DealDetail_UpdatePrice — 2010.HTC Biz.HTC.WH.hkt.cs:6771) =====
// 🔴 Luật nguồn: tra bảng xe theo **VIN** để lấy `CarId` rồi mới update — **KHÔNG lấy CarId từ input**;
//    không tìm thấy xe thì báo lỗi. Update `DLS_DealDetail.Price = PriceNew` theo `DealNo` + `CarId`,
//    và ghi lịch sử `Dls_DealDetail_HisUpdPrice` (giá cũ + giá mới).
// ⚠️ Trong MiniHTC `DealerDealDetail.CarId` chính là VIN, nên bước tra xe quy về **kiểm VIN tồn tại**
//    trong master VIN (`CarVinMasters`).
// TWIN: chỉ `TERP.WSHTC.64` (27520).
app.MapGet("/api/dealdetail/price-history", async (AppDbContext db, ITenantContext t, string? dealNo, string? carId) =>
{
    var qy = db.DlsDealDetailHisUpdPrices.Where(h => h.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealNo)) qy = qy.Where(h => h.DealNo == dealNo);
    if (!string.IsNullOrWhiteSpace(carId)) qy = qy.Where(h => h.CarId == carId.Trim().ToUpperInvariant());
    var items = await qy.OrderByDescending(h => h.Id).Take(500)
        .Select(h => new { h.DealNo, h.CarId, h.PriceOld, h.PriceNew, h.UpdDTime, h.UpdBy }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/dealdetail/update-price", async (DealDetailPriceDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.DealNo) && !string.IsNullOrWhiteSpace(r.VIN) && r.PriceNew is not null).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Chưa có dòng nào để sửa giá." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var updated = 0;
    foreach (var r in rows)
    {
        var vin = r.VIN!.Trim().ToUpperInvariant();
        // Guard nguồn: xe phải tồn tại (nguồn tra Car_Car theo VIN để lấy CarId).
        var carExists = await db.CarVinMasters.AnyAsync(x => x.OrgId == t.OrgId && x.VIN == vin);
        if (!carExists) return Results.BadRequest(new { error = $"Không tìm thấy xe VIN {vin}." });

        var d = await db.DealerDeals.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealNo == r.DealNo);
        if (d is null) return Results.BadRequest(new { error = $"Không tìm thấy giao dịch {r.DealNo}." });
        var line = await db.DealerDealDetails.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealId == d.Id && x.CarId == vin);
        if (line is null) return Results.BadRequest(new { error = $"Giao dịch {r.DealNo} không có xe {vin}." });

        db.DlsDealDetailHisUpdPrices.Add(new DlsDealDetailHisUpdPrice
        {
            OrgId = t.OrgId, DealNo = r.DealNo!, CarId = vin,
            PriceOld = line.Price, PriceNew = r.PriceNew, UpdDTime = now, UpdBy = who,
        });
        line.Price = r.PriceNew;
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { rows = rows.Count, updated });
}).RequireAuthorization();

// ===== Sửa BIÊN BẢN GIAO XE: ngày xuất kho & tỉnh/huyện tuyến =====
// Port 1:1 `Support_Sto_DlvMinutes_UpdateDlvStartDateAndDeliveryOutDate` (Biz.HTC.WH.hkt.cs:8155)
// và `Support_Sto_DlvMinutes_UpdateProvinceAndDistrict` (8856). TWIN: **chỉ `TERP.WSHTC.64`** (99709/99842).
// 🔴 Hàm 1 cùng lớp với CarDeliveryDate: **một giá trị `DateNew` ghi vào HAI bảng, HAI tên cột**
//    (`Sto_DlvMinutes.DlvStartDate` join DlvMnNo+VIN · `Car_DeliveryOrderDetail.DeliveryOutDate`
//     join DeliveryOrderNo+DeliveryVIN), kèm lịch sử lưu giá trị cũ của cả hai.
app.MapPost("/api/dlvminutes/update-dates", async (DlvUpdDatesDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.VIN) && r.DateNew is not null).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Chưa có dòng nào để sửa ngày xuất kho." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    int nDlv = 0, nDo = 0;
    foreach (var r in rows)
    {
        var vin = r.VIN!.Trim().ToUpperInvariant();
        var newDate = r.DateNew!.Value;
        var his = new DlvMinutesUpdDateHis
        {
            OrgId = t.OrgId, DlvMnNo = r.DlvMnNo, DeliveryOrderNo = r.DeliveryOrderNo, VIN = vin,
            DlvStartDateNew = newDate, DeliveryOutDateNew = newDate, UpdDTime = now, UpdBy = who,
        };
        if (!string.IsNullOrWhiteSpace(r.DlvMnNo))
        {
            // 🔴 #B36 GAP: nguồn khoá **CẶP (`DlvMnNo`, `VIN`)** — cả ở guard tồn tại
            //    (`Biz.HTC.WH.hkt.cs:8257-8261`: `and t.DlvMnNo = @strDlvMnNo and t.VIN = @strVIN`)
            //    lẫn ở câu update (`:8464-8466`: `on t.DlvMnNo = f.DlvMnNo and t.VIN = f.VIN`).
            //    Port cũ khớp **chỉ số biên bản** rồi ghi vào **HEADER** ⇒ một biên bản chở nhiều xe thì
            //    sửa ngày xuất kho của MỘT xe **đổi luôn cho cả lô**. Dòng xe (`TranspDlvConfirmCar`)
            //    đã có sẵn cột `DlvStartDate` đúng khuôn nguồn — port cũ không dùng tới.
            var m = await db.TranspDlvConfirms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlvMinutesNo == r.DlvMnNo);
            if (m is null)
                return Results.BadRequest(new { error = $"Không tìm thấy biên bản {r.DlvMnNo}.", vin });
            var mc = await db.TranspDlvConfirmCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TranspDlvConfirmId == m.Id && x.VIN == vin);
            if (mc is null)
                return Results.BadRequest(new { error = $"Xe {vin} không nằm trong biên bản {r.DlvMnNo}.", rowKey = "(DlvMnNo, VIN)" });
            his.DlvStartDateOld = mc.DlvStartDate; mc.DlvStartDate = newDate; nDlv++;
        }
        if (!string.IsNullOrWhiteSpace(r.DeliveryOrderNo))
        {
            var o = await db.DeliveryOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DoNo == r.DeliveryOrderNo);
            if (o is not null)
            {
                var c = await db.DeliveryOrderCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DoId == o.Id && x.Vin == vin);
                if (c is not null) { his.DeliveryOutDateOld = c.DeliveryOutDate; c.DeliveryOutDate = newDate; nDo++; }
            }
        }
        db.DlvMinutesUpdDateHiss.Add(his);
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { rows = rows.Count, dlvMinutesUpdated = nDlv, deliveryOrderCarsUpdated = nDo });
}).RequireAuthorization();

// 🔴 Sửa TỈNH/HUYỆN tuyến giao — nguồn **kiểm cặp tỉnh–huyện mới có tồn tại trong `Mst_District`**
//    cho CẢ hai đầu tuyến (F: nơi đi, T: nơi đến) trước khi cập nhật.
app.MapPost("/api/dlvminutes/update-province", async (DlvUpdProvinceDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.DlvMnNo) && !string.IsNullOrWhiteSpace(r.VIN)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Chưa có dòng nào để sửa tỉnh/huyện." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var updated = 0;
    foreach (var r in rows)
    {
        var hdr = await db.TranspDlvConfirms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlvMinutesNo == r.DlvMnNo);
        if (hdr is null) return Results.BadRequest(new { error = $"Không tìm thấy biên bản {r.DlvMnNo}.", guard = "…_DlvMnNoNotExist" });
        // 🔴 #B36 GAP (cùng loại với hàm sửa ngày): nguồn khoá **CẶP (`DlvMnNo`, `VIN`)** — mỗi xe trong
        //    biên bản có **tuyến riêng** (`Biz.HTC.WH.hkt.cs:9022`: `and t.VIN = @strVIN`; và cả sáu bảng
        //    tạm cập nhật đều mang `drInput["VIN"]` làm khoá, `:9150-9250`). Port cũ khớp **chỉ số biên
        //    bản** rồi ghi vào **HEADER** ⇒ đổi tuyến của MỘT xe **đổi luôn cho cả lô**.
        var m = await db.TranspDlvConfirmCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId
            && x.TranspDlvConfirmId == hdr.Id && x.VIN == r.VIN!.Trim().ToUpperInvariant());
        if (m is null) return Results.BadRequest(new { error = $"Xe {r.VIN} không nằm trong biên bản {r.DlvMnNo}.", rowKey = "(DlvMnNo, VIN)" });
        // ✅ GUARD ĐÃ PORT (nợ #92 đóng ở #116, sau khi có master `Mst_District` từ #115).
        // Nguồn (`Biz.HTC.WH.hkt.cs:9072-9140`) kiểm CẶP (ProvinceCode, DistrictCode) phải tồn tại
        // trong `Mst_District`, làm RIÊNG cho từng đầu tuyến: F (nơi đi) và T (nơi đến).
        // 🔴 Guard chỉ chạy khi giá trị THỰC SỰ ĐỔI — nguồn bọc trong
        //    `if (!drInput["FProvinceCodeNew"].Equals(...) || !drInput["FDistrictCodeNew"].Equals(...))`.
        var fProvNew = string.IsNullOrWhiteSpace(r.FProvinceCodeNew) ? m.FProvinceCode : r.FProvinceCodeNew;
        var fDistNew = string.IsNullOrWhiteSpace(r.FDistrictCodeNew) ? m.FDistrictCode : r.FDistrictCodeNew;
        if (fProvNew != m.FProvinceCode || fDistNew != m.FDistrictCode)
        {
            var okF = await db.MstDistricts.AnyAsync(x => x.OrgId == t.OrgId
                && x.ProvinceCode == fProvNew && x.DistrictCode == fDistNew);
            if (!okF) return Results.BadRequest(new { error = $"Tỉnh + xã giao (nơi đi) không hợp lệ: {fProvNew}/{fDistNew}." });
        }
        var tProvNew = string.IsNullOrWhiteSpace(r.TProvinceCodeNew) ? m.TProvinceCode : r.TProvinceCodeNew;
        var tDistNew = string.IsNullOrWhiteSpace(r.TDistrictCodeNew) ? m.TDistrictCode : r.TDistrictCodeNew;
        if (tProvNew != m.TProvinceCode || tDistNew != m.TDistrictCode)
        {
            var okT = await db.MstDistricts.AnyAsync(x => x.OrgId == t.OrgId
                && x.ProvinceCode == tProvNew && x.DistrictCode == tDistNew);
            if (!okT) return Results.BadRequest(new { error = $"Tỉnh + xã giao (nơi đến) không hợp lệ: {tProvNew}/{tDistNew}." });
        }
        var his = new DlvMinutesUpdProvinceHis
        {
            OrgId = t.OrgId, DlvMnNo = r.DlvMnNo, VIN = r.VIN!.Trim().ToUpperInvariant(), UpdDTime = now, UpdBy = who,
            FProvinceCodeOld = m.FProvinceCode, FDistrictCodeOld = m.FDistrictCode,
            TProvinceCodeOld = m.TProvinceCode, TDistrictCodeOld = m.TDistrictCode,
            FProvinceCodeNew = r.FProvinceCodeNew, FDistrictCodeNew = r.FDistrictCodeNew,
            TProvinceCodeNew = r.TProvinceCodeNew, TDistrictCodeNew = r.TDistrictCodeNew,
        };
        if (!string.IsNullOrWhiteSpace(r.FProvinceCodeNew)) m.FProvinceCode = r.FProvinceCodeNew;
        if (!string.IsNullOrWhiteSpace(r.FDistrictCodeNew)) m.FDistrictCode = r.FDistrictCodeNew;
        if (!string.IsNullOrWhiteSpace(r.TProvinceCodeNew)) m.TProvinceCode = r.TProvinceCodeNew;
        if (!string.IsNullOrWhiteSpace(r.TDistrictCodeNew)) m.TDistrictCode = r.TDistrictCodeNew;
        db.DlvMinutesUpdProvinceHiss.Add(his);
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { rows = rows.Count, updated });
}).RequireAuthorization();

// ===== Cập nhật NGÀY GIAO XE (CarDeliveryDate_Update — port 1:1 2010.HTC Biz.HTC.WH.cs:139603) =====
// 🔴 MỘT hành động ghi vào **BA bảng** với **ba tên cột khác nhau** nhưng cùng một giá trị:
//   · `Sto_DlvMinutes.DlvEndDate`            join `DlvMnNo` + `VIN`, **guard `FDlvMnStatus = 'A'`**
//   · `Car_DeliveryOrderDetail.DeliveryEndDate` join `DeliveryOrderNo` + `CarId`
//   · `DLS_DealDetail.DeliveryDate`          join `DealNo` + `CarId`
// và ghi lịch sử `CarDeliveryDate_HisUpd` lưu **giá trị CŨ của cả ba cột** + giá trị mới.
// TWIN: chỉ `TERP.WSHTC.64` (36429) có hàm này; md5 thân hàm khớp 2 máy.
app.MapGet("/api/cardeliverydate/history", async (AppDbContext db, ITenantContext t, string? vin) =>
{
    var qy = db.CarDeliveryDateHisUpds.Where(h => h.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(vin)) qy = qy.Where(h => h.VIN == vin.Trim().ToUpperInvariant());
    var items = await qy.OrderByDescending(h => h.Id).Take(500).Select(h => new
    {
        h.VIN, h.DlvMnNo, h.DeliveryOrderNo, h.CarId, h.DealNo,
        h.DlvEndDateOld, h.DeliveryEndDateOld, h.DeliveryDateOld,
        h.DlvEndDateNew, h.DeliveryEndDateNew, h.DeliveryDateNew, h.UpdDTime, h.UpdBy
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/cardeliverydate/update", async (CarDeliveryDateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.VIN) && r.CarDeliveryDate is not null).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Chưa có dòng nào để cập nhật ngày giao xe." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    int nDlv = 0, nDo = 0, nDeal = 0;
    foreach (var r in rows)
    {
        var vin = r.VIN!.Trim().ToUpperInvariant();
        var newDate = r.CarDeliveryDate!.Value;
        var his = new CarDeliveryDateHisUpd
        {
            OrgId = t.OrgId, VIN = vin, DlvMnNo = r.DlvMnNo, DeliveryOrderNo = r.DeliveryOrderNo,
            CarId = r.CarId, DealNo = r.DealNo, UpdDTime = now, UpdBy = who,
            DlvEndDateNew = newDate, DeliveryEndDateNew = newDate, DeliveryDateNew = newDate,
        };

        // (1) Biên bản giao xe — CHỈ khi đã duyệt phía F ("A"), đúng guard `t.FDlvMnStatus = 'A'`.
        if (!string.IsNullOrWhiteSpace(r.DlvMnNo))
        {
            var m = await db.TranspDlvConfirms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlvMinutesNo == r.DlvMnNo && x.FDlvMnStatus == "A");
            if (m is not null) { his.DlvEndDateOld = m.DlvEndDate; m.DlvEndDate = newDate; nDlv++; }
        }
        // (2) Dòng lệnh giao xe.
        if (!string.IsNullOrWhiteSpace(r.DeliveryOrderNo) && !string.IsNullOrWhiteSpace(r.CarId))
        {
            var o = await db.DeliveryOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DoNo == r.DeliveryOrderNo);
            if (o is not null)
            {
                var c = await db.DeliveryOrderCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DoId == o.Id && x.Vin == r.CarId);
                if (c is not null) { his.DeliveryEndDateOld = c.DeliveryEndDate; c.DeliveryEndDate = newDate; nDo++; }
            }
        }
        // (3) Dòng giao dịch bán lẻ.
        if (!string.IsNullOrWhiteSpace(r.DealNo) && !string.IsNullOrWhiteSpace(r.CarId))
        {
            var d = await db.DealerDeals.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealNo == r.DealNo);
            if (d is not null)
            {
                var dd = await db.DealerDealDetails.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealId == d.Id && x.CarId == r.CarId);
                if (dd is not null) { his.DeliveryDateOld = dd.DeliveryDate; dd.DeliveryDate = newDate; nDeal++; }
            }
        }
        db.CarDeliveryDateHisUpds.Add(his);
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { rows = rows.Count, dlvMinutesUpdated = nDlv, deliveryOrderCarsUpdated = nDo, dealDetailsUpdated = nDeal });
}).RequireAuthorization();

// ===== Đơn mua xe từ hãng (Ord_PurchaseOrder — port 1:1 OrderPOCreate_New2018119 /
// OrderPOCancel_New20181119, 2010.HTC Biz.HTC.WH.cs:27908/28160) =====
// ⚠️ Nguồn KHÔNG có cột trạng thái: vòng đời chỉ bằng cờ `FlagActive` ("1"→"0"), giống `Ord_POCommand`.
app.MapGet("/api/purchaseorders", async (AppDbContext db, ITenantContext t, string? month, string? flagActive) =>
{
    var qy = db.PurchaseOrders.Where(o => o.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(month)) qy = qy.Where(o => o.OrderMonth == month);
    if (!string.IsNullOrWhiteSpace(flagActive)) qy = qy.Where(o => o.FlagActive == flagActive);
    var items = await qy.OrderByDescending(o => o.Id).Take(500).Select(o => new
    {
        o.POCode, o.OrderMonth, o.ProductionMonth, o.ExpectedMonth, o.FlagActive, o.CreatedBy, o.CreatedAt,
        lines = db.PurchaseOrderLines.Count(l => l.OrgId == t.OrgId && l.PurchaseOrderId == o.Id),
        totalQty = db.PurchaseOrderLines.Where(l => l.OrgId == t.OrgId && l.PurchaseOrderId == o.Id).Sum(l => (int?)l.Quantity) ?? 0
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/purchaseorders", async (PurchaseOrderDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user, string? flagDirect) =>
{
    // ===== #B34 ĐỐI CHIẾU THÊM VỚI TWIN **2010.HTC** `OrderPOCreate_New2018119` =====
    //   (`DataWH/Biz.HTC.WH.cs:27908`; WS 64-bit `WSHTC.asmx.cs:7103` → tên biz có **lỗi chính tả
    //   `_New2018119`** thiếu một chữ số — giữ nguyên khi tra cứu). Bản chết cùng họ:
    //   `Delete.BizHTC.Report.cs:69144` (`_New2018115`) và `Biz.HTC.WH.Rel.20230823.cs:25814` (file
    //   không nằm trong `TERP.BizHTC.csproj`).
    // #174 trước đây đối chiếu twin **TCMotor DMSCarSv** (`BizHTC.Order.cs:2780`). Bản 2010.HTC lệch 2 chỗ:
    // 🔴 GAP A — **RBAC**: `myCommon_CheckHTCDirect(…, TConst.Flag.Active)` (`:27972-27976`) là **DÒNG
    //    ACTIVE** ở bản 2010.HTC ⇒ chỉ người dùng HTC trực tiếp được tạo đơn mua. Port thiếu hẳn.
    // 🔴 GAP B — **ĐỊNH DẠNG THÁNG**: `TUtils.CUtils.StandardizeMonth` (`TERP.Utils/Utils.cs:382-389`)
    //    trả **`"yyyy-MM-01"`** (`return string.Format("{0}-01", dtime.ToString("yyyy-MM"))`), KHÔNG
    //    phải `"yyyyMM"`. Port ghi `"202609"` ⇒ lệch hẳn dữ liệu hệ nguồn và bộ lọc `?month=` của GET
    //    không bao giờ khớp. Đã sửa ở **CẢ HAI** site cùng khuôn (đơn mua + lệnh đặt xe).
    if (flagDirect == "0")
        return Results.BadRequest(new { error = "Chỉ người dùng HTC trực tiếp (FlagDirect='1') được tạo đơn mua xe.", guard = "myCommon_CheckHTCDirect(Flag.Active)" });
    // ===== #174 port TRỌN `OrderPOCreate` (TCMotor DMSCarSv, TERP.BizHTC/BizHTC.Order.cs:2780) =====
    // BƯỚC 3B — ca "TÊN THƯ MỤC KHÁC, NỘI DUNG GIỐNG": laptop có `DMSCarSv/V20.2023.Release.**V2**`,
    //   máy 150 có `DMSCarSv/V20.2023.Release` (không hậu tố V2) — **md5 `b1c089a3` GIỐNG HỆT**.
    //   Laptop còn có `DMSCarSv/V20` md5 y hệt; `DMSales.Foton` là bản KHÁC (`d841d5fb`).
    // TWIN: `TERP.WSHTC/App_Code/WSHTC.cs` gọi thẳng `_biz.OrderPOCreate` (cụm này chỉ có WS 32-bit).
    //
    // 🔴 Cùng khuôn với `OrderPOCommandCreate` đã vá ở #173 — và port cũ mắc **đúng bốn lỗi ấy**:
    //   1. **Số đơn do NGƯỜI DÙNG nhập** (`strPOCode`), guard `Length >= TConst.HTCConst.MinLengthCode` (=5).
    //      Port cũ: rỗng thì tự sinh `"PO"+timestamp` ⇒ mã không tra được ở hệ nguồn.
    //   2. **Ba cột tháng SERVER TỰ TÍNH**: `OrderMonth` = tháng hiện tại · `+1` · `+2`. Port cũ lấy từ DTO.
    //   3. Nguồn chặn `Quantity < 0` ⇒ **dòng 0 xe HỢP LỆ**; port cũ lọc `> 0` ⇒ vứt âm thầm.
    //   4. Thiếu `DuplicateKeyDetail` (khoá của nguồn) và hai guard master.
    // ⚠️ KHÁC #173 một điểm: ở đây nguồn nhận **CẢ `ModelCode` lẫn `SpecCode`** rồi kiểm KHỚP nhau
    //    (`myCommon_CheckMatchingModelAndSpecCode`) — không suy `ModelCode` ra từ spec như bên POCommand.
    var code = (dto.POCode ?? "").Trim().ToUpperInvariant();
    if (code.Length < 5)
        return Results.BadRequest(new { error = "Số đơn mua phải có ít nhất 5 ký tự." });
    if (await db.PurchaseOrders.AnyAsync(x => x.OrgId == t.OrgId && x.POCode == code))
        return Results.BadRequest(new { error = $"Số đơn mua {code} đã tồn tại!" });

    // `OrderPOCreate_TableDetailBeBlank`
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.SpecCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Chưa có dòng chi tiết nào." });

    var now = DateTime.Now;
    // #B34 StandardizeMonth (Utils.cs:382-389) tra "yyyy-MM-01", KHONG phai "yyyyMM".
    var orderMonth = now.ToString("yyyy-MM") + "-01";
    var productionMonth = now.AddMonths(1).ToString("yyyy-MM") + "-01";
    var expectedMonth = now.AddMonths(2).ToString("yyyy-MM") + "-01";

    var seen = new HashSet<string>();
    var built = new List<PurchaseOrderLine>();
    foreach (var l in lines)
    {
        var spec = l.SpecCode.Trim().ToUpperInvariant();
        var model = (l.ModelCode ?? "").Trim().ToUpperInvariant();
        var color = (l.ColorCode ?? "").Trim().ToUpperInvariant();

        // `OrderPOCreate_InvalidDetailQuantity`: chặn ÂM, cho phép 0.
        if (l.Quantity < 0)
            return Results.BadRequest(new { error = $"Spec {spec}: số lượng không hợp lệ.", specCode = spec });

        // `myCommon_CheckMatchingModelAndSpecCode` — spec phải tồn tại VÀ thuộc đúng model đã khai.
        var sp = await db.CarSpecs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SpecCode == spec && x.FlagActive == "1");
        if (sp is null) return Results.BadRequest(new { error = $"Spec {spec} không tồn tại hoặc đã ngừng hoạt động.", specCode = spec });
        if (model.Length > 0 && sp.ModelCode != model)
            return Results.BadRequest(new { error = $"Spec {spec} thuộc model {sp.ModelCode}, không phải {model}.", specCode = spec });
        if (model.Length == 0) model = sp.ModelCode;

        // `myCommon_CheckMatchingModelAndColor`
        if (color.Length > 0)
        {
            var okColor = await db.MstCarColors.AnyAsync(x => x.OrgId == t.OrgId && x.ModelCode == model && x.ColorCode == color && x.FlagActive == "1");
            if (!okColor) return Results.BadRequest(new { error = $"Màu {color} không thuộc model {model}.", specCode = spec, colorCode = color });
        }

        // `OrderPOCreate_DuplicateKeyDetail`
        var key = $"|{code}||{spec}||{model}||{color}|";
        if (!seen.Add(key))
            return Results.BadRequest(new { error = $"Dòng trùng khoá (Spec/Model/Màu): {spec}/{model}/{color}.", key });

        built.Add(new PurchaseOrderLine { OrgId = t.OrgId, SpecCode = spec, ModelCode = model, ColorCode = color, Quantity = l.Quantity });
    }

    var o = new PurchaseOrder
    {
        OrgId = t.OrgId, POCode = code,
        OrderMonth = orderMonth, ProductionMonth = productionMonth, ExpectedMonth = expectedMonth,
        FlagActive = "1",
        CreatedBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system",
        CreatedAt = now,
    };
    db.PurchaseOrders.Add(o); await db.SaveChangesAsync();
    foreach (var b in built) { b.PurchaseOrderId = o.Id; db.PurchaseOrderLines.Add(b); }
    await db.SaveChangesAsync();
    return Results.Ok(new { o.POCode, o.OrderMonth, o.ProductionMonth, o.ExpectedMonth, o.FlagActive, o.CreatedBy,
        lines = built.Count, totalQty = built.Sum(l => l.Quantity) });
}).RequireAuthorization();

app.MapGet("/api/purchaseorders/{code}/lines", async (string code, AppDbContext db, ITenantContext t) =>
{
    code = code.Trim().ToUpperInvariant();
    var o = await db.PurchaseOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.POCode == code);
    if (o is null) return Results.NotFound(new { code });
    var lines = await db.PurchaseOrderLines.Where(l => l.OrgId == t.OrgId && l.PurchaseOrderId == o.Id)
        .Select(l => new { l.SpecCode, l.ModelCode, l.ColorCode, l.Quantity }).ToListAsync();
    return Results.Ok(new { o.POCode, o.OrderMonth, o.ProductionMonth, o.ExpectedMonth, o.FlagActive, count = lines.Count, lines, totalQty = lines.Sum(x => x.Quantity) });
}).RequireAuthorization();

// 🔴 HUỶ — `OrderPOCancel_New20181119`: guard `myOrder_CheckPO(..., Flag.Active)` rồi gán
// `FlagActive = Flag.Inactive`. Nguồn **KHÔNG xoá dòng chi tiết** khi huỷ.
app.MapPost("/api/purchaseorders/{code}/cancel", async (string code, AppDbContext db, ITenantContext t) =>
{
    code = code.Trim().ToUpperInvariant();
    var o = await db.PurchaseOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.POCode == code);
    if (o is null) return Results.NotFound(new { code });
    if (o.FlagActive != "1") return Results.BadRequest(new { error = "Đơn mua đã huỷ." });
    o.FlagActive = "0";
    await db.SaveChangesAsync();
    return Results.Ok(new { o.POCode, o.FlagActive });
}).RequireAuthorization();

// ===== Đơn đặt hàng NCC (port 1:1 Supplier PO — TCMotor) =====
app.MapGet("/api/pos", async (AppDbContext db, ITenantContext t, string? status) =>
{
    var q = db.SupplierPOs.Where(p => p.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(p => p.Status == status);
    var items = await q.OrderByDescending(p => p.Id).Take(500).Select(p => new
    { p.PoNo, p.SupplierCode, p.Note, p.Total, p.Status, p.CreatedAt, p.SentAt, p.ReceivedAt }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/pos", async (PODto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.SupplierCode)) return Results.BadRequest(new { error = "Cần SupplierCode." });
    var no = "PO" + DateTime.Now.ToString("yyMMddHHmmss");
    var p = new SupplierPO { OrgId = t.OrgId, PoNo = no, SupplierCode = dto.SupplierCode.Trim().ToUpperInvariant(), Note = dto.Note, Total = dto.Total, Status = "Draft" };
    db.SupplierPOs.Add(p); await db.SaveChangesAsync();
    return Results.Ok(new { p.PoNo, p.SupplierCode, p.Total, status = p.Status });
}).RequireAuthorization();

app.MapPost("/api/pos/{no}/{action}", async (string no, string action, AppDbContext db, ITenantContext t) =>
{
    if (action is not ("send" or "receive" or "cancel")) return Results.BadRequest(new { error = "action = send|receive|cancel" });
    no = no.Trim().ToUpperInvariant();
    var p = await db.SupplierPOs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PoNo == no);
    if (p is null) return Results.NotFound(new { no });
    var now = DateTime.Now;
    if (action == "send") { if (p.Status != "Draft") return Results.BadRequest(new { error = "Sai trạng thái." }); p.Status = "Sent"; p.SentAt = now; }
    else if (action == "receive") { if (p.Status != "Sent") return Results.BadRequest(new { error = "Chưa gửi." }); p.Status = "Received"; p.ReceivedAt = now; }
    else { if (p.Status == "Received") return Results.BadRequest(new { error = "Đã nhận." }); p.Status = "Cancelled"; }
    await db.SaveChangesAsync();
    return Results.Ok(new { p.PoNo, status = p.Status });
}).RequireAuthorization();

// ===== BOM định mức bảo dưỡng (header-detail, port 1:1 FrmMstBOMMng — TCMotor) =====
app.MapGet("/api/boms", async (AppDbContext db, ITenantContext t, string? model) =>
{
