// ===== Hãng bảo hiểm + khách hàng thuộc hãng (port 1:1 FrmInsuranceCreate/Modify — TCMotor DMSCarSv/Admin) =====
// Nguồn: ValidateInput() + checkInsuranceExist() + gviewPart_ValidateRow() + mst.SerInsuranceCreate.
app.MapGet("/api/insurances", async (AppDbContext database, ITenantContext tenant, string? keyword) =>
{
    var insuranceQuery = database.ServiceInsurances.Where(insurance => insurance.OrgId == tenant.OrgId);
    if (!string.IsNullOrWhiteSpace(keyword))
    {
        var searchKeyword = keyword.Trim();
        insuranceQuery = insuranceQuery.Where(insurance =>
            insurance.InsNo.Contains(searchKeyword) || insurance.InsVieName.Contains(searchKeyword));
    }
    var items = await insuranceQuery.OrderBy(insurance => insurance.InsNo)
        .Select(insurance => new
        {
            insurance.Id, insurance.InsNo, insurance.InsVieName, insurance.InsEngName, insurance.Address,
            insurance.Email, insurance.Telephone, insurance.Fax, insurance.Website, insurance.Taxcode,
            insurance.Description, insurance.Status,
            customers = database.ServiceInsuranceCustomers
                .Count(customer => customer.OrgId == tenant.OrgId && customer.ServiceInsuranceId == insurance.Id)
        })
        .ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/insurances", async (ServiceInsuranceDto request, AppDbContext database, ITenantContext tenant) =>
{
    // LUẬT 1-3 (ValidateInput): 3 trường bắt buộc, giữ nguyên văn thông báo form gốc.
    if (string.IsNullOrWhiteSpace(request.InsNo))
        return Results.BadRequest(new { error = "Phải nhập vào mã hãng bảo hiểm" });
    if (string.IsNullOrWhiteSpace(request.InsVieName))
        return Results.BadRequest(new { error = "Phải nhập vào tên tiếng việt" });
    if (string.IsNullOrWhiteSpace(request.Address))
        return Results.BadRequest(new { error = "Phải nhập vào địa chỉ" });

    var insuranceNo = request.InsNo.Trim().ToUpperInvariant();

    // LUẬT 4 (checkInsuranceExist): mã hãng BH đã tồn tại thì KHÔNG cho tạo mới.
    var alreadyExists = await database.ServiceInsurances
        .AnyAsync(insurance => insurance.OrgId == tenant.OrgId && insurance.InsNo == insuranceNo);
    if (alreadyExists)
        return Results.BadRequest(new { error = "Hãng bảo hiểm đã tồn tại!" });

    // LUẬT 5 (gviewPart_ValidateRow): mỗi dòng khách hàng phải có CusId, và CusId KHÔNG trùng nhau.
    var customerRows = request.Customers ?? new List<InsuranceCustomerDto>();
    var validationError = ValidateInsuranceCustomerRows(customerRows);
    if (validationError is not null) return Results.BadRequest(new { error = validationError });

    var insuranceCompany = new ServiceInsurance
    {
        OrgId = tenant.OrgId,
        InsNo = insuranceNo,
        InsVieName = request.InsVieName.Trim(),
        InsEngName = request.InsEngName,
        Address = request.Address.Trim(),
        Email = request.Email, Telephone = request.Telephone, Fax = request.Fax,
        Website = request.Website, Taxcode = request.Taxcode, Description = request.Description
    };
    database.ServiceInsurances.Add(insuranceCompany);
    await database.SaveChangesAsync();

    foreach (var customerRow in customerRows)
        database.ServiceInsuranceCustomers.Add(new ServiceInsuranceCustomer
        {
            OrgId = tenant.OrgId,
            ServiceInsuranceId = insuranceCompany.Id,
            CusId = customerRow.CusId.Trim().ToUpperInvariant(),
            CusName = customerRow.CusName,
            Address = customerRow.Address,
            Mobile = customerRow.Mobile,
            Description = customerRow.Description
        });
    await database.SaveChangesAsync();

    return Results.Ok(new { insuranceCompany.Id, insuranceCompany.InsNo, insuranceCompany.InsVieName, customers = customerRows.Count });
}).RequireAuthorization();

app.MapGet("/api/insurances/{insNo}/customers", async (string insNo, AppDbContext database, ITenantContext tenant) =>
{
    var insuranceNo = insNo.Trim().ToUpperInvariant();
    var insuranceCompany = await database.ServiceInsurances
        .FirstOrDefaultAsync(insurance => insurance.OrgId == tenant.OrgId && insurance.InsNo == insuranceNo);
    if (insuranceCompany is null) return Results.NotFound(new { error = "Không tồn tại." });

    var customers = await database.ServiceInsuranceCustomers
        .Where(customer => customer.OrgId == tenant.OrgId && customer.ServiceInsuranceId == insuranceCompany.Id)
        .Select(customer => new { customer.CusId, customer.CusName, customer.Address, customer.Mobile, customer.Description })
        .ToListAsync();
    return Results.Ok(new { insNo = insuranceCompany.InsNo, count = customers.Count, customers });
}).RequireAuthorization();

// ===== Truy vấn hội viên Hyundai theo đại lý (port 1:1 FrmQuery_LoyaltyMember — TCMotor DMSCarSv/Services) =====
// Nguồn: btnQuery_Click → LoyaltyService.Map_QueryDealer_Member_Create(dealerCode, memberNo, phone);
// tra Crd_Member bên Loyalty (WA_Crd_Member_Get) lọc MemberNo + PhoneNo + trạng thái "APPROVE".
app.MapPost("/api/loyalty/member-queries", async (
    QueryLoyaltyMemberDto request,
    AppDbContext database,
    ITenantContext tenant) =>
{
    // LUẬT 1: mã hội viên bắt buộc.
    if (string.IsNullOrWhiteSpace(request.MemberNo))
        return Results.BadRequest(new { error = "Mã hội viên trống!" });

    // LUẬT 2: số điện thoại bắt buộc.
    if (string.IsNullOrWhiteSpace(request.PhoneNo))
        return Results.BadRequest(new { error = "Số điện thoại trống!" });

    // LUẬT 3: form gốc chặn tại txtPhone_KeyPress — ô điện thoại CHỈ nhận chữ số.
    // API không có sự kiện gõ phím nên phải kiểm lại ở server, nếu không sẽ lọt dữ liệu bẩn.
    var phoneNo = request.PhoneNo.Trim();
    if (!phoneNo.All(char.IsDigit))
        return Results.BadRequest(new { error = "Số điện thoại chỉ được nhập chữ số!" });

    if (string.IsNullOrWhiteSpace(request.DealerCode))
        return Results.BadRequest(new { error = "Cần mã đại lý (dealerCode)." });

    var memberNo = request.MemberNo.Trim().ToUpperInvariant();
    var dealerCode = request.DealerCode.Trim().ToUpperInvariant();

    // Nguồn chỉ chấp nhận hội viên đã duyệt (BuidWhereClause(..., "APPROVE")).
    // Bản fleet không nối được Loyalty thật nên đối chiếu dữ liệu hội viên cục bộ.
    var memberExistsLocally = await database.MemberVouchers
        .AnyAsync(voucher => voucher.OrgId == tenant.OrgId && voucher.MemberNo == memberNo);

    // Ghi nhận map Đại lý ↔ Hội viên (Map_QueryDealer_Member_Create); truy vấn lại thì cập nhật bản cũ.
    var existingQuery = await database.DealerMemberQueries.FirstOrDefaultAsync(query =>
        query.OrgId == tenant.OrgId && query.DealerCode == dealerCode && query.MemberNo == memberNo);
    if (existingQuery is null)
    {
        existingQuery = new DealerMemberQuery { OrgId = tenant.OrgId, DealerCode = dealerCode, MemberNo = memberNo };
        database.DealerMemberQueries.Add(existingQuery);
    }
    existingQuery.PhoneNo = phoneNo;
    existingQuery.CardNo = request.CardNo;
    existingQuery.MemberStatus = "APPROVE";
    existingQuery.QueriedAt = DateTime.Now;

    await database.SaveChangesAsync();
    return Results.Ok(new
    {
        existingQuery.DealerCode,
        existingQuery.MemberNo,
        existingQuery.PhoneNo,
        existingQuery.CardNo,
        foundInLoyalty = memberExistsLocally,
        message = "Truy vấn thành công!"   // đúng thông báo form gốc
    });
}).RequireAuthorization();

app.MapGet("/api/loyalty/member-queries", async (
    AppDbContext database, ITenantContext tenant, string? dealerCode, string? memberNo) =>
{
    var memberQueries = database.DealerMemberQueries.Where(query => query.OrgId == tenant.OrgId);
    if (!string.IsNullOrWhiteSpace(dealerCode))
        memberQueries = memberQueries.Where(query => query.DealerCode == dealerCode.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(memberNo))
        memberQueries = memberQueries.Where(query => query.MemberNo == memberNo.Trim().ToUpperInvariant());

    var items = await memberQueries.OrderByDescending(query => query.QueriedAt)
        .Select(query => new { query.DealerCode, query.MemberNo, query.PhoneNo, query.CardNo, query.MemberStatus, query.QueriedAt })
        .ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// ===== Lịch sử thời gian GXDK / dự kiến giao xe (port 1:1 FrmHistoryGXDK — TCMotor DMSCarSv/Services) =====
// Nguồn: Ser_Ro_PlanedDeliveryDate_HisGet / _HisDelete (bảng Ser_Ro_PlanedDeliveryDate_His).
// Mỗi lần đổi ngày dự kiến giao → ghi 1 dòng lịch sử; dòng mới nhất mang FlagCurrent="1".
app.MapGet("/api/gxdk", async (
    AppDbContext database,
    ITenantContext tenant,
    string? roNo,
    string? plateNo,
    string? cusName,
    DateTime? fromDate,
    DateTime? toDate) =>
{
    var historyQuery = database.RoDeliveryDateHistories.Where(history => history.OrgId == tenant.OrgId);

    // Nguồn: txtRONo.Text.Replace("BG-","") — bỏ tiền tố số báo giá trước khi khớp số LSC.
    if (!string.IsNullOrWhiteSpace(roNo))
    {
        var searchRoNo = roNo.Trim().ToUpperInvariant().Replace("BG-", "").Trim();
        historyQuery = historyQuery.Where(history => history.RoNo.Contains(searchRoNo));
    }
    if (!string.IsNullOrWhiteSpace(plateNo))
    {
        var searchPlateNo = plateNo.Trim().ToUpperInvariant();
        historyQuery = historyQuery.Where(history => (history.PlateNo ?? "").ToUpper().Contains(searchPlateNo));
    }
    if (!string.IsNullOrWhiteSpace(cusName))
        historyQuery = historyQuery.Where(history => (history.CusName ?? "").Contains(cusName.Trim()));
    // Khoảng thời gian GXDK (txtPlanedDeliveryDateFrom / txPlanedDeliveryDateTo)
    if (fromDate.HasValue) historyQuery = historyQuery.Where(history => history.PlanedDeliveryDate >= fromDate.Value);
    if (toDate.HasValue) historyQuery = historyQuery.Where(history => history.PlanedDeliveryDate <= toDate.Value);

    var historyRows = await historyQuery
        .OrderByDescending(history => history.PlanedDeliveryDate)
        .Select(history => new
        {
            history.Id, history.RoNo, history.PlateNo, history.CusName,
            history.PlanedDeliveryDate, history.Remark, history.FlagCurrent,
            isLatest = history.FlagCurrent == "1"   // bản mới nhất → UI nên khoá nút xoá
        })
        .ToListAsync();

    return Results.Ok(new { count = historyRows.Count, items = historyRows });
}).RequireAuthorization();

// Ghi nhận 1 lần đổi thời gian GXDK: bản cũ bị hạ FlagCurrent="0", bản mới thành "1".
app.MapPost("/api/gxdk", async (DeliveryDateHistoryDto request, AppDbContext database, ITenantContext tenant) =>
{
    if (string.IsNullOrWhiteSpace(request.RoNo))
        return Results.BadRequest(new { error = "Cần số lệnh sửa chữa (roNo)." });

    var repairOrderNo = request.RoNo.Trim().ToUpperInvariant().Replace("BG-", "").Trim();
    var repairOrder = await database.RepairOrders
        .FirstOrDefaultAsync(order => order.OrgId == tenant.OrgId && order.RONo == repairOrderNo);
    if (repairOrder is null)
        return Results.NotFound(new { error = $"Không tìm thấy RO {repairOrderNo}." });

    // Hạ cờ mọi bản lịch sử trước đó của RO này (chỉ được tồn tại DUY NHẤT 1 bản FlagCurrent="1").
    var previousHistories = await database.RoDeliveryDateHistories
        .Where(history => history.OrgId == tenant.OrgId
                       && history.RepairOrderId == repairOrder.Id
                       && history.FlagCurrent == "1")
        .ToListAsync();
    foreach (var previousHistory in previousHistories) previousHistory.FlagCurrent = "0";

    var newHistory = new RoDeliveryDateHistory
    {
        OrgId = tenant.OrgId,
        RepairOrderId = repairOrder.Id,
        RoNo = repairOrder.RONo,
        PlateNo = request.PlateNo ?? repairOrder.LicensePlate,
        CusName = request.CusName ?? repairOrder.CusName,
        PlanedDeliveryDate = request.PlanedDeliveryDate,
        Remark = request.Remark,
        FlagCurrent = "1"
    };
    database.RoDeliveryDateHistories.Add(newHistory);

    // Đồng bộ luôn ngày dự kiến giao trên chính lệnh sửa chữa.
    repairOrder.PlanedDeliveryDate = request.PlanedDeliveryDate;

    await database.SaveChangesAsync();
    return Results.Ok(new { newHistory.Id, newHistory.RoNo, newHistory.PlanedDeliveryDate, newHistory.FlagCurrent });
}).RequireAuthorization();

// Xoá 1 dòng lịch sử — 🔴 GUARD GỐC: cấm xoá bản mới nhất (FlagCurrent="1").
app.MapDelete("/api/gxdk/{historyId:long}", async (long historyId, AppDbContext database, ITenantContext tenant) =>
{
    var history = await database.RoDeliveryDateHistories
        .FirstOrDefaultAsync(row => row.OrgId == tenant.OrgId && row.Id == historyId);
    if (history is null) return Results.NotFound(new { error = "Không tồn tại." });

    // Nguồn btnDel_Click: chỉ xoá khi FLAGCURRENT == "0"; ngược lại báo lỗi và KHÔNG xoá.
    if (history.FlagCurrent != "0")
        return Results.BadRequest(new { error = "Không được xóa Thời gian GXDK mới nhất." });

    database.RoDeliveryDateHistories.Remove(history);
    await database.SaveChangesAsync();
    return Results.Ok(new { deleted = historyId });
}).RequireAuthorization();

