app.MapPost("/api/transreqs/{no}/{action}", async (string no, string action, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    // ===== #178 DUYỆT / BỎ DUYỆT yêu cầu vận chuyển — `Sto_TranspReq_Approve_New20181119` =====
    // Nguồn: `TERP.BizHTC/DataWH/Biz.HTC.WH.cs:110578` (csproj 272).
    // BƯỚC 3B: hàm bắt đầu **KHÁC DÒNG** giữa hai máy (laptop 110578 / máy 150 110583) — căn theo MỐC HÀM
    //   như luật #156, vùng 323 dòng md5 `2965c767` KHỚP. TWIN: WS 32-bit và 64-bit gọi CÙNG bản.
    //
    // 🔴 Nguồn KHÔNG có hai lệnh riêng: một hàm, hai ngả qua cờ `strFlagUnapprove`
    //    (`bApprove = (strFlagUnapprove == Flag.Inactive)`), và ba khác biệt mà port cũ bỏ hết:
    //   1. Trạng thái đích: `bApprove ? TConst.Stage.Approved ("A") : TConst.Stage.**Rejected ("R")**`.
    //      ⚠️ Port cũ gán **"C"** (Cancel) cho nhánh reject — SAI MÃ; "C" và "R" là hai mã khác nhau
    //      trong `TConst.Stage`, và cụm này dùng "R".
    //   2. 🔴 **Guard KHÁC NHAU giữa hai ngả** — đây là điểm nặng nhất:
    //      · duyệt   ⇒ yêu cầu liên quan phải `in ('P')`;
    //      · BỎ DUYỆT ⇒ chấp nhận `in ('A','P')`, kèm comment nguồn *"reject: Được hủy các YCVT A khi
    //        chưa có BBGN"* ⇒ **bỏ duyệt được yêu cầu ĐÃ DUYỆT**. Port cũ chặn cả hai ngả bằng
    //        `Status != "P"` ⇒ yêu cầu đã duyệt **không bao giờ gỡ ra được**.
    //   3. Guard riêng của ngả bỏ duyệt: đã tồn tại **Biên bản giao nhận** (`Sto_DlvMinutes` với
    //      `FDlvMnStatus in ('P','A')`) thì CHẶN (`Sto_TranspReq_Approve_InvalidStoDLV`) — xe đã lên
    //      đường thì không rút lại lệnh được.
    if (action is not ("approve" or "unapprove")) return Results.BadRequest(new { error = "action = approve|unapprove" });
    no = no.Trim().ToUpperInvariant();
    var r = await db.TransportRequests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TranspReqNo == no);
    if (r is null) return Results.NotFound(new { no });

    var bApprove = action == "approve";
    if (bApprove)
    {
        if (r.Status != "P")
            return Results.BadRequest(new { error = $"Yêu cầu đang ở '{r.Status}' — chỉ duyệt khi còn chờ duyệt (P)." });
    }
    else
    {
        // Ngả bỏ duyệt chấp nhận CẢ "A" lẫn "P".
        if (r.Status is not ("A" or "P"))
            return Results.BadRequest(new { error = $"Yêu cầu đang ở '{r.Status}' — chỉ bỏ duyệt khi đang chờ duyệt (P) hoặc đã duyệt (A)." });

        // `Sto_TranspReq_Approve_InvalidStoDLV`: đã có BBGN ở trạng thái P/A thì không gỡ được.
        var vins = await db.TransportReqCars.Where(c => c.OrgId == t.OrgId && c.ReqId == r.Id)
            .Select(c => c.Vin).ToListAsync();
        var dlv = await db.TranspDlvConfirms.Where(m => m.OrgId == t.OrgId
                && (m.FDlvMnStatus == "P" || m.FDlvMnStatus == "A")
                && db.TranspDlvConfirmCars.Any(c => c.OrgId == t.OrgId && c.TranspDlvConfirmId == m.Id && vins.Contains(c.VIN)))
            .Select(m => m.DlvMinutesNo).FirstOrDefaultAsync();
        if (dlv is not null)
            return Results.BadRequest(new { error = $"Đã tồn tại biên bản giao nhận {dlv} — không bỏ duyệt được yêu cầu vận chuyển.", dlvMinutesNo = dlv });
    }

    var whoTR = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var nowTR = DateTime.Now;
    // `strSRTReqStatus = bApprove ? Approved : Rejected`
    r.Status = bApprove ? "A" : "R";
    r.DecidedAt = nowTR; r.ApprovedBy = whoTR;
    r.LogLUDateTime = nowTR; r.LogLUBy = whoTR;
    foreach (var c in await db.TransportReqCars.Where(c => c.OrgId == t.OrgId && c.ReqId == r.Id).ToListAsync())
    { c.TransportReqDtlStatus = r.Status; c.LogLUDateTime = nowTR; c.LogLUBy = whoTR; }
    await db.SaveChangesAsync();
    return Results.Ok(new { r.TranspReqNo, status = r.Status, unapprove = !bApprove });
}).RequireAuthorization();

// ===== Phí vận chuyển theo tuyến (Mst_TranspFee — port 1:1 FrmNewTranspFee/FrmMngTranspFee, Phase2) =====
app.MapGet("/api/transpfees", async (AppDbContext db, ITenantContext t, string? transporter, string? model) =>
{
    var q = db.TranspFees.Where(f => f.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(transporter)) q = q.Where(f => f.TransporterCode == transporter);
    if (!string.IsNullOrWhiteSpace(model)) q = q.Where(f => f.ModelCode == model);
    var items = await q.OrderBy(f => f.ProvinceCodeFrom).ThenBy(f => f.ProvinceCodeTo).Take(1000).Select(f => new
    {
        f.ProvinceCodeFrom, f.ProvinceCodeTo, f.DistrictCodeFrom, f.DistrictCodeTo, f.TransporterCode, f.ModelCode, f.ValFee, f.ExpectedDays
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/transpfees", async (TranspFeeDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.ProvinceCodeFrom) || string.IsNullOrWhiteSpace(dto.ProvinceCodeTo)
        || string.IsNullOrWhiteSpace(dto.TransporterCode) || string.IsNullOrWhiteSpace(dto.ModelCode))
        return Results.BadRequest(new { error = "Cần tỉnh From/To + nhà VC + model." });
    string pf = dto.ProvinceCodeFrom.Trim().ToUpperInvariant(), pt = dto.ProvinceCodeTo.Trim().ToUpperInvariant(),
           tr = dto.TransporterCode.Trim().ToUpperInvariant(), md = dto.ModelCode.Trim().ToUpperInvariant(),
           df = (dto.DistrictCodeFrom ?? "").Trim().ToUpperInvariant(), dt2 = (dto.DistrictCodeTo ?? "").Trim().ToUpperInvariant();
    // upsert theo khoá tuyến đầy đủ (tỉnh+huyện From/To + NVC + model)
    var f = await db.TranspFees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ProvinceCodeFrom == pf && x.ProvinceCodeTo == pt
        && (x.DistrictCodeFrom ?? "") == df && (x.DistrictCodeTo ?? "") == dt2 && x.TransporterCode == tr && x.ModelCode == md);
    if (f is null) { f = new TranspFee { OrgId = t.OrgId, ProvinceCodeFrom = pf, ProvinceCodeTo = pt, DistrictCodeFrom = df, DistrictCodeTo = dt2, TransporterCode = tr, ModelCode = md }; db.TranspFees.Add(f); }
    f.ValFee = dto.ValFee; f.ExpectedDays = dto.ExpectedDays; f.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { f.ProvinceCodeFrom, f.ProvinceCodeTo, f.TransporterCode, f.ModelCode, f.ValFee, f.ExpectedDays });
}).RequireAuthorization();

// Tạo hàng loạt 1 phiên bản CPVT mới (port 1:1 FrmNewTranspFee btnApply_Click, Phase2) — mỗi lần Apply tạo 1 lô TFVCode mới, không upsert.
app.MapPost("/api/transpfees/versions", async (TranspFeeVersionDto dto, AppDbContext db, ITenantContext t) =>
{
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.ProvinceCodeFrom) && !string.IsNullOrWhiteSpace(r.ProvinceCodeTo)
        && !string.IsNullOrWhiteSpace(r.TransporterCode) && !string.IsNullOrWhiteSpace(r.ModelCode)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu CPVT." });
    var tfv = "TFV" + DateTime.Now.ToString("yyMMddHHmmss");
    foreach (var r in rows)
        db.TranspFees.Add(new TranspFee
        {
            OrgId = t.OrgId, TFVCode = tfv, ProvinceCodeFrom = r.ProvinceCodeFrom!.Trim().ToUpperInvariant(), ProvinceCodeTo = r.ProvinceCodeTo!.Trim().ToUpperInvariant(),
            DistrictCodeFrom = r.DistrictCodeFrom, DistrictCodeTo = r.DistrictCodeTo, TransporterCode = r.TransporterCode!.Trim().ToUpperInvariant(),
            ModelCode = r.ModelCode!.Trim().ToUpperInvariant(), ValFee = r.ValFee, ExpectedDays = r.ExpectedDays
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { tfvCode = tfv, rows = rows.Count });
}).RequireAuthorization();

// Danh sách phiên bản CPVT (port 1:1 FrmMngTranspFeeHist btnSearch_Click)
app.MapGet("/api/transpfees/versions", async (AppDbContext db, ITenantContext t) =>
{
    var items = await db.TranspFees.Where(f => f.OrgId == t.OrgId && f.TFVCode != null)
        .GroupBy(f => f.TFVCode)
        .Select(g => new { tfvCode = g.Key, rows = g.Count(), updatedAt = g.Max(x => x.UpdatedAt) })
        .OrderByDescending(g => g.updatedAt).Take(200).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Xóa hàng loạt phiên bản CPVT (port 1:1 FrmMngTranspFeeHist btnDeleteDetail_Click / DeleteTranspFeeVerList)
app.MapPost("/api/transpfees/versions/delete-batch", async (TranspFeeVerDeleteDto dto, AppDbContext db, ITenantContext t) =>
{
    var codes = (dto.TFVCodes ?? new()).Where(c => !string.IsNullOrWhiteSpace(c)).ToList();
    if (codes.Count == 0) return Results.BadRequest(new { error = "Hãy chọn Phiên bản CPVT" });
    var rows = db.TranspFees.Where(f => f.OrgId == t.OrgId && f.TFVCode != null && codes.Contains(f.TFVCode));
    var deletedRows = await rows.CountAsync();
    db.TranspFees.RemoveRange(rows);
    await db.SaveChangesAsync();
    return Results.Ok(new { deletedVersions = codes.Count, deletedRows });
}).RequireAuthorization();

// ===== #B90 LỊCH SỬ PHIÊN BẢN CHI PHÍ VẬN CHUYỂN — `Mst_TranspFeeVerGet_Hist_New20181115` =====
// Trace LIVE: WS `:39282` → **`_biz.Mst_TranspFeeVerGet_Hist_New20181115`**
//   (`BizHTC.MasterData.cs:2257`). ⚠️ Sinh đôi gần kề: `Mst_TranspFeeVerGet_New20181115` (WS `:39187`)
//   là hàm **KHÁC** — đọc bảng ĐANG hiệu lực; hàm này đọc **LỊCH SỬ**.
//   3B đo thật, **khớp cả 2 máy**: start=2257 md5 `fe1c586bc61f2994d987f3bfcc64728f`.
// 🔴 **NGUỒN CÓ BA BẢNG, PORT CŨ GỘP CÒN MỘT**:
//      `Mst_TranspFeeVer`  — **đầu** phiên bản (ngày tạo, cờ hiệu lực)
//      `Mst_TranspFee`     — bảng **ĐANG** hiệu lực
//      `Mst_TranspFeeHist` — **ẢNH CHỤP** dòng phí của từng phiên bản
//    Port cũ chỉ gắn `TFVCode` lên `TranspFee` ⇒ **không có đầu phiên bản** và **không có ảnh chụp**.
//    ⇒ Xem lại một phiên bản cũ sẽ ra **số HIỆN TẠI**, không phải số của lúc đó. Đã thêm 2 entity §12.
// 🔴 **Hàm này đọc `Mst_TranspFeeHist`, KHÔNG đọc `Mst_TranspFee`** — đó là toàn bộ lý do nó tồn tại.
// 🔴 **BỐN `INNER JOIN` danh mục địa lý** (`Mst_Province` ×2 + `Mst_District` ×2, cả đầu ĐI và ĐẾN):
//    dòng có tỉnh/huyện **không tra được trong danh mục sẽ BỊ LOẠI khỏi kết quả** — **không** hiện ra
//    với ô trống. Port đếm `droppedNoGeo` để đo được phần bị mất.
// 🔴 **`strIsGetDetail` quyết định có trả BẢNG CHI TIẾT hay không**: mặc định
//    `zzzzClauseSelect_Mst_TranspFee_Hist = "-- Nothing."`; chỉ khi cờ = `Flag.Active` mới nối câu
//    select dòng chi tiết (kèm `ProvinceNameFrom`… lấy từ join). ⇒ **không phải "ẩn cột"** mà là
//    **không chạy hẳn câu truy vấn thứ ba**.
// 🔴 **LỖ HỔNG RBAC — biến thể 2 (khai mà KHÔNG dùng), ca thứ 10**: nguồn bind
//    `alParamsCoupleSql.AddRange(new object[] { "@strBUPatternOfUser", drAbilityOfUser["BUPattern"] });`
//    (`:2342`) nhưng **`@strBUPatternOfUser` KHÔNG xuất hiện lần nào trong câu SQL** (đã đếm: đúng 1
//    lần trong cả hàm, chính là dòng bind). ⇒ **phạm vi BU vô hiệu**. Cùng khuôn
//    #B46/#B47/#B50/#B52/#B53. Port trả `outOfScopeCount` + cờ `enforceBuScope`, **không tự bịt**.
app.MapGet("/api/transpfees/versions/history", async (
    AppDbContext db, ITenantContext t,
    string? tfvCode, string? flagActive, DateTime? createdFrom, DateTime? createdTo,
    string? provinceCodeFrom, string? provinceCodeTo, string? transporterCode, string? modelCode,
    string? isGetDetail, string? buPattern, string? enforceBuScope) =>
{
    var wantDetail = (isGetDetail ?? "").Trim() == "1";
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();

    // `#tbl_Mst_TranspFeeVer_Filter` — lọc TFVCode qua bảng LỊCH SỬ (không phải bảng hiện hành).
    var hist = await db.TranspFeeHists.Where(h => h.OrgId == t.OrgId).ToListAsync();

    // BỐN inner join danh mục địa lý: thiếu một mã là LOẠI dòng.
    var provinces = (await db.Masters.Where(m => m.OrgId == t.OrgId && m.Category == "Province")
        .Select(m => new { m.Code, m.Name }).ToListAsync());
    var provName = provinces.GroupBy(p => p.Code).ToDictionary(g => g.Key!, g => g.First().Name);
    var districts = (await db.Masters.Where(m => m.OrgId == t.OrgId && m.Category == "District")
        .Select(m => new { m.Code, m.Name }).ToListAsync());
    var distName = districts.GroupBy(d => d.Code).ToDictionary(g => g.Key!, g => g.First().Name);

    var beforeGeo = hist.Count;
    hist = hist.Where(h =>
        provName.ContainsKey(h.ProvinceCodeFrom) && provName.ContainsKey(h.ProvinceCodeTo)
        && h.DistrictCodeFrom != null && distName.ContainsKey(h.DistrictCodeFrom)
        && h.DistrictCodeTo != null && distName.ContainsKey(h.DistrictCodeTo)).ToList();
    var droppedNoGeo = beforeGeo - hist.Count;

    if (!string.IsNullOrWhiteSpace(tfvCode)) hist = hist.Where(h => h.TFVCode == tfvCode.Trim()).ToList();
    if (!string.IsNullOrWhiteSpace(provinceCodeFrom)) hist = hist.Where(h => h.ProvinceCodeFrom == provinceCodeFrom.Trim().ToUpperInvariant()).ToList();
    if (!string.IsNullOrWhiteSpace(provinceCodeTo)) hist = hist.Where(h => h.ProvinceCodeTo == provinceCodeTo.Trim().ToUpperInvariant()).ToList();
    if (!string.IsNullOrWhiteSpace(transporterCode)) hist = hist.Where(h => h.TransporterCode == transporterCode.Trim().ToUpperInvariant()).ToList();
    if (!string.IsNullOrWhiteSpace(modelCode)) hist = hist.Where(h => h.ModelCode == modelCode.Trim().ToUpperInvariant()).ToList();

    var tfvCodes = hist.Select(h => h.TFVCode).Distinct().ToList();
    var vers = await db.TranspFeeVers
        .Where(v => v.OrgId == t.OrgId && tfvCodes.Contains(v.TFVCode)).ToListAsync();
    if (!string.IsNullOrWhiteSpace(flagActive)) vers = vers.Where(v => v.FlagActive == flagActive.Trim()).ToList();
    if (createdFrom is not null) vers = vers.Where(v => v.CreatedDate >= createdFrom).ToList();
    if (createdTo is not null) vers = vers.Where(v => v.CreatedDate <= createdTo).ToList();
    var keep = vers.Select(v => v.TFVCode).ToHashSet();
    hist = hist.Where(h => keep.Contains(h.TFVCode)).ToList();

    // Phạm vi BU: nguồn bind mà KHÔNG dùng ⇒ chỉ đo, chỉ lọc khi bật cờ.
    var transporters = await db.Dealers.Where(d => d.OrgId == t.OrgId)
        .Select(d => new { d.DealerCode, d.BUCode }).ToListAsync();
    bool InScope(string? code)
    {
        if (pattern is null) return true;
        var d = transporters.FirstOrDefault(x => x.DealerCode == code);
        return d is not null && (d.BUCode ?? "").ToUpperInvariant().StartsWith(pattern);
    }
    var outOfScopeCount = hist.Count(h => !InScope(h.TransporterCode));
    if (enforceBuScope == "1") hist = hist.Where(h => InScope(h.TransporterCode)).ToList();

    var versions = vers.Where(v => hist.Any(h => h.TFVCode == v.TFVCode))
        .OrderByDescending(v => v.CreatedDate).Select(v => new
        {
            mtfvTFVCode = v.TFVCode, mtfvCreatedDate = v.CreatedDate, mtfvCreatedBy = v.CreatedBy,
            mtfvFlagActive = v.FlagActive, mtfvRemark = v.Remark,
            lineCount = hist.Count(h => h.TFVCode == v.TFVCode)
        }).ToList();

    object? detail = null;
    if (wantDetail)
        detail = hist.OrderBy(h => h.TFVCode, StringComparer.Ordinal)
            .ThenBy(h => h.ProvinceCodeFrom, StringComparer.Ordinal).Select(h => new
            {
                mtfhTFVCode = h.TFVCode,
                mtfhProvinceCodeFrom = h.ProvinceCodeFrom, ProvinceNameFrom = provName[h.ProvinceCodeFrom],
                mtfhProvinceCodeTo = h.ProvinceCodeTo, ProvinceNameTo = provName[h.ProvinceCodeTo],
                mtfhDistrictCodeFrom = h.DistrictCodeFrom, DistrictNameFrom = distName[h.DistrictCodeFrom!],
                mtfhDistrictCodeTo = h.DistrictCodeTo, DistrictNameTo = distName[h.DistrictCodeTo!],
                mtfhTransporterCode = h.TransporterCode, mtfhModelCode = h.ModelCode,
                mtfhValFee = h.ValFee, mtfhExpectedDays = h.ExpectedDays, mtfhCreatedDate = h.CreatedDate
            }).ToList();

    return Results.Ok(new
    {
        versionCount = versions.Count, versions,
        isGetDetail = wantDetail, detail,
        droppedNoGeo, outOfScopeCount, buScopeEnforced = enforceBuScope == "1",
        threeTablesNote = "NGUON CO BA BANG, PORT CU GOP CON MOT: Mst_TranspFeeVer (dau phien ban) + Mst_TranspFee (dang hieu luc) + Mst_TranspFeeHist (ANH CHUP dong phi cua tung phien ban). Port cu chi gan TFVCode len TranspFee => khong co dau phien ban va khong co anh chup => xem lai mot phien ban cu se ra SO HIEN TAI, khong phai so cua luc do.",
        readsHistNote = "Ham nay doc Mst_TranspFeeHist, KHONG doc Mst_TranspFee - do la toan bo ly do no ton tai. Sinh doi gan ke Mst_TranspFeeVerGet_New20181115 (WS :39187) moi la ban doc bang DANG hieu luc.",
        geoJoinNote = "BON INNER JOIN danh muc dia ly (Mst_Province x2 + Mst_District x2, ca dau DI va DEN): dong co tinh/huyen KHONG tra duoc trong danh muc se BI LOAI khoi ket qua - KHONG hien ra voi o trong. Da dem o droppedNoGeo.",
        isGetDetailNote = "strIsGetDetail quyet dinh CO CHAY cau truy van thu ba hay khong: mac dinh zzzzClauseSelect_Mst_TranspFee_Hist = '-- Nothing.'; chi khi co = Flag.Active moi noi cau select dong chi tiet (kem ProvinceNameFrom... lay tu join). KHONG phai 'an cot' ma la khong chay han cau truy van.",
        rbacHole = "LO HONG RBAC - bien the 2 (khai ma KHONG dung), ca thu 10: nguon bind '@strBUPatternOfUser' = drAbilityOfUser['BUPattern'] (:2342) nhung @strBUPatternOfUser KHONG xuat hien lan nao trong cau SQL (dem duoc dung 1 lan trong ca ham, chinh la dong bind) => PHAM VI BU VO HIEU. Cung khuon #B46/#B47/#B50/#B52/#B53. Port tra outOfScopeCount + co enforceBuScope; KHONG tu bit."
    });
}).RequireAuthorization();

// ===== #B91 TRA NGÀY HẠN THANH TOÁN CỌC — `Mst_Calendar_GetForDepositDuty_New20181115` =====
// Trace LIVE: WS `:1513` → `_biz.Mst_Calendar_GetForDepositDuty_New20181115`
//   (`BizHTC.MasterData.cs:1366`). 3B đo thật, **khớp cả 2 máy**: start=1366 md5
//   `cd698e82176516841d4757ae96660c5d`.
// 🔴 **Đây chính là mảnh còn thiếu của #B77**: hàm dùng **cùng khuôn**
//    `mySql_GetClauseSelect_Mst_Calendar_GetForDayT()` (`BizHTC.Common.cs:1682`) và **cùng tham số
//    hệ thống** `TConst.HTCParamCode.Calendar_DepositDuty_DayT`, nhưng ở đây chỉ **TRA CỨU** —
//    không ghi gì. Dùng để xem trước ngày hạn trước khi chạy `Ord_SalesOrder_Update_Calc` (#B77).
// 🔴 Nhắc lại quy tắc "ngày thứ T" (`C0-…quinquagesimusseptimus`): đánh số **liên tiếp các NGÀY LÀM
//    VIỆC** (`CalendarType='WorkingDay'` ∧ **`StatusValue = 0`** ∧ `Date >= @strMCALDate_From`) bằng
//    `identity(bigint,0,1) MyIdxSeq`, rồi self-join `MyIdxSeq + @nDayT` ⇒ **nhảy T VỊ TRÍ**, không
//    phải cộng T ngày lịch. Trả nguyên bảng `#tbl_Mst_Calendar_DayT` (mỗi ngày làm việc một dòng,
//    kèm ngày-thứ-T tương ứng), **không** phải một giá trị đơn lẻ.
// 🔴 **LỖ HỔNG RBAC — biến thể 2, ca thứ 11**: `@strBUPatternOfUser` được bind (`:1388`) nhưng
//    **đếm được đúng 1 lần trong cả hàm** — chính là dòng bind; câu SQL lịch **không dùng đến**.
//    Ở đây tác hại thấp (lịch làm việc là dữ liệu chung), nhưng vẫn ghi vào hồ sơ để **đủ mẫu**.
// 📌 NỢ (giống #B77): tham số `Calendar_DepositDuty_DayT` nằm ở bảng tham số hệ thống
//    (`myUtils_GetParamsRaw`) **chưa có trong MiniHTC** ⇒ **KHÔNG đoán**, nhận qua query `dayT`;
//    thiếu ⇒ trả `Mst_Calendar_GetForDepositDuty_ParamNotSet`.
app.MapGet("/api/calendars/deposit-duty", async (
    AppDbContext db, ITenantContext t, DateTime? fromDate, int? dayT) =>
{
    if (fromDate is null)
        return Results.BadRequest(new { error = "Mst_Calendar_GetForDepositDuty_InvalidDateFrom" });
    if (dayT is null)
        return Results.BadRequest(new
        {
            error = "Mst_Calendar_GetForDepositDuty_ParamNotSet",
            missing = "Calendar_DepositDuty_DayT",
            note = "Tham so nay nam o bang tham so he thong (myUtils_GetParamsRaw) chua co trong MiniHTC. KHONG doan gia tri - phai truyen vao (giong no cua #B77)."
        });

    var from = fromDate.Value.Date;
    // `CalendarType = 'WorkingDay'` AND `StatusValue = 0` (0 = NGÀY LÀM VIỆC) AND `Date >= @from`.
    var workDays = await db.MstCalendars
        .Where(c => c.OrgId == t.OrgId && c.CalendarType == "WorkingDay" && c.StatusValue == "0" && c.Date >= from)
        .OrderBy(c => c.Date).Select(c => c.Date).ToListAsync();

    // `identity(bigint, 0, 1) MyIdxSeq` rồi `left join … on t.MyIdxSeq + @nDayT = t1.MyIdxSeq`.
    var items = workDays.Select((d, i) => new
    {
        myIdxSeq = i,
        mcalDate = d,
        myIdxSeqDayT = (i + dayT.Value) < workDays.Count ? (int?)(i + dayT.Value) : null,
        dateDayT = (i + dayT.Value) < workDays.Count ? (DateTime?)workDays[i + dayT.Value] : null
    }).ToList();

    return Results.Ok(new
    {
        fromDate = from, dayT,
        workingDayCount = workDays.Count,
        count = items.Count, items,
        dayTRule = "'Ngay thu T' la NGAY LAM VIEC THU T, KHONG phai cong T ngay lich: danh so lien tiep cac ngay da loc (CalendarType='WorkingDay' AND StatusValue=0 AND Date >= @strMCALDate_From) bang identity(bigint,0,1) MyIdxSeq roi self-join 'MyIdxSeq + @nDayT' de NHAY T VI TRI. Xem luat C0-...quinquagesimusseptimus.",
        statusValueNote = "StatusValue = 0 NGHIA LA NGAY LAM VIEC (0 = khong nghi). Hieu nguoc dau la lech toan bo moc han.",
        shapeNote = "Nguon tra NGUYEN bang #tbl_Mst_Calendar_DayT - moi ngay lam viec mot dong kem ngay-thu-T tuong ung - KHONG phai mot gia tri don le. Dong co dateDayT = null la ngay ma lich chua khai bao du xa.",
        relatedNote = "Day chinh la manh con thieu cua #B77 (Ord_SalesOrder_Update_Calc): CUNG khuon mySql_GetClauseSelect_Mst_Calendar_GetForDayT (BizHTC.Common.cs:1682) va CUNG tham so Calendar_DepositDuty_DayT, nhung o day chi TRA CUU - khong ghi gi.",
        rbacHole = "LO HONG RBAC - bien the 2 (khai ma khong dung), ca thu 11: @strBUPatternOfUser duoc bind (:1388) nhung dem duoc dung 1 lan trong ca ham - chinh la dong bind; cau SQL lich KHONG dung den. Tac hai thap (lich lam viec la du lieu chung) nhung van ghi de DU MAU.",
        paramDebt = "NO giong #B77: Calendar_DepositDuty_DayT o bang tham so he thong chua co trong MiniHTC => nhan qua query dayT."
    });
}).RequireAuthorization();

// ===== Biên bản vận chuyển / giao nhận (TransportMinutes — port 1:1 FrmNewTransportMinutes/FrmMngTransportMinutes) =====
app.MapGet("/api/transminutes", async (AppDbContext db, ITenantContext t, string? status, string? dealer) =>
{
    var q = db.TransportMinutes.Where(m => m.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(m => m.Status == status);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(m => m.DealerCode == dealer);
    var items = await q.OrderByDescending(m => m.Id).Take(500).Select(m => new
    {
        m.TransportMinutesNo, m.DealerCode, m.TransporterCode, m.Status, m.CreatedAt, m.DecidedAt,
        // #142 parity Car_TransportMinutes: hai trục còn lại + mọi mốc duyệt.
        m.DLTransportMinutesStatus, m.HTCTransportMinutesStatus, m.TransportMinutesDate, m.FilePath,
        m.DLCreatedDateTime, m.DLCreatedBy, m.DLApprDateTime, m.DLApprBy,
        m.HTCAppr1DateTime, m.HTCAppr1By, m.HTCAppr2DateTime, m.HTCAppr2By,
        m.HTCCancelDateTime, m.HTCCancelBy, m.LogLUDateTime, m.LogLUBy,
        cars = db.TransportMinutesCars.Count(c => c.OrgId == t.OrgId && c.MinutesId == m.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/transminutes", async (TransMinDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode) || string.IsNullOrWhiteSpace(dto.TransporterCode))
        return Results.BadRequest(new { error = "Cần DealerCode và TransporterCode." });
    var vins = (dto.Cars ?? new List<TransMinCarDto>()).Where(c => !string.IsNullOrWhiteSpace(c.Vin)).ToList();
    if (vins.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 VIN." });
    var dupe = vins.GroupBy(c => c.Vin.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });
    var no = "TM" + DateTime.Now.ToString("yyMMddHHmmss");
    var whoTM = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var nowTM = DateTime.Now;
    // #142 parity: nguồn tạo biên bản ở CẢ BA trục = "P" và ghi cặp DLCreated*.
    var m = new TransportMinutes { OrgId = t.OrgId, TransportMinutesNo = no, DealerCode = dto.DealerCode.Trim().ToUpperInvariant(),
        TransporterCode = dto.TransporterCode.Trim().ToUpperInvariant(),
        Status = "P", DLTransportMinutesStatus = "P", HTCTransportMinutesStatus = "P",
        TransportMinutesDate = dto.TransportMinutesDate ?? nowTM,
        DLCreatedDateTime = nowTM, DLCreatedBy = whoTM, LogLUDateTime = nowTM, LogLUBy = whoTM };
    db.TransportMinutes.Add(m); await db.SaveChangesAsync();
    foreach (var c in vins)
        db.TransportMinutesCars.Add(new TransportMinutesCar { OrgId = t.OrgId, MinutesId = m.Id, Vin = c.Vin.Trim().ToUpperInvariant(), DoNo = c.DoNo, ColorCode = c.ColorCode, EngineNo = c.EngineNo,
            DtlStatus = "P", CarId = c.CarId, LogLUDateTime = nowTM, LogLUBy = whoTM });
    await db.SaveChangesAsync();
    return Results.Ok(new { m.TransportMinutesNo, m.DealerCode, m.TransporterCode, cars = vins.Count, status = m.Status });
}).RequireAuthorization();

