        dealerFilterNote = "Giong pivot tham khach: inner join Mst_Dealer + FlagActive='1' + BUCode like @strBUPatternOfUser."
    });
}).RequireAuthorization();
app.MapGet("/api/reports/guarantee-due-payment", async (
    AppDbContext db, ITenantContext t, DateTime? dateEndFrom, DateTime? dateEndTo) =>
{
    if (dateEndFrom is null || dateEndTo is null)
        return Results.BadRequest(new { error = "Cần khoảng ngày kết thúc bảo lãnh (dateEndFrom, dateEndTo)." });
    var dFrom = dateEndFrom.Value; var dTo = dateEndTo.Value;
    var today = DateTime.Now.Date;

    var rows = await (from d in db.BankGuaranteeDtls.Where(x => x.OrgId == t.OrgId
                            && x.GuaranteeDetailStatus == "A"
                            && x.DateEnd != null && x.DateEnd >= dFrom && x.DateEnd <= dTo)
                      join h in db.BankGuarantees.Where(x => x.OrgId == t.OrgId
                            && x.BankCode != "TCGBANK" && x.BankCode != "DEALER")
                           on d.GuaranteeId equals h.Id
                      select new
                      {
                          d.VIN, d.DateEnd, d.GrtValue, d.DateStart,
                          h.GuaranteeNo, h.BankCode, h.BankGuaranteeNo, h.DealerCode
                      }).ToListAsync();

    // `inner join Car_VIN` / `inner join Car_Car` của nguồn ⇒ VIN chưa khai bị LOẠI.
    var vins = rows.Select(r => r.VIN).Distinct().ToList();
    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && vins.Contains(c.VIN)).ToListAsync();
    var known = cars.ToDictionary(c => c.VIN);
    var droppedNoCarVin = rows.Count(r => !known.ContainsKey(r.VIN));
    rows = rows.Where(r => known.ContainsKey(r.VIN)).ToList();

    var banks = await db.MstBanks.Where(b => b.OrgId == t.OrgId).Select(b => new { b.BankCode, b.BankName }).ToListAsync();
    var dealers = await db.Dealers.Where(x => x.OrgId == t.OrgId).Select(x => new { x.DealerCode, x.DealerName }).ToListAsync();

    var items = rows.Select(r =>
    {
        var cv = known[r.VIN];
        // `NgayCham = datediff(day, pgd.DateEnd, getdate())` — ÂM nghĩa là chưa tới hạn.
        var ngayCham = (int)(today - r.DateEnd!.Value.Date).TotalDays;
        return new
        {
            ccCarId = cv.VIN, cvVIN = r.VIN,
            cvModelCode = cv.ModelCode, cvSpecCode = cv.SpecCode, cvColorCode = cv.ColorCode,
            ccUnitPriceActual = cv.UnitPriceActual,
            pgdDateEnd = r.DateEnd, pgdDateStart = r.DateStart, pgdGuaranteeValue = r.GrtValue,
            pgGuaranteeNo = r.GuaranteeNo, pgBankCode = r.BankCode,
            bankName = banks.FirstOrDefault(b => b.BankCode == r.BankCode)?.BankName,
            pgBankGuaranteeNo = r.BankGuaranteeNo,
            dealerCode = r.DealerCode,
            dealerName = dealers.FirstOrDefault(x => x.DealerCode == r.DealerCode)?.DealerName,
            ngayCham,
            overdue = ngayCham >= 0,
            paidPercent = (decimal?)null,      // NỢ: cần Pmt_PaymentDetail
            amountNotPaid = (decimal?)null     // NỢ
        };
    }).OrderBy(x => x.pgBankCode).ThenByDescending(x => x.ngayCham).ToList();

    return Results.Ok(new
    {
        dateEndFrom = dFrom, dateEndTo = dTo, asOfDate = today,
        count = items.Count, droppedNoCarVin,
        overdueCount = items.Count(x => x.overdue),
        notYetDueCount = items.Count(x => !x.overdue),
        totalGuaranteeValue = items.Sum(x => x.pgdGuaranteeValue),
        conditionsFromSource = new[]
        {
            "Co bao lanh A: GuaranteeDetailStatus in ('A')",
            "Ngay ket thuc bao lanh trong [a;b]: DateEnd >= @From and <= @To",
            "KHONG lay VIN co NH phat hanh la TCGBANK va DEALER: BankCode not in ('TCGBANK','DEALER') - loai tru theo MA NGAN HANG, khong phai theo loai bao lanh",
            "So ngay cham TT BL = datediff(day, DateEnd, getdate())"
        },
        ngayChamNote = "Chu thich nguon noi 'So ngay cham >= 0' nhung dieu kien do KHONG co trong WHERE cua khoi loc => port DONG ACTIVE: khong chan, tra ca dong ngayCham AM (chua toi han) va dem rieng o notYetDueCount.",
        debt = "NO co nhan: dieu kien 'Tong % da thanh toan < 100% den today' va cot paidPercent/amountNotPaid can tang Pmt_PaymentDetail - MiniHTC chua co, tra null, KHONG suy so. Khoi #tbl_Pmt_PaymentDetailTotal_Temp o nguon cung DA BI COMMENT ('Ham nay gay cham => tach thanh 2 ham o duoi')."
    });
}).RequireAuthorization();
app.MapGet("/api/reports/car-doc-req-pivot", async (
    AppDbContext db, ITenantContext t, DateTime? tDate, string? buPattern) =>
{
    var asOf = (tDate ?? DateTime.Now).Date;
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();

    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId)
        .Select(d => new { d.DealerCode, d.DealerName, d.BUCode }).ToListAsync();
    var scope = dealers.Where(d => pattern is null || (d.BUCode ?? "").ToUpperInvariant().StartsWith(pattern))
        .Select(d => d.DealerCode).ToHashSet();

    // Cả DÒNG và ĐẦU đề nghị đều phải 'A'.
    var heads = await db.CarDocRequests.Where(r => r.OrgId == t.OrgId && r.Status == "A").ToListAsync();
    var headIds = heads.Select(h => h.Id).ToList();
    var lines = await db.CarDocRequestCars
        .Where(c => c.OrgId == t.OrgId && headIds.Contains(c.RequestId) && c.DRDtlStatus == "A").ToListAsync();

    // `inner join Car_VIN` / `inner join Car_Car` ⇒ VIN chưa khai bị LOẠI.
    var vins = lines.Select(l => l.CarId).Distinct().ToList();
    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && vins.Contains(c.VIN)).ToListAsync();
    var known = cars.ToDictionary(c => c.VIN);
    var droppedNoCarVin = lines.Count(l => !known.ContainsKey(l.CarId));
    lines = lines.Where(l => known.ContainsKey(l.CarId)).ToList();

    var models = await db.CarModelStds.Where(m => m.OrgId == t.OrgId).Select(m => new { m.ModelCode, m.ModelName }).ToListAsync();
    var specs = await db.CarSpecs.Where(s => s.OrgId == t.OrgId).Select(s => new { s.SpecCode, s.SpecDesc }).ToListAsync();
    var colors = await db.MstCarColors.Where(c => c.OrgId == t.OrgId)
        .Select(c => new { c.ModelCode, c.ColorCode, c.ColorExtCode, c.ColorExtNameVN, c.ColorIntCode, c.ColorIntNameVN }).ToListAsync();

    int divideByZeroRows = 0, droppedByDealerJoin = 0;
    var items = new List<object>();
    foreach (var l in lines)
    {
        var cv = known[l.CarId];
        if (cv.DealerCode == null || !scope.Contains(cv.DealerCode)) { droppedByDealerJoin++; continue; }
        // 🔴 Vế `OR` của nguồn — KHÔNG phải AND. (Vế `pgd.DateStart is null` luôn đúng ở MiniHTC vì
        //    chưa có tầng `Pmt_GuaranteeDetail` ⇒ điều kiện này hiện **không loại dòng nào**; ghi nợ.)
        var mortageEndIsNull = cv.MortageEndDate is null;
        var guaranteeStartIsNull = true;                       // NỢ: chưa có Pmt_GuaranteeDetail
        if (!(mortageEndIsNull || guaranteeStartIsNull)) continue;

        var h = heads.First(z => z.Id == l.RequestId);
        var mo = models.FirstOrDefault(m => m.ModelCode == cv.ModelCode);
        var sp = specs.FirstOrDefault(s => s.SpecCode == cv.SpecCode);
        var co = colors.FirstOrDefault(c => c.ModelCode == cv.ModelCode && c.ColorCode == cv.ColorCode);
        var dl = dealers.FirstOrDefault(d => d.DealerCode == cv.DealerCode);

        int? dutyDays = h.ApprovedDate2 is null ? null : (int)(asOf - h.ApprovedDate2.Value.Date).TotalDays;
        // Chia 0: nguồn không bảo vệ ⇒ port trả null và ĐẾM RIÊNG, không bịa 0%.
        decimal? dutyPct = null;
        if ((cv.UnitPriceActual ?? 0m) == 0m) divideByZeroRows++;

        items.Add(new
        {
            drListCode = h.RequestNo, drListStatus = h.Status, drDtlStatus = l.DRDtlStatus,
            cdrlApprovedDate2 = h.ApprovedDate2, dutyDays,
            cvVIN = cv.VIN, ccCarId = cv.VIN, cvModelCode = cv.ModelCode, mcmModelName = mo?.ModelName,
            mcsSpecCode = cv.SpecCode, mcsSpecDescription = sp?.SpecDesc,
            cvColorCode = cv.ColorCode, cvColorExtCode = co?.ColorExtCode, cvColorExtNameVN = co?.ColorExtNameVN,
            cvColorIntCode = co?.ColorIntCode, cvColorIntNameVN = co?.ColorIntNameVN,
            ccDealerCode = cv.DealerCode, ccDealerName = dl?.DealerName,
            cvMortageEndDate = cv.MortageEndDate, cvCODate = cv.CODate,
            ccUnitPriceActual = cv.UnitPriceActual,
            dutyCompletedPercent = dutyPct,          // NỢ: cần tầng cọc + bảo lãnh
            pmpdDepositAmount = (decimal?)null,      // NỢ
            pmgdGuaranteeValue = (decimal?)null      // NỢ
        });
    }

    return Results.Ok(new
    {
        asOfDate = asOf, count = items.Count, items,
        droppedNoCarVin, droppedByDealerJoin, divideByZeroRows,
        filterRule = "(cv.MortageEndDate IS NULL  OR  pgd.DateStart IS NULL) AND cdrd.DRDtlStatus='A' AND cdrl.DRListStatus='A' — ve dau la OR, KHONG phai AND; chu thich 'Chua co ngay giao ho so' chi gan cho ve TRAI.",
        twoStatusAxesNote = "Ca DONG (DRDtlStatus) lan DAU (DRListStatus) deu phai 'A' - hai truc rieng, phai kiem ca hai.",
        dutyDaysRule = "DutyDays = DateDiff(day, cdrl.ApprovedDate2, @strTDate) - moc la duyet cap 2 cua DAU de nghi, KHONG phai cua dong.",
        divideByZeroNote = "DutyCompletedPercent cua nguon chia cho cc.UnitPriceActual KHONG co bao ve chia 0 - port tra null va dem rieng o divideByZeroRows, KHONG bia 0%.",
        debt = "NO co nhan: Pmt_GuaranteeDetail va khoi CachingForPaymentTotal/CachingForPayment_Deposit (tien coc) chua co o MiniHTC => dutyCompletedPercent / pmpdDepositAmount / pmgdGuaranteeValue tra null. Ve loc 'pgd.DateStart IS NULL' hien khong loai dong nao. Cung mon no da ghi o #B37/#B56."
    });
}).RequireAuthorization();
app.MapGet("/api/reports/business-status-period", async (
    AppDbContext db, ITenantContext t, DateTime? fromDate, DateTime? toDate,
    string? buPattern, string? groupBy) =>
{
    if (fromDate is null || toDate is null)
        return Results.BadRequest(new { error = "Cần khoảng thời gian (fromDate, toDate)." });
    var dFrom = fromDate.Value; var dTo = toDate.Value;
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();

    // `#tbl_Mst_Dealer` — lọc `BUCode like @strBUPatternOfUser` (LỌC THẬT).
    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId)
        .Select(d => new { d.DealerCode, d.DealerName, d.BUCode, d.FlagActive }).ToListAsync();
    var scopeList = dealers.Where(d => pattern is null || (d.BUCode ?? "").ToUpperInvariant().StartsWith(pattern)).ToList();
    var scope = scopeList.Select(d => d.DealerCode).ToHashSet();

    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId).ToListAsync();
    cars = cars.Where(c => c.DealerCode != null && scope.Contains(c.DealerCode)).ToList();

    // Xe tồn tại tại một mốc.
    List<CarVinMaster> ExistAt(DateTime at) => cars
        .Where(c => c.CreatedDate != null && c.CreatedDate <= at
                    && (c.CarCancelDate == null || c.CarCancelDate > at)).ToList();
    var fromCars = ExistAt(dFrom);
    var toCars = ExistAt(dTo);

    // "Đã bán tận tay khách cuối" — CHỈ bán lẻ (`DealerCodeBuyer is null`).
    var soldLines = await (from f in db.DealerDealDetails.Where(x => x.OrgId == t.OrgId
                                && (x.DeliveryStatus == "A" || x.DeliveryStatus == "F"))
                           join d in db.DealerDeals.Where(x => x.OrgId == t.OrgId
                                && (x.DealerCodeBuyer == null || x.DealerCodeBuyer == ""))
                                on f.DealId equals d.Id
                           select new { f.CarId, d.DealDate, d.DealerCode }).ToListAsync();
    HashSet<string> SoldBy(DateTime at) => soldLines.Where(x => x.DealDate <= at).Select(x => x.CarId).ToHashSet();

    // Lệnh xuất xe.
    var cdod = await db.DeliveryOrderCars.Where(x => x.OrgId == t.OrgId)
        .Select(x => new { Key = x.CarId ?? x.Vin, x.Vin, x.ConfirmStatus, x.DeliveryOutDate, x.DeliveryEndDate })
        .ToListAsync();

    // Tồn kho ĐẠI LÝ tại mốc: đã tiếp nhận (`DeliveryEndDate <= @mốc` + `ConfirmStatus = 'F'`) TRỪ đã bán lẻ.
    List<string> DealerInStock(List<CarVinMaster> pool, DateTime at)
    {
        var sold = SoldBy(at);
        var received = cdod.Where(x => x.ConfirmStatus == "F"
                                       && x.DeliveryEndDate != null && x.DeliveryEndDate <= at)
                           .Select(x => x.Key).ToHashSet();
        return pool.Where(c => received.Contains(c.VIN) && !sold.Contains(c.VIN)).Select(c => c.VIN).ToList();
    }
    // Back-order tại mốc: CHƯA có LXX active-đã-xuất tính tới mốc (lọc ngược).
    List<string> BackOrder(List<CarVinMaster> pool, DateTime at)
    {
        var outed = cdod.Where(x => (x.ConfirmStatus == "A" || x.ConfirmStatus == "F")
                                    && x.DeliveryOutDate != null && x.DeliveryOutDate <= at)
                        .Select(x => x.Key).ToHashSet();
        return pool.Where(c => !outed.Contains(c.VIN)).Select(c => c.VIN).ToList();
    }

    // Xe HUỶ trong kỳ: FlagActive='0' và CarCancelDate ∈ [dFrom, dTo].
    var cancelled = cars.Where(c => c.FlagActive == "0"
                                    && c.CarCancelDate >= dFrom && c.CarCancelDate <= dTo).ToList();

    // Đơn hàng trong kỳ: CreatedDate ∈ [from,to] và SOStatus in ('A2').
    var orders = await (from o in db.SalesOrders.Where(x => x.OrgId == t.OrgId
                            && x.CreatedAt >= dFrom && x.CreatedAt <= dTo && x.Status == "A2")
                        join l in db.SalesOrderLines.Where(x => x.OrgId == t.OrgId) on o.Id equals l.SalesOrderId
                        select new { o.DealerCode, l.ModelCode, l.SpecCode, l.ColorCode, l.RequestedQuantity }).ToListAsync();
    orders = orders.Where(o => scope.Contains(o.DealerCode)).ToList();

    var soldInPeriod = soldLines.Where(x => x.DealDate >= dFrom && x.DealDate <= dTo).ToList();

    var perDealer = scopeList.Select(d => new
    {
        dealerCode = d.DealerCode, dealerName = d.DealerName, buCode = d.BUCode,
        inStockFrom = DealerInStock(fromCars, dFrom).Count(v => cars.First(c => c.VIN == v).DealerCode == d.DealerCode),
        inStockTo = DealerInStock(toCars, dTo).Count(v => cars.First(c => c.VIN == v).DealerCode == d.DealerCode),
        backOrderFrom = BackOrder(fromCars, dFrom).Count(v => cars.First(c => c.VIN == v).DealerCode == d.DealerCode),
        backOrderTo = BackOrder(toCars, dTo).Count(v => cars.First(c => c.VIN == v).DealerCode == d.DealerCode),
        soldInPeriod = soldInPeriod.Count(x => x.DealerCode == d.DealerCode),
        cancelledInPeriod = cancelled.Count(c => c.DealerCode == d.DealerCode),
        orderedQty = orders.Where(o => o.DealerCode == d.DealerCode).Sum(o => o.RequestedQuantity)
    }).Where(x => x.inStockFrom + x.inStockTo + x.backOrderFrom + x.backOrderTo
                  + x.soldInPeriod + x.cancelledInPeriod + x.orderedQty > 0).ToList();

    object? perModel = groupBy == "model"
        ? cars.GroupBy(c => c.ModelCode ?? "").Select(g => new
        {
            modelCode = g.Key,
            inStockTo = DealerInStock(toCars.Where(c => (c.ModelCode ?? "") == g.Key).ToList(), dTo).Count,
            backOrderTo = BackOrder(toCars.Where(c => (c.ModelCode ?? "") == g.Key).ToList(), dTo).Count,
            soldInPeriod = soldInPeriod.Count(x => cars.Any(c => c.VIN == x.CarId && (c.ModelCode ?? "") == g.Key)),
            orderedQty = orders.Where(o => (o.ModelCode ?? "") == g.Key).Sum(o => o.RequestedQuantity)
        }).OrderBy(x => x.modelCode).ToList()
        : null;

    return Results.Ok(new
    {
        fromDate = dFrom, toDate = dTo, groupBy = groupBy ?? "dealer",
        perDealer, perModel,
        soldRule = "DA BAN chi tinh BAN LE TOI NGUOI TIEU DUNG: Dls_DealDetail.DeliveryStatus in ('A','F') VA Dls_Deal.DealerCodeBuyer is null (chu thich nguon: 'Ban toi Khach Cuoi la Nguoi tieu dung') => giao dich ban buon DL->DL BI LOAI.",
        inStockRule = "Ton kho dai ly = da tiep nhan (DeliveryEndDate <= moc VA ConfirmStatus = 'F' - sieu ve CHI 'F', hep hon ('A','F') dung o cho khac) TRU di xe da ban le (ky thuat LOC NGUOC).",
        backOrderRule = "Back-order = LOC NGUOC: xe CHUA co LXX active-da-xuat tinh toi moc.",
        cancelRule = "Xe huy trong ky: FlagActive = '0' VA CarCancelDate trong [dFrom, dTo].",
        orderRule = "Don hang trong ky: CreatedDate trong [from,to] VA SOStatus in ('A2') - 'Chi lay Don hang da Duyet A2'.",
        existAtRule = "Xe ton tai tai mot moc: CreatedDate <= moc VA (CarCancelDate is null HOAC > moc).",
        twoScreensNote = "FrmBusinessStatusByDealer va FrmBusinessStatusByModel dung CHUNG mot ham - tham so groupBy = dealer|model.",
        rbacNote = "@strBUPatternOfUser DUNG THAT (inner join #tbl_Mst_Dealer) - giong #B55/#B56."
    });
}).RequireAuthorization();
app.MapGet("/api/reports/car-delivered-not-duty-complete", async (
    AppDbContext db, ITenantContext t, DateTime? tDate, string? buPattern, string? groupBy) =>
{
    var asOf = (tDate ?? DateTime.Now).Date;
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();

    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId).Select(d => new { d.DealerCode, d.BUCode }).ToListAsync();
    var scope = dealers
        .Where(d => pattern is null || (d.BUCode ?? "").ToUpperInvariant().StartsWith(pattern))
        .Select(d => d.DealerCode).ToHashSet();

    // `#tbl_CDOD_Active`: ConfirmStatus in ('A','F') AND DeliveryOutDate <= @strTDate.
    var cdod = await db.DeliveryOrderCars
        .Where(x => x.OrgId == t.OrgId && (x.ConfirmStatus == "A" || x.ConfirmStatus == "F")
                    && x.DeliveryOutDate != null && x.DeliveryOutDate <= asOf)
        .Select(x => new { Key = x.CarId ?? x.Vin, x.Vin, x.DeliveryOutDate, x.DoId })
        .ToListAsync();

    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId).ToListAsync();
    var byVin = cars.ToDictionary(c => c.VIN);

    var rows = cdod
        .Where(x => byVin.ContainsKey(x.Vin))
        .Select(x => new { Cdod = x, Car = byVin[x.Vin] })
        // `inner join Mst_Dealer … and BUCode like @strBUPatternOfUser` — LỌC THẬT.
        .Where(z => z.Car.DealerCode != null && scope.Contains(z.Car.DealerCode))
        .ToList();

    static (int b1, int b2, int b3, int b4, int b5, int b6) Buckets(int d) => (
        d >= 1 && d <= 15 ? 1 : 0,
        d >= 16 && d <= 30 ? 1 : 0,
        d >= 31 && d <= 60 ? 1 : 0,
        d >= 61 && d <= 180 ? 1 : 0,
        d >= 181 && d <= 360 ? 1 : 0,
        d >= 361 ? 1 : 0);

    var detail = rows.Select(z =>
    {
        var days = (int)(asOf - z.Cdod.DeliveryOutDate!.Value.Date).TotalDays;
        var (b1, b2, b3, b4, b5, b6) = Buckets(days);
        return new
        {
            ccCarId = z.Cdod.Key, cvVIN = z.Car.VIN, cvModelCode = z.Car.ModelCode,
            cvSpecCode = z.Car.SpecCode, cvColorCode = z.Car.ColorCode, ccDealerCode = z.Car.DealerCode,
            cdodDeliveryOutDate = z.Cdod.DeliveryOutDate, daysOut = days,
            type1_15 = b1, type16_30 = b2, type31_60 = b3, type61_180 = b4, type181_360 = b5, type361 = b6,
            uncategorized = (b1 + b2 + b3 + b4 + b5 + b6) == 0 ? 1 : 0,   // d = 0: nguồn không xếp nhóm
            paymentDeposit = (decimal?)null    // NỢ: khối CachingForPayment_Deposit chưa port
        };
    }).ToList();

    object Totals(IEnumerable<dynamic> src) => new
    {
        qty = src.Count(),
        type1_15 = src.Sum(x => (int)x.type1_15), type16_30 = src.Sum(x => (int)x.type16_30),
        type31_60 = src.Sum(x => (int)x.type31_60), type61_180 = src.Sum(x => (int)x.type61_180),
        type181_360 = src.Sum(x => (int)x.type181_360), type361 = src.Sum(x => (int)x.type361),
        uncategorized = src.Sum(x => (int)x.uncategorized)
    };

    // Ba màn dùng chung hàm này, khác nhau ở TRỤC GOM: theo đại lý / theo spec / không gom.
    object? grouped = groupBy switch
    {
        "dealer" => detail.GroupBy(x => x.ccDealerCode)
            .Select(g => new { dealerCode = g.Key, totals = Totals(g) }).OrderBy(x => x.dealerCode).ToList(),
        "spec" => detail.GroupBy(x => x.cvSpecCode)
            .Select(g => new { specCode = g.Key, totals = Totals(g) }).OrderBy(x => x.specCode).ToList(),
        _ => null
    };

    return Results.Ok(new
    {
        asOfDate = asOf, count = detail.Count, totals = Totals(detail),
        groupBy = groupBy ?? "none", grouped,
        detail,
        filterRule = "mySql_Car_DeliveryOrderDetail_FilterActive_01: ConfirmStatus in ('A','F') VA DeliveryOutDate <= @strTDate. Manh SQL nay DUNG CHUNG cho nhieu bao cao.",
        bucketRule = "6 nhom tuoi theo DateDiff(day, DeliveryOutDate, @strTDate): 1-15 / 16-30 / 31-60 / 61-180 / 181-360 / >=361. BIEN KHEP HAI DAU => d = 0 (xuat trong ngay) KHONG thuoc nhom nao (ca 6 co = 0) - hanh vi that cua nguon, da dem rieng o 'uncategorized'.",
        threeScreensNote = "FrmCarDeliOutButNotDuty / ...ByDealer / ...BySpec dung CHUNG mot ham, chi khac truc gom - tham so groupBy = dealer|spec|none.",
        rbacNote = "@strBUPatternOfUser DUNG THAT (inner join Mst_Dealer) - giong #B55.",
        debt = "NO co nhan: khoi zzzzClauseSelect_CachingForPayment_Deposit (tien coc) chua port - tra null, KHONG bia so."
    });
}).RequireAuthorization();
app.MapGet("/api/reports/car-on-way", async (
    AppDbContext db, ITenantContext t, DateTime? tDate, string? buPattern) =>
{
    var asOf = tDate ?? DateTime.Now;
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();

    // `inner join Mst_Dealer … and (md.BUCode like @strBUPatternOfUser)` — INNER JOIN thật, lọc thật.
    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId).Select(d => new { d.DealerCode, d.BUCode }).ToListAsync();
    var scope = dealers
        .Where(d => pattern is null || (d.BUCode ?? "").ToUpperInvariant().StartsWith(pattern))
        .Select(d => d.DealerCode).ToHashSet();

    var rows = await (from d in db.DeliveryOrderCars.Where(x => x.OrgId == t.OrgId)
                      join h in db.DeliveryOrders.Where(x => x.OrgId == t.OrgId) on d.DoId equals h.Id
                      select new
                      {
                          d.Vin, d.CarId, d.ModelCode, d.ColorCode, d.StorageCode,
                          d.ConfirmStatus, d.DeliveryOutDate, d.DeliveryEndDate, d.DeliveryStartDate,
                          DoNo = h.DoNo, h.DealerCode, h.CreatedAt
                      }).ToListAsync();

    var beforeScope = rows.Count;
    rows = rows.Where(x => x.DealerCode != null && scope.Contains(x.DealerCode)).ToList();
    var droppedByDealerJoin = beforeScope - rows.Count;

    // BA điều kiện lõi.
    rows = rows.Where(x => (x.ConfirmStatus == "A" || x.ConfirmStatus == "F")
                           && x.DeliveryOutDate is not null && x.DeliveryOutDate <= asOf
                           && x.DeliveryEndDate is null).ToList();

    // `Sto_TranspReqDtl` join theo CẶP (CarId, RefOrdNo = DeliveryOrderNo), chỉ 'A'/'F'.
    var carIds = rows.Select(x => x.CarId ?? x.Vin).Distinct().ToList();
    var trDtls = await (from d in db.TransportReqCars.Where(x => x.OrgId == t.OrgId && carIds.Contains(x.CarId)
                            && (x.TransportReqDtlStatus == "A" || x.TransportReqDtlStatus == "F"))
                        join h in db.TransportRequests.Where(x => x.OrgId == t.OrgId) on d.ReqId equals h.Id
                        select new { d.CarId, RefOrdNo = d.DoNo, h.TranspReqNo, h.TransporterCode, TranspReqDtlStatus = d.TransportReqDtlStatus }).ToListAsync();

    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId).Select(c => new { c.VIN, c.SpecCode, c.LoaiThung }).ToListAsync();

    var items = rows.Select(x =>
    {
        var key = x.CarId ?? x.Vin;
        // 🔴 Khớp CẶP: cùng CarId **và** RefOrdNo = số lệnh xuất — thiếu vế sau là dính YCVT chứng từ khác.
        var tr = trDtls.FirstOrDefault(z => z.CarId == key && z.RefOrdNo == x.DoNo);
        var cv = cars.FirstOrDefault(c => c.VIN == x.Vin);
        return new
        {
            cdoDeliveryOrderNo = x.DoNo, cdoDealerCode = x.DealerCode, cdoCreatedDate = x.CreatedAt,
            cdodCarId = key, cvVIN = x.Vin, cvModelCode = x.ModelCode, cvSpecCode = cv?.SpecCode,
            cvColorCode = x.ColorCode, cvLoaiThung = cv?.LoaiThung, cdodStorageCode = x.StorageCode,
            cdodConfirmStatus = x.ConfirmStatus, cdodDeliveryOutDate = x.DeliveryOutDate,
            cdodDeliveryStartDate = x.DeliveryStartDate, cdodDeliveryEndDate = x.DeliveryEndDate,
            ctrTranspReqNo = tr?.TranspReqNo, ctrTransporterCode = tr?.TransporterCode,
            ctrdTranspReqDtlStatus = tr?.TranspReqDtlStatus,
            daysOnWay = x.DeliveryOutDate is null ? (int?)null : (int)(asOf.Date - x.DeliveryOutDate.Value.Date).TotalDays
        };
    }).OrderBy(x => x.cdoDealerCode).ThenBy(x => x.cvVIN, StringComparer.Ordinal).ToList();

    return Results.Ok(new
    {
        asOfDate = asOf, count = items.Count, items, droppedByDealerJoin,
        coreRule = "ConfirmStatus in ('A','F') VA DeliveryOutDate is not null & <= @strTDate VA DeliveryEndDate is null (chua toi dai ly).",
        onWayDefinitionNote = "Dinh nghia 'dang tren duong' o day theo LENH XUAT XE, KHAC cot FlagIsOnWay cua #B52 von xet theo BIEN BAN GIAO (FDlvMnStatus='A' + TDlvMnStatus='P'). Hai dinh nghia song song trong cung he - dung dung lan.",
        rbacNote = "@strBUPatternOfUser o ham nay DUNG THAT (inner join Mst_Dealer) - chu thich khop code. Bang chung cac ca #B45-#B53 la LECH so voi chuan cua chinh he nguon.",
        joinNote = "Sto_TranspReqDtl khop CAP (CarId, RefOrdNo = DeliveryOrderNo) + TranspReqDtlStatus in ('A','F')."
    });
}).RequireAuthorization();
app.MapGet("/api/reports/mortage-in-out-stock", async (
    AppDbContext db, ITenantContext t, DateTime? fromDate, DateTime? toDate, string? getDetail) =>
{
    if (fromDate is null || toDate is null)
        return Results.BadRequest(new { error = "Cần khoảng thời gian (fromDate, toDate)." });
    var from = fromDate.Value; var to = toDate.Value;

    var cars = await db.CarVinMasters
        .Where(c => c.OrgId == t.OrgId
                    && c.MortageBankCode != null && c.MortageBankCode != ""
                    && c.DocumentsStatus == "A")
        .ToListAsync();

    static bool HasStart(CarVinMaster c) => c.MortageStartDate is not null;
    var dauKy = cars.Where(c => c.MortageStartDate < from
                                && (c.MortageEndDate == null || c.MortageEndDate > from)).ToList();
    var tang = cars.Where(c => c.MortageStartDate >= from && c.MortageStartDate <= to).ToList();
    var giam = cars.Where(c => HasStart(c) && c.MortageEndDate >= from && c.MortageEndDate <= to).ToList();
    var cuoiKy = cars.Where(c => HasStart(c) && c.MortageEndDate == null).ToList();

    // `Mst_CarPrice` theo `max(EffectiveDate)` gom (Model, Spec, Color).
    var prices = await db.CarPrices.Where(p => p.OrgId == t.OrgId).ToListAsync();
    var lastPrice = prices
        .GroupBy(p => new { p.ModelCode, Spec = p.SpecCode ?? "", Color = p.ColorCode ?? "" })
        .ToDictionary(g => g.Key, g => g.OrderByDescending(p => p.EffectiveDate).First().Price);
    decimal PriceOf(CarVinMaster c)
    {
        var k = new { ModelCode = c.ModelCode ?? "", Spec = c.SpecCode ?? "", Color = c.ColorCode ?? "" };
        return lastPrice.TryGetValue(k, out var p) ? p : 0m;
    }

    // `union all` với 4 cột cờ — một VIN có thể nằm ở nhiều nhóm.
    var rows = new List<object>();
    void Add(List<CarVinMaster> src, string flag)
    {
        foreach (var c in src)
            rows.Add(new
            {
                dauKy = flag == "DauKy" ? 1 : 0, tang = flag == "Tang" ? 1 : 0,
                giam = flag == "Giam" ? 1 : 0, cuoiKy = flag == "CuoiKy" ? 1 : 0,
                c.VIN, c.ModelCode, c.SpecCode, c.ColorCode, c.DealerCode,
                c.MortageBankCode, c.MortageStartDate, c.MortageEndDate, c.DocumentsStatus,
                price = PriceOf(c)
            });
    }
    Add(dauKy, "DauKy"); Add(tang, "Tang"); Add(giam, "Giam"); Add(cuoiKy, "CuoiKy");

    var summary = new
    {
        dauKy = new { qty = dauKy.Count, amount = dauKy.Sum(PriceOf) },
        tang = new { qty = tang.Count, amount = tang.Sum(PriceOf) },
        giam = new { qty = giam.Count, amount = giam.Sum(PriceOf) },
        cuoiKy = new { qty = cuoiKy.Count, amount = cuoiKy.Sum(PriceOf) }
    };

    return Results.Ok(new
    {
        fromDate = from, toDate = to, summary,
        detail = getDetail == "1" ? rows : null,
        detailIncluded = getDetail == "1",     // nguồn có cờ `strIsGetDetail`, chỉ trả bảng chi tiết khi bật
        scopeNote = "BAO CAO THE CHAP NGAN HANG (Car_VIN.MortageBankCode), KHONG phai nhap-xuat-ton kho vat ly.",
        commonFilter = "MortageBankCode is not null AND <> '' AND DocumentsStatus = 'A' (ca 4 khoi).",
        sourceQuirk = "Khoi CUOI KY KHONG dung @strTDate_To: dieu kien chi la MortageEndDate is null/'' => 'con the chap tinh den HIEN TAI', khong phai tai cuoi ky. Day la hanh vi that cua nguon (RptSQLQuery.cs:10667-10678) - port giu nguyen, khong tu sua.",
        overlapNote = "4 khoi union all voi 4 cot co 1/0 => MOT VIN co the xuat hien o NHIEU nhom, khong phai phan loai loai tru.",
        priceNote = "Gia lay tu Mst_CarPrice theo max(EffectiveDate) gom (Model, Spec, Color) - bang gia THEO THOI DIEM."
    });
}).RequireAuthorization();
app.MapGet("/api/stocbreqs/search", async (
    AppDbContext db, ITenantContext t,
    string? cbReqNo, string? cbReqStatus, DateTime? createdFrom, DateTime? createdTo,
    string? vin, string? cbReqDtlStatus, int? recordStart, int? recordCount) =>
{
    var start = recordStart ?? 0;
    var count = recordCount ?? 200;

    var heads = await db.StoCBReqs.Where(x => x.OrgId == t.OrgId).ToListAsync();
    if (!string.IsNullOrWhiteSpace(cbReqNo))
    { var k = cbReqNo.Trim().ToUpperInvariant(); heads = heads.Where(h => h.CBReqNo.ToUpperInvariant().Contains(k)).ToList(); }
    if (!string.IsNullOrWhiteSpace(cbReqStatus))
    { var set = cbReqStatus.Split(',').Select(s => s.Trim()).ToHashSet(); heads = heads.Where(h => set.Contains(h.CBReqStatus)).ToList(); }
    if (createdFrom is not null) heads = heads.Where(h => h.CreatedDate >= createdFrom).ToList();
    if (createdTo is not null) heads = heads.Where(h => h.CreatedDate <= createdTo).ToList();

    var headIds = heads.Select(h => h.Id).ToList();
    var dtls = await db.StoCBReqDtls.Where(x => x.OrgId == t.OrgId && headIds.Contains(x.StoCBReqId)).ToListAsync();
    if (!string.IsNullOrWhiteSpace(vin))
    { var k = vin.Trim().ToUpperInvariant(); dtls = dtls.Where(x => x.VIN.ToUpperInvariant().Contains(k)).ToList(); }
    if (!string.IsNullOrWhiteSpace(cbReqDtlStatus)) dtls = dtls.Where(x => x.CBReqDtlStatus == cbReqDtlStatus.Trim()).ToList();

    // 🔴 `left join` toàn tuyến ⇒ chỉ thu hẹp đầu yêu cầu khi NGƯỜI DÙNG lọc theo cột của DÒNG.
    var filterOnDetail = !string.IsNullOrWhiteSpace(vin) || !string.IsNullOrWhiteSpace(cbReqDtlStatus);
    if (filterOnDetail)
    {
        var keep = dtls.Select(x => x.StoCBReqId).ToHashSet();
        heads = heads.Where(h => keep.Contains(h.Id)).ToList();
    }

    // `MyIdxSeq` trên `distinct sc.CBReqNo`, `order by sc.CBReqNo`; `MyCount` đếm TRƯỚC khi cắt.
    var orderedNos = heads.Select(h => h.CBReqNo).Distinct().OrderBy(x => x, StringComparer.Ordinal).ToList();
    var myCount = orderedNos.Count;
    var pageNos = orderedNos.Skip(start).Take(count).ToList();
    var idx = pageNos.Select((no, i) => new { no, i }).ToDictionary(x => x.no, x => x.i);
    heads = heads.Where(h => idx.ContainsKey(h.CBReqNo)).OrderBy(h => idx[h.CBReqNo]).ToList();  // giữ thứ tự MyIdxSeq
    var pageIds = heads.Select(h => h.Id).ToHashSet();
    dtls = dtls.Where(x => pageIds.Contains(x.StoCBReqId)).ToList();

    var items = heads.Select(h => new
    {
        scCBReqNo = h.CBReqNo, scCBReqStatus = h.CBReqStatus, scCreatedDate = h.CreatedDate,
        scCreatedBy = h.CreatedBy, scApprovedBy = h.ApprovedBy, scApprovedAt = h.ApprovedAt, scRemark = h.Remark,
        details = dtls.Where(d => d.StoCBReqId == h.Id)
            .Select(d => new { d.VIN, d.ModelCode, d.SpecCode, d.EngineNo, d.CBReqDtlStatus }).ToList()
    }).ToList();

    return Results.Ok(new
    {
        myCount, recordStart = start, recordCount = count, count = items.Count, items,
        joinNote = "Nguon dung LEFT JOIN toan tuyen (Sto_CBReq <- Sto_CBReqDetail <- Car_VIN <- Car_Car) => yeu cau CHUA CO DONG NAO VAN RA, khac cac man dung inner join Car_VIN.",
        pagingRule = "MyIdxSeq tren distinct CBReqNo, order by CBReqNo; MyCount dem TRUOC khi cat trang; khoi tra ve order by MyIdxSeq asc (giu dung thu tu trang).",
        regionNameTrap = "Khoi #region ten 'Sto_CBReq_GetX_New20181119' nhung ham that la 'Sto_CBReqGet_GetX_New20181119' (thua 'Get') - grep theo ten region se khong thay dinh nghia.",
        rbacQuirk = "@strBUPatternOfUser khai bao nhung KHONG DUNG trong SQL nguon - ca thu BAY."
    });
}).RequireAuthorization();

// (2) Lệnh ĐIỀU CHUYỂN đóng thùng — `Sto_RearrangeCB_GetX_New20181119` (`Biz.HTC.WH.cs:117568`).
app.MapGet("/api/storearcbs/search", async (
    AppDbContext db, ITenantContext t,
    string? stoRearCBNo, string? rearCBStatus, DateTime? createdFrom, DateTime? createdTo,
    string? vin, string? rearCBDtlStatus, int? recordStart, int? recordCount) =>
{
    var start = recordStart ?? 0;
    var count = recordCount ?? 200;

    var heads = await db.StoRearCBs.Where(x => x.OrgId == t.OrgId).ToListAsync();
    if (!string.IsNullOrWhiteSpace(stoRearCBNo))
    { var k = stoRearCBNo.Trim().ToUpperInvariant(); heads = heads.Where(h => h.StoRearCBNo.ToUpperInvariant().Contains(k)).ToList(); }
    if (!string.IsNullOrWhiteSpace(rearCBStatus))
    { var set = rearCBStatus.Split(',').Select(s => s.Trim()).ToHashSet(); heads = heads.Where(h => set.Contains(h.RearCBStatus)).ToList(); }
    if (createdFrom is not null) heads = heads.Where(h => h.CreatedDate >= createdFrom).ToList();
    if (createdTo is not null) heads = heads.Where(h => h.CreatedDate <= createdTo).ToList();

    var headIds = heads.Select(h => h.Id).ToList();
    var dtls = await db.StoRearCBDtls.Where(x => x.OrgId == t.OrgId && headIds.Contains(x.StoRearCBId)).ToListAsync();
    if (!string.IsNullOrWhiteSpace(vin))
    { var k = vin.Trim().ToUpperInvariant(); dtls = dtls.Where(x => x.VIN.ToUpperInvariant().Contains(k)).ToList(); }
    if (!string.IsNullOrWhiteSpace(rearCBDtlStatus)) dtls = dtls.Where(x => x.RearCBDtlStatus == rearCBDtlStatus.Trim()).ToList();

    if (!string.IsNullOrWhiteSpace(vin) || !string.IsNullOrWhiteSpace(rearCBDtlStatus))
    {
        var keep = dtls.Select(x => x.StoRearCBId).ToHashSet();
        heads = heads.Where(h => keep.Contains(h.Id)).ToList();
    }

    var orderedNos = heads.Select(h => h.StoRearCBNo).Distinct().OrderBy(x => x, StringComparer.Ordinal).ToList();
    var myCount = orderedNos.Count;
    var pageNos = orderedNos.Skip(start).Take(count).ToList();
    var idx = pageNos.Select((no, i) => new { no, i }).ToDictionary(x => x.no, x => x.i);
    heads = heads.Where(h => idx.ContainsKey(h.StoRearCBNo)).OrderBy(h => idx[h.StoRearCBNo]).ToList();
    var pageIds = heads.Select(h => h.Id).ToHashSet();
    dtls = dtls.Where(x => pageIds.Contains(x.StoRearCBId)).ToList();

    var items = heads.Select(h => new
    {
        srcStoRearCBNo = h.StoRearCBNo, srcRearCBStatus = h.RearCBStatus, srcCreatedDate = h.CreatedDate,
        srcCreatedBy = h.CreatedBy, srcApprovedBy = h.ApprovedBy, srcApprovedDate = h.ApprovedDate, srcRemark = h.Remark,
        details = dtls.Where(d => d.StoRearCBId == h.Id)
            .Select(d => new { d.VIN, d.SpecCode, d.EngineNo, d.RearCBDtlStatus }).ToList()
    }).ToList();

    return Results.Ok(new
    {
        myCount, recordStart = start, recordCount = count, count = items.Count, items,
        pagingRule = "Cung khuon voi /api/stocbreqs/search: MyIdxSeq tren distinct so lenh, MyCount dem TRUOC khi cat trang, tra ve theo MyIdxSeq asc."
    });
}).RequireAuthorization();
app.MapGet("/api/vins/search", async (
    AppDbContext db, ITenantContext t,
    string? vin, string? specCode, string? modelCode, string? colorCode, string? dealerCode,
    string? packingListNo, string? buPattern, string? enforceBuScope,
    int? recordStart, int? recordCount) =>
{
    var start = recordStart ?? 0;
    var count = recordCount ?? 200;
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();

    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId).ToListAsync();
    string? U(string? s) => string.IsNullOrWhiteSpace(s) ? null : s.Trim().ToUpperInvariant();
    var fVin = U(vin);
    if (fVin is not null) cars = cars.Where(c => c.VIN.ToUpperInvariant().Contains(fVin)).ToList();
    if (!string.IsNullOrWhiteSpace(specCode)) { var set = specCode.Split(',').Select(s => s.Trim()).ToHashSet(); cars = cars.Where(c => set.Contains(c.SpecCode ?? "")).ToList(); }
    if (!string.IsNullOrWhiteSpace(modelCode)) { var set = modelCode.Split(',').Select(s => s.Trim()).ToHashSet(); cars = cars.Where(c => set.Contains(c.ModelCode ?? "")).ToList(); }
    if (!string.IsNullOrWhiteSpace(colorCode)) { var set = colorCode.Split(',').Select(s => s.Trim()).ToHashSet(); cars = cars.Where(c => set.Contains(c.ColorCode ?? "")).ToList(); }
    if (!string.IsNullOrWhiteSpace(dealerCode)) { var set = dealerCode.Split(',').Select(s => s.Trim().ToUpperInvariant()).ToHashSet(); cars = cars.Where(c => set.Contains(c.DealerCode ?? "")).ToList(); }
    if (!string.IsNullOrWhiteSpace(packingListNo)) { var k = packingListNo.Trim().ToUpperInvariant(); cars = cars.Where(c => (c.PackingListNo ?? "").ToUpperInvariant().Contains(k)).ToList(); }

    var vinSet = cars.Select(c => c.VIN).ToHashSet();

    // `#tblmaxDlv`: biên bản giao **MỚI NHẤT theo mã** (max chuỗi `DlvMnNo`) của từng VIN.
    var dlvRows = await (from d in db.TranspDlvConfirmCars.Where(x => x.OrgId == t.OrgId && vinSet.Contains(x.VIN))
                         join h in db.TranspDlvConfirms.Where(x => x.OrgId == t.OrgId) on d.TranspDlvConfirmId equals h.Id
                         select new { d.VIN, h.DlvMinutesNo, h.FDlvMnStatus, h.TDlvMnStatus, d.DlvStartDate, h.DlvEndDate }).ToListAsync();
    var maxDlv = dlvRows.GroupBy(x => x.VIN)
        .ToDictionary(g => g.Key, g => g.OrderByDescending(x => x.DlvMinutesNo, StringComparer.Ordinal).First());

    // `src_RearCBStatus`: bản ghi đóng thùng **mới nhất theo `CreatedDate`**.
    var rearCb = await (from d in db.StoRearCBDtls.Where(x => x.OrgId == t.OrgId && vinSet.Contains(x.VIN))
                        join h in db.StoRearCBs.Where(x => x.OrgId == t.OrgId) on d.StoRearCBId equals h.Id
                        select new { d.VIN, h.RearCBStatus, h.CreatedDate }).ToListAsync();
    var lastRearCb = rearCb.GroupBy(x => x.VIN)
        .ToDictionary(g => g.Key, g => g.OrderByDescending(x => x.CreatedDate).First().RearCBStatus);

    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId).Select(d => new { d.DealerCode, d.BUCode }).ToListAsync();
    bool InScope(string? dc)
    {
        if (pattern is null) return true;
        var dl = dealers.FirstOrDefault(z => z.DealerCode == dc);
        return dl is not null && (dl.BUCode ?? "").ToUpperInvariant().StartsWith(pattern);
    }
    var outOfScopeCount = cars.Count(c => !InScope(c.DealerCode));
    if (enforceBuScope == "1") cars = cars.Where(c => InScope(c.DealerCode)).ToList();

    cars = cars.OrderBy(c => c.VIN, StringComparer.Ordinal).ToList();
    var myCount = cars.Count;
    var now = DateTime.Now;
    var items = cars.Skip(start).Take(count).Select(c =>
    {
        maxDlv.TryGetValue(c.VIN, out var dlv);
        // `FlagIsOnWay`: 'A' + 'P' + (DlvEndDate null hoặc > getdate()).
        var onWay = dlv is not null
                    && dlv.FDlvMnStatus == "A" && dlv.TDlvMnStatus == "P"
                    && (dlv.DlvEndDate is null || dlv.DlvEndDate > now) ? "Y" : "N";
        // `COYear`: rỗng/null ⇒ null; ngược lại **4 ký tự đầu** của chuỗi ngày + "-01-01".
        string? coYear = c.CODate is null ? null
            : c.CODate.Value.ToString("yyyy-MM-dd").Substring(0, 4) + "-01" + "-01";
        return new
        {
            cvVIN = c.VIN, cvModelCode = c.ModelCode, cvSpecCode = c.SpecCode, cvColorCode = c.ColorCode,
            // #B80 §12 — bốn cột cờ/VIN-đã-ghép của `CarCarUpdate02_New20260409`.
            ccFlagMapVIN = c.FlagMapVIN, ccFlagCarDeliveryOrder = c.FlagCarDeliveryOrder,
            ccFlagTestCar = c.FlagTestCar, ccMappedVin = c.MappedVin,
            cvActualSpec = c.ActualSpec, cvEngineNo = c.EngineNo, cvKeyNo = c.KeyNo,
            cvStorageCodeCurrent = c.StorageCodeCurrent, cvPackingListNo = c.PackingListNo,
            cvCODate = c.CODate, ccDealerCode = c.DealerCode, ccCarCancelRemark = c.CarCancelRemark,
            flagIsOnWay = onWay,
            dlvMnNo = dlv?.DlvMinutesNo, fDlvMnStatus = dlv?.FDlvMnStatus, tDlvMnStatus = dlv?.TDlvMnStatus,
            srcRearCBStatus = lastRearCb.TryGetValue(c.VIN, out var rs) ? rs : null,
            coYear,
            total = 1.0m                              // cột `TOTAL` hằng 1.0 của nguồn
        };
    }).ToList();

    return Results.Ok(new
    {
        myCount, recordStart = start, recordCount = count, count = items.Count, items,
        flagIsOnWayRule = "FDlvMnStatus='A' VA TDlvMnStatus='P' VA (DlvEndDate is null HOAC > getdate()) => 'Y'; xet tren bien ban MOI NHAT theo max(DlvMnNo) (max CHUOI ma, khong phai theo ngay).",
        rearCbRule = "src_RearCBStatus = top 1 RearCBStatus order by Sto_RearrangeCB.CreatedDate desc.",
        coYearRule = "COYear = Convert(varchar(4), CODate) + '-01' + '-01' — nguon cat 4 KY TU DAU cua chuoi ngay, KHONG dung year().",
        outOfScopeCount, buScopeEnforced = enforceBuScope == "1",
        rbacQuirk = "@strBUPatternOfUser khai bao nhung KHONG DUNG trong SQL nguon - ca thu SAU lien tiep.",
        debt = "NO co nhan: cac left join lam giau (CT_TKHQ / CT_PackingList / CT_LC / Mst_CarSpec / Mst_CarModel) chua port day du."
    });
}).RequireAuthorization();
app.MapGet("/api/vins/for-tcg-invoice-adj", async (
    AppDbContext db, ITenantContext t,
    string? vin, string? drListCode, DateTime? drCreatedFrom, DateTime? drCreatedTo,
    DateTime? invoiceDateFrom, DateTime? invoiceDateTo, string? docRequestType,
    string? dealerCode, string? flagisHTC, int? recordStart, int? recordCount) =>
{
    var start = recordStart ?? 0;
    var count = recordCount ?? 200;

    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId).ToListAsync();
    if (!string.IsNullOrWhiteSpace(vin))
    { var k = vin.Trim().ToUpperInvariant(); cars = cars.Where(c => c.VIN.ToUpperInvariant().Contains(k)).ToList(); }
    // `Car_Car.DealerCode` dùng **"in"** (danh sách), không phải "=".
    if (!string.IsNullOrWhiteSpace(dealerCode))
    { var set = dealerCode.Split(',').Select(s => s.Trim().ToUpperInvariant()).ToHashSet(); cars = cars.Where(c => set.Contains(c.DealerCode ?? "")).ToList(); }
    // 🔴 `FlagisHTC` — vế thứ nhất, trên `Car_VIN`.
    if (!string.IsNullOrWhiteSpace(flagisHTC))
    { var k = flagisHTC.Trim(); cars = cars.Where(c => c.FlagisHTC == k).ToList(); }

    var vinSet = cars.Select(c => c.VIN).ToHashSet();

    // `VAT_TCGInvoiceDetail.TCGStatusDetail in ('F')` + đầu hoá đơn.
    var invDtls = await db.VatTcgInvoiceDetails
        .Where(d => d.OrgId == t.OrgId && vinSet.Contains(d.VIN) && d.TCGStatusDetail == "F").ToListAsync();
    var invCodes = invDtls.Select(d => d.TCGInvoiceCode).Distinct().ToList();
    var invHeadsQ = db.VatTcgInvoices.Where(h => h.OrgId == t.OrgId && invCodes.Contains(h.TCGInvoiceCode));
    var invHeads = await invHeadsQ.ToListAsync();
    // 🔴 `FlagisHTC` — vế thứ hai, trên `VAT_TCGInvoice` (lọc thiếu vế này là nới lỏng).
    if (!string.IsNullOrWhiteSpace(flagisHTC))
    { var k = flagisHTC.Trim(); invHeads = invHeads.Where(h => h.FlagisHTC == k).ToList(); }
    if (invoiceDateFrom is not null) invHeads = invHeads.Where(h => h.TCGInvoiceDate >= invoiceDateFrom).ToList();
    if (invoiceDateTo is not null) invHeads = invHeads.Where(h => h.TCGInvoiceDate <= invoiceDateTo).ToList();
    var keptCodes = invHeads.Select(h => h.TCGInvoiceCode).ToHashSet();
    invDtls = invDtls.Where(d => keptCodes.Contains(d.TCGInvoiceCode)).ToList();

    // Bộ lọc theo ĐỀ NGHỊ GIẤY TỜ (`Car_DocReqList`): DRListCode LIKE · CreatedDate khoảng · TypeCRR "in".
    var needDocReq = !string.IsNullOrWhiteSpace(drListCode) || drCreatedFrom is not null
                     || drCreatedTo is not null || !string.IsNullOrWhiteSpace(docRequestType);
    HashSet<string>? docReqVins = null;
    if (needDocReq)
    {
        var heads = await db.CarDocRequests.Where(r => r.OrgId == t.OrgId).ToListAsync();
        if (!string.IsNullOrWhiteSpace(drListCode))
        { var k = drListCode.Trim().ToUpperInvariant(); heads = heads.Where(r => r.RequestNo.ToUpperInvariant().Contains(k)).ToList(); }
        if (drCreatedFrom is not null) heads = heads.Where(r => r.CreatedAt >= drCreatedFrom).ToList();
        if (drCreatedTo is not null) heads = heads.Where(r => r.CreatedAt <= drCreatedTo).ToList();
        if (!string.IsNullOrWhiteSpace(docRequestType))
        { var set = docRequestType.Split(',').Select(s => s.Trim().ToUpperInvariant()).ToHashSet(); heads = heads.Where(r => set.Contains(r.TypeCRR.ToUpperInvariant())).ToList(); }
        var ids = heads.Select(r => r.Id).ToList();
        docReqVins = (await db.CarDocRequestCars.Where(c => c.OrgId == t.OrgId && ids.Contains(c.RequestId))
            .Select(c => c.CarId).ToListAsync()).ToHashSet();
    }

    var rows = invDtls
        .Where(d => docReqVins is null || docReqVins.Contains(d.VIN))
        .Select(d =>
        {
            var cv = cars.First(c => c.VIN == d.VIN);
            var h = invHeads.First(x => x.TCGInvoiceCode == d.TCGInvoiceCode);
            return new
            {
                cvVIN = cv.VIN, cvModelCode = cv.ModelCode, cvSpecCode = cv.SpecCode, cvColorCode = cv.ColorCode,
                cvFlagisHTC = cv.FlagisHTC, ccDealerCode = cv.DealerCode, ccUnitPriceActual = cv.UnitPriceActual,
                vtiTCGInvoiceCode = h.TCGInvoiceCode, vtiTCGInvoiceDate = h.TCGInvoiceDate, vtiFlagisHTC = h.FlagisHTC,
                vtidTCGUnitPrice = d.TCGUnitPrice, vtidTCGStatusDetail = d.TCGStatusDetail
            };
        })
        .OrderBy(x => x.cvVIN, StringComparer.Ordinal).ToList();

    var myCount = rows.Count;
    var items = rows.Skip(start).Take(count).ToList();
    return Results.Ok(new
    {
        myCount, recordStart = start, recordCount = count, count = items.Count, items,
        overloadTrap = "SalesService co HAI overload SearchVinForTCGInvoice: :14985 bi comment TOAN BO (~20 tham so), :15538 CON SONG (10 tham so). Form goi ban 10 tham so - phai doi chieu CHU KY, dung ket luan 'man chet' tu ban bi comment.",
        flagisHtcRule = "FlagisHTC loc tren CA HAI bang: Car_VIN va VAT_TCGInvoice - thieu mot ve la NOI LONG bo loc.",
        notPorted = "Dieu kien '(Car_VIN.TCGUnitPrice - VAT_TCGInvoiceDetail.TCGUnitPrice) > 0' da bi REM o nguon (:15593) - khong port.",
        filterShapes = "LIKE: VIN, DRListCode · 'in': DealerCode, TypeCRR, TCGStatusDetail('F') · '=': FlagisHTC · khoang: DR.CreatedDate, TCGInvoiceDate"
    });
}).RequireAuthorization();
app.MapGet("/api/vins/for-rearcb-trans-req", async (
    AppDbContext db, ITenantContext t,
    string? vin, string? specCode, string? modelCode, string? colorCode,
    string? stoRearCBNo, string? buPattern, string? enforceBuScope,
    int? recordStart, int? recordCount) =>
{
    var start = recordStart ?? 0;
    var count = recordCount ?? 200;
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();

    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId).ToListAsync();
    string? U(string? s) => string.IsNullOrWhiteSpace(s) ? null : s.Trim().ToUpperInvariant();
    var fVin = U(vin);
    if (fVin is not null) cars = cars.Where(c => c.VIN.ToUpperInvariant().Contains(fVin)).ToList();
    if (!string.IsNullOrWhiteSpace(specCode)) { var set = specCode.Split(',').Select(s => s.Trim()).ToHashSet(); cars = cars.Where(c => set.Contains(c.SpecCode ?? "")).ToList(); }
    if (!string.IsNullOrWhiteSpace(modelCode)) { var set = modelCode.Split(',').Select(s => s.Trim()).ToHashSet(); cars = cars.Where(c => set.Contains(c.ModelCode ?? "")).ToList(); }
    if (!string.IsNullOrWhiteSpace(colorCode)) { var set = colorCode.Split(',').Select(s => s.Trim()).ToHashSet(); cars = cars.Where(c => set.Contains(c.ColorCode ?? "")).ToList(); }

    var vinSet = cars.Select(c => c.VIN).ToHashSet();
    // ĐIỀU KIỆN LÕI: phải có dòng lệnh đóng thùng đang **"A"** (không phải "A2" như luồng nội bộ).
    var rear = await (from d in db.StoRearCBDtls.Where(x => x.OrgId == t.OrgId && vinSet.Contains(x.VIN) && x.RearCBDtlStatus == "A")
                      join h in db.StoRearCBs.Where(x => x.OrgId == t.OrgId) on d.StoRearCBId equals h.Id
                      select new { d.VIN, h.StoRearCBNo, d.RearCBDtlStatus }).ToListAsync();
    rear = rear.Where(x => !string.IsNullOrEmpty(x.StoRearCBNo)).ToList();          // `is not null`
    if (!string.IsNullOrWhiteSpace(stoRearCBNo))
    { var k = stoRearCBNo.Trim().ToUpperInvariant(); rear = rear.Where(x => (x.StoRearCBNo ?? "").ToUpperInvariant().Contains(k)).ToList(); }

    var packingLists = await db.PackingLists.Where(p => p.OrgId == t.OrgId).Select(p => new { p.PLNo, p.LcNo, p.PortCode }).ToListAsync();
    var tkhqs = await db.CtTkhqs.Where(k => k.OrgId == t.OrgId).Select(k => new { k.DeclarationNo, k.OpenDate }).ToListAsync();

    var joined = rear.Select(r =>
    {
        var cv = cars.First(c => c.VIN == r.VIN);
        var pl = packingLists.FirstOrDefault(p => p.PLNo == cv.PackingListNo);
        var kq = tkhqs.FirstOrDefault(k => k.DeclarationNo == cv.DeclarationNo);
        return new
        {
            cvVIN = cv.VIN, cvModelCode = cv.ModelCode, cvSpecCode = cv.SpecCode, cvColorCode = cv.ColorCode,
            cvActualSpec = cv.ActualSpec, cvEngineNo = cv.EngineNo, cvStorageCodeCurrent = cv.StorageCodeCurrent,
            cvPackingListNo = cv.PackingListNo, ctplLCNo = pl?.LcNo, ctplPortCode = pl?.PortCode,
            cttDeclarationNo = kq?.DeclarationNo, cttOpenDate = kq?.OpenDate,
            ccDealerCode = cv.DealerCode, cvTypeCB = cv.TypeCB, cvLoaiThung = cv.LoaiThung,
            ssrdStoRearCBNo = r.StoRearCBNo, ssrdRearCBDtlStatus = r.RearCBDtlStatus
        };
    }).ToList();

    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId).Select(d => new { d.DealerCode, d.BUCode }).ToListAsync();
    bool InScope(string? dc)
    {
        if (pattern is null) return true;
        var dl = dealers.FirstOrDefault(z => z.DealerCode == dc);
        return dl is not null && (dl.BUCode ?? "").ToUpperInvariant().StartsWith(pattern);
    }
    var outOfScopeCount = joined.Count(x => !InScope(x.ccDealerCode));
    if (enforceBuScope == "1") joined = joined.Where(x => InScope(x.ccDealerCode)).ToList();

    joined = joined.OrderBy(x => x.cvVIN, StringComparer.Ordinal).ToList();
    var myCount = joined.Count;
    var items = joined.Skip(start).Take(count).ToList();

    return Results.Ok(new
    {
        myCount, recordStart = start, recordCount = count, count = items.Count, items,
        coreRule = "StoRearCBNo is not null VÀ RearCBDtlStatus in ('A').",
        siblingDiff = "KHÁC #B47 (YCVT nội bộ) vốn đòi RearrangeDtlStatus in ('A2') — hai luồng anh em CỐ Ý khác trạng thái tiền đề, không được đồng bộ hoá.",
        joinNote = "Nguồn viết left join nhưng where có 'is not null' ⇒ INNER JOIN thực chất.",
        outOfScopeCount, buScopeEnforced = enforceBuScope == "1",
        rbacQuirk = "@strBUPatternOfUser khai bao nhung KHONG DUNG trong SQL nguon - ca thu NAM lien tiep (#B45/#B46/#B47/#B48/#B50)."
    });
}).RequireAuthorization();
app.MapGet("/api/vins/for-rear-trans-req", async (
    AppDbContext db, ITenantContext t,
    string? vin, string? specCode, string? modelCode, string? colorCode,
    string? storageRearrangeNo, string? buPattern, string? enforceBuScope,
    int? recordStart, int? recordCount) =>
{
    var start = recordStart ?? 0;
    var count = recordCount ?? 200;
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();

    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId).ToListAsync();
    string? U(string? s) => string.IsNullOrWhiteSpace(s) ? null : s.Trim().ToUpperInvariant();
    var fVin = U(vin);
    if (fVin is not null) cars = cars.Where(c => c.VIN.ToUpperInvariant().Contains(fVin)).ToList();
    if (!string.IsNullOrWhiteSpace(specCode)) { var set = specCode.Split(',').Select(s => s.Trim()).ToHashSet(); cars = cars.Where(c => set.Contains(c.SpecCode ?? "")).ToList(); }
    if (!string.IsNullOrWhiteSpace(modelCode)) { var set = modelCode.Split(',').Select(s => s.Trim()).ToHashSet(); cars = cars.Where(c => set.Contains(c.ModelCode ?? "")).ToList(); }
    if (!string.IsNullOrWhiteSpace(colorCode)) { var set = colorCode.Split(',').Select(s => s.Trim()).ToHashSet(); cars = cars.Where(c => set.Contains(c.ColorCode ?? "")).ToList(); }

    var vinSet = cars.Select(c => c.VIN).ToHashSet();
    // ĐIỀU KIỆN LÕI: phải có dòng lệnh điều chuyển đang "A2" (left join + is not null = inner join).
    var rear = await (from d in db.StorageRearrangeDetails.Where(x => x.OrgId == t.OrgId && vinSet.Contains(x.VIN) && x.RearrangeDtlStatus == "A2")
                      join h in db.StorageRearranges.Where(x => x.OrgId == t.OrgId) on d.StorageRearrangeId equals h.Id
                      select new { d.VIN, StorageRearrangeNo = h.SCNo, d.RearrangeDtlStatus }).ToListAsync();
    if (!string.IsNullOrWhiteSpace(storageRearrangeNo))
    { var k = storageRearrangeNo.Trim().ToUpperInvariant(); rear = rear.Where(x => (x.StorageRearrangeNo ?? "").ToUpperInvariant().Contains(k)).ToList(); }
    rear = rear.Where(x => !string.IsNullOrEmpty(x.StorageRearrangeNo)).ToList();   // `is not null`

    var packingLists = await db.PackingLists.Where(p => p.OrgId == t.OrgId).Select(p => new { p.PLNo, p.LcNo, p.PortCode }).ToListAsync();

    var joined = rear.Select(r =>
    {
        var cv = cars.First(c => c.VIN == r.VIN);
        var pl = packingLists.FirstOrDefault(p => p.PLNo == cv.PackingListNo);
        return new
        {
            cvVIN = cv.VIN, cvModelCode = cv.ModelCode, cvSpecCode = cv.SpecCode, cvColorCode = cv.ColorCode,
            cvActualSpec = cv.ActualSpec, cvStorageCodeCurrent = cv.StorageCodeCurrent,
            cvPackingListNo = cv.PackingListNo, ctplLCNo = pl?.LcNo, ctplPortCode = pl?.PortCode,
            ccDealerCode = cv.DealerCode,
            ssrdStorageRearrangeNo = r.StorageRearrangeNo, ssrdRearrangeDtlStatus = r.RearrangeDtlStatus
        };
    }).ToList();

    // Phạm vi BU — nguồn KHÔNG dùng `@strBUPatternOfUser`: đo được, chỉ lọc khi bật cờ.
    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId).Select(d => new { d.DealerCode, d.BUCode }).ToListAsync();
    bool InScope(string? dealerCode)
    {
        if (pattern is null) return true;
        var dl = dealers.FirstOrDefault(z => z.DealerCode == dealerCode);
        return dl is not null && (dl.BUCode ?? "").ToUpperInvariant().StartsWith(pattern);
    }
    var outOfScopeCount = joined.Count(x => !InScope(x.ccDealerCode));
    if (enforceBuScope == "1") joined = joined.Where(x => InScope(x.ccDealerCode)).ToList();

    // `order by cv.VIN`; `MyCount` đếm trên bảng CUỐI (sau mọi điều kiện).
    joined = joined.OrderBy(x => x.cvVIN, StringComparer.Ordinal).ToList();
    var myCount = joined.Count;
    var items = joined.Skip(start).Take(count).ToList();

    return Results.Ok(new
    {
        myCount, recordStart = start, recordCount = count, count = items.Count, items,
        coreRule = "Chỉ tạo YCVT Nội bộ cho Lệnh điều chuyển A2 (chú thích nguồn 20170425): RearrangeDtlStatus in ('A2') + StorageRearrangeNo is not null.",
        joinNote = "Nguồn viết left join nhưng where có 'is not null' ⇒ INNER JOIN thực chất — xe không có lệnh điều chuyển A2 thì KHÔNG ra.",
        outOfScopeCount, buScopeEnforced = enforceBuScope == "1",
        rbacQuirk = "@strBUPatternOfUser khai bao nhung KHONG DUNG trong SQL nguon (ca thu ba lien tiep: #B45, #B46, #B47) => man khong loc pham vi BU. CAN NGHIEP VU/BAO MAT CHOT."
    });
}).RequireAuthorization();
app.MapGet("/api/vins/for-insurance-req", async (
    AppDbContext db, ITenantContext t,
    string? vin, string? specCode, string? modelCode, string? colorCode, string? carId,
    string? refOrdType, string? refOrdNo, DateTime? createdDateLimit,
    string? buPattern, string? enforceBuScope, int? recordStart, int? recordCount) =>
{
    var start = recordStart ?? 0;
    var count = recordCount ?? 200;
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();

    // `#tbl_Car_VIN_Filter` — lọc trên `Car_VIN` (+ `left join Car_Car`, MiniHTC gộp một bảng).
    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId).ToListAsync();
    string? U(string? s) => string.IsNullOrWhiteSpace(s) ? null : s.Trim().ToUpperInvariant();
    var fVin = U(vin); var fCar = U(carId);
    if (fVin is not null) cars = cars.Where(c => c.VIN.ToUpperInvariant().Contains(fVin)).ToList();
    if (fCar is not null) cars = cars.Where(c => c.VIN.ToUpperInvariant().Contains(fCar)).ToList();
    if (!string.IsNullOrWhiteSpace(specCode)) { var set = specCode.Split(',').Select(s => s.Trim()).ToHashSet(); cars = cars.Where(c => set.Contains(c.SpecCode ?? "")).ToList(); }
    if (!string.IsNullOrWhiteSpace(modelCode)) { var set = modelCode.Split(',').Select(s => s.Trim()).ToHashSet(); cars = cars.Where(c => set.Contains(c.ModelCode ?? "")).ToList(); }
    if (!string.IsNullOrWhiteSpace(colorCode)) { var set = colorCode.Split(',').Select(s => s.Trim()).ToHashSet(); cars = cars.Where(c => set.Contains(c.ColorCode ?? "")).ToList(); }

    var vinSet = cars.Select(c => c.VIN).ToHashSet();
    var ordNo = U(refOrdNo);
    bool MatchNo(string? no) => ordNo is null || (no ?? "").ToUpperInvariant().Contains(ordNo);
    // Điều kiện `CreatedDate >= @CreatedDateLimit` KHÔNG áp trừ khi người gọi truyền mốc thật (lỗi 1).
    bool AfterLimit(DateTime? created) => createdDateLimit is null || (created is not null && created >= createdDateLimit);

    var rows = new List<InsReqVinRow>();
    var want = U(refOrdType);

    // 1) CARTRANSPORT — lệnh xuất xe.
    if (want is null || want == "CARTRANSPORT")
    {
        var q = await (from d in db.DeliveryOrderCars.Where(x => x.OrgId == t.OrgId && vinSet.Contains(x.Vin) && x.ConfirmStatus != "R" && x.ConfirmStatus != "C")
                       join h in db.DeliveryOrders.Where(x => x.OrgId == t.OrgId && x.Status != "R" && x.Status != "C") on d.DoId equals h.Id
                       select new { d.Vin, RefOrdNo = h.DoNo, DtlStatus = d.ConfirmStatus, h.CreatedAt, d.StorageCode }).ToListAsync();
        rows.AddRange(q.Where(x => MatchNo(x.RefOrdNo) && AfterLimit(x.CreatedAt))
            .Select(x => new InsReqVinRow(x.Vin, "CARTRANSPORT", x.RefOrdNo, x.DtlStatus, x.CreatedAt, null, x.StorageCode)));
    }
    // 2) CARRETRIEVE — thu hồi xe.
    if (want is null || want == "CARRETRIEVE")
    {
        var q = await db.CarRetrieves.Where(x => x.OrgId == t.OrgId && vinSet.Contains(x.Vin)
                    && x.RetrieveDtlStatus != "R" && x.RetrieveDtlStatus != "C")
            .Select(x => new { x.Vin, x.RetrieveOrderNo, x.RetrieveDtlStatus, x.DealerCode }).ToListAsync();
        rows.AddRange(q.Where(x => MatchNo(x.RetrieveOrderNo))
            .Select(x => new InsReqVinRow(x.Vin, "CARRETRIEVE", x.RetrieveOrderNo, x.RetrieveDtlStatus, null, x.DealerCode, null)));
    }
    // 3) STORAGEREARRANGE — điều chuyển nội bộ.
    if (want is null || want == "STORAGEREARRANGE")
    {
        var q = await (from d in db.StorageRearrangeDetails.Where(x => x.OrgId == t.OrgId && vinSet.Contains(x.VIN) && x.RearrangeDtlStatus != "R" && x.RearrangeDtlStatus != "C")
                       join h in db.StorageRearranges.Where(x => x.OrgId == t.OrgId) on d.StorageRearrangeId equals h.Id
                       select new { d.VIN, StorageRearrangeNo = h.SCNo, d.RearrangeDtlStatus }).ToListAsync();
        rows.AddRange(q.Where(x => MatchNo(x.StorageRearrangeNo))
            .Select(x => new InsReqVinRow(x.VIN, "STORAGEREARRANGE", x.StorageRearrangeNo, x.RearrangeDtlStatus, null, null, null)));
    }
    // 4) STORAGEREARRCB — điều chuyển đóng thùng.
    if (want is null || want == "STORAGEREARRCB")
    {
        var q = await (from d in db.StoRearCBDtls.Where(x => x.OrgId == t.OrgId && vinSet.Contains(x.VIN) && x.RearCBDtlStatus != "R" && x.RearCBDtlStatus != "C")
                       join h in db.StoRearCBs.Where(x => x.OrgId == t.OrgId) on d.StoRearCBId equals h.Id
                       select new { d.VIN, h.StoRearCBNo, d.RearCBDtlStatus }).ToListAsync();
        rows.AddRange(q.Where(x => MatchNo(x.StoRearCBNo))
            .Select(x => new InsReqVinRow(x.VIN, "STORAGEREARRCB", x.StoRearCBNo, x.RearCBDtlStatus, null, null, null)));
    }

    // Phạm vi BU: nguồn KHÔNG dùng `@strBUPatternOfUser` (lỗi 2) — đo được, chỉ lọc khi bật cờ.
    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId).Select(d => new { d.DealerCode, d.BUCode }).ToListAsync();
    var carDealer = cars.ToDictionary(c => c.VIN, c => c.DealerCode);
    bool InScope(string v)
    {
        if (pattern is null) return true;
        var dc = carDealer.TryGetValue(v, out var x) ? x : null;
        var dl = dealers.FirstOrDefault(z => z.DealerCode == dc);
        return dl is not null && (dl.BUCode ?? "").ToUpperInvariant().StartsWith(pattern);
    }
    var outOfScopeCount = rows.Count(r => !InScope(r.Vin));
    if (enforceBuScope == "1") rows = rows.Where(r => InScope(r.Vin)).ToList();

    var myCount = rows.Count;
    var items = rows.Skip(start).Take(count).ToList();
    return Results.Ok(new
    {
        myCount, recordStart = start, recordCount = count, count = items.Count, items,
        refOrdTypes = new[] { "CARTRANSPORT", "CARRETRIEVE", "STORAGEREARRANGE", "STORAGEREARRCB" },
        outOfScopeCount, buScopeEnforced = enforceBuScope == "1",
        sourceBugs = new[]
        {
            "@CreatedDateLimit KHONG BAO GIO duoc thay o nguon (khong Replace, khong trong param list, lai boc nhay don) => 4 khoi chung tu hong/tra rong. Port BO dieu kien; truyen createdDateLimit de ap moc that.",
            "@strBUPatternOfUser khai bao nhung KHONG DUNG trong SQL => nguon khong loc pham vi BU. Port do bang outOfScopeCount, bat loc bang enforceBuScope=1.",
            "Client SalesService.cs:14541 go thua '@': RetrieveOrderNo like '%@<so>%' => tim theo so chung tu khong bao gio ra LENH THU HOI. Port theo y dinh (bo '@')."
        }
    });
}).RequireAuthorization();
app.MapGet("/api/docreqs/search-tcg", async (
    AppDbContext db, ITenantContext t,
    string? drTcgListCode, string? drTcgListStatus, DateTime? createdFrom, DateTime? createdTo,
    string? carId, string? vin, string? drTcgDtlStatus,
    string? buPattern, string? enforceBuScope, int? recordStart, int? recordCount) =>
{
    var start = recordStart ?? 0;
    var count = recordCount ?? 200;
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();

    // Luồng TCG nằm cùng bảng với ĐNGT thường, phân biệt bằng `TypeCRR` (nợ mô hình đã ghi ở #B40).
    var heads = await db.DocReqs.Where(x => x.OrgId == t.OrgId && x.TypeCRR == "DEALERTCG").ToListAsync();
    if (!string.IsNullOrWhiteSpace(drTcgListCode))
    { var k = drTcgListCode.Trim().ToUpperInvariant(); heads = heads.Where(h => h.DocReqNo.ToUpperInvariant().Contains(k)).ToList(); }
    if (!string.IsNullOrWhiteSpace(drTcgListStatus))
    { var set = drTcgListStatus.Split(',').Select(s => s.Trim()).Where(s => s.Length > 0).ToHashSet(); heads = heads.Where(h => set.Contains(h.Status)).ToList(); }
    if (createdFrom is not null) heads = heads.Where(h => h.CreatedAt >= createdFrom).ToList();
    if (createdTo is not null) heads = heads.Where(h => h.CreatedAt <= createdTo).ToList();

    var headIds = heads.Select(h => h.Id).ToList();
    var dtls = await db.DocReqCars.Where(x => x.OrgId == t.OrgId && headIds.Contains(x.DocReqId)).ToListAsync();
    if (!string.IsNullOrWhiteSpace(vin))
    { var k = vin.Trim().ToUpperInvariant(); dtls = dtls.Where(x => x.Vin.ToUpperInvariant().Contains(k)).ToList(); }
    if (!string.IsNullOrWhiteSpace(drTcgDtlStatus)) dtls = dtls.Where(x => x.DRDtlStatus == drTcgDtlStatus.Trim()).ToList();

    // `inner join Car_VIN` — VIN chưa khai bị LOẠI.
    var vinKeys = dtls.Select(x => x.Vin).Distinct().ToList();
    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && vinKeys.Contains(c.VIN)).ToListAsync();
    var known = cars.Select(c => c.VIN).ToHashSet();
    var droppedNoCarVin = dtls.Count(x => !known.Contains(x.Vin));
    dtls = dtls.Where(x => known.Contains(x.Vin)).ToList();
    if (!string.IsNullOrWhiteSpace(carId))
    { var k = carId.Trim().ToUpperInvariant(); dtls = dtls.Where(x => x.Vin.ToUpperInvariant().Contains(k)).ToList(); }

    // Phạm vi BU: nguồn dùng LEFT JOIN ⇒ **không loại**. Đo số dòng lẽ ra bị loại; chỉ lọc khi bật cờ.
    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId).Select(d => new { d.DealerCode, d.BUCode }).ToListAsync();
    bool InScope(string? dealerCode)
    {
        if (pattern is null) return true;
        var dl = dealers.FirstOrDefault(x => x.DealerCode == dealerCode);
        return dl is not null && (dl.BUCode ?? "").ToUpperInvariant().StartsWith(pattern);
    }
    var carDealer = cars.ToDictionary(c => c.VIN, c => c.DealerCode);
    var outOfScopeCount = dtls.Count(x => !InScope(carDealer.TryGetValue(x.Vin, out var dc) ? dc : null));
    if (enforceBuScope == "1")
        dtls = dtls.Where(x => InScope(carDealer.TryGetValue(x.Vin, out var dc) ? dc : null)).ToList();

    // Phân trang trên `distinct DRTCGListCode`, `order by DRTCGListCode`; MyCount đếm TRƯỚC khi cắt.
    var keptHeadIds = dtls.Select(x => x.DocReqId).ToHashSet();
    heads = heads.Where(h => keptHeadIds.Contains(h.Id)).ToList();
    var orderedNos = heads.Select(h => h.DocReqNo).Distinct().OrderBy(x => x, StringComparer.Ordinal).ToList();
    var myCount = orderedNos.Count;
    var pageNos = orderedNos.Skip(start).Take(count).ToHashSet();
    heads = heads.Where(h => pageNos.Contains(h.DocReqNo)).ToList();
    var pageIds = heads.Select(h => h.Id).ToHashSet();
    dtls = dtls.Where(x => pageIds.Contains(x.DocReqId)).ToList();

    var items = dtls.Select(x =>
    {
        var h = heads.First(z => z.Id == x.DocReqId);
        var cv = cars.First(c => c.VIN == x.Vin);
        return new
        {
            drTcgListCode = h.DocReqNo, drTcgListStatus = h.Status, cdrtcglCreatedDate = h.CreatedAt,
            cdrtcgdVIN = x.Vin, drTcgDtlStatus = x.DRDtlStatus,
            x.CancelDate, x.CancelBy, x.Remark, x.ApprovedDate1, x.ApprovedBy1, x.ApprovedDate2, x.ApprovedBy2,
            cvModelCode = cv.ModelCode, cvSpecCode = cv.SpecCode, cvColorCode = cv.ColorCode,
            ccDealerCode = cv.DealerCode
        };
    }).ToList();

    return Results.Ok(new
    {
        myCount, recordStart = start, recordCount = count, count = items.Count, items,
        droppedNoCarVin,
        outOfScopeCount, buScopeEnforced = enforceBuScope == "1",
        rbacQuirk = "Nguồn dùng LEFT JOIN Mst_Dealer nhưng chú thích ghi 'Must inner join to filter AbilityOfUser' ⇒ phạm vi BU KHÔNG lọc được. Port giữ đúng nguồn; bật enforceBuScope=1 để lọc theo ý định trong chú thích. CẦN NGHIỆP VỤ CHỐT.",
        filterShapes = "LIKE: DRTCGListCode/VIN/CarId · 'in': DRTCGListStatus · '=': DRTCGDtlStatus · khoảng: CreatedDate",
        joinNote = "inner join Car_VIN ⇒ VIN chưa khai bị LOẠI; điều kiện ConfirmStatus not in ('R','C') nằm TRONG mệnh đề on, không loại cả xe."
    });
}).RequireAuthorization();
app.MapPost("/api/docreqs/{no}/cars/delete-tcg", async (string no, CdrCancelDto dto,
    AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    // `..._TableDetailBeBlank`
    var vins = (dto.Vins ?? new()).Where(v => !string.IsNullOrWhiteSpace(v))
        .Select(v => v.Trim().ToUpperInvariant()).ToList();
    if (vins.Count == 0) return Results.BadRequest(new { error = "Chưa chọn xe nào để xoá.", guard = "Car_DocReqTCGDtlDelete_ByDealer_TableDetailBeBlank" });
    // `..._DuplicateKeyDetail`
    var dup = vins.GroupBy(v => v).FirstOrDefault(g => g.Count() > 1);
    if (dup != null) return Results.BadRequest(new { error = $"VIN {dup.Key} bị trùng trong danh sách!", guard = "Car_DocReqTCGDtlDelete_ByDealer_DuplicateKeyDetail" });
    vins = vins.Distinct().ToList();

    var d = await db.DocReqs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DocReqNo == no);
    if (d is null) return Results.NotFound(new { no });
    // `myCar_CheckCar_DocReqTCGList(…, Flag.Active, Stage.Pending)` — theo CODE là "P", không phải "C".
    if (d.Status != "P")
        return Results.BadRequest(new
        {
            error = $"Đề nghị TCG đang ở '{d.Status}' — chỉ xoá được khi đang chờ duyệt 'P'.",
            guard = "myCar_CheckCar_DocReqTCGList(Stage.Pending)",
            sourceQuirk = "Chú thích nguồn viết 'chỉ xóa Đề nghị ở trạng thái C' nhưng THAM SỐ thực là Stage.Pending — port theo CODE."
        });

    var lines = await db.DocReqCars.Where(x => x.OrgId == t.OrgId && x.DocReqId == d.Id && vins.Contains(x.Vin)).ToListAsync();
    foreach (var vin in vins)
    {
        // `myCar_CheckCar_DocReqTCGDtl(…, Flag.Active, Stage.Pending)`
        var line = lines.FirstOrDefault(x => x.Vin == vin);
        if (line is null) return Results.BadRequest(new { error = $"Xe {vin} không nằm trong đề nghị {no}." });
        if (line.DRDtlStatus != "P")
            return Results.BadRequest(new { error = $"Xe {vin} đang ở '{line.DRDtlStatus}' — luồng TCG chỉ xoá được dòng đang 'P'.", note = "Khác luồng thường: ở đó phải HUỶ về 'C' trước rồi mới xoá (#B31)." });
    }

    db.DocReqCars.RemoveRange(lines);
    await db.SaveChangesAsync();

    // "Kỹ thuật lọc ngược": hết dòng thì xoá luôn đầu đề nghị.
    var remain = await db.DocReqCars.CountAsync(x => x.OrgId == t.OrgId && x.DocReqId == d.Id);
    var headerDeleted = false;
    string? headerStatusNew = null;
    if (remain == 0) { db.DocReqs.Remove(d); await db.SaveChangesAsync(); headerDeleted = true; }
    else
    {
        // `SetStatusCar_DocReqTCGList_New20181119(…)` tại `:85481` — cùng hàm rollup của #B40.
        var allDtl = await db.DocReqCars.Where(x => x.OrgId == t.OrgId && x.DocReqId == d.Id)
            .Select(x => x.DRDtlStatus).ToListAsync();
        headerStatusNew = RollupDocReqTcgListStatus(allDtl);
        if (headerStatusNew is not null) { d.Status = headerStatusNew; await db.SaveChangesAsync(); }
    }

    return Results.Ok(new
    {
        requestNo = no, deleted = vins.Count, vins, remainingCars = remain, headerDeleted,
        headerStatus = headerDeleted ? null : d.Status, headerStatusChanged = headerStatusNew is not null,
        rbacNote = "myCommon_CheckHTCDirect ở nguồn BỊ COMMENT — không port (lệnh ByDealer).",
        headerDeleteRule = "Nguồn xoá luôn Car_DocReqTCGList khi không còn Car_DocReqTCGDtl tương ứng."
    });
}).RequireAuthorization();
app.MapPost("/api/docreqs/{no}/edit-support", async (string no, DocReqSupportDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var d = await db.DocReqs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DocReqNo == no);
    if (d is null) return Results.NotFound(new { no });
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.Vin)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu được thay đổi" });
    int updated = 0; var notFound = new List<string>();
    foreach (var r in rows)
    {
        var vin = r.Vin!.Trim().ToUpperInvariant();
        var c = await db.DocReqCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DocReqId == d.Id && x.Vin == vin);
        if (c is null) { notFound.Add(vin); continue; }
        c.LetterRepresentationDate = r.LetterRepresentationDate; c.LetterRepresentationNo = r.LetterRepresentationNo; c.LoanSupportDay = r.LoanSupportDay;
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// 🔴 DUYỆT CẤP 1 ở HEADER — `CarDocReqApprove1_New20181119` (Biz.HTC.WH.cs:82296-82380). Vào từ "P".
//    ⚠️ Luật rẽ nhánh theo LOẠI ĐỀ NGHỊ: `TypeCRR == "NORMAL"` ⇒ **nhảy thẳng "A2"** và ghi luôn
//    ApprovedDate2/By2 (đề nghị thường duyệt một lần là xong); loại khác chỉ lên "A1", còn phải
//    duyệt cấp 2 **theo TỪNG XE**. Port cũ có submit/complete phẳng — mất hẳn nhánh này.
app.MapPost("/api/docreqs/{no}/approve1", async (string no, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var d = await db.DocReqs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DocReqNo == no);
    if (d is null) return Results.NotFound(new { no });
    if (d.Status != "P") return Results.BadRequest(new { error = "Chỉ duyệt cấp 1 đề nghị đang chờ duyệt (P)." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    d.ApprovedDate1 = now; d.ApprovedBy1 = who;
    if (string.Equals(d.TypeCRR, "NORMAL", StringComparison.OrdinalIgnoreCase))
    { d.Status = "A2"; d.ApprovedDate2 = now; d.ApprovedBy2 = who; }
    else d.Status = "A1";
    // Dòng đi theo header ở bước này (nguồn duyệt cấp 2 vào từ "A1" của DÒNG).
    foreach (var c in await db.DocReqCars.Where(x => x.OrgId == t.OrgId && x.DocReqId == d.Id && x.DRDtlStatus == "P").ToListAsync())
        c.DRDtlStatus = d.Status;
    await db.SaveChangesAsync();
    return Results.Ok(new { d.DocReqNo, status = d.Status, d.TypeCRR, oneStep = d.Status == "A2" });
}).RequireAuthorization();

// 🔴 HUỶ CẢ ĐỀ NGHỊ — `CarDocReqListCancel_New20181119` (Biz.HTC.WH.cs:84912-85170).
// Khác hẳn huỷ từng xe: chỉ vào từ **"P"** (đề nghị chưa duyệt), và **lan trạng thái "C" xuống MỌI dòng**.
app.MapPost("/api/docreqs/{no}/cancel", async (string no, DocReqCarActionDto? dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var d = await db.DocReqs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DocReqNo == no);
    if (d is null) return Results.NotFound(new { no });
    if (d.Status != "P") return Results.BadRequest(new { error = "Chỉ huỷ được đề nghị đang chờ duyệt (P)." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";

    // 🔴 RBAC theo NGƯỜI TẠO, không theo đại lý ghi trên đề nghị: nguồn lấy `CreatedBy` → đại lý của
    //    người đó → `myCommon_CheckAccessDealerData(BUPattern, BUCode)`. Nguyên văn comment nguồn:
    //    "Đại lý được Hủy đề nghị do Đại lý tạo ra. Không được hủy đề nghị do HTC tạo hộ".
    //    ⚠️ MiniHTC chưa có tầng BUPattern/ability ⇒ tạm kiểm bằng chính người tạo; đã ghi nợ RBAC.
    if (!string.IsNullOrWhiteSpace(d.CreatedBy) && !string.Equals(d.CreatedBy, who, StringComparison.OrdinalIgnoreCase))
        return Results.BadRequest(new { error = $"Đề nghị do '{d.CreatedBy}' tạo — bạn không huỷ được đề nghị người khác tạo hộ." });

    var cars = await db.DocReqCars.Where(x => x.OrgId == t.OrgId && x.DocReqId == d.Id).ToListAsync();
    var vins = cars.Select(x => x.Vin).ToList();

    // Huỷ đề nghị NORMAL thì phải huỷ đề nghị SPECIAL của cùng xe TRƯỚC (nguồn kiểm từng VIN).
    if (string.Equals(d.TypeCRR, "NORMAL", StringComparison.OrdinalIgnoreCase))
    {
        var specialIds = db.DocReqs.Where(x => x.OrgId == t.OrgId && x.TypeCRR == "SPECIAL" && x.Id != d.Id).Select(x => x.Id);
        var blocked = await db.DocReqCars.Where(x => x.OrgId == t.OrgId && vins.Contains(x.Vin) && specialIds.Contains(x.DocReqId))
            .Select(x => x.Vin).FirstOrDefaultAsync();
        if (blocked != null)
            return Results.BadRequest(new { error = $"Xe {blocked} còn đề nghị loại đặc biệt — phải huỷ đề nghị đặc biệt trước." });
    }
    // Guard hạ nguồn: đề nghị giải chấp (ReqDMNo) và đề nghị hoá đơn (ReqIVNo).
    var dm = await db.RedeemRequestLines.Where(x => x.OrgId == t.OrgId && vins.Contains(x.VIN!)).Select(x => x.VIN).FirstOrDefaultAsync();
    if (dm != null) return Results.BadRequest(new { error = $"Xe {dm} đã có đề nghị giải chấp — không huỷ được đề nghị hồ sơ." });
    var iv = await db.RedeemInvoiceRequestLines.Where(x => x.OrgId == t.OrgId && vins.Contains(x.VIN!)).Select(x => x.VIN).FirstOrDefaultAsync();
    if (iv != null) return Results.BadRequest(new { error = $"Xe {iv} đã có đề nghị hoá đơn — không huỷ được đề nghị hồ sơ." });

    var now = DateTime.Now;
    d.Status = "C"; d.CancelDate = now; d.CancelBy = who;
    // Nguồn lan xuống MỌI dòng bằng một câu update (không lọc theo trạng thái dòng).
    // #B45 SS12 - ghi luon CancelDate/CancelBy cho DONG (nguon Car_DocReqTCGDtl co hai cot nay)
    foreach (var c in cars) { c.DRDtlStatus = "C"; c.CancelDate = now; c.CancelBy = who; }

    // Nguồn gửi email thông báo khi đề nghị do ĐẠI LÝ tạo (`TypeCRR == DEALER`) — nhánh dễ bị bỏ sót.
    var mailed = false;
    if (string.Equals(d.TypeCRR, "DEALER", StringComparison.OrdinalIgnoreCase))
    {
        db.EmailSends.Add(new EmailSend
        {
            OrgId = t.OrgId,
            BatchNo = "DRCANCEL" + now.ToString("yyMMddHHmmss"),
            Email = "",
            EmailType = "DOCREQ_CANCEL",
            Subject = $"Huỷ đề nghị giấy tờ {d.DocReqNo}",
            Body = $"Đề nghị {d.DocReqNo} (đại lý {d.DealerCode}, {cars.Count} xe) đã bị huỷ bởi {who}." + (dto?.Remark is null ? "" : $" Lý do: {dto.Remark}"),
            DealerCode = d.DealerCode,
            Status = "0",   // hàng đợi — đúng cờ nguồn, chưa gửi
        });
        mailed = true;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { d.DocReqNo, status = d.Status, statusName = "Huỷ", carsCancelled = cars.Count, mailQueued = mailed });
}).RequireAuthorization();

// 🔴 DUYỆT CẤP 2 / TỪ CHỐI / HUỶ — nguồn thao tác theo **TỪNG XE**, không theo cả đề nghị:
//    `CarDocReqDtlApprove2_New20181119` (82492) · `CarDocReqDtlReject_New20181119` (83426) ·
//    `CarDocReqDtlCancel_New20210223` (82986).
//    ⚠️ TWIN: WS 32-bit gọi bản Cancel `_New20181119`, còn **`TERP.WSHTC.64` gọi `_New20210223`**
//    (bản 64-bit là bản CI/CD đang chạy) ⇒ port theo `_New20210223`.
app.MapPost("/api/docreqs/{no}/cars/{vin}/{action}", async (string no, string vin, string action, DocReqCarActionDto? dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (action is not ("approve2" or "reject" or "cancel"))
        return Results.BadRequest(new { error = "action = approve2|reject|cancel" });
    no = no.Trim().ToUpperInvariant(); vin = vin.Trim().ToUpperInvariant();
    var d = await db.DocReqs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DocReqNo == no);
    if (d is null) return Results.NotFound(new { no });
    var c = await db.DocReqCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DocReqId == d.Id && x.Vin == vin);
    if (c is null) return Results.NotFound(new { no, vin });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;

    if (action == "approve2")
    {
        // 🔴 Luồng TCG dùng hàm RIÊNG `CarDocReqTCGDtlApprove2_New20181119` (Biz.HTC.WH.cs:82847-82931):
        //    vào từ **"P"** (không phải "A1") rồi lên thẳng "A2", và ghi **CẢ BỐN** cột duyệt cùng lúc —
        //    duyệt một lần là qua cả hai cấp.
        //    ⚠️ Nợ cấu trúc: nguồn để luồng TCG ở **bảng RIÊNG** `Car_DocReqTCGList`/`Car_DocReqTCGDtl`
        //    (cột trạng thái `DRTCGDtlStatus`), MiniHTC đang gộp chung và phân biệt bằng `TypeCRR`.
        if (string.Equals(d.TypeCRR, "DEALERTCG", StringComparison.OrdinalIgnoreCase))
        {
            if (c.DRDtlStatus != "P") return Results.BadRequest(new { error = $"Xe {vin} (luồng TCG) phải đang chờ duyệt (P)." });
            c.DRDtlStatus = "A2";
            c.ApprovedDate1 = now; c.ApprovedBy1 = who; c.ApprovedDate2 = now; c.ApprovedBy2 = who;
            await db.SaveChangesAsync();

            // ===== #B40 GAP — SIDE-EFFECT `SetStatusCar_DocReqTCGList_New20181119` (`Biz.HTC.WH.cs:82627`) =====
            // Nguồn gọi ngay sau khi ghi dòng (`:82936`) để **TÍNH LẠI trạng thái ĐẦU đề nghị** từ trạng thái
            // của TẤT CẢ các dòng. Port cũ thiếu hẳn ⇒ đầu đề nghị **đứng nguyên trạng thái cũ mãi mãi**,
            // dù mọi dòng đã duyệt xong. Chuỗi `if / else if` — **nhánh đầu khớp là dừng**, đúng thứ tự:
            //   1. có **BẤT KỲ** dòng "A1"            → "A1"   (một dòng A1 thắng tất cả)
            //   2. `countF + countC == countAll && countF > 0` → "F"
            //   3. `countC == countAll`               → "C"
            //   4. `countP == countAll`               → "P"
            //   5. `countA2 == countAll`              → "A2"
            //   6. `countAll == countF + countA2`     → "A2"
            //   7. `else`                             → **KHÔNG LÀM GÌ** (thân đã bị comment sạch ở nguồn)
            var allDtl = await db.DocReqCars.Where(x => x.OrgId == t.OrgId && x.DocReqId == d.Id)
                .Select(x => x.DRDtlStatus).ToListAsync();
            var headerStatusNew = RollupDocReqTcgListStatus(allDtl);
            if (headerStatusNew is not null) { d.Status = headerStatusNew; await db.SaveChangesAsync(); }
            return Results.Ok(new
            {
                no, vin, status = c.DRDtlStatus, statusName = "Duyệt cấp 2 (TCG, một bước)",
                headerStatus = d.Status, headerStatusChanged = headerStatusNew is not null,
                rollupRule = "SetStatusCar_DocReqTCGList: A1 nếu có bất kỳ dòng A1; F nếu F+C=All và F>0; C nếu toàn C; P nếu toàn P; A2 nếu toàn A2 hoặc F+A2=All; else GIỮ NGUYÊN."
            });
        }
        // Nguồn: `strRequestStatusListToCheck = Stage.Approved1` ⇒ CHỈ từ "A1".
        if (c.DRDtlStatus != "A1") return Results.BadRequest(new { error = $"Xe {vin} phải ở trạng thái duyệt cấp 1 (A1)." });
        c.DRDtlStatus = "A2"; c.ApprovedDate2 = now; c.ApprovedBy2 = who;
        await db.SaveChangesAsync();
        return Results.Ok(new { no, vin, status = c.DRDtlStatus, statusName = "Duyệt cấp 2" });
    }

    // Hai nhánh còn lại đều yêu cầu HEADER thuộc "P,A1,A2,F" (nguồn guard cả hai tầng).
    if (d.Status is not ("P" or "A1" or "A2" or "F"))
        return Results.BadRequest(new { error = $"Đề nghị đang ở trạng thái '{d.Status}' — không thao tác được." });

    if (action == "reject")
    {
        // 🔴 Nguồn cho từ chối CHỈ từ "A2" — tức là **từ chối SAU khi đã duyệt cấp 2**, không phải trước.
        if (c.DRDtlStatus != "A2") return Results.BadRequest(new { error = $"Xe {vin} chỉ từ chối được sau khi đã duyệt cấp 2 (A2)." });
        c.DRDtlStatus = "R"; c.RejectDate = now; c.RejectBy = who; c.Remark = dto?.Remark;
        await db.SaveChangesAsync();
        return Results.Ok(new { no, vin, status = c.DRDtlStatus, statusName = "Từ chối" });
    }

    // cancel: dòng phải thuộc "A1,A2" + 3 ràng buộc hạ nguồn của nguồn.
    if (c.DRDtlStatus is not ("A1" or "A2"))
        return Results.BadRequest(new { error = $"Xe {vin} chỉ huỷ được khi đang ở A1 hoặc A2." });
    // (1) Đã phát hành hoá đơn HTC hoặc TCG cho xe ⇒ cấm huỷ.
    if (await db.InvoiceLines.AnyAsync(x => x.OrgId == t.OrgId && x.Vin == vin))
        return Results.BadRequest(new { error = $"Xe {vin} đã có hoá đơn — không huỷ được đề nghị hồ sơ." });
    // (2) Đã có đề nghị giải chấp (`ReqDMNo`) ⇒ cấm.
    if (await db.RedeemRequestLines.AnyAsync(x => x.OrgId == t.OrgId && x.VIN == vin))
        return Results.BadRequest(new { error = $"Xe {vin} đã có đề nghị giải chấp — không huỷ được." });
    // (3) Xe đang nằm trong một đề nghị loại SPECIAL khác ⇒ cấm.
    var specialIds = db.DocReqs.Where(x => x.OrgId == t.OrgId && x.TypeCRR == "SPECIAL" && x.Id != d.Id).Select(x => x.Id);
    if (await db.DocReqCars.AnyAsync(x => x.OrgId == t.OrgId && x.Vin == vin && specialIds.Contains(x.DocReqId)))
        return Results.BadRequest(new { error = $"Xe {vin} đang thuộc một đề nghị loại đặc biệt khác — không huỷ được." });
    c.DRDtlStatus = "C"; c.Remark = dto?.Remark; c.CancelDate = DateTime.Now; c.CancelBy = user.Identity?.Name ?? "system";   // #B45 SS12
    await db.SaveChangesAsync();
    return Results.Ok(new { no, vin, status = c.DRDtlStatus, statusName = "Huỷ" });}).RequireAuthorization();

// ===== Thiết lập hóa đơn theo model (InvoiceSetup — port 1:1 FrmMst_InvoiceSetup, 2010.HTC/Admin/Product) =====
app.MapGet("/api/invoicesetups", async (AppDbContext db, ITenantContext t, string? active, string? model) =>
{
    var q = db.InvoiceSetups.Where(s => s.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(active)) q = q.Where(s => s.FlagActive == active);
    if (!string.IsNullOrWhiteSpace(model)) q = q.Where(s => s.ModelCode == model);
    var items = await q.OrderByDescending(s => s.Id).Take(500).Select(s => new { s.ModelCode, s.FlagInvoiceHTMV, s.FlagInvoiceTCG, s.FlagActive, s.LogLUDateTime, s.LogLUBy }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/invoicesetups", async (InvoiceSetupDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.ModelCode)) return Results.BadRequest(new { error = "Chưa nhập model." });
    var md = dto.ModelCode.Trim().ToUpperInvariant();
    var ex = await db.InvoiceSetups.FirstOrDefaultAsync(s => s.OrgId == t.OrgId && s.ModelCode == md);
    if (ex is not null) { ex.FlagInvoiceHTMV = dto.FlagInvoiceHTMV == "1" ? "1" : "0"; ex.FlagInvoiceTCG = dto.FlagInvoiceTCG == "1" ? "1" : "0"; ex.FlagActive = "1"; await db.SaveChangesAsync(); return Results.Ok(new { ex.ModelCode, updated = true }); }
    var s2 = new InvoiceSetup { OrgId = t.OrgId, ModelCode = md, FlagInvoiceHTMV = dto.FlagInvoiceHTMV == "1" ? "1" : "0", FlagInvoiceTCG = dto.FlagInvoiceTCG == "1" ? "1" : "0", FlagActive = "1" };
    db.InvoiceSetups.Add(s2); await db.SaveChangesAsync();
    return Results.Ok(new { s2.ModelCode, updated = false });
}).RequireAuthorization();

// ===== #185 THIẾT LẬP HOÁ ĐƠN theo model — cụm `Mst_InvoiceSetup_*` =====
// Nguồn: `TERP.BizHTC/DataWH/Biz.HTC.WH.cs` (csproj 272) — `_CreateMulti` (206588), `_Update` (207257).
// BƯỚC 3B: hàm `_Update` bắt đầu **KHÁC DÒNG** (laptop 207257 / máy 150 207262) — căn theo MỐC HÀM
//   (luật #156), vùng 160 dòng md5 `5cdaec42` KHỚP. Đã liệt kê ranh giới hàm: 207257 → 207415.
// 🔴 TWIN: cụm này **CHỈ có ở WS 64-bit** (`_CreateMulti` · `_Get` · `_Update`); WS 32-bit **không có hàm nào**.
//
// 🔴 Cách tìm ra: danh sách 36 hàm field-mask (#184). Đây là hàm thứ BA được port.
//    Port cũ chỉ có POST upsert đơn — **ghi CẢ HAI cờ mỗi lần gọi**, tức rộng hơn nguồn.
//
// 🔴 `_CreateMulti` — tạo HÀNG LOẠT, ba guard mỗi dòng:
//    · `Mst_InvoiceSetup_CheckDB(..., Flag.No)` — model **CHƯA có** thiết lập (chặn trùng);
//    · `Mst_CarModel_CheckDB_New20210604(..., Flag.Yes)` — model phải TỒN TẠI trong master xe;
//    · hai cờ phải là **đúng "0" hoặc "1"**, rỗng cũng là lỗi
//      (`CreateMulti_InvalidFlagInvoiceHTMV` / `_InvalidFlagInvoiceTCG`).
//      ⚠️ Port cũ dùng `dto.X == "1" ? "1" : "0"` ⇒ **nuốt mọi giá trị rác thành "0"** thay vì báo lỗi.
app.MapPost("/api/invoicesetups/create-multi", async (InvoiceSetupMultiDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var rows = (dto.Items ?? new()).Where(x => !string.IsNullOrWhiteSpace(x.ModelCode)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Chưa có dòng thiết lập nào." });   // CreateMulti_TableBlank
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var built = new List<InvoiceSetup>();
    foreach (var r in rows)
    {
        var md = r.ModelCode!.Trim().ToUpperInvariant();
        if (await db.InvoiceSetups.AnyAsync(s => s.OrgId == t.OrgId && s.ModelCode == md))
            return Results.BadRequest(new { error = $"Model {md} đã có thiết lập hoá đơn.", modelCode = md });
        if (!await db.CarModelStds.AnyAsync(m => m.OrgId == t.OrgId && m.ModelCode == md))
            return Results.BadRequest(new { error = $"Model {md} không tồn tại trong danh mục xe.", modelCode = md });
        // Hai cờ PHẢI là "0" hoặc "1" — rỗng/giá trị lạ đều là LỖI, không tự quy về "0".
        if (r.FlagInvoiceHTMV is not ("0" or "1"))
            return Results.BadRequest(new { error = $"Model {md}: cờ hoá đơn HTMV phải là \"0\" hoặc \"1\".", modelCode = md });
        if (r.FlagInvoiceTCG is not ("0" or "1"))
            return Results.BadRequest(new { error = $"Model {md}: cờ hoá đơn TCG phải là \"0\" hoặc \"1\".", modelCode = md });
        built.Add(new InvoiceSetup { OrgId = t.OrgId, ModelCode = md,
            FlagInvoiceHTMV = r.FlagInvoiceHTMV!, FlagInvoiceTCG = r.FlagInvoiceTCG!,
            FlagActive = "1", CreatedAt = now, LogLUDateTime = now, LogLUBy = who });
    }
    db.InvoiceSetups.AddRange(built);
    await db.SaveChangesAsync();
    return Results.Ok(new { created = built.Count, models = built.Select(x => x.ModelCode) });
}).RequireAuthorization();

// 🔴 `_Update` (207257) — FIELD-MASK hai cờ:
//    `bUpd_FlagInvoiceHTMV = mask.Contains("Mst_InvoiceSetup.FlagInvoiceHTMV".ToUpper())`
//    `bUpd_FlagInvoiceTCG  = mask.Contains("Mst_InvoiceSetup.FlagInvoiceTCG".ToUpper())`
//    Chỉ cờ có trong mask mới được ghi; `LogLUDateTime`/`LogLUBy` **luôn** ghi.
//    Guard duy nhất: `Mst_InvoiceSetup_CheckDB(..., Flag.Yes)` — bản ghi phải tồn tại.
//    ⚠️ **KHÔNG có guard theo cột** ở lệnh này (khác #184) — mask chỉ chọn cột, không kéo theo kiểm tra.
// ⚠️ LỆCH CÓ CHỦ ĐÍCH: nguồn ghi `LogLUDateTime` với format **"yyyyMMddHH:mm:ss"** (thiếu dấu gạch/khoảng
//    trắng) — toàn hệ dùng "yyyy-MM-dd HH:mm:ss" ở **671** chỗ, format kia chỉ **10** chỗ ⇒ lỗi gõ của nguồn,
//    không phải quy ước. Ghi mốc bằng `DateTime` chuẩn (luật `C0-ducentesimustricesimussecundus`).
app.MapPost("/api/invoicesetups/{model}/update", async (string model, InvoiceSetupUpdateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    model = model.Trim().ToUpperInvariant();
    var s = await db.InvoiceSetups.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ModelCode == model);
    if (s is null) return Results.NotFound(new { model });

    var mask = (dto.FtColsUpd ?? "").ToUpperInvariant();
    var updHTMV = mask.Contains("MST_INVOICESETUP.FLAGINVOICEHTMV");
    var updTCG = mask.Contains("MST_INVOICESETUP.FLAGINVOICETCG");

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    if (updHTMV) s.FlagInvoiceHTMV = (dto.FlagInvoiceHTMV ?? "").Trim();
    if (updTCG) s.FlagInvoiceTCG = (dto.FlagInvoiceTCG ?? "").Trim();
    s.LogLUDateTime = DateTime.Now; s.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { s.ModelCode, updatedHTMV = updHTMV, updatedTCG = updTCG,
        s.FlagInvoiceHTMV, s.FlagInvoiceTCG, s.LogLUDateTime, s.LogLUBy });
}).RequireAuthorization();

app.MapPost("/api/invoicesetups/{model}/toggle", async (string model, AppDbContext db, ITenantContext t) =>
{
    model = model.Trim().ToUpperInvariant();
    var s = await db.InvoiceSetups.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ModelCode == model);
    if (s is null) return Results.NotFound(new { model });
    s.FlagActive = s.FlagActive == "1" ? "0" : "1";
    await db.SaveChangesAsync();
    return Results.Ok(new { s.ModelCode, flagActive = s.FlagActive });
}).RequireAuthorization();

// ===== Ngưỡng tồn kho bán hàng (SalesInventoryThreshold — port 1:1 FrmMstSalesInventoryThreshold, 2010.HTC/Admin/Product) =====
