// Ký kép: ĐL ký (dealer) + HTC ký (htc); đủ 2 chữ ký -> Approved (Đã ký).
app.MapPost("/api/banktms/{no}/sign/{side}", async (string no, string side, AppDbContext db, ITenantContext t) =>
{
    if (side is not ("dealer" or "htc")) return Results.BadRequest(new { error = "side = dealer|htc" });
    no = no.Trim().ToUpperInvariant();
    var m = await db.BankTransportMinutes.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TransportMinutesNo == no);
    if (m is null) return Results.NotFound(new { no });
    if (m.Status == "Cancel") return Results.BadRequest(new { error = "Biên bản đã hủy." });
    if (m.Status == "Approved") return Results.BadRequest(new { error = "Biên bản đã ký đủ." });
    if (side == "dealer")
    {
        if (m.DLApprDateTime != null) return Results.BadRequest(new { error = "Đại lý đã ký." });
        m.DLApprDateTime = DateTime.Now;
    }
    else
    {
        if (m.HTCAppr2DateTime != null) return Results.BadRequest(new { error = "HTC đã ký." });
        m.HTCAppr2DateTime = DateTime.Now;
    }
    if (m.DLApprDateTime != null && m.HTCAppr2DateTime != null) m.Status = "Approved";
    await db.SaveChangesAsync();
    return Results.Ok(new { m.TransportMinutesNo, m.Status, dlSigned = m.DLApprDateTime != null, htcSigned = m.HTCAppr2DateTime != null });
}).RequireAuthorization();

app.MapPost("/api/banktms/{no}/cancel", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.BankTransportMinutes.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TransportMinutesNo == no);
    if (m is null) return Results.NotFound(new { no });
    if (m.Status == "Approved") return Results.BadRequest(new { error = "Không thể hủy biên bản đã ký đủ." });
    m.Status = "Cancel";
    await db.SaveChangesAsync();
    return Results.Ok(new { m.TransportMinutesNo, m.Status });
}).RequireAuthorization();

// ===== Phiếu thanh toán ngân hàng (BankPayment — port 1:1 FrmMngPM, cụm Bank) =====
// ===== 🔴 #203 HỢP NHẤT `/api/bankpms` về đúng bảng nguồn `Pmt_Payment` =====
// Tiếp nợ #202 (đã ghi CÓ DANH SÁCH). Đối chiếu nguồn xong:
//  · `PaymentPaymentCreate_New20191202` (BankIntergration/BizHTC.MBBank.cs:446-460) ghi `Pmt_PaymentDetail`
//    đúng **5 cột**: `PaymentNo` · `CarId` · `GuaranteeNo` · `DlrCtrNo` · `Amount`. Không hơn.
//  · 11 cột "thừa" của `BankPaymentCar` KHÔNG thuộc bảng chi tiết mà là **dữ liệu DẪN XUẤT / của bảng khác**:
//    `AmountAccum` = `Sum(pmpd_Accum.Amount)` trong báo cáo (DataWH/Biz.HTC.WH.My.cs:1871);
//    `UnitPriceActual` là cột của `Car_Car` (`cc.UnitPriceActual`); VIN/ModelCode/SpecCode/ColorCode lấy bằng
//    JOIN `Car_Car`→`Car_VIN`. Port cũ đã **lưu cứng dữ liệu dẫn xuất vào bảng chi tiết**.
//  ⇒ `PmtPayment`/`PmtPaymentDetail` (#155) là bản ĐÚNG; cụm này chuyển sang dùng chúng.
//    `BankPayment`/`BankPaymentCar` trở thành entity CHẾT (giữ class để không phá dữ liệu cũ).
app.MapGet("/api/bankpms", async (AppDbContext db, ITenantContext t, string? dealer, string? pmNo, string? status) =>
{
    var q = db.PmtPayments.Where(p => p.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(p => p.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(pmNo)) q = q.Where(p => p.PaymentNo.Contains(pmNo!) || (p.BankPaymentNo != null && p.BankPaymentNo.Contains(pmNo!)));
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(p => p.PaymentStatus == status);
    var items = await q.OrderByDescending(p => p.Id).Take(500).Select(p => new
    {
        p.PaymentNo, p.BankPaymentNo, p.DealerCode, p.BankCodeSend, p.BankCodeReceive, p.Funds, p.TotalAmount,
        p.PaymentStatus, p.AccountingRecordNo, p.CreatedDate, p.ApprovedDate, p.InterestRate, p.LoanPeriod,
        cars = db.PmtPaymentDetails.Count(c => c.OrgId == t.OrgId && c.PaymentNo == p.PaymentNo)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/bankpms", async (BankPmDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Chưa chọn đại lý." });
    if (string.IsNullOrWhiteSpace(dto.BankCodeReceive)) return Results.BadRequest(new { error = "Chưa chọn ngân hàng nhận." });
    var cars = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.VIN)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "Chưa có xe trên phiếu thanh toán." });
    var dupe = cars.GroupBy(c => c.VIN.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });
    var no = "PTT" + DateTime.Now.ToString("yyMMddHHmmss");
    var p2 = new PmtPayment
    {
        OrgId = t.OrgId, PaymentNo = no, BankPaymentNo = dto.BankPaymentNo, DealerCode = dto.DealerCode.Trim(),
        BankCodeSend = dto.BankCodeSend, BankCodeReceive = dto.BankCodeReceive.Trim(),
        BankAccountSend = dto.BankAccountSend, BankAccountReceive = dto.BankAccountReceive,
        Funds = dto.Funds, BankLending = dto.BankLending, Remark = dto.Remark,
        PaymentStatus = "P",                      // TConst.Stage.Pending
        TotalAmount = cars.Sum(c => c.AmountCurrent)
    };
    db.PmtPayments.Add(p2);
    foreach (var c in cars)
        // #203: chi tiết chỉ giữ ĐÚNG 5 cột của `Pmt_PaymentDetail`. Các trường VIN/ModelCode/SpecCode/
        //   ColorCode/SOCode/AmountAccum/PercentAccum/UnitPriceActual/PercentCurrent/BankGuaranteeNo mà DTO
        //   còn nhận là **dữ liệu dẫn xuất** — nguồn KHÔNG lưu ở đây, GET dựng lại bằng join (xem `/cars`).
        db.PmtPaymentDetails.Add(new PmtPaymentDetail
        {
            OrgId = t.OrgId, PaymentNo = no,
            CarId = string.IsNullOrWhiteSpace(c.CarId) ? c.VIN.Trim().ToUpperInvariant() : c.CarId!.Trim(),
            GuaranteeNo = c.GuaranteeNo, DlrCtrNo = c.DlrCtrNo, Amount = c.AmountCurrent
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { p2.PaymentNo, cars = cars.Count, totalAmount = p2.TotalAmount });
}).RequireAuthorization();

app.MapGet("/api/bankpms/{no}/cars", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var p = await db.PmtPayments.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PaymentNo == no);
    if (p is null) return Results.NotFound(new { no });
    // #203: 5 cột thật của `Pmt_PaymentDetail`; ModelCode/SpecCode lấy bằng JOIN đúng như nguồn
    //   (`Pmt_PaymentDetail.CarId` → `Car_Car` → `Car_VIN`), KHÔNG lưu cứng trong bảng chi tiết.
    var cars = await db.PmtPaymentDetails.Where(c => c.OrgId == t.OrgId && c.PaymentNo == no)
        .Select(c => new
        {
            c.CarId, c.GuaranteeNo, c.DlrCtrNo, c.Amount,
            vin       = db.CarVinMasters.Where(m => m.OrgId == t.OrgId && m.VIN == c.CarId).Select(m => m.VIN).FirstOrDefault(),
            modelCode = db.CarVinMasters.Where(m => m.OrgId == t.OrgId && m.VIN == c.CarId).Select(m => m.ModelCode).FirstOrDefault(),
            specCode  = db.CarVinMasters.Where(m => m.OrgId == t.OrgId && m.VIN == c.CarId).Select(m => m.SpecCode).FirstOrDefault()
        }).ToListAsync();
    return Results.Ok(new { p.PaymentNo, p.DealerCode, p.PaymentStatus, p.TotalAmount, p.AccountingRecordNo, count = cars.Count, cars });
}).RequireAuthorization();

// Duyệt phiếu TT: Draft -> Approved (gán số ghi sổ kế toán) / Rejected.
app.MapPost("/api/bankpms/{no}/{action}", async (string no, string action, string? accNo, AppDbContext db, ITenantContext t) =>
{
    if (action is not ("approve" or "reject")) return Results.BadRequest(new { error = "action = approve|reject" });
    no = no.Trim().ToUpperInvariant();
    var p = await db.PmtPayments.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PaymentNo == no);
    if (p is null) return Results.NotFound(new { no });
    // 🔴 #202 TỪ VỰNG: nguồn ghi `PaymentStatus` bằng `TConst.Stage` (P/A/R/C) — đã grep mọi chỗ gán
    //    `["PaymentStatus"] =` trong `TERP.BizHTC`: tất cả đều là `TConst.Stage.*`. Bộ Draft/Approved/Rejected
    //    của port cũ KHÔNG có ở nguồn ⇒ đổi + migration trong Seeder.
    //    Lệnh nguồn tương ứng có thật ở cổng WSHTC (cả 32 lẫn 64 bit):
    //    `PaymentPaymentApprove_Approve_New20210601` / `PaymentPaymentApprove_Reject_new20200130`.
    if (p.PaymentStatus != "P") return Results.BadRequest(new { error = "Phiếu thanh toán không ở trạng thái chờ duyệt.", current = p.PaymentStatus });
    if (action == "approve")
    {
        p.PaymentStatus = "A"; p.ApprovedDate = DateTime.Now;   // #203: tên cột đúng nguồn
        p.AccountingRecordNo = string.IsNullOrWhiteSpace(accNo) ? "GS" + DateTime.Now.ToString("yyMMddHHmmss") : accNo!.Trim();
    }
    else p.PaymentStatus = "R";
    await db.SaveChangesAsync();
    return Results.Ok(new { p.PaymentNo, p.PaymentStatus, p.AccountingRecordNo });
}).RequireAuthorization();

// Cập nhật số chứng từ kế toán trên phiếu TT (port 1:1 FrmUpdateChungTuKT, Sales/Payment) — ghi old->new.
app.MapPost("/api/bankpms/{no}/ctkt", async (string no, BankPmCtktDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var p = await db.PmtPayments.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PaymentNo == no);
    if (p is null) return Results.NotFound(new { no });
    if (string.IsNullOrWhiteSpace(dto.NewAccountingRecordNo)) return Results.BadRequest(new { error = "Chưa nhập số chứng từ kế toán mới." });
    if (p.PaymentStatus != "Approved") return Results.BadRequest(new { error = "Chỉ cập nhật chứng từ trên phiếu đã duyệt." });
    var oldNo = p.AccountingRecordNo;
    p.AccountingRecordNo = dto.NewAccountingRecordNo.Trim();
    await db.SaveChangesAsync();
    return Results.Ok(new { p.PaymentNo, oldAccountingRecordNo = oldNo, newAccountingRecordNo = p.AccountingRecordNo });
}).RequireAuthorization();

// Sửa lãi suất + kỳ hạn vay theo lô (port 1:1 FrmUpdate_Pmt_Payment, Sales/Payment) — guard: cả 2 bắt buộc + số; lãi suất 0-100; kỳ hạn > 0.
app.MapPost("/api/bankpms/interest-rate", async (BankPmInterestDto dto, AppDbContext db, ITenantContext t) =>
{
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.PaymentNo)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu được thay đổi" });
    foreach (var r in rows)
    {
        if (r.InterestRate is null || r.LoanPeriod is null)
            return Results.BadRequest(new { error = $"Cần nhập đủ thông tin lãi suất và kỳ hạn cho thanh toán {r.PaymentNo}!" });
        if (r.InterestRate < 0 || r.InterestRate > 100)
            return Results.BadRequest(new { error = $"Thông tin lãi suất của thanh toán {r.PaymentNo} phải lớn hơn bằng 0(>=0) và nhỏ hơn bằng 100(<=100)!" });
        if (r.LoanPeriod < 0)
            return Results.BadRequest(new { error = $"Thông tin kỳ hạn của thanh toán {r.PaymentNo} phải lớn hơn 0(>0)!" });
    }
    int updated = 0; var notFound = new List<string>();
    foreach (var r in rows)
    {
        var no = r.PaymentNo!.Trim().ToUpperInvariant();
        var p = await db.PmtPayments.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PaymentNo == no);
        if (p is null) { notFound.Add(no); continue; }
        p.InterestRate = r.InterestRate; p.LoanPeriod = r.LoanPeriod;
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// Sửa thanh toán — xác nhận ngày hết hạn TT + số ghi sổ theo lô (port 1:1 FrmEditPMPayEndDate, Sales/Payment; PmConfirmDateEnd).
// Import danh sách (PaymentNo, AccountingRecordNo, PaymentEndDate) -> cập nhật từng phiếu tìm theo PaymentNo; báo matched/notFound.
app.MapGet("/api/bankpms/enddate", async (AppDbContext db, ITenantContext t, string? q) =>
{
    var qry = db.PmtPayments.Where(p => p.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) qry = qry.Where(p => p.PaymentNo.Contains(q!) || p.AccountingRecordNo.Contains(q!));
    var items = await qry.OrderByDescending(p => p.Id).Take(500)
        .Select(p => new { p.PaymentNo, p.DealerCode, p.TotalAmount, p.PaymentStatus, p.AccountingRecordNo, p.PaymentEndDate }).ToListAsync();
    return Results.Ok(new { count = items.Count, withEndDate = items.Count(x => x.PaymentEndDate != null), items });
}).RequireAuthorization();

app.MapPost("/api/bankpms/confirm-enddate", async (PmConfirmEndDateDto dto, AppDbContext db, ITenantContext t) =>
{
    var lines = (dto.Lines ?? new List<PmEndDateRowDto>()).Where(l => !string.IsNullOrWhiteSpace(l.PaymentNo)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Phải có ít nhất 1 dòng." });
    var nos = lines.Select(l => l.PaymentNo!.Trim().ToUpperInvariant()).ToHashSet();
    var rows = await db.PmtPayments.Where(p => p.OrgId == t.OrgId && nos.Contains(p.PaymentNo)).ToListAsync();
    var byNo = rows.ToDictionary(p => p.PaymentNo.ToUpperInvariant(), p => p);
    int matched = 0; var notFound = new List<string>();
    foreach (var l in lines)
    {
        var key = l.PaymentNo!.Trim().ToUpperInvariant();
        if (!byNo.TryGetValue(key, out var p)) { notFound.Add(l.PaymentNo!.Trim()); continue; }
        if (l.PaymentEndDate.HasValue) p.PaymentEndDate = l.PaymentEndDate;
        if (!string.IsNullOrWhiteSpace(l.AccountingRecordNo)) p.AccountingRecordNo = l.AccountingRecordNo!.Trim();
        matched++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { matched, notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// ===== Hóa đơn VAT HTC (VatInvoice — port 1:1 FrmMngInvoice, cụm Bank) =====
app.MapGet("/api/vatinvoices", async (AppDbContext db, ITenantContext t, string? dealer, string? invNo, string? status, string? adjType) =>
{
    var q = db.VatInvoices.Where(v => v.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(v => v.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(invNo)) q = q.Where(v => v.HTCInvoiceCode.Contains(invNo!) || v.HTCInvoiceNo.Contains(invNo!));
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(v => v.VatHTCStatus == status);
    if (adjType == "adj") q = q.Where(v => v.InvoiceAdjType != "");
    else if (adjType == "root") q = q.Where(v => v.InvoiceAdjType == "");
    var items = await q.OrderByDescending(v => v.Id).Take(500).Select(v => new
    {
        v.HTCInvoiceCode, v.HTCInvoiceNo, v.InvoiceIDCode, v.HTCInvoiceDate, v.VAT, v.DealerCode, v.BankCode, v.SourceInvoiceName, v.InvoiceAdjType, v.RootHTCInvoiceNo, v.OS_HDDT_InvoiceCode, v.VatHTCStatus, v.CreatedAt,
        v.ApprovedDate, v.ApprovedBy,
        v.OS_HDDT_RefNo, v.HddtSyncedAt, v.PaymentMethodCode, v.SourceInvoiceCode, v.RefNo,   // #195 §12
        v.ValGoodsNotTaxable, v.ValGoodsNotChargeTax, v.ValGoodsVAT5, v.ValVAT5, v.ValGoodsVAT10, v.ValVAT10,
        v.TotalValInvoice, v.TotalValVAT, v.TotalValPmt, v.CurrencyCode, v.CurrencyRate,
        cars = db.VatInvoiceCars.Count(c => c.OrgId == t.OrgId && c.VatInvoiceId == v.Id),
        totalPrice = db.VatInvoiceCars.Where(c => c.OrgId == t.OrgId && c.VatInvoiceId == v.Id).Sum(c => (decimal?)c.HTCUnitPrice) ?? 0
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/vatinvoices", async (VatInvoiceDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Chưa chọn đại lý." });
    if (string.IsNullOrWhiteSpace(dto.InvoiceIDCode)) return Results.BadRequest(new { error = "Chưa nhập ký hiệu hóa đơn." });
    var cars = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.VIN)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "Chưa có xe trên hóa đơn." });
    var dupe = cars.GroupBy(c => c.VIN.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });
    // ===== 🔴 #195 HOÁ ĐƠN THAY THẾ / ĐIỀU CHỈNH — `VAT_HTCInvoiceCreate_Special_New20190816` (8329) =====
    // Nguồn: `TERP.BizHTC/HDDTIntergration/BizHTC.HDDTIntergration.cs`, thư mục **`.Release.2025`**.
    // Hằng `TConst.SourceInvoiceCode` (Const.Main.cs:33): INVOICEROOT · INVOICEADJ · INVOICEREPLACE.
    //
    // 🔴 BƯỚC 3B (đính chính kết luận #194): laptop CÓ CẢ `.Release.20220125` LẪN `.Release.2025`.
    //    #194 trót so laptop`.20220125` với 150`.2025` — hai THƯ MỤC khác nhau, nên tưởng "file khác giữa 2 máy".
    //    Đo lại đúng cặp `.Release.2025` ↔ `.Release.2025`: vẫn KHÁC, nhưng chỉ **8 dòng** ở đúng khối này —
    //    laptop lưu `dt_VAT_HTCInvoice_RefNo` (hoá đơn GỐC), máy 150 lưu `dt_VAT_HTCInvoice` (hoá đơn MỚI).
    //    Các dòng ngay trên đó GÁN vào `_RefNo` ⇒ bản **laptop** mới là bản đúng ⇒ canonical = laptop `.Release.2025`.
    //
    // Nguồn: khi `SourceInvoiceCode == INVOICEREPLACE`, sau khi tạo hoá đơn mới thì hoá đơn GỐC (`RefNo`)
    //    bị chuyển `VatHTCStatus = Stage.Cancel ("C")` + ghi `LogLUDateTime`/`LogLUBy`.
    var srcCode = (dto.SourceInvoiceCode ?? "").Trim().ToUpperInvariant();
    if (srcCode.Length > 0 && srcCode is not ("INVOICEROOT" or "INVOICEADJ" or "INVOICEREPLACE"))
        return Results.BadRequest(new { error = "SourceInvoiceCode phải là INVOICEROOT | INVOICEADJ | INVOICEREPLACE." });
    var refNo = (dto.RefNo ?? "").Trim().ToUpperInvariant();
    VatInvoice? rootInv = null;
    if (srcCode == "INVOICEREPLACE")
    {
        if (refNo.Length == 0)
            return Results.BadRequest(new { error = "Hoá đơn thay thế phải chỉ ra mã hoá đơn gốc (RefNo)." });
        rootInv = await db.VatInvoices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.HTCInvoiceCode == refNo);
        if (rootInv is null) return Results.NotFound(new { error = $"Không tìm thấy hoá đơn gốc {refNo}.", refNo });
    }

    var code = "HDVAT" + DateTime.Now.ToString("yyMMddHHmmss");
    var v2 = new VatInvoice
    {
        OrgId = t.OrgId, HTCInvoiceCode = code, InvoiceIDCode = dto.InvoiceIDCode.Trim(), VAT = dto.VAT <= 0 ? 10 : dto.VAT, DealerCode = dto.DealerCode.Trim(), BankCode = dto.BankCode ?? "",
        SourceInvoiceName = dto.SourceInvoiceName ?? "", InvoiceAdjType = dto.InvoiceAdjType ?? "", RootHTCInvoiceNo = dto.RootHTCInvoiceNo ?? "",
        SourceInvoiceCode = srcCode, RefNo = refNo,      // #195
        // Nguồn tạo ở "P" (chờ duyệt) và để SỐ + NGÀY hoá đơn NULL (Biz.HTC.WH.cs:120616-120619).
        VatHTCStatus = "P",
        OS_HDDT_RefNo = dto.OS_HDDT_RefNo,
        PaymentMethodCode = string.IsNullOrWhiteSpace(dto.PaymentMethodCode) ? "CK" : dto.PaymentMethodCode!.Trim().ToUpperInvariant(),
        ValGoodsNotTaxable = dto.ValGoodsNotTaxable, ValGoodsNotChargeTax = dto.ValGoodsNotChargeTax,
        ValGoodsVAT5 = dto.ValGoodsVAT5, ValVAT5 = dto.ValVAT5,
        ValGoodsVAT10 = dto.ValGoodsVAT10, ValVAT10 = dto.ValVAT10,
        TotalValInvoice = dto.TotalValInvoice, TotalValVAT = dto.TotalValVAT, TotalValPmt = dto.TotalValPmt,
        CurrencyCode = string.IsNullOrWhiteSpace(dto.CurrencyCode) ? "VND" : dto.CurrencyCode!.Trim().ToUpperInvariant(),
        CurrencyRate = dto.CurrencyRate <= 0 ? 1 : dto.CurrencyRate
    };
    db.VatInvoices.Add(v2); await db.SaveChangesAsync();
    foreach (var c in cars)
        db.VatInvoiceCars.Add(new VatInvoiceCar { OrgId = t.OrgId, VatInvoiceId = v2.Id, VIN = c.VIN.Trim().ToUpperInvariant(), ModelCode = c.ModelCode ?? "", SpecCode = c.SpecCode ?? "", EngineNo = c.EngineNo ?? "", BrandName = c.BrandName ?? "", CarType = c.CarType ?? "", InvoiceNoFactory = c.InvoiceNoFactory ?? "", ProductionYear = c.ProductionYear ?? "", HTCUnitPrice = c.HTCUnitPrice, CustomsClearanceDate = c.CustomsClearanceDate });
    // 🔴 #195: huỷ hoá đơn GỐC — đúng khối `if (…InvoiceReplace)` của nguồn.
    if (rootInv is not null)
    {
        rootInv.VatHTCStatus = "C";
        rootInv.LogLUDateTime = DateTime.Now;
        rootInv.LogLUBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    }
    // ⚠️ KHÔNG port khối "Updte Detail" đi kèm: nguồn lọc `HTCInvoiceCode = strHTCInvoiceCode` — tức mã hoá đơn
    //    **MỚI**, không phải `RefNo` — và còn đòi `HTCStatusDetail in ('F')` trong khi dòng vừa tạo đang là "P".
    //    ⇒ ở nguồn khối đó KHÔNG khớp dòng nào, không làm gì cả. Port giữ đúng hành vi thật, ghi nợ để
    //    người nghiệp vụ quyết có nên huỷ chi tiết hoá đơn gốc hay không.
    await db.SaveChangesAsync();
    return Results.Ok(new { v2.HTCInvoiceCode, cars = cars.Count, sourceInvoiceCode = srcCode, refNo,
                            cancelledRootInvoice = rootInv?.HTCInvoiceCode });
}).RequireAuthorization();

app.MapGet("/api/vatinvoices/{code}/cars", async (string code, AppDbContext db, ITenantContext t) =>
