    var c = await db.FnExpCalcs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CaNo == no);
    if (c is null) return Results.NotFound(new { no });
    if (c.Status != "Draft") return Results.BadRequest(new { error = "Bảng tính không ở trạng thái chờ duyệt." });
    c.Status = action == "approve" ? "Approved" : "Rejected";
    if (action == "approve") c.ApprovedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { c.CaNo, c.Status });
}).RequireAuthorization();

// ===== Lịch sản xuất / ETA xe nhập (WoSchedule — port 1:1 FrmImportETAMng, Sales/WorkOrder) =====
app.MapGet("/api/woschedules", async (AppDbContext db, ITenantContext t, string? no, string? createdBy, string? status) =>
{
    var q = db.WoSchedules.Where(s => s.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(no)) q = q.Where(s => s.ScheduleNo.Contains(no!));
    if (!string.IsNullOrWhiteSpace(createdBy)) q = q.Where(s => s.CreatedBy == createdBy);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(s => s.Status == status);
    var items = await q.OrderByDescending(s => s.Id).Take(500).Select(s => new
    {
        s.ScheduleNo, s.CreatedBy, s.Status, s.CreatedAt,
        lines = db.WoScheduleLines.Count(l => l.OrgId == t.OrgId && l.WoScheduleId == s.Id),
        totalOrder = db.WoScheduleLines.Where(l => l.OrgId == t.OrgId && l.WoScheduleId == s.Id).Sum(l => (int?)l.QtyOrder) ?? 0,
        totalProduct = db.WoScheduleLines.Where(l => l.OrgId == t.OrgId && l.WoScheduleId == s.Id).Sum(l => (int?)l.QtyProduct) ?? 0
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/woschedules", async (WoScheduleDto dto, AppDbContext db, ITenantContext t) =>
{
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.WorkOrderNo) && l.QtyOrder > 0).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Lịch sản xuất trống hoặc số lượng đặt hàng <= 0." });
    var dupe = lines.GroupBy(l => l.WorkOrderNo.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"Số lệnh SX {dupe.Key} bị trùng!" });
    var no = "WOS" + DateTime.Now.ToString("yyMMddHHmmss");
    var s2 = new WoSchedule { OrgId = t.OrgId, ScheduleNo = no, CreatedBy = dto.CreatedBy ?? "system", Status = "Open" };
    db.WoSchedules.Add(s2); await db.SaveChangesAsync();
    foreach (var l in lines)
    {
        var prod = Math.Max(0, Math.Min(l.QtyProduct, l.QtyOrder));
        db.WoScheduleLines.Add(new WoScheduleLine { OrgId = t.OrgId, WoScheduleId = s2.Id, WorkOrderNo = l.WorkOrderNo.Trim(), ModelCode = l.ModelCode ?? "", SpecCode = l.SpecCode ?? "", ColorCode = l.ColorCode ?? "", QtyOrder = l.QtyOrder, QtyProduct = prod, QtyRemain = l.QtyOrder - prod, CreatedDate = DateTime.Now, QtyRemainOrder = l.QtyRemainOrder ?? 0m });
    }
    await db.SaveChangesAsync();
    // Neu tat ca dong da du SL -> Closed
    if (!await db.WoScheduleLines.AnyAsync(l => l.OrgId == t.OrgId && l.WoScheduleId == s2.Id && l.QtyRemain > 0)) { s2.Status = "Closed"; await db.SaveChangesAsync(); }
    return Results.Ok(new { s2.ScheduleNo, lines = lines.Count, status = s2.Status });
}).RequireAuthorization();

app.MapGet("/api/woschedules/{no}/lines", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var s = await db.WoSchedules.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ScheduleNo == no);
    if (s is null) return Results.NotFound(new { no });
    var lines = await db.WoScheduleLines.Where(l => l.OrgId == t.OrgId && l.WoScheduleId == s.Id)
        .Select(l => new { l.WorkOrderNo, l.ModelCode, l.SpecCode, l.ColorCode, l.QtyOrder, l.QtyProduct, l.QtyRemain, l.CreatedDate, l.QtyRemainOrder }).ToListAsync();
    return Results.Ok(new { s.ScheduleNo, s.Status, count = lines.Count, lines });
}).RequireAuthorization();

// Cap nhat SL da san xuat (ghi nhan tien do); khi het SL con lai toan lich -> Closed.
app.MapPost("/api/woschedules/{no}/lines/{workOrderNo}/produce", async (string no, string workOrderNo, WoProduceDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var s = await db.WoSchedules.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ScheduleNo == no);
    if (s is null) return Results.NotFound(new { no });
    var line = await db.WoScheduleLines.FirstOrDefaultAsync(l => l.OrgId == t.OrgId && l.WoScheduleId == s.Id && l.WorkOrderNo == workOrderNo.Trim());
    if (line is null) return Results.NotFound(new { workOrderNo });
    if (dto.Qty <= 0) return Results.BadRequest(new { error = "Số lượng sản xuất phải > 0." });
    if (line.QtyProduct + dto.Qty > line.QtyOrder) return Results.BadRequest(new { error = $"Vượt số lượng đặt hàng (đặt {line.QtyOrder}, đã SX {line.QtyProduct})." });
    line.QtyProduct += dto.Qty; line.QtyRemain = line.QtyOrder - line.QtyProduct;
    await db.SaveChangesAsync();
    var remain = await db.WoScheduleLines.AnyAsync(l => l.OrgId == t.OrgId && l.WoScheduleId == s.Id && l.QtyRemain > 0);
    if (!remain && s.Status == "Open") { s.Status = "Closed"; await db.SaveChangesAsync(); }
    return Results.Ok(new { line.WorkOrderNo, line.QtyProduct, line.QtyRemain, scheduleStatus = s.Status });
}).RequireAuthorization();

// ===== Giao dịch bán buôn xe ĐL→ĐL (WholesaleDeal — port 1:1 FrmNewDealToDealer, SalesDealer) =====
// ===== #158: BÁO CÁO GỬI HÃNG HMC (HMC_Report) =====
// Nguồn: `myDealerSales_GenerateHMCReport` (BizHTC.DealerSales.cs:24, csproj 110, md5 c5cf9085 khớp 2 máy).
// 🔴 Chuỗi `PerformContents` dài ĐÚNG 54 ký tự — hợp đồng dữ liệu với hãng; nguồn NÉM LỖI nếu khác 54.
string BuildHmcPerformContents(string? dealerCode, DateTime performDate, string vin, string deliveryType, string? salesType, DateTime createdDate)
    => "A26AD"                                              // DistributorCode, fix cứng (5)
     + (dealerCode ?? "").PadRight(10)                      // DealerCode căn TRÁI (10)
     + performDate.ToString("yyyyMMdd")                     // PerformDate (8)
     + vin                                                  // VIN (17)
     + deliveryType                                         // DeliveryType (4)
     + (salesType ?? "").PadRight(2)                        // SalesType căn TRÁI (2)
     + createdDate.ToString("yyyyMMdd");                    // CreatedDate (8)

app.MapGet("/api/hmcreports", async (AppDbContext db, ITenantContext t, string? dealNo, string? vin, string? deliveryType) =>
{
    var q = db.HmcReports.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealNo)) q = q.Where(x => x.DealNo == dealNo);
    if (!string.IsNullOrWhiteSpace(vin)) q = q.Where(x => x.VIN == vin!.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(deliveryType)) q = q.Where(x => x.DeliveryType == deliveryType);
    var items = await q.OrderByDescending(x => x.Id).Take(1000).Select(x => new {
        x.DealerCode, x.DealNo, x.CarId, x.VIN, x.DeliveryType, x.SalesType, x.PerformDate,
        x.CreatedDate, x.CreatedBy, x.PerformContents, x.AutoID,
        contentsLength = x.PerformContents == null ? 0 : x.PerformContents.Length }).ToListAsync();
    return Results.Ok(new { count = items.Count,
        invalidLength = items.Count(i => i.contentsLength != 54), items });
}).RequireAuthorization();

// ===== #B09 HỢP NHẤT THỰC THỂ SONG TRÙNG #5 (sau #56 RD_ReqInvoice, #60 Sto_DlvMinutes, #B06 StoF_MaintainMain) =====
// `WholesaleDeal`/`WholesaleDealCar` và `DealerDeal`/`DealerDealDetail` **cùng port `DLS_Deal`/`DLS_DealDetail`**.
// 🔴 Hậu quả THẬT (không phải lý thuyết): giao dịch bán buôn ĐL→ĐL ghi vào bộ RIÊNG nên **màn "tìm xe để bán
//    cho đại lý" (#B08) và hai báo cáo GPS (#B04/#B05) — vốn đọc `DealerDeal` — không bao giờ thấy chúng.**
// ⇒ Giữ `DealerDeal`/`DealerDealDetail` làm bảng chuẩn (đúng nguồn, nhiều màn khác đã dùng); cụm
//   `/api/wholesaledeals` nay ĐỌC/GHI thẳng vào đó. `WholesaleDeal*` ⛔ ngưng ghi.
// Trace twin LIVE: `FrmNewDealToDealer.btnSave_Click:212` → `DealerService.InsertDealToDealer` (:1274)
//   → WS `DealerSalesDealCreate_SellToDealer` → **`_biz.DealerSalesDealCreate_SellToDealer_New20230306`**
//   (`Biz.HTC.WH.cs:92880`) — ghi **BẢY bảng**.
app.MapGet("/api/wholesaledeals", async (AppDbContext db, ITenantContext t, string? buyer, string? no) =>
{
    // Bán buôn ĐL→ĐL = dòng `DLS_Deal` có `DealerCodeBuyer` (đại lý mua), phân biệt với bán lẻ cho khách.
    var q = db.DealerDeals.Where(d => d.OrgId == t.OrgId && d.DealerCodeBuyer != null && d.DealerCodeBuyer != "");
    if (!string.IsNullOrWhiteSpace(buyer)) q = q.Where(d => d.DealerCodeBuyer == buyer);
    if (!string.IsNullOrWhiteSpace(no)) q = q.Where(d => d.DealNo.Contains(no!) || (d.DealNoUser != null && d.DealNoUser.Contains(no!)));
    var items = await q.OrderByDescending(d => d.Id).Take(500).Select(d => new
    {
        d.DealNo, d.DealNoUser, buyerDealerCode = d.DealerCodeBuyer, d.SalesManCode, d.DealerCode, d.SalesType,
        d.DealDate, d.CustomerCodeBuyer, d.CustomerCodeHolder, d.CustomerCodeDriver,
        d.CreatedAt, d.CreatedBy, d.FlagInitDeal, d.CtmCareFlag, d.DlrContractNo, d.LogLUDateTime, d.LogLUBy,
        cars = db.DealerDealDetails.Count(c => c.OrgId == t.OrgId && c.DealId == d.Id),
        totalAmount = db.DealerDealDetails.Where(c => c.OrgId == t.OrgId && c.DealId == d.Id).Sum(c => (decimal?)c.PriceAFVAT) ?? 0m
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/wholesaledeals", async (WholesaleDealDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealNoUser)) return Results.BadRequest(new { error = "Phải nhập số giao dịch người dùng" });
    if (string.IsNullOrWhiteSpace(dto.BuyerDealerCode)) return Results.BadRequest(new { error = "Hãy chọn đại lý mua" });
    var cars = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.VIN)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "Chưa chọn xe giao dịch" });
    var dupe = cars.GroupBy(c => c.VIN.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });   // ..._DuplicateKeyDetail

    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var no = "DTD" + now.ToString("yyMMddHHmmss");
    // `if (strDealNo.Length < TConst.HTCConst.MinLengthCode)` ⇒ **MinLengthCode = 5** (Const.Main.cs:322).
    if (no.Length < 5) return Results.BadRequest(new { error = "Số giao dịch quá ngắn (tối thiểu 5 ký tự)." });
    var buyerCode = dto.BuyerDealerCode.Trim().ToUpperInvariant();
    var sellerCode = (dto.DealerCode ?? "").Trim().ToUpperInvariant();

    // `myCommon_CheckDealer(..., Flag.Active exist, Flag.Active active)` — đại lý MUA phải tồn tại & đang hoạt động.
    var buyerDealer = await db.Dealers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == buyerCode);
    if (buyerDealer is null) return Results.BadRequest(new { error = $"Đại lý mua {buyerCode} không tồn tại." });
    if ((buyerDealer.FlagActive ?? buyerDealer.Status) == "0") return Results.BadRequest(new { error = $"Đại lý mua {buyerCode} đang ngưng hoạt động." });
    // ⚠️ `myCommon_CheckAccessDealerData(BUCode)` — tầng ability BUPattern là nợ chung fleet, chưa port.

    // `GetTableContents("Mst_Customer", ..., "DealerCode","=",TConst.HTCConst.HTCPublicDealerCode)` rỗng ⇒
    // `..._CustomerNotFound`. GIÁ TRỊ hằng = **"HTC.PUBLIC"** (Const.Main.cs:320), không phải tên hằng.
    const string HtcPublicDealerCode = "HTC.PUBLIC";

    // Kiểm từng xe: `Car_Car_CheckDB(..., FlagCurrent = Flag.Active, CDODConfirmStatus = Stage.Finished)`
    // — chú thích nguồn: "Đại lý phải đã Nhập xe." (Stage.Finished = "F", Const.Main.cs:121).
    var vinKeys = cars.Select(c => c.VIN.Trim().ToUpperInvariant()).ToList();
    var vinMasters = await db.CarVinMasters.Where(x => x.OrgId == t.OrgId && vinKeys.Contains(x.VIN))
        .Select(x => new { x.VIN, x.ModelCode, x.SpecCode, x.ColorCode }).ToListAsync();
    var confirmedVins = (await db.DeliveryOrderCars
        .Where(x => x.OrgId == t.OrgId && x.ConfirmStatus == "F" && vinKeys.Contains(x.Vin))
        .Select(x => x.Vin).ToListAsync()).ToHashSet();
    foreach (var v in vinKeys)
    {
        if (!vinMasters.Any(x => x.VIN == v)) return Results.BadRequest(new { error = $"Xe {v} chưa khai báo trên hệ thống." });
        if (!confirmedVins.Contains(v)) return Results.BadRequest(new { error = $"Xe {v} đại lý chưa nhập kho (ConfirmStatus phải = 'F')." });
    }

    // ---- 1/7 `Dlr_Contract`: nguồn TỰ SINH hợp đồng đại lý và **DUYỆT LUÔN** ----
    var ctrNo = (dto.DlrContractNo ?? "").Trim();
    if (ctrNo.Length == 0) ctrNo = "DLRCTR" + now.ToString("yyMMddHHmmss");
    db.DlrContracts.Add(new DlrContract { OrgId = t.OrgId, DlrContractNo = ctrNo,
        DealerCode = sellerCode, DealerCodeBuyer = buyerCode,
        CustomerCode = sellerCode,                       // nguồn: CustomerCode = DealerCode (bên BÁN)
        DlrContractNoUser = dto.DealNoUser, SalesType = dto.SalesType, SalesManCode = dto.SalesManCode,
        ContractDate = dto.DealDate ?? now, CreatedAt = now, CreatedBy = who,
        VersionDTimeCurr = now, VersionCount = 1, VersionUpdateBy = who,
        FlagActive = "1",
        // 🔴 `DlrCtrStatus = TConst.Stage.Approved` = **"A"** — hợp đồng sinh ra ở trạng thái ĐÃ DUYỆT,
        //    kèm `ApproveDTime`; `FlagDealFinish = Flag.Inactive` = "0"; `TransactorCode = DealerCode`.
        Status = "A", ApproveDTime = now, FlagDealFinish = "0", TransactorCode = sellerCode,
        LogLUDateTime = now, LogLUBy = who });

    // ---- 2/7 `Dlr_ContractDtl`: GỘP NHÓM theo (Spec, Model, Color) + SumQty, KHÔNG phải 1 dòng/xe ----
    var grouped = cars.Select(c => new { c, m = vinMasters.First(x => x.VIN == c.VIN.Trim().ToUpperInvariant()) })
        .GroupBy(x => new { x.m.ModelCode, x.m.SpecCode, x.m.ColorCode }).ToList();
    foreach (var grp in grouped)
        db.DlrContractDetails.Add(new DlrContractDetail { OrgId = t.OrgId, DlrContractNo = ctrNo,
            ModelCode = grp.Key.ModelCode, SpecCode = grp.Key.SpecCode, ColorCode = grp.Key.ColorCode,
            Qty = grp.Count(), DlvExpectedDate = dto.DealDate ?? now, LogLUDateTime = now, LogLUBy = who });

    // ---- 3/7 `Dlr_ContractCar`: 1 dòng/xe, sinh `CtrCarId` "<SốHĐ>.NN" (2 chữ số, đúng quy ước entity) ----
    var ctrCarIds = new Dictionary<string, string>();
    int seq = 0;
    foreach (var c in cars)
    {
        var v = c.VIN.Trim().ToUpperInvariant();
        var m = vinMasters.First(x => x.VIN == v);
        var ctrCarId = $"{ctrNo}.{++seq:00}";
        ctrCarIds[v] = ctrCarId;
        db.DlrContractCars.Add(new DlrContractCar { OrgId = t.OrgId, DlrContractNo = ctrNo, CtrCarId = ctrCarId,
            ModelCode = m.ModelCode, SpecCode = m.SpecCode, ColorCode = m.ColorCode,
            DlvExpectedDate = dto.DealDate ?? now, FlagCancel = "0", FlagDelivery = "0",
            LogLUDateTime = now, LogLUBy = who });
    }

    // ---- 4/7 `Dlr_ContractDtlHis`: ảnh chụp dòng hợp đồng tại thời điểm tạo ----
    foreach (var grp in grouped)
        db.DlrContractDtlHiss.Add(new DlrContractDtlHis { OrgId = t.OrgId, DlrContractNo = ctrNo,
            ModelCode = grp.Key.ModelCode, SpecCode = grp.Key.SpecCode, ColorCode = grp.Key.ColorCode,
            Qty = grp.Count(),
            // Khoá nhóm lịch sử = `Dlr_Contract.VersionDTimeCurr` lúc ghi; `ContractUpdateType` NULL = bản ghi lúc TẠO.
            VersionDTimeCurr = now, ContractUpdateType = null, DlvExpectedDate = dto.DealDate ?? now,
            LogLUDateTime = now, LogLUBy = who });

    // ---- 5/7 `DLS_Deal` (bảng CHUẨN `DealerDeal`) ----
    var d2 = new DealerDeal
    {
        OrgId = t.OrgId, DealNo = no, DealNoUser = dto.DealNoUser.Trim(),
        DealerCode = sellerCode, DealerCodeBuyer = buyerCode,
        // Nguồn gán CẢ BA cột khách hàng = DealerCodeBuyer (đại lý mua đóng vai khách).
        CustomerCodeBuyer = buyerCode, CustomerCodeHolder = buyerCode, CustomerCodeDriver = buyerCode,
        SalesType = dto.SalesType ?? "", SalesManCode = dto.SalesManCode,
        DealDate = dto.DealDate ?? now, CreatedAt = now, CreatedBy = who,
        FlagInitDeal = "0",            // TConst.Flag.Inactive
        CtmCareFlag = "1",             // TConst.Flag.Active — nguồn đánh dấu đã kiểm chứng CSKH ngay khi tạo
        CtmCareUpdDate = now, CtmCareUpdBy = who, CtmCareRemark = null,
        DlrContractNo = ctrNo,
        LogLUDateTime = now, LogLUBy = who
    };
    db.DealerDeals.Add(d2); await db.SaveChangesAsync();

    // ---- 6/7 `DLS_DealDetail` + 7/7 `HMC_Report` ----
    foreach (var c in cars)
    {
        var v = c.VIN.Trim().ToUpperInvariant();
        db.DealerDealDetails.Add(new DealerDealDetail
        {
            OrgId = t.OrgId, DealId = d2.Id, CarId = c.CarId ?? v, VIN = v, PlateNo = c.PlateNo,
            PriceAFVAT = c.UnitPrice, DealNoPrevious = null,          // nguồn gán DBNull
            DeliveryDate = dto.DealDate ?? now,                        // = DealDate, không phải ngày hôm nay
            DeliveryStatus = "A",                                      // TConst.Stage.Approved
            ConfirmDate = now, ConfirmBy = who,
            FlagCurrent = "1",                                         // TConst.Flag.Active
            CtrCarId = ctrCarIds[v]
        });
        // 🔴 DeliveryType = **"001A"** (`HMCRpt_DeliveryToEndUser`, Const.Main.cs:330). Dòng dùng
        //    `HMCRpt_DeliveryToDealer` = "010A" nằm NGAY CẠNH nhưng **đã bị COMMENT** — port dòng ACTIVE.
        var contents = BuildHmcPerformContents(sellerCode, dto.DealDate ?? now, v, "001A", dto.SalesType, now);
        db.HmcReports.Add(new HmcReport { OrgId = t.OrgId, DealerCode = sellerCode, DealNo = no,
            CarId = c.CarId ?? v, VIN = v, DeliveryType = "001A", SalesType = dto.SalesType,
            PerformDate = dto.DealDate ?? now, CreatedDate = now, CreatedBy = who, PerformContents = contents });
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { d2.DealNo, dlrContractNo = ctrNo, cars = cars.Count,
        totalAmount = cars.Sum(c => c.UnitPrice), contractDtlRows = grouped.Count,
        htcPublicDealerCode = HtcPublicDealerCode,
        tablesWritten = new[] { "DLS_Deal", "DLS_DealDetail", "Dlr_Contract", "Dlr_ContractDtl", "Dlr_ContractCar", "Dlr_ContractDtlHis", "HMC_Report" } });
}).RequireAuthorization();

app.MapGet("/api/wholesaledeals/{no}/cars", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var d = await db.DealerDeals.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealNo == no);
    if (d is null) return Results.NotFound(new { no });
    var cars = await db.DealerDealDetails.Where(c => c.OrgId == t.OrgId && c.DealId == d.Id)
        .Select(c => new { c.VIN, c.CarId, c.PlateNo, unitPrice = c.PriceAFVAT, c.Price, c.DealNoPrevious,
            c.DeliveryDate, c.DeliveryStatus, c.ConfirmDate, c.ConfirmBy, c.FlagCurrent, c.CtrCarId }).ToListAsync();
    return Results.Ok(new { d.DealNo, d.DealNoUser, buyerDealerCode = d.DealerCodeBuyer, d.DlrContractNo,
        count = cars.Count, totalAmount = cars.Sum(c => c.unitPrice), cars });
}).RequireAuthorization();

// 🔴 #B09 GỠ nút `confirm|cancel` TỰ CHẾ (Draft/Confirmed/Cancelled): bảng nguồn `DLS_Deal` **không có cột
//    trạng thái nào** — toàn bộ khối `insert` của `DealerSalesDealCreate_SellToDealer_New20230306` không ghi
//    cột status nào cho đầu giao dịch. Ba giá trị kia là BỊA (luật C0-…sextus).
//    Thao tác THẬT của nguồn ngoài Tạo/Sửa chỉ còn **XOÁ**: `DealerSalesDealDelete_New20210412`
//    (`Biz.HTC.WH.cs:98210`), WS `DealerSalesDealDelete` (`WSHTC.asmx.cs:26897`).
app.MapDelete("/api/wholesaledeals/{no}", async (string no, AppDbContext db, ITenantContext t, string? force) =>
{
    no = no.Trim().ToUpperInvariant();
    var d = await db.DealerDeals.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealNo == no);
    if (d is null) return Results.NotFound(new { no });
    // `DLS_Deal_CheckDB(..., strFlagInitDealListToCheck = TConst.Flag.Inactive)` ⇒ chỉ xoá được giao dịch
    // KHÔNG phải giao dịch khởi tạo.
    if (d.FlagInitDeal != "0") return Results.BadRequest(new { error = "Không xoá được giao dịch khởi tạo (FlagInitDeal phải = '0')." });
    var isForce = force == "1" || force == "true";      // `bIsForceDelete = StringEqual(strIsForceDelete, Flag.Active)`
    var details = await db.DealerDealDetails.Where(c => c.OrgId == t.OrgId && c.DealId == d.Id).ToListAsync();
    // `..._CarDeliveried`: xe đã giao thì không cho xoá.
    var delivered = details.FirstOrDefault(c => c.DeliveryDate != null && c.DeliveryStatus == "A" && !isForce);
    if (delivered is not null)
        return Results.BadRequest(new { error = $"Xe {delivered.VIN ?? delivered.CarId} đã giao — không xoá được giao dịch (dùng force=1 nếu được phép)." });
    db.DealerDealDetails.RemoveRange(details);
    db.DealerDeals.Remove(d);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = no, cars = details.Count, forced = isForce });
}).RequireAuthorization();

// ===== Sửa thông tin giao dịch bán xe (DealRecord — port 1:1 cụm FrmEditDeal_*: DealDate/PlateNo/SalesType/SoBaoHanh/KHGD/KiemChung) =====

// ===== #B12 TÌM GIAO DỊCH BÁN — trả DÒNG XE (port 1:1 `DLS_Deal_Get`, dùng bởi FrmMngDeal + Frm_RePostSBHOnline) =====
// Trace twin LIVE (biz là **VỎ BỌC**, phải đi tiếp mới thấy SQL):
//   `DealerService.SearchDeal` / `SearchDeal_SBHOnline` (:2374) → WS `DLS_Deal_Get` (`WSHTC.asmx.cs:72826`)
//   → `_biz.DLS_Deal_Get_New20181119` (`Biz.HTC.WH.cs:145006`) — hàm này **không có SQL nào**, nó chỉ gọi
//   → **`DLS_Deal_GetX_New20190228`** (`Biz.HTC.WH.cs:145680`) — SQL thật nằm ở đây.
// 🔴 KẾT QUẢ SAI HÌNH DẠNG nếu port ẩu: client `SearchDeal_SBHOnline` trả về
//    `mdsFinal.Tables[Tbl_Dealer_Deal_Detail]` ⇒ **một bản ghi = MỘT DÒNG XE**, không phải một chứng từ.
// 🔴 RBAC join ở đây là `dlsd.**DealerCode**` (đại lý BÁN) — **khác** `SearchCarToSellToDealer` (#B08) và
//    `SearchCarToPDI` (#B10) vốn join theo `dlsd.DealerCodeBuyer`. Cùng một bảng, ba màn, hai cột RBAC.
// 🔴 `flagInitDeal = "0"` được client **HARDCODE** (`DealerService.cs:2384-2388`, `if` luôn đúng vì biến gán
//    cứng ngay trên) ⇒ biến thể SBHOnline **luôn** loại giao dịch khởi tạo.

// ===== #B13 TRA XE TRÊN HỢP ĐỒNG ĐẠI LÝ CHƯA VÀO GIAO DỊCH (port 1:1 `Dlr_ContractCar_Get`) =====
// Dùng bởi `FrmNewDeal` (:236, :967) khi chọn xe từ hợp đồng để lập giao dịch bán.
// Trace twin LIVE: `Dlr_PDIRequestService.Dlr_ContractCar_Get` (:391) → WS `Dlr_ContractCar_Get`
//   (`WSHTC.asmx.cs:37955`) → `_biz.Dlr_ContractCar_Get` → **`Dlr_ContractCar_GetX`**
//   (`BizHTC.Contract.cs:8776`) — SQL thật ở hàm X, hàm ngoài chỉ là vỏ bọc.
// 🔴 GUARD FIX CỨNG TRONG SQL, nằm NGOÀI mọi bộ lọc của client: `and dcc.FlagDelivery = '0'`
//    kèm chú thích nguồn *"Tìm ra những CarId hợp đồng chưa có trong giao dịch nào"* (`:8858`).
//    ⇒ dù client gửi `FlagDelivery` gì thì SQL **vẫn luôn** thêm `= '0'`. Không port guard này ⇒ màn lập
//    giao dịch sẽ chào cả những xe ĐÃ giao.
// 🔴 Tám bộ lọc của client (`Dlr_PDIRequestService.cs:391-438`) **đều là `"="` tuyệt đối**, không có LIKE nào.
//    `FrmNewDeal` gọi với `FlagCancel = Flag.Inactive("0")`, `FlagDelivery = Flag.Inactive("0")`,
//    `DlrCtrStatus = Stage.Approved("A")`.
app.MapGet("/api/dlrcontractcars/available", async (
    AppDbContext db, ITenantContext t,
    string? dlrContractNo, string? ctrCarId, string? modelCode, string? specCode, string? colorCode,
    string? flagCancel, string? flagDelivery, string? dlrCtrStatus, string? buPattern,
    int? recordStart, int? recordCount) =>
{
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();
    var start = recordStart ?? 0;
    var count = recordCount ?? 200;

    var cars = await db.DlrContractCars.Where(c => c.OrgId == t.OrgId).ToListAsync();
    // Tám bộ lọc "=" của client.
    if (!string.IsNullOrWhiteSpace(dlrContractNo)) cars = cars.Where(c => c.DlrContractNo == dlrContractNo.Trim()).ToList();
    if (!string.IsNullOrWhiteSpace(ctrCarId)) cars = cars.Where(c => c.CtrCarId == ctrCarId.Trim()).ToList();
    if (!string.IsNullOrWhiteSpace(modelCode)) cars = cars.Where(c => c.ModelCode == modelCode.Trim()).ToList();
    if (!string.IsNullOrWhiteSpace(specCode)) cars = cars.Where(c => c.SpecCode == specCode.Trim()).ToList();
    if (!string.IsNullOrWhiteSpace(colorCode)) cars = cars.Where(c => c.ColorCode == colorCode.Trim()).ToList();
    if (!string.IsNullOrWhiteSpace(flagCancel)) cars = cars.Where(c => c.FlagCancel == flagCancel.Trim()).ToList();
    if (!string.IsNullOrWhiteSpace(flagDelivery)) cars = cars.Where(c => c.FlagDelivery == flagDelivery.Trim()).ToList();
    // 🔴 Guard fix cứng của SQL — LUÔN áp, không phụ thuộc tham số trên.
    var beforeHardGuard = cars.Count;
    cars = cars.Where(c => c.FlagDelivery == "0").ToList();
    var droppedByDeliveredGuard = beforeHardGuard - cars.Count;

    // `inner join Dlr_ContractDtl dcd` theo BỐN cột (DlrContractNo + Spec + Model + Color) — dòng xe không
    // khớp một dòng chi tiết hợp đồng nào sẽ bị LOẠI.
    var dtls = await db.DlrContractDetails.Where(x => x.OrgId == t.OrgId).ToListAsync();
    // `inner join Dlr_Contract dc` + `inner join Mst_Dealer md on dc.DealerCode = md.DealerCode and BUCode like …`
    var contracts = await db.DlrContracts.Where(x => x.OrgId == t.OrgId).ToListAsync();
    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId).Select(d => new { d.DealerCode, d.BUCode }).ToListAsync();

    int droppedNoContractDtl = 0, droppedNoContract = 0, droppedByDealerJoin = 0, droppedCtrStatus = 0;
    var kept = new List<(DlrContractCar car, DlrContract ctr)>();
    foreach (var c in cars)
    {
        var dtl = dtls.FirstOrDefault(x => x.DlrContractNo == c.DlrContractNo && x.SpecCode == c.SpecCode
                                           && x.ModelCode == c.ModelCode && x.ColorCode == c.ColorCode);
        if (dtl is null) { droppedNoContractDtl++; continue; }
        var dc = contracts.FirstOrDefault(x => x.DlrContractNo == c.DlrContractNo);
        if (dc is null) { droppedNoContract++; continue; }
        var dl = dealers.FirstOrDefault(x => x.DealerCode == dc.DealerCode);
        if (dl is null) { droppedByDealerJoin++; continue; }
        if (pattern is not null && !(dl.BUCode ?? "").ToUpperInvariant().StartsWith(pattern)) { droppedByDealerJoin++; continue; }
        // Bộ lọc `dc.DlrCtrStatus` do client gửi (`FrmNewDeal` gửi Stage.Approved = "A").
        if (!string.IsNullOrWhiteSpace(dlrCtrStatus) && dc.Status != dlrCtrStatus.Trim()) { droppedCtrStatus++; continue; }
        kept.Add((c, dc));
    }

    // `order by dcc.DlrContractNo asc, dcc.SpecCode asc` rồi đánh `MyIdxSeq` và cắt theo khoảng.
    var ordered = kept.OrderBy(x => x.car.DlrContractNo, StringComparer.Ordinal)
                      .ThenBy(x => x.car.SpecCode ?? "", StringComparer.Ordinal).ToList();
    var myCount = ordered.Count;                                  // khối `select Count(0) MyCount`
    var page = ordered.Skip(start).Take(count).ToList();

    // `left join DLS_DealerCustomer ddc on dc.**TransactorCode** = ddc.CustomerCode`
    // ⚠️ Dòng dùng `dc.CustomerCode` nằm NGAY TRÊN nhưng **đã bị COMMENT** (`:8855-8856`) — port dòng ACTIVE.
    var custCodes = page.Select(x => x.ctr.TransactorCode).Where(x => x != null).Distinct().ToList();
    var custs = await db.DealerCustomers.Where(c => c.OrgId == t.OrgId && custCodes.Contains(c.CustomerCode))
        .Select(c => new { c.CustomerCode, c.FullName, c.Address, c.PhoneNo, c.ProvinceCode, c.DistrictCode }).ToListAsync();

    var items = page.Select((x, i) => new
    {
        myIdxSeq = start + i,
        x.car.DlrContractNo, x.car.CtrCarId, x.car.ModelCode, x.car.SpecCode, x.car.ColorCode,
        x.car.DlvExpectedDate, x.car.FlagCancel, x.car.FlagDelivery, x.car.LogLUDateTime, x.car.LogLUBy,
        dlrCtrStatus = x.ctr.Status, x.ctr.TransactorCode,
        ddc_CustomerCode = custs.FirstOrDefault(c => c.CustomerCode == x.ctr.TransactorCode)?.CustomerCode,
        ddc_FullName = custs.FirstOrDefault(c => c.CustomerCode == x.ctr.TransactorCode)?.FullName,
        ddc_Address = custs.FirstOrDefault(c => c.CustomerCode == x.ctr.TransactorCode)?.Address,
        ddc_PhoneNo = custs.FirstOrDefault(c => c.CustomerCode == x.ctr.TransactorCode)?.PhoneNo,
        ddc_ProvinceCode = custs.FirstOrDefault(c => c.CustomerCode == x.ctr.TransactorCode)?.ProvinceCode,
        ddc_DistrictCode = custs.FirstOrDefault(c => c.CustomerCode == x.ctr.TransactorCode)?.DistrictCode
    }).ToList();

    return Results.Ok(new
    {
        myCount, recordStart = start, recordCount = count, count = items.Count, items,
        hardGuard = "SQL nguồn LUÔN thêm `dcc.FlagDelivery = '0'` (xe hợp đồng chưa vào giao dịch nào), ngoài mọi bộ lọc client",
        customerJoinColumn = "dc.TransactorCode = ddc.CustomerCode (dòng dùng dc.CustomerCode đã bị COMMENT ở nguồn)",
        filterShapes = "cả 8 bộ lọc đều là '=' tuyệt đối, không có LIKE",
        droppedByDeliveredGuard, droppedNoContractDtl, droppedNoContract, droppedByDealerJoin, droppedCtrStatus
    });
}).RequireAuthorization();
app.MapGet("/api/deals/search", async (
    AppDbContext db, ITenantContext t,
    string? dealNo, string? carId, string? vin, string? flagInitDeal, string? buPattern,
    int? recordStart, int? recordCount) =>
{
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();
    var start = recordStart ?? 0;
    var count = recordCount ?? 200;

    // `from DLS_Deal dlsd inner join Mst_Dealer md on dlsd.DealerCode = md.DealerCode and BUCode like @…`
    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId).Select(d => new { d.DealerCode, d.BUCode }).ToListAsync();
    var deals = await db.DealerDeals.Where(d => d.OrgId == t.OrgId).ToListAsync();
    int droppedByDealerJoin = 0;
    deals = deals.Where(d =>
    {
        var dl = dealers.FirstOrDefault(x => x.DealerCode == d.DealerCode);
        if (dl is null) { droppedByDealerJoin++; return false; }              // nối TRONG ⇒ mất dòng lúc ĐỌC
        if (pattern is not null && !(dl.BUCode ?? "").ToUpperInvariant().StartsWith(pattern)) { droppedByDealerJoin++; return false; }
        return true;
    }).ToList();

    // Bộ lọc do CLIENT dựng (`sbSql.AddWhereClause`), ba cái đầu là LIKE `%…%`, `FlagInitDeal` là "=".
    if (!string.IsNullOrWhiteSpace(dealNo)) { var k = dealNo.Trim().ToUpperInvariant(); deals = deals.Where(d => d.DealNo.ToUpperInvariant().Contains(k)).ToList(); }
    if (!string.IsNullOrWhiteSpace(flagInitDeal)) deals = deals.Where(d => d.FlagInitDeal == flagInitDeal.Trim()).ToList();

    var dealIds = deals.Select(d => d.Id).ToList();
    var details = await db.DealerDealDetails.Where(x => x.OrgId == t.OrgId && dealIds.Contains(x.DealId)).ToListAsync();
    if (!string.IsNullOrWhiteSpace(carId)) { var k = carId.Trim().ToUpperInvariant(); details = details.Where(x => x.CarId.ToUpperInvariant().Contains(k)).ToList(); }

    var carIds = details.Select(x => x.CarId).Distinct().ToList();
    var carsVin = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && carIds.Contains(c.VIN)).ToListAsync();
    if (!string.IsNullOrWhiteSpace(vin))
    {
        var k = vin.Trim().ToUpperInvariant();
        var okVins = carsVin.Where(c => c.VIN.ToUpperInvariant().Contains(k)).Select(c => c.VIN).ToHashSet();
        details = details.Where(x => okVins.Contains(x.CarId)).ToList();
    }

    // `#tbl_DLS_Deal_Draft` gán `identity(bigint,0,1) MyIdxSeq` **theo `order by dlsd.DealNo`**, rồi
    // `#tbl_DLS_Deal_Filter` cắt `MyIdxSeq >= @nFilterRecordStart and <= @nFilterRecordEnd`.
    // ⚠️ Phân trang của nguồn là **theo SỐ GIAO DỊCH (DealNo distinct)**, KHÔNG phải theo dòng xe.
    var pagedDealNos = deals.Select(d => d.DealNo).Distinct().OrderBy(x => x, StringComparer.Ordinal).ToList();
    var myCount = pagedDealNos.Count;                                          // khối `select Count(0) MyCount`
    var pageNos = pagedDealNos.Skip(start).Take(count).ToHashSet();
    var pagedDealIds = deals.Where(d => pageNos.Contains(d.DealNo)).Select(d => d.Id).ToHashSet();
    details = details.Where(x => pagedDealIds.Contains(x.DealId)).ToList();

    var ctrDtls = await db.DlrContractDetails.Where(x => x.OrgId == t.OrgId).ToListAsync();
    var items = details.Select(x =>
    {
        var d = deals.First(z => z.Id == x.DealId);
        var cv = carsVin.FirstOrDefault(c => c.VIN == x.CarId);
        var prev = string.IsNullOrWhiteSpace(x.DealNoPrevious) ? null : deals.FirstOrDefault(z => z.DealNo == x.DealNoPrevious);
        // `left join Dlr_ContractDtl dcd on dlsd.DlrContractNo = dcd.DlrContractNo and cc.SpecCode = dcd.SpecCode
        //  and cc.ModelCode = dcd.ModelCode and **cc.ColorCode** = dcd.ColorCode`
        // 🔴 Ở ĐÂY màu lấy từ **Car_Car** (`cc`), trong khi `SearchCarToPDI` (#B10) lấy từ **Car_VIN** (`cv`)
        //    — hai màn, hai nguồn màu; không được suy màn này từ màn kia.
        var dcd = d.DlrContractNo is null ? null : ctrDtls.FirstOrDefault(z =>
            z.DlrContractNo == d.DlrContractNo && z.SpecCode == cv?.SpecCode && z.ModelCode == cv?.ModelCode && z.ColorCode == cv?.ColorCode);
        return new
        {
            dealNo = d.DealNo, d.DealNoUser, d.DealerCode, d.DealerCodeBuyer, d.SalesType, d.DealDate,
            d.FlagInitDeal, d.CtmCareFlag, d.DlrContractNo, d.CustomerCodeBuyer,
            x.CarId, x.PlateNo, x.PriceAFVAT, x.Price, x.DeliveryDate, x.DeliveryStatus,
            x.ConfirmDate, x.ConfirmBy, x.FlagCurrent, x.DealNoPrevious, x.CtrCarId,
            cvVIN = cv?.VIN, ccSpecCode = cv?.SpecCode, ccModelCode = cv?.ModelCode, ccColorCode = cv?.ColorCode,
            cvSpecCode = cv?.SpecCode, cvModelCode = cv?.ModelCode, cvColorCode = cv?.ColorCode,
            cvEngineNo = cv?.EngineNo, cvKeyNo = cv?.KeyNo, cvActualSpec = cv?.ActualSpec, cvSerialNo = cv?.SerialNo,
            dlsdpDealerCode = prev?.DealerCode, dlsdpDealerCodeBuyer = prev?.DealerCodeBuyer,
            // `dcd.UnitPrice` của nguồn ↔ MiniHTC đặt tên `DlrContractDetail.Price` (đơn giá theo hợp đồng ĐL).
            unitPrice = dcd?.Price
        };
    }).ToList();

    // ===== #B14 khối `Car_PlateNoDuplicate` của nguồn (`Biz.HTC.WH.cs:146035-146055`) =====
    // Với các giao dịch trong TRANG hiện tại, lấy mọi dòng có `PlateNo` khác rỗng, rồi tìm những dòng ở
    // **GIAO DỊCH KHÁC** (`t.DealNo <> f.DealNo`) đang dùng CÙNG biển số ⇒ trả (CarId, PlateNo).
    // ⚠️ So sánh là **DealNo <> DealNo**, KHÔNG phải CarId <> CarId — hai dòng cùng một giao dịch trùng biển
    //    số thì nguồn KHÔNG coi là trùng.
    var pagePlates = details.Where(x => !string.IsNullOrWhiteSpace(x.PlateNo))
        .Select(x => new { x.PlateNo, DealNo = deals.First(z => z.Id == x.DealId).DealNo }).ToList();
    var plateKeys = pagePlates.Select(p => p.PlateNo!).Distinct().ToList();
    var otherLines = await db.DealerDealDetails
        .Where(f => f.OrgId == t.OrgId && f.PlateNo != null && plateKeys.Contains(f.PlateNo))
        .Select(f => new { f.CarId, f.PlateNo, f.DealId }).ToListAsync();
    var allDealNos = await db.DealerDeals.Where(z => z.OrgId == t.OrgId)
        .Select(z => new { z.Id, z.DealNo }).ToListAsync();
    var plateNoDuplicates = otherLines
        .Select(f => new { f.CarId, f.PlateNo, DealNo = allDealNos.FirstOrDefault(z => z.Id == f.DealId)?.DealNo })
        .Where(f => pagePlates.Any(p => p.PlateNo == f.PlateNo && p.DealNo != f.DealNo))
        .Distinct().ToList();

    return Results.Ok(new
    {
        myCount,                       // tổng SỐ GIAO DỊCH khớp lọc (trước phân trang) — đúng `MyCount` của nguồn
        recordStart = start, recordCount = count,
        count = items.Count, items,
        plateNoDuplicates,             // #B14: khối `Car_PlateNoDuplicate` của nguồn
        rowShape = "MỘT bản ghi = MỘT DÒNG XE (DLS_DealDetail), không phải một chứng từ",
        rbacJoinColumn = "dlsd.DealerCode (đại lý BÁN) — khác cars-to-sell-to-dealer/cars-to-pdi vốn join DealerCodeBuyer",
        droppedByDealerJoin,
        // ⚠️ NỢ có nhãn: nguồn còn trả `CTPLShippingDate*` (join `CT_PackingList` theo `cv.PackingListNo`) và
        //    `CVStoreDate`/`CVCQStartDate`/`CVCQEndDate`/`CVCODate` — MiniHTC `CarVinMaster` chưa có các cột đó.
        missingEnrichNote = "NỢ: CTPLShippingDateStart/End/EndExpected + CVStoreDate/CVCQStartDate/CVCQEndDate/CVCODate chưa có cột trong CarVinMaster."
    });
}).RequireAuthorization();
app.MapGet("/api/deals/records", async (AppDbContext db, ITenantContext t, string? dealNo, string? vin, string? dealer) =>
{
    var q = db.DealRecords.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealNo)) q = q.Where(r => r.DealNo.Contains(dealNo!));
    if (!string.IsNullOrWhiteSpace(vin)) q = q.Where(r => r.VIN.Contains(vin!.ToUpper()));
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(r => r.DealerCode == dealer);
    var items = await q.OrderByDescending(r => r.Id).Take(500)
        .Select(r => new { r.DealNo, r.VIN, r.DealerCode, r.DealDate, r.PlateNo, r.SalesType, r.WarrantyNo, r.CustomerCode, r.VerifyStatus, r.UpdatedAt }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/deals/records", async (DealRecordDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealNo)) return Results.BadRequest(new { error = "Chưa nhập số giao dịch." });
    var no = dto.DealNo.Trim();
    var ex = await db.DealRecords.FirstOrDefaultAsync(r => r.OrgId == t.OrgId && r.DealNo == no);
    if (ex is not null)
    {
        ex.VIN = (dto.VIN ?? "").Trim().ToUpperInvariant(); ex.DealerCode = dto.DealerCode ?? ""; ex.DealDate = dto.DealDate; ex.PlateNo = dto.PlateNo ?? ""; ex.SalesType = dto.SalesType ?? ""; ex.WarrantyNo = dto.WarrantyNo ?? ""; ex.CustomerCode = dto.CustomerCode ?? ""; ex.VerifyStatus = dto.VerifyStatus ?? ""; ex.UpdatedAt = DateTime.Now;
        await db.SaveChangesAsync();
        return Results.Ok(new { ex.DealNo, updated = true });
    }
    var r2 = new DealRecord { OrgId = t.OrgId, DealNo = no, VIN = (dto.VIN ?? "").Trim().ToUpperInvariant(), DealerCode = dto.DealerCode ?? "", DealDate = dto.DealDate, PlateNo = dto.PlateNo ?? "", SalesType = dto.SalesType ?? "", WarrantyNo = dto.WarrantyNo ?? "", CustomerCode = dto.CustomerCode ?? "", VerifyStatus = dto.VerifyStatus ?? "" };
    db.DealRecords.Add(r2); await db.SaveChangesAsync();
    return Results.Ok(new { r2.DealNo, updated = false });
}).RequireAuthorization();

// Patch 1 field GD (audit old->new). field = dealDate|plateNo|salesType|warrantyNo|customerCode|verifyStatus.
app.MapPost("/api/deals/records/{dealNo}/patch", async (string dealNo, DealPatchDto dto, AppDbContext db, ITenantContext t) =>
{
    dealNo = dealNo.Trim();
    var r = await db.DealRecords.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealNo == dealNo);
    if (r is null) return Results.NotFound(new { dealNo });
    var field = (dto.Field ?? "").Trim();
    if (field is not ("dealDate" or "plateNo" or "salesType" or "warrantyNo" or "customerCode" or "verifyStatus")) return Results.BadRequest(new { error = "Field không hợp lệ (dealDate|plateNo|salesType|warrantyNo|customerCode|verifyStatus)." });
    if (string.IsNullOrWhiteSpace(dto.Value)) return Results.BadRequest(new { error = "Chưa nhập giá trị mới." });
    string oldVal;
    switch (field)
    {
        case "dealDate":
            if (!DateTime.TryParse(dto.Value, out var newDate)) return Results.BadRequest(new { error = "Ngày giao dịch không hợp lệ." });
            oldVal = r.DealDate?.ToString("yyyy-MM-dd") ?? ""; r.DealDate = newDate; break;
        case "plateNo": oldVal = r.PlateNo; r.PlateNo = dto.Value.Trim(); break;
        case "salesType": oldVal = r.SalesType; r.SalesType = dto.Value.Trim(); break;
        case "warrantyNo": oldVal = r.WarrantyNo; r.WarrantyNo = dto.Value.Trim(); break;
        case "customerCode": oldVal = r.CustomerCode; r.CustomerCode = dto.Value.Trim(); break;
        default: oldVal = r.VerifyStatus; r.VerifyStatus = dto.Value.Trim(); break;
    }
    r.UpdatedAt = DateTime.Now;
    db.DealPatchLogs.Add(new DealPatchLog { OrgId = t.OrgId, DealRecordId = r.Id, DealNo = dealNo, Field = field, OldValue = oldVal, NewValue = dto.Value.Trim() });
    await db.SaveChangesAsync();
    return Results.Ok(new { r.DealNo, field, oldValue = oldVal, newValue = dto.Value.Trim() });
}).RequireAuthorization();

app.MapGet("/api/deals/records/{dealNo}/history", async (string dealNo, AppDbContext db, ITenantContext t) =>
{
    dealNo = dealNo.Trim();
    var logs = await db.DealPatchLogs.Where(l => l.OrgId == t.OrgId && l.DealNo == dealNo)
        .OrderByDescending(l => l.Id).Take(200).Select(l => new { l.Field, l.OldValue, l.NewValue, l.PatchedAt }).ToListAsync();
    return Results.Ok(new { dealNo, count = logs.Count, logs });
}).RequireAuthorization();

// ===== HOÁ ĐƠN TCG (VAT_TCGInvoice + Detail) =====
// 🔴 TWIN đã trace kỹ (bảng này được ghi ở BỐN file khác nhau — không chọn theo file, phải theo WS):
//    WS 32-bit (WSHTC.cs:34444) gọi `..._New20181119`, WS 64-bit (WSHTC.64:46231) gọi
//    `VAT_TCGInvoiceCreate_New20201210` ở FILE KHÁC: HDDTIntergration/BizHTC.HDDTIntergration.cs:20115
//    → `VAT_TCGInvoiceCreateX_20201210` (14549). Canonical = bản 64-bit/2020 (mới hơn 2 năm).
// 🔴 `VatTCGStatus` KHÔNG dùng "A"/"R": tạo = "P", **duyệt = "F"** (Stage.Finished),
//    **không duyệt = "C"** (Stage.Cancel) — `VAT_TCGInvoiceApproveX` (19061, dòng +132).
// 🔴 Số hoá đơn (`TCGInvoiceNo`/`TCGInvoiceDate`) và mã HĐĐT (`OS_HDDT_*`) nguồn để **NULL lúc tạo**,
//    chỉ điền về sau — port giữ đúng, không sinh số ngay khi tạo.
// ⚠️ Nguồn ghi song song `_dbMain` + `_dbWH` — nợ `_dbWH` chung fleet.
app.MapGet("/api/tcginvoices", async (AppDbContext db, ITenantContext t, string? code, string? status, string? refNo) =>
{
    var qy = db.VatTcgInvoices.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(code)) qy = qy.Where(x => x.TCGInvoiceCode == code);
    if (!string.IsNullOrWhiteSpace(status)) qy = qy.Where(x => x.VatTCGStatus == status);
    if (!string.IsNullOrWhiteSpace(refNo)) qy = qy.Where(x => x.RefNo == refNo);
    var items = await qy.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.TCGInvoiceCode, x.SourceInvoiceCode, x.InvoiceAdjType, x.InvoiceIDType, x.RefNo,
        x.VatTCGStatus, x.TCGInvoiceNo, x.TCGInvoiceDate, x.OS_HDDT_InvoiceCode, x.OS_HDDT_RefNo,
        x.VAT, x.FlagView, x.TInvoiceCode, x.FlagImport,
        x.CreatedDate, x.CreatedBy, x.ApprovedDate, x.ApprovedBy, x.LogLUDateTime, x.LogLUBy,
    }).ToListAsync();
    var codes = items.Select(i => i.TCGInvoiceCode).ToList();
    var dtls = await db.VatTcgInvoiceDetails.Where(d => d.OrgId == t.OrgId && codes.Contains(d.TCGInvoiceCode))
        .Select(d => new
        {
            d.TCGInvoiceCode, d.VIN, d.TCGUnitPrice, d.TCGVAT, d.TInvoicePrice,
            d.BrandName, d.CarType, d.CustomsClearanceDate,
            d.InvoiceNoFactory, d.InvoiceFactorySearch, d.ProductionMonth,
            d.TCGStatusDetail, d.LogLUDateTime, d.LogLUBy,
        }).ToListAsync();
    return Results.Ok(new { count = items.Count, items, details = dtls });
}).RequireAuthorization();

app.MapPost("/api/tcginvoices/create", async (TcgInvoiceCreateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.TCGInvoiceCode ?? "").Trim();
    if (code.Length < 1) return Results.BadRequest(new { error = "Mã hoá đơn TCG rỗng." });
    if (await db.VatTcgInvoices.AnyAsync(x => x.OrgId == t.OrgId && x.TCGInvoiceCode == code))
        return Results.BadRequest(new { error = $"Hoá đơn {code} đã tồn tại." });
    var rows = (dto.Details ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.VIN)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Bảng chi tiết rỗng." });
    var seen = new HashSet<string>();
    foreach (var r in rows)
        if (!seen.Add(r.VIN!.Trim().ToUpperInvariant()))
            return Results.BadRequest(new { error = $"VIN {r.VIN} bị lặp trong hoá đơn." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    db.VatTcgInvoices.Add(new VatTcgInvoice
    {
        OrgId = t.OrgId, TCGInvoiceCode = code,
        SourceInvoiceCode = dto.SourceInvoiceCode, InvoiceAdjType = dto.InvoiceAdjType,
        InvoiceIDType = dto.InvoiceIDType, RefNo = dto.RefNo,
        VatTCGStatus = "P",
        // 🔴 Nguồn để NULL lúc tạo — số hoá đơn và mã HĐĐT chỉ có về sau.
        TCGInvoiceNo = null, TCGInvoiceDate = null,
        OS_HDDT_InvoiceCode = null, OS_HDDT_RefNo = null,
        VAT = dto.VAT, FlagView = dto.FlagView, TInvoiceCode = dto.TInvoiceCode, FlagImport = dto.FlagImport,
        CreatedDate = now, CreatedBy = who, LogLUDateTime = now, LogLUBy = who,
    });
    foreach (var r in rows)
        db.VatTcgInvoiceDetails.Add(new VatTcgInvoiceDetail
        {
            OrgId = t.OrgId, TCGInvoiceCode = code, VIN = r.VIN!.Trim().ToUpperInvariant(),
            TCGUnitPrice = r.TCGUnitPrice, TCGVAT = r.TCGVAT,
            TInvoicePrice = 0m, // 🔴 nguồn LUÔN ghi 0 khi tạo, không lấy từ đầu vào
            BrandName = r.BrandName, CarType = r.CarType,
            CustomsClearanceDate = r.CustomsClearanceDate,
            InvoiceNoFactory = r.InvoiceNoFactory, InvoiceFactorySearch = r.InvoiceFactorySearch,
            ProductionMonth = r.ProductionMonth,
            TCGStatusDetail = "P", LogLUDateTime = now, LogLUBy = who,
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { code, details = rows.Count, status = "P" });
}).RequireAuthorization();

// 🔴 Duyệt → "F" (Finished), từ chối → "C" (Cancel). Nguồn dùng CHUNG một hàm, cờ `bApprove` quyết định.
app.MapPost("/api/tcginvoices/approve", async (TcgInvoiceApproveDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.TCGInvoiceCode ?? "").Trim();
    var row = await db.VatTcgInvoices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TCGInvoiceCode == code);
    if (row is null) return Results.NotFound(new { error = $"Không có hoá đơn {code}." });
    if (row.VatTCGStatus != "P")
        return Results.BadRequest(new { error = $"Hoá đơn đang '{row.VatTCGStatus}', chỉ duyệt được khi 'P'." });

    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var approve = dto.Approve != false;
    row.VatTCGStatus = approve ? "F" : "C";
    row.ApprovedDate = now; row.ApprovedBy = who;
    row.LogLUDateTime = now; row.LogLUBy = who;
    // Số hoá đơn chỉ được điền khi DUYỆT (nguồn sinh qua Seq_PrintVAT — xem /api/seqcommon/get TCGIV).
    if (approve && !string.IsNullOrWhiteSpace(dto.TCGInvoiceNo))
    {
        row.TCGInvoiceNo = dto.TCGInvoiceNo!.Trim();
        row.TCGInvoiceDate = dto.TCGInvoiceDate ?? now;
    }
    var dtls = await db.VatTcgInvoiceDetails.Where(d => d.OrgId == t.OrgId && d.TCGInvoiceCode == code).ToListAsync();
    foreach (var d in dtls) { d.TCGStatusDetail = row.VatTCGStatus; d.LogLUDateTime = now; d.LogLUBy = who; }
    await db.SaveChangesAsync();
    return Results.Ok(new { code, status = row.VatTCGStatus, row.TCGInvoiceNo, detailsSynced = dtls.Count });
}).RequireAuthorization();

// ===== #B108 TÍNH TRƯỚC KHI DUYỆT HOÁ ĐƠN TCG — `VAT_TCGInvoice_CalcBeforeAppr` =====
// Trace LIVE: WS → **`_biz.VAT_TCGInvoice_CalcBeforeAppr`** (`BizHTC.InvoiceHTC_TCG.cs:1052`) —
//   **không có hậu tố `_NewYYYYMMDD`**. 3B đo thật, **khớp cả 2 máy**: start=1052 md5
//   `0d60d89f3781755e8a85b4849aaf1b5b`.
// 🔴🔴 **`strFlagUnapprove` ĐẢO NGHĨA — bẫy port ngược rất dễ mắc**:
//      `bool bApprove = CmUtils.StringUtils.StringEqual(strFlagUnapprove, TConst.Flag.**Inactive**);`
//    ⇒ **`FlagUnapprove = "0"` nghĩa là ĐANG DUYỆT**; `"1"` mới là **huỷ duyệt**.
//    Tên tham số là *"un-approve"* nhưng giá trị **"0"** mới kích hoạt nhánh duyệt. Đọc lướt theo
//    tên ⇒ port **ngược hoàn toàn** luồng duyệt/huỷ duyệt.
// 🔴 **BA khối `if (bApprove)`, chỉ HAI khối chạy — đọc thiếu là kết luận sai "không duyệt gì"**:
//    1. khối đầu (`:1107`) gọi **`VAT_TCGInvoice_Build_CalcForHDDTMultiX`** — **ĐANG CHẠY**, đây là
//       phần **tính dữ liệu hoá đơn điện tử**;
//    2. khối thứ hai (`:1129`) gọi `VAT_TCGInvoiceApproveX` — **BỊ COMMENT TOÀN BỘ**;
//    3. **bên trong vòng lặp từng hoá đơn** (`:1207`) lại có `if (bApprove)` gọi
//       **`VAT_TCGInvoiceApproveX(…, drScan["TCGInvoiceCode"], strFlagUnapprove)`** — **ĐANG CHẠY**.
//    ⇒ **Việc duyệt thật sự xảy ra TRONG VÒNG LẶP, theo TỪNG hoá đơn**, không phải một lần cho cả lô.
//      Dừng ở khối 2 (bị comment) sẽ kết luận nhầm là hàm "chỉ tính, không duyệt".
// 🔴 Đầu vào là **BẢNG `VAT_TCGInvoice`**: thiếu ⇒ `…_TCGInvoiceTblNotFound`; **rỗng ⇒ TỪ CHỐI**
//    (`…_TCGInvoiceTblInvalid`) — khuôn #B82/#B86.
//    ⚠️ Tên hằng lỗi chính tả **`CalcBeforeAprr`** (thiếu `p`, thừa `r`) — **khác** tên hàm
//      `CalcBeforeAppr`. Giữ nguyên để đối chiếu log.
// 🔴 Trả **HAI bảng**: `Invoice_Invoice` + `Invoice_InvoiceDtl` (dữ liệu hoá đơn điện tử đã tính,
//    để gửi sang HDDT) — **không phải** trả lại `VAT_TCGInvoice`.
// 📌 **NỢ — KHÔNG ĐOÁN CÔNG THỨC**: `VAT_TCGInvoice_Build_CalcForHDDTMultiX` (engine tính HDDT) chưa
//    có trong MiniHTC ⇒ hai bảng trả về để **rỗng** kèm cờ `hddtCalcSkipped`; phần **duyệt theo từng
//    hoá đơn** thì port thật.
app.MapPost("/api/tcginvoices/calc-before-approve", async (
    List<string> tcgInvoiceCodes, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user, string? flagUnapprove) =>
{
    // Bảng đầu vào: thiếu ⇒ NotFound; rỗng ⇒ TỪ CHỐI.
    if (tcgInvoiceCodes is null)
        return Results.BadRequest(new { error = "VAT_TCGInvoice_CalcBeforeAprr_Input_TCGInvoiceTblNotFound" });
    var codes = tcgInvoiceCodes.Select(x => (x ?? "").Trim()).Where(x => x.Length > 0).Distinct().ToList();
    if (codes.Count == 0)
        return Results.BadRequest(new { error = "VAT_TCGInvoice_CalcBeforeAprr_Input_TCGInvoiceTblInvalid" });

    // 🔴 ĐẢO NGHĨA: "0" (hoặc bỏ trống) ⇒ ĐANG DUYỆT; "1" ⇒ huỷ duyệt.
    var flag = (flagUnapprove ?? "0").Trim();
    var bApprove = flag == "0";

    var invs = await db.VatTcgInvoices
        .Where(i => i.OrgId == t.OrgId && codes.Contains(i.TCGInvoiceCode)).ToListAsync();
    var missing = codes.Where(c => !invs.Any(i => i.TCGInvoiceCode == c)).ToList();
    if (missing.Count > 0)
        return Results.BadRequest(new { error = "VAT_TCGInvoice_NotExist", check = new { TCGInvoiceCode = missing[0] }, missing });

    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var approved = new List<object>();

    // 🔴 Duyệt xảy ra TRONG VÒNG LẶP, theo TỪNG hoá đơn (khối `if (bApprove)` thứ ba).
    if (bApprove)
        foreach (var inv in invs)
        {
            var before = inv.VatTCGStatus;
            inv.VatTCGStatus = "A";
            inv.ApprovedDate = now;
            inv.ApprovedBy = by;
            approved.Add(new { inv.TCGInvoiceCode, statusBefore = before, status = inv.VatTCGStatus });
        }
    // 🔴🔴 #B120 TỰ SỬA #B108 — nguồn KHÔNG lưu: đường "Return Good" gọi `RollbackSafety`.
    db.ChangeTracker.Clear();   // đúng như RollbackSafety của nguồn: vứt bỏ mọi thay đổi vừa tính

    return Results.Ok(new
    {
        flagUnapprove = flag,
        bApprove,
        inputCount = codes.Count,
        approvedCount = approved.Count,
        approved,
        // Nguồn trả HAI bảng này; MiniHTC chưa có engine tính HDDT ⇒ để rỗng, KHÔNG bịa.
        Invoice_Invoice = Array.Empty<object>(),
        Invoice_InvoiceDtl = Array.Empty<object>(),
        hddtCalcSkipped = true,
        dryRun = true,
        dryRunNote = "#B120 TU SUA #B108: day la CHAY THU, KHONG LUU. Duong 'Return Good' cua nguon goi TDALUtils.DBUtils.RollbackSafety(_dbMain) + RollbackSafety(_dbWH) - KHONG PHAI CommitSafety (doi chieu: VAT_..._SaveAll thi CommitSafety). Nguon co goi VAT_TCGInvoiceApproveX (ghi that) NHUNG BEN TRONG transaction roi ROLLBACK => khong dong nao ton tai sau khi ham tra ve. Muc dich: TINH TRUOC ket qua duyet de nguoi dung xem, viec duyet that do ham KHAC lam. Port ban dau cua toi goi SaveChangesAsync() => DUYET THAT hoa don chi vi bam 'xem truoc' - da sua thanh db.ChangeTracker.Clear().",
        unapproveNreNote = "BAY TIEM AN cua nguon (KHONG tu va): 'DataSet dsGetData_Output = null;' roi CHI gan trong 'if (bApprove)'. Vung '// Get:' ben duoi chay VO DIEU KIEN va truy cap dsGetData_Output.Tables[...] => khi FlagUnapprove = '1' (HUY DUYET) se NullReferenceException. Ghi lai de nghiep vu xac nhan, port tra hai bang rong thay vi crash.",
        flagInvertedNote = "strFlagUnapprove DAO NGHIA: 'bool bApprove = StringEqual(strFlagUnapprove, TConst.Flag.Inactive)' => FlagUnapprove = '0' nghia la DANG DUYET; '1' moi la HUY DUYET. Ten tham so la 'un-approve' nhung gia tri '0' moi kich hoat nhanh duyet. Doc luot theo ten se port NGUOC HOAN TOAN luong duyet/huy duyet.",
        threeBlocksNote = "BA khoi 'if (bApprove)', chi HAI khoi chay: (1) :1107 goi VAT_TCGInvoice_Build_CalcForHDDTMultiX - DANG CHAY, phan tinh du lieu hoa don dien tu; (2) :1129 goi VAT_TCGInvoiceApproveX - BI COMMENT TOAN BO; (3) BEN TRONG VONG LAP tung hoa don (:1207) lai co if (bApprove) goi VAT_TCGInvoiceApproveX(..., drScan['TCGInvoiceCode'], strFlagUnapprove) - DANG CHAY. => Viec duyet THAT SU xay ra TRONG VONG LAP, theo TUNG hoa don. Dung o khoi 2 (bi comment) se ket luan nham la ham 'chi tinh, khong duyet'.",
        emptyInputNote = "Dau vao la BANG VAT_TCGInvoice: thieu => TblNotFound; RONG => BI TU CHOI (TblInvalid) - khuon #B82/#B86.",
        errorNameTypo = "Ten hang loi chinh ta 'CalcBeforeAprr' (thieu p, thua r) - KHAC ten ham 'CalcBeforeAppr'. Giu nguyen de doi chieu log.",
        returnShapeNote = "Nguon tra HAI bang: Invoice_Invoice + Invoice_InvoiceDtl (du lieu hoa don dien tu da tinh, de gui sang HDDT) - KHONG phai tra lai VAT_TCGInvoice.",
        hddtDebt = "NO - KHONG DOAN CONG THUC: VAT_TCGInvoice_Build_CalcForHDDTMultiX (engine tinh HDDT) chua co trong MiniHTC => hai bang tra ve de RONG kem co hddtCalcSkipped; phan duyet theo tung hoa don thi port that."
    });
}).RequireAuthorization();

// ===== #B115 SINH SỐ HOÁ ĐƠN TCG — `VAT_TCGInvoice_GenTCGInvoiceNo_New20181115` =====
// Trace LIVE: WS → `_biz.VAT_TCGInvoice_GenTCGInvoiceNo_New20181115`
//   (`BizHTC.InvoiceHTC_TCG.cs:4801`). 3B đo thật, **khớp cả 2 máy**: start=4801 md5
//   `458eea22f053c1c0acfd7f0ca13db050`.
// 🔴 **DÃY SỐ RIÊNG CHO TỪNG CẶP `(InvoiceIDCode, InvoiceIDType)`** — không phải dãy toàn cục:
//    `select max(vt.TCGInvoiceNo) from VAT_TCGInvoice vt where InvoiceIDCode = @… and InvoiceIDType = @…`
//    ⇒ mỗi **mẫu hoá đơn** có dãy số riêng. Gộp thành một dãy chung là **trùng số giữa các mẫu**.
// 🔴 **SỐ ĐẦU TIÊN LÀ `"0000000"` (BẢY SỐ 0), KHÔNG PHẢI `"0000001"`**:
//    `else strTCGInvoiceNo = "0000000";` khi chưa có bản ghi nào. Port khởi tạo bằng 1 ⇒ **lệch một
//    số** so với toàn bộ dữ liệu lịch sử.
// 🔴 **ĐỆM 0 VỀ ĐÚNG 7 KÝ TỰ bằng chuỗi `if/else if`**, không dùng `PadLeft`:
//    độ dài 1→"000000"+x · 2→"00000"+x · … · 6→"0"+x.
//    ⚠️ **Không có nhánh cho độ dài ≥ 7** ⇒ số từ **8 chữ số trở lên KHÔNG được đệm** (trả nguyên),
//      và cũng **không có guard tràn**. Port `PadLeft(7,'0')` cho **cùng kết quả** ở mọi độ dài ≤ 7
//      và cũng không cắt khi > 7 ⇒ tương đương; ghi rõ để người sau khỏi tưởng port đơn giản hoá.
// 🔴 **`max()` chạy trên cột CHUỖI** (`TCGInvoiceNo` là text). Thứ tự chuỗi = thứ tự số **chỉ nhờ
//    việc luôn đệm về 7 ký tự**; khi vượt 7 chữ số, `max` chuỗi sẽ **chọn sai** (vd `"9999999"` >
//    `"10000000"`). Đây là **giới hạn thật của thiết kế**, ghi lại chứ không tự sửa.
// 🔴🔴 **KHÔNG GHI DB, KHÔNG KHOÁ — sinh số CÓ THỂ TRÙNG khi hai người bấm cùng lúc.**
//    Hàm chỉ `select max` rồi `+1` và **trả về**; không `insert`, không `update`, không khoá tem.
//    (`bNeedTransaction = true` nhưng bên trong **không ghi gì** ⇒ transaction rỗng.)
//    ⇒ Hai phiên gọi đồng thời **nhận cùng một số**; chống trùng phải do bước **lưu hoá đơn** đảm
//      nhiệm. Port giữ đúng và trả `noReservationNote` để không ai tưởng số đã được "giữ chỗ".
// ✅ RBAC: `myCommon_CheckHTCDirect(…, TConst.Flag.Active)` — bắt buộc FlagDirect.
// 🔴 Trả về bảng tên **`Tbl_TCGInvoiceNo`** với đúng **một cột `TCGInvoiceNo`**.
app.MapGet("/api/tcginvoices/gen-invoice-no", async (
    AppDbContext db, ITenantContext t, string? invoiceIDCode, string? invoiceIDType) =>
{
    var idCode = (invoiceIDCode ?? "").Trim();
    var idType = (invoiceIDType ?? "").Trim();

    // 🔴 max() trong phạm vi CẶP (InvoiceIDCode, InvoiceIDType) — dãy riêng từng mẫu hoá đơn.
    var maxNo = await db.VatTcgInvoices
        .Where(v => v.OrgId == t.OrgId
                    && (v.InvoiceIDCode ?? "") == idCode
                    && (v.InvoiceIDType ?? "") == idType
                    && v.TCGInvoiceNo != null)
        .MaxAsync(v => v.TCGInvoiceNo);

    string next;
    if (!string.IsNullOrWhiteSpace(maxNo) && long.TryParse(maxNo, out var n))
    {
        // Đệm 0 về ĐÚNG 7 ký tự; số ≥ 8 chữ số KHÔNG bị đệm và KHÔNG bị cắt (như nguồn).
        next = (n + 1).ToString();
        if (next.Length < 7) next = next.PadLeft(7, '0');
    }
    else
    {
        // 🔴 Chưa có bản ghi nào ⇒ "0000000" (BẢY số 0), KHÔNG phải "0000001".
        next = "0000000";
    }

    return Results.Ok(new
    {
        Tbl_TCGInvoiceNo = new[] { new { TCGInvoiceNo = next } },
        invoiceIDCode = idCode, invoiceIDType = idType,
        maxTCGInvoiceNo = maxNo,
        scopeNote = "DAY SO RIENG CHO TUNG CAP (InvoiceIDCode, InvoiceIDType) - khong phai day toan cuc: 'select max(vt.TCGInvoiceNo) from VAT_TCGInvoice where InvoiceIDCode = @... and InvoiceIDType = @...'. Moi MAU HOA DON co day so rieng; gop thanh mot day chung la TRUNG SO giua cac mau.",
        firstNumberNote = "SO DAU TIEN LA '0000000' (BAY SO 0), KHONG PHAI '0000001': nguon co 'else strTCGInvoiceNo = \"0000000\";' khi chua co ban ghi nao. Port khoi tao bang 1 => LECH MOT SO so voi toan bo du lieu lich su.",
        paddingNote = "DEM 0 VE DUNG 7 KY TU bang chuoi if/else if (do dai 1..6), KHONG dung PadLeft. KHONG co nhanh cho do dai >= 7 => so tu 8 chu so tro len KHONG duoc dem (tra nguyen) va KHONG co guard tran. Port dung PadLeft(7,'0') cho CUNG ket qua o moi do dai <= 7 va cung khong cat khi > 7 => tuong duong.",
        stringMaxNote = "max() chay tren cot CHUOI (TCGInvoiceNo la text). Thu tu chuoi = thu tu so CHI NHO viec luon dem ve 7 ky tu; khi vuot 7 chu so, max chuoi se CHON SAI (vd '9999999' > '10000000'). Day la GIOI HAN THAT cua thiet ke - ghi lai, khong tu sua.",
        noReservationNote = "KHONG GHI DB, KHONG KHOA - SINH SO CO THE TRUNG khi hai nguoi bam cung luc. Ham chi 'select max' roi +1 va TRA VE; khong insert/update/khoa tem (bNeedTransaction = true nhung ben trong KHONG ghi gi => transaction rong). Hai phien goi dong thoi NHAN CUNG MOT SO; chong trung phai do buoc LUU HOA DON dam nhiem. So tra ve KHONG duoc 'giu cho'.",
        rbacNote = "myCommon_CheckHTCDirect(..., TConst.Flag.Active) - bat buoc FlagDirect.",
        returnShapeNote = "Nguon tra ve bang ten 'Tbl_TCGInvoiceNo' voi dung MOT cot 'TCGInvoiceNo'."
    });
}).RequireAuthorization();

// ===== #B116 SINH SỐ HOÁ ĐƠN HTC — `VAT_HTCInvoice_GenHTCInvoiceNo_New20181115` =====
// Trace LIVE: WS → `_biz.VAT_HTCInvoice_GenHTCInvoiceNo_New20181115`
//   (`BizHTC.InvoiceHTC_TCG.cs:6308`). 3B đo thật, **khớp cả 2 máy**: start=6308 md5
//   `5531b6f801c3515ed024a370cf182417`.
// 🔴 **SONG SINH TỪNG DÒNG với #B115** (`VAT_TCGInvoice_GenTCGInvoiceNo`): cùng khuôn
//    `max(<cột>) + 1` trong phạm vi **cặp `(InvoiceIDCode, InvoiceIDType)`**, cùng chuỗi
//    `if/else if` đệm 0 về **7 ký tự**, cùng giá trị khởi đầu **`"0000000"`** (bảy số 0),
//    cùng **KHÔNG ghi DB / KHÔNG khoá** ⇒ **số có thể trùng**.
//    Khác nhau **chỉ ở**: bảng (`VAT_HTCInvoice`), cột (`HTCInvoiceNo`), tên bảng trả về
//    (**`Tbl_HTCInvoiceNo`**). ⇒ Mọi luật của #B115 áp dụng nguyên
//    (`C0-…quartusdecimus`, `C0-…quintusdecimus`).
// ⚠️ **HAI DÃY SỐ ĐỘC LẬP**: hoá đơn **TCG** và hoá đơn **HTC** đếm riêng trên **hai bảng khác nhau**
//    ⇒ **cùng một cặp `(InvoiceIDCode, InvoiceIDType)` có thể cho ra số giống nhau ở hai loại**.
//    Đó là **đúng ý nguồn** (hai loại chứng từ khác nhau), không phải trùng lặp cần sửa.
// 📌 §12: `VatHtcInvoice.InvoiceIDCode` — nửa kia của phạm vi dãy số (song sinh với #B115).
app.MapGet("/api/htcinvoices/gen-invoice-no", async (
    AppDbContext db, ITenantContext t, string? invoiceIDCode, string? invoiceIDType) =>
{
    var idCode = (invoiceIDCode ?? "").Trim();
    var idType = (invoiceIDType ?? "").Trim();

    var maxNo = await db.VatHtcInvoices
        .Where(v => v.OrgId == t.OrgId
                    && (v.InvoiceIDCode ?? "") == idCode
                    && (v.InvoiceIDType ?? "") == idType
                    && v.HTCInvoiceNo != null)
        .MaxAsync(v => v.HTCInvoiceNo);

    string next;
    if (!string.IsNullOrWhiteSpace(maxNo) && long.TryParse(maxNo, out var n))
    {
        next = (n + 1).ToString();
        if (next.Length < 7) next = next.PadLeft(7, '0');
    }
    else next = "0000000";      // bảy số 0 — KHÔNG phải "0000001"

    return Results.Ok(new
    {
        Tbl_HTCInvoiceNo = new[] { new { HTCInvoiceNo = next } },
        invoiceIDCode = idCode, invoiceIDType = idType,
        maxHTCInvoiceNo = maxNo,
        twinNote = "SONG SINH TUNG DONG voi #B115 (VAT_TCGInvoice_GenTCGInvoiceNo): cung khuon max(<cot>)+1 trong pham vi cap (InvoiceIDCode, InvoiceIDType), cung chuoi if/else if dem 0 ve 7 ky tu, cung gia tri khoi dau '0000000', cung KHONG ghi DB / KHONG khoa. Khac nhau CHI o: bang (VAT_HTCInvoice), cot (HTCInvoiceNo), ten bang tra ve (Tbl_HTCInvoiceNo).",
        twoSequencesNote = "HAI DAY SO DOC LAP: hoa don TCG va hoa don HTC dem rieng tren HAI BANG KHAC NHAU => cung mot cap (InvoiceIDCode, InvoiceIDType) CO THE cho ra so giong nhau o hai loai. Day la DUNG Y NGUON (hai loai chung tu khac nhau), khong phai trung lap can sua.",
        noReservationNote = "KHONG GHI DB, KHONG KHOA - SINH SO CO THE TRUNG khi hai nguoi bam cung luc. So tra ve KHONG duoc 'giu cho'; chong trung phai do buoc LUU HOA DON dam nhiem. Xem luat C0-...quartusdecimus.",
        stringMaxNote = "max() chay tren cot CHUOI - dung duoc CHI NHO dem co dinh 7 ky tu; vuot 7 chu so thi max chuoi CHON SAI ('9999999' > '10000000'). Nguong tran: 10 trieu hoa don moi mau. Xem luat C0-...quintusdecimus.",
        firstNumberNote = "So dau tien la '0000000' (BAY so 0), KHONG phai '0000001'."
    });
}).RequireAuthorization();

// ===== #B117 HUỶ HOÁ ĐƠN TCG TRÊN HDDT — `VAT_TCGInvoice_Invoice_Invoice_Deleted` =====
// Trace LIVE: WS → `_biz.VAT_TCGInvoice_Invoice_Invoice_Deleted` (`BizHTC.InvoiceHTC_TCG.cs:1399`)
//   — **không có hậu tố `_NewYYYYMMDD`**. 3B đo thật, **khớp cả 2 máy**: start=1399 md5
//   `b596e1c087541e50d9c29f3ed30508b2`.
// 🔴 **"Deleted" KHÔNG PHẢI XOÁ — mà là ĐỔI TRẠNG THÁI sang `'C'`** (`:1831`, `:1857`):
//      `update VAT_TCGInvoice       set VatTCGStatus   = 'C' -- Rejected …`
//      `update VAT_TCGInvoiceDetail set TCGStatusDetail = 'C' -- Rejected …`
//    ⇒ **không có `delete`** ở đâu cả; dữ liệu vẫn còn, chỉ chuyển sang **huỷ**.
//    ⚠️ Chú thích nguồn ghi **`-- Rejected`** cho giá trị `'C'` — **lệch từ vựng** (`TConst.Stage`:
//      `'C'` = *Cancelled*, `'R'` = *Rejected*). Giữ **giá trị** `'C'`, **bỏ qua** nhãn sai.
//    ⇒ Port thành `db.Remove(...)` là **mất dữ liệu** và làm hỏng mọi báo cáo đọc hoá đơn đã huỷ.
// 🔴 **BỐN kiểm đầu vào BẮT BUỘC**, mỗi cái một mã lỗi riêng:
//    `TCGInvoiceCode` (`…_strTCGInvoiceCodeInvalid`) · `DeleteDTime` (`…_strDeleteDTimeInvalid`) ·
//    `DeleteReason` (`…_strDeleteReasonInvalid`) · `Email` (`…_strEmailInvalid`).
//    Sau đó hoá đơn phải **tồn tại** (`…_strTCGInvoiceCodeNotFound`).
// 🔴 **DÒ HOÁ ĐƠN ĐIỀU CHỈNH CỦA HOÁ ĐƠN GỐC** trước khi huỷ:
//      `from VAT_TCGInvoice t inner join #tbl_VAT_TCGInvoiceInput f **on t.RefNo = f.TCGInvoiceCode**`
//      `where t.SourceInvoiceCode = **'INVOICEADJ'** and t.VatTCGStatus **not in ('C')**`
//    ⇒ tìm hoá đơn **điều chỉnh** (`RefNo` trỏ về hoá đơn đang huỷ) **chưa bị huỷ**.
//    ⚠️ **Khối "Thu hồi hoá đơn điều chỉnh" NGAY SAU ĐÓ BỊ COMMENT TOÀN BỘ** (`:1726-1800`) ⇒ nguồn
//      **dò ra nhưng KHÔNG làm gì** với danh sách đó. Port giữ đúng: **trả ra để cảnh báo**
//      (`invoiceAdjNotRecalled`), **không tự thu hồi**.
// 🔴 Ghi **cả `_dbMain` và `_dbWH`**, cả hai bảng (đầu + dòng).
// 📌 **NỢ — hiệu ứng RA NGOÀI**: `OSDMS_TVAN_OS_Invoice_Invoice_DeletedX` (gọi sang **hệ thống hoá
//    đơn điện tử TVAN**) và `OSDMS_TVAN_Invoice_Invoice_GetX` chưa có trong MiniHTC ⇒ endpoint
//    **chỉ đổi trạng thái trong DB**, cờ `tvanNotCalled = true`. Theo luật `C0-…quingentesimusseptimus`:
//    hiệu ứng ra ngoài **không tự bắn**. `AttachedDelFile*`/`Email` nhận vào nhưng **chưa gửi đi đâu**.
app.MapPost("/api/tcginvoices/{code}/hddt-delete", async (
    string code, TcgInvoiceHddtDeleteDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    var invCode = (code ?? "").Trim();
    if (invCode.Length == 0)
        return Results.BadRequest(new { error = "VAT_TCGInvoice_Invoice_Invoice_Deleted_Input_strTCGInvoiceCodeInvalid" });
    if (dto.DeleteDTime is null)
        return Results.BadRequest(new { error = "VAT_TCGInvoice_Invoice_Invoice_Deleted_Input_strDeleteDTimeInvalid" });
    if (string.IsNullOrWhiteSpace(dto.DeleteReason))
        return Results.BadRequest(new { error = "VAT_TCGInvoice_Invoice_Invoice_Deleted_Input_strDeleteReasonInvalid" });
    if (string.IsNullOrWhiteSpace(dto.Email))
        return Results.BadRequest(new { error = "VAT_TCGInvoice_Invoice_Invoice_Deleted_Input_strEmailInvalid" });

    var inv = await db.VatTcgInvoices.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.TCGInvoiceCode == invCode);
    if (inv is null)
        return Results.BadRequest(new
        {
            error = "VAT_TCGInvoice_Invoice_Invoice_Deleted_Input_strTCGInvoiceCodeNotFound",
            check = new { TCGInvoiceCode = invCode }
        });

    // 🔴 Dò hoá đơn ĐIỀU CHỈNH trỏ về hoá đơn này và CHƯA bị huỷ.
    var adjs = await db.VatTcgInvoices
        .Where(v => v.OrgId == t.OrgId && v.RefNo == invCode
                    && v.SourceInvoiceCode == "INVOICEADJ" && v.VatTCGStatus != "C")
        .Select(v => new { v.TCGInvoiceCode, v.SourceInvoiceCode, v.VatTCGStatus })
        .ToListAsync();

    var now = DateTime.Now;
    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";

    // 🔴 "Deleted" = ĐỔI TRẠNG THÁI sang 'C', KHÔNG xoá dòng.
    var statusBefore = inv.VatTCGStatus;
    inv.VatTCGStatus = "C";
    inv.LogLUDateTime = now; inv.LogLUBy = by;

    var dtls = await db.VatTcgInvoiceDetails
        .Where(d => d.OrgId == t.OrgId && d.TCGInvoiceCode == invCode).ToListAsync();
    foreach (var d in dtls) { d.TCGStatusDetail = "C"; d.LogLUDateTime = now; d.LogLUBy = by; }

    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        tcgInvoiceCode = invCode,
        statusBefore, vatTCGStatus = inv.VatTCGStatus,
        detailsUpdated = dtls.Count,
        deleteReason = dto.DeleteReason, deleteDTime = dto.DeleteDTime, email = dto.Email,
        invoiceAdjNotRecalled = adjs,
        tvanNotCalled = true,
        notDeleteNote = "'Deleted' KHONG PHAI XOA - ma la DOI TRANG THAI sang 'C': update VAT_TCGInvoice set VatTCGStatus='C' va update VAT_TCGInvoiceDetail set TCGStatusDetail='C'. KHONG co 'delete' o dau ca; du lieu van con. Port thanh db.Remove(...) la MAT DU LIEU va lam hong moi bao cao doc hoa don da huy.",
        vocabMismatchNote = "Chu thich nguon ghi '-- Rejected' cho gia tri 'C' - LECH TU VUNG (TConst.Stage: 'C' = Cancelled, 'R' = Rejected). Giu GIA TRI 'C', BO QUA nhan sai.",
        fourChecksNote = "BON kiem dau vao BAT BUOC, moi cai mot ma loi rieng: TCGInvoiceCode / DeleteDTime / DeleteReason / Email. Sau do hoa don phai TON TAI (_strTCGInvoiceCodeNotFound).",
        invoiceAdjNote = "DO HOA DON DIEU CHINH cua hoa don goc truoc khi huy: 'inner join #tbl_VAT_TCGInvoiceInput f ON t.RefNo = f.TCGInvoiceCode where t.SourceInvoiceCode = INVOICEADJ and t.VatTCGStatus not in (C)'. NHUNG khoi 'Thu hoi hoa don dieu chinh' NGAY SAU DO BI COMMENT TOAN BO (:1726-1800) => nguon DO RA NHUNG KHONG LAM GI. Port giu dung: tra ra de canh bao (invoiceAdjNotRecalled), KHONG tu thu hoi.",
        tvanDebt = "NO - HIEU UNG RA NGOAI: OSDMS_TVAN_OS_Invoice_Invoice_DeletedX (goi sang he thong hoa don dien tu TVAN) va OSDMS_TVAN_Invoice_Invoice_GetX chua co trong MiniHTC => endpoint CHI doi trang thai trong DB. Theo luat C0-...quingentesimusseptimus: hieu ung ra ngoai KHONG TU BAN. AttachedDelFile*/Email nhan vao nhung CHUA gui di dau.",
        twoDbNote = "Nguon ExecNonQuery tren CA _dbMain va _dbWH, cho CA HAI bang (dau + dong)."
    });
}).RequireAuthorization();

// ===== #B118 HUỶ HOÁ ĐƠN HTC TRÊN HDDT — `VAT_HTCInvoice_Invoice_Invoice_Deleted` =====
// Trace LIVE: `BizHTC.InvoiceHTC_TCG.cs:2221` — **không có hậu tố**. 3B đo thật, **khớp cả 2 máy**:
//   start=2221 md5 `3d34b5c058a6110c886dce5d02b76bc9`.
// 🔴 Cùng khuôn "Deleted = ĐỔI TRẠNG THÁI, KHÔNG XOÁ" như #B117 (`VatHTCStatus`/`HTCStatusDetail`
//   ← `'C'`, chú thích nguồn `-- Rejected` **lệch từ vựng**, giữ **giá trị**).
// 🔴🔴 **NHƯNG SONG SINH NÀY KHÁC #B117 Ở HAI ĐIỂM CỐT TỬ — KHÔNG ĐƯỢC COPY #B117 SANG:**
//   **(1) HOÁ ĐƠN ĐIỀU CHỈNH ⇒ BẮN LỖI, CHẶN HUỶ** (`:2588`):
//        `if (dtInvoiceAdj != null && dtInvoiceAdj.Rows.Count > 0) throw …_HTCInvoiceCode_InvoiceadjExist;`
//        Chú thích nguồn: *"Nếu thu hồi hóa đơn gốc có hóa đơn điều chỉnh ==> bắn lỗi"*.
//        ⇒ Bên **TCG (#B117)** khối xử lý bị **comment** ⇒ dò ra mà **không làm gì**, huỷ vẫn chạy.
//          Bên **HTC (#B118)** thì **CHẶN THẲNG**. Cùng một câu SQL dò, **hai hành vi ngược nhau**.
//   **(2) THAM SỐ `strFlagisHTC` (PHÁP NHÂN) — mã lỗi riêng `…_Input_strFlagisHTCInvalid`:**
//        chỉ nhận `FlagIsHTC.FlagisHTC = "1"` hoặc `FlagisHTCLD = "2"` (`Const.Main.cs:1158-1164`);
//        **`"0"` (FlagisNone) BỊ CHẶN** dù vẫn là hằng hợp lệ của cùng lớp.
//        Và nó **vào cả câu tìm hoá đơn**: `where HTCInvoiceCode = @… **and t.FlagisHTC = @…**`
//        ⇒ đúng mã nhưng **sai pháp nhân** ⇒ báo **NotFound**, không phải "sai cờ".
//        Chú thích nguồn giải thích vì sao update bên dưới **không** cần lọc lại: *"HTCInvoiceCode là PK"*.
//        Ngoài ra `strFlagisHTC` chọn **cấu hình HDDT khác nhau**: `_strConfig_HDDT_NetworkHTC` vs
//        `…NetworkHTCLD`, `_strConfig_HDDT_MSTHTC` vs `…MSTHTCLD` ⇒ **hai mạng HDDT, hai MST**.
// 🔴 **NĂM kiểm đầu vào** (nhiều hơn #B117 một cái, do có `strFlagisHTC`), mỗi cái một mã lỗi riêng;
//   rồi hoá đơn phải **tồn tại theo CẶP (mã, pháp nhân)** (`…_Input_strHTCInvoiceCodeNotFound`).
// 🔴 `select **top 1**` vào `#tbl_VAT_HTCInvoiceInput` — chỉ lấy **một** hoá đơn (khác lô).
// 📌 **NỢ — hiệu ứng RA NGOÀI**: `OSDMS_TVAN_Invoice_Invoice_GetX` (đọc hoá đơn bên TVAN, và **ném
//   `…_InvoiceCodeInQinvoiceNotFound` nếu bảng trả về không đúng 1 dòng**) rồi
//   `OSDMS_TVAN_OS_Invoice_Invoice_DeletedX` (đẩy huỷ sang TVAN, kèm `AttachedDelFileSpec` /
//   `AttachedDelFileName` / `DeleteReason` / `DeleteDTimeActual` / `Remark = ""`).
//   Chưa có trong MiniHTC ⇒ endpoint **chỉ đổi trạng thái trong DB**, cờ `tvanNotCalled = true`.
//   Theo luật `C0-…quingentesimusseptimus`: hiệu ứng ra ngoài **không tự bắn**.
// 🔴 Ghi **cả `_dbMain` và `_dbWH`**, cả hai bảng (đầu + dòng).
// 📌 §12: `VatHtcInvoice.OS_HDDT_InvoiceCode`.
app.MapPost("/api/htcinvoices/{code}/hddt-delete", async (
    string code, HtcInvoiceHddtDeleteDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    var invCode = (code ?? "").Trim();
    if (invCode.Length == 0)
        return Results.BadRequest(new { error = "VAT_HTCInvoice_Invoice_Invoice_Deleted_Input_strHTCInvoiceCodeInvalid" });

    // 🔴 (2) PHÁP NHÂN — chỉ "1" (HTC) hoặc "2" (HTCLD); "0" (None) BỊ CHẶN.
    var flagisHTC = (dto.FlagisHTC ?? "").Trim();
    if (!(flagisHTC == "1" || flagisHTC == "2"))
        return Results.BadRequest(new
        {
            error = "VAT_HTCInvoice_Invoice_Invoice_Deleted_Input_strFlagisHTCInvalid",
            check = new { HTCInvoiceCode = invCode, FlagisHTC = flagisHTC },
            vocabNote = "FlagIsHTC (Const.Main.cs:1158-1164): '1' = FlagisHTC | '2' = FlagisHTCLD | '0' = FlagisNone. Guard CHI nhan '1' hoac '2' => '0' BI CHAN du van la hang hop le cua cung lop."
        });

    if (dto.DeleteDTime is null)
        return Results.BadRequest(new { error = "VAT_HTCInvoice_Invoice_Invoice_Deleted_Input_strDeleteDTimeInvalid" });
    if (string.IsNullOrWhiteSpace(dto.DeleteReason))
        return Results.BadRequest(new { error = "VAT_HTCInvoice_Invoice_Invoice_Deleted_Input_strDeleteReasonInvalid" });
    if (string.IsNullOrWhiteSpace(dto.Email))
        return Results.BadRequest(new { error = "VAT_HTCInvoice_Invoice_Invoice_Deleted_Input_strEmailInvalid" });

    // 🔴 Tìm theo CẶP (mã, pháp nhân) — `select top 1 … where HTCInvoiceCode = @… and FlagisHTC = @…`
    var inv = await db.VatHtcInvoices
        .Where(v => v.OrgId == t.OrgId && v.HTCInvoiceCode == invCode && (v.FlagisHTC ?? "") == flagisHTC)
        .OrderBy(v => v.Id).FirstOrDefaultAsync();
    if (inv is null)
        return Results.BadRequest(new
        {
            error = "VAT_HTCInvoice_Invoice_Invoice_Deleted_Input_strHTCInvoiceCodeNotFound",
            check = new { HTCInvoiceCode = invCode, FlagisHTC = flagisHTC },
            note = "Dung ma nhung SAI PHAP NHAN cung ra NotFound (dieu kien nam trong cau tim), khong phai loi 'sai co'."
        });

    // 🔴 (1) Hoá đơn ĐIỀU CHỈNH còn sống ⇒ CHẶN HUỶ (khác hẳn #B117 bên TCG).
    var adjs = await db.VatHtcInvoices
        .Where(v => v.OrgId == t.OrgId && v.RefNo == invCode
                    && v.SourceInvoiceCode == "INVOICEADJ" && v.VatHTCStatus != "C")
        .Select(v => new { v.HTCInvoiceCode, v.SourceInvoiceCode, v.VatHTCStatus, v.OS_HDDT_InvoiceCode })
        .ToListAsync();
    if (adjs.Count > 0)
        return Results.BadRequest(new
        {
            error = "VAT_HTCInvoice_Invoice_Invoice_Deleted_HTCInvoiceCode_InvoiceadjExist",
            check = new { HTCInvoiceCode = invCode },
            invoiceAdj = adjs,
            twinDivergenceNote = "SONG SINH KHAC NHAU: ben HTC (#B118) co hoa don DIEU CHINH con song => BAN LOI, CHAN HUY (chu thich nguon: 'Neu thu hoi hoa don goc co hoa don dieu chinh ==> ban loi'). Ben TCG (#B117) cung cau SQL do do NHUNG khoi xu ly BI COMMENT => do ra ma KHONG LAM GI, huy van chay."
        });

    var now = DateTime.Now;
    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";

    var statusBefore = inv.VatHTCStatus;
    inv.VatHTCStatus = "C";
    inv.LogLUDateTime = now; inv.LogLUBy = by;

    var dtls = await db.VatHtcInvoiceDetails
        .Where(d => d.OrgId == t.OrgId && d.HTCInvoiceCode == invCode).ToListAsync();
    foreach (var d in dtls) { d.HTCStatusDetail = "C"; d.LogLUDateTime = now; d.LogLUBy = by; }

    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        htcInvoiceCode = invCode, flagisHTC,
        statusBefore, vatHTCStatus = inv.VatHTCStatus,
        detailsUpdated = dtls.Count,
        osHddtInvoiceCode = inv.OS_HDDT_InvoiceCode,
        deleteReason = dto.DeleteReason, deleteDTime = dto.DeleteDTime, email = dto.Email,
        tvanNotCalled = true,
        notDeleteNote = "'Deleted' KHONG PHAI XOA - ma la DOI TRANG THAI: update VAT_HTCInvoice set VatHTCStatus='C' va update VAT_HTCInvoiceDetail set HTCStatusDetail='C'. KHONG co 'delete' o dau ca. Chu thich nguon ghi '-- Rejected' cho 'C' - LECH TU VUNG (TConst.Stage: 'C'=Cancelled, 'R'=Rejected); giu GIA TRI, bo qua nhan.",
        twinDivergenceNote = "KHONG DUOC COPY #B117 SANG: song sinh nay KHAC O HAI DIEM COT TU. (1) Hoa don DIEU CHINH con song => #B118 BAN LOI CHAN HUY, con #B117 (TCG) khoi xu ly BI COMMENT nen huy van chay. (2) #B118 co them tham so strFlagisHTC (phap nhan) voi ma loi rieng _Input_strFlagisHTCInvalid.",
        flagisHTCNote = "strFlagisHTC chi nhan '1' (HTC) / '2' (HTCLD); '0' (FlagisNone) BI CHAN. No VAO CA CAU TIM hoa don: 'where HTCInvoiceCode = @... and t.FlagisHTC = @...' => dung ma nhung sai phap nhan ra NotFound. Chu thich nguon: update ben duoi KHONG can loc lai vi 'HTCInvoiceCode la PK'. Ngoai ra no chon CAU HINH HDDT khac nhau: _strConfig_HDDT_NetworkHTC vs ...NetworkHTCLD, _strConfig_HDDT_MSTHTC vs ...MSTHTCLD => HAI MANG HDDT, HAI MST.",
        fiveChecksNote = "NAM kiem dau vao (nhieu hon #B117 mot cai): HTCInvoiceCode / FlagisHTC / DeleteDTime / DeleteReason / Email; roi hoa don phai TON TAI theo CAP (ma, phap nhan). Nguon dung 'select top 1' - chi lay MOT hoa don.",
        tvanDebt = "NO - HIEU UNG RA NGOAI: OSDMS_TVAN_Invoice_Invoice_GetX (doc hoa don ben TVAN; nem _InvoiceCodeInQinvoiceNotFound neu bang tra ve KHONG dung 1 dong) roi OSDMS_TVAN_OS_Invoice_Invoice_DeletedX (day huy sang TVAN kem AttachedDelFileSpec / AttachedDelFileName / DeleteReason / DeleteDTimeActual / Remark = ''). Chua co trong MiniHTC => CHI doi trang thai trong DB. Luat C0-...quingentesimusseptimus: hieu ung ra ngoai KHONG TU BAN.",
        twoDbNote = "Nguon ExecNonQuery tren CA _dbMain va _dbWH, cho CA HAI bang (dau + dong)."
    });
}).RequireAuthorization();

// ===== #B121/#B122 TÍNH TRƯỚC KHI DUYỆT HOÁ ĐƠN HTC & HTCLD — `VAT_HTCInvoice_CalcBeforeAprr`
//       và `VAT_HTCLDInvoice_CalcBeforeAprr` =====
// Trace LIVE: `HDDTIntergration.cs:10196` (HTC) và `:10413` (HTCLD). 3B đo thật, **khớp cả 2 máy**:
//   `10196/43780da461a854440179fe5faee7a9e6` · `10413/5b8b479182d5eeb00885fcd0fffd20ce`.
// 🔴🔴 **CHẠY THỬ — KHÔNG LƯU. Đường "Return Good" gọi `RollbackSafety`, KHÔNG phải `CommitSafety`**:
//      `// Return Good:  RollbackSafety(_dbMain);  RollbackSafety(_dbWH);  return mdsFinal;`
//    Nguồn **có** gọi `VAT_HTCInvoiceApproveX` (ghi thật) nhưng **bên trong transaction rồi rollback**
//    ⇒ **không dòng nào tồn tại** sau khi hàm trả về. Mục đích: **tính trước** kết quả duyệt cho người
//    dùng xem; việc duyệt thật do hàm **khác** làm.
//    ⚠️ Đối chiếu: `…_SaveAll` (#B119) dùng `CommitSafety` ⇒ **cùng file, hai kiểu kết thúc khác nhau**.
//    📌 Đây chính là lỗi tôi đã mắc ở **#B108** (gọi `SaveChangesAsync`) — đã tự sửa ở **#B120**.
// 🔴 **HAI HÀM NÀY GIỐNG NHAU 1:1** (diff toàn thân chỉ ra **khác biệt duy nhất là TÊN**: tên hàm,
//    tên hằng lỗi, và **engine tính**: `VAT_HTCInvoice_Build_CalcForHDDTMultiX` vs
//    `VAT_HTCLDInvoice_Build_CalcForHDDTMultiX`). ⇒ Khác #B117/#B118 (song sinh **ngược nhau**).
//    ⚠️ **Hai điểm KHÔNG đổi tên theo pháp nhân — dễ tưởng là lỗi nhưng là nguồn thật:**
//      · bản **HTCLD** vẫn kiểm bảng đầu vào tên **`"VAT_HTCInvoice"`** (không phải `VAT_HTCLDInvoice`);
//      · bản **HTCLD** vẫn gọi **`VAT_HTCInvoiceApproveX`** (không có bản ApproveX riêng cho HTCLD).
//      ⇒ Hai pháp nhân **dùng chung bảng và chung hàm duyệt**; chỉ **engine tính HDDT** là riêng.
// 🔴 `strFlagUnapprove` **đảo nghĩa** như #B108: `bApprove = StringEqual(strFlagUnapprove, Inactive)`
//    ⇒ **`"0"` = ĐANG DUYỆT**, `"1"` = huỷ duyệt.
// 🔴 **BẪY TIỀM ẨN của nguồn (KHÔNG tự vá)**: `DataSet dsGetData_Output = null;` chỉ được gán **trong
//    `if (bApprove)`**, nhưng vùng `// Get:` bên dưới chạy **vô điều kiện** và truy cập
//    `dsGetData_Output.Tables[…]` ⇒ khi `FlagUnapprove = "1"` sẽ **NullReferenceException**.
//    Port trả **hai bảng rỗng** thay vì crash, và ghi cờ `unapproveWouldNreInSource`.
// 🔴 Khối `if (bApprove)` gọi `VAT_HTCInvoiceUpdateX` **bị comment toàn bộ** ⇒ chỉ còn `ApproveX`.
// 🔴 `StdDataInTable`: `StdParam` cho `HTCInvoiceCode` + `OS_HDDT_RefNo`, **`StdDate`** cho `HTCInvoiceDate`.
// 🔴 Đầu vào là **BẢNG**: thiếu ⇒ `…_HTCInvoiceTblNotFound`; **rỗng ⇒ TỪ CHỐI** (`…_HTCInvoiceTblInvalid`).
// 📌 **NỢ — KHÔNG ĐOÁN CÔNG THỨC**: hai engine `…_Build_CalcForHDDTMultiX` chưa có trong MiniHTC ⇒
//    `Invoice_Invoice` / `Invoice_InvoiceDtl` trả **rỗng**, cờ `hddtCalcSkipped`.
static async Task<IResult> HtcCalcBeforeApprAsync(
    List<string> htcInvoiceCodes, AppDbContext db, ITenantContext t,
    string? flagUnapprove, string phapNhan)
{
    var errPrefix = phapNhan == "HTCLD" ? "VAT_HTCLDInvoice_CalcBeforeAprr" : "VAT_HTCInvoice_CalcBeforeAprr";

    if (htcInvoiceCodes is null)
        return Results.BadRequest(new { error = errPrefix + "_Input_HTCInvoiceTblNotFound" });
    var codes = htcInvoiceCodes.Select(x => (x ?? "").Trim()).Where(x => x.Length > 0).Distinct().ToList();
    if (codes.Count == 0)
        return Results.BadRequest(new { error = errPrefix + "_Input_HTCInvoiceTblInvalid" });

    // 🔴 ĐẢO NGHĨA: "0" (hoặc bỏ trống) ⇒ ĐANG DUYỆT; "1" ⇒ huỷ duyệt.
    var flag = (flagUnapprove ?? "0").Trim();
    var bApprove = flag == "0";

    // 🔴 CẢ HAI pháp nhân đều đọc bảng "VAT_HTCInvoice" — nguồn KHÔNG đổi tên bảng theo pháp nhân.
    var invs = await db.VatHtcInvoices
        .Where(i => i.OrgId == t.OrgId && codes.Contains(i.HTCInvoiceCode)).ToListAsync();
    var missing = codes.Where(c => !invs.Any(i => i.HTCInvoiceCode == c)).ToList();

    var preview = new List<object>();
    if (bApprove)
        foreach (var inv in invs)
            preview.Add(new
            {
                inv.HTCInvoiceCode,
                statusBefore = inv.VatHTCStatus,
                statusIfApproved = "A",
                inv.HTCInvoiceDate, inv.OS_HDDT_InvoiceCode
            });

    // 🔴🔴 KHÔNG ghi gì: nguồn rollback trên đường thành công. Không gọi SaveChangesAsync.
    return Results.Ok(new
    {
        phapNhan, flagUnapprove = flag, bApprove,
        inputCount = codes.Count, foundCount = invs.Count, missing,
        preview,
        Invoice_Invoice = Array.Empty<object>(),
        Invoice_InvoiceDtl = Array.Empty<object>(),
        hddtCalcSkipped = true,
        dryRun = true,
        unapproveWouldNreInSource = !bApprove,
        dryRunNote = "CHAY THU - KHONG LUU. Duong 'Return Good' cua nguon goi RollbackSafety(_dbMain) + RollbackSafety(_dbWH), KHONG phai CommitSafety. Nguon CO goi VAT_HTCInvoiceApproveX (ghi that) NHUNG BEN TRONG transaction roi ROLLBACK => khong dong nao ton tai sau khi ham tra ve. Muc dich: TINH TRUOC ket qua duyet de nguoi dung xem; viec duyet that do ham KHAC lam. Doi chieu: ..._SaveAll (#B119) dung CommitSafety - CUNG FILE, HAI KIEU KET THUC KHAC NHAU. Day chinh la loi toi mac o #B108, da tu sua o #B120.",
        twinIdenticalNote = "HAI HAM (HTC :10196 va HTCLD :10413) GIONG NHAU 1:1 - diff toan than chi ra khac biet duy nhat la TEN (ten ham, ten hang loi) va ENGINE TINH: VAT_HTCInvoice_Build_CalcForHDDTMultiX vs VAT_HTCLDInvoice_Build_CalcForHDDTMultiX. Khac han #B117/#B118 (song sinh NGUOC NHAU).",
        sharedNamesNote = "HAI DIEM KHONG DOI TEN THEO PHAP NHAN - de tuong la loi nhung la nguon that: (1) ban HTCLD van kiem bang dau vao ten 'VAT_HTCInvoice' (khong phai VAT_HTCLDInvoice); (2) ban HTCLD van goi VAT_HTCInvoiceApproveX (khong co ban ApproveX rieng cho HTCLD). => Hai phap nhan DUNG CHUNG bang va CHUNG ham duyet; chi ENGINE TINH HDDT la rieng.",
        flagInvertedNote = "strFlagUnapprove DAO NGHIA: bApprove = StringEqual(strFlagUnapprove, TConst.Flag.Inactive) => '0' = DANG DUYET, '1' = HUY DUYET.",
        unapproveNreNote = "BAY TIEM AN cua nguon (KHONG tu va): 'DataSet dsGetData_Output = null;' chi duoc gan TRONG if (bApprove), nhung vung '// Get:' ben duoi chay VO DIEU KIEN va truy cap dsGetData_Output.Tables[...] => khi FlagUnapprove = '1' se NullReferenceException. Port tra HAI BANG RONG thay vi crash.",
        commentedUpdateNote = "Khoi if (bApprove) goi VAT_HTCInvoiceUpdateX BI COMMENT TOAN BO => chi con ApproveX chay.",
        stdNote = "StdDataInTable: StdParam cho HTCInvoiceCode + OS_HDDT_RefNo, StdDate cho HTCInvoiceDate.",
        hddtDebt = "NO - KHONG DOAN CONG THUC: hai engine ..._Build_CalcForHDDTMultiX chua co trong MiniHTC => Invoice_Invoice / Invoice_InvoiceDtl tra RONG."
    });
}

app.MapPost("/api/htcinvoices/calc-before-approve", async (
    List<string> htcInvoiceCodes, AppDbContext db, ITenantContext t, string? flagUnapprove) =>
    await HtcCalcBeforeApprAsync(htcInvoiceCodes, db, t, flagUnapprove, "HTC")).RequireAuthorization();

app.MapPost("/api/htcldinvoices/calc-before-approve", async (
    List<string> htcInvoiceCodes, AppDbContext db, ITenantContext t, string? flagUnapprove) =>
    await HtcCalcBeforeApprAsync(htcInvoiceCodes, db, t, flagUnapprove, "HTCLD")).RequireAuthorization();

// ===== #B123 LẤY SAO KÊ NGÂN HÀNG TỪ TCF — `OS_DMS_TCF_WA_Bank_BankStatementDtl_Get_New20210601` =====
// Trace LIVE: `BizHTC.TCFIntergration.cs:7427`. 3B đo thật, **khớp cả 2 máy**:
//   `7427/1350c81c9d76b77d1c2d62b4c7f5c67c`.
// 🔴 **Dữ liệu KHÔNG nằm ở DMS** — hàm chỉ **dựng mệnh đề lọc** rồi gọi
//   `OS_DMS_TCF_WA_Bank_BankStatementDtl_GetX` sang **hệ TCF** (`_strConfig_TCF_*`).
//   ⇒ MiniHTC chưa có kênh TCF ⇒ endpoint này **dựng đúng mệnh đề + giải ra danh sách tài khoản** rồi
//     trả về, **không tự gọi ra ngoài** (luật `C0-…quingentesimusseptimus`), cờ `tcfNotCalled`.
// 🔴 **BẮT BUỘC có bảng `Pmt_Payment` và KHÔNG được rỗng**: thiếu ⇒ `…_PmtPaymnetTblNotFound`
//   (⚠️ **tên hằng lỗi sai chính tả `PmtPaymnet`** — giữ nguyên để đối chiếu log);
//   rỗng ⇒ `…_PmtPaymnetTblInvalid`. Đây là **guard chống tìm trắng** — cấm nới lỏng.
// 🔴 **`strTypeApprAuto` BẮT BUỘC, chỉ HAI giá trị**, khác đi là **ném lỗi** (`…_TypeApprAutoInvalid`):
//     · `TConst.TypeApprTCF.ONline  = "ONLINE"`  ⇒ thêm `Bank_BankStatement.CreateBy **=** 'SA.BG.ALL'`
//     · `TConst.TypeApprTCF.OFFline = "OFFLINE"` ⇒ thêm `Bank_BankStatement.CreateBy **<>** 'SA.BG.ALL'`
//   ⚠️ Cùng lớp hằng **có `ALL = "ALL"` nhưng guard KHÔNG nhận** ⇒ truyền `"ALL"` là **lỗi**.
//     (Cùng khuôn #B118: `FlagisNone = "0"` cũng là hằng hợp lệ nhưng bị chặn.)
//   ⚠️ `'SA.BG.ALL'` là **tài khoản người tạo cắm cứng** — dấu hiệu "sao kê do máy nạp" (ONLINE).
// 🔴 **Mệnh đề thời gian LUÔN có** (không có nhánh bỏ qua):
//     `ThoiDiemGiaoDichDTime >= '{from}' and ThoiDiemGiaoDichDTime <= '{to}'`.
// 🔴 **Danh sách tài khoản nhận lấy từ DMS**, không do client gửi:
//     `select distinct f.BankAccountReceive from #input_Pmt_Payment pp inner join Pmt_Payment f
//      on pp.PaymentNo = f.PaymentNo where f.PaymentStatus **not in ('F')**`
//   ⇒ chỉ phiếu **chưa hoàn tất** mới được đối chiếu sao kê.
// 🔴🔴 **`in '{0}'` — CHUỖI GHÉP BỌC MỘT CẶP NHÁY, KHÔNG PHẢI IN-LIST**:
//     `… += " and Bank_BankStatementDtl.AccountNoBankNhan in '" + "a,b,c" + "'"`
//   ⇒ theo cú pháp SQL Server đây là **so sánh bằng với chuỗi `"a,b,c"`**, không phải tập hợp.
//     Có **đúng một** tài khoản thì vẫn đúng; từ **hai** trở lên thì phụ thuộc **bộ phân tích của TCF**.
//   📌 **NGHI VẤN, chưa kết luận** (mệnh đề chạy ở **hệ ngoài**, không phải SQL Server của DMS):
//     port dựng **y hệt** nguồn và **gắn cờ `inListSuspicious`** khi số tài khoản ≥ 2 — không tự sửa
//     thành `in ('a','b')` vì làm vậy là **đổi kết quả** so với hệ đang chạy.
//   ⚠️ Khối tương tự cho `PaymentCode` **bị comment** (`:7534-7549`) — cùng lỗi hình dạng, đã tắt.
// 🔴 Phân trang **vô hiệu**: `RecordStart = "0"`, `RecordCount = **"12345600"**` (số ma).
// 🔴 Kết quả TCF trả về phải có bảng `Bank_BankStatementDtl`, thiếu ⇒ `…_BankStatementDtlTblNotFound`.
app.MapPost("/api/tcf/bank-statement-dtl/build-query", async (
    TcfBankStatementQueryDto dto, AppDbContext db, ITenantContext t) =>
{
    // Bảng Pmt_Payment: thiếu ⇒ NotFound; RỖNG ⇒ TỪ CHỐI (guard chống tìm trắng).
    if (dto.PaymentNos is null)
        return Results.BadRequest(new { error = "OS_DMS_TCF_WA_Bank_BankStatementDtl_Get_PmtPaymnetTblNotFound" });
    var paymentNos = dto.PaymentNos.Select(x => (x ?? "").Trim()).Where(x => x.Length > 0).Distinct().ToList();
    if (paymentNos.Count == 0)
        return Results.BadRequest(new { error = "OS_DMS_TCF_WA_Bank_BankStatementDtl_Get_PmtPaymnetTblInvalid" });

    // 🔴 TypeApprAuto: CHỈ "ONLINE" / "OFFLINE"; "ALL" tuy là hằng cùng lớp nhưng BỊ CHẶN.
    var typeAppr = (dto.TypeApprAuto ?? "").Trim().ToUpperInvariant();
    if (!(typeAppr == "ONLINE" || typeAppr == "OFFLINE"))
        return Results.BadRequest(new
        {
            error = "OS_DMS_TCF_WA_Bank_BankStatementDtl_Get_TypeApprAutoInvalid",
            check = new { TypeApprAuto = typeAppr },
            vocabNote = "TConst.TypeApprTCF: ALL='ALL' | ONline='ONLINE' | OFFline='OFFLINE'. Guard CHI nhan ONLINE/OFFLINE => 'ALL' BI CHAN du la hang cung lop (cung khuon #B118 voi FlagisNone)."
        });

    // 🔴 Tài khoản nhận LẤY TỪ DMS (không do client gửi), chỉ phiếu PaymentStatus not in ('F').
    var accounts = await db.PmtPayments
        .Where(p => p.OrgId == t.OrgId && paymentNos.Contains(p.PaymentNo) && p.PaymentStatus != "F")
        .Select(p => p.BankAccountReceive)
        .Where(a => a != null && a != "")
        .Distinct().ToListAsync();

    var from = (dto.DateTimeFrom ?? "").Trim();
    var to = (dto.DateTimeTo ?? "").Trim();

    // 🔴 Dựng Y HỆT nguồn — kể cả `in '<chuỗi ghép>'`.
    var where = $"Bank_BankStatementDtl.ThoiDiemGiaoDichDTime >= '{from}' "
              + $" and Bank_BankStatementDtl.ThoiDiemGiaoDichDTime <= '{to}' ";
    var accountList = string.Join(",", accounts);
    if (accountList.Length > 0)
        where += $" and Bank_BankStatementDtl.AccountNoBankNhan in '{accountList}'";
    where += typeAppr == "ONLINE"
        ? " and Bank_BankStatement.CreateBy = 'SA.BG.ALL'"
        : " and Bank_BankStatement.CreateBy <> 'SA.BG.ALL'";

    return Results.Ok(new
    {
        typeApprAuto = typeAppr,
        paymentNoCount = paymentNos.Count,
        bankAccountReceive = accounts,
        dateTimeFrom = from, dateTimeTo = to,
        whereClause = where,
        recordStart = "0", recordCount = "12345600",
        Bank_BankStatementDtl = Array.Empty<object>(),
        tcfNotCalled = true,
        inListSuspicious = accounts.Count >= 2,
        remoteNote = "Du lieu KHONG nam o DMS: ham chi DUNG MENH DE LOC roi goi OS_DMS_TCF_WA_Bank_BankStatementDtl_GetX sang he TCF (_strConfig_TCF_*). MiniHTC chua co kenh TCF => endpoint dung dung menh de + giai ra danh sach tai khoan roi TRA VE, KHONG tu goi ra ngoai (luat C0-...quingentesimusseptimus).",
        guardNote = "BAT BUOC co bang Pmt_Payment va KHONG duoc rong: thieu => _PmtPaymnetTblNotFound (TEN HANG LOI SAI CHINH TA 'PmtPaymnet' - giu nguyen de doi chieu log); rong => _PmtPaymnetTblInvalid. Day la GUARD CHONG TIM TRANG - cam noi long.",
        typeApprNote = "strTypeApprAuto BAT BUOC, chi HAI gia tri, khac di la NEM LOI: ONLINE => them Bank_BankStatement.CreateBy = 'SA.BG.ALL'; OFFLINE => them CreateBy <> 'SA.BG.ALL'. 'SA.BG.ALL' la tai khoan nguoi tao CAM CUNG - dau hieu 'sao ke do may nap' (ONLINE).",
        accountSourceNote = "Danh sach tai khoan nhan LAY TU DMS, khong do client gui: 'select distinct f.BankAccountReceive from #input_Pmt_Payment pp inner join Pmt_Payment f on pp.PaymentNo = f.PaymentNo where f.PaymentStatus NOT IN (F)' => chi phieu CHUA HOAN TAT moi duoc doi chieu sao ke.",
        inListSuspiciousNote = "NGHI VAN (chua ket luan): nguon ghep 'AccountNoBankNhan in ' + 'a,b,c' + ' ' - BOC MOT CAP NHAY, KHONG PHAI IN-LIST. Theo cu phap SQL Server day la SO SANH BANG voi chuoi 'a,b,c'. Co DUNG MOT tai khoan thi van dung; tu HAI tro len thi phu thuoc bo phan tich cua TCF (menh de chay o HE NGOAI, khong phai SQL Server cua DMS). Port dung Y HET nguon va gan co inListSuspicious khi so tai khoan >= 2 - KHONG tu sua thanh in ('a','b') vi lam vay la DOI KET QUA so voi he dang chay. Khoi tuong tu cho PaymentCode (:7534-7549) BI COMMENT - cung loi hinh dang, da tat.",
        pagingNote = "Phan trang VO HIEU: RecordStart='0', RecordCount='12345600' (so ma).",
        outputNote = "Ket qua TCF tra ve phai co bang Bank_BankStatementDtl, thieu => _BankStatementDtlTblNotFound."
    });
}).RequireAuthorization();

// ===== #B124 BÁO CÁO XE TỒN TẠI ĐẠI LÝ — `Rpt_SummaryCarAtDealer_Add` / `…_AddX` =====
// Trace LIVE: `BizHTC.Report.cs:36946` (cửa) → **`Rpt_SummaryCarAtDealer_AddX`** (`:37062`, thân thật)
//   → SQL `RptSQLQuery.mySql_Rpt_SummaryCarAtDealer_Add()` (`:24934`, **~1060 dòng**).
//   3B đo thật, **khớp cả 2 máy**: `37062/7d3e9fa00e5d7ad33ba21894d4836398`.
// 🔴🔴 **RBAC — CA THỨ 22, kiểu "lời giải thích còn, bộ lọc mất"**:
//    Trong SQL còn nguyên chú thích **`-- Must inner join to filter AbilityOfUser`** ngay trên
//    `inner join Mst_Dealer md on cc.DealerCode = md.DealerCode` — nhưng điều kiện thật
//    **`--and (md.BUCode like @strBUPatternOfUser)` ĐÃ BỊ COMMENT**; và trong C#
//    `//DataRow drAbilityOfUser = myCommon_GetAbilityOfUser(strPartnerUserCode);` **cũng bị comment**.
//    ⇒ `inner join` còn đó nhưng **không lọc quyền gì nữa**; nó chỉ còn tác dụng loại đại lý không tồn tại.
//    ⚠️ Thay vào đó **phạm vi bị CẮM CỨNG `"HTC%"`** ở hai chỗ dựng CarID
//      (`zzB_tbl_Dlr_Contract_GenCarId_zzE(…, "HTC%", …)` và `…SalesOrderRoot…(…, "HTC%", …)`).
//    📌 **KHÔNG tự vá** — chỉ mở cờ đo `enforceBuScope`.
// 🔴 **LỌC NGƯỢC (nguồn tự chú thích `(*) Sử dụng kỹ thuật Lọc Ngược`)**: `left join` bảng
//    `#tbl_CDOD_Active` rồi **`where cdod.CarId is null`** ⇒ **giữ xe CHƯA có lệnh xuất kho đang hiệu
//    lực**. `#tbl_CDOD_Active` = `mySql_Car_DeliveryOrderDetail_FilterActive_01(` **`and (cdod.DeliveryOutDate <= @strTDate)`** `)`
//    ⇒ "đã xuất kho **tính đến ngày báo cáo**". Port bằng `inner join` là **đảo ngược báo cáo**.
// 🔴 **BỐN điều kiện giữ xe** (ngoài lọc ngược): `cc.FlagActive = '1'` · `cc.FlagEarlyCancel = '0'`
//    · `sdm.DlvMnNo is null` (chưa có biên bản giao xe hợp lệ) · `md.FlagActive = '1'`
//    (chú thích nguồn *"Thomptt: 20180522: Chỉ lấy đại lý trạng thái active"*).
//    ⚠️ `--and (vms.DeliveryOutDate is null)` **bị comment** ⇒ `VIN_MyStatus` join vào nhưng **không lọc**.
// 🔴 **Biên bản giao xe (`Sto_DlvMinutes`) chỉ tính khi khớp CẢ BỐN**: `sdm.VIN = cc.VIN` **và**
//    `cdod_t.DeliveryOrderNo = sdm.RefOrdNo` **và** `sdm.TranspReqType = 'CARTRANSPORT'` **và**
//    cặp trạng thái `(F='A' và T='A')` **hoặc** `(F='A' và T='P')` — **không có** cặp `(P, *)`.
// 🔴 **Ngày mặc định khi bỏ trống**: `TDate_From` ⇒ `DateTimeSpecial.DateMin`,
//    `TDate_To` ⇒ `DateTimeSpecial.DateMax` ⇒ **cho phép tìm trắng** (khác các hàm có guard).
//    Rồi ghép cứng `From + " 00:00:00"`, `To + " 23:59:59"`.
// 🔴 **Mốc tuần tính từ CHỦ NHẬT đầu tuần hiện tại**, không phải từ hôm nay:
//    `dtimeTDate_BeginThisWeek = TDate - GetDayOfWeek(TDate, DayOfWeek.Sunday)`, rồi `+7` và `+14`.
// 🔴 **Ba bảng ra**, bảng thứ ba **có điều kiện**: `Rpt_SummaryCarAtDealer` ·
//    `…_GroupBySpec` · và **chỉ khi `strIsGetDetail = TConst.Flag.Active`** thì mới có `…_Detail`.
// 📌 **NỢ — KHÔNG ĐOÁN CÔNG THỨC** (để `null`, có cờ):
//    · ba mảnh caching thanh toán (`…_Temp` `'A','F'` · `…_Deposit` `'A','F'` · `…_A_Deposit` `'A','F'`)
//      ⇒ `DutyCompletedPercent = (Deposit + GuaranteeValue) / UnitPriceActual * 100` **để null**;
//    · `DateDiff(day, cc.DepositDutyEndDate, @strTDate) DutyDays` cần cột nguồn chưa có;
//    · `VIN_MyStatus`, `Sto_DlvMinutes` (thiếu `FDlvMnStatus`/`TDlvMnStatus`/`RefOrdNo`/`TranspReqType`),
//      `Car_DeliveryOrderDetail`, hai bảng CarID sinh động ⇒ các cột tương ứng **để null**.
//    ⚠️ Nguồn còn **trộn tham số nướng và tham số chạy**: `@strReportMonth` bị `Replace` thành
//      `DateTime.Now.AddMonths(-1).ToString("yyyy-MM-01")` trong khi `@strTDate` là **param runtime**
//      ⇒ đúng cảnh báo `[BAKE-PARAM-MIX]` đã ghi nhớ; ghi lại, **không sửa**.
// 🔴 **Lọc KHU VỰC đi qua HAI CHẶNG, không phải một cột trên đại lý**:
//    `Mst_Dealer.ProvinceCode → Mst_Province.AreaCode → Mst_Area.AreaRootCode → Mst_Area.AreaCode`
//    (`inner join Mst_Area marea on marea.AreaCode = mpv.AreaCode` rồi
//     `inner join Mst_Area marea1 on marea.AreaRootCode = marea1.AreaCode`)
//    ⇒ `strAreaCode` so với **KHU VỰC GỐC** (`marea1`), **không phải** khu vực trực tiếp của tỉnh.
//    So sánh theo khuôn `('strAreaCode' = '' or marea1.AreaCode = 'strAreaCode')` ⇒ **rỗng = bỏ lọc**.
//    ⚠️ Ở đây chú thích `--and (md.BUCode like @strBUPatternOfUser)  -- filter AbilityOfUser` **lặp lại
//      lần thứ ba** trong cùng câu SQL — cùng một bộ lọc quyền bị tắt ở **ba** chỗ.
app.MapGet("/api/reports/summary-car-at-dealer", async (
    AppDbContext db, ITenantContext t,
    string? dealerCode, string? areaCode, string? tDateFrom, string? tDateTo,
    string? isGetDetail, string? enforceBuScope, string? buPattern) =>
{
    // 🔴 Bỏ trống ⇒ DateMin / DateMax (cho phép tìm trắng — đúng nguồn).
    var from = string.IsNullOrWhiteSpace(tDateFrom) ? new DateTime(1900, 1, 1) : DateTime.Parse(tDateFrom).Date;
    var to = string.IsNullOrWhiteSpace(tDateTo) ? new DateTime(9999, 12, 31) : DateTime.Parse(tDateTo).Date;
    var tDate = DateTime.Now.Date;

    // 🔴 Mốc tuần tính từ CHỦ NHẬT đầu tuần hiện tại.
    var beginThisWeek = tDate.AddDays(-(int)tDate.DayOfWeek);
    var next1Week = beginThisWeek.AddDays(7);
    var next2Week = beginThisWeek.AddDays(14);

    var dealers = await db.Dealers
        .Where(d => d.OrgId == t.OrgId && d.FlagActive == "1")   // md.FlagActive = '1'
        .Select(d => new { d.DealerCode, d.DealerName, d.ProvinceCode, d.BUCode }).ToListAsync();
    if (!string.IsNullOrWhiteSpace(dealerCode))
        dealers = dealers.Where(d => d.DealerCode == dealerCode.Trim()).ToList();
    // 🔴 KHU VỰC đi qua HAI CHẶNG, KHÔNG phải cột trên đại lý:
    //   `Mst_Dealer.ProvinceCode → Mst_Province.AreaCode → Mst_Area.AreaRootCode → Mst_Area.AreaCode`
    //   ⇒ tham số `strAreaCode` so với **KHU VỰC GỐC** (`marea1`), không phải khu vực trực tiếp của tỉnh.
    var provinces = (await db.MstProvinces.Where(p => p.OrgId == t.OrgId)
        .Select(p => new { p.ProvinceCode, p.AreaCode }).ToListAsync())
        .GroupBy(p => p.ProvinceCode).ToDictionary(g => g.Key, g => g.First().AreaCode ?? "");
    var areaRootOf = (await db.Areas.Where(a => a.OrgId == t.OrgId)
        .Select(a => new { a.AreaCode, a.AreaRootCode }).ToListAsync())
        .GroupBy(a => a.AreaCode).ToDictionary(g => g.Key, g => g.First().AreaRootCode ?? "");
    string RootAreaOfDealer(string? provinceCode)
    {
        var ac = provinces.TryGetValue(provinceCode ?? "", out var a) ? a : "";
        return areaRootOf.TryGetValue(ac, out var r) ? r : "";
    }
    if (!string.IsNullOrWhiteSpace(areaCode))
        dealers = dealers.Where(d => RootAreaOfDealer(d.ProvinceCode) == areaCode.Trim()).ToList();

    // 📌 Cờ ĐO, mặc định TẮT: nguồn KHÔNG lọc quyền (điều kiện BUCode bị comment).
    var scoped = enforceBuScope == "1";
    var pattern = (buPattern ?? "HTC").Trim();
    if (scoped) dealers = dealers.Where(d => (d.BUCode ?? "").StartsWith(pattern)).ToList();

    var dealerCodes = dealers.Select(d => d.DealerCode).ToList();

    // 🔴 BỐN điều kiện giữ xe + LỌC NGƯỢC lệnh xuất kho.
    var cars = await db.CarVinMasters
        .Where(c => c.OrgId == t.OrgId
                    && c.FlagActive == "1"
                    && (c.FlagEarlyCancel ?? "0") == "0"
                    && c.DealerCode != null && dealerCodes.Contains(c.DealerCode))
        .ToListAsync();

    // LỌC NGƯỢC: xe ĐÃ xuất kho tính đến @strTDate thì LOẠI.
    var deliveredVins = (await db.DeliveryOrderCars
        .Where(x => x.OrgId == t.OrgId && x.DeliveryOutDate != null && x.DeliveryOutDate <= tDate)
        .Select(x => x.Vin).ToListAsync()).ToHashSet();
    cars = cars.Where(c => !deliveredVins.Contains(c.VIN)).ToList();

    var dealerMap = dealers.ToDictionary(d => d.DealerCode, d => d);
    var specs = (await db.CarSpecs.Where(s => s.OrgId == t.OrgId)
        .Select(s => new { s.SpecCode, s.SpecDesc }).ToListAsync())
        .GroupBy(s => s.SpecCode).ToDictionary(g => g.Key, g => g.First().SpecDesc);

    var rows = cars.Select(c => new
    {
        CarId = c.VIN, c.VIN, c.SpecCode, c.ModelCode, c.ColorCode,
        CCDealerCode = c.DealerCode,
        CCDealerName = dealerMap.TryGetValue(c.DealerCode ?? "", out var d) ? d.DealerName : null,
        MCSSpecDescription = specs.TryGetValue(c.SpecCode ?? "", out var sd) ? sd : null,
        c.SOCode, c.PackingListNo, c.StorageCodeCurrent,
        // 📌 NỢ — không đoán công thức:
        DutyDays = (int?)null,
        DutyCompletedPercent = (decimal?)null,
        PMPDAmountTotal_Deposit = (decimal?)null,
        OSODApprovedDate = (DateTime?)null,
        SDMDlvStartDate = (DateTime?)null,
        SDMDlvEndDate = (DateTime?)null,
        DLSDDealerCodeSource = (string?)null
    }).ToList();

    var groupBySpec = rows.GroupBy(r => r.SpecCode ?? "")
        .Select(g => new { SpecCode = g.Key, Qty = g.Count() })
        .OrderBy(x => x.SpecCode).ToList();

    var wantDetail = isGetDetail == "1";

    return Results.Ok(new
    {
        tDateFrom = from, tDateTo = to, tDate,
        beginThisWeek, next1Week, next2Week,
        dealerCount = dealers.Count, count = rows.Count,
        Rpt_SummaryCarAtDealer = rows,
        Rpt_SummaryCarAtDealer_GroupBySpec = groupBySpec,
        Rpt_SummaryCarAtDealer_Detail = wantDetail ? rows : null,
        isGetDetail = wantDetail,
        enforceBuScope = scoped, buPattern = pattern,
        paymentCachingSkipped = true,
        areaChainNote = "Loc KHU VUC di qua HAI CHANG, khong phai mot cot tren dai ly: Mst_Dealer.ProvinceCode -> Mst_Province.AreaCode -> Mst_Area.AreaRootCode -> Mst_Area.AreaCode ('inner join Mst_Area marea on marea.AreaCode = mpv.AreaCode' roi 'inner join Mst_Area marea1 on marea.AreaRootCode = marea1.AreaCode') => strAreaCode so voi KHU VUC GOC (marea1), KHONG phai khu vuc truc tiep cua tinh. Khuon so sanh ('strAreaCode' = '' or marea1.AreaCode = 'strAreaCode') => RONG = BO LOC. Chu thich '--and (md.BUCode like @strBUPatternOfUser) -- filter AbilityOfUser' LAP LAI LAN THU BA trong cung cau SQL - mot bo loc quyen bi tat o BA cho.",
        rbacHole = "CA THU 22, kieu 'LOI GIAI THICH CON, BO LOC MAT': trong SQL con nguyen chu thich '-- Must inner join to filter AbilityOfUser' ngay tren 'inner join Mst_Dealer md on cc.DealerCode = md.DealerCode', nhung dieu kien that '--and (md.BUCode like @strBUPatternOfUser)' DA BI COMMENT; va trong C# '//DataRow drAbilityOfUser = myCommon_GetAbilityOfUser(...)' cung bi comment. => inner join con do nhung KHONG LOC QUYEN gi nua. Thay vao do pham vi bi CAM CUNG 'HTC%' o hai cho dung CarID. KHONG tu va - chi mo co do enforceBuScope.",
        reverseFilterNote = "LOC NGUOC (nguon tu chu thich '(*) Su dung ky thuat Loc Nguoc'): left join #tbl_CDOD_Active roi 'where cdod.CarId is null' => GIU xe CHUA co lenh xuat kho dang hieu luc. #tbl_CDOD_Active = mySql_Car_DeliveryOrderDetail_FilterActive_01('and (cdod.DeliveryOutDate <= @strTDate)') => 'da xuat kho TINH DEN NGAY BAO CAO'. Port bang inner join la DAO NGUOC BAO CAO.",
        fourConditionsNote = "BON dieu kien giu xe (ngoai loc nguoc): cc.FlagActive='1'; cc.FlagEarlyCancel='0'; sdm.DlvMnNo is null (chua co bien ban giao xe hop le); md.FlagActive='1' (chu thich nguon 'Thomptt: 20180522: Chi lay dai ly trang thai active'). Rieng '--and (vms.DeliveryOutDate is null)' BI COMMENT => VIN_MyStatus join vao nhung KHONG loc.",
        dlvMinutesJoinNote = "Bien ban giao xe (Sto_DlvMinutes) CHI tinh khi khop CA BON: sdm.VIN = cc.VIN VA cdod_t.DeliveryOrderNo = sdm.RefOrdNo VA sdm.TranspReqType = 'CARTRANSPORT' VA cap trang thai (F='A' va T='A') HOAC (F='A' va T='P') - KHONG co cap (P, *).",
        dateDefaultNote = "Ngay mac dinh khi bo trong: TDate_From => TConst.DateTimeSpecial.DateMin, TDate_To => DateMax => CHO PHEP TIM TRANG (khac cac ham co guard). Roi ghep cung From + ' 00:00:00', To + ' 23:59:59'.",
        weekNote = "Moc tuan tinh tu CHU NHAT DAU TUAN HIEN TAI, khong phai tu hom nay: BeginThisWeek = TDate - GetDayOfWeek(TDate, DayOfWeek.Sunday), roi +7 va +14.",
        threeTablesNote = "BA bang ra, bang thu ba CO DIEU KIEN: Rpt_SummaryCarAtDealer; ..._GroupBySpec; va CHI KHI strIsGetDetail = TConst.Flag.Active moi co ..._Detail.",
        debtNote = "NO - KHONG DOAN CONG THUC (de null): ba manh caching thanh toan => DutyCompletedPercent = (Deposit + GuaranteeValue) / UnitPriceActual * 100 de NULL; DateDiff(day, cc.DepositDutyEndDate, @strTDate) DutyDays can cot nguon chua co; VIN_MyStatus, Sto_DlvMinutes (thieu FDlvMnStatus/TDlvMnStatus/RefOrdNo/TranspReqType), Car_DeliveryOrderDetail, hai bang CarID sinh dong => cac cot tuong ung de null.",
        bakeParamMixNote = "Nguon TRON tham so NUONG va tham so CHAY: '@strReportMonth' bi Replace thanh DateTime.Now.AddMonths(-1).ToString('yyyy-MM-01') trong khi '@strTDate' la param runtime => dung canh bao [BAKE-PARAM-MIX] da ghi nho. Ghi lai, KHONG sua."
    });
}).RequireAuthorization();

// ===== #B125 TẦNG CACHING THANH TOÁN (trả nợ tồn) — `mySql_GetClauseSelect_CachingForPaymentTotal`
//       và `…CachingForPaymentAccum` (`TERP.BizHTC.SQLQuery/CommonSQLQuery.cs`) =====
// 📌 Đây là **món nợ đã ghi từ #B114/#B124** ("tầng thanh toán chưa có ⇒ mọi cột tiền null").
//   Nay đọc được **trọn công thức** nên **trả nợ**, không còn phải để null.
// 🔴 **CÔNG THỨC ĐÚNG NGUYÊN VĂN**:
//      `select t.CarId, **Sum(pmpd.Amount) AmountTotal**, **Max(pmp.PaymentEndDate) PaymentEndDateMax**`
//      `from <bảng xe đã lọc> t inner join Pmt_PaymentDetail pmpd on t.CarId = pmpd.CarId`
//      `                        inner join Pmt_Payment pmp       on pmpd.PaymentNo = pmp.PaymentNo`
//      `where (pmp.PaymentStatus **in (<danh sách>)**) <và tuỳ chọn `and (pmpd.GuaranteeNo is null)`>`
//      `group by t.CarId`
//   ⚠️ **`inner join` hai lớp** ⇒ xe **không có** thanh toán nào khớp trạng thái thì **không có dòng**
//     trong bảng tạm ⇒ ở báo cáo nó `left join` vào và ra **NULL**, rồi mới `IsNull(...,0)`.
//     Port bằng `Sum(...)` mặc định 0 ngay từ đầu là **không phân biệt được "chưa trả" với "trả 0"**.
// 🔴🔴 **THAM SỐ `bGuaranteeNoBeNull` LÀ ĐỊNH NGHĨA "TIỀN CỌC"**:
//      `true` ⇒ thêm **`and (pmpd.GuaranteeNo is null)`** — tức **cọc = khoản thanh toán KHÔNG gắn
//      bảo lãnh**. Bỏ điều kiện này là **gộp cả tiền bảo lãnh vào tiền cọc**.
// 🔴🔴 **CÙNG MỘT HÀM, MỖI BÁO CÁO GỌI VỚI BỘ LỌC TRẠNG THÁI KHÁC NHAU** — số liệu **cố ý khác**:
//      · #B114 `CarCarGetList`      : Total `'A','F'` · Deposit `'A','F'` · A_Deposit `'A','F'`
//      · #B124 `SummaryCarAtDealer` : Total `'A','F'` · Deposit `'A','F'` · A_Deposit `'A','F'`
//      · #B126 `RptPayment_01`      : Total **`'F'`**  · Deposit **`'F'`**  (Accum `'F'`)
//      · #B127 `RptPayment_01_Mst`  : Total **`'F'`**  · Deposit **`'A','F'`**  ← xem #B127
//   ⇒ **Không được dùng một hàm chung "tính tiền cọc" cho mọi báo cáo.**
static async Task<Dictionary<string, (decimal AmountTotal, DateTime? PaymentEndDateMax)>>
    CachingForPaymentTotalAsync(AppDbContext db, Guid orgId, List<string> carIds,
                                string[] statusList, bool guaranteeNoBeNull)
{
    var q = from d in db.PmtPaymentDetails
            join p in db.PmtPayments on d.PaymentNo equals p.PaymentNo
            where d.OrgId == orgId && p.OrgId == orgId
                  && d.CarId != null && carIds.Contains(d.CarId)
                  && statusList.Contains(p.PaymentStatus)
            select new { d.CarId, d.Amount, d.GuaranteeNo, p.PaymentEndDate };
    // 🔴 "Tiền cọc" = thanh toán KHÔNG gắn bảo lãnh.
    if (guaranteeNoBeNull) q = q.Where(x => x.GuaranteeNo == null || x.GuaranteeNo == "");
    var raw = await q.ToListAsync();
    return raw.GroupBy(x => x.CarId!)
        .ToDictionary(g => g.Key,
            g => (g.Sum(x => x.Amount ?? 0m),
                  g.Where(x => x.PaymentEndDate != null).Select(x => x.PaymentEndDate).DefaultIfEmpty(null).Max()));
}

// ===== #B126/#B127 BÁO CÁO THANH TOÁN 01 — `RptPayment_01_New20260514` và `…_New20260514_Mst` =====
// Trace LIVE: WS64 `:30096` → `_biz.RptPayment_01_New20260514` (`DataWH/BizHTC.zTemp.cs:23162`);
//   WS64 `:30208` → `_biz.RptPayment_01_New20260514_Mst` (`:24757`).
//   3B đo thật, **khớp cả 2 máy**: `23162/f12f2b609d2b2a669d7eedc14695a17f` ·
//   `24757/fe6bbc6645915e026ef43fa01b311373`.
// ✅ **PHẢN VÍ DỤ LÀNH MẠNH VỀ RBAC** (hiếm, ghi lại để đối chiếu với 22 ca lỗ đã thống kê):
//    `DataRow drAbilityOfUser = myCommon_GetAbilityOfUser(strPartnerUserCode);` **KHÔNG bị comment**,
//    và `alParamsCoupleSql.AddRange(new object[]{ "@strBUPatternOfUser", drAbilityOfUser["BUPattern"] });`
//    **bind quyền THẬT**; thêm `myCommon_CheckHTCDirect(...)`. ⇒ Báo cáo này **có lọc phạm vi đúng**.
// 🔴🔴 **HAI CỬA CỦA CÙNG MỘT BÁO CÁO TÍNH TIỀN CỌC KHÁC NHAU** — đối chiếu từng dòng:
//      · bản **chi tiết** (`:23283`): `CachingForPaymentTotal(#tbl_…_Deposit, **"'F'"**, true)`
//        — chú thích *"Chỉ xét Thanh toán Cọc ('F')"*;
//      · bản **master** (`:24882`): `CachingForPaymentTotal(#tbl_…_Deposit, **"'A','F'"**, true)`
//        — chú thích *"…('A','F') **//20210601 thêm trạng thái A**"*.
//    ⇒ Thay đổi 2021 **chỉ áp vào bản master, KHÔNG lan sang bản chi tiết** ⇒ **tổng ở master có thể
//      LỚN HƠN tổng cộng dồn của chi tiết**, đúng bằng phần cọc đang ở trạng thái `'A'` (đã duyệt,
//      chưa hoàn tất). **Cả hai SQL đều thật sự dùng bảng này** (mỗi bên 3 lần) nên chênh lệch là **có
//      hiệu lực**, không phải mã chết.
//    📌 **KHÔNG tự đồng bộ** — đây là quyết định nghiệp vụ; port giữ **đúng từng bên** và trả
//      `depositStatusFilter` để người dùng thấy ngay mình đang xem con số theo bộ lọc nào.
// 🔴 `strZoneCode`: `IsNullOrEmpty ? "" : StandardizeParam(...)` ⇒ **chuẩn hoá về CHUỖI RỖNG, không
//    để NULL** — đúng khuôn tránh bẫy `@strZoneCode = NULL` làm mất sạch dòng (đã ghi nhớ riêng).
// 🔴 **17 tham số lọc đều đi qua `BuildClause("and", "<cột>", <danh sách>, "@p", ref params)`** ⇒
//    danh sách rỗng ⇒ **bỏ hẳn mệnh đề** (không phải `in ()`).
// 📌 **NỢ còn lại** (không đoán): `mySql_GetClauseSelect_Mst_Calendar_GetForDayT` (bảng tham số ngày
//    làm việc), `RatioDebtPolicy_V20`, `GetDiscountOfCar_02_Dtl`, `Pmt_Guarantee` ⇒ các cột chính sách
//    công nợ / chiết khấu / bảo lãnh để **null**.
static async Task<IResult> RptPayment01Async(
    AppDbContext db, ITenantContext t, string? dealerCode, string? soCode, string? modelCode,
    string? zoneCode, string? enforceBuScope, string? buPattern, bool isMst)
{
    // 🔴 Zone: chuẩn hoá về "" chứ KHÔNG để null.
    var zone = (zoneCode ?? "").Trim();

    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId).ToListAsync();
    if (!string.IsNullOrWhiteSpace(dealerCode)) cars = cars.Where(c => c.DealerCode == dealerCode.Trim()).ToList();
    if (!string.IsNullOrWhiteSpace(soCode)) cars = cars.Where(c => c.SOCode == soCode.Trim()).ToList();
    if (!string.IsNullOrWhiteSpace(modelCode)) cars = cars.Where(c => c.ModelCode == modelCode.Trim()).ToList();

    // 🔴🔴 CỔNG VÙNG (#B128 bổ sung cho cả ba cửa — đọc kỹ template SQL mới thấy):
    //   `left join Mst_DealerZone mdz on md.DealerCode = mdz.DealerCode`
    //   `left join Mst_Zone mz on mdz.ZoneCode = mz.ZoneCode`
    //   `where … and (@strZoneCode = '' or mdz.ZoneCode = @strZoneCode)`
    //   `      and mdz.FlagActive = '1'`
    // ⚠️ `mdz.FlagActive = '1'` nằm ở **WHERE** trên một **`left join`** ⇒ **biến thành `inner join`
    //   trên thực tế**: đại lý **không có dòng vùng đang hiệu lực** thì **BỊ LOẠI KHỎI BÁO CÁO**,
    //   kể cả khi `@strZoneCode` rỗng. Đây **không phải** "bỏ lọc khi rỗng".
    var zoneRows = await db.DealerZones
        .Where(z => z.OrgId == t.OrgId && z.FlagActive == "1")
        .Select(z => new { z.DealerCode, z.ZoneCode }).ToListAsync();
    var zoneOfDealer = zoneRows.GroupBy(z => z.DealerCode).ToDictionary(g => g.Key, g => g.First().ZoneCode);
    cars = cars.Where(c =>
    {
        if (!zoneOfDealer.TryGetValue(c.DealerCode ?? "", out var zc)) return false;   // FlagActive='1' ở WHERE
        return zone.Length == 0 || zc == zone;
    }).ToList();

    // ✅ Nguồn bind quyền THẬT ở báo cáo này; MiniHTC chưa có bảng quyền ⇒ cờ đo.
    var scoped = enforceBuScope == "1";
    if (scoped)
    {
        var pat = (buPattern ?? "HTC").Trim();
        var okDealers = (await db.Dealers.Where(d => d.OrgId == t.OrgId)
            .Select(d => new { d.DealerCode, d.BUCode }).ToListAsync())
            .Where(d => (d.BUCode ?? "").StartsWith(pat)).Select(d => d.DealerCode).ToHashSet();
        cars = cars.Where(c => okDealers.Contains(c.DealerCode ?? "")).ToList();
    }

    var carIds = cars.Select(c => c.VIN).ToList();

    // 🔴 BỘ LỌC TRẠNG THÁI KHÁC NHAU GIỮA HAI CỬA — đây là điểm cốt tử của cặp này.
    var depositStatus = isMst ? new[] { "A", "F" } : new[] { "F" };
    var total = await CachingForPaymentTotalAsync(db, t.OrgId, carIds, new[] { "F" }, false);
    var deposit = await CachingForPaymentTotalAsync(db, t.OrgId, carIds, depositStatus, true);

    var rows = cars.Select(c =>
    {
        var hasTotal = total.TryGetValue(c.VIN, out var tt);
        var hasDep = deposit.TryGetValue(c.VIN, out var dp);
        return new
        {
            CarId = c.VIN, c.VIN, c.SpecCode, c.ModelCode, c.ColorCode, c.DealerCode, c.SOCode,
            c.FlagEarlyCancel, c.FlagisHTC,
            // 🔴 Không có dòng trong bảng tạm ⇒ NULL (khác hẳn "đã trả 0").
            PmtAmountTotal = hasTotal ? tt.AmountTotal : (decimal?)null,
            PmtPaymentEndDateMax = hasTotal ? tt.PaymentEndDateMax : null,
            PmtDepositTotal = hasDep ? dp.AmountTotal : (decimal?)null,
            PmtDepositEndDateMax = hasDep ? dp.PaymentEndDateMax : null,
            // 📌 NỢ còn lại — không đoán công thức:
            RatioDebtPolicy = (decimal?)null,
            DiscountOfCar_02_Dtl = (decimal?)null,
            GuaranteeValue = (decimal?)null,
            DateDayT = (DateTime?)null
        };
    }).ToList();

    return Results.Ok(new
    {
        variant = isMst ? "Mst" : "Detail",
        zoneCode = zone,
        count = rows.Count,
        items = rows,
        depositStatusFilter = depositStatus,
        totalStatusFilter = new[] { "F" },
        enforceBuScope = scoped,
        cachingFormulaNote = "CONG THUC DUNG NGUYEN VAN: select t.CarId, Sum(pmpd.Amount) AmountTotal, Max(pmp.PaymentEndDate) PaymentEndDateMax from <bang xe da loc> t inner join Pmt_PaymentDetail pmpd on t.CarId = pmpd.CarId inner join Pmt_Payment pmp on pmpd.PaymentNo = pmp.PaymentNo where pmp.PaymentStatus in (<ds>) [and pmpd.GuaranteeNo is null] group by t.CarId. INNER JOIN HAI LOP => xe khong co thanh toan khop trang thai thi KHONG CO DONG trong bang tam => bao cao left join vao va ra NULL, roi moi IsNull(...,0). Port de mac dinh 0 ngay tu dau la KHONG PHAN BIET DUOC 'chua tra' voi 'tra 0'.",
        depositDefinitionNote = "Tham so bGuaranteeNoBeNull LA DINH NGHIA 'TIEN COC': true => them 'and (pmpd.GuaranteeNo is null)' - coc = khoan thanh toan KHONG GAN BAO LANH. Bo dieu kien nay la GOP CA TIEN BAO LANH VAO TIEN COC.",
        twoDoorsDivergenceNote = "HAI CUA CUA CUNG MOT BAO CAO TINH TIEN COC KHAC NHAU: ban CHI TIET (:23283) dung \"'F'\" (chu thich 'Chi xet Thanh toan Coc (F)'); ban MASTER (:24882) dung \"'A','F'\" (chu thich '...(A,F) //20210601 them trang thai A'). Thay doi 2021 CHI AP VAO BAN MASTER, KHONG lan sang ban chi tiet => tong o master co the LON HON tong cong don cua chi tiet, dung bang phan coc dang o trang thai 'A'. CA HAI SQL deu that su dung bang nay (moi ben 3 lan) nen chenh lech CO HIEU LUC, khong phai ma chet. KHONG tu dong bo - day la quyet dinh nghiep vu.",
        rbacHealthyNote = "PHAN VI DU LANH MANH VE RBAC (hiem): myCommon_GetAbilityOfUser KHONG bi comment, va alParamsCoupleSql bind '@strBUPatternOfUser' = drAbilityOfUser['BUPattern'] - QUYEN THAT; them myCommon_CheckHTCDirect. Bao cao nay CO loc pham vi dung. Ghi lai de doi chieu voi 22 ca lo da thong ke.",
        zoneNote = "strZoneCode: IsNullOrEmpty ? '' : StandardizeParam(...) => CHUAN HOA VE CHUOI RONG, KHONG de NULL - dung khuon tranh bay @strZoneCode = NULL lam mat sach dong.",
        buildClauseNote = "17 tham so loc deu di qua BuildClause('and', '<cot>', <danh sach>, '@p', ref params) => danh sach RONG => BO HAN menh de (khong phai 'in ()').",
        remainingDebt = "NO CON LAI (khong doan): mySql_GetClauseSelect_Mst_Calendar_GetForDayT (bang tham so ngay lam viec), RatioDebtPolicy_V20, GetDiscountOfCar_02_Dtl, Pmt_Guarantee => cac cot chinh sach cong no / chiet khau / bao lanh de null."
    });
}

