// ✅ RBAC: **cả 8 cửa** đều `myCommon_GetAbilityOfUser` (đếm riêng = 1) ⇒ họ báo cáo này lành mạnh.
app.MapGet("/api/reports/payment-01-matrix", async (
    AppDbContext db, ITenantContext t, string? dealerCode, string? soCode, string? modelCode,
    string? zoneCode, string? enforceBuScope, string? buPattern,
    string? tckt, string? wh, string? mst) =>
{
    var isMst = mst == "1";
    var isTckt = tckt == "1";
    var isWh = wh == "1";

    var res = await RptPayment01Async(db, t, dealerCode, soCode, modelCode, zoneCode,
                                      enforceBuScope, buPattern, isMst);

    var door = (isTckt ? "TCKT_" : "") + (isWh ? "WH_" : "") + (isMst ? "Mst" : "Detail");
    return Results.Ok(new
    {
        door,
        sourceFunction = "RptPayment_01" + (isTckt ? "_TCKT" : "") + (isWh ? "_WH" : "")
                         + (isMst ? "_Mst" : "") + "_New20260514",
        database = isWh ? "WH" : "Main",
        sqlTemplate = isTckt ? (isMst ? "mySql_RptPayment_01_TCKT_Mst_New20260514" : "mySql_RptPayment_01_TCKT_New20260514")
                             : (isMst ? "mySql_RptPayment_01_Mst" : "mySql_RptPayment_01_New20260514"),
        depositStatusFilter = isMst ? new[] { "A", "F" } : new[] { "F" },
        totalStatusFilter = new[] { "F" },
        sourceHasDebugSleep4s = isWh,
        sameDbAsMain = isWh,
        baseResult = res,
        matrixNote = "MA TRAN DAY DU 8 CUA (do tung cua, khong suy tu ten): {Main, WH} x {chi tiet, Mst} x {thuong, TCKT} - hoan toan deu 2x2x2. Deposit filter: Mst => 'A','F'; chi tiet => 'F'. Total filter: 'F' o CA TAM. Thread.Sleep(4000): CO o 4/4 cua WH, KHONG o 4/4 cua Main.",
        selfCorrection = "TU SUA KET LUAN O #B126/#B127: o do toi viet 'thay doi 2021 CHI ap vao ban master, KHONG lan sang ban chi tiet' - nghe nhu SO SUAT BO SOT. Co du 8 cua moi thay: bo loc 'A','F' duoc ap DU CA BON cua _Mst va 'F' du ca bon cua chi tiet => day la QUY TAC CO CHU DICH ('bang tong hop tinh ca coc da duyet, bang chi tiet chi tinh coc da hoan tat'), KHONG phai quen dong bo. Chenh lech tong-master vs cong-don-chi-tiet VAN CO THAT nhung la THIET KE. Bai hoc: dung ket luan 'quen dong bo' khi moi doi chieu HAI cua - phai phu het ho ham.",
        sleepScopeNote = "Thread.Sleep(4000) xuat hien DUNG o 4/4 cua WH va 0/4 cua Main => khop chu thich 'Sleep WH'; xac nhan no gan voi DUONG DOC KHO, khong rai ngau nhien (xem #B129).",
        rbacNote = "CA 8 CUA deu co myCommon_GetAbilityOfUser (dem rieng tung mau = 1) => ho bao cao nay LANH MANH ve RBAC - doi lap voi 22 ca lo da thong ke."
    });
}).RequireAuthorization();

// ===== #B134 JOB LẬP KẾ HOẠCH GIAO XE TỰ ĐỘNG — `DMS40_Auto_EstimateDeliveyPlan_New20240514` =====
// Trace LIVE: WS64 `:23377` → `_biz.DMS40_Auto_EstimateDeliveyPlan_New20240514`
//   (`DataWH/BizHTC.PlanDelivery.cs:27`). **3B đo theo dải dòng tường minh, khớp cả 2 máy**:
//   `27,661 / 10a16c48e52f523b096f9ac0d812e886`.
// 🔴🔴 **THỨ TỰ TÁM CHẶNG LÀ NGHIỆP VỤ, KHÔNG PHẢI CHI TIẾT CÀI ĐẶT** — chặng sau ăn phần còn lại
//   của chặng trước; đảo thứ tự là **đổi kết quả phân bổ xe**:
//     1. `SONGFIRST`  → `…_ForSONGFirstX_New20240514`
//     2. `BOATEDP`    → `Auto_EstimateDelivery_BO_ProcessX` (**cấp THÊM một số gốc `SUPPLYDBSUM`**)
//     3. `BO`         → `…_ForBOX`            (chú thích nguồn: *"Job BO Tồn"*)
//     4. `SUPPLYDBSUM`→ (dùng số gốc đã cấp ở chặng 2)
//     5. `SONG`       → `…_ForSONGX_New20240514`
//     6. `NEWDEALER`  → `…_ForNewDealerX_New20240514`
//     7. `NEWSPEC`    → `…_ForNewSpecX_New20240514`
//     8. `ALL`        → `…_ForAllX_New20240514`
// 🔴 **MỖI CHẶNG XIN MỘT `ATEDPNo` RIÊNG** (`SequenceGetForDMS_MyGet(…, SequenceTypeDMS40.ATEDPNo)`)
//   ⇒ **một lượt chạy sinh TÁM số kế hoạch khác nhau**, không phải một số dùng chung.
//   Khuôn số: **`{yyMM}{"ATEDPNO"}{seq % 100000 :00000}`** (`BizHTC.MasterData.cs:190-205`) —
//   khớp ví dụ còn sót trong nguồn: `"2206ATEDPNO21554"`.
//   ⚠️ **`seq % 100000` ⇒ số QUAY VÒNG**: quá 100.000 lượt trong **cùng một tháng** là **trùng số**.
//     Ghi lại, **không tự sửa** (đổi khuôn số là đổi dữ liệu lịch sử).
// 🔴 **Tám chặng đều bọc trong `if (true)`** — công tắc bật/tắt **hàn cứng ở trạng thái BẬT**.
//   ⇒ Không có đường nào bỏ qua chặng; port thêm cờ tắt là **thêm hành vi nguồn không có**.
//   (Cờ `stagesOnly` dưới đây **chỉ để xem trước danh sách**, không tắt chặng nào.)
// 📌 **NỢ — KHÔNG ĐOÁN**: tám hàm `…ForXXX` là **thuật toán phân bổ**, mỗi hàm hàng nghìn dòng, đọc
//   trên **họ bảng `Auto_EstimateDeliveryPlan_*`** (Demand · SupplyMnfDtl · SupplyHTCLocal ·
//   SupplyHTCGlobal · SupplyGlobal · MapRoundSpec · SupplyDistributionSum{MapVIN,Mnf,Local} · Storage…)
//   — chưa có trong MiniHTC. Endpoint này **chỉ điều phối**: cấp đúng tám số theo đúng thứ tự và
//   ghi lại, cờ `EngineRan = false` cho từng chặng. **Không sinh dòng kế hoạch giả.**
// 📌 §12: thực thể `AtedpRun` + Seeder `CREATE TABLE IF NOT EXISTS` + DbSet + trả trong response.
app.MapPost("/api/dms40/auto-estimate-delivery-plan/run", async (
    AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user,
    string? stagesOnly) =>
{
    // 🔴 Thứ tự CỐ ĐỊNH — là nghiệp vụ.
    var stages = new[]
    {
        (Order: 1, Type: "SONGFIRST",   Engine: "DMS40_Auto_EstimateDeliveyPlan_ForSONGFirstX_New20240514"),
        (Order: 2, Type: "BOATEDP",     Engine: "Auto_EstimateDelivery_BO_ProcessX"),
        (Order: 3, Type: "BO",          Engine: "DMS40_Auto_EstimateDeliveyPlan_ForBOX"),
        (Order: 4, Type: "SUPPLYDBSUM", Engine: "(dung so goc cap o chang BOATEDP)"),
        (Order: 5, Type: "SONG",        Engine: "DMS40_Auto_EstimateDeliveyPlan_ForSONGX_New20240514"),
        (Order: 6, Type: "NEWDEALER",   Engine: "DMS40_Auto_EstimateDeliveyPlan_ForNewDealerX_New20240514"),
        (Order: 7, Type: "NEWSPEC",     Engine: "DMS40_Auto_EstimateDeliveyPlan_ForNewSpecX_New20240514"),
        (Order: 8, Type: "ALL",         Engine: "DMS40_Auto_EstimateDeliveyPlan_ForAllX_New20240514"),
    };

    if (stagesOnly == "1")
        return Results.Ok(new { stages = stages.Select(s => new { s.Order, s.Type, s.Engine }), previewOnly = true });

    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var runId = Guid.NewGuid().ToString("N");
    var yyMM = DateTime.Now.ToString("yyMM");

    // 🔴 Khuôn số nguồn: {yyMM}{ATEDPNO}{seq % 100000 :00000} — seq lấy nối tiếp trong bảng.
    var used = await db.AtedpRuns.Where(r => r.OrgId == t.OrgId).CountAsync();
    string NextNo(int i) => $"{yyMM}ATEDPNO{((used + i) % 100000):00000}";

    var rows = new List<AtedpRun>();
    var idx = 0;
    string? spdbsRoot = null;
    foreach (var s in stages)
    {
        idx++;
        var no = NextNo(idx);
        // 🔴 Chặng BOATEDP cấp THÊM một số gốc SUPPLYDBSUM, dùng lại ở chặng 4.
        if (s.Type == "BOATEDP") { idx++; spdbsRoot = NextNo(idx); }
        rows.Add(new AtedpRun
        {
            OrgId = t.OrgId, RunId = runId, StageOrder = s.Order, ATEDPType = s.Type,
            ATEDPNo = no,
            ATEDPNoSPDBSRoot = s.Type == "BOATEDP" ? spdbsRoot : (s.Type == "SUPPLYDBSUM" ? spdbsRoot : null),
            EngineRan = false, CreatedBy = by
        });
    }
    db.AtedpRuns.AddRange(rows);
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        runId,
        stages = rows.Select(r => new { r.StageOrder, r.ATEDPType, r.ATEDPNo, r.ATEDPNoSPDBSRoot, r.EngineRan }),
        enginesNotRun = true,
        stageOrderNote = "THU TU TAM CHANG LA NGHIEP VU, khong phai chi tiet cai dat - chang sau an phan con lai cua chang truoc; dao thu tu la DOI KET QUA PHAN BO XE. Thu tu: SONGFIRST -> BOATEDP -> BO ('Job BO Ton') -> SUPPLYDBSUM -> SONG -> NEWDEALER -> NEWSPEC -> ALL.",
        numberingNote = "MOI CHANG XIN MOT ATEDPNo RIENG (SequenceGetForDMS_MyGet voi SequenceTypeDMS40.ATEDPNo = 'ATEDPNO') => MOT LUOT CHAY SINH TAM SO KE HOACH KHAC NHAU, khong phai mot so dung chung. Khuon: {yyMM}{ATEDPNO}{seq % 100000 :00000} (BizHTC.MasterData.cs:190-205) - khop vi du con sot trong nguon: '2206ATEDPNO21554'.",
        wrapAroundNote = "seq % 100000 => SO QUAY VONG: qua 100.000 luot trong CUNG MOT THANG la TRUNG SO. Ghi lai, KHONG tu sua (doi khuon so la doi du lieu lich su).",
        alwaysOnNote = "Tam chang deu boc trong 'if (true)' - cong tac bat/tat HAN CUNG O TRANG THAI BAT. Khong co duong nao bo qua chang; port them co tat la THEM HANH VI NGUON KHONG CO. Tham so stagesOnly chi de XEM TRUOC danh sach, khong tat chang nao.",
        spdbsRootNote = "Chang BOATEDP cap THEM mot so goc SUPPLYDBSUM (strATEDPNo_SPDBSRoot) roi chuyen vao Auto_EstimateDelivery_BO_ProcessX; chang SUPPLYDBSUM dung lai chinh so do.",
        engineDebt = "NO - KHONG DOAN: tam ham ...ForXXX la THUAT TOAN PHAN BO, moi ham hang nghin dong, doc tren ho bang Auto_EstimateDeliveryPlan_* (Demand, SupplyMnfDtl, SupplyHTCLocal, SupplyHTCGlobal, SupplyGlobal, MapRoundSpec, SupplyDistributionSum{MapVIN,Mnf,Local}, Storage...) - chua co trong MiniHTC. Endpoint nay CHI DIEU PHOI: cap dung tam so theo dung thu tu va ghi lai, EngineRan = false. KHONG sinh dong ke hoach gia."
    });
}).RequireAuthorization();

// ===== #B135 DỰNG LẠI CACHE KHO CHO JOB KẾ HOẠCH — `myCache_Auto_EstimateDeliveryPlan_Storage_Gen`
//       (bước tiền xử lý CHẠY NGAY TRƯỚC 8 chặng của #B134) =====
// 🔴 **Bẫy tìm hàm — hàm sống nằm trong file tên `zTemp.*`**: `grep` ra **6 định nghĩa**, phần lớn ở
//   `DMS40/Delete.0.21.PlanDelivery.cs` và `Backup/…`. Bản **ĐANG BIÊN DỊCH** là
//   **`DMS40/zTemp.0.21.PlanDelivery.cs:779`** — csproj ghi `<Compile Include="DMS40\zTemp.0.21.PlanDelivery.cs" />`
//   (dòng 279) trong khi `Delete.0.21.PlanDelivery.cs` chỉ là **`<None Include=…>`** (dòng 318) ⇒
//   **không được biên dịch**. ⇒ Dấu `Delete.*` = chết **đã được csproj xác nhận**, nhưng dấu
//   `zTemp.*` **KHÔNG** có nghĩa là tạm/chết.
// 🔴🔴 **XOÁ SẠCH RỒI NẠP LẠI TOÀN BỘ**: `delete from Auto_EstimateDeliveryPlan_Storage;` rồi
//   `insert into … select …` ⇒ đây là **cache dựng lại từ đầu mỗi lượt**, không phải bảng tích luỹ.
//   Port bằng "thêm nếu chưa có" là **để lại rác của lần chạy trước**.
// 🔴 **BỐN BƯỚC, thứ tự quyết định giá trị `FlagLocal`**:
//   1. **TÍCH ĐỀ-CÁC** `Mst_Dealer × Mst_Storage × Mst_CarModel` (`inner join … on (1=1)` — **ba bảng
//      nhân nhau, không điều kiện**) ⇒ `FlagLocal = '-1'`. ⚠️ Số dòng = |ĐL| × |Kho| × |Model|.
//   2. `left join Mst_StorageGlobal` theo **(StorageCode, ModelCode)** ⇒ khớp thì `FlagLocal = '0'`.
//   3. `left join Dlr_StorageLocal` theo **(DealerCode, StorageCode)** ⇒ khớp thì `FlagLocal = '1'`.
//      ⇒ **local GHI ĐÈ global** vì chạy sau. Đảo hai bước là đổi phân loại kho.
//   4. Bản cuối **chỉ giữ `FlagLocal != '-1'`** ⇒ bộ ba không thuộc global lẫn local **bị loại**;
//      vì vậy giá trị `'-1'` **không bao giờ xuất hiện** trong bảng đích.
// 📌 §12: thực thể `AutoEstDlvPlanStorage` + Seeder + DbSet + trả trong response.
app.MapPost("/api/dms40/auto-estimate-delivery-plan/rebuild-storage-cache", async (
    AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;

    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId).Select(d => d.DealerCode).ToListAsync();
    var storages = await db.Storages.Where(s => s.OrgId == t.OrgId).Select(s => s.StorageCode).ToListAsync();
    var models = await db.CarModelStds.Where(m => m.OrgId == t.OrgId).Select(m => m.ModelCode).ToListAsync();

    var globals = (await db.StorageGlobalMaps.Where(g => g.OrgId == t.OrgId)
        .Select(g => new { g.StorageCode, g.ModelCode }).ToListAsync())
        .Select(g => g.StorageCode + "\u0001" + g.ModelCode).ToHashSet();
    var locals = (await db.DealerStorageLocals.Where(l => l.OrgId == t.OrgId)
        .Select(l => new { l.DealerCode, l.StorageCode }).ToListAsync())
        .Select(l => l.DealerCode + "\u0001" + l.StorageCode).ToHashSet();

    var rows = new List<AutoEstDlvPlanStorage>();
    foreach (var d in dealers)
        foreach (var s in storages)
            foreach (var m in models)
            {
                var flag = "-1";                                             // bước 1
                if (globals.Contains(s + "\u0001" + m)) flag = "0";          // bước 2
                if (locals.Contains(d + "\u0001" + s)) flag = "1";           // bước 3 — GHI ĐÈ bước 2
                if (flag == "-1") continue;                                  // bước 4 — loại
                rows.Add(new AutoEstDlvPlanStorage
                {
                    OrgId = t.OrgId, DealerCode = d, StorageCode = s, ModelCode = m,
                    FlagLocal = flag, LogLUDateTime = now, LogLUBy = by
                });
            }

    // 🔴 XOÁ SẠCH rồi nạp lại — đúng như `delete from …; insert into …`.
    var old = await db.AutoEstDlvPlanStorages.Where(x => x.OrgId == t.OrgId).ToListAsync();
    db.AutoEstDlvPlanStorages.RemoveRange(old);
    db.AutoEstDlvPlanStorages.AddRange(rows);
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        deleted = old.Count,
        inserted = rows.Count,
        cartesianSize = (long)dealers.Count * storages.Count * models.Count,
        dealers = dealers.Count, storages = storages.Count, models = models.Count,
        byFlagLocal = rows.GroupBy(r => r.FlagLocal).Select(g => new { FlagLocal = g.Key, Qty = g.Count() }),
        rebuildNote = "XOA SACH ROI NAP LAI TOAN BO: nguon chay 'delete from Auto_EstimateDeliveryPlan_Storage;' roi 'insert into ... select ...' => CACHE DUNG LAI TU DAU moi luot, khong phai bang tich luy. Port bang 'them neu chua co' la DE LAI RAC cua lan chay truoc.",
        fourStepsNote = "BON BUOC, thu tu quyet dinh gia tri FlagLocal: (1) TICH DE-CAC Mst_Dealer x Mst_Storage x Mst_CarModel (inner join ... on (1=1) - ba bang nhan nhau, KHONG dieu kien) => FlagLocal '-1'; (2) left join Mst_StorageGlobal theo (StorageCode, ModelCode) => khop thi '0'; (3) left join Dlr_StorageLocal theo (DealerCode, StorageCode) => khop thi '1' - LOCAL GHI DE GLOBAL vi chay sau, dao hai buoc la doi phan loai kho; (4) ban cuoi CHI GIU FlagLocal != '-1' => bo ba khong thuoc global lan local BI LOAI, nen '-1' KHONG BAO GIO xuat hien trong bang dich.",
        cartesianWarning = "So dong buoc 1 = |Dai ly| x |Kho| x |Model| - tich De-cac day du, khong co dieu kien loc nao.",
        deadFileNote = "BAY TIM HAM: grep ra SAU dinh nghia, phan lon o DMS40/Delete.0.21.PlanDelivery.cs va Backup/... Ban DANG BIEN DICH la DMS40/zTemp.0.21.PlanDelivery.cs:779 - csproj ghi <Compile Include=(DMS40 zTemp.0.21.PlanDelivery.cs)> (dong 279) trong khi Delete.0.21.PlanDelivery.cs chi la <None Include=...> (dong 318) => KHONG duoc bien dich. Dau 'Delete.*' = chet DA DUOC CSPROJ XAC NHAN; nhung dau 'zTemp.*' KHONG co nghia la tam/chet."
    });
}).RequireAuthorization();

// ===== #B136/#B137/#B138 TỶ LỆ PHÂN BỔ XE THEO KHO — `Auto_MapVIN_StorageRate_Get` / `_GetWH` / `_Save`
//       (`DMS40/zTemp.0.20.MapVIN.cs`, csproj dòng 127 `<Compile Include>` ⇒ **file SỐNG**) =====
// Trace LIVE: WS64 `:18997` (Get) · `:19079` (GetWH) · `:18918` (Save).
// **3B đo theo dải dòng tường minh, khớp cả 2 máy**:
//   `76743,76994 / b4a7f772c3d68e61d78ed59acec4da0c`  (Get)
//   `76995,77248 / f11a83309f11e7817ed29cd4d5ba7d08`  (GetWH)
//   `77249,77700 / 4bf852995dcb07d885d83a4b24b01526`  (Save)
// 🔴 **KHOÁ NGHIỆP VỤ LÀ BỘ BỐN**: `(StorageCode, ModelCode, SpecCode, ColorExtCode)` — mọi `inner
//   join`, `delete` và `order by` đều theo đủ bốn cột. Bỏ sót một cột là **gộp nhầm dòng**.
// 🔴 **BA MIỀN, KHÔNG PHẢI MỘT TỶ LỆ**: `MBVal` (Bắc) · `MTVal` (Trung) · `MNVal` (Nam) — mỗi bộ bốn
//   có **ba** giá trị độc lập; guard nguồn: **mỗi giá trị `< 0` ⇒ `…_Save_InvalidValue`**
//   (⚠️ **cùng MỘT mã lỗi cho cả ba cột** ⇒ thông báo không chỉ ra cột nào sai — giữ nguyên).
//   ⚠️ Nguồn **không** kiểm tổng ba miền bằng 100 hay bất kỳ trần nào — **không tự thêm**.
// 🔴 **PHÂN TRANG kiểu `identity(bigint,0,1) MyIdxSeq`**: đánh số vào bảng tạm *Draft* rồi cắt trang
//   bằng `MyIdxSeq between @start and @end`. **`MyCount` được đếm trên bảng Draft — TRƯỚC khi cắt
//   trang** ⇒ tổng số dòng là của **toàn bộ kết quả lọc**, không phải của trang. Trả ở bảng
//   **`MySummaryTable`**. ⚠️ `MyIdxSeq` bắt đầu từ **0**.
// 🔴 **`#tblMst_CarColor` được `select distinct` TRƯỚC khi join** — nguồn cố ý gom màu về duy nhất
//   theo `(ModelCode, ColorExtCode)`; join thẳng `Mst_CarColor` sẽ **nở dòng** vì bảng đó còn tách
//   theo màu nội thất.
// 🔴 Ba `left join` làm giàu: `Mst_CarModel` (ModelCode) · `Mst_CarSpec` (**ModelCode + SpecCode**) ·
//   `#tblMst_CarColor` (**ModelCode + ColorExtCode**) — tiền tố bí danh `mcm_` / `mcs_` / `mcc_`.
// 🔴 **`_Save` = XOÁ THEO BỘ BỐN RỒI CHÈN LẠI** (không `update`): `delete t from Auto_MapVIN_StorageRate t
//   inner join #input… f on <đủ 4 cột>` rồi `if (!bIsDelete) insert into …`.
//   ⇒ **`FlagIsDelete = "1"` (`TConst.Flag.Yes`) ⇒ CHỈ XOÁ**, không chèn lại. Một endpoint, hai việc.
//   Ghi **cả `_dbMain` và `_dbWH`**.
// 🔴 Guard tồn tại trước khi ghi, **mỗi thứ một mã lỗi**: `…_InvalidStorageCode` · `…_InvalidModelCode`
//   · `…_InvalidSpecCode` · `…_InvalidColorExtCode`; bảng đầu vào thiếu ⇒ `…TblNotFound`.
// 🔴 **`_GetWH` khác `_Get` đúng một điểm: đọc trên DB Warehouse** (khuôn #B129) ⇒ MiniHTC một CSDL
//   ⇒ trả cùng số liệu, cờ `sameDbAsMain`.
// 📌 §12: thực thể `AutoMapVinStorageRate` + Seeder + DbSet + DTO + có ở **cả POST và GET**.
static async Task<IResult> AutoMapVinStorageRateGetAsync(
    AppDbContext db, ITenantContext t, string? storageCode, string? modelCode, string? specCode,
    string? colorExtCode, int? recordStart, int? recordCount, bool isWh)
{
    var q = db.AutoMapVinStorageRates.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(storageCode)) q = q.Where(r => r.StorageCode == storageCode.Trim());
    if (!string.IsNullOrWhiteSpace(modelCode)) q = q.Where(r => r.ModelCode == modelCode.Trim());
    if (!string.IsNullOrWhiteSpace(specCode)) q = q.Where(r => r.SpecCode == specCode.Trim());
    if (!string.IsNullOrWhiteSpace(colorExtCode)) q = q.Where(r => r.ColorExtCode == colorExtCode.Trim());

    var all = await q
        .OrderBy(r => r.StorageCode).ThenBy(r => r.ModelCode)
        .ThenBy(r => r.SpecCode).ThenBy(r => r.ColorExtCode)
        .ToListAsync();

    // 🔴 MyCount đếm TRƯỚC khi cắt trang.
    var myCount = all.Count;

    var start = recordStart ?? 0;
    var count = recordCount ?? myCount;
    var page = all.Skip(start).Take(count <= 0 ? myCount : count).ToList();

    var models = (await db.CarModelStds.Where(m => m.OrgId == t.OrgId)
        .Select(m => new { m.ModelCode, m.ModelName }).ToListAsync())
        .GroupBy(m => m.ModelCode).ToDictionary(g => g.Key, g => g.First().ModelName);
    var specs = (await db.CarSpecs.Where(s => s.OrgId == t.OrgId)
        .Select(s => new { s.ModelCode, s.SpecCode, s.SpecDesc }).ToListAsync())
        .GroupBy(s => (s.ModelCode ?? "") + "|#|" + s.SpecCode).ToDictionary(g => g.Key, g => g.First().SpecDesc);
    // 🔴 distinct TRƯỚC khi join — tránh nở dòng vì màu nội thất.
    var colors = (await db.MstCarColors.Where(c => c.OrgId == t.OrgId)
        .Select(c => new { c.ModelCode, c.ColorExtCode, c.ColorExtName, c.ColorExtNameVN }).ToListAsync())
        .GroupBy(c => (c.ModelCode ?? "") + "|#|" + (c.ColorExtCode ?? ""))
        .ToDictionary(g => g.Key, g => g.First());

    var items = page.Select((r, i) => new
    {
        MyIdxSeq = start + i,                       // 🔴 đánh số bắt đầu từ 0
        r.StorageCode, r.ModelCode, r.SpecCode, r.ColorExtCode,
        r.MBVal, r.MTVal, r.MNVal, r.LogLUDateTime, r.LogLUBy,
        mcm_ModelCode = r.ModelCode,
        mcm_ModelName = models.TryGetValue(r.ModelCode, out var mn) ? mn : null,
        mcs_SpecCode = r.SpecCode,
        mcs_SpecDescription = specs.TryGetValue(r.ModelCode + "|#|" + r.SpecCode, out var sd) ? sd : null,
        mcc_ColorExtCode = r.ColorExtCode,
        mcc_ColorExtName = colors.TryGetValue(r.ModelCode + "|#|" + r.ColorExtCode, out var cc) ? cc.ColorExtName : null,
        mcc_ColorExtNameVN = colors.TryGetValue(r.ModelCode + "|#|" + r.ColorExtCode, out var cc2) ? cc2.ColorExtNameVN : null
    }).ToList();

    return Results.Ok(new
    {
        MySummaryTable = new[] { new { MyCount = myCount } },
        Auto_MapVIN_StorageRate = items,
        recordStart = start, recordCount = count,
        sameDbAsMain = isWh,
        keyNote = "KHOA NGHIEP VU LA BO BON (StorageCode, ModelCode, SpecCode, ColorExtCode) - moi inner join, delete va order by deu theo du bon cot. Bo sot mot cot la GOP NHAM DONG.",
        threeRegionNote = "BA MIEN, KHONG PHAI MOT TY LE: MBVal (Bac) / MTVal (Trung) / MNVal (Nam) - moi bo bon co BA gia tri doc lap. Nguon KHONG kiem tong ba mien bang 100 hay bat ky tran nao - KHONG tu them.",
        pagingNote = "PHAN TRANG kieu identity(bigint,0,1) MyIdxSeq: danh so vao bang tam Draft roi cat trang bang MyIdxSeq between @start and @end. MyCount duoc dem TREN BANG DRAFT - TRUOC khi cat trang => tong so dong la cua TOAN BO ket qua loc, khong phai cua trang. Tra o bang MySummaryTable. MyIdxSeq bat dau tu 0.",
