        if (!colorKeys.Contains(mc + "|#|" + ce))
            return Results.BadRequest(new { error = "Auto_MapVIN_DistributionSumRate_Save_InvalidColorExtCode", check = new { ModelCode = mc, ColorExtCode = ce } });
        if ((r.MBVal ?? 0m) < 0 || (r.MTVal ?? 0m) < 0 || (r.MNVal ?? 0m) < 0)
