    db.AutoMapVinDistSumRates.RemoveRange(toDelete);

    var inserted = 0;
    if (!isDelete)
        foreach (var r in dto.Rows)
        {
            db.AutoMapVinDistSumRates.Add(new AutoMapVinDistSumRate
            {
                OrgId = t.OrgId,
                ModelCode = (r.ModelCode ?? "").Trim(),
                SpecCode = (r.SpecCode ?? "").Trim(),
                ColorExtCode = (r.ColorExtCode ?? "").Trim(),
                MBVal = r.MBVal, MTVal = r.MTVal, MNVal = r.MNVal,
                LogLUDateTime = now, LogLUBy = by
            });
            inserted++;
        }
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        flagIsDelete = isDelete ? "1" : "0",
        deleted = toDelete.Count, inserted,
        keyNote = "Xoa/chen theo BO BA (ModelCode, SpecCode, ColorExtCode) - KHONG co StorageCode.",
        deleteInsertNote = "_Save = xoa theo khoa roi chen lai (khong update); FlagIsDelete = '1' => CHI XOA. Ghi ca _dbMain va _dbWH."
    });
}).RequireAuthorization();

// ===== #B142/#B143/#B144 CẤU HÌNH ĐẦU VÀO MAP VIN — `Config_MapVINCarCarInput_Get` / `_Add` / `_Update`
//       (`DMS40/zTemp.0.20.MapVIN.cs`) =====
// Trace LIVE: WS64 `:18701` (Get) · `:18777` (Add) · `:18847` (Update). Mỗi cửa public là **vỏ mỏng**
//   (~120 dòng) gọi thân thật `…GetX` / `…AddX` / `…UpdateX`.
// **3B đo trên THÂN THẬT, dải dòng tường minh, khớp cả 2 máy**:
//   `74379,74577 / 7ce36ab9eabcc5df20cc8d6649511ac7`  (`GetX`)
//   `74709,75300 / 4eb769d81458a4a8428e37568df9a44f`  (`AddX`)
//   `75421,76300 / 0b28c0a1036c0373a3037aa7777e8703`  (`UpdateX`)
//   ⚠️ Lần đầu tôi lấy dải "tới hàm `public` kế tiếp" ⇒ **trùm luôn vài hàm `private` không liên quan**
//     (`Auto_MapVIN_StorageRate_CheckDB`…). Biên đúng phải chặn ở **thành viên KẾ TIẾP bất kể
//     `public` hay `private`**. (Bổ sung cho luật `C0-…vicesimusseptimus`.)
// 🔴🔴 **HIỆU LỰC THEO NGÀY — `EffDateStart` PHẢI TỪ NGÀY MAI TRỞ ĐI**:
//   `if (strEffDateStart.CompareTo(dtimeSys.AddDays(1).ToString("yyyy-MM-dd")) < 0) throw
//    …_Add_InvalidEffDateStartAfterSysDate;`
//   ⇒ **không cho hiệu lực từ HÔM NAY hay quá khứ** — chỉ từ **ngày mai**. Bỏ trống ⇒ `…_InvalidEffDateStart`.
// 🔴 **Chống trùng mốc**: đã tồn tại bản cùng `ModelCode` **và** cùng `EffDateStart` ⇒
//   `…_Add_MoreThanOneCfgATMVIpCodeActive` (chú thích nguồn: *"ModelCode already exist this EffDateStart."*).
// 🔴🔴 **DỰNG LẠI TOÀN BỘ DÂY CHUYỀN HIỆU LỰC sau mỗi lần ghi** — không chỉ đóng bản liền trước:
//   nguồn đọc **tất cả** bản của model, sắp theo `EffDateStart`, rồi
//     · với **mỗi cặp liền kề**: `EffDateEnd(bản trước) = EffDateStart(bản sau) **− 1 ngày**`;
//     · **bản cuối cùng**: `EffDateEnd = TConst.DateTimeSpecial.DateMax`;
//     · sau đó `update … set FlagActive = @flag where ModelCode = @m and **EffDateEnd < ngày hệ thống**`
//       ⇒ **tự đóng cờ các bản đã hết hạn**.
//   ⇒ Port kiểu "chỉ sửa bản vừa thêm" sẽ để lại **khoảng chồng lấn** giữa các bản.
// 🔴 Guard giá trị dòng: `ValPmtDepositPercentFrom` và `…To` phải trong **[0, 100]**
//   (`…_InvalidValue` — **chung một mã cho cả hai cột**); `FlagIsExistGuarantee` **chỉ `'1'`/`'0'`**.
//   ⚠️ Nguồn **KHÔNG** kiểm `From <= To`, cũng **không** kiểm các khoảng chồng nhau — **không tự thêm**.
// 🔴 `DCPType` **không có lớp hằng** trong `TERP.Constants` ⇒ là **chuỗi tự do**; không dựng từ vựng giả.
// 🔴 Bản mới luôn được tạo với `EffDateEnd = DateMax` và `FlagActive = TConst.Flag.Active` ("1").
// 🔴 Ghi **cả `_dbMain` và `_dbWH`** (mọi câu update dây chuyền đều chạy hai lần).
// 📌 §12: `ConfigMapVinInput` + `ConfigMapVinInputDtl` + Seeder + DbSet + DTO + có ở **cả POST và GET**.

// 🔴 Dựng lại dây chuyền hiệu lực cho MỘT model — dùng chung cho cả _Add và _Update.
static async Task RebuildEffChainAsync(AppDbContext db, Guid orgId, string modelCode, DateTime sysDate)
{
    var chain = await db.ConfigMapVinInputs
        .Where(c => c.OrgId == orgId && c.ModelCode == modelCode)
        .OrderBy(c => c.EffDateStart).ToListAsync();
    for (var i = 0; i + 1 < chain.Count; i++)
        chain[i].EffDateEnd = chain[i + 1].EffDateStart.AddDays(-1);      // bản trước = bản sau − 1 ngày
    if (chain.Count > 0)
        chain[^1].EffDateEnd = new DateTime(9999, 12, 31);                 // bản cuối = DateMax
    foreach (var c in chain)
        if (c.EffDateEnd < sysDate) c.FlagActive = "0";                    // đã hết hạn ⇒ đóng cờ
}

app.MapGet("/api/dms40/mapvin-config-inputs", async (
    AppDbContext db, ITenantContext t, string? modelCode, string? cfgATMVIpCode, string? flagActive) =>
{
    var q = db.ConfigMapVinInputs.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(modelCode)) q = q.Where(c => c.ModelCode == modelCode.Trim());
    if (!string.IsNullOrWhiteSpace(cfgATMVIpCode)) q = q.Where(c => c.CfgATMVIpCode == cfgATMVIpCode.Trim());
    if (!string.IsNullOrWhiteSpace(flagActive)) q = q.Where(c => c.FlagActive == flagActive.Trim());

    var heads = await q.OrderBy(c => c.ModelCode).ThenBy(c => c.EffDateStart).ToListAsync();
    var codes = heads.Select(h => h.CfgATMVIpCode).ToList();
    var dtls = await db.ConfigMapVinInputDtls
        .Where(d => d.OrgId == t.OrgId && codes.Contains(d.CfgATMVIpCode)).ToListAsync();

    return Results.Ok(new
    {
        Config_MapVINCarCarInput = heads,
        Config_MapVINCarCarInputDtl = dtls,
        count = heads.Count,
        effChainNote = "Mot model co NHIEU BAN noi tiep thanh DAY CHUYEN HIEU LUC: EffDateEnd cua ban truoc = EffDateStart cua ban sau TRU 1 NGAY; ban cuoi luon EffDateEnd = DateMax.",
        vocabNote = "DCPType KHONG co lop hang trong TERP.Constants => la CHUOI TU DO; khong dung tu vung gia. FlagIsExistGuarantee chi '1'/'0'."
    });
}).RequireAuthorization();

app.MapPost("/api/dms40/mapvin-config-inputs", async (
    ConfigMapVinInputAddDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    var cfg = (dto.CfgATMVIpCode ?? "").Trim();
    var model = (dto.ModelCode ?? "").Trim();
    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var sys = DateTime.Now.Date;

    // 🔴 EffDateStart bắt buộc.
    if (dto.EffDateStart is null)
        return Results.BadRequest(new { error = "Config_MapVINCarCarInput_Add_InvalidEffDateStart" });
    var effStart = dto.EffDateStart.Value.Date;

    // 🔴🔴 PHẢI TỪ NGÀY MAI TRỞ ĐI — hôm nay cũng bị chặn.
    if (effStart < sys.AddDays(1))
        return Results.BadRequest(new
        {
            error = "Config_MapVINCarCarInput_Add_InvalidEffDateStartAfterSysDate",
            check = new { EffDateStart = effStart, MinAllowed = sys.AddDays(1) },
            note = "Nguon so sanh voi dtimeSys.AddDays(1) => KHONG cho hieu luc tu HOM NAY hay qua khu."
        });

    if (dto.Rows is null || dto.Rows.Count == 0)
        return Results.BadRequest(new { error = "Config_MapVINCarCarInput_Add_Input_MapVINCarCarInputDtlNotFound" });

    // 🔴 Chống trùng mốc: cùng ModelCode + cùng EffDateStart.
    var dup = await db.ConfigMapVinInputs
        .AnyAsync(c => c.OrgId == t.OrgId && c.ModelCode == model && c.EffDateStart == effStart);
    if (dup)
        return Results.BadRequest(new
        {
            error = "Config_MapVINCarCarInput_Add_MoreThanOneCfgATMVIpCodeActive",
            check = new { ModelCode = model, EffDateStart = effStart },
            note = "Chu thich nguon: 'ModelCode already exist this EffDateStart.'"
        });

    foreach (var r in dto.Rows)
    {
        // 🔴 [0, 100] — CHUNG một mã lỗi cho cả hai cột. Nguồn KHONG kiem From <= To.
        if ((r.ValPmtDepositPercentFrom ?? 0m) < 0 || (r.ValPmtDepositPercentFrom ?? 0m) > 100
            || (r.ValPmtDepositPercentTo ?? 0m) < 0 || (r.ValPmtDepositPercentTo ?? 0m) > 100)
            return Results.BadRequest(new { error = "Config_MapVINCarCarInput_Add_InvalidValue", check = new { r.ValPmtDepositPercentFrom, r.ValPmtDepositPercentTo } });
        var g = (r.FlagIsExistGuarantee ?? "").Trim();
        if (!(g == "1" || g == "0"))
            return Results.BadRequest(new { error = "Config_MapVINCarCarInput_Add_InvalidValue", check = new { FlagIsExistGuarantee = g } });
    }

    var now = DateTime.Now;
    db.ConfigMapVinInputs.Add(new ConfigMapVinInput
    {
        OrgId = t.OrgId, CfgATMVIpCode = cfg, ModelCode = model,
        EffDateStart = effStart,
        EffDateEnd = new DateTime(9999, 12, 31),      // 🔴 bản mới luôn DateMax
        FlagActive = "1",                             // TConst.Flag.Active
        LogLUDateTime = now, LogLUBy = by
    });
    foreach (var r in dto.Rows)
        db.ConfigMapVinInputDtls.Add(new ConfigMapVinInputDtl
        {
            OrgId = t.OrgId, CfgATMVIpCode = cfg, ModelCode = model,
            DCPType = r.DCPType,
            ValPmtDepositPercentFrom = r.ValPmtDepositPercentFrom,
            ValPmtDepositPercentTo = r.ValPmtDepositPercentTo,
            FlagIsExistGuarantee = (r.FlagIsExistGuarantee ?? "0").Trim(),
            FlagActive = "1", LogLUDateTime = now, LogLUBy = by
        });
    await db.SaveChangesAsync();

    // 🔴🔴 DỰNG LẠI TOÀN BỘ dây chuyền hiệu lực của model.
    await RebuildEffChainAsync(db, t.OrgId, model, sys);
    await db.SaveChangesAsync();

    var chain = await db.ConfigMapVinInputs
        .Where(c => c.OrgId == t.OrgId && c.ModelCode == model)
        .OrderBy(c => c.EffDateStart).ToListAsync();

    return Results.Ok(new
    {
        cfgATMVIpCode = cfg, modelCode = model, effDateStart = effStart,
        dtlInserted = dto.Rows.Count,
        effChain = chain.Select(c => new { c.CfgATMVIpCode, c.EffDateStart, c.EffDateEnd, c.FlagActive }),
        effDateRuleNote = "EffDateStart PHAI TU NGAY MAI TRO DI: nguon so sanh voi dtimeSys.AddDays(1) => khong cho hieu luc tu HOM NAY hay qua khu. Bo trong => _InvalidEffDateStart.",
        dupRuleNote = "Chong trung moc: da ton tai ban cung ModelCode VA cung EffDateStart => _Add_MoreThanOneCfgATMVIpCodeActive (chu thich nguon: 'ModelCode already exist this EffDateStart.').",
        chainRebuildNote = "DUNG LAI TOAN BO DAY CHUYEN HIEU LUC sau moi lan ghi - khong chi dong ban lien truoc: doc TAT CA ban cua model, sap theo EffDateStart, roi (a) moi cap lien ke: EffDateEnd(ban truoc) = EffDateStart(ban sau) TRU 1 NGAY; (b) ban cuoi: EffDateEnd = DateMax; (c) update FlagActive cho nhung ban co EffDateEnd < ngay he thong. Port kieu 'chi sua ban vua them' se de lai KHOANG CHONG LAN.",
        valueGuardNote = "ValPmtDepositPercentFrom va ...To phai trong [0, 100] (_InvalidValue - CHUNG mot ma cho ca hai cot); FlagIsExistGuarantee chi '1'/'0'. Nguon KHONG kiem From <= To, cung KHONG kiem cac khoang chong nhau - khong tu them.",
        twoDbNote = "Nguon ghi CA _dbMain va _dbWH (moi cau update day chuyen deu chay hai lan)."
    });
}).RequireAuthorization();

app.MapPut("/api/dms40/mapvin-config-inputs/{cfgCode}", async (
    string cfgCode, ConfigMapVinInputUpdateDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    var cfg = (cfgCode ?? "").Trim();
    if (cfg.Length == 0)
        return Results.BadRequest(new { error = "Config_MapVINCarCarInput_Update_Input_MapVINCarCarInputInvalid" });

    var head = await db.ConfigMapVinInputs.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.CfgATMVIpCode == cfg);
    if (head is null)
        return Results.BadRequest(new { error = "Config_MapVINCarCarInput_Update_Input_MapVINCarCarInputNotFound", check = new { CfgATMVIpCode = cfg } });

    if (dto.Rows is not null)
        foreach (var r in dto.Rows)
        {
            if ((r.ValPmtDepositPercentFrom ?? 0m) < 0 || (r.ValPmtDepositPercentFrom ?? 0m) > 100
                || (r.ValPmtDepositPercentTo ?? 0m) < 0 || (r.ValPmtDepositPercentTo ?? 0m) > 100)
                return Results.BadRequest(new { error = "Config_MapVINCarCarInput_Update_InvalidValue", check = new { r.ValPmtDepositPercentFrom, r.ValPmtDepositPercentTo } });
            var g = (r.FlagIsExistGuarantee ?? "").Trim();
            if (!(g == "1" || g == "0"))
                return Results.BadRequest(new { error = "Config_MapVINCarCarInput_Update_InvalidValue", check = new { FlagIsExistGuarantee = g } });
        }

    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var sys = now.Date;

    // Thay dòng: xoá theo (CfgATMVIpCode) rồi chèn lại — cùng khuôn "xoá rồi chèn" của họ MapVIN.
    var oldDtls = await db.ConfigMapVinInputDtls
        .Where(d => d.OrgId == t.OrgId && d.CfgATMVIpCode == cfg).ToListAsync();
    var replaced = 0;
    if (dto.Rows is not null)
    {
        db.ConfigMapVinInputDtls.RemoveRange(oldDtls);
        foreach (var r in dto.Rows)
        {
            db.ConfigMapVinInputDtls.Add(new ConfigMapVinInputDtl
            {
                OrgId = t.OrgId, CfgATMVIpCode = cfg, ModelCode = head.ModelCode,
                DCPType = r.DCPType,
                ValPmtDepositPercentFrom = r.ValPmtDepositPercentFrom,
                ValPmtDepositPercentTo = r.ValPmtDepositPercentTo,
                FlagIsExistGuarantee = (r.FlagIsExistGuarantee ?? "0").Trim(),
                FlagActive = "1", LogLUDateTime = now, LogLUBy = by
            });
            replaced++;
        }
    }
    head.LogLUDateTime = now; head.LogLUBy = by;
    await db.SaveChangesAsync();

    // 🔴 Dựng lại dây chuyền hiệu lực (nguồn chạy cùng khối này ở cả _Add lẫn _Update).
    await RebuildEffChainAsync(db, t.OrgId, head.ModelCode, sys);
    await db.SaveChangesAsync();

    var chain = await db.ConfigMapVinInputs
        .Where(c => c.OrgId == t.OrgId && c.ModelCode == head.ModelCode)
        .OrderBy(c => c.EffDateStart).ToListAsync();

    return Results.Ok(new
    {
        cfgATMVIpCode = cfg, modelCode = head.ModelCode,
        dtlDeleted = dto.Rows is null ? 0 : oldDtls.Count,
        dtlInserted = replaced,
        effChain = chain.Select(c => new { c.CfgATMVIpCode, c.EffDateStart, c.EffDateEnd, c.FlagActive }),
        errorCodesNote = "Cua _Update chi co BA ma loi: _Input_MapVINCarCarInputInvalid / _Input_MapVINCarCarInputNotFound / _InvalidValue - KHONG co guard EffDateStart nhu cua _Add (cua _Update khong nhan EffDateStart).",
        chainRebuildNote = "Dung lai day chuyen hieu luc chay o CA _Add lan _Update."
    });
}).RequireAuthorization();

// ===== #B145 XIN CHẠY JOB MAP VIN (BO) — `Auto_MapVIN_BO_Save` =====
// Trace LIVE: `DMS40/0.20.MapVIN.2024.cs:27` — csproj dòng **357** `<Compile Include>` ⇒ **file SỐNG**.
//   **3B đo theo dải dòng tường minh, khớp cả 2 máy**: `27,236 / b7b9d892358473d9b434d984bb76a253`.
// 🔴🔴 **KHOÁ LOẠI TRỪ MỘT LƯỢT CHẠY (mutex) — điểm cốt tử của hàm này**:
//      `select top 1 t.ATMVNo, t.ATMVType from Auto_MapVIN t where **t.ProcessDTime is null**
//       order by t.ATMVNo desc`
//      `if (dtCheck.Rows.Count > 0) throw …DMS40_Auto_MapVIN_InvalidOtherProcessing;`
//   ⇒ Còn **bất kỳ** lượt nào **chưa có `ProcessDTime`** thì **mọi lượt mới bị từ chối**.
//     `ProcessDTime is null` = *"đang chạy dở"*, **không phải** "chưa bắt đầu".
//   ⚠️ Đây là **khoá mềm ở tầng ứng dụng**, không phải khoá DB: hai phiên gọi **cùng lúc** đều đọc
//     thấy "sạch" rồi cùng ghi ⇒ vẫn có thể **lọt hai lượt**. Ghi lại, **không tự thêm khoá**.
//   ⚠️ Guard **không tự dọn** lượt treo: một lượt chết giữa chừng (không kịp ghi `ProcessDTime`) sẽ
//     **chặn vĩnh viễn** mọi lượt sau cho tới khi có người sửa tay. Ghi lại, **không tự thêm hạn chờ**.
// 🔴 `objATMVNo` **bắt buộc**, rỗng ⇒ `TError.ErrHTC.DMS40_Auto_MapVIN` (**mã lỗi chung**, không có
//   mã riêng cho ô trống — thông báo sẽ không chỉ ra thiếu gì; giữ nguyên).
// 🔴 **`CommandTimeOut = 55000` giây (~15 giờ)** trên **cả `_dbMain` và `_dbWH`** — chú thích nguồn
//   `// DũngND. 20220707 55000s`. ⇒ Job này được thiết kế để chạy **rất lâu**; đừng port với timeout
//   mặc định rồi kết luận "treo".
// 📌 **NỢ**: `Auto_MapVIN_BO_GetAndSaveX` (thuật toán map VIN cho hàng BO) chưa có trong MiniHTC ⇒
//   endpoint **chỉ ghi lượt chạy + giữ khoá**, cờ `engineNotRun`. **Không sinh dữ liệu map giả.**
// 📌 §12: thực thể `AutoMapVin` + Seeder + DbSet + DTO + có ở **cả POST và GET**.
app.MapPost("/api/dms40/mapvin/bo-save", async (
    AutoMapVinBoSaveDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    var atmvNo = (dto.ATMVNo ?? "").Trim();
    if (atmvNo.Length == 0)
        return Results.BadRequest(new
        {
            error = "DMS40_Auto_MapVIN",
            check = new { ATMVNo = atmvNo },
            note = "Nguon dung MA LOI CHUNG cho o trong - khong co ma rieng; thong bao khong chi ra thieu gi. Giu nguyen."
        });

    // 🔴🔴 KHOÁ LOẠI TRỪ: còn lượt nào ProcessDTime is null ⇒ TỪ CHỐI.
    var running = await db.AutoMapVins
        .Where(a => a.OrgId == t.OrgId && a.ProcessDTime == null)
        .OrderByDescending(a => a.ATMVNo)
        .Select(a => new { a.ATMVNo, a.ATMVType }).FirstOrDefaultAsync();
    if (running is not null)
        return Results.BadRequest(new
        {
            error = "DMS40_Auto_MapVIN_InvalidOtherProcessing",
            check = new { DB_ATMVNo = running.ATMVNo, DB_ATMVType = running.ATMVType },
            mutexNote = "Con BAT KY luot nao CHUA co ProcessDTime thi MOI luot moi bi TU CHOI. 'ProcessDTime is null' = DANG CHAY DO, khong phai 'chua bat dau'."
        });

    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    db.AutoMapVins.Add(new AutoMapVin
    {
        OrgId = t.OrgId, ATMVNo = atmvNo, ATMVType = dto.ATMVType,
        ProcessDTime = null,                 // 🔴 giữ khoá cho tới khi lượt chạy kết thúc
        CreatedBy = by
    });
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        atmvNo, atmvType = dto.ATMVType,
        processDTime = (DateTime?)null,
        engineNotRun = true,
        mutexNote = "KHOA LOAI TRU MOT LUOT CHAY: 'select top 1 ... from Auto_MapVIN where ProcessDTime is null order by ATMVNo desc'; co dong nao => throw DMS40_Auto_MapVIN_InvalidOtherProcessing.",
        mutexWeaknessNote = "Day la KHOA MEM O TANG UNG DUNG, khong phai khoa DB: hai phien goi CUNG LUC deu doc thay 'sach' roi cung ghi => van co the LOT HAI LUOT. Ghi lai, KHONG tu them khoa.",
        stuckRunNote = "Guard KHONG TU DON luot treo: mot luot chet giua chung (khong kip ghi ProcessDTime) se CHAN VINH VIEN moi luot sau cho toi khi co nguoi sua tay. Ghi lai, KHONG tu them han cho.",
        timeoutNote = "CommandTimeOut = 55000 giay (~15 gio) tren CA _dbMain va _dbWH - chu thich nguon '// DungND. 20220707 55000s'. Job nay duoc thiet ke de chay RAT LAU; dung port voi timeout mac dinh roi ket luan 'treo'.",
        engineDebt = "NO: Auto_MapVIN_BO_GetAndSaveX (thuat toan map VIN cho hang BO) chua co trong MiniHTC => endpoint CHI ghi luot chay + giu khoa. KHONG sinh du lieu map gia."
    });
}).RequireAuthorization();

// ===== #B146 TRA LƯỢT CHẠY MAP VIN — `Auto_MapVIN_Get` =====
// Trace LIVE: `DMS40/zTemp.0.20.MapVIN.cs:78753` (**hàm cuối file**, 78753–79158).
//   **3B khớp cả 2 máy**: `78753,79158 / cf2cb5e064e306b0cd9b84c4c52a3253`.
// 🔴 **MƯỜI BẢY bảng kết quả trong MỘT lời gọi** — mỗi bảng một cờ `bGet_*` riêng:
//   `MySummaryTable` · `Auto_MapVIN` · `Auto_MapVIN_Car_Car` (*"Cầu"*) · `…_Car_CarHist` ·
//   `…_Car_VIN` · `…_Car_VINHist` · `…_MapRoundSpec` · `…_D2Limit` · `…_D2LimitApproveDate` ·
//   `…_D2Limit_Car_Car` · `…_D2Plan_Car_Car` · `…_D2Plan_Car_CarHist` · `…_D2Plan_Car_VIN` ·
//   `…_D2Plan_Car_VINHist` · `…_D2Plan_MapRound` · `…_D2Plan_MapRoundSpec` ·
//   `Auto_MApVIN_SortApproveDateHist` (⚠️ **viết hoa sai `MApVIN`** — giữ nguyên để khớp client).
// 🔴 Cùng khuôn phân trang `identity(bigint,0,1) MyIdxSeq` + `MyCount` **đếm trước khi cắt trang**;
//   bảng gốc sắp **`order by t.ATMVNo desc`** (mới nhất trước), khác các màn master sắp tăng dần.
// 📌 **NỢ**: 15/17 bảng phụ chưa có thực thể trong MiniHTC ⇒ trả **mảng rỗng** kèm
//   `tablesNotPorted`; **không bịa dữ liệu**.
app.MapGet("/api/dms40/mapvin/runs", async (
    AppDbContext db, ITenantContext t, string? atmvNo, string? atmvType,
    string? onlyRunning, int? recordStart, int? recordCount) =>
{
    var q = db.AutoMapVins.Where(a => a.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(atmvNo)) q = q.Where(a => a.ATMVNo == atmvNo.Trim());
    if (!string.IsNullOrWhiteSpace(atmvType)) q = q.Where(a => a.ATMVType == atmvType.Trim());
    if (onlyRunning == "1") q = q.Where(a => a.ProcessDTime == null);

    // 🔴 order by ATMVNo DESC — mới nhất trước.
    var all = await q.OrderByDescending(a => a.ATMVNo).ToListAsync();
    var myCount = all.Count;                                  // đếm TRƯỚC khi cắt trang
    var start = recordStart ?? 0;
    var count = recordCount ?? myCount;
    var page = all.Skip(start).Take(count <= 0 ? myCount : count).ToList();

    return Results.Ok(new
    {
        MySummaryTable = new[] { new { MyCount = myCount } },
        Auto_MapVIN = page.Select((a, i) => new { MyIdxSeq = start + i, a.ATMVNo, a.ATMVType, a.ProcessDTime, a.CreatedAt, a.CreatedBy }),
        Auto_MapVIN_Car_Car = Array.Empty<object>(),
        Auto_MapVIN_Car_CarHist = Array.Empty<object>(),
        Auto_MapVIN_Car_VIN = Array.Empty<object>(),
        Auto_MapVIN_Car_VINHist = Array.Empty<object>(),
        Auto_MapVIN_MapRoundSpec = Array.Empty<object>(),
        Auto_MapVIN_D2Limit = Array.Empty<object>(),
        Auto_MapVIN_D2LimitApproveDate = Array.Empty<object>(),
        Auto_MapVIN_D2Limit_Car_Car = Array.Empty<object>(),
        Auto_MapVIN_D2Plan_Car_Car = Array.Empty<object>(),
        Auto_MapVIN_D2Plan_Car_CarHist = Array.Empty<object>(),
        Auto_MapVIN_D2Plan_Car_VIN = Array.Empty<object>(),
        Auto_MapVIN_D2Plan_Car_VINHist = Array.Empty<object>(),
        Auto_MapVIN_D2Plan_MapRound = Array.Empty<object>(),
        Auto_MapVIN_D2Plan_MapRoundSpec = Array.Empty<object>(),
        Auto_MApVIN_SortApproveDateHist = Array.Empty<object>(),
        recordStart = start, recordCount = count,
        tablesNotPorted = 15,
        multiTableNote = "MUOI BAY bang ket qua trong MOT loi goi, moi bang mot co bGet_* rieng. Ten bang 'Auto_MApVIN_SortApproveDateHist' VIET HOA SAI ('MApVIN') - giu nguyen de khop client.",
        pagingNote = "Cung khuon identity(bigint,0,1) MyIdxSeq + MyCount DEM TRUOC KHI CAT TRANG; bang goc sap 'order by t.ATMVNo DESC' (moi nhat truoc) - khac cac man master sap tang dan.",
        debtNote = "NO: 15/17 bang phu chua co thuc the trong MiniHTC => tra MANG RONG. Khong bia du lieu."
    });
}).RequireAuthorization();

// ===== #B147 TRA LƯỢT KẾ HOẠCH GIAO XE — `Auto_EstimateDeliveryPlan_Get_New20181115` =====
// Trace LIVE: `DMS40/zTemp.0.21.PlanDelivery.cs:536`.
//   **3B đo theo dải dòng tường minh, khớp cả 2 máy**: `536,778 / 7842a969eacd6052bc5ab611b6811434`.
// ✅ **RBAC lành mạnh**: `myCommon_GetAbilityOfUser` **không bị comment** và
//   `alParamsCoupleSql.AddRange(new object[] { "@strBUPatternOfUser", drAbilityOfUser["BUPattern"] })`
//   ⇒ **bind quyền THẬT** (cùng nhóm với #B126 — đối lập 22 ca lỗ đã thống kê).
// 🔴 **Chỉ HAI bảng ra**: `MySummaryTable` + `Auto_EstimateDeliveryPlan` — khác hẳn `Auto_MapVIN_Get`
//   (#B146) trả **17 bảng**, dù hai màn nhìn rất giống nhau. **Không suy số bảng theo họ hàm.**
// 🔴 **Sắp theo `atedp.CreateDTime desc`** (thời điểm tạo, mới nhất trước) — **không** phải theo
//   `ATEDPNo` như #B146. Hai màn cùng họ, **hai tiêu chí sắp khác nhau**.
// 🔴 Cùng khuôn `identity(bigint,0,1) MyIdxSeq`, `MyCount` **đếm trước khi cắt trang**.
// 📌 Dùng lại thực thể `AtedpRun` (#B134) — mỗi chặng của một lượt là một dòng.
app.MapGet("/api/dms40/estimate-delivery-plans", async (
    AppDbContext db, ITenantContext t, string? atedpNo, string? atedpType,
    int? recordStart, int? recordCount) =>
{
    var q = db.AtedpRuns.Where(a => a.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(atedpNo)) q = q.Where(a => a.ATEDPNo == atedpNo.Trim());
    if (!string.IsNullOrWhiteSpace(atedpType)) q = q.Where(a => a.ATEDPType == atedpType.Trim());

    // 🔴 order by CreateDTime DESC — KHÔNG phải theo số.
    var all = await q.OrderByDescending(a => a.CreatedAt).ThenBy(a => a.StageOrder).ToListAsync();
    var myCount = all.Count;                                  // đếm TRƯỚC khi cắt trang
    var start = recordStart ?? 0;
    var count = recordCount ?? myCount;
    var page = all.Skip(start).Take(count <= 0 ? myCount : count).ToList();

    return Results.Ok(new
    {
        MySummaryTable = new[] { new { MyCount = myCount } },
        Auto_EstimateDeliveryPlan = page.Select((a, i) => new
        {
            MyIdxSeq = start + i,
            a.ATEDPNo, a.ATEDPType, a.ATEDPNoSPDBSRoot,
            a.RunId, a.StageOrder, a.EngineRan,
            CreateDTime = a.CreatedAt, a.CreatedBy
        }),
        recordStart = start, recordCount = count,
        rbacHealthyNote = "RBAC LANH MANH: myCommon_GetAbilityOfUser KHONG bi comment va alParamsCoupleSql bind '@strBUPatternOfUser' = drAbilityOfUser['BUPattern'] - QUYEN THAT (cung nhom voi #B126, doi lap 22 ca lo da thong ke).",
        twoTablesNote = "CHI HAI bang ra: MySummaryTable + Auto_EstimateDeliveryPlan - khac han Auto_MapVIN_Get (#B146) tra MUOI BAY bang, du hai man nhin rat giong nhau. KHONG suy so bang theo ho ham.",
        orderNote = "Sap theo 'atedp.CreateDTime desc' (thoi diem tao, moi nhat truoc) - KHONG phai theo ATEDPNo nhu #B146. Hai man cung ho, HAI TIEU CHI SAP KHAC NHAU.",
        pagingNote = "Cung khuon identity(bigint,0,1) MyIdxSeq, MyCount dem TRUOC khi cat trang."
    });
}).RequireAuthorization();

// ===== #B109 GÁN HOÁ ĐƠN CHUYỂN GIAO CHO VIN — `Car_VIN_UpdMulti_InvoiceTransferred` =====
// Trace LIVE: WS → **`_biz.Car_VIN_UpdMulti_InvoiceTransferred`** (`BizHTC.Car.cs:2155`) —
//   **không có hậu tố `_NewYYYYMMDD`**. 3B đo thật, **khớp cả 2 máy**: start=2155 md5
//   `59435ec67ec941897ccda120ce0a2a47`.
// 🔴 **BA ĐIỀU KIỆN NGHIỆP VỤ, chú thích nguồn ghi rõ bằng tiếng Việt** — đọc đủ cả ba:
//    **(0)** `myCar_CheckVIN_FlagisHTC(…, Flag.Active, TConst.FlagIsHTC.FlagisHTC, "", …)` —
//        chú thích: *"vin phải tạo hóa đơn TCG xuất cho HTC ⇒ cờ FlagisHTC của vin = 1"*.
//    **(1)** *"Xe **chưa có** hoá đơn HTC xuất cho đại lý **hoặc** hoá đơn đó **đã huỷ**"*:
//        `select top 1 * from VAT_HTCInvoiceDetail where VIN = @VIN and HTCStatusDetail in ('P','F','A')`
//        ⇒ **CÓ dòng** nào ở `P`/`F`/`A` là **CHẶN** (`…_ExistHTCInvoice`).
//        ⚠️ Đọc ngược rất dễ: `in ('P','F','A')` là **danh sách CÒN SỐNG**; huỷ (`R`/`C`) **không** nằm
//          trong đó nên **không chặn** — đúng ý *"hoặc đã huỷ"*.
//    **(2)** *"Có hoá đơn TCG xuất cho HTC trạng thái F (xe CKD và CBU **trừ** HR-CKD và EU-CKD)"*:
//        chỉ kiểm khi **`VAT_ModelInvoice` KHÔNG có dòng** cho model đó (`Rows.Count == 0`) —
//        tức `VAT_ModelInvoice` là **danh sách MIỄN TRỪ**; model nằm trong đó thì **bỏ qua** kiểm TCG.
//        Khi phải kiểm: `select top 1 from VAT_TCGInvoiceDetail where VIN = @VIN and
//        TCGStatusDetail **not in ('R','C','P')`** ⇒ **không có** dòng ⇒ **CHẶN**
//        (`…_TCGInvoiceNotExist`). ⚠️ `not in ('R','C','P')` = **đã duyệt trở lên**, không phải `= 'F'`.
// 🔴 **HIỆU ỨNG PHỤ CHÍNH: `FlagisHTC` bị đặt `'2'`** (`:2345`) — không phải "1"/"0". Đây là **giá trị
//    thứ ba** của cờ, đánh dấu *"đã có hoá đơn chuyển giao"*. Port bỏ dòng này ⇒ mọi màn lọc theo
//    `FlagisHTC` (vd #B51 `FrmSearchVinForTCGInvoice`) **vẫn thấy xe như chưa chuyển giao**.
// 🔴 Ghi **ba cột** + dấu vết: `InvoiceNoTransferred`, `InvoiceTransferredDate`, `FlagisHTC`,
//    `LogLUDateTime`, `LogLUBy`. Đầu vào là **BẢNG `Car_VIN`**; rỗng ⇒
//    ⚠️ ném **`Car_VIN_UpdMulti_**InvoiceFactory**_CarVINTableBlank`** — **mã lỗi của hàm KHÁC**
//    (`_InvoiceFactory`), lỗi nhãn do copy-paste. Giữ nguyên để đối chiếu log.
// 📌 NỢ: `VAT_ModelInvoice` (danh sách model miễn trừ) chưa có trong MiniHTC ⇒ cờ
//    `modelExemptionUnchecked` cho biết bước (2) **luôn phải kiểm TCG**; không bịa danh sách miễn trừ.
app.MapPost("/api/vins/update-invoice-transferred", async (
    List<VinInvoiceTransferredDto> rows, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    if (rows is null || rows.Count == 0)
        return Results.BadRequest(new { error = "Car_VIN_UpdMulti_InvoiceFactory_CarVINTableBlank" });

    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var updated = new List<object>();

    foreach (var (r, i) in rows.Select((r, i) => (r, i)))
    {
        var vin = (r.VIN ?? "").Trim().ToUpperInvariant();
        var cv = await db.CarVinMasters.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.VIN == vin);
        if (cv is null)
            return Results.BadRequest(new { error = "Common_InvalidVIN", check = new { Idx = i, VIN = vin } });
        // (0) VIN phải có cờ FlagisHTC = "1" (đã tạo hoá đơn TCG xuất cho HTC).
        if ((cv.FlagisHTC ?? "") != "1")
            return Results.BadRequest(new
            {
                error = "Car_VIN_CheckVIN_FlagisHTC_Invalid",
                check = new { Idx = i, VIN = vin, cv.FlagisHTC },
                note = "Nguon: 'vin phai tao hoa don TCG xuat cho HTC => co FlagisHTC cua vin = 1'."
            });

        // (1) CÓ dòng HTCInvoiceDetail ở 'P'/'F'/'A' ⇒ CHẶN (danh sách CÒN SỐNG; huỷ R/C không chặn).
        var htcAlive = await db.VatHtcInvoiceDetails
            .FirstOrDefaultAsync(d => d.OrgId == t.OrgId && d.VIN == vin
                && (d.HTCStatusDetail == "P" || d.HTCStatusDetail == "F" || d.HTCStatusDetail == "A"));
        if (htcAlive is not null)
            return Results.BadRequest(new
            {
                error = "Car_VIN_UpdMulti_InvoiceTransferred_ExistHTCInvoice",
                check = new { Idx = i, VIN = vin, htcAlive.HTCInvoiceCode, htcAlive.HTCStatusDetail }
            });

        // (2) `VAT_ModelInvoice` = danh sách MIỄN TRỪ; MiniHTC chưa có ⇒ luôn phải kiểm TCG.
        var tcgOk = await db.VatTcgInvoiceDetails.AnyAsync(d => d.OrgId == t.OrgId && d.VIN == vin
            && d.TCGStatusDetail != "R" && d.TCGStatusDetail != "C" && d.TCGStatusDetail != "P");
        if (!tcgOk)
            return Results.BadRequest(new
            {
                error = "Car_VIN_UpdMulti_InvoiceTransferred_TCGInvoiceNotExist",
                check = new { Idx = i, VIN = vin },
                note = "Dieu kien: VAT_TCGInvoiceDetail co dong voi TCGStatusDetail NOT IN ('R','C','P') - tuc DA DUYET TRO LEN, khong phai = 'F'."
            });

        cv.InvoiceNoTransferred = (r.InvoiceNoTransferred ?? "").Trim();
        cv.InvoiceTransferredDate = r.InvoiceTransferredDate;
        cv.FlagisHTC = "2";                       // 🔴 GIÁ TRỊ THỨ BA của cờ
        cv.LogLUDateTime = now; cv.LogLUBy = by;
        updated.Add(new { vin, cv.InvoiceNoTransferred, cv.InvoiceTransferredDate, flagisHTC = cv.FlagisHTC });
    }
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        updatedCount = updated.Count, updated,
        modelExemptionUnchecked = true,
        threeGuardsNote = "BA DIEU KIEN NGHIEP VU (chu thich nguon ghi ro bang tieng Viet): (0) myCar_CheckVIN_FlagisHTC(..., Flag.Active, FlagIsHTC.FlagisHTC, ...) - 'vin phai tao hoa don TCG xuat cho HTC => co FlagisHTC cua vin = 1'; (1) 'Xe CHUA CO hoa don HTC xuat cho dai ly HOAC hoa don do DA HUY'; (2) 'Co hoa don TCG xuat cho HTC trang thai F (xe CKD va CBU TRU HR-CKD va EU-CKD)'.",
        aliveListNote = "Dieu kien (1) dung 'HTCStatusDetail in (P,F,A)' - day la DANH SACH CON SONG: CO dong nao trong do la CHAN. Huy (R/C) KHONG nam trong danh sach nen KHONG chan - dung y 'hoac da huy'. Doc nguoc rat de.",
        exemptionListNote = "Dieu kien (2) CHI kiem khi VAT_ModelInvoice KHONG CO dong cho model do (Rows.Count == 0) => VAT_ModelInvoice la DANH SACH MIEN TRU; model nam trong do thi BO QUA kiem TCG. Khi phai kiem: TCGStatusDetail NOT IN ('R','C','P') = DA DUYET TRO LEN, KHONG phai = 'F'.",
        flagThirdValueNote = "HIEU UNG PHU CHINH: FlagisHTC bi dat '2' (:2345) - khong phai '1'/'0'. Day la GIA TRI THU BA cua co, danh dau 'da co hoa don chuyen giao'. Port bo dong nay => moi man loc theo FlagisHTC (vd #B51 FrmSearchVinForTCGInvoice) VAN THAY XE NHU CHUA CHUYEN GIAO.",
        errorNameQuirk = "Lo rong => nem 'Car_VIN_UpdMulti_InvoiceFactory_CarVINTableBlank' - MA LOI CUA HAM KHAC (_InvoiceFactory), loi nhan do copy-paste. Giu nguyen de doi chieu log.",
        modelInvoiceDebt = "NO: VAT_ModelInvoice (danh sach model MIEN TRU) chua co trong MiniHTC => buoc (2) LUON PHAI kiem TCG. Khong bia danh sach mien tru."
    });
}).RequireAuthorization();

// ===== #B110 SỬA HÀNG LOẠT HỒ SƠ THẾ CHẤP CỦA VIN — `Car_VIN_UpdMulti_Profile_New20210521` =====
// Trace LIVE: WS → **`_biz.Car_VIN_UpdMulti_Profile_New20210521`** (`BizHTC.Car.cs:2495`).
//   3B đo thật, **khớp cả 2 máy**: start=2495 md5 `f22a0a8ed9ac87c1f9b48662fa9df96c`.
// 🔴 **GUARD CẶP NGÀY — HAI CHIỀU, KHÔNG ĐỐI XỨNG** (`:2753-2790`):
//    · `MortageEndDate < MortageStartDate` ⇒ ném `File_CarVINUpdate_InvalidMortageEnd`;
//    · **`MortageStartDate` RỖNG mà `MortageEndDate` CÓ** ⇒ **cũng ném** — tức **không được nhập ngày
//      kết thúc khi chưa có ngày bắt đầu**. Chiều ngược lại (**có start, không end**) thì **HỢP LỆ**.
//    ⚠️ Nguồn còn nhét **cả biểu thức điều kiện dưới dạng CHUỖI** vào tham số chẩn đoán
//      (`"Check.ConditionErrRaise", "(objMortageStartDate != DBNull.Value && …)"`) — port giữ lại
//      để đối chiếu log nguồn.
// 🔴 **"Xe ĐÃ tạo giải chấp thì KHÔNG được sửa mã ngân hàng bàn giao tài sản"** (chú thích nguyên văn):
//    guard **chỉ chạy khi `MortageBankCode` THAY ĐỔI** (`if (!StringEqualIgnoreCase(mới, cũ))`),
//    rồi dò `RD_ReqRedeemDtl` với `DMReqDtlStatus **not in ('R','C')`** ⇒ có dòng ⇒ ném
//    `CarVINUpdate_ExistRDNo`. Sửa các trường **khác** vẫn được — **guard điều kiện kép** (khuôn #B87).
//    ⚠️ Chú thích nguồn ngay trong SQL: *"K cần vì chỉ có A,P"* — tác giả biết `not in ('R','C')`
//      là thừa nhưng **vẫn giữ**; port giữ nguyên.
//    ⚠️ **Lỗi nhãn**: tham số chẩn đoán `"MortageBankCode_Update"` lại gán **`objMortageEndDate`**
//      (copy-paste sai biến) — giữ nguyên để đối chiếu log.
// 🔴 **`PackingListNo` là BẮT BUỘC**: `if (Rows[0]["PackingListNo"] == DBNull.Value) throw
//    CarVINUpdate_InvalidPackingListNo` ⇒ VIN **chưa gắn packing list** không sửa hồ sơ được.
// ⚠️ **HAI guard ĐÃ BỊ COMMENT** — port thêm lại là **chặt hơn nguồn**:
//    · kiểm `DocumentsStatus == Stage.Pending` (`:2639-2649`);
//    · kiểm `MortageStartDate` so với `CODate` (`:2721-2752`), kèm cả `CODate` rỗng.
//      Biến `objCODate` cũng **bị comment ở chỗ khai báo** ⇒ **`CODate` không còn tham gia** hàm này.
// ⚠️ Chú thích nguồn: *"Ngày giao hồ sơ **LUÔN truyền vào Null**: lý do nhập cùng BillNo"*
//    ⇒ màn này **không** đặt ngày giao hồ sơ, dù bộ cột có `DRFullDocDate`.
// 🔴 `MyBuildDBDT_Common` ghi **12 cột**: `VIN` · `MortageStartDate` · `MortageEndDate` ·
//    `StatusMortageEnd` · `LogDateTimeStatusMortageEnd` · `DRFullDocDate` · `CQNo` · `CONo` ·
//    `MortageBankCode` · `RedeemDate` · `LogLUDateTime` · `LogLUBy`.
// 📌 §12: `CarVinMaster.StatusMortageEnd` · `.LogDateTimeStatusMortageEnd` · `.DRFullDocDate` ·
//    `.CQNo` · `.CONo`.
app.MapPost("/api/vins/update-profile-multi", async (
    List<VinProfileUpdDto> rows, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    if (rows is null || rows.Count == 0)
        return Results.BadRequest(new { error = "Car_VIN_UpdMulti_Profile_CarVINTableBlank" });

    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var updated = new List<object>();

    foreach (var (r, i) in rows.Select((r, i) => (r, i)))
    {
        var vin = (r.VIN ?? "").Trim().ToUpperInvariant();
        var cv = await db.CarVinMasters.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.VIN == vin);
        if (cv is null)
            return Results.BadRequest(new { error = "Common_InvalidVIN", check = new { Idx = i, VIN = vin } });

        // 🔴 `PackingListNo` BẮT BUỘC.
        if (string.IsNullOrWhiteSpace(cv.PackingListNo))
            return Results.BadRequest(new
            {
                error = "CarVINUpdate_InvalidPackingListNo",
                check = new { Idx = i, VIN = vin, cv.PackingListNo }
            });

        // 🔴 GUARD CẶP NGÀY — hai chiều, KHÔNG đối xứng.
        if (r.MortageStartDate is not null && r.MortageEndDate is not null
            && r.MortageEndDate < r.MortageStartDate)
            return Results.BadRequest(new
            {
                error = "File_CarVINUpdate_InvalidMortageEnd",
                check = new
                {
                    VIN = vin, r.MortageStartDate, r.MortageEndDate,
                    Check_ConditionErrRaise = "(objMortageStartDate != DBNull.Value && objMortageEndDate != DBNull.Value && (Convert.ToDateTime(objMortageEndDate) < Convert.ToDateTime(objMortageStartDate)))"
                }
            });
        if (r.MortageStartDate is null && r.MortageEndDate is not null)
            return Results.BadRequest(new
            {
                error = "File_CarVINUpdate_InvalidMortageEnd",
                check = new
                {
                    VIN = vin, r.MortageStartDate, r.MortageEndDate,
                    Check_ConditionErrRaise = "(objMortageStartDate == DBNull.Value && objMortageEndDate != DBNull.Value)"
                },
                note = "KHONG duoc nhap ngay ket thuc khi chua co ngay bat dau. Chieu nguoc lai (co start, khong end) thi HOP LE."
            });

        // 🔴 Chỉ kiểm khi ĐỔI mã ngân hàng — guard điều kiện kép.
        var bankNew = (r.MortageBankCode ?? "").Trim();
        var bankOld = (cv.MortageBankCode ?? "").Trim();
        if (!string.Equals(bankNew, bankOld, StringComparison.OrdinalIgnoreCase))
        {
            var rd = await db.ReqRedeemDtls
                .FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.VIN == vin
                    && x.DMReqDtlStatus != "R" && x.DMReqDtlStatus != "C");
            if (rd is not null)
                return Results.BadRequest(new
                {
                    error = "CarVINUpdate_ExistRDNo",
                    check = new
                    {
                        VIN = vin, MortageBankCode_old = bankOld,
                        // ⚠️ Lỗi nhãn của nguồn: gán objMortageEndDate cho "MortageBankCode_Update".
                        MortageBankCode_Update = r.MortageEndDate,
                        ReqDMNo = rd.DRListCode   // MiniHTC: dau moi tuong duong ReqDMNo cua nguon
                    },
                    note = "Xe DA tao giai chap thi KHONG duoc sua ma ngan hang ban giao tai san. Guard CHI chay khi MortageBankCode THAY DOI."
                });
        }

        // 12 cột của `MyBuildDBDT_Common`.
        cv.MortageStartDate = r.MortageStartDate;
        cv.MortageEndDate = r.MortageEndDate;
        cv.StatusMortageEnd = r.StatusMortageEnd;
        cv.LogDateTimeStatusMortageEnd = r.StatusMortageEnd is null ? cv.LogDateTimeStatusMortageEnd : now;
        cv.DRFullDocDate = r.DRFullDocDate;
        cv.CQNo = string.IsNullOrWhiteSpace(r.CQNo) ? null : r.CQNo.Trim();
        cv.CONo = string.IsNullOrWhiteSpace(r.CONo) ? null : r.CONo.Trim();
        cv.MortageBankCode = string.IsNullOrWhiteSpace(bankNew) ? null : bankNew;
        cv.RedeemDate = r.RedeemDate;
        cv.LogLUDateTime = now; cv.LogLUBy = by;
        updated.Add(new { vin, cv.MortageStartDate, cv.MortageEndDate, cv.MortageBankCode, cv.RedeemDate });
    }
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        updatedCount = updated.Count, updated,
        datePairGuardNote = "GUARD CAP NGAY HAI CHIEU, KHONG DOI XUNG: (a) MortageEndDate < MortageStartDate => nem InvalidMortageEnd; (b) MortageStartDate RONG ma MortageEndDate CO => CUNG NEM. Chieu nguoc lai (co start, khong end) thi HOP LE. Nguon nhet ca BIEU THUC dieu kien duoi dang CHUOI vao tham so chan doan 'Check.ConditionErrRaise' - port giu lai de doi chieu log.",
        bankChangeGuardNote = "'Xe DA tao giai chap thi KHONG duoc sua ma ngan hang ban giao tai san': guard CHI chay khi MortageBankCode THAY DOI, roi do RD_ReqRedeemDtl voi DMReqDtlStatus NOT IN ('R','C') => co dong => nem CarVINUpdate_ExistRDNo. Sua cac truong KHAC van duoc (guard dieu kien kep - khuon #B87). Chu thich trong SQL: 'K can vi chi co A,P' - tac gia biet not in (R,C) la thua nhung VAN GIU.",
        labelBugNote = "LOI NHAN cua nguon: tham so chan doan 'MortageBankCode_Update' lai gan objMortageEndDate (copy-paste sai bien). Giu nguyen de doi chieu log.",
        packingListNote = "PackingListNo la BAT BUOC: VIN chua gan packing list KHONG sua ho so duoc (CarVINUpdate_InvalidPackingListNo).",
        commentedGuardsNote = "HAI guard DA BI COMMENT - port them lai la CHAT HON NGUON: (1) kiem DocumentsStatus == Stage.Pending (:2639-2649); (2) kiem MortageStartDate so voi CODate (:2721-2752). Bien objCODate cung BI COMMENT o cho khai bao => CODate KHONG CON tham gia ham nay.",
        docDateNote = "Chu thich nguon: 'Ngay giao ho so LUON truyen vao Null: ly do nhap cung BillNo' => man nay KHONG dat ngay giao ho so, du bo cot co DRFullDocDate.",
        writeColsNote = "MyBuildDBDT_Common ghi 12 cot: VIN, MortageStartDate, MortageEndDate, StatusMortageEnd, LogDateTimeStatusMortageEnd, DRFullDocDate, CQNo, CONo, MortageBankCode, RedeemDate, LogLUDateTime, LogLUBy."
    });
}).RequireAuthorization();

// ===== #B111 GỬI MAIL YÊU CẦU HỒ SƠ THEO VIN — `Car_VIN_SendMailForDoc` =====
// Trace LIVE: WS → `_biz.Car_VIN_SendMailForDoc` (`BizHTC.Car.cs:3373`) → thân thật ở
//   **`Car_VIN_SendMailForDocX`** (`:3494`). **Không có hậu tố `_NewYYYYMMDD`**.
//   3B đo thật, **khớp cả 2 máy**: start=3494 md5 `8aaadb9e02fafd54218fe2ec8e18ecaa`.
// 🔴🔴 **GUARD ĐỌC NGƯỢC RẤT DỄ SAI — điều kiện CHẶN là `MortageEndDate IS NULL`**:
//      `select t.VIN, t.MortageEndDate from Car_VIN t where t.VIN = '@strVIN' **and
//       t.MortageEndDate is null**;`   →   `if (dtCheck.Rows.Count > 0) throw
//       Car_VIN_SendMailForDocX_InvalidMortageEndDate`
//    ⇒ **CÓ dòng nghĩa là VIN CHƯA kết thúc thế chấp ⇒ CHẶN gửi mail.**
//    Chỉ gửi được cho VIN **đã có `MortageEndDate`**. Đọc lướt thành "phải có `MortageEndDate` thì
//    mới chặn" là **đảo ngược hoàn toàn** tập VIN được gửi.
//    ⚠️ Nguồn chép cả điều kiện vào chẩn đoán: `"Check.ConditionRaiseError", "t.MortageEndDate is null"`
//      — port giữ nguyên chuỗi để log hai bên khớp (khuôn `C0-…quingentesimusquartus`).
//    ⚠️ Guard chạy **theo TỪNG VIN trong lô** và **ném ngay** ở VIN đầu tiên hỏng ⇒ **cả lô không gửi**.
// 🔴 **KHOÁ GOM NHÓM GỬI MAIL = CẶP `(DealerCode, BankCodeMyFilter)`** (`select distinct`) ⇒
//    **một email cho MỖI cặp (đại lý, ngân hàng)** — cùng khuôn gom nhóm của #B86. Gom sai khoá
//    ⇒ **sai SỐ LƯỢNG email gửi ra ngoài**, và đây là **hiệu ứng ra khỏi hệ thống** (không undo được).
// 🔴 **Ngân hàng lấy qua BẢO LÃNH, không phải từ `Car_VIN`**: `Car_Car → Pmt_GuaranteeDetail
//    (`GuaranteeDetailStatus not in ('R','C')`) → Pmt_Guarantee (`GuaranteeStatus not in ('R','C')`)`
//    — **cả hai** đều `left join` **mang điều kiện trong `on`** ⇒ bảo lãnh đã huỷ/từ chối **chỉ bị bỏ
//    ghép** (BankCode = null), **KHÔNG loại VIN** khỏi danh sách gửi.
//    ⚠️ `inner join Car_Car` thì **có** loại: VIN không có bản ghi xe **bị bỏ hẳn**.
// 📌 **NỢ — KHÔNG GỬI MAIL THẬT**: `DMS40_Email_BatchSendEmail_CarVINSendMailForDoc` là tầng gửi mail
//    hàng loạt, MiniHTC **chưa có**. Endpoint này **chỉ DỰNG danh sách nhóm nhận** và trả về để đối
//    chiếu; cờ `emailNotSent = true`. **Cố ý không tự gửi** — hiệu ứng ra ngoài phải do nghiệp vụ bật.
app.MapPost("/api/vins/send-mail-for-doc", async (
    List<string> vins, AppDbContext db, ITenantContext t) =>
{
    // Bảng đầu vào: thiếu ⇒ NotFound; rỗng ⇒ TỪ CHỐI.
    if (vins is null)
        return Results.BadRequest(new { error = "Car_VIN_SendMailForDocX_Input_Car_VINTblNotFound" });
    var list = vins.Select(x => (x ?? "").Trim().ToUpperInvariant()).Where(x => x.Length > 0).Distinct().ToList();
    if (list.Count == 0)
        return Results.BadRequest(new { error = "Car_VIN_SendMailForDocX_Input_Car_VINTblInvalid" });

    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && list.Contains(c.VIN)).ToListAsync();

    // 🔴 CHẶN nếu VIN CHƯA kết thúc thế chấp (`MortageEndDate is null`) — ném ngay ở VIN đầu tiên.
    foreach (var vin in list)
    {
        var cv = cars.FirstOrDefault(c => c.VIN == vin);
        if (cv is null)
            return Results.BadRequest(new { error = "Common_InvalidVIN", check = new { VIN = vin } });
        if (cv.MortageEndDate is null)
            return Results.BadRequest(new
            {
                error = "Car_VIN_SendMailForDocX_InvalidMortageEndDate",
                check = new
                {
                    VIN = vin, cv.MortageEndDate,
                    Check_ConditionRaiseError = "t.MortageEndDate is null",
                    Check_ErrRows_Count = 1
                },
                guardNote = "CO dong nghia la VIN CHUA ket thuc the chap => CHAN gui mail. Chi gui duoc cho VIN DA CO MortageEndDate. Guard chay theo TUNG VIN va NEM NGAY o VIN dau tien hong => CA LO khong gui."
            });
    }

    // `inner join Car_Car` — VIN không có bản ghi xe bị BỎ HẲN.
    var withCar = cars.Where(c => c.DealerCode != null).ToList();
    var droppedNoCarCar = cars.Count - withCar.Count;

    // Ngân hàng lấy QUA BẢO LÃNH; `left join` mang điều kiện ⇒ bảo lãnh huỷ chỉ mất BankCode.
    var grtDtls = await db.BankGuaranteeDtls
        .Where(d => d.OrgId == t.OrgId && list.Contains(d.VIN)).ToListAsync();
    var grtIds = grtDtls.Select(d => d.GuaranteeId).Distinct().ToList();
    var grts = (await db.BankGuarantees.Where(g => g.OrgId == t.OrgId && grtIds.Contains(g.Id)).ToListAsync())
        .ToDictionary(g => g.Id);

    var rowsFull = withCar.Select(c =>
    {
        var dtl = grtDtls.FirstOrDefault(d => d.VIN == c.VIN
            && d.GuaranteeDetailStatus != "R" && d.GuaranteeDetailStatus != "C");
        BankGuarantee? g = null;
        if (dtl is not null) grts.TryGetValue(dtl.GuaranteeId, out g);
        var bankOk = g is not null && g.Status != "R" && g.Status != "C";
        return new
        {
            c.VIN, c.DealerCode,
            BankCode = bankOk ? g!.BankCode : null,
            GuaranteeNo = bankOk ? g!.GuaranteeNo : null
        };
    }).ToList();

    // 🔴 GOM NHÓM = CẶP (DealerCode, BankCode) — MỘT email cho MỖI cặp.
    var groups = rowsFull
        .GroupBy(x => (x.DealerCode, x.BankCode))
        .OrderBy(g => g.Key.DealerCode, StringComparer.Ordinal)
        .Select(g => new
        {
            dealerCode = g.Key.DealerCode,
            bankCodeMyFilter = g.Key.BankCode,
            vinCount = g.Count(),
            vins = g.Select(x => x.VIN).OrderBy(x => x, StringComparer.Ordinal).ToList(),
            guaranteeNos = g.Select(x => x.GuaranteeNo).Where(x => x != null).Distinct().ToList()
        }).ToList();

    return Results.Ok(new
    {
        inputVins = list.Count,
        droppedNoCarCar,
        emailGroupCount = groups.Count,
        groups,
        emailNotSent = true,
        guardInvertedNote = "GUARD DOC NGUOC RAT DE SAI: dieu kien CHAN la 'MortageEndDate IS NULL'. Cau kiem 'select ... where VIN = @VIN and t.MortageEndDate is null' roi 'if (Rows.Count > 0) throw' => CO dong nghia la VIN CHUA ket thuc the chap => CHAN. CHI gui duoc cho VIN DA CO MortageEndDate. Doc luot thanh 'phai co MortageEndDate thi moi chan' la DAO NGUOC hoan toan tap VIN duoc gui.",
        batchAbortNote = "Guard chay theo TUNG VIN trong lo va NEM NGAY o VIN dau tien hong => CA LO khong gui, khong phai bo qua rieng VIN do.",
        groupingNote = "KHOA GOM NHOM GUI MAIL = CAP (DealerCode, BankCodeMyFilter) qua 'select distinct' => MOT EMAIL cho MOI cap (dai ly, ngan hang) - cung khuon gom nhom cua #B86. Gom sai khoa => SAI SO LUONG EMAIL GUI RA NGOAI, va day la HIEU UNG RA KHOI HE THONG (khong undo duoc).",
        bankViaGuaranteeNote = "Ngan hang lay QUA BAO LANH, khong phai tu Car_VIN: Car_Car -> Pmt_GuaranteeDetail (GuaranteeDetailStatus not in R,C) -> Pmt_Guarantee (GuaranteeStatus not in R,C). CA HAI deu left join MANG DIEU KIEN TRONG 'on' => bao lanh da huy/tu choi CHI BI BO GHEP (BankCode = null), KHONG loai VIN khoi danh sach gui. Rieng 'inner join Car_Car' THI CO loai.",
        emailDebt = "NO - KHONG GUI MAIL THAT: DMS40_Email_BatchSendEmail_CarVINSendMailForDoc (tang gui mail hang loat) chua co trong MiniHTC. Endpoint nay CHI DUNG danh sach nhom nhan va tra ve de doi chieu. CO Y khong tu gui - hieu ung ra ngoai phai do nghiep vu bat."
    });
}).RequireAuthorization();

// ===== #B112 ĐÓNG THÙNG XE — `CarVINUpdate_TypeCB_New20181115` =====
// Trace LIVE: WS → **`_biz.CarVINUpdate_TypeCB_New20181115`** (`BizHTC.Car.cs:1216`).
//   3B đo thật, **khớp cả 2 máy**: start=1216 md5 `1322c2af2563cf4b8244943b23022734`.
// 🔴 **TỪ VỰNG `TConst.CVTypeCB` có BA giá trị** (`Const.Main.cs:669-674`), **không phải cờ nhị phân**:
//      **`"Y"`** đã đóng thùng · **`"N"`** chưa đóng thùng · **`"NONE"`** bình thường (không đóng thùng).
//    Guard vào: **chỉ VIN đang `"N"`** mới đóng thùng được (`…_InvalidVINTypeCB`) ⇒ xe `"NONE"`
//    (không thuộc diện đóng thùng) **cũng bị chặn**, không chỉ xe đã đóng rồi.
//    Hiệu ứng: `TypeCB` ← **`"Y"`**.
// 🔴 **NĂM guard trước khi ghi** — port thiếu bất kỳ cái nào là nới lỏng nghiệp vụ:
//    1. `TypeCB` phải `= "N"`;
//    2. `LoaiThung` **bắt buộc** (`…_LoaiThungNotNull`) và phải nằm trong danh mục (`…_LoaiThungNotValid`);
//    3. `StorageCodeCurrent` **bắt buộc** (`…_InvalidStorageCodeCurrent`) và kho đó phải có
//       **`StorageType`** hợp lệ (`…_InvalidStorageType`);
//    4. `PackingListNo` **bắt buộc** (`…_InvalidPackingListNo`) — cùng guard với #B110;
//    5. `InspectionDate` hợp lệ (`…_InvalidInspectionDate`).
//    ⚠️ Ngoài ra, khi có `ActualSpec`: **`RootSpec` của `ActualSpec` phải TRÙNG `RootSpec` của
//      `SpecCode` hiện tại** — tức chỉ được đổi sang spec **cùng gốc**.
// 🔴 **GHI CÓ ĐIỀU KIỆN — `alColumnEffective` thay đổi theo dữ liệu vào** (`:1640-1656`):
//    · **luôn** ghi: `TypeCB` (hằng `"Y"`) + `LoaiThung`;
//    · `ActualSpec` **chỉ ghi khi khác rỗng**;
//    · `SerialNo` **chỉ ghi khi khác rỗng**;
//    · `InspectionDate` chỉ ghi khi khác rỗng **VÀ khác `DateTime.MinValue.ToString("yyyy-MM-dd")`**
//      ⇒ chuỗi **`"0001-01-01"` được coi là RỖNG**, không phải ngày thật.
//    ⇒ Port gán vô điều kiện sẽ **XOÁ** `ActualSpec`/`SerialNo` cũ khi client gửi rỗng.
// 🔴 Ghi **cả `_dbMain` và `_dbWH`**.
// 📌 §12: `CarVinMaster.InspectionDate`.
app.MapPost("/api/vins/{vin}/close-box", async (
    string vin, VinCloseBoxDto dto, AppDbContext db, ITenantContext t) =>
{
    var code = (vin ?? "").Trim().ToUpperInvariant();
    var cv = await db.CarVinMasters.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.VIN == code);
    if (cv is null) return Results.NotFound(new { error = "Common_InvalidVIN", check = new { VIN = code } });

    // (1) CHỈ VIN đang "N" (chưa đóng thùng) — "NONE" cũng bị chặn.
    var typeCb = (cv.TypeCB ?? "").Trim();
    if (!string.Equals(typeCb, "N", StringComparison.OrdinalIgnoreCase))
        return Results.BadRequest(new
        {
            error = "CarVINUpdate_TypeCB_InvalidVINTypeCB",
            check = new { VIN = code, Check_TypeCB = typeCb },
            vocabNote = "TConst.CVTypeCB co BA gia tri: 'Y' da dong thung | 'N' chua dong thung | 'NONE' binh thuong (khong dong thung). CHI VIN dang 'N' moi dong thung duoc => xe 'NONE' CUNG BI CHAN."
        });

    // (2) LoaiThung bắt buộc + phải có trong danh mục.
    var loaiThung = (dto.LoaiThung ?? "").Trim();
    if (loaiThung.Length == 0)
        return Results.BadRequest(new { error = "CarVINUpdate_TypeCB_LoaiThungNotNull", check = new { VIN = code } });
    var loaiThungOk = await db.Masters.AnyAsync(m => m.OrgId == t.OrgId && m.Category == "LoaiThung" && m.Code == loaiThung);
    if (!loaiThungOk)
        return Results.BadRequest(new { error = "CarVINUpdate_TypeCB_LoaiThungNotValid", check = new { VIN = code, LoaiThung = loaiThung } });

    // (3) StorageCodeCurrent bắt buộc + kho phải có StorageType.
    var storageCode = (cv.StorageCodeCurrent ?? "").Trim();
    if (storageCode.Length == 0)
        return Results.BadRequest(new { error = "CarVINUpdate_TypeCB_InvalidStorageCodeCurrent", check = new { VIN = code, cv.StorageCodeCurrent } });
    var storage = await db.Storages.FirstOrDefaultAsync(s => s.OrgId == t.OrgId && s.StorageCode == storageCode);
    if (storage is null || string.IsNullOrWhiteSpace(storage.StorageType))
        return Results.BadRequest(new { error = "CarVINUpdate_TypeCB_InvalidStorageType", check = new { VIN = code, StorageCode = storageCode, storage?.StorageType } });

    // (4) PackingListNo bắt buộc (cùng guard #B110).
    if (string.IsNullOrWhiteSpace(cv.PackingListNo))
        return Results.BadRequest(new { error = "CarVINUpdate_TypeCB_InvalidPackingListNo", check = new { VIN = code, cv.PackingListNo } });

    // (5) ActualSpec (nếu có) phải CÙNG RootSpec với SpecCode hiện tại.
    var actualSpec = (dto.ActualSpec ?? "").Trim();
    if (actualSpec.Length > 0)
    {
        var specCur = await db.CarSpecs.FirstOrDefaultAsync(s => s.OrgId == t.OrgId && s.SpecCode == (cv.SpecCode ?? ""));
        var specNew = await db.CarSpecs.FirstOrDefaultAsync(s => s.OrgId == t.OrgId && s.SpecCode == actualSpec);
        if (specNew is null)
            return Results.BadRequest(new { error = "Common_InvalidSpecCode", check = new { VIN = code, ActualSpec = actualSpec } });
        if (!string.Equals(specCur?.RootSpec ?? "", specNew.RootSpec ?? "", StringComparison.OrdinalIgnoreCase))
            return Results.BadRequest(new
            {
                error = "CarVINUpdate_TypeCB_InvalidActualSpecRootSpec",
                check = new { VIN = code, SpectCode_RootSpec = specCur?.RootSpec, ActualSpec_RootSpec = specNew.RootSpec },
                note = "Chi duoc doi sang spec CUNG GOC (RootSpec)."
            });
    }

    // 🔴 GHI CÓ ĐIỀU KIỆN — alColumnEffective thay đổi theo dữ liệu vào.
    var written = new List<string> { "TypeCB", "LoaiThung" };
    cv.TypeCB = "Y";                                    // hằng `CVTypeCB.DongThung`
    cv.LoaiThung = loaiThung;
    if (actualSpec.Length > 0) { cv.ActualSpec = actualSpec; written.Add("ActualSpec"); }
    var serialNo = (dto.SerialNo ?? "").Trim();
    if (serialNo.Length > 0) { cv.SerialNo = serialNo; written.Add("SerialNo"); }
    // `"0001-01-01"` (DateTime.MinValue) được coi là RỖNG.
    if (dto.InspectionDate is not null && dto.InspectionDate.Value.Date != DateTime.MinValue.Date)
    { cv.InspectionDate = dto.InspectionDate; written.Add("InspectionDate"); }

    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        vin = code, cv.TypeCB, cv.LoaiThung, cv.ActualSpec, cv.SerialNo, cv.InspectionDate,
        columnsWritten = written,
        vocabNote = "TConst.CVTypeCB co BA gia tri (Const.Main.cs:669-674), KHONG phai co nhi phan: 'Y' da dong thung | 'N' chua dong thung | 'NONE' binh thuong. Guard vao chi nhan 'N'.",
        fiveGuardsNote = "NAM guard truoc khi ghi: (1) TypeCB phai = 'N'; (2) LoaiThung BAT BUOC + phai co trong danh muc; (3) StorageCodeCurrent BAT BUOC + kho phai co StorageType hop le; (4) PackingListNo BAT BUOC (cung guard #B110); (5) InspectionDate hop le. Ngoai ra: ActualSpec (neu co) phai CUNG RootSpec voi SpecCode hien tai - chi duoc doi sang spec CUNG GOC.",
        conditionalWriteNote = "GHI CO DIEU KIEN - alColumnEffective THAY DOI THEO DU LIEU VAO (:1640-1656): LUON ghi TypeCB (hang 'Y') + LoaiThung; ActualSpec CHI ghi khi khac rong; SerialNo CHI ghi khi khac rong; InspectionDate chi ghi khi khac rong VA khac DateTime.MinValue.ToString('yyyy-MM-dd') => chuoi '0001-01-01' duoc coi la RONG. Port gan vo dieu kien se XOA ActualSpec/SerialNo cu khi client gui rong.",
        twoDbNote = "Nguon SaveData('Car_VIN', ...) HAI LAN - _dbMain va _dbWH."
    });
}).RequireAuthorization();

// ===== #B113 TRA DANH SÁCH VIN THEO LÔ LỚN — `CarVINGetList_New20181115` =====
// Trace LIVE: **HAI** điểm vào WS (`:14806` và `:53953`) cùng gọi
//   `_biz.CarVINGetList_New20181115` (`BizHTC.Car.cs:1045`).
//   3B đo thật, **khớp cả 2 máy**: start=1045 md5 `a34b3661b5921a5408ede477c089424c`.
// 🔴🔴 **CHIA LÔ VÌ GIỚI HẠN THAM SỐ CỦA SQL SERVER — `myUtil_GetDataForHugeList`**
//    (`BizHTC.Common.cs:614`): danh sách VIN bị **cắt thành từng lô
//    `TConst.HTCConst.MaxParamsSqlSv` = **2000** phần tử** (`Const.Main.cs:325`, chú thích nguồn:
//    *"Must be less than 2100 - limited by SqlServer"*), chạy **cùng câu SQL nhiều lần**, rồi
//    **`UnionAll`** kết quả lại.
//    ⇒ Đây là lý do hàm tên *"HugeList"*. Port dùng `IN (...)` một phát với danh sách > 2000 VIN sẽ
//      **vỡ ở SQL Server thật**; MiniHTC/Postgres không vỡ nhưng **phải giữ nguyên ngữ nghĩa gộp**
//      (`UnionAll`, **không** distinct) để số dòng khớp nguồn.
//    ⚠️ `UnionAll(ref dtResult, ref dtGetData, **false**)` — tham số cuối `false` = **KHÔNG khử trùng**.
// 🔴 **RBAC biến thể 2 — ca thứ 20**: `myUtil_GetDataForHugeList` bind
//    `"@strBUPatternOfUser", drAbilityOfUser["BUPattern"]` (**quyền THẬT**, hiếm!) nhưng **bước 3 cho
//    thấy SQL của `CarVINGetList` KHÔNG dùng tham số này** (`grep -c` trong vùng hàm = **0**).
//    ⇒ Hàm dùng chung có sẵn quyền thật, **nhưng câu SQL bỏ qua** ⇒ vẫn **không lọc phạm vi**.
//    (Đối chiếu: `CarCarGetList_New20181115` cùng file **có** 1 lần dùng — sẽ kiểm ở đơn vị riêng.)
// 🔴 **Bí danh CÓ TIỀN TỐ để tránh đè cột** (khuôn #B93/#B97/#B102): `cv.*` giữ nguyên tên, còn
//    `CT_PackingList` → **`CTPL…`**, `Car_Car` → **`CC…`**, `CT_Declaration` → **`CTD…`**.
//    ⚠️ Hai chỗ **lệch khuôn**: `ctt.DeclarationNo` mang bí danh **`CTPLDeclarationNo`** (tiền tố
//      `CTPL` nhưng lấy từ bảng **`CT_TKHQ`**, không phải `CT_PackingList`); và `ctlc.BankName` /
//      `ctlc.ContractNo` **không có tiền tố nào**. Giữ nguyên để đối chiếu.
// 🔴 `inner join Car_VIN` (bắt buộc) + **BỐN `left join`** làm giàu: `CT_TKHQ` (theo `DeclarationNo`),
//    `CT_PackingList`, `CT_LC`, `CT_Declaration`, `Car_Car` — thiếu bảng nào chỉ để trống, **không loại dòng**.
app.MapPost("/api/vins/get-list", async (
    List<string> vins, AppDbContext db, ITenantContext t, int? batchSize) =>
{
    if (vins is null || vins.Count == 0)
        return Results.BadRequest(new { error = "CarVINGetList_InvalidVINList" });

    // `TConst.HTCConst.MaxParamsSqlSv` = 2000 (phải < 2100 — giới hạn của SQL Server).
    const int MaxParamsSqlSv = 2000;
    var step = Math.Clamp(batchSize ?? MaxParamsSqlSv, 1, MaxParamsSqlSv);
    var list = vins.Select(x => (x ?? "").Trim().ToUpperInvariant()).Where(x => x.Length > 0).ToList();

    var pls = (await db.PackingLists.Where(p => p.OrgId == t.OrgId).ToListAsync())
        .GroupBy(p => p.PLNo).ToDictionary(g => g.Key, g => g.First());
    var tkhqs = (await db.CtTkhqs.Where(k => k.OrgId == t.OrgId).ToListAsync())
        .GroupBy(k => k.DeclarationNo).ToDictionary(g => g.Key, g => g.First());
    var lcs = (await db.LettersOfCredit.Where(l => l.OrgId == t.OrgId).ToListAsync())
        .GroupBy(l => l.LCNo).ToDictionary(g => g.Key, g => g.First());

    // 🔴 CHIA LÔ đúng như nguồn, rồi UnionAll (KHÔNG khử trùng).
    var result = new List<object>();
    var batches = 0;
    for (var i = 0; i < list.Count; i += step)
    {
        var chunk = list.Skip(i).Take(step).ToList();
        batches++;
        var cars = await db.CarVinMasters
            .Where(c => c.OrgId == t.OrgId && chunk.Contains(c.VIN)).ToListAsync();
        foreach (var cv in cars)
        {
            pls.TryGetValue(cv.PackingListNo ?? "", out var ctpl);
            tkhqs.TryGetValue(cv.DeclarationNo ?? "", out var ctt);
            lcs.TryGetValue(ctpl?.LcNo ?? "", out var ctlc);
            result.Add(new
            {
                cv.VIN, cv.ModelCode, cv.SpecCode, cv.ColorCode, cv.ActualSpec, cv.EngineNo,
                cv.DeclarationNo, cv.PackingListNo, cv.WorkOrderNo, cv.FlagActive,
                cv.CQStartDate, cv.CQExpectedDate, cv.TypeCB, cv.LoaiThung,
                // Tiền tố CTPL… (từ CT_PackingList)
                CTPLPackingListNo = ctpl?.PLNo,
                CTPLLCNo = ctpl?.LcNo,
                // ⚠️ Lệch khuôn: tiền tố CTPL nhưng LẤY TỪ CT_TKHQ.
                CTPLDeclarationNo = ctt?.DeclarationNo,
                CTPLPortCode = ctpl?.PortCode,
                CTPLShippingDateStart = ctpl?.ShippingDateStart,
                CTPLShippingDateEnd = ctpl?.ShippingDateEnd,
                CTPLShippingDateEndExpected = ctpl?.ShippingDateEndExpected,
                CTPLCreatedDate = ctpl?.CreatedAt,
                // ⚠️ Lệch khuôn: KHÔNG có tiền tố.
                BankName = ctlc?.BankName,
                ContractNo = ctlc?.ContractNo,
                // Tiền tố CC… (từ Car_Car) — MiniHTC gộp vào CarVinMaster.
                CCCarId = cv.VIN, CCSpecCode = cv.SpecCode, CCModelCode = cv.ModelCode,
                CCColorCode = cv.ColorCode, CCDealerCode = cv.DealerCode,
                CCFlagActive = cv.FlagActive, CCVIN = cv.VIN,
                CCCarCancelRemark = cv.CarCancelRemark,
                CTDOpenDate = ctt?.OpenDate
            });
        }
    }

    return Results.Ok(new
    {
        inputVins = list.Count, batches, batchSize = step, count = result.Count, items = result,
        hugeListNote = "CHIA LO VI GIOI HAN THAM SO CUA SQL SERVER - myUtil_GetDataForHugeList (BizHTC.Common.cs:614): danh sach VIN bi cat thanh tung lo TConst.HTCConst.MaxParamsSqlSv = 2000 phan tu (Const.Main.cs:325, chu thich nguon: 'Must be less than 2100 - limited by SqlServer'), chay CUNG CAU SQL NHIEU LAN roi UnionAll ket qua. Day la ly do ham ten 'HugeList'. Port dung IN (...) mot phat voi > 2000 VIN se VO o SQL Server that.",
        unionAllNote = "UnionAll(ref dtResult, ref dtGetData, FALSE) - tham so cuoi 'false' = KHONG KHU TRUNG. Port phai giu nguyen ngu nghia gop de so dong khop nguon.",
        rbacHole = "RBAC bien the 2 (khai ma khong dung), CA THU 20: myUtil_GetDataForHugeList bind '@strBUPatternOfUser' = drAbilityOfUser['BUPattern'] - QUYEN THAT (hiem!) - nhung BUOC 3 cho thay SQL cua CarVINGetList KHONG dung tham so nay (grep -c trong vung ham = 0). Ham dung chung co san quyen that NHUNG CAU SQL BO QUA => van KHONG loc pham vi. Doi chieu: CarCarGetList_New20181115 cung file CO 1 lan dung.",
        aliasPrefixNote = "Bi danh CO TIEN TO de tranh de cot (khuon #B93/#B97/#B102): cv.* giu nguyen ten; CT_PackingList -> CTPL...; Car_Car -> CC...; CT_Declaration -> CTD... HAI CHO LECH KHUON: ctt.DeclarationNo mang bi danh CTPLDeclarationNo (tien to CTPL nhung lay tu bang CT_TKHQ); va ctlc.BankName / ctlc.ContractNo KHONG CO tien to nao. Giu nguyen de doi chieu.",
