// ===== Hạn mức & thanh toán marketing theo năm/đại lý (Rpt_Marketing — port 1:1 cụm 5 hàm
// Rpt_MarketingGet/Create/UpdateMulti/Update/Approve_New20181115, 2010.HTC BizHTC.Marketing.cs
// 1617 / 1811 / 2182 / 2567 / 2822). TWIN: cả WS 32-bit lẫn 64-bit gọi cùng bản _New20181115. =====
// 🔴 RptStatus theo TConst.Stage: tạo = "P", duyệt = "A".
// 🔴 DUYỆT THEO NĂM, không theo đại lý: nguồn chạy `where MKTYear = @strMKTYear` — một phát cả năm.
// 🔴 UpdateMulti = XOÁ TRẮNG cả năm rồi INSERT lại (không sửa từng dòng); dòng mới về "P".
// ⚠️ RBAC nguồn (CheckHTCDirect + CheckAccessDealerData theo BUPattern) chưa port — nợ chung toàn fleet.
static bool MktYearValid(string y) =>
    y.Length == 4 && int.TryParse(y, out var n) && n >= 1900 && n <= 2100;

app.MapGet("/api/rptmarketing", async (AppDbContext db, ITenantContext t, string? mktYear, string? dealerCode, string? rptStatus) =>
{
    var qy = db.RptMarketings.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(mktYear)) qy = qy.Where(x => x.MKTYear == mktYear);
    if (!string.IsNullOrWhiteSpace(dealerCode)) qy = qy.Where(x => x.DealerCode == dealerCode);
    if (!string.IsNullOrWhiteSpace(rptStatus)) qy = qy.Where(x => x.RptStatus == rptStatus);
    var items = await qy.OrderBy(x => x.MKTYear).ThenBy(x => x.DealerCode).Select(x => new
    {
        x.Id, x.MKTYear, x.DealerCode,
        x.Limit1, x.Limit2, x.Limit3, x.Limit4,
        x.Payment1, x.Payment2, x.Payment3, x.Payment4,
        x.Remark, x.RptStatus, x.CreatedDate, x.CreatedBy, x.LogLUDateTime, x.LogLUBy,
        LimitTotal = (x.Limit1 ?? 0) + (x.Limit2 ?? 0) + (x.Limit3 ?? 0) + (x.Limit4 ?? 0),
        PaymentTotal = (x.Payment1 ?? 0) + (x.Payment2 ?? 0) + (x.Payment3 ?? 0) + (x.Payment4 ?? 0),
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Kiểm tra Limit/Payment âm — nguồn ném 8 mã lỗi riêng InvalidLimit1..4 / InvalidPayment1..4.
static string? MktNegative(RptMarketingRowDto r)
{
    if (r.Limit1 < 0) return "Limit1 âm."; if (r.Limit2 < 0) return "Limit2 âm.";
    if (r.Limit3 < 0) return "Limit3 âm."; if (r.Limit4 < 0) return "Limit4 âm.";
    if (r.Payment1 < 0) return "Payment1 âm."; if (r.Payment2 < 0) return "Payment2 âm.";
    if (r.Payment3 < 0) return "Payment3 âm."; if (r.Payment4 < 0) return "Payment4 âm.";
    return null;
}

app.MapPost("/api/rptmarketing/create", async (RptMarketingCreateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var year = (dto.MKTYear ?? "").Trim();
    if (!MktYearValid(year)) return Results.BadRequest(new { error = "Năm không hợp lệ (4 chữ số, 1900..2100)." });
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.DealerCode)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Bảng Rpt_Marketing đầu vào rỗng." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    foreach (var r in rows)
    {
        var neg = MktNegative(r);
        if (neg is not null) return Results.BadRequest(new { error = $"Đại lý {r.DealerCode}: {neg}" });
        // 🔴 Guard nguồn Rpt_MarketingActive_CheckDB với FlagExistToCheck = "N": cặp (năm, đại lý) PHẢI CHƯA có.
        var dup = await db.RptMarketings.AnyAsync(x => x.OrgId == t.OrgId && x.MKTYear == year && x.DealerCode == r.DealerCode);
        if (dup) return Results.BadRequest(new { error = $"Năm {year} đã có dòng cho đại lý {r.DealerCode}." });
    }
    foreach (var r in rows)
        db.RptMarketings.Add(new RptMarketing
        {
            OrgId = t.OrgId, MKTYear = year, DealerCode = r.DealerCode!.Trim(),
            Limit1 = r.Limit1, Limit2 = r.Limit2, Limit3 = r.Limit3, Limit4 = r.Limit4,
            Payment1 = r.Payment1, Payment2 = r.Payment2, Payment3 = r.Payment3, Payment4 = r.Payment4,
            Remark = r.Remark, RptStatus = "P",
            CreatedDate = now, CreatedBy = who, LogLUDateTime = now, LogLUBy = who,
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { created = rows.Count, mktYear = year, rptStatus = "P" });
}).RequireAuthorization();

// 🔴 Nguồn XOÁ TRẮNG cả năm rồi insert lại — thay thế toàn bộ, không merge theo đại lý.
app.MapPost("/api/rptmarketing/updatemulti", async (RptMarketingCreateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var year = (dto.MKTYear ?? "").Trim();
    if (!MktYearValid(year)) return Results.BadRequest(new { error = "Năm không hợp lệ (4 chữ số, 1900..2100)." });
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.DealerCode)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Bảng Rpt_Marketing đầu vào rỗng." });
    foreach (var r in rows)
    {
        var neg = MktNegative(r);
        if (neg is not null) return Results.BadRequest(new { error = $"Đại lý {r.DealerCode}: {neg}" });
    }
    var old = await db.RptMarketings.Where(x => x.OrgId == t.OrgId && x.MKTYear == year).ToListAsync();
    // Guard nguồn Rpt_MarketingActive_CheckDB_Year: cả năm phải đang chờ duyệt.
    var notPending = old.Where(x => x.RptStatus != "P").Select(x => x.DealerCode).Distinct().ToList();
    if (notPending.Count > 0)
        return Results.BadRequest(new { error = $"Năm {year} đã duyệt/khoá ở các đại lý: {string.Join(", ", notPending.Take(10))}." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    db.RptMarketings.RemoveRange(old);
    foreach (var r in rows)
        db.RptMarketings.Add(new RptMarketing
        {
            OrgId = t.OrgId, MKTYear = year, DealerCode = r.DealerCode!.Trim(),
            Limit1 = r.Limit1, Limit2 = r.Limit2, Limit3 = r.Limit3, Limit4 = r.Limit4,
            Payment1 = r.Payment1, Payment2 = r.Payment2, Payment3 = r.Payment3, Payment4 = r.Payment4,
            Remark = r.Remark, RptStatus = "P",
            CreatedDate = now, CreatedBy = who, LogLUDateTime = now, LogLUBy = who,
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = old.Count, created = rows.Count, mktYear = year });
}).RequireAuthorization();

// Sửa MỘT dòng: nguồn chỉ ghi cột có giá trị parse được (alColumnEffective); Remark luôn ghi đè.
app.MapPost("/api/rptmarketing/update", async (RptMarketingUpdateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var year = (dto.MKTYear ?? "").Trim();
    var dealer = (dto.DealerCode ?? "").Trim();
    var row = await db.RptMarketings.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MKTYear == year && x.DealerCode == dealer);
    if (row is null) return Results.NotFound(new { error = $"Không có dòng marketing năm {year} cho đại lý {dealer}." });
    // Guard nguồn: chỉ sửa được khi còn chờ duyệt.
    if (row.RptStatus != "P") return Results.BadRequest(new { error = $"Dòng đang ở trạng thái {row.RptStatus}, chỉ sửa được khi 'P'." });
    var neg = MktNegative(new RptMarketingRowDto(dealer, dto.Limit1, dto.Limit2, dto.Limit3, dto.Limit4, dto.Payment1, dto.Payment2, dto.Payment3, dto.Payment4, dto.Remark));
    if (neg is not null) return Results.BadRequest(new { error = neg });

    if (dto.Limit1 is not null) row.Limit1 = dto.Limit1;
    if (dto.Limit2 is not null) row.Limit2 = dto.Limit2;
    if (dto.Limit3 is not null) row.Limit3 = dto.Limit3;
    if (dto.Limit4 is not null) row.Limit4 = dto.Limit4;
    if (dto.Payment1 is not null) row.Payment1 = dto.Payment1;
    if (dto.Payment2 is not null) row.Payment2 = dto.Payment2;
    if (dto.Payment3 is not null) row.Payment3 = dto.Payment3;
    if (dto.Payment4 is not null) row.Payment4 = dto.Payment4;
    row.Remark = dto.Remark; // nguồn luôn ghi Remark, kể cả rỗng
    row.LogLUDateTime = DateTime.Now;
    row.LogLUBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    await db.SaveChangesAsync();
    return Results.Ok(new { row.MKTYear, row.DealerCode, row.RptStatus });
}).RequireAuthorization();

// 🔴 Duyệt CẢ NĂM một phát (nguồn: update … where MKTYear = @strMKTYear), không nhận DealerCode.
app.MapPost("/api/rptmarketing/approve", async (RptMarketingApproveDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var year = (dto.MKTYear ?? "").Trim();
    if (!MktYearValid(year)) return Results.BadRequest(new { error = "Năm không hợp lệ (4 chữ số, 1900..2100)." });
    var rows = await db.RptMarketings.Where(x => x.OrgId == t.OrgId && x.MKTYear == year).ToListAsync();
    if (rows.Count == 0) return Results.BadRequest(new { error = $"Năm {year} chưa có dòng marketing nào." });
    var notPending = rows.Where(x => x.RptStatus != "P").Select(x => x.DealerCode).Distinct().ToList();
    if (notPending.Count > 0)
        return Results.BadRequest(new { error = $"Năm {year} có dòng không ở trạng thái 'P': {string.Join(", ", notPending.Take(10))}." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    foreach (var r in rows) { r.RptStatus = "A"; r.LogLUDateTime = now; r.LogLUBy = who; }
    await db.SaveChangesAsync();
    return Results.Ok(new { approved = rows.Count, mktYear = year, rptStatus = "A" });
}).RequireAuthorization();

// ===== Nhật ký gọi API SBHOnline (OS_SBHOnline_Log — port 1:1 OS_SBHOnline_Log_Create,
// 2010.HTC BizHTC.DealerSales.cs:4433; 17 điểm gọi ở Biz.HTC.WH.cs + Biz.HTC.WH.hkt.cs) =====
// 🔴 HAI trục tên khác nhau: `FuncCall` = hàm nghiệp vụ ERP kích hoạt (DealerSalesDealCreate /
//    DealerSalesDealUpdateMulti / DealerSalesDealDelete); `FuncCode` = lệnh API SBHOnline
//    (fleet_owner_create / fleet_owner_update / fleet_create / fleet_update / fleet_car_id).
// 🔴 `ErrCode` KHÔNG phải mã số: "0" = thành công, ngược lại là THÔNG ĐIỆP lỗi nguyên văn
//    (`response.errorMessage`, hoặc `ex.Message + "/" + response.errorMessage`).
// 🔴 Nguồn KHÔNG có guard nào và catch nuốt trọn ⇒ POST không bao giờ trả 4xx vì lý do nghiệp vụ.
app.MapGet("/api/sbhonlineapilogs", async (AppDbContext db, ITenantContext t, string? dealNo, string? carId, string? funcCall, string? funcCode, string? createdBy, bool? onlyError) =>
{
    var qy = db.SbhOnlineApiLogs.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealNo)) qy = qy.Where(x => x.DealNo == dealNo);
    if (!string.IsNullOrWhiteSpace(carId)) qy = qy.Where(x => x.CarId == carId);
    if (!string.IsNullOrWhiteSpace(funcCall)) qy = qy.Where(x => x.FuncCall == funcCall);
    if (!string.IsNullOrWhiteSpace(funcCode)) qy = qy.Where(x => x.FuncCode == funcCode);
    if (!string.IsNullOrWhiteSpace(createdBy)) qy = qy.Where(x => x.CreatedBy == createdBy);
    // `ErrCode` khác "0" nghĩa là lỗi — bản thân nó CHÍNH LÀ thông điệp lỗi.
    if (onlyError == true) qy = qy.Where(x => x.ErrCode != "0");
    var items = await qy.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.FuncCall, x.FuncCode, x.RQ, x.RT, x.DealNo, x.CarId, x.ErrCode, x.CreatedDateTime, x.CreatedBy,
        Success = x.ErrCode == "0",
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/sbhonlineapilogs", async (SbhOnlineApiLogDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    // Nguồn không kiểm tra gì cả (region Check rỗng) — giữ nguyên, chỉ chuẩn hoá khoảng trắng.
    db.SbhOnlineApiLogs.Add(new SbhOnlineApiLog
    {
        OrgId = t.OrgId,
        FuncCall = dto.FuncCall, FuncCode = dto.FuncCode,
        RQ = dto.RQ, RT = dto.RT,
        DealNo = (dto.DealNo ?? "").Trim(), CarId = (dto.CarId ?? "").Trim(),
        ErrCode = string.IsNullOrWhiteSpace(dto.ErrCode) ? "0" : dto.ErrCode,
        CreatedDateTime = DateTime.Now,
        CreatedBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system",
    });
    await db.SaveChangesAsync();
    return Results.Ok(new { logged = true, success = string.IsNullOrWhiteSpace(dto.ErrCode) || dto.ErrCode == "0" });
}).RequireAuthorization();

// ===== Nhật ký đẩy xe đã bán sang CarService (DLS_LogCarSv — port 1:1 DSL_LogCarSvCreate,
// 2010.HTC BizHTC.DealerSales.cs:3974 / DSL_LogCarSvGet_New20181115:4104).
// TWIN: cả WSHTC 32-bit (WSHTC.cs:26209) lẫn 64-bit đều gọi cùng bản `_New20181115`. =====
// 🔴 `ErrCode = "0"` là THÀNH CÔNG; khác "0" là mã lỗi CarService trả về.
// 🔴 `FuncCode`: nhánh thành công ghi tên lệnh (`SerCustomerCarSalesCreate`, `OS_Ser_CarSalesUpd`,
//    `OS_Ser_CarSalesDelX`); nhánh lỗi ghi `PVal` — function code nơi phát sinh lỗi.
// 🔴 Nguồn NUỐT lỗi (catch chỉ rollback, không ném): ghi log hỏng KHÔNG được làm hỏng luồng bán xe.
//    Vì vậy POST dưới đây trả 200 kèm `logged=false` + `reason` thay vì 400.
// ⚠️ Nguồn lọc thêm theo `Mst_Dealer.BUCode like @strBUPatternOfUser` (RBAC) — nợ chung toàn fleet.
app.MapGet("/api/carsvlogs", async (AppDbContext db, ITenantContext t, string? dealNo, string? dealerCode, string? carId, string? vin, string? funcCode, string? errCode, string? createdBy, bool? onlyError) =>
{
    var qy = db.CarSvLogs.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealNo)) qy = qy.Where(x => x.DealNo == dealNo);
    if (!string.IsNullOrWhiteSpace(dealerCode)) qy = qy.Where(x => x.DealerCode == dealerCode);
    if (!string.IsNullOrWhiteSpace(carId)) qy = qy.Where(x => x.CarId == carId);
    if (!string.IsNullOrWhiteSpace(vin)) qy = qy.Where(x => x.VIN == vin);
    if (!string.IsNullOrWhiteSpace(funcCode)) qy = qy.Where(x => x.FuncCode == funcCode);
    if (!string.IsNullOrWhiteSpace(errCode)) qy = qy.Where(x => x.ErrCode == errCode);
    if (!string.IsNullOrWhiteSpace(createdBy)) qy = qy.Where(x => x.CreatedBy == createdBy);
    // Tiện dụng: chỉ lấy các lần đẩy LỖI (ErrCode khác "0").
    if (onlyError == true) qy = qy.Where(x => x.ErrCode != "0");
    var items = await qy.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.DealNo, x.DealerCode, x.CarId, x.VIN, x.FuncCode, x.ErrCode, x.CreatedDateTime, x.CreatedBy,
        Success = x.ErrCode == "0",
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/carsvlogs", async (CarSvLogDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var dealNo = (dto.DealNo ?? "").Trim();
    var carId = (dto.CarId ?? "").Trim();
    var vin = (dto.VIN ?? "").Trim();
    // 🔴 Guard nguồn, nhưng thất bại thì NUỐT (không ném) — đúng như `catch` của `DSL_LogCarSvCreate`.
    // MinLengthCode = 5 (TConst.HTCConst, Const.Main.cs:322).
    string? reason = null;
    if (dealNo.Length < 5) reason = "DealNo ngắn hơn MinLengthCode (5).";
    else if (vin.Length < 1) reason = "VIN rỗng.";
    else if (carId.Length < 1) reason = "CarId rỗng.";
    if (reason is not null) return Results.Ok(new { logged = false, reason });

    db.CarSvLogs.Add(new CarSvLog
    {
        OrgId = t.OrgId, DealNo = dealNo, DealerCode = (dto.DealerCode ?? "").Trim(),
        CarId = carId, VIN = vin, FuncCode = dto.FuncCode, ErrCode = dto.ErrCode ?? "0",
        CreatedDateTime = DateTime.Now,
        CreatedBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system",
    });
    await db.SaveChangesAsync();
    return Results.Ok(new { logged = true, success = (dto.ErrCode ?? "0") == "0" });
}).RequireAuthorization();

// ===== Nhật ký gọi API GPS (GPS_LogGPS — port 1:1 GPS_LogGPS_Add,
// 2010.HTC StorageFG/BizHTC.ConnGPSVelocaDMS.cs:1476) =====
// 🔴 Mỗi lần gọi API ghi HAI dòng chung một `LogId`: "RQ" trước khi gửi (Status rỗng) và
//    "RS" sau khi nhận (Status = kết quả, hoặc "FALSE" khi lỗi). Endpoint dưới đây phơi đúng mô hình đó.
// 🔴 `FunctionType` theo `TConst.TypeCallGPS`: MAPVIN · OUTSTO · GETADDRESSONLINE · SEARCHADDRESSS ·
//    DMSUNMAPVIN (giữ nguyên "SEARCHADDRESSS" thừa một chữ S của nguồn).
app.MapGet("/api/gpscalllogs", async (AppDbContext db, ITenantContext t, string? logId, string? logType, string? functionType, string? status) =>
{
    var qy = db.GpsCallLogs.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(logId)) qy = qy.Where(x => x.LogId == logId);
    if (!string.IsNullOrWhiteSpace(logType)) qy = qy.Where(x => x.LogType == logType.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(functionType)) qy = qy.Where(x => x.FunctionType == functionType.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(status)) qy = qy.Where(x => x.Status == status);
    var items = await qy.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.LogId, x.LogType, x.Status, x.Exception, x.DataSend, x.DataResponse,
        x.IDMSKey, x.FunctionName, x.FunctionType, x.Trycount, x.Url, x.Remark, x.CreatedAt
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Ghi một dòng nhật ký (dùng cho cả RQ lẫn RS — đúng như nguồn gọi cùng một hàm `GPS_LogGPS_Add`).
app.MapPost("/api/gpscalllogs", async (GpsCallLogDto dto, AppDbContext db, ITenantContext t) =>
{
    var logType = (dto.LogType ?? "RQ").Trim().ToUpperInvariant();
    if (logType is not ("RQ" or "RS")) return Results.BadRequest(new { error = "LogType = RQ | RS (TConst.LogTypeGPS)." });
    var fnType = string.IsNullOrWhiteSpace(dto.FunctionType) ? null : dto.FunctionType!.Trim().ToUpperInvariant();
    string[] okTypes = { "MAPVIN", "OUTSTO", "GETADDRESSONLINE", "SEARCHADDRESSS", "DMSUNMAPVIN" };
    if (fnType is not null && !okTypes.Contains(fnType))
        return Results.BadRequest(new { error = $"FunctionType không hợp lệ. Cho phép: {string.Join(", ", okTypes)}." });
    var logId = string.IsNullOrWhiteSpace(dto.LogId) ? Guid.NewGuid().ToString("N") : dto.LogId!.Trim();
    var row = new GpsCallLog
    {
        OrgId = t.OrgId, LogId = logId, LogType = logType,
        // Nguồn để Status RỖNG ở dòng RQ; "FALSE" khi lỗi phía RS.
        Status = logType == "RQ" ? "" : dto.Status,
        Exception = dto.Exception, DataSend = dto.DataSend, DataResponse = dto.DataResponse,
        IDMSKey = dto.IDMSKey, FunctionName = dto.FunctionName, FunctionType = fnType,
        Trycount = string.IsNullOrWhiteSpace(dto.Trycount) ? "1" : dto.Trycount, // nguồn luôn truyền "1"
        Url = dto.Url, Remark = dto.Remark,
    };
    db.GpsCallLogs.Add(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { row.LogId, row.LogType, row.FunctionType, row.Status });
}).RequireAuthorization();

// Tra một lần gọi trọn vẹn: ghép cặp RQ + RS theo LogId.
app.MapGet("/api/gpscalllogs/{logId}/pair", async (string logId, AppDbContext db, ITenantContext t) =>
{
    var rows = await db.GpsCallLogs.Where(x => x.OrgId == t.OrgId && x.LogId == logId)
        .OrderBy(x => x.Id).ToListAsync();
    if (rows.Count == 0) return Results.NotFound(new { logId });
    var rq = rows.FirstOrDefault(x => x.LogType == "RQ");
    var rs = rows.FirstOrDefault(x => x.LogType == "RS");
    return Results.Ok(new
    {
        logId,
        request = rq is null ? null : new { rq.FunctionType, rq.FunctionName, rq.Url, rq.DataSend, rq.CreatedAt },
        response = rs is null ? null : new { rs.Status, rs.DataResponse, rs.Exception, rs.CreatedAt },
        completed = rq is not null && rs is not null,
    });
}).RequireAuthorization();

// ===== Kế hoạch bán lẻ theo tháng (Rpt_PlanRetail — port 1:1 Rpt_PlanRetail_Create/Approve/Cancel,
// 2010.HTC BizHTC.Report.cs:33001/33644/33900). TWIN: chỉ `TERP.WSHTC.64` (95765/95832/95901). =====
// 🔴 Trạng thái `TConst.PRStatus`: "P" mới tạo · "A" duyệt · "C" từ chối.
// ⚠️ Guard phản trực giác: **duyệt vào từ "P" HOẶC "C"** (bản đã từ chối duyệt lại được);
//    **từ chối chỉ vào từ "P"**.
// ⚠️ Phần sinh dữ liệu tổng hợp (`mySql_Rpt_PlanRetail_Create`) CHƯA port — endpoint nhận dòng từ client.
app.MapGet("/api/planretails", async (AppDbContext db, ITenantContext t, string? month, string? dealer, string? status) =>
{
    var qy = db.PlanRetails.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(month)) qy = qy.Where(x => x.PlanMonth == month);
    if (!string.IsNullOrWhiteSpace(dealer)) qy = qy.Where(x => x.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(status)) qy = qy.Where(x => x.PRStatus == status);
    var items = await qy.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.Id, x.PlanMonth, x.PlanTimes, x.PlanTimesPrev, x.DealerCode, x.PRStatus,
        x.ApprovedBy, x.ApprovedDate, x.CancelBy, x.CancelDate, x.CreatedBy, x.CreatedAt,
        lines = db.PlanRetailDtls.Count(l => l.OrgId == t.OrgId && l.PlanRetailId == x.Id),
        totalQty = db.PlanRetailDtls.Where(l => l.OrgId == t.OrgId && l.PlanRetailId == x.Id).Sum(l => (int?)l.Quantity) ?? 0
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/planretails", async (PlanRetailDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (string.IsNullOrWhiteSpace(dto.PlanMonth)) return Results.BadRequest(new { error = "Cần PlanMonth (YYYY-MM)." });
    if (string.IsNullOrWhiteSpace(dto.PlanTimes)) return Results.BadRequest(new { error = "Cần PlanTimes (lần lập trong tháng)." });
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Cần DealerCode." });
    var month = dto.PlanMonth.Trim(); var times = dto.PlanTimes.Trim(); var dealer = dto.DealerCode.Trim().ToUpperInvariant();
    // Khoá nghiệp vụ của nguồn: PlanMonth + PlanTimes + DealerCode.
    if (await db.PlanRetails.AnyAsync(x => x.OrgId == t.OrgId && x.PlanMonth == month && x.PlanTimes == times && x.DealerCode == dealer))
        return Results.BadRequest(new { error = $"Kế hoạch {month} lần {times} của đại lý {dealer} đã tồn tại!" });

    var h = new PlanRetail
    {
        OrgId = t.OrgId, PlanMonth = month, PlanTimes = times, PlanTimesPrev = dto.PlanTimesPrev,
        DealerCode = dealer, PRStatus = "P",
        CreatedBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system",
    };
    db.PlanRetails.Add(h); await db.SaveChangesAsync();
    var lines = (dto.Lines ?? new()).Where(l => l.Quantity > 0).ToList();
    foreach (var l in lines)
        db.PlanRetailDtls.Add(new PlanRetailDtl { OrgId = t.OrgId, PlanRetailId = h.Id, ModelCode = l.ModelCode, SpecCode = l.SpecCode, ColorCode = l.ColorCode, Quantity = l.Quantity });
    // Nguồn ghi CÙNG LÚC bảng gộp theo model (Rpt_PlanRetailModel) — gộp từ chi tiết.
    foreach (var g in lines.Where(l => !string.IsNullOrWhiteSpace(l.ModelCode)).GroupBy(l => l.ModelCode!.Trim().ToUpperInvariant()))
        db.PlanRetailModels.Add(new PlanRetailModel { OrgId = t.OrgId, PlanRetailId = h.Id, ModelCode = g.Key, Quantity = g.Sum(x => x.Quantity) });
    await db.SaveChangesAsync();
    return Results.Ok(new { h.Id, h.PlanMonth, h.PlanTimes, h.DealerCode, status = h.PRStatus, lines = lines.Count });
}).RequireAuthorization();

app.MapGet("/api/planretails/{id}/lines", async (long id, AppDbContext db, ITenantContext t) =>
{
    var h = await db.PlanRetails.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { id });
    var lines = await db.PlanRetailDtls.Where(l => l.OrgId == t.OrgId && l.PlanRetailId == id)
        .Select(l => new { l.ModelCode, l.SpecCode, l.ColorCode, l.Quantity }).ToListAsync();
    var byModel = await db.PlanRetailModels.Where(m => m.OrgId == t.OrgId && m.PlanRetailId == id)
        .Select(m => new { m.ModelCode, m.Quantity }).ToListAsync();
    return Results.Ok(new { h.Id, h.PlanMonth, h.PlanTimes, h.DealerCode, h.PRStatus, count = lines.Count, lines, byModel });
}).RequireAuthorization();

app.MapPost("/api/planretails/{id}/{action}", async (long id, string action, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (action is not ("approve" or "cancel")) return Results.BadRequest(new { error = "action = approve|cancel" });
    var h = await db.PlanRetails.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { id });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    if (action == "approve")
    {
        // Guard nguồn `Rpt_PlanRetail_Approve`: strPRStatusListToCheck = "P, C".
        if (h.PRStatus is not ("P" or "C"))
            return Results.BadRequest(new { error = $"Kế hoạch đang ở '{h.PRStatus}' — chỉ duyệt khi mới tạo (P) hoặc đã từ chối (C)." });
        h.PRStatus = "A"; h.ApprovedDate = DateTime.Now; h.ApprovedBy = who;
    }
    else
    {
        // Guard nguồn `Rpt_PlanRetail_Cancel`: PRStatus.Pending ⇒ CHỈ từ "P".
        if (h.PRStatus != "P")
            return Results.BadRequest(new { error = $"Kế hoạch đang ở '{h.PRStatus}' — chỉ từ chối khi còn mới tạo (P)." });
        h.PRStatus = "C"; h.CancelDate = DateTime.Now; h.CancelBy = who;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { h.Id, status = h.PRStatus });
}).RequireAuthorization();

