}).RequireAuthorization();

// ⚠️ #199 ĐÃ BỎ `POST /api/transpdlv/{no}/confirm` — **nguồn KHÔNG có lệnh này**. Ba bằng chứng độc lập:
//   1. Hệ nhà vận chuyển `TERP.WSTransp/App_Code/WSTransp.cs` chỉ có **MỘT** lệnh ghi:
//      `Sto_TranspPlanApprovedByTransporter` — duyệt **KẾ HOẠCH VẬN CHUYỂN**, không phải biên bản giao nhận.
//      (Lệnh đó ĐÃ port: `POST /api/transplans/{vinPlan}/transporter-approve`.)
//   2. Màn gốc `TERP.TranspClient/Views/Transp/FrmMngDlvMinutes.cs` (717 dòng) có đúng **ba** nút:
//      `btnExport` · `btnSearch` · `btnClose` ⇒ **màn CHỈ ĐỌC**, không có nút xác nhận nào.
//   3. Grep toàn `TERP.BizHTC`: bảng `Sto_DlvMinutes` **không có cột `ConfirmStatus`**; trục trạng thái
//      thật là `FDlvMnStatus`/`TDlvMnStatus` (P/A/R) — đã port ở `/api/dlvminutes/{no}/approve` (#159).
//   ⇒ Cùng cách xử lý với `/dlrcontracts/{no}/finish` (#198) và `/deliver`+`/reject` (#175).

// ===== Biên bản giao nhận xe: duyệt HAI PHÍA + bảng kiểm tra tình trạng xe =====
// Port 1:1 FrmHTCMngDlvMinutes + FrmHTCNewDlvMinutes (2010.HTC TERP.HTCClient/Views/Sales/DlvMinutes).
// TWIN đã trace: WSHTC.Sto_DlvMinutes_Approved → biz Sto_DlvMinutes_Approve_New20190416 (KHÔNG phải hàm trùng tên).

// Danh mục mục kiểm tra — đúng phần đuôi các cột FSTATUS_*/TSTATUS_* của bảng Sto_DlvMinutes.
// Nguồn trải thành 68 cột phẳng (34 mục × 2 phía); ở đây giữ nguyên danh mục nhưng lưu theo dòng.
var dlvCheckItemCatalog = new (string Group, string Code)[]
{
    // OS — ngoại thất
    ("OS", "Chassis"), ("OS", "Paint"), ("OS", "Glass"), ("OS", "Wipers"), ("OS", "Mirrors"),
    ("OS", "LightSystem"), ("OS", "Antenna"), ("OS", "Logo"), ("OS", "Moulding"), ("OS", "CementDust"),
    // IS — nội thất
    ("IS", "InstrumentPanel"), ("IS", "Switchs"), ("IS", "Sunvisor"), ("IS", "CigarLighter"), ("IS", "Mirror"),
    ("IS", "RadioCD"), ("IS", "AirCondition"), ("IS", "Seats"), ("IS", "RoofLamps"), ("IS", "RoofMat"),
    ("IS", "FloorPanel"), ("IS", "TrimPanel"), ("IS", "KeyAndRemote"), ("IS", "Filter"),
    // SP — phụ tùng kèm xe
    ("SP", "SpareWheel"), ("SP", "WheelCover"), ("SP", "ToolBag"), ("SP", "KeyEnvelope"),
    // DA — giấy tờ kèm xe
    ("DA", "OriginalCertificate"), ("DA", "UserManual"), ("DA", "CDGuaranty"),
    ("DA", "GuarantyBooklet"), ("DA", "OriginalInvoice"), ("DA", "StampedInvoice"),
};
var dlvCheckItemCodes = dlvCheckItemCatalog.Select(i => i.Code).ToHashSet(StringComparer.OrdinalIgnoreCase);

// Danh mục mục kiểm tra để client dựng form (nguồn là các nhãn cố định trên FrmHTCNewDlvMinutes).
app.MapGet("/api/transpdlv/checkitems", () => Results.Ok(new
{
    count = dlvCheckItemCatalog.Length,
    groups = dlvCheckItemCatalog.GroupBy(i => i.Group)
        .Select(g => new { group = g.Key, items = g.Select(i => i.Code).ToArray() })
})).RequireAuthorization();

// Bảng kiểm tra tình trạng xe của một biên bản, kèm trạng thái duyệt hai phía.
app.MapGet("/api/transpdlv/{no}/checkitems", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.TranspDlvConfirms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlvMinutesNo == no);
    if (m is null) return Results.NotFound(new { no });
    var items = await db.DlvMinutesCheckItems
        .Where(i => i.OrgId == t.OrgId && i.TranspDlvConfirmId == m.Id)
        .Select(i => new { i.ItemGroup, i.ItemCode, i.FStatus, i.TStatus }).ToListAsync();
    return Results.Ok(new
    {
        m.DlvMinutesNo, m.TranspReqNo, m.TranspReqType,
        m.FDlvMnStatus, m.TDlvMnStatus, m.FApprovedDate, m.FApprovedBy, m.TApprovedDate, m.TApprovedBy,
        m.FStorageCode, m.TStorageCode, m.FAddress, m.TAddress, m.DlvStartDate, m.DlvEndDate,
        m.PlateNo, m.DriverId, m.TPlateNo, m.TDriverId, m.FRemark, m.TRemark,
        m.FStatusIaKm, m.TStatusIaKm, m.FStatusIaRemark, m.TStatusIaRemark,
        count = items.Count, items
    });
}).RequireAuthorization();

// Ghi bảng kiểm tra + thông tin tuyến của MỘT phía (side = F bên giao, T bên nhận).
// Nguồn chỉ cho sửa khi biên bản CHƯA duyệt phía F (btnUpdate_Click).
app.MapPost("/api/transpdlv/{no}/checkitems", async (
    string no, DlvCheckSheetDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.TranspDlvConfirms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlvMinutesNo == no);
    if (m is null) return Results.NotFound(new { no });

    var side = (dto.Side ?? "").Trim().ToUpperInvariant();
    if (side is not ("F" or "T")) return Results.BadRequest(new { error = "Side = F (bên giao) | T (bên nhận)" });

    // Giữ nguyên câu thông báo của form gốc.
    if (m.FDlvMnStatus == "A")
        return Results.BadRequest(new { error = "Biên bản giao nhận đã được phê duyệt, không được phép sửa" });

    var lines = dto.Items ?? new();
    var unknown = lines.FirstOrDefault(l => !dlvCheckItemCodes.Contains((l.ItemCode ?? "").Trim()));
    if (unknown is not null)
        return Results.BadRequest(new { error = $"Mục kiểm tra không hợp lệ: {unknown.ItemCode}" });
    var duplicated = lines.GroupBy(l => l.ItemCode!.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (duplicated is not null)
        return Results.BadRequest(new { error = $"Mục kiểm tra {duplicated.Key} bị trùng!" });

    var existing = await db.DlvMinutesCheckItems
        .Where(i => i.OrgId == t.OrgId && i.TranspDlvConfirmId == m.Id).ToListAsync();
    foreach (var line in lines)
    {
        var code = line.ItemCode!.Trim();
        var row = existing.FirstOrDefault(i => string.Equals(i.ItemCode, code, StringComparison.OrdinalIgnoreCase));
        if (row is null)
        {
            row = new DlvMinutesCheckItem
            {
                OrgId = t.OrgId, TranspDlvConfirmId = m.Id, ItemCode = code,
                ItemGroup = dlvCheckItemCatalog.First(i => string.Equals(i.Code, code, StringComparison.OrdinalIgnoreCase)).Group
            };
            db.DlvMinutesCheckItems.Add(row);
            existing.Add(row);
        }
        // Chỉ ghi đè cột của đúng phía đang nhập — phía kia giữ nguyên kết quả đã chấm.
        if (side == "F") row.FStatus = line.Status; else row.TStatus = line.Status;
    }

    if (side == "F")
    {
        m.FStorageCode = dto.StorageCode ?? m.FStorageCode;
        m.FAddress = dto.Address ?? m.FAddress;
        m.PlateNo = dto.PlateNo ?? m.PlateNo;
        m.DriverId = dto.DriverId ?? m.DriverId;
        m.FRemark = dto.Remark ?? m.FRemark;
        m.FStatusIaKm = dto.StatusIaKm ?? m.FStatusIaKm;
        m.FStatusIaRemark = dto.StatusIaRemark ?? m.FStatusIaRemark;
        m.DlvStartDate = dto.DlvDate ?? m.DlvStartDate;
    }
    else
    {
        m.TStorageCode = dto.StorageCode ?? m.TStorageCode;
        m.TAddress = dto.Address ?? m.TAddress;
        m.TPlateNo = dto.PlateNo ?? m.TPlateNo;
        m.TDriverId = dto.DriverId ?? m.TDriverId;
        m.TRemark = dto.Remark ?? m.TRemark;
        m.TStatusIaKm = dto.StatusIaKm ?? m.TStatusIaKm;
        m.TStatusIaRemark = dto.StatusIaRemark ?? m.TStatusIaRemark;
        m.DlvEndDate = dto.DlvDate ?? m.DlvEndDate;
    }

    await db.SaveChangesAsync();
    return Results.Ok(new { m.DlvMinutesNo, side, saved = lines.Count });
}).RequireAuthorization();

// ⚠️ #200 HỢP NHẤT — ĐÃ BỎ `POST /api/transpdlv/{no}/approve`: **trùng lặp** với
//    `POST /api/dlvminutes/{no}/approve` (#159). Hai route cùng ghi MỘT bảng (`TranspDlvConfirms`) và cùng
//    port MỘT hàm nguồn `Sto_DlvMinutes_Approve_New20190416` — vi phạm §1, chỉ lộ ra khi audit nợ sweep #194.
//    · Bản #159 có **side-effect ghi ngược ngày xuất kho lên 4 chứng từ nguồn**; bản này KHÔNG có ⇒ gọi nhầm
//      route sẽ duyệt biên bản mà bỏ trắng toàn bộ side-effect.
//    · Đổi lại, bản này có guard `FDlvMnStatus == "P"` mà #159 thiếu ⇒ đã **mang guard sang bản #159**
//      trước khi gỡ (đúng luật `C0-ducentesimusnonagesimusprimus`: không được gỡ mất thứ chỉ bản kia có).
//    · `side=T` là **BỊA**: chữ ký nguồn chỉ có `strDlvMnNo` + `strFromFlagUnapprove`, không có tham số phía;
//      dòng ghi `TDlvMnStatus` trong nguồn bị comment cố ý (--20131126). Không lệnh nào của WS duyệt phía T.
//    🔴 TWIN FILE: `Sto_DlvMinutes_Approve_New20190416` có ở CẢ `DataWH/Biz.HTC.WH.cs:138340` LẪN
//      `DataWH/Biz.HTC.WH.Rel.20230823.cs:130768`; file `.Rel.20230823.cs` **không có trong csproj** ⇒ FILE CHẾT.
//      Bản LIVE là `Biz.HTC.WH.cs` (csproj dòng 272) — đúng bản #159 đã dùng.

// Sửa thông tin bàn giao cho đại lý — chỉ mở khi CẢ HAI phía đã duyệt (btnUpdateDealer_Click).
app.MapPost("/api/transpdlv/{no}/updatedealer", async (
    string no, DlvUpdateDealerDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.TranspDlvConfirms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlvMinutesNo == no);
    if (m is null) return Results.NotFound(new { no });

    if (m.FDlvMnStatus != "A" || m.TDlvMnStatus != "A")
        return Results.BadRequest(new { error = "Biên bản bàn gian chưa phê duyệt, không được phép sửa cho đại lý" });

    if (!string.IsNullOrWhiteSpace(dto.DealerCode)) m.DealerCode = dto.DealerCode.Trim().ToUpperInvariant();
    m.TAddress = dto.TAddress ?? m.TAddress;
    m.DlvEndDate = dto.DlvEndDate ?? m.DlvEndDate;
    m.TRemark = dto.TRemark ?? m.TRemark;

    await db.SaveChangesAsync();
    return Results.Ok(new { m.DlvMinutesNo, m.DealerCode, m.TAddress, m.DlvEndDate });
}).RequireAuthorization();

// ===== Báo cáo bán hàng HMC (HmcSalesRecord — port 1:1 FrmHMCReport, SalesDealer) =====
app.MapPost("/api/hmcsales", async (HmcSalesDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.VIN)) return Results.BadRequest(new { error = "Chưa nhập số khung (VIN)." });
    if (dto.TransactionDate is null) return Results.BadRequest(new { error = "Chưa nhập ngày giao dịch." });
    var r = new HmcSalesRecord { OrgId = t.OrgId, VIN = dto.VIN.Trim().ToUpperInvariant(), DealerCode = dto.DealerCode ?? "", ModelCode = dto.ModelCode ?? "", TransactionDate = dto.TransactionDate.Value, DeliveryType = dto.DeliveryType ?? "", SalesType = dto.SalesType ?? "" };
    db.HmcSalesRecords.Add(r); await db.SaveChangesAsync();
    return Results.Ok(new { r.VIN });
}).RequireAuthorization();

// Báo cáo HMC theo khoảng ngày: dòng theo VIN (ngày yyyyMMdd, loại giao, loại bán tách N/O) + tổng hợp.
app.MapGet("/api/hmcreport", async (AppDbContext db, ITenantContext t, DateTime? from, DateTime? to, string? dealer) =>
{
    var q = db.HmcSalesRecords.Where(r => r.OrgId == t.OrgId);
    if (from is not null) q = q.Where(r => r.TransactionDate >= from.Value.Date);
    if (to is not null) q = q.Where(r => r.TransactionDate < to.Value.Date.AddDays(1));
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(r => r.DealerCode == dealer);
    var recs = await q.OrderBy(r => r.TransactionDate).Take(2000).ToListAsync();
    var rows = recs.Select(r => new
    {
        transactionDate = r.TransactionDate.ToString("yyyyMMdd"),
        r.VIN, r.DealerCode, r.ModelCode, r.DeliveryType, r.SalesType,
        n = r.SalesType.Length >= 1 ? r.SalesType.Substring(0, 1) : "",   // ký tự 1 (field N)
        o = r.SalesType.Length >= 2 ? r.SalesType.Substring(1, 1) : ""    // ký tự 2 (field O)
    }).ToList();
    var byDelivery = recs.GroupBy(r => string.IsNullOrEmpty(r.DeliveryType) ? "(chưa rõ)" : r.DeliveryType)
        .Select(g => new { deliveryType = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var bySalesType = recs.GroupBy(r => string.IsNullOrEmpty(r.SalesType) ? "(chưa rõ)" : r.SalesType)
        .Select(g => new { salesType = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    return Results.Ok(new { total = rows.Count, byDelivery, bySalesType, rows });
}).RequireAuthorization();

// ===== Báo cáo back-order / đơn hàng chưa giao (BackOrder — port 1:1 FrmBackOrderByModel + FrmBackOrderByDealer) =====
app.MapPost("/api/backorder", async (BackOrderDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.ModelCode)) return Results.BadRequest(new { error = "Chưa nhập model." });
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Chưa nhập đại lý." });
    if (dto.QtyOrder <= 0) return Results.BadRequest(new { error = "Số lượng đặt phải > 0." });
    var deliv = Math.Max(0, Math.Min(dto.QtyDelivered, dto.QtyOrder));
    var b = new BackOrder { OrgId = t.OrgId, DealerCode = dto.DealerCode.Trim(), DealerName = dto.DealerName ?? "", ModelCode = dto.ModelCode.Trim(), SpecDesc = dto.SpecDesc ?? "", QtyOrder = dto.QtyOrder, QtyDelivered = deliv };
    db.BackOrders.Add(b); await db.SaveChangesAsync();
    return Results.Ok(new { b.ModelCode, b.DealerCode, backOrder = b.QtyOrder - b.QtyDelivered });
}).RequireAuthorization();

// Báo cáo back-order theo MODEL (gom theo model/spec).
app.MapGet("/api/backorder/bymodel", async (AppDbContext db, ITenantContext t, string? dealer) =>
{
    var q = db.BackOrders.Where(b => b.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(b => b.DealerCode == dealer);
    var recs = await q.ToListAsync();
    var rows = recs.GroupBy(b => new { b.ModelCode, b.SpecDesc })
        .Select(g => new { modelCode = g.Key.ModelCode, specDesc = g.Key.SpecDesc, qtyOrder = g.Sum(x => x.QtyOrder), qtyDelivered = g.Sum(x => x.QtyDelivered), backOrder = g.Sum(x => x.QtyOrder - x.QtyDelivered) })
        .Where(x => true).OrderByDescending(x => x.backOrder).ToList();
    return Results.Ok(new { totalBackOrder = rows.Sum(x => x.backOrder), rows });
}).RequireAuthorization();

// Báo cáo back-order theo ĐẠI LÝ (gom theo đại lý).
app.MapGet("/api/backorder/bydealer", async (AppDbContext db, ITenantContext t, string? model) =>
{
    var q = db.BackOrders.Where(b => b.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(model)) q = q.Where(b => b.ModelCode == model);
    var recs = await q.ToListAsync();
    var rows = recs.GroupBy(b => new { b.DealerCode, b.DealerName })
        .Select(g => new { dealerCode = g.Key.DealerCode, dealerName = g.Key.DealerName, qtyOrder = g.Sum(x => x.QtyOrder), qtyDelivered = g.Sum(x => x.QtyDelivered), backOrder = g.Sum(x => x.QtyOrder - x.QtyDelivered) })
        .OrderByDescending(x => x.backOrder).ToList();
    return Results.Ok(new { totalBackOrder = rows.Sum(x => x.backOrder), rows });
}).RequireAuthorization();

// ===== Báo cáo bảo lãnh đến hạn thanh toán (port 1:1 FrmBLDenHanThanhToan) — tái dùng BankGuarantee =====
app.MapGet("/api/report/bldenhan", async (AppDbContext db, ITenantContext t, DateTime? from, DateTime? to) =>
{
    if (from is null) return Results.BadRequest(new { error = "Phải chọn ngày báo cáo từ" });
    var toDate = to ?? DateTime.Today;
    if (toDate.Date > DateTime.Today) return Results.BadRequest(new { error = "Ngày kết thúc bảo lãnh đến không được lớn hơn ngày hiện tại!" });
    var f = from.Value.Date; var e = toDate.Date.AddDays(1);
    // BL đến hạn = ngày hết hạn (DateExpired) rơi vào [from, to], đã duyệt, chưa tất toán.
    var recs = await db.BankGuarantees.Where(g => g.OrgId == t.OrgId && g.Status == "Approved" && g.FlagSettled != "1"
                    && g.DateExpired != null && g.DateExpired >= f && g.DateExpired < e).ToListAsync();
    var detail = recs.OrderBy(g => g.DateExpired).Select(g => new
    {
        g.GuaranteeNo, g.DealerCode, g.BankCode, g.BankGuaranteeNo, g.TotalAmount,
        dateExpired = g.DateExpired!.Value.ToString("yyyy-MM-dd"),
        daysLeft = (int)(g.DateExpired!.Value.Date - DateTime.Today).TotalDays
    }).ToList();
    var byBank = recs.GroupBy(g => string.IsNullOrEmpty(g.BankCode) ? "(chưa rõ)" : g.BankCode)
        .Select(g => new { bankCode = g.Key, count = g.Count(), totalAmount = g.Sum(x => x.TotalAmount) })
        .OrderByDescending(x => x.totalAmount).ToList();
    return Results.Ok(new { total = detail.Count, totalAmount = recs.Sum(g => g.TotalAmount), byBank, detail });
}).RequireAuthorization();

// ===== Báo cáo dư nợ bảo lãnh (port 1:1 FrmBaocaoBaolanh) — tái dùng BankGuarantee, gom theo NH + trạng thái =====
app.MapGet("/api/report/guarantee", async (AppDbContext db, ITenantContext t, string? grtNo, DateTime? openFrom, DateTime? openTo, string? bank) =>
{
    var q = db.BankGuarantees.Where(g => g.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(grtNo)) q = q.Where(g => g.GuaranteeNo.Contains(grtNo!) || g.BankGuaranteeNo.Contains(grtNo!));
    if (!string.IsNullOrWhiteSpace(bank)) q = q.Where(g => g.BankCode == bank);
    if (openFrom is not null) q = q.Where(g => g.DateOpen != null && g.DateOpen >= openFrom.Value.Date);
    if (openTo is not null) q = q.Where(g => g.DateOpen != null && g.DateOpen < openTo.Value.Date.AddDays(1));
    var recs = await q.ToListAsync();
    // Dư nợ BL = tổng giá trị BL đã duyệt, CHƯA tất toán.
    decimal Debit(BankGuarantee g) => g.Status == "Approved" && g.FlagSettled != "1" ? g.TotalAmount : 0;
    var byBank = recs.GroupBy(g => string.IsNullOrEmpty(g.BankCode) ? "(chưa rõ)" : g.BankCode)
        .Select(g => new { bankCode = g.Key, count = g.Count(), totalAmount = g.Sum(x => x.TotalAmount), debit = g.Sum(Debit), settled = g.Count(x => x.FlagSettled == "1") })
        .OrderByDescending(x => x.debit).ToList();
    var byStatus = recs.GroupBy(g => g.Status)
        .Select(g => new { status = g.Key, count = g.Count(), totalAmount = g.Sum(x => x.TotalAmount) })
        .OrderByDescending(x => x.count).ToList();
    var detail = recs.OrderByDescending(g => g.DateOpen).Take(500).Select(g => new
    {
        g.GuaranteeNo, g.DealerCode, g.BankCode, g.BankGuaranteeNo, g.TotalAmount, g.Status, g.FlagSettled,
        dateOpen = g.DateOpen != null ? g.DateOpen.Value.ToString("yyyy-MM-dd") : "",
        debit = Debit(g),
        g.TermActual, g.TermWarning, g.RemarkReject, g.ApprovedBy, g.BankCodeMonitor, g.BankBUCode
    }).ToList();
    return Results.Ok(new { total = recs.Count, totalDebit = recs.Sum(Debit), totalAmount = recs.Sum(g => g.TotalAmount), byBank, byStatus, detail });
}).RequireAuthorization();

// Cập nhật ngày mốc SO theo lô (port 1:1 FrmMng_SO_Approved_Date, 2010.HTC): ngày duyệt / hết hạn nghĩa vụ cọc / hết hạn BL / đến hạn giao xe.
app.MapGet("/api/salesorders/sodates", async (AppDbContext db, ITenantContext t, string? dealer, string? so) =>
{
    var q = db.SalesOrders.Where(o => o.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(o => o.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(so)) q = q.Where(o => o.SoCode.Contains(so!));
    var items = await q.OrderByDescending(o => o.Id).Take(500).Select(o => new {
        o.SoCode, o.DealerCode, o.Status, o.ApprovedDate, o.DepositDutyEndDate, o.GrtEndDate, o.CarDueDate, o.PenalizeActual
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, totalPenalize = items.Sum(x => x.PenalizeActual), items });
}).RequireAuthorization();

app.MapPost("/api/salesorders/edit-dates", async (SoEditDatesDto dto, AppDbContext db, ITenantContext t) =>
{
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.SOCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Không có SO thay đổi." });
    foreach (var l in lines)
        if (l.DepositDutyEndDate.HasValue && l.CarDueDate.HasValue && l.CarDueDate < l.DepositDutyEndDate)
            return Results.BadRequest(new { error = $"SO {l.SOCode}: ngày đến hạn giao xe phải >= ngày hết hạn nghĩa vụ cọc." });
    var codes = lines.Select(l => l.SOCode!.Trim()).ToHashSet();
    var orders = await db.SalesOrders.Where(o => o.OrgId == t.OrgId && codes.Contains(o.SoCode)).ToListAsync();
    var byCode = orders.ToDictionary(o => o.SoCode, o => o);
    int updated = 0; var notFound = new List<string>();
    foreach (var l in lines)
    {
        var code = l.SOCode!.Trim();
        if (!byCode.TryGetValue(code, out var o)) { notFound.Add(code); continue; }
        if (l.ApprovedDate.HasValue) o.ApprovedDate = l.ApprovedDate;
        if (l.DepositDutyEndDate.HasValue) o.DepositDutyEndDate = l.DepositDutyEndDate;
        if (l.GrtEndDate.HasValue) o.GrtEndDate = l.GrtEndDate;
        if (l.CarDueDate.HasValue) o.CarDueDate = l.CarDueDate;
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// Cập nhật tiền phạt trả chậm thực tế theo SO (port 1:1 FrmUpdatePenaltyPmtDelayReal, 2010.HTC).
app.MapPost("/api/salesorders/edit-penalty", async (SoEditPenaltyDto dto, AppDbContext db, ITenantContext t) =>
{
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.SOCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Không có SO thay đổi." });
    if (lines.Any(l => l.PenalizeActual < 0)) return Results.BadRequest(new { error = "Tiền phạt không được âm." });
    var codes = lines.Select(l => l.SOCode!.Trim()).ToHashSet();
    var orders = await db.SalesOrders.Where(o => o.OrgId == t.OrgId && codes.Contains(o.SoCode)).ToListAsync();
    var byCode = orders.ToDictionary(o => o.SoCode, o => o);
    int updated = 0; var notFound = new List<string>();
    foreach (var l in lines)
    {
        var code = l.SOCode!.Trim();
        if (!byCode.TryGetValue(code, out var o)) { notFound.Add(code); continue; }
        o.PenalizeActual = l.PenalizeActual; updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, totalPenalize = orders.Sum(o => o.PenalizeActual), notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// ===== Báo cáo bán hàng đại lý (port 1:1 FrmBanHangDL) — tái dùng SalesOrder + SalesOrderLine =====
app.MapGet("/api/report/salesbydealer", async (AppDbContext db, ITenantContext t, string? dealer, string? status, string? orderType, DateTime? from, DateTime? to) =>
{
    var q = db.SalesOrders.Where(o => o.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(o => o.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(o => o.Status == status);
    if (!string.IsNullOrWhiteSpace(orderType)) q = q.Where(o => o.OrderType == orderType);
    if (from is not null) q = q.Where(o => o.CreatedAt >= from.Value.Date);
    if (to is not null) q = q.Where(o => o.CreatedAt < to.Value.Date.AddDays(1));
    var orders = await q.ToListAsync();
    var ids = orders.Select(o => o.Id).ToHashSet();
    var lines = await db.SalesOrderLines.Where(l => l.OrgId == t.OrgId && ids.Contains(l.SalesOrderId)).ToListAsync();
    var lineByOrder = lines.GroupBy(l => l.SalesOrderId).ToDictionary(g => g.Key, g => g.ToList());
    int ReqQty(long oid) => lineByOrder.TryGetValue(oid, out var ls) ? ls.Sum(x => x.RequestedQuantity) : 0;
    int AppQty(long oid) => lineByOrder.TryGetValue(oid, out var ls) ? ls.Sum(x => x.ApprovedQuantity ?? 0) : 0;
    decimal Amount(long oid) => lineByOrder.TryGetValue(oid, out var ls) ? ls.Sum(x => x.UnitPrice * x.RequestedQuantity) : 0;
    var byDealer = orders.GroupBy(o => string.IsNullOrEmpty(o.DealerCode) ? "(chưa rõ)" : o.DealerCode)
        .Select(g => new { dealerCode = g.Key, orders = g.Count(), reqQty = g.Sum(o => ReqQty(o.Id)), appQty = g.Sum(o => AppQty(o.Id)), amount = g.Sum(o => Amount(o.Id)) })
        .OrderByDescending(x => x.amount).ToList();
    var byStatus = orders.GroupBy(o => o.Status).Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var detail = orders.OrderByDescending(o => o.Id).Take(500).Select(o => new
    {
        o.SoCode, o.DealerCode, o.OrderType, o.PayType, o.Status, createdAt = o.CreatedAt.ToString("yyyy-MM-dd"),
        reqQty = ReqQty(o.Id), appQty = AppQty(o.Id), amount = Amount(o.Id)
    }).ToList();
    return Results.Ok(new { totalOrders = orders.Count, totalReqQty = orders.Sum(o => ReqQty(o.Id)), totalAmount = orders.Sum(o => Amount(o.Id)), byDealer, byStatus, detail });
}).RequireAuthorization();

// ===== Báo cáo tổng hợp (port 1:1 FrmBaoCaoTongHop) — dashboard gộp các entity chính, tái dùng =====
app.MapGet("/api/report/summary", async (AppDbContext db, ITenantContext t) =>
{
    var org = t.OrgId;
    // Đơn hàng bán
    var so = await db.SalesOrders.Where(o => o.OrgId == org).Select(o => o.Status).ToListAsync();
    var soLineAmt = await db.SalesOrderLines.Where(l => l.OrgId == org).SumAsync(l => (decimal?)(l.UnitPrice * l.RequestedQuantity)) ?? 0;
    // Bán buôn ĐL->ĐL
    // #B09: sau hợp nhất song trùng #5, bán buôn ĐL→ĐL nằm trong `DealerDeal` (DLS_Deal) — nhận diện bằng
    // `DealerCodeBuyer` khác rỗng; tiền lấy từ Σ `PriceAFVAT` của dòng (đầu giao dịch không có cột tổng).
    var wsDeals = await db.DealerDeals.Where(w => w.OrgId == org && w.DealerCodeBuyer != null && w.DealerCodeBuyer != "").Select(w => w.Id).ToListAsync();
    var wsAmount = await db.DealerDealDetails.Where(c => c.OrgId == org && wsDeals.Contains(c.DealId)).SumAsync(c => (decimal?)c.PriceAFVAT) ?? 0m;
    // Bảo lãnh ngân hàng
    var grt = await db.BankGuarantees.Where(g => g.OrgId == org).Select(g => new { g.Status, g.FlagSettled, g.TotalAmount }).ToListAsync();
    // Phiếu thanh toán
    var pm = await db.PmtPayments.Where(p => p.OrgId == org).Select(p => new { p.PaymentStatus, p.TotalAmount }).ToListAsync();
    // Hợp đồng đại lý bán lẻ
    var dc = await db.DlrContracts.Where(c => c.OrgId == org).CountAsync();
    // Back-order
    var bo = await db.BackOrders.Where(b => b.OrgId == org).Select(b => new { b.QtyOrder, b.QtyDelivered }).ToListAsync();

    var summary = new
    {
        salesOrders = new { count = so.Count, byStatus = so.GroupBy(s => s).Select(g => new { status = g.Key, count = g.Count() }).ToList(), totalAmount = soLineAmt },
        // #B09: bỏ `confirmed` — `DLS_Deal` không có cột trạng thái (Draft/Confirmed/Cancelled là BỊA).
        wholesaleDeals = new { count = wsDeals.Count, totalAmount = wsAmount },
        guarantees = new { count = grt.Count, approved = grt.Count(g => g.Status == "Approved"), debit = grt.Where(g => g.Status == "Approved" && g.FlagSettled != "1").Sum(g => g.TotalAmount), settled = grt.Count(g => g.FlagSettled == "1") },
        payments = new { count = pm.Count, approved = pm.Count(p => p.PaymentStatus == "Approved"), totalAmount = pm.Sum(p => p.TotalAmount) },
        dealerContracts = new { count = dc },
        backOrder = new { totalOrder = bo.Sum(b => b.QtyOrder), totalDelivered = bo.Sum(b => b.QtyDelivered), backOrder = bo.Sum(b => b.QtyOrder - b.QtyDelivered) }
    };
    return Results.Ok(summary);
}).RequireAuthorization();

// ===== Báo cáo tình trạng hiệu lực bảo lãnh (port 1:1 FrmBCTinhTrangHoSoHieuLucBaoLanh) — tái dùng BankGuarantee =====
app.MapGet("/api/report/grtvalidity", async (AppDbContext db, ITenantContext t, string? bank, int? soonDays) =>
{
    var soon = soonDays is > 0 ? soonDays.Value : 30;   // ngưỡng "sắp hết hạn" (mặc định 30 ngày)
    var q = db.BankGuarantees.Where(g => g.OrgId == t.OrgId && g.Status == "Approved" && g.FlagSettled != "1");
    if (!string.IsNullOrWhiteSpace(bank)) q = q.Where(g => g.BankCode == bank);
    var recs = await q.ToListAsync();
    var today = DateTime.Today;
    string Classify(BankGuarantee g)
    {
        if (g.DateExpired is null) return "NoDate";
        var days = (g.DateExpired.Value.Date - today).Days;
        if (days < 0) return "Expired";
        if (days <= soon) return "ExpiringSoon";
        return "Valid";
    }
    var detail = recs.OrderBy(g => g.DateExpired ?? DateTime.MaxValue).Take(500).Select(g => new
    {
        g.GuaranteeNo, g.DealerCode, g.BankCode, g.BankGuaranteeNo, g.TotalAmount,
        dateExpired = g.DateExpired != null ? g.DateExpired.Value.ToString("yyyy-MM-dd") : "",
        daysLeft = g.DateExpired != null ? (int)(g.DateExpired.Value.Date - today).TotalDays : (int?)null,
        validity = Classify(g)
    }).ToList();
    var byValidity = recs.GroupBy(Classify)
        .Select(g => new { validity = g.Key, count = g.Count(), totalAmount = g.Sum(x => x.TotalAmount) }).ToList();
    return Results.Ok(new
    {
        soonDays = soon,
        total = recs.Count,
        valid = recs.Count(g => Classify(g) == "Valid"),
        expiringSoon = recs.Count(g => Classify(g) == "ExpiringSoon"),
        expired = recs.Count(g => Classify(g) == "Expired"),
        byValidity, detail
    });
}).RequireAuthorization();

// ===== Báo cáo phiếu thanh toán ngân hàng (port 1:1 báo cáo Pmt_PM) — tái dùng BankPayment =====
app.MapGet("/api/report/payment", async (AppDbContext db, ITenantContext t, string? bank, string? status, string? dealer, DateTime? from, DateTime? to) =>
{
    var q = db.PmtPayments.Where(p => p.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(bank)) q = q.Where(p => p.BankCodeReceive == bank || p.BankCodeSend == bank);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(p => p.PaymentStatus == status);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(p => p.DealerCode == dealer);
    if (from is not null) q = q.Where(p => p.CreatedDate >= from.Value.Date);
    if (to is not null) q = q.Where(p => p.CreatedDate < to.Value.Date.AddDays(1));
    var recs = await q.ToListAsync();
    var byBank = recs.GroupBy(p => string.IsNullOrEmpty(p.BankCodeReceive) ? "(chưa rõ)" : p.BankCodeReceive)
        .Select(g => new { bankCode = g.Key, count = g.Count(), totalAmount = g.Sum(x => x.TotalAmount), approved = g.Count(x => x.PaymentStatus == "Approved") })
        .OrderByDescending(x => x.totalAmount).ToList();
    var byStatus = recs.GroupBy(p => p.PaymentStatus).Select(g => new { status = g.Key, count = g.Count(), totalAmount = g.Sum(x => x.TotalAmount) }).OrderByDescending(x => x.count).ToList();
    var byFunds = recs.GroupBy(p => string.IsNullOrEmpty(p.Funds) ? "(chưa rõ)" : p.Funds).Select(g => new { funds = g.Key, count = g.Count(), totalAmount = g.Sum(x => x.TotalAmount) }).OrderByDescending(x => x.totalAmount).ToList();
    var detail = recs.OrderByDescending(p => p.Id).Take(500).Select(p => new
    {
        p.PaymentNo, p.BankPaymentNo, p.DealerCode, p.BankCodeSend, p.BankCodeReceive, p.Funds, p.TotalAmount, p.PaymentStatus, p.AccountingRecordNo,
        createdAt = p.CreatedDate.ToString("yyyy-MM-dd")
    }).ToList();
    return Results.Ok(new { total = recs.Count, totalAmount = recs.Sum(p => p.TotalAmount), approvedAmount = recs.Where(p => p.PaymentStatus == "Approved").Sum(p => p.TotalAmount), byBank, byStatus, byFunds, detail });
}).RequireAuthorization();

// ===== Báo cáo hóa đơn VAT HTC (port 1:1 báo cáo VAT_HTCInvoice) — tái dùng VatInvoice + VatInvoiceCar =====
app.MapGet("/api/report/vatinvoice", async (AppDbContext db, ITenantContext t, string? dealer, string? status, string? adjType, DateTime? from, DateTime? to) =>
{
    var q = db.VatInvoices.Where(v => v.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(v => v.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(v => v.VatHTCStatus == status);
    if (adjType == "adj") q = q.Where(v => v.InvoiceAdjType != "");
    else if (adjType == "root") q = q.Where(v => v.InvoiceAdjType == "");
    if (from is not null) q = q.Where(v => v.CreatedAt >= from.Value.Date);
    if (to is not null) q = q.Where(v => v.CreatedAt < to.Value.Date.AddDays(1));
    var invs = await q.ToListAsync();
    var ids = invs.Select(v => v.Id).ToHashSet();
    var carAgg = await db.VatInvoiceCars.Where(c => c.OrgId == t.OrgId && ids.Contains(c.VatInvoiceId))
        .GroupBy(c => c.VatInvoiceId).Select(g => new { g.Key, cars = g.Count(), amount = g.Sum(x => x.HTCUnitPrice) }).ToListAsync();
    var carMap = carAgg.ToDictionary(x => x.Key, x => (x.cars, x.amount));
    int Cars(long id) => carMap.TryGetValue(id, out var v) ? v.cars : 0;
    decimal Amt(long id) => carMap.TryGetValue(id, out var v) ? v.amount : 0;
    var byDealer = invs.GroupBy(v => string.IsNullOrEmpty(v.DealerCode) ? "(chưa rõ)" : v.DealerCode)
        .Select(g => new { dealerCode = g.Key, count = g.Count(), cars = g.Sum(v => Cars(v.Id)), amount = g.Sum(v => Amt(v.Id)) }).OrderByDescending(x => x.amount).ToList();
    var byStatus = invs.GroupBy(v => v.VatHTCStatus).Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var detail = invs.OrderByDescending(v => v.Id).Take(500).Select(v => new
    {
        v.HTCInvoiceCode, v.HTCInvoiceNo, v.InvoiceIDCode, v.DealerCode, v.VAT, v.InvoiceAdjType, v.VatHTCStatus, v.OS_HDDT_InvoiceCode,
        cars = Cars(v.Id), amount = Amt(v.Id), createdAt = v.CreatedAt.ToString("yyyy-MM-dd")
    }).ToList();
    return Results.Ok(new { total = invs.Count, totalCars = invs.Sum(v => Cars(v.Id)), totalAmount = invs.Sum(v => Amt(v.Id)),
        pending = invs.Count(v => v.VatHTCStatus == "P"), issued = invs.Count(v => v.VatHTCStatus == "F"),
        cancelled = invs.Count(v => v.VatHTCStatus == "C"), rejected = invs.Count(v => v.VatHTCStatus == "R"), byDealer, byStatus, detail });
}).RequireAuthorization();

// ===== Báo cáo bán buôn ĐL→ĐL (port 1:1 báo cáo Deal To Dealer) =====
// #B09: đọc thẳng bảng CHUẨN `DealerDeal`/`DealerDealDetail` (`DLS_Deal`/`DLS_DealDetail`) sau khi hợp nhất
//       song trùng #5. Trước đó báo cáo đọc `WholesaleDeal` nên **không thấy** giao dịch nào ghi qua
//       `/api/dealerdeals/todealer` — và ngược lại. Tiền tệ lấy từ Σ `PriceAFVAT` của dòng, đúng nguồn
//       (đầu `DLS_Deal` KHÔNG có cột tổng tiền).
// 🔴 Bỏ bộ lọc/nhóm theo `status`: `DLS_Deal` không có cột trạng thái nào (Draft/Confirmed/Cancelled là BỊA).
app.MapGet("/api/report/wholesale", async (AppDbContext db, ITenantContext t, string? buyer, string? salesman, DateTime? from, DateTime? to) =>
{
    var q = db.DealerDeals.Where(w => w.OrgId == t.OrgId && w.DealerCodeBuyer != null && w.DealerCodeBuyer != "");
    if (!string.IsNullOrWhiteSpace(buyer)) q = q.Where(w => w.DealerCodeBuyer == buyer);
    if (!string.IsNullOrWhiteSpace(salesman)) q = q.Where(w => w.SalesManCode == salesman);
    if (from is not null) q = q.Where(w => w.CreatedAt >= from.Value.Date);
    if (to is not null) q = q.Where(w => w.CreatedAt < to.Value.Date.AddDays(1));
    var deals = await q.ToListAsync();
    var ids = deals.Select(d => d.Id).ToHashSet();
    var lines = await db.DealerDealDetails.Where(c => c.OrgId == t.OrgId && ids.Contains(c.DealId))
        .GroupBy(c => c.DealId).Select(g => new { g.Key, cars = g.Count(), amount = g.Sum(x => x.PriceAFVAT) }).ToListAsync();
    var carMap = lines.ToDictionary(x => x.Key, x => x.cars);
    var amtMap = lines.ToDictionary(x => x.Key, x => x.amount);
    int Cars(long id) => carMap.TryGetValue(id, out var v) ? v : 0;
    decimal Amt(long id) => amtMap.TryGetValue(id, out var v) ? v : 0m;
    var byBuyer = deals.GroupBy(d => string.IsNullOrEmpty(d.DealerCodeBuyer) ? "(chưa rõ)" : d.DealerCodeBuyer!)
        .Select(g => new { buyerDealerCode = g.Key, count = g.Count(), cars = g.Sum(d => Cars(d.Id)), amount = g.Sum(d => Amt(d.Id)) })
        .OrderByDescending(x => x.amount).ToList();
    var bySalesType = deals.GroupBy(d => string.IsNullOrEmpty(d.SalesType) ? "(chưa rõ)" : d.SalesType)
        .Select(g => new { salesType = g.Key, count = g.Count(), amount = g.Sum(x => Amt(x.Id)) }).OrderByDescending(x => x.count).ToList();
    var bySalesman = deals.Where(d => !string.IsNullOrEmpty(d.SalesManCode)).GroupBy(d => d.SalesManCode!)
        .Select(g => new { salesManCode = g.Key, count = g.Count(), amount = g.Sum(x => Amt(x.Id)) }).OrderByDescending(x => x.amount).ToList();
    var detail = deals.OrderByDescending(d => d.Id).Take(500).Select(d => new
    {
        d.DealNo, d.DealNoUser, buyerDealerCode = d.DealerCodeBuyer, d.SalesManCode, d.SalesType, d.DlrContractNo,
        totalAmount = Amt(d.Id), cars = Cars(d.Id), createdAt = d.CreatedAt.ToString("yyyy-MM-dd")
    }).ToList();
    return Results.Ok(new { total = deals.Count, totalAmount = deals.Sum(d => Amt(d.Id)),
        totalCars = deals.Sum(d => Cars(d.Id)), byBuyer, bySalesType, bySalesman, detail });
}).RequireAuthorization();

// ===== Báo cáo yêu cầu bảo hiểm (port 1:1 báo cáo Ins_InsuranceReq) — tái dùng InsuranceReq + Dtl =====
app.MapGet("/api/report/insurance", async (AppDbContext db, ITenantContext t, string? company, string? status, string? insType, DateTime? from, DateTime? to, string? insCompanyPattern) =>
{
    var q = db.InsuranceReqs.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(company)) q = q.Where(r => r.InsCompanyCode == company);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(r => r.Status == status);
    // 🔴 RBAC của nguồn (TERP.BizInsurance/InsReq.cs): người dùng công ty bảo hiểm CHỈ thấy dữ liệu
    // của công ty mình — nguồn lọc bằng PATTERN `InsCompanyCode like @strAbilityOfUser`.
    // Port cũ KHÔNG có tầng lọc này ở BẤT KỲ đường đọc nào.
    if (!string.IsNullOrWhiteSpace(insCompanyPattern)) { var _p = insCompanyPattern!.Trim().Replace("%", ""); q = q.Where(r => r.InsCompanyCode.Contains(_p)); }
    if (!string.IsNullOrWhiteSpace(insType)) q = q.Where(r => r.InsTypeCode == insType);
    if (from is not null) q = q.Where(r => r.CreatedAt >= from.Value.Date);
    if (to is not null) q = q.Where(r => r.CreatedAt < to.Value.Date.AddDays(1));
    var reqs = await q.ToListAsync();
    var ids = reqs.Select(r => r.Id).ToHashSet();
    var dtlAgg = await db.InsuranceReqDtls.Where(c => c.OrgId == t.OrgId && ids.Contains(c.InsuranceReqId))
        .GroupBy(c => c.InsuranceReqId).Select(g => new { g.Key, cars = g.Count(), insAmount = g.Sum(x => x.InsAmount), fee = g.Sum(x => x.Price) }).ToListAsync();
    var m = dtlAgg.ToDictionary(x => x.Key, x => (x.cars, x.insAmount, x.fee));
    int Cars(long id) => m.TryGetValue(id, out var v) ? v.cars : 0;
    decimal InsAmt(long id) => m.TryGetValue(id, out var v) ? v.insAmount : 0;
    decimal Fee(long id) => m.TryGetValue(id, out var v) ? v.fee : 0;
    var byCompany = reqs.GroupBy(r => string.IsNullOrEmpty(r.InsCompanyCode) ? "(chưa rõ)" : r.InsCompanyCode)
        .Select(g => new { company = g.Key, count = g.Count(), cars = g.Sum(r => Cars(r.Id)), insAmount = g.Sum(r => InsAmt(r.Id)), fee = g.Sum(r => Fee(r.Id)) }).OrderByDescending(x => x.insAmount).ToList();
    var byStatus = reqs.GroupBy(r => r.Status).Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var byType = reqs.GroupBy(r => string.IsNullOrEmpty(r.InsTypeCode) ? "(chưa rõ)" : r.InsTypeCode).Select(g => new { insType = g.Key, count = g.Count(), cars = g.Sum(r => Cars(r.Id)) }).OrderByDescending(x => x.count).ToList();
    var detail = reqs.OrderByDescending(r => r.Id).Take(500).Select(r => new
    {
        r.InsReqNo, r.InsCompanyCode, r.InsTypeCode, r.Status, cars = Cars(r.Id), insAmount = InsAmt(r.Id), fee = Fee(r.Id), createdAt = r.CreatedAt.ToString("yyyy-MM-dd")
    }).ToList();
    return Results.Ok(new { total = reqs.Count, totalCars = reqs.Sum(r => Cars(r.Id)), totalInsAmount = reqs.Sum(r => InsAmt(r.Id)), totalFee = reqs.Sum(r => Fee(r.Id)), byCompany, byStatus, byType, detail });
}).RequireAuthorization();

// ===== Báo cáo công văn bảo lãnh/claim đại lý (port 1:1 báo cáo GrtClaim) — tái dùng GrtClaim + GrtClaimDetail =====
app.MapGet("/api/report/grtclaim", async (AppDbContext db, ITenantContext t, string? dealer, string? status, string? flag, DateTime? from, DateTime? to) =>
{
    var q = db.GrtClaims.Where(g => g.OrgId == t.OrgId);
