    var byBank = rows.GroupBy(r => string.IsNullOrEmpty(r.BankCode) ? "(không vay)" : r.BankCode)
        .Select(g => new { bankCode = g.Key, cars = g.Count(), amount = g.Sum(x => x.Price) }).OrderByDescending(x => x.cars).ToList();
