// ===== Báo cáo đẩy sổ bảo hành online (port 1:1 báo cáo SbhOnline) — tái dùng SbhOnline =====
app.MapGet("/api/report/sbhonline", async (AppDbContext db, ITenantContext t, string? dealer, string? status) =>
{
    var q = db.SbhOnlines.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(r => r.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(r => r.PostStatus == status);
    var rows = await q.ToListAsync();
    var byDealer = rows.GroupBy(r => string.IsNullOrEmpty(r.DealerCode) ? "(chưa rõ)" : r.DealerCode)
        .Select(g => new { dealerCode = g.Key, cars = g.Count(), posted = g.Count(x => x.PostStatus == "Posted"), pending = g.Count(x => x.PostStatus != "Posted"), pushes = g.Sum(x => x.PushCount) })
        .OrderByDescending(x => x.cars).ToList();
    var byStatus = rows.GroupBy(r => r.PostStatus).Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var retry = rows.Count(r => r.PushCount > 1);
    var detail = rows.OrderByDescending(r => r.Id).Take(500).Select(r => new
    {
        r.VIN, r.DealNo, r.DealerCode, r.PostStatus, r.PushCount,
        deliveryDate = r.DeliveryDate.HasValue ? r.DeliveryDate.Value.ToString("yyyy-MM-dd") : "",
        lastPushAt = r.LastPushAt.HasValue ? r.LastPushAt.Value.ToString("yyyy-MM-dd HH:mm") : ""
    }).ToList();
    return Results.Ok(new { total = rows.Count, posted = rows.Count(r => r.PostStatus == "Posted"), pending = rows.Count(r => r.PostStatus != "Posted"), totalPushes = rows.Sum(r => r.PushCount), retry, byDealer, byStatus, detail });
}).RequireAuthorization();

// ===== Báo cáo yêu cầu thế chấp xe (port 1:1 báo cáo ReqMortgage) — tái dùng ReqMortgage + ReqMortgageCar =====
app.MapGet("/api/report/reqmortgage", async (AppDbContext db, ITenantContext t, string? mortageBank, string? dealer, string? status) =>
{
    var q = db.ReqMortgages.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(mortageBank)) q = q.Where(r => r.MortageBankCode == mortageBank);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(r => r.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(r => r.Status == status);
    var reqs = await q.ToListAsync();
    var ids = reqs.Select(r => r.Id).ToHashSet();
    var cars = await db.ReqMortgageCars.Where(c => c.OrgId == t.OrgId && ids.Contains(c.ReqMortgageId)).ToListAsync();
    var carByReq = cars.GroupBy(c => c.ReqMortgageId).ToDictionary(g => g.Key, g => g.Count());
    var byBank = reqs.GroupBy(r => string.IsNullOrEmpty(r.MortageBankCode) ? "(chưa rõ)" : r.MortageBankCode)
        .Select(g => new { mortageBank = g.Key, reqs = g.Count(), approved = g.Count(x => x.Status == "Approved"), cars = g.Sum(x => carByReq.TryGetValue(x.Id, out var c) ? c : 0) })
        .OrderByDescending(x => x.cars).ToList();
    var byDealer = reqs.GroupBy(r => string.IsNullOrEmpty(r.DealerCode) ? "(chưa rõ)" : r.DealerCode)
        .Select(g => new { dealerCode = g.Key, reqs = g.Count(), cars = g.Sum(x => carByReq.TryGetValue(x.Id, out var c) ? c : 0) })
        .OrderByDescending(x => x.cars).ToList();
    var byStatus = reqs.GroupBy(r => r.Status).Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var detail = reqs.OrderByDescending(r => r.Id).Take(500).Select(r => new
    {
        r.ReqRMNo, r.MortageBankCode, r.DealerCode, r.Status,
        cars = carByReq.TryGetValue(r.Id, out var c) ? c : 0,
        mortageDate = r.MortageDate.HasValue ? r.MortageDate.Value.ToString("yyyy-MM-dd") : "",
        createdAt = r.CreatedAt.ToString("yyyy-MM-dd")
    }).ToList();
    return Results.Ok(new { total = reqs.Count, totalCars = cars.Count, approved = reqs.Count(r => r.Status == "Approved"), byBank, byDealer, byStatus, detail });
}).RequireAuthorization();

// ===== Báo cáo xác nhận giao xe vận chuyển (port 1:1 báo cáo TranspDlvConfirm) — tái dùng TranspDlvConfirm + Car =====
app.MapGet("/api/report/transpdlv", async (AppDbContext db, ITenantContext t, string? transporter, string? dealer, string? status) =>
{
    var q = db.TranspDlvConfirms.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(transporter)) q = q.Where(r => r.TransporterCode == transporter);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(r => r.DealerCode == dealer);
    // #199: lọc theo trạng thái phía GIAO (FDlvMnStatus) — cột `ConfirmStatus` không có ở nguồn.
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(r => r.FDlvMnStatus == status);
    var reqs = await q.ToListAsync();
    var ids = reqs.Select(r => r.Id).ToHashSet();
    var cars = await db.TranspDlvConfirmCars.Where(c => c.OrgId == t.OrgId && ids.Contains(c.TranspDlvConfirmId)).ToListAsync();
    var carByReq = cars.GroupBy(c => c.TranspDlvConfirmId).ToDictionary(g => g.Key, g => g.Count());
    var byTransporter = reqs.GroupBy(r => string.IsNullOrEmpty(r.TransporterCode) ? "(chưa rõ)" : r.TransporterCode)
        .Select(g => new { transporter = g.Key, minutes = g.Count(),
                           // #199: đếm theo TRỤC THẬT của nguồn (FDlvMnStatus = "A"), không theo cột bịa ConfirmStatus.
                           confirmed = g.Count(x => x.FDlvMnStatus == "A"), cars = g.Sum(x => carByReq.TryGetValue(x.Id, out var c) ? c : 0) })
        .OrderByDescending(x => x.cars).ToList();
    var byDealer = reqs.GroupBy(r => string.IsNullOrEmpty(r.DealerCode) ? "(chưa rõ)" : r.DealerCode)
        .Select(g => new { dealerCode = g.Key, minutes = g.Count(), cars = g.Sum(x => carByReq.TryGetValue(x.Id, out var c) ? c : 0) })
        .OrderByDescending(x => x.cars).ToList();
    // #199: nhóm theo CẶP hai phía duyệt — đúng mô hình nguồn (biên bản có HAI trục độc lập).
    var byStatus = reqs.GroupBy(r => r.FDlvMnStatus + "/" + r.TDlvMnStatus)
        .Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var detail = reqs.OrderByDescending(r => r.Id).Take(500).Select(r => new
    {
        r.DlvMinutesNo, r.TransporterCode, r.DealerCode, r.FDlvMnStatus, r.TDlvMnStatus,   // #199 trục thật
        cars = carByReq.TryGetValue(r.Id, out var c) ? c : 0,
        confirmDate = r.ConfirmDate.HasValue ? r.ConfirmDate.Value.ToString("yyyy-MM-dd") : "",
        createdAt = r.CreatedAt.ToString("yyyy-MM-dd")
    }).ToList();
    return Results.Ok(new { total = reqs.Count, totalCars = cars.Count,
        confirmed = reqs.Count(r => r.FDlvMnStatus == "A"),   // #199 trục thật
        confirmedBothSides = reqs.Count(r => r.FDlvMnStatus == "A" && r.TDlvMnStatus == "A"),
        byTransporter, byDealer, byStatus, detail });
}).RequireAuthorization();

// ===== Báo cáo yêu cầu QC/giao hồ sơ xe (port 1:1 báo cáo QcDocReq) — tái dùng QcDocReq + QcDocReqCar =====
app.MapGet("/api/report/qcdocreq", async (AppDbContext db, ITenantContext t, string? model, string? deliverType, string? status) =>
{
    var q = db.QcDocReqs.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(r => r.DocReqStatus == status);
    var reqs = await q.ToListAsync();
    var ids = reqs.Select(r => r.Id).ToHashSet();
    var cq = db.QcDocReqCars.Where(c => c.OrgId == t.OrgId && ids.Contains(c.QcDocReqId));
    if (!string.IsNullOrWhiteSpace(model)) cq = cq.Where(c => c.ModelCode == model);
    if (!string.IsNullOrWhiteSpace(deliverType)) cq = cq.Where(c => c.DocDeliverTypeCode == deliverType);
    var cars = await cq.ToListAsync();
    var byModel = cars.GroupBy(c => string.IsNullOrEmpty(c.ModelCode) ? "(chưa rõ)" : c.ModelCode)
        .Select(g => new { modelCode = g.Key, cars = g.Count() }).OrderByDescending(x => x.cars).ToList();
    var byDeliver = cars.GroupBy(c => string.IsNullOrEmpty(c.DocDeliverTypeCode) ? "(chưa rõ)" : c.DocDeliverTypeCode)
        .Select(g => new { deliverType = g.Key, cars = g.Count() }).OrderByDescending(x => x.cars).ToList();
    var byStatus = reqs.GroupBy(r => r.DocReqStatus).Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var carByReq = cars.GroupBy(c => c.QcDocReqId).ToDictionary(g => g.Key, g => g.Count());
    var detail = reqs.Where(r => carByReq.ContainsKey(r.Id) || string.IsNullOrEmpty(model + deliverType))
        .OrderByDescending(r => r.Id).Take(500).Select(r => new
        {
            r.DocReqNo, r.CreateBy, r.DocReqStatus, cars = carByReq.TryGetValue(r.Id, out var c) ? c : 0, createdAt = r.CreatedAt.ToString("yyyy-MM-dd")
        }).ToList();
    return Results.Ok(new { total = reqs.Count, totalCars = cars.Count, approved = reqs.Count(r => r.DocReqStatus == "Approved"), byModel, byDeliver, byStatus, detail });
}).RequireAuthorization();

// ===== Báo cáo sắp xếp kho (port 1:1 báo cáo StorageRearrange/SC) — tái dùng StorageRearrange + Detail =====
app.MapGet("/api/report/storagerearrange", async (AppDbContext db, ITenantContext t, string? storageFrom, string? storageTo, string? status) =>
{
    var q = db.StorageRearranges.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(r => r.Status == status);
    var reqs = await q.ToListAsync();
    var ids = reqs.Select(r => r.Id).ToHashSet();
    var lq = db.StorageRearrangeDetails.Where(l => l.OrgId == t.OrgId && ids.Contains(l.StorageRearrangeId));
    if (!string.IsNullOrWhiteSpace(storageFrom)) lq = lq.Where(l => l.StorageCodeFrom == storageFrom);
    if (!string.IsNullOrWhiteSpace(storageTo)) lq = lq.Where(l => l.StorageCodeTo == storageTo);
    var lines = await lq.ToListAsync();
    var byRoute = lines.GroupBy(l => new { From = string.IsNullOrEmpty(l.StorageCodeFrom) ? "(chưa rõ)" : l.StorageCodeFrom, To = string.IsNullOrEmpty(l.StorageCodeTo) ? "(chưa rõ)" : l.StorageCodeTo })
        .Select(g => new { route = g.Key.From + " → " + g.Key.To, cars = g.Count() }).OrderByDescending(x => x.cars).ToList();
    var byStatus = reqs.GroupBy(r => r.Status).Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var byDay = reqs.GroupBy(r => r.CreatedAt.ToString("yyyy-MM-dd")).Select(g => new { day = g.Key, count = g.Count() }).OrderByDescending(x => x.day).Take(30).ToList();
    var carByReq = lines.GroupBy(l => l.StorageRearrangeId).ToDictionary(g => g.Key, g => g.Count());
    var detail = reqs.Where(r => carByReq.ContainsKey(r.Id) || string.IsNullOrEmpty(storageFrom + storageTo))
        .OrderByDescending(r => r.Id).Take(500).Select(r => new
        {
            r.SCNo, r.Status, cars = carByReq.TryGetValue(r.Id, out var c) ? c : 0, createdAt = r.CreatedAt.ToString("yyyy-MM-dd")
        }).ToList();
    return Results.Ok(new { total = reqs.Count, totalCars = lines.Count, confirmed = reqs.Count(r => r.Status == "Confirmed"), byRoute, byStatus, byDay, detail });
}).RequireAuthorization();

// ===== Báo cáo chuyển kho xe (port 1:1 báo cáo CBReq) — tái dùng CBReq + CBReqDetail =====
app.MapGet("/api/report/cbreq", async (AppDbContext db, ITenantContext t, string? storageFrom, string? storageTo, string? typeCB, string? status) =>
{
    var q = db.StoCBReqs.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(r => r.CBReqStatus == status);
    var reqs = await q.ToListAsync();
    var ids = reqs.Select(r => r.Id).ToHashSet();
    var lq = db.StoCBReqDtls.Where(l => l.OrgId == t.OrgId && ids.Contains(l.StoCBReqId));
    if (!string.IsNullOrWhiteSpace(storageFrom)) lq = lq.Where(l => l.StorageCodeFrom == storageFrom);
    if (!string.IsNullOrWhiteSpace(storageTo)) lq = lq.Where(l => l.StorageCodeTo == storageTo);
    if (!string.IsNullOrWhiteSpace(typeCB)) lq = lq.Where(l => l.TypeCB == typeCB);
    var lines = await lq.ToListAsync();
    var byRoute = lines.GroupBy(l => new { From = string.IsNullOrEmpty(l.StorageCodeFrom) ? "(chưa rõ)" : l.StorageCodeFrom, To = string.IsNullOrEmpty(l.StorageCodeTo) ? "(chưa rõ)" : l.StorageCodeTo })
        .Select(g => new { route = g.Key.From + " → " + g.Key.To, cars = g.Count() }).OrderByDescending(x => x.cars).ToList();
    var byType = lines.GroupBy(l => string.IsNullOrEmpty(l.TypeCB) ? "(chưa rõ)" : l.TypeCB).Select(g => new { typeCB = g.Key, cars = g.Count() }).OrderByDescending(x => x.cars).ToList();
    var byStatus = reqs.GroupBy(r => r.CBReqStatus).Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    // cars per req
    var carByReq = lines.GroupBy(l => l.StoCBReqId).ToDictionary(g => g.Key, g => g.Count());
    var detail = reqs.Where(r => carByReq.ContainsKey(r.Id) || string.IsNullOrEmpty(storageFrom + storageTo + typeCB))
        .OrderByDescending(r => r.Id).Take(500).Select(r => new
        {
            r.CBReqNo, r.CBReqStatus, cars = carByReq.TryGetValue(r.Id, out var c) ? c : 0, createdAt = r.CreatedDate.ToString("yyyy-MM-dd")
        }).ToList();
    return Results.Ok(new { total = reqs.Count, totalCars = lines.Count, confirmed = reqs.Count(r => r.CBReqStatus == "A"), byRoute, byType, byStatus, detail });
}).RequireAuthorization();

// ===== Tài khoản ngân hàng (BankAccount — port 1:1 FrmMstAccountBank, 2010.HTC/Admin/Product) =====
app.MapGet("/api/bankaccounts", async (AppDbContext db, ITenantContext t, string? bank, string? dealer, string? active) =>
{
    var q = db.BankAccounts.Where(a => a.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(bank)) q = q.Where(a => a.BankCode == bank);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(a => a.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(active)) q = q.Where(a => a.FlagActive == active);
    var items = await q.OrderByDescending(a => a.Id).Take(500).Select(a => new { a.AccountNo, a.AccountName, a.BankCode, a.DealerCode, a.FlagAccGrtClaim, a.FlagActive }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
