app.MapGet("/api/gpsdlvaddresses", async (AppDbContext db, ITenantContext t, string? dlvMnNo, string? vin, string? gpsStatus) =>
{
    var q = db.GpsDlvMinutesAddresses.Where(x => x.OrgId == t.OrgId);
