// ===== #B33 AUDIT PARITY `Ord_SalesOrder_UpdateMulti` (`FrmUpdate_SO_Approved_Date`) — 5 GAP =====
// Trace LIVE: `sv.Ord_SalesOrder_UpdateMulti` → **`_biz.Ord_SalesOrder_UpdateMulti`**
//   (`DataWH/Biz.HTC.WH.My.cs:19901`, chỉ có ở WS 64-bit).
// 🔴 GAP 1 — **PORT CŨ KHÔNG SỬA GÌ CẢ**: nó chỉ ghi hai bảng `*_SupportLog`. Nguồn thì `update
//    Ord_SalesOrder` **VÀ** `update Ord_SalesOrderDetail` (`:20135`, `:20174`), log chỉ là **tác dụng phụ**
//    chụp lại trước/sau. Hệ quả: màn "sửa ngày duyệt SO" **ghi nhật ký một thay đổi chưa từng xảy ra** —
//    cùng loại lỗi với "đổi màu xe mà không đổi màu" (#B25).
// 🔴 GAP 2 — **Giá trị CŨ lấy sai nguồn**: nguồn chụp `#tblOrd_SalesOrderOld` từ **BẢNG ĐƠN THẬT** ngay
//    trước khi update; port cũ đọc bản ghi log gần nhất ⇒ lần đầu sửa thì Old = null, và mọi thay đổi
//    do luồng khác gây ra đều **không được ghi nhận**.
// 🔴 GAP 3 — **Đầu vào là BẢNG NHIỀU SO**, mỗi dòng đúng **hai** cột nghiệp vụ `SOCode` + `ApprovedDate`
//    (`MyBuildDBDT_Common :20080-20090`; `DepositDutyEndDate`/`CarDueDate` **đã bị comment**). Port cũ nhận
//    một SO kèm danh sách dòng có 4 mốc ngày riêng — **bịa bề mặt đầu vào** mà nguồn không có.
// 🔴 GAP 4 — **Một ngày ghi vào BA chỗ**: header `ApprovedDate1 = ApprovedDate2 = f.ApprovedDate`
//    (cùng MỘT giá trị vào **cả hai** cột), và **MỌI dòng** của SO (`update … on t.SOCode = f.SOCode`,
//    **không** lọc theo Model/Spec/Color). Port cũ để client gửi hai ngày khác nhau và khớp dòng theo bộ ba.
// 🔴 GAP 5 — **Log ghi VÔ ĐIỀU KIỆN** cho mọi SO/mọi dòng đụng tới; port cũ tự chế điều kiện
//    "chỉ ghi khi có thay đổi" ⇒ mất vết những lần lưu-không-đổi (chính là thứ nhật ký hỗ trợ cần).
// ⚠️ NỢ CÓ NHÃN — hậu xử lý `DepositDutyEndDate` (`:20208-20255`): nguồn tính lại "ngày ĐL cam kết thanh
//    toán hết cọc" bằng lịch làm việc (`Mst_Calendar`, hàm `dbo.f_WorkingDate_Get_01`, tham số
//    `TConst.HTCParamCode.Calendar_DepositDuty_DayT`) rồi **PostCheck** báo lỗi nếu còn dòng NULL.
//    MiniHTC chưa có tầng lịch làm việc ⇒ **KHÔNG đoán công thức**, để nguyên và ghi nợ.
app.MapPost("/api/salesorders/support-update", async (List<SoSupportUpdDto> dto, AppDbContext db,
    ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var rows = (dto ?? new()).Where(x => !string.IsNullOrWhiteSpace(x.SOCode)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Bảng đơn hàng cần sửa ngày duyệt đang rỗng." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;

    var codes = rows.Select(x => x.SOCode.Trim().ToUpperInvariant()).Distinct().ToList();
    var orders = await db.SalesOrders.Where(o => o.OrgId == t.OrgId && codes.Contains(o.SoCode)).ToListAsync();

    // Nguồn kiểm TỪNG DÒNG trong cùng transaction rồi mới ghi cả lô ⇒ validate hết trước.
    foreach (var x in rows)
    {
        var code = x.SOCode.Trim().ToUpperInvariant();
        // `..._SOCodeNotFound`
        if (!orders.Any(o => o.SoCode == code))
            return Results.BadRequest(new { error = $"Không tìm thấy đơn hàng {code}.", guard = "Ord_SalesOrder_UpdateMulti_SOCodeNotFound" });
        // `..._ApprovedDateEmpty` — ngày duyệt BẮT BUỘC (hai guard cùng họ cho cọc/đến hạn đã bị comment).
        if (x.ApprovedDate is null)
            return Results.BadRequest(new { error = $"Đơn {code}: thiếu ngày duyệt (ApprovedDate).", guard = "Ord_SalesOrder_UpdateMulti_ApprovedDateEmpty" });
    }

    var orderIds = orders.Select(o => o.Id).ToList();
    var lines = await db.SalesOrderLines.Where(l => l.OrgId == t.OrgId && orderIds.Contains(l.SalesOrderId)).ToListAsync();

    int headersUpdated = 0, linesUpdated = 0, headerLogs = 0, lineLogs = 0;
    foreach (var x in rows)
    {
        var code = x.SOCode.Trim().ToUpperInvariant();
        var o = orders.First(z => z.SoCode == code);
        var newDate = x.ApprovedDate!.Value;

        // `#tblOrd_SalesOrderOld` — chụp giá trị cũ TỪ BẢNG THẬT, trước khi update.
        var old1 = o.Approved1At; var old2 = o.Approved2At;
        // `ClauseSet`: LogLUDateTime · LogLUBy · ApprovedDate1 = ApprovedDate2 = f.ApprovedDate.
        o.Approved1At = newDate; o.Approved2At = newDate;
        headersUpdated++;

        // Log đầu đơn — VÔ ĐIỀU KIỆN, không phụ thuộc "có đổi hay không".
        db.OrdSalesOrderSupportLogs.Add(new OrdSalesOrderSupportLog
        {
            OrgId = t.OrgId, SOCode = code, UpdDTime = now, UpdBy = who, DealerCode = o.DealerCode,
            ApprovedDate1Old = old1, ApprovedDate1 = o.Approved1At,
            ApprovedDate2Old = old2, ApprovedDate2 = o.Approved2At,
            LogLUDateTime = now, LogLUBy = who
        });
        headerLogs++;

        // `update Ord_SalesOrderDetail … on t.SOCode = f.SOCode` — MỌI dòng của SO, không lọc Model/Spec/Color.
        foreach (var l in lines.Where(z => z.SalesOrderId == o.Id))
        {
            // `#tblOrd_SalesOrderDetailOld` giữ cả 4 mốc, nhưng `ClauseSet` chỉ ghi `ApprovedDate`;
            // ba mốc kia vào log với Old == New (nguồn chụp lại sau update, chúng không đổi).
            var oldApproved = l.ApprovedDate;
            l.ApprovedDate = newDate;
            linesUpdated++;
            db.OrdSalesOrderDetailSupportLogs.Add(new OrdSalesOrderDetailSupportLog
            {
                OrgId = t.OrgId, SOCode = code, UpdDTime = now, UpdBy = who,
                ModelCode = l.ModelCode, SpecCode = l.SpecCode ?? "", ColorCode = l.ColorCode ?? "",
                ApprovedDateOld = oldApproved, ApprovedDate = l.ApprovedDate,
                DepositDutyEndDateOld = null, DepositDutyEndDate = null,
                GrtEndDateOld = null, GrtEndDate = null,
                CarDueDateOld = null, CarDueDate = null,
                LogLUDateTime = now, LogLUBy = who
            });
            lineLogs++;
        }
    }
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        orders = codes.Count, headersUpdated, linesUpdated, headerLogs, lineLogs,
        columnsWritten = new
        {
            header = new[] { "ApprovedDate1", "ApprovedDate2", "LogLUDateTime", "LogLUBy" },
            detail = new[] { "ApprovedDate", "LogLUDateTime", "LogLUBy" }
        },
        oneDateThreePlaces = "MỘT ApprovedDate đầu vào ghi vào ApprovedDate1 + ApprovedDate2 của đầu đơn VÀ ApprovedDate của MỌI dòng.",
        logRule = "Log ghi VÔ ĐIỀU KIỆN (nguồn không có điều kiện 'chỉ khi đổi').",
        debt = "NỢ: hậu xử lý DepositDutyEndDate theo lịch làm việc (Mst_Calendar + f_WorkingDate_Get_01 + tham số Calendar_DepositDuty_DayT) và PostCheck 'còn dòng NULL thì báo lỗi' — MiniHTC chưa có tầng lịch, KHÔNG đoán công thức."
    });
}).RequireAuthorization();

app.MapGet("/api/salesorders/{so}/support-history", async (string so, AppDbContext db, ITenantContext t) =>
{
    so = so.Trim().ToUpperInvariant();
    var header = await db.OrdSalesOrderSupportLogs.Where(x => x.OrgId == t.OrgId && x.SOCode == so)
        .OrderByDescending(x => x.Id).Select(x => new { x.UpdDTime, x.UpdBy, x.DealerCode,
            x.ApprovedDate1Old, x.ApprovedDate1, x.ApprovedDate2Old, x.ApprovedDate2,
            x.LogLUDateTime, x.LogLUBy }).ToListAsync();
    var lines = await db.OrdSalesOrderDetailSupportLogs.Where(x => x.OrgId == t.OrgId && x.SOCode == so)
        .OrderByDescending(x => x.Id).Select(x => new { x.UpdDTime, x.UpdBy, x.ModelCode, x.SpecCode, x.ColorCode,
            x.ApprovedDateOld, x.ApprovedDate, x.DepositDutyEndDateOld, x.DepositDutyEndDate,
            x.GrtEndDateOld, x.GrtEndDate, x.CarDueDateOld, x.CarDueDate,
            x.LogLUDateTime, x.LogLUBy }).ToListAsync();
    return Results.Ok(new { soCode = so, headerCount = header.Count, lineCount = lines.Count, header, lines });
}).RequireAuthorization();

// ===== #148: CẤU HÌNH BẬT/TẮT JOB NỀN (Mst_SettingRunJob) =====
// Nguồn: DataWH/BizHTC.zTemp.cs (csproj 276) tại 56576. Chỉ có ở WS 64-bit (_Get / _Save).
app.MapGet("/api/settingrunjobs", async (AppDbContext db, ITenantContext t, string? flagActive) =>
{
    var q = db.MstSettingRunJobs.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(flagActive)) q = q.Where(x => x.FlagActive == flagActive);
    var items = await q.OrderBy(x => x.JobCode).Select(x => new {
        x.JobCode, x.JobName, x.FlagActive, x.LogLUDateTime, x.LogLUBy }).ToListAsync();
    return Results.Ok(new { count = items.Count, active = items.Count(i => i.FlagActive == "1"), items });
}).RequireAuthorization();

// UPSERT theo JobCode (nguồn chỉ có một hàm _Save cho cả thêm lẫn sửa).
app.MapPost("/api/settingrunjobs", async (SettingRunJobDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.JobCode ?? "").Trim().ToUpperInvariant();
    if (code.Length == 0) return Results.BadRequest(new { error = "Thiếu mã job." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var now = DateTime.Now;
    var x = await db.MstSettingRunJobs.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.JobCode == code);
    var created = x is null;
    if (x is null) { x = new MstSettingRunJob { OrgId = t.OrgId, JobCode = code }; db.MstSettingRunJobs.Add(x); }
    x.JobName = dto.JobName ?? x.JobName;
    x.FlagActive = (dto.FlagActive ?? "1").Trim() == "0" ? "0" : "1";
    x.LogLUDateTime = now; x.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { x.JobCode, x.JobName, x.FlagActive, created });
}).RequireAuthorization();

app.MapPost("/api/settingrunjobs/{code}/toggle", async (string code, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    code = code.Trim().ToUpperInvariant();
    var x = await db.MstSettingRunJobs.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.JobCode == code);
    if (x is null) return Results.NotFound(new { code });
    x.FlagActive = x.FlagActive == "1" ? "0" : "1";
    x.LogLUDateTime = DateTime.Now; x.LogLUBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    await db.SaveChangesAsync();
    return Results.Ok(new { x.JobCode, x.FlagActive });
}).RequireAuthorization();

// ===== #147: TỈ LỆ DUYỆT ĐƠN TỐI ĐA THEO (ĐẠI LÝ, DÒNG XE) — Mst_SORateMax =====
// Nguồn: DMS40/0.01.Master.cs (csproj 122) — Mst_SORateMax_AddMultiX (6936) ghi tại 7120.
// 🔴 Chỉ có ở WS 64-bit. Nguồn CHỈ THÊM MỚI, không có hàm sửa/xoá.
app.MapGet("/api/soratemaxes", async (AppDbContext db, ITenantContext t, string? dealer, string? model, string? flagActive) =>
{
    var q = db.MstSoRateMaxes.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(x => x.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(model)) q = q.Where(x => x.ModelCode == model);
    if (!string.IsNullOrWhiteSpace(flagActive)) q = q.Where(x => x.FlagActive == flagActive);
    var items = await q.OrderBy(x => x.DealerCode).ThenBy(x => x.ModelCode).Take(2000).Select(x => new {
        x.DealerCode, x.ModelCode, x.Rate, x.FlagActive, x.LogLUDateTime, x.LogLUBy }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Thêm hàng loạt — port 1:1 `Mst_SORateMax_AddMulti`.
// Ba guard của nguồn đã port: (1) bảng đầu vào phải có dòng; (2) cặp (đại lý, model) PHẢI CHƯA tồn tại
// (`CheckDB(…, TConst.Flag.No)`); (3) `Rate` **không được âm** — nguồn KHÔNG chặn cận trên.
// `FlagActive` nguồn ép cứng "1".
app.MapPost("/api/soratemaxes", async (SoRateMaxAddDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var lines = (dto.Lines ?? new()).Where(x => !string.IsNullOrWhiteSpace(x.DealerCode) && !string.IsNullOrWhiteSpace(x.ModelCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Chưa có dòng nào để thêm." });
    var neg = lines.FirstOrDefault(x => x.Rate < 0);
    if (neg is not null) return Results.BadRequest(new { error = $"Tỉ lệ của {neg.DealerCode}/{neg.ModelCode} không được âm." });
    var dupe = lines.GroupBy(x => (x.DealerCode.Trim().ToUpperInvariant(), x.ModelCode.Trim().ToUpperInvariant()))
        .FirstOrDefault(g => g.Count() > 1);
    if (dupe.Key.Item1 is not null) return Results.BadRequest(new { error = $"Cặp {dupe.Key.Item1}/{dupe.Key.Item2} bị trùng trong danh sách gửi lên." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var now = DateTime.Now;
    var exists = new List<string>();
    foreach (var l in lines)
    {
        var dealer = l.DealerCode.Trim().ToUpperInvariant();
        var model = l.ModelCode.Trim().ToUpperInvariant();
        if (await db.MstSoRateMaxes.AnyAsync(x => x.OrgId == t.OrgId && x.DealerCode == dealer && x.ModelCode == model))
        { exists.Add($"{dealer}/{model}"); continue; }
        db.MstSoRateMaxes.Add(new MstSoRateMax { OrgId = t.OrgId, DealerCode = dealer, ModelCode = model,
            Rate = l.Rate, FlagActive = "1", LogLUDateTime = now, LogLUBy = who });
    }
    if (exists.Count == lines.Count)
        return Results.Conflict(new { error = "Tất cả các cặp gửi lên đều đã tồn tại — nguồn chỉ cho THÊM MỚI.", exists });
    await db.SaveChangesAsync();
    return Results.Ok(new { added = lines.Count - exists.Count, skippedExisting = exists });
}).RequireAuthorization();

// ===== #146: HẠN MỨC PHÂN BỔ THEO SPEC (Mng_Quota + Mng_QuotaHis) =====
// Nguồn: DMS40/0.01.Master.cs (csproj 122) — Mng_Quota_UpdMultiX_New20230306 (6158).
// 🔴 CHỈ có ở WS 64-bit (_biz.Mng_Quota_Get, _biz.Mng_Quota_UpdMulti); WS 32-bit không có hàm nào.
// Khoá kép (DealerCode, SpecCode). Nguồn CHỈ SỬA dòng đã có (guard CheckDB với Flag.Yes), không thêm mới.
app.MapGet("/api/mngquotas", async (AppDbContext db, ITenantContext t, string? dealer, string? spec, string? flagActive) =>
{
    var q = db.MngQuotas.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(x => x.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(spec)) q = q.Where(x => x.SpecCode == spec);
    if (!string.IsNullOrWhiteSpace(flagActive)) q = q.Where(x => x.FlagActive == flagActive);
    var items = await q.OrderBy(x => x.DealerCode).ThenBy(x => x.SpecCode).Take(2000).Select(x => new {
        x.DealerCode, x.SpecCode, x.QtyQuota, x.FlagActive, x.UpdateDTime, x.UpdateBy,
        x.LogLUDateTime, x.LogLUBy }).ToListAsync();
    return Results.Ok(new { count = items.Count, totalQty = items.Sum(i => i.QtyQuota), items });
}).RequireAuthorization();

// Tạo dòng hạn mức (nguồn không có hàm thêm mới — bổ sung để dữ liệu có thể khởi tạo được;
// mọi thao tác SỬA vẫn đi qua /api/mngquotas/upd-multi đúng như nguồn).
app.MapPost("/api/mngquotas", async (MngQuotaLineDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var dealer = (dto.DealerCode ?? "").Trim().ToUpperInvariant();
    var spec = (dto.SpecCode ?? "").Trim().ToUpperInvariant();
    if (dealer.Length == 0 || spec.Length == 0) return Results.BadRequest(new { error = "Cần cả DealerCode và SpecCode (khoá kép)." });
    if (await db.MngQuotas.AnyAsync(x => x.OrgId == t.OrgId && x.DealerCode == dealer && x.SpecCode == spec))
        return Results.Conflict(new { error = $"Hạn mức {dealer}/{spec} đã tồn tại — dùng /api/mngquotas/upd-multi để sửa." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var now = DateTime.Now;
    db.MngQuotas.Add(new MngQuota { OrgId = t.OrgId, DealerCode = dealer, SpecCode = spec, QtyQuota = dto.QtyQuota,
        FlagActive = "1", UpdateDTime = now, UpdateBy = who, LogLUDateTime = now, LogLUBy = who });
    await db.SaveChangesAsync();
    return Results.Ok(new { dealer, spec, dto.QtyQuota });
}).RequireAuthorization();

// Sửa hàng loạt — port 1:1 `Mng_Quota_UpdMultiX_New20230306`.
// 🔴 Ba điểm của nguồn đã port nguyên:
//   1) guard `Mng_Quota_CheckDB_New20230306(..., TConst.Flag.Yes)` ⇒ dòng PHẢI đã tồn tại, không tự thêm.
//   2) lệnh update LUÔN ép `FlagActive = '1'` ⇒ mọi lần sửa đều **BẬT LẠI** dòng đang tắt.
//   3) `QtyQuota` chỉ được ghi khi cờ `bUpd_QtyQuota` bật (ở đây là `UpdQtyQuota`).
// Sau khi update mới chụp `Mng_QuotaHis` ⇒ lịch sử lưu giá trị **SAU** thay đổi, và
// `VesionCode` = chính chuỗi `LogLUDateTime` của lượt sửa.
app.MapPost("/api/mngquotas/upd-multi", async (MngQuotaUpdDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var lines = (dto.Lines ?? new()).Where(x => !string.IsNullOrWhiteSpace(x.DealerCode) && !string.IsNullOrWhiteSpace(x.SpecCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Không có dòng nào để sửa." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var now = DateTime.Now;
    var version = now.ToString("yyyy-MM-dd HH:mm:ss");   // nguồn dùng chính chuỗi LogLUDateTime làm VesionCode
    var missing = new List<string>(); var changed = 0;
    foreach (var l in lines)
    {
        var dealer = l.DealerCode.Trim().ToUpperInvariant();
        var spec = l.SpecCode.Trim().ToUpperInvariant();
        var row = await db.MngQuotas.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == dealer && x.SpecCode == spec);
        if (row is null) { missing.Add($"{dealer}/{spec}"); continue; }
        row.LogLUDateTime = now; row.LogLUBy = who;
        row.UpdateDTime = now; row.UpdateBy = who;
        row.FlagActive = "1";                                   // nguồn ép cứng
        if (dto.UpdQtyQuota) row.QtyQuota = l.QtyQuota;
        // ảnh chụp SAU update
        db.MngQuotaHiss.Add(new MngQuotaHis { OrgId = t.OrgId, VesionCode = version, DealerCode = dealer,
            SpecCode = spec, QtyQuota = row.QtyQuota, FlagActive = row.FlagActive,
            FunctionName = "Mng_Quota_UpdMultiX", UpdateDTime = now, UpdateBy = who,
            LogLUDateTime = now, LogLUBy = who });
        changed++;
    }
    if (missing.Count > 0 && changed == 0)
        return Results.BadRequest(new { error = "Không dòng nào tồn tại để sửa.", missing });
    await db.SaveChangesAsync();
    return Results.Ok(new { version, changed, missing });
}).RequireAuthorization();

app.MapGet("/api/mngquotas/history", async (AppDbContext db, ITenantContext t, string? dealer, string? spec, string? version) =>
