app.MapPost("/api/mstquotas", async (MstQuotaDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var dealer = (dto.DealerCode ?? "").Trim().ToUpperInvariant();
    var code = (dto.QuotaCode ?? "").Trim().ToUpperInvariant();
    if (dealer.Length == 0 || code.Length == 0) return Results.BadRequest(new { error = "Cần cả DealerCode và QuotaCode." });
    if (dto.SOApprDateFrom is not null && dto.SOApprDateTo is not null && dto.SOApprDateTo < dto.SOApprDateFrom)
        return Results.BadRequest(new { error = "Ngày kết thúc nhỏ hơn ngày bắt đầu." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var now = DateTime.Now;
    var h = await db.Quotas.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == dealer && x.QuotaCode == code);
    var created = h is null;
    if (h is null) { h = new Quota { OrgId = t.OrgId, DealerCode = dealer, QuotaCode = code }; db.Quotas.Add(h); }
    h.QuotaName = dto.QuotaName; h.ModelCondition = dto.ModelCondition; h.ModelPromotion = dto.ModelPromotion;
    h.SpecCodeCondition = dto.SpecCodeCondition; h.SpecCodePromotion = dto.SpecCodePromotion;
    h.QtyCondition = dto.QtyCondition; h.QtyPromotion = dto.QtyPromotion;
    h.SOApprDateFrom = dto.SOApprDateFrom; h.SOApprDateTo = dto.SOApprDateTo;
    // SOApprDateToInit: chỉ đặt LẦN ĐẦU — về sau giữ nguyên để còn biết hạn gốc trước khi gia hạn.
    if (created) h.SOApprDateToInit = dto.SOApprDateTo;
    h.FlagActive = (dto.FlagActive ?? "1").Trim() == "0" ? "0" : "1";
    h.LogLUDateTime = now; h.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { dealer, code, created, h.SOApprDateToInit });
}).RequireAuthorization();

// ===== #145: DANH MỤC MÀU XE + SPEC ÁP DỤNG (Mst_CarColor + Mst_CarColorSpec) =====
// Nguồn: BizHTC.MasterData.cs (csproj 115) — Mst_CarColor_Save (3382) → _SaveX (3552).
// 🔴 TWIN "đọc ở cả hai, GHI chỉ 64-bit": WS 32-bit chỉ có _Get_New20181119; _Save chỉ ở WS 64-bit.
// Khoá nghiệp vụ là CẶP (ModelCode, ColorCode).
app.MapGet("/api/carcolors", async (AppDbContext db, ITenantContext t, string? model, string? color, string? flagActive) =>
{
    var q = db.MstCarColors.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(model)) q = q.Where(x => x.ModelCode == model);
    if (!string.IsNullOrWhiteSpace(color)) q = q.Where(x => x.ColorCode == color);
    if (!string.IsNullOrWhiteSpace(flagActive)) q = q.Where(x => x.FlagActive == flagActive);
    var items = await q.OrderBy(x => x.ModelCode).ThenBy(x => x.ColorCode).Take(1000).Select(x => new {
        x.ModelCode, x.ColorCode, x.ColorExtType, x.ColorExtCode, x.ColorExtName, x.ColorExtNameVN,
        x.ColorIntCode, x.ColorIntName, x.ColorIntNameVN, x.ColorFee, x.FlagActive, x.Remark,
        x.LogLUDateTime, x.LogLUBy,
        specs = db.MstCarColorSpecs.Count(s => s.OrgId == t.OrgId && s.ModelCode == x.ModelCode && s.ColorCode == x.ColorCode) }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapGet("/api/carcolors/{model}/{color}", async (string model, string color, AppDbContext db, ITenantContext t) =>
{
    model = model.Trim().ToUpperInvariant(); color = color.Trim().ToUpperInvariant();
    var h = await db.MstCarColors.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ModelCode == model && x.ColorCode == color);
    if (h is null) return Results.NotFound(new { model, color });
    var specs = await db.MstCarColorSpecs.Where(x => x.OrgId == t.OrgId && x.ModelCode == model && x.ColorCode == color)
        .OrderBy(x => x.SpecCode).Select(x => new { x.SpecCode, x.LogLUDateTime, x.LogLUBy }).ToListAsync();
    return Results.Ok(new { header = new { h.ModelCode, h.ColorCode, h.ColorExtType, h.ColorExtCode,
        h.ColorExtName, h.ColorExtNameVN, h.ColorIntCode, h.ColorIntName, h.ColorIntNameVN, h.ColorFee,
        h.FlagActive, h.Remark, h.LogLUDateTime, h.LogLUBy }, count = specs.Count, specs });
}).RequireAuthorization();

// Lưu (UPSERT theo cặp khoá) — nguồn `_SaveX` dùng đúng một hàm cho cả thêm lẫn sửa:
//   `Mst_CarColor_CheckDB` gọi với hai tham số lọc RỖNG ⇒ chỉ để BIẾT đã tồn tại hay chưa,
//   không chặn; chưa có thì thêm, có rồi thì sửa.
// 🔴 Quy ước lưới WinForm đã port: dòng spec có `SpecCode` **RỖNG** ⇒ `bIsDeleteSpec = true`
//    (BizHTC.MasterData.cs:3808-3812) — tức gửi lên một dòng trống nghĩa là **XOÁ SẠCH spec**
//    của cặp (Model, Color), không phải bỏ qua dòng đó.
app.MapPost("/api/carcolors", async (CarColorDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var model = (dto.ModelCode ?? "").Trim().ToUpperInvariant();
    var color = (dto.ColorCode ?? "").Trim().ToUpperInvariant();
    if (model.Length == 0 || color.Length == 0) return Results.BadRequest(new { error = "Cần cả ModelCode và ColorCode (khoá kép)." });
    if (dto.Specs is null) return Results.BadRequest(new { error = "Thiếu bảng Mst_CarColorSpec (nguồn bắt buộc có, kể cả rỗng)." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var now = DateTime.Now;

    var rawSpecs = dto.Specs.Select(x => (x.SpecCode ?? "").Trim().ToUpperInvariant()).ToList();
    var blankSpec = rawSpecs.Any(x => x.Length == 0);   // quy ước "dòng trống = xoá sạch spec"
    var specs = rawSpecs.Where(x => x.Length > 0).Distinct().ToList();
    if (!blankSpec && specs.Count == 0) return Results.BadRequest(new { error = "Phải có ít nhất 1 spec, hoặc gửi 1 dòng trống để xoá hết spec." });

    var h = await db.MstCarColors.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ModelCode == model && x.ColorCode == color);
    var created = h is null;
    if (h is null) { h = new MstCarColor { OrgId = t.OrgId, ModelCode = model, ColorCode = color }; db.MstCarColors.Add(h); }
    h.ColorExtType = dto.ColorExtType; h.ColorExtCode = dto.ColorExtCode; h.ColorExtName = dto.ColorExtName;
    h.ColorExtNameVN = dto.ColorExtNameVN; h.ColorIntCode = dto.ColorIntCode; h.ColorIntName = dto.ColorIntName;
    h.ColorIntNameVN = dto.ColorIntNameVN; h.ColorFee = dto.ColorFee;
    h.FlagActive = (dto.FlagActive ?? "1").Trim() == "0" ? "0" : "1";
    h.Remark = dto.Remark; h.LogLUDateTime = now; h.LogLUBy = who;

    // nguồn: xoá sạch spec của cặp khoá rồi ghi lại (BizHTC.MasterData.cs:3875-3893).
    db.MstCarColorSpecs.RemoveRange(await db.MstCarColorSpecs
        .Where(x => x.OrgId == t.OrgId && x.ModelCode == model && x.ColorCode == color).ToListAsync());
    if (!blankSpec)
        foreach (var s in specs)
            db.MstCarColorSpecs.Add(new MstCarColorSpec { OrgId = t.OrgId, ModelCode = model, ColorCode = color,
                SpecCode = s, LogLUDateTime = now, LogLUBy = who });
    await db.SaveChangesAsync();
    return Results.Ok(new { model, color, created, specs = blankSpec ? 0 : specs.Count, specsCleared = blankSpec });
}).RequireAuthorization();

// Xoá: nguồn dùng CÙNG hàm _SaveX với cờ FlagIsDelete="1" — xoá cả spec lẫn bản ghi màu.
// 🔴 Nguồn: chưa tồn tại + đang xoá ⇒ `goto MyCodeLabel_Done` (THÀNH CÔNG, không báo lỗi).
//    Port đúng ý đó: trả 200 idempotent thay vì 404.
app.MapDelete("/api/carcolors/{model}/{color}", async (string model, string color, AppDbContext db, ITenantContext t) =>
{
    model = model.Trim().ToUpperInvariant(); color = color.Trim().ToUpperInvariant();
    var h = await db.MstCarColors.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ModelCode == model && x.ColorCode == color);
    if (h is null) return Results.Ok(new { model, color, deleted = false, note = "Không tồn tại — nguồn coi là thành công." });
    db.MstCarColorSpecs.RemoveRange(await db.MstCarColorSpecs
        .Where(x => x.OrgId == t.OrgId && x.ModelCode == model && x.ColorCode == color).ToListAsync());
    db.MstCarColors.Remove(h);
    await db.SaveChangesAsync();
    return Results.Ok(new { model, color, deleted = true });
}).RequireAuthorization();

// ===== #B93 TRA MÀU XE + BẢNG GHÉP MÀU↔SPEC — `Mst_CarColorSpec_Get` =====
// Trace LIVE: WS → `_biz.Mst_CarColorSpec_Get` (`BizHTC.MasterData.cs:3048`, thân
//   **`Mst_CarColorSpec_GetX`** `:3175`). 3B đo thật, **khớp cả 2 máy**: start=3175 md5
//   `59119c3bb13023020b60ee1569de7312`.
// 🔴 **MỘT lần gọi trả tới HAI bảng, và KHUNG PHÂN TRANG là `Mst_CarColor`** — không phải bảng ghép:
//    `#tbl_Mst_CarColor_Draft` đánh số `identity(bigint,0,1) MyIdxSeq` **trên `Mst_CarColor`**, cắt
//    trang, rồi **hai** khối `zOut` bám vào cùng `#tbl_Mst_CarColor_Filter`. ⇒ **phân trang theo MÀU**,
//    một màu có nhiều spec thì bảng ghép trả **nhiều dòng hơn** số bản ghi trang. Đừng phân trang
//    trên bảng ghép.
// 🔴 **Hai cờ `bGet_*` độc lập**: mặc định cả hai khối là `"-- Nothing."`; chỉ khi bật mới **chạy
//    câu truy vấn tương ứng** (cùng khuôn `strIsGetDetail` ở #B90 — **không** phải "ẩn cột").
// 🔴 **Bảng ghép nối bằng `inner join`, nhưng lấy TÊN MÀU bằng `left join`**:
//      `inner join Mst_CarColorSpec mccs on t.ModelCode = mccs.ModelCode and t.ColorCode = mccs.ColorCode`
//      `left  join Mst_CarColor      mcc  on mccs.ModelCode = mcc.ModelCode and mccs.ColorCode = mcc.ColorCode`
//    ⇒ dòng ghép **không có** bản ghi màu vẫn **giữ lại**, chỉ thiếu tên (`mcc_*` = null).
//    Cột tên được **đổi bí danh có tiền tố `mcc_`** (`mcc_ColorExtName`, `mcc_ColorIntNameVN`,
//    `mcc_FlagActive`…) để **không đè** cột cùng tên của `mccs.*`. Port giữ đúng tiền tố.
// 🔴 **RBAC biến thể 2 — ca thứ 12**: `@strBUPatternOfUser` được bind nhưng danh mục màu **không có
//    cột đại lý** để lọc ⇒ tham số **không dùng đến**. Tác hại ~0 (dữ liệu chung), ghi để đủ mẫu.
app.MapGet("/api/carcolorspecs", async (
    AppDbContext db, ITenantContext t, int? recordStart, int? recordCount,
    string? modelCode, string? colorCode, string? getCarColor, string? getCarColorSpec) =>
{
    var start = Math.Max(0, recordStart ?? 0);
    var count = Math.Clamp(recordCount ?? 200, 1, 1000);
    var wantColor = (getCarColor ?? "1").Trim() == "1";
    var wantSpec = (getCarColorSpec ?? "1").Trim() == "1";

    // `#tbl_Mst_CarColor_Draft` — KHUNG phân trang là `Mst_CarColor`.
    var q = db.MstCarColors.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(modelCode)) q = q.Where(c => c.ModelCode == modelCode.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(colorCode)) q = q.Where(c => c.ColorCode == colorCode.Trim().ToUpperInvariant());
    var draft = await q.OrderBy(c => c.ModelCode).ThenBy(c => c.ColorCode).ToListAsync();
    var myCount = draft.Count;                       // `MyCount` đếm TRƯỚC khi cắt trang
    var page = draft.Skip(start).Take(count).ToList();
    var keys = page.Select(c => (c.ModelCode, c.ColorCode)).ToHashSet();

    object? carColors = null;
    if (wantColor)
        carColors = page.Select(c => new
        {
            mccModelCode = c.ModelCode, mccColorCode = c.ColorCode,
            mccColorExtCode = c.ColorExtCode, mccColorExtName = c.ColorExtName, mccColorExtNameVN = c.ColorExtNameVN,
            mccColorIntCode = c.ColorIntCode, mccColorIntName = c.ColorIntName, mccColorIntNameVN = c.ColorIntNameVN
        }).ToList();

    object? carColorSpecs = null;
    if (wantSpec)
    {
        var links = await db.MstCarColorSpecs.Where(s => s.OrgId == t.OrgId).ToListAsync();
        // `inner join` với trang màu; tên màu lấy bằng `left join` (thiếu thì để null).
        var colorByKey = page.ToDictionary(c => (c.ModelCode, c.ColorCode));
        carColorSpecs = links.Where(s => keys.Contains((s.ModelCode, s.ColorCode)))
            .OrderBy(s => s.ModelCode, StringComparer.Ordinal)
            .ThenBy(s => s.ColorCode, StringComparer.Ordinal)
            .ThenBy(s => s.SpecCode, StringComparer.Ordinal)
            .Select(s =>
            {
                colorByKey.TryGetValue((s.ModelCode, s.ColorCode), out var mcc);
                return new
                {
                    mccsModelCode = s.ModelCode, mccsColorCode = s.ColorCode, mccsSpecCode = s.SpecCode,
                    mccsLogLUDateTime = s.LogLUDateTime, mccsLogLUBy = s.LogLUBy,
                    // Tiền tố `mcc_` của nguồn — cố ý để KHÔNG đè cột cùng tên của `mccs.*`.
                    mcc_ColorExtName = mcc?.ColorExtName, mcc_ColorExtNameVN = mcc?.ColorExtNameVN,
                    mcc_ColorIntName = mcc?.ColorIntName, mcc_ColorIntNameVN = mcc?.ColorIntNameVN,
                    mcc_FlagActive = mcc?.FlagActive
                };
            }).ToList();
    }

    return Results.Ok(new
    {
        myCount, recordStart = start, recordCount = count,
        getCarColor = wantColor, getCarColorSpec = wantSpec,
        carColors, carColorSpecs,
        pagingFrameNote = "MOT lan goi tra toi HAI bang, va KHUNG PHAN TRANG la Mst_CarColor - KHONG phai bang ghep: #tbl_Mst_CarColor_Draft danh so identity(bigint,0,1) MyIdxSeq TREN Mst_CarColor, cat trang, roi HAI khoi zOut bam vao cung #tbl_Mst_CarColor_Filter. => phan trang THEO MAU; mot mau co nhieu spec thi bang ghep tra NHIEU DONG HON so ban ghi trang. Dung phan trang tren bang ghep.",
        twoFlagsNote = "Hai co bGet_* DOC LAP: mac dinh ca hai khoi la '-- Nothing.'; chi khi bat moi CHAY cau truy van tuong ung (cung khuon strIsGetDetail o #B90 - KHONG phai 'an cot').",
        joinShapeNote = "Bang ghep noi bang INNER JOIN (Mst_CarColorSpec theo ModelCode+ColorCode) nhung TEN MAU lay bang LEFT JOIN (Mst_CarColor) => dong ghep KHONG CO ban ghi mau van GIU LAI, chi thieu ten (mcc_* = null).",
        aliasPrefixNote = "Cot ten mau duoc doi bi danh co TIEN TO 'mcc_' (mcc_ColorExtName, mcc_ColorIntNameVN, mcc_FlagActive...) de KHONG DE cot cung ten cua mccs.*. Port giu dung tien to.",
        rbacHole = "LO HONG RBAC - bien the 2 (khai ma khong dung), ca thu 12: @strBUPatternOfUser duoc bind nhung danh muc mau KHONG CO cot dai ly de loc => tham so khong dung den. Tac hai ~0 (du lieu chung), ghi de DU MAU."
    });
}).RequireAuthorization();

// ===== #B94 XE ĐÃ PDI XONG, CHỜ NHẬP KHO — `HTMV_PDIStorageGet_New20181115` =====
// Trace LIVE: WS → `_biz.HTMV_PDIStorageGet_New20181115` (`BizHTC.HTMV.cs:950`).
//   3B đo thật, **khớp cả 2 máy**: start=950 md5 `30e7adb0646c3adfc88947de8cd3cc4d`.
// 🔴 **HAI ĐIỀU KIỆN TRẠNG THÁI VIẾT CỨNG TRONG SQL, KHÔNG PHẢI THAM SỐ** (`:1049-1050`):
//      `and ((scd.PDIDtlStatus     IN ('F')))`   — dòng PDI **đã hoàn tất**
//      `and ((scd.PDIStorageStatus IN ('P')))`   — nhưng **CHƯA vào kho** (còn chờ)
//    ⇒ Đây **chính là nghiệp vụ của màn**: "xe PDI xong, chờ nhập kho". Port bỏ hai điều kiện này
//      là trả về **cả xe chưa PDI** — sai hẳn danh sách, không có lỗi nào báo.
//    🔗 **Nối với #B81**: `ContractPackingListApproved` đặt `PDIStorageStatus = 'F'` cho mọi VIN của
//      packing list ⇒ **duyệt packing list hợp đồng sẽ LOẠI xe khỏi danh sách này**. Hai màn ăn khớp
//      qua đúng một cột.
// 🔴 **`left join HTMV_PDIDtl` NHƯNG `where` lọc theo `scd.PDIDtlStatus`** ⇒ **inner join thực chất**:
//    phiếu PDI **không có dòng nào** bị loại hẳn (cùng khuôn #B47/#B70/#B72).
// 🔴 **`mcc.ColorExtNameVN + '/' + mcc.ColorIntNameVN as Color_Vn_Combined`** — nối chuỗi trong SQL
//    Server: **một vế NULL ⇒ CẢ CHUỖI NULL**. Port dùng nội suy `$"{a}/{b}"` sẽ ra `"/Đen"` thay vì
//    `null` — khác nguồn. Đã giữ đúng ngữ nghĩa NULL-lan-truyền.
// 🔴 Ba `left join` làm giàu (`Car_VIN.ActualSpec`, `Mst_CarSpec.SpecDescription`, `Mst_CarColor`)
//    là **left thật** — thiếu danh mục thì để trống, **không** loại dòng.
// 🔴 **RBAC biến thể 2 — ca thứ 13**: `@strBUPatternOfUser` bind (`:1029`) nhưng **không** xuất hiện
//    trong bất kỳ mệnh đề `where` nào (mọi `BuildClause` đều dùng `@p…`). ⇒ vô hiệu.
app.MapGet("/api/pdi/storage-pending", async (
    AppDbContext db, ITenantContext t,
    string? pdiNo, string? pdiStatus, string? createdBy, DateTime? createdFrom, DateTime? createdTo,
    string? vin, string? refNo, string? lcTemp, string? specCode, string? modelCode, string? colorCode) =>
{
    var heads = await db.HtmvPdis.Where(h => h.OrgId == t.OrgId).ToListAsync();
    if (!string.IsNullOrWhiteSpace(pdiNo)) heads = heads.Where(h => h.PDINo == pdiNo.Trim()).ToList();
    if (!string.IsNullOrWhiteSpace(pdiStatus)) heads = heads.Where(h => h.Status == pdiStatus.Trim()).ToList();
    if (!string.IsNullOrWhiteSpace(createdBy)) heads = heads.Where(h => h.CreatedBy == createdBy.Trim()).ToList();
    if (createdFrom is not null) heads = heads.Where(h => h.CreatedAt >= createdFrom).ToList();
    if (createdTo is not null) heads = heads.Where(h => h.CreatedAt <= createdTo).ToList();
    var headById = heads.ToDictionary(h => h.Id);

    // 🔴 HAI điều kiện trạng thái VIẾT CỨNG — nghiệp vụ của màn, không phải bộ lọc người dùng.
    var dtls = await db.HtmvPdiDtls
        .Where(d => d.OrgId == t.OrgId && d.PDIDtlStatus == "F" && d.PDIStorageStatus == "P")
        .ToListAsync();
    // `left join HTMV_PDIDtl` + `where scd.PDIDtlStatus…` ⇒ inner join thực chất.
    dtls = dtls.Where(d => headById.ContainsKey(d.HtmvPdiId)).ToList();

    if (!string.IsNullOrWhiteSpace(vin)) dtls = dtls.Where(d => d.VIN == vin.Trim().ToUpperInvariant()).ToList();
    if (!string.IsNullOrWhiteSpace(refNo)) dtls = dtls.Where(d => d.RefNo == refNo.Trim()).ToList();
    if (!string.IsNullOrWhiteSpace(lcTemp)) dtls = dtls.Where(d => d.LCTemp == lcTemp.Trim()).ToList();
    if (!string.IsNullOrWhiteSpace(specCode)) dtls = dtls.Where(d => d.SpecCode == specCode.Trim().ToUpperInvariant()).ToList();
    if (!string.IsNullOrWhiteSpace(modelCode)) dtls = dtls.Where(d => d.ModelCode == modelCode.Trim().ToUpperInvariant()).ToList();
    if (!string.IsNullOrWhiteSpace(colorCode)) dtls = dtls.Where(d => d.ColorCode == colorCode.Trim().ToUpperInvariant()).ToList();

    // Ba left join LÀM GIÀU — thiếu danh mục thì để trống, KHÔNG loại dòng.
    var vins = dtls.Select(d => d.VIN).Distinct().ToList();
    var cars = (await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && vins.Contains(c.VIN))
        .Select(c => new { c.VIN, c.ActualSpec }).ToListAsync())
        .GroupBy(c => c.VIN).ToDictionary(g => g.Key, g => g.First().ActualSpec);
    var specs = (await db.CarSpecs.Where(s => s.OrgId == t.OrgId).Select(s => new { s.SpecCode, s.SpecDesc }).ToListAsync())
        .GroupBy(s => s.SpecCode).ToDictionary(g => g.Key, g => g.First().SpecDesc);
    var colors = (await db.MstCarColors.Where(c => c.OrgId == t.OrgId)
        .Select(c => new { c.ModelCode, c.ColorCode, c.ColorExtNameVN, c.ColorIntNameVN }).ToListAsync())
        .GroupBy(c => (c.ModelCode, c.ColorCode)).ToDictionary(g => g.Key, g => g.First());

    var items = dtls.OrderBy(d => d.VIN, StringComparer.Ordinal).Select(d =>
    {
        colors.TryGetValue((d.ModelCode ?? "", d.ColorCode ?? ""), out var mcc);
        // 🔴 Nối chuỗi SQL Server: MỘT vế NULL ⇒ CẢ CHUỖI NULL.
        string? colorCombined = (mcc?.ColorExtNameVN is null || mcc?.ColorIntNameVN is null)
            ? null : mcc.ColorExtNameVN + "/" + mcc.ColorIntNameVN;
        return new
        {
            scPDINo = headById[d.HtmvPdiId].PDINo,
            scPDIStatus = headById[d.HtmvPdiId].Status,
            scdVIN = d.VIN, scdRefNo = d.RefNo, scdLCTemp = d.LCTemp,
            scdSpecCode = d.SpecCode, scdModelCode = d.ModelCode, scdColorCode = d.ColorCode,
            scdEngineNo = d.EngineNo, scdProductionMonth = d.ProductionMonth,
            scdPDIDtlStatus = d.PDIDtlStatus, scdPDIStorageStatus = d.PDIStorageStatus,
            scdFlagRepair = d.FlagRepair, scdRepairRemark = d.RepairRemark,   // #B95 §12 doc lai
            cvActualSpec = cars.TryGetValue(d.VIN, out var asp) ? asp : null,
            mcsSpecDescription = specs.TryGetValue(d.SpecCode ?? "", out var sd) ? sd : null,
            Color_Vn_Combined = colorCombined
        };
    }).ToList();

    return Results.Ok(new
    {
        count = items.Count, items,
        hardCodedStatusNote = "HAI DIEU KIEN TRANG THAI VIET CUNG TRONG SQL, KHONG PHAI THAM SO: 'scd.PDIDtlStatus IN (F)' (dong PDI DA HOAN TAT) va 'scd.PDIStorageStatus IN (P)' (CHUA vao kho). Day CHINH LA nghiep vu cua man - 'xe PDI xong, cho nhap kho'. Port bo hai dieu kien nay la tra ve CA XE CHUA PDI, sai han danh sach ma khong co loi nao bao.",
        linkToB81Note = "NOI VOI #B81: ContractPackingListApproved dat PDIStorageStatus = 'F' cho MOI VIN cua packing list => duyet packing list hop dong se LOAI xe khoi danh sach nay. Hai man an khop qua dung mot cot.",
        joinShapeNote = "left join HTMV_PDIDtl NHUNG where loc theo scd.PDIDtlStatus => INNER JOIN THUC CHAT: phieu PDI khong co dong nao bi loai han (khuon #B47/#B70/#B72). Ba left join lam giau (Car_VIN.ActualSpec, Mst_CarSpec.SpecDescription, Mst_CarColor) la LEFT THAT - thieu danh muc thi de trong, KHONG loai dong.",
        nullConcatNote = "Color_Vn_Combined = mcc.ColorExtNameVN + '/' + mcc.ColorIntNameVN - noi chuoi SQL Server: MOT VE NULL => CA CHUOI NULL. Port dung noi suy $\"{a}/{b}\" se ra '/Den' thay vi null - KHAC nguon. Da giu dung ngu nghia NULL-lan-truyen.",
        rbacHole = "LO HONG RBAC - bien the 2 (khai ma khong dung), ca thu 13: @strBUPatternOfUser bind (:1029) nhung KHONG xuat hien trong bat ky menh de where nao (moi BuildClause deu dung @p...). => VO HIEU."
    });
}).RequireAuthorization();

// ===== #B95 CẬP NHẬT CỜ SỬA CHỮA CỦA DÒNG PDI — `HTMV_PDIUpdate_New20181115` =====
// Trace LIVE: WS → `_biz.HTMV_PDIUpdate_New20181115` (`BizHTC.HTMV.cs:3064`).
//   3B đo thật, **khớp cả 2 máy**: start=3064 md5 `6290560edff8743033085b623e731866`.
// 🔴 **GHI ĐÚNG HAI CỘT NGHIỆP VỤ**: `FlagRepair` và `RepairRemark` (+ `LogLUDateTime`/`LogLUBy`).
//    Hàm **KHÔNG đụng tới trạng thái nào** — không `PDIDtlStatus`, không `PDIStorageStatus`.
//    Port thêm bất kỳ cột nào khác là **mở quyền ghi ngoài nguồn** (`C0-…quinquagesimusquintus`).
// 🔴 **Khoá dòng HAI phần, mẫu KHÁC thường**: `string.Format("|{0}||{1}|", PDINo, VIN)` —
//    **hai dấu `|` liền nhau ở giữa**, không phải `|a|b|`. Trùng trong lô ⇒ ném.
//    ⚠️ **Lỗi NHÃN trong nguồn** (ghi nhận, không sửa): mã lỗi ném ra là
//      **`HTMV_PDIApprove_DuplicateKeyDetail`** — mã của hàm **APPROVE**, không phải của Update.
// 🔴 **Guard trạng thái NHẬN TẤT CẢ**: `myCar_CheckHTMV_PDIDtl(…, Flag.Active, **"P,A,R,C,F"**,
//    **"P,A,R,C,F"**, …)` — cả hai danh sách liệt kê **đủ 5 giá trị** ⇒ thực chất **không lọc gì**,
//    chỉ đòi dòng **tồn tại**. Port siết lại là **chặt hơn nguồn**.
// 🔴 `myCar_CheckVIN(…, **""**, **""**, …)` — hai tham số kiểm truyền **chuỗi RỖNG** ⇒ **cố ý không
//    kiểm** tồn tại/`DocumentsStatus` (khuôn `C0-…sexagesimusprimus`).
// 🔴 Chỉ ghi **`_dbMain`**, KHÔNG ghi `_dbWH` — như #B81, khác #B75/#B92.
// 📌 §12: `HtmvPdiDtl.FlagRepair` + `.RepairRemark` (entity + Seeder + DTO + POST + đọc ở #B94 GET).
app.MapPost("/api/pdi/dtl/update-repair", async (
    List<PdiDtlRepairDto> rows, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    if (rows is null || rows.Count == 0)
        return Results.BadRequest(new { error = "HTMV_PDIUpdate_TableDetailBeBlank" });

    var seen = new HashSet<string>(StringComparer.Ordinal);
    var now = DateTime.Now;
    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var heads = await db.HtmvPdis.Where(h => h.OrgId == t.OrgId).ToListAsync();
    var headByNo = heads.GroupBy(h => h.PDINo).ToDictionary(g => g.Key, g => g.First());

    var targets = new List<HtmvPdiDtl>();
    foreach (var (r, i) in rows.Select((r, i) => (r, i)))
    {
        var pdiNo = (r.PDINo ?? "").Trim();
        var vin = (r.VIN ?? "").Trim().ToUpperInvariant();
        // 🔴 Khoá "|PDINo||VIN|" — HAI dấu | liền nhau ở giữa.
        var keyDetail = $"|{pdiNo}||{vin}|";
        if (!seen.Add(keyDetail))
            return Results.BadRequest(new
            {
                // ⚠️ Nguồn dùng mã lỗi của hàm APPROVE — giữ nguyên để đối chiếu log.
                error = "HTMV_PDIApprove_DuplicateKeyDetail",
                check = new { HTMV_PDIDtl_Idx = i, strKeyDetail = keyDetail }
            });

        if (!headByNo.TryGetValue(pdiNo, out var head))
            return Results.BadRequest(new { error = "HTMV_PDI_NotExist", check = new { HTMV_PDIDtl_Idx = i, PDINo = pdiNo } });

        // Guard: chỉ đòi dòng TỒN TẠI ("P,A,R,C,F" = đủ 5 giá trị = không lọc).
        var d = await db.HtmvPdiDtls
            .FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.HtmvPdiId == head.Id && x.VIN == vin);
        if (d is null)
            return Results.BadRequest(new { error = "HTMV_PDIDtl_NotExist", check = new { HTMV_PDIDtl_Idx = i, PDINo = pdiNo, VIN = vin } });
        targets.Add(d);
    }

    // Ghi ĐÚNG hai cột nghiệp vụ + dấu vết.
    var updated = 0;
    foreach (var (d, r) in targets.Zip(rows))
    {
        d.FlagRepair = r.FlagRepair;
        d.RepairRemark = r.RepairRemark;
        d.LogLUDateTime = now; d.LogLUBy = by;
        updated++;
    }
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        updated,
        logLUDateTime = now, logLUBy = by,
        writeScopeNote = "GHI DUNG HAI COT NGHIEP VU: FlagRepair va RepairRemark (+ LogLUDateTime/LogLUBy). Ham KHONG dung toi trang thai nao - khong PDIDtlStatus, khong PDIStorageStatus. Them cot khac la MO QUYEN GHI NGOAI NGUON.",
        keyPatternNote = "Khoa dong HAI phan, mau KHAC thuong: string.Format(\"|{0}||{1}|\", PDINo, VIN) - HAI dau | lien nhau o giua, khong phai |a|b|.",
        errorCodeQuirk = "LOI NHAN TRONG NGUON (ghi nhan, khong sua): ma loi nem ra khi trung khoa la HTMV_PDIApprove_DuplicateKeyDetail - ma cua ham APPROVE, khong phai cua Update.",
        statusGuardNote = "Guard trang thai NHAN TAT CA: myCar_CheckHTMV_PDIDtl(..., Flag.Active, 'P,A,R,C,F', 'P,A,R,C,F', ...) - ca hai danh sach liet ke DU 5 gia tri => thuc chat KHONG LOC GI, chi doi dong TON TAI. Port siet lai la CHAT HON NGUON.",
        checkVinNote = "myCar_CheckVIN(..., \"\", \"\", ...) - hai tham so kiem truyen CHUOI RONG => CO Y khong kiem ton tai/DocumentsStatus (khuon C0-...sexagesimusprimus).",
        singleDbNote = "Chi ghi _dbMain, KHONG ghi _dbWH - nhu #B81, khac #B75/#B92.",
        relatedNote = "Cap doc cua ham nay la #B94 (GET /api/pdi/storage-pending)."
    });
}).RequireAuthorization();

// ===== #144: KẾ HOẠCH ĐẶT HÀNG GỬI NHÀ MÁY HTMV (Ord_OrderPlan_HTMV + Detail) =====
// Nguồn: DMS40/zTemp.0.30.Order.cs (csproj 128) — _Create (9461) / _Update (10585). Chỉ có ở WS 64-bit.
// ⛔ NỢ ghi rõ: `_Create` là JOB TỰ SINH — chỉ nhận `strFlagIsMonth` rồi TỰ TÍNH 8 loại số lượng
//    (BO đã duyệt / đơn chờ / tồn HTC / BO nhà máy / tồn đại lý / kế hoạch / đơn thực / nhà máy duyệt)
//    từ nhiều bảng. Vòng này port VÒNG ĐỜI kế hoạch (nhập số liệu sẵn có, sửa, tra cứu);
//    THUẬT TOÁN tính để một vòng riêng — không bịa công thức.
// ✅ Nguồn `_Create` XOÁ theo OrderPlanNo trước khi ghi (delete-then-insert) ⇒ idempotent;
//    khác `HR_SalesManOfMonth` (#141) vốn không xoá và nhân đôi khi chạy lại.
app.MapGet("/api/orderplanhtmv", async (AppDbContext db, ITenantContext t, string? no, string? flagIsMonth) =>
{
    var q = db.OrdOrderPlanHtmvs.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(no)) q = q.Where(x => x.OrderPlanNo.Contains(no!));
    if (!string.IsNullOrWhiteSpace(flagIsMonth)) q = q.Where(x => x.FlagIsMonth == flagIsMonth);
    var items = await q.OrderByDescending(x => x.Id).Take(500).Select(x => new {
        x.OrderPlanNo, x.PeriodDate, x.FlagIsMonth, x.CreatedDate, x.CreatedBy, x.UpdateDTime, x.UpdateBy,
        x.LogLUDateTime, x.LogLUBy,
        specs = db.OrdOrderPlanHtmvDetails.Count(d => d.OrgId == t.OrgId && d.OrderPlanNo == x.OrderPlanNo) }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapGet("/api/orderplanhtmv/{no}", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
