app.MapPost("/api/trainingcourses/{id}/participants", async (long id, TrainingParticipantDto dto, AppDbContext db, ITenantContext t) =>
{
    var course = await db.TrainingCourses.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (course is null) return Results.NotFound(new { id });
    var sm = (dto.SMHyundaiCode ?? "").Trim();
    if (string.IsNullOrWhiteSpace(sm)) return Results.BadRequest(new { error = "Chưa nhập mã NVBH." });
    if (dto.OrganizeDate is null) return Results.BadRequest(new { error = "Chưa nhập ngày tổ chức." });
    var exists = await db.TrainingParticipants.AnyAsync(x => x.OrgId == t.OrgId && x.CourseId == id && x.SMHyundaiCode == sm && x.OrganizeDate == dto.OrganizeDate);
    if (exists) return Results.BadRequest(new { error = $"NVBH {sm} đã tham gia khóa này vào ngày đó." });
    var p = new TrainingParticipant
    {
        OrgId = t.OrgId, CourseId = id,
        // Mã bản ghi tham gia (TRAININGDTLCODE) — định danh thật của nguồn, sinh khi client không truyền.
        TrainingDtlCode = string.IsNullOrWhiteSpace(dto.TrainingDtlCode) ? "TDT" + DateTime.Now.ToString("yyMMddHHmmssfff") : dto.TrainingDtlCode.Trim(),
        SMHyundaiCode = sm, SMName = dto.SMName, OrganizeDate = dto.OrganizeDate,
        FormalityTraining = dto.FormalityTraining, Place = dto.Place,
        ResultIn = dto.ResultIn, ResultOut = dto.ResultOut,
        FlagActive = dto.FlagActive == "0" ? "0" : "1",
        UpdatedAt = DateTime.Now
    };
    db.TrainingParticipants.Add(p);
    await db.SaveChangesAsync();
    return Results.Ok(new { p.Id, p.SMHyundaiCode, p.OrganizeDate });
}).RequireAuthorization();

// Tiến trình tham gia khoá đào tạo — port 1:1 FrmQLTienTrinhThamGiaKhoaDT (2010.HTC/Admin/Product):
// tra cứu lịch sử đào tạo XUYÊN KHOÁ của nhân viên (nguồn: DealerService.Mst_TrainingDtl_Get, 7 tham số lọc)
// rồi xuất Excel. Lưới nguồn ghép Mst_Training (mã + tên khoá), Mst_SalesMan (mã + tên NV) và tên đại lý.
app.MapGet("/api/trainingparticipants/progress", async (
    AppDbContext db, ITenantContext t,
    string? trainingCode, string? trainingUserCode, string? trainingName,
    string? smHyundaiCode, string? smName, DateTime? organizeDate, string? flagActive) =>
{
    var q = db.TrainingParticipants.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(smHyundaiCode)) q = q.Where(x => x.SMHyundaiCode!.Contains(smHyundaiCode!));
    if (!string.IsNullOrWhiteSpace(smName)) q = q.Where(x => x.SMName != null && x.SMName.Contains(smName!));
    if (organizeDate.HasValue) q = q.Where(x => x.OrganizeDate == organizeDate);
    if (!string.IsNullOrWhiteSpace(flagActive)) q = q.Where(x => x.FlagActive == flagActive);

    // Lọc theo khoá học: nguồn lọc trên bảng đã ghép, nên phải quy về danh sách khoá trước.
    if (!string.IsNullOrWhiteSpace(trainingCode)
        || !string.IsNullOrWhiteSpace(trainingUserCode)
        || !string.IsNullOrWhiteSpace(trainingName))
    {
        var courseQuery = db.TrainingCourses.Where(c => c.OrgId == t.OrgId);
        if (!string.IsNullOrWhiteSpace(trainingCode)) courseQuery = courseQuery.Where(c => c.TrainingUserCode == trainingCode);
        if (!string.IsNullOrWhiteSpace(trainingUserCode)) courseQuery = courseQuery.Where(c => c.TrainingUserCode.Contains(trainingUserCode!));
        if (!string.IsNullOrWhiteSpace(trainingName)) courseQuery = courseQuery.Where(c => c.TrainingName != null && c.TrainingName.Contains(trainingName!));
        var courseIdsFiltered = await courseQuery.Select(c => c.Id).ToListAsync();
        q = q.Where(x => courseIdsFiltered.Contains(x.CourseId));
    }

    var rows = await q.OrderBy(x => x.SMHyundaiCode).ThenBy(x => x.OrganizeDate).Take(1000).ToListAsync();
    var courseIdsOfRows = rows.Select(r => r.CourseId).Distinct().ToList();
    var courses = await db.TrainingCourses
        .Where(c => c.OrgId == t.OrgId && courseIdsOfRows.Contains(c.Id))
        .Select(c => new { c.Id, c.TrainingUserCode, c.TrainingName, c.DealerCode })
        .ToListAsync();
    var courseById = courses.ToDictionary(c => c.Id);

    var dealerCodes = courses.Where(c => c.DealerCode != null).Select(c => c.DealerCode!).Distinct().ToList();
    var dealerRows = await db.Dealers
        .Where(d => d.OrgId == t.OrgId && dealerCodes.Contains(d.DealerCode))
        .Select(d => new { d.DealerCode, d.DealerName })
        .ToListAsync();
    var dealerNameByCode = dealerRows
        .GroupBy(d => d.DealerCode)
        .ToDictionary(g => g.Key, g => g.First().DealerName);

    var items = rows.Select((r, i) =>
    {
        courseById.TryGetValue(r.CourseId, out var course);
        var dealerCode = course?.DealerCode;
        return new
        {
            index = i + 1,
            r.TrainingDtlCode,
            trainingUserCode = course?.TrainingUserCode,
            trainingName = course?.TrainingName,
            r.SMHyundaiCode,
            r.SMName,
            dealerCode,
            dealerName = dealerCode is not null && dealerNameByCode.TryGetValue(dealerCode, out var dn) ? dn : null,
            r.OrganizeDate,
            r.FormalityTraining,
            r.Place,
            r.ResultIn,
            r.ResultOut,
            r.FlagActive,
            r.UpdatedAt
        };
    }).ToList();

    // Nguồn hiện thông báo "không tìm thấy kết quả" khi lưới rỗng.
    return Results.Ok(new { count = items.Count, notFound = items.Count == 0, items });
}).RequireAuthorization();

app.MapDelete("/api/trainingcourses/{id}/participants/{pid}", async (long id, long pid, AppDbContext db, ITenantContext t) =>
{
    var p = await db.TrainingParticipants.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CourseId == id && x.Id == pid);
    if (p is null) return Results.NotFound(new { pid });
    db.TrainingParticipants.Remove(p);
    await db.SaveChangesAsync();
    return Results.Ok(new { removed = pid });
}).RequireAuthorization();

// ===== Chứng chỉ nhân viên bán hàng (SalesManCertificate — port 1:1 FrmMst_SalesManCertificateCreate/Mng/Update, 2010.HTC/Admin) =====
app.MapGet("/api/salesmancerts", async (AppDbContext db, ITenantContext t, string? q, string? cert, bool? all) =>
{
    var qry = db.SalesManCertificates.Where(x => x.OrgId == t.OrgId);
    if (all != true) qry = qry.Where(x => x.FlagActive == "1");
    if (!string.IsNullOrWhiteSpace(cert)) qry = qry.Where(x => x.CertificateCode == cert);
    if (!string.IsNullOrWhiteSpace(q)) qry = qry.Where(x => x.SMHyundaiCode.Contains(q!) || x.CertificateCode.Contains(q!) || x.CertificateName!.Contains(q!));
    var items = await qry.OrderBy(x => x.SMHyundaiCode).Take(500).Select(x => new { x.Id, x.SMCerNo, x.SMHyundaiCode, x.CertificateCode, x.CertificateName, x.SMType, x.DepartmentCode, x.DealerCode, x.EffStartDate, x.EffEndDate, x.Remark, x.FlagActive, x.UpdatedAt }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/salesmancerts", async (
    SalesManCertificateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var sm = (dto.SMHyundaiCode ?? "").Trim();
    var cc = (dto.CertificateCode ?? "").Trim();

    // Thứ tự + nguyên văn thông báo theo btnSave_Click của FrmMst_SalesManCertificateCreate.
    if (string.IsNullOrWhiteSpace(sm)) return Results.BadRequest(new { error = "Chưa nhập Mã nhân viên!" });
    // Nguồn bắt buộc phải "lấy thông tin theo mã nhân viên" trước khi lưu ⇒ NVBH phải có thật.
    var salesManExists = await db.DlSalesMen.AnyAsync(x => x.OrgId == t.OrgId && x.SMHyundaiCode == sm)
                      || await db.SalesMen.AnyAsync(x => x.OrgId == t.OrgId && x.SMHyundaiCode == sm);
    if (!salesManExists) return Results.BadRequest(new { error = "Chưa lấy thông tin theo Mã nhân viên mới." });
    if (string.IsNullOrWhiteSpace(dto.DepartmentCode)) return Results.BadRequest(new { error = "Chưa chọn Mã phòng ban!" });
    if (string.IsNullOrWhiteSpace(dto.SMType)) return Results.BadRequest(new { error = "Chưa chọn Mã loại nhân viên!" });
    if (string.IsNullOrWhiteSpace(cc)) return Results.BadRequest(new { error = "Chưa chọn Chứng chỉ!" });
    if (dto.EffStartDate is null) return Results.BadRequest(new { error = "Chưa nhập Ngày cấp chứng chỉ!" });
    // Ngày kết thúc KHÔNG bắt buộc (nguồn đã comment khối bắt buộc — port dòng ĐANG CHẠY, không port dòng comment).
    // Khi có nhập thì nguồn chặn bằng ">=" ⇒ hai ngày BẰNG NHAU cũng bị chặn.
    if (dto.EffEndDate.HasValue && dto.EffStartDate >= dto.EffEndDate)
        return Results.BadRequest(new { error = "Ngày cấp chứng chỉ > Ngày kết thúc chứng chỉ!" });

    var actor = user.Identity?.Name;
    var now = DateTime.Now;

    // Khoá là SỐ CHỨNG CHỈ: có SMCerNo → sửa đúng lần cấp đó; không có → lần cấp MỚI.
    // (Trước đây khoá theo cặp (NVBH, mã chứng chỉ) nên cấp lại sẽ ĐÈ mất lần cấp cũ.)
    var smCerNo = (dto.SMCerNo ?? "").Trim();
    SalesManCertificate? row = null;
    if (smCerNo.Length > 0)
    {
        row = await db.SalesManCertificates.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SMCerNo == smCerNo);
        if (row is null) return Results.NotFound(new { error = $"Không tìm thấy số chứng chỉ '{smCerNo}'." });
    }
    else
    {
        smCerNo = "SMC" + now.ToString("yyMMddHHmmssfff");
        row = new SalesManCertificate { OrgId = t.OrgId, SMCerNo = smCerNo, CreatedAt = now, CreatedBy = actor };
        db.SalesManCertificates.Add(row);
    }

    row.SMHyundaiCode = sm;
    row.CertificateCode = cc;
    row.CertificateName = dto.CertificateName;
    row.SMType = dto.SMType;
    row.DepartmentCode = dto.DepartmentCode;
    row.DealerCode = dto.DealerCode;
    row.EffStartDate = dto.EffStartDate;
    row.EffEndDate = dto.EffEndDate;
    row.Remark = dto.Remark;
    row.UpdatedAt = now;
    row.UpdatedBy = actor;
    if (!string.IsNullOrWhiteSpace(dto.FlagActive)) row.FlagActive = dto.FlagActive!;

    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        row.Id, row.SMCerNo, row.SMHyundaiCode, row.CertificateCode, row.FlagActive,
        message = "Tạo mới chi tiết chứng chỉ nhân viên thành công!"
    });
}).RequireAuthorization();

// Tiến trình cấp chứng chỉ NVBH — port 1:1 FrmQLTienTrinhCapChungChi (2010.HTC/Admin/Product):
// màn tra cứu + xuất Excel, ghép chứng chỉ với thông tin NVBH, lọc theo đại lý / loại NV / chứng chỉ / khoảng ngày cấp.
app.MapGet("/api/salesmancerts/progress", async (
    AppDbContext db, ITenantContext t,
    string? dealer, string? smType, string? cert, string? sm, DateTime? from, DateTime? to) =>
{
    var q = db.SalesManCertificates.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(x => x.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(smType)) q = q.Where(x => x.SMType == smType);
    if (!string.IsNullOrWhiteSpace(cert)) q = q.Where(x => x.CertificateCode == cert);
    if (!string.IsNullOrWhiteSpace(sm)) q = q.Where(x => x.SMHyundaiCode.Contains(sm!));
    if (from.HasValue) q = q.Where(x => x.EffStartDate >= from);
    if (to.HasValue) q = q.Where(x => x.EffStartDate <= to);

    // Lưới nguồn hiển thị kèm TÊN NVBH lấy từ Mst_DlSalesMan (join), nên phải ghép ở đây.
    var rows = await q.OrderBy(x => x.SMHyundaiCode).ThenBy(x => x.EffStartDate).Take(1000).ToListAsync();
    var smCodes = rows.Select(r => r.SMHyundaiCode).Distinct().ToList();
    var smNames = await db.DlSalesMen
        .Where(x => x.OrgId == t.OrgId && smCodes.Contains(x.SMHyundaiCode))
        .Select(x => new { x.SMHyundaiCode, x.SMName })
        .ToListAsync();
    var nameByCode = smNames
        .GroupBy(x => x.SMHyundaiCode)
        .ToDictionary(g => g.Key, g => g.First().SMName);

    var items = rows.Select((r, i) => new
    {
        index = i + 1,
        r.SMCerNo,
        r.SMHyundaiCode,
        smName = nameByCode.TryGetValue(r.SMHyundaiCode, out var n) ? n : null,
        r.SMType,
        r.CertificateCode,
        r.CertificateName,
        effStartCertificate = r.EffStartDate,
        effEndCertificate = r.EffEndDate,
        r.DealerCode,
        r.Remark,
        r.FlagActive,
        updateDateTime = r.UpdatedAt
    }).ToList();

    // Nguồn báo "không tìm thấy kết quả" khi lưới rỗng — trả cờ để client hiện đúng thông báo đó.
    return Results.Ok(new { count = items.Count, notFound = items.Count == 0, items });
}).RequireAuthorization();

app.MapPost("/api/salesmancerts/{id}/toggle", async (long id, AppDbContext db, ITenantContext t) =>
{
    var row = await db.SalesManCertificates.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (row is null) return Results.NotFound(new { id });
    row.FlagActive = row.FlagActive == "1" ? "0" : "1"; row.UpdatedAt = DateTime.Now;
