    return Results.Ok(new { header = new { h.Id, h.OrderNo, h.OrderDate, h.CusName, h.Address, h.Phone, h.Mobile, h.Note, h.TotalQty, h.Status, h.SourceType, h.RONo, h.CreatedBy, h.CreatedAt }, lines });
