    var dup = lines.GroupBy(l => (l.PartCode ?? "").Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dup != null) return Results.BadRequest(new { error = $"Phụ tùng '{dup.Key}' bị trùng trong lệnh." });
