    var code = (dto.SupplierCode ?? "").Trim();
    if (string.IsNullOrWhiteSpace(code)) return Results.BadRequest(new { error = "Chưa nhập mã nhà cung cấp." });
    if (!string.IsNullOrWhiteSpace(dto.Phone) && !dto.Phone!.All(c => char.IsDigit(c) || c is ' ' or '-' or '+' or '(' or ')')) return Results.BadRequest(new { error = "Số điện thoại không hợp lệ." });
    var row = await db.SerMstSuppliers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SupplierCode == code);
    if (row is null) { row = new SerMstSupplier { OrgId = t.OrgId, SupplierCode = code }; db.SerMstSuppliers.Add(row); }
    row.SupplierName = dto.SupplierName; row.Address = dto.Address; row.Phone = dto.Phone; row.Fax = dto.Fax; row.UpdatedAt = DateTime.Now;
    if (!string.IsNullOrWhiteSpace(dto.FlagActive)) row.FlagActive = dto.FlagActive!;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.SupplierCode, row.SupplierName, row.FlagActive });
}).RequireAuthorization();

app.MapPost("/api/sersuppliers/{id}/toggle", async (long id, AppDbContext db, ITenantContext t) =>
{
    var row = await db.SerMstSuppliers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (row is null) return Results.NotFound(new { id });
    row.FlagActive = row.FlagActive == "1" ? "0" : "1"; row.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.FlagActive });
}).RequireAuthorization();

// ===== Phiếu điều chỉnh tồn kho (StockAdj — port 1:1 FrmStockAdjCreate/Search, TCMotor DMSCarSv) =====
app.MapGet("/api/stockadjs", async (AppDbContext db, ITenantContext t, string? status, string? no) =>
{
    var q = db.StockAdjs.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.AdjStatus == status);
    if (!string.IsNullOrWhiteSpace(no)) q = q.Where(x => x.StockAdjNo.Contains(no!));
    var items = await q.OrderByDescending(x => x.Id).Take(500).Select(x => new {
        x.Id, x.StockAdjNo, x.StorageCode, x.DealerCode, x.StockOutDate, x.Remark, x.AdjStatus, x.CreatedBy, x.CreatedAt, x.ApprovedAt,
        lines = db.StockAdjLines.Count(l => l.OrgId == t.OrgId && l.StockAdjId == x.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/stockadjs", async (StockAdjDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.PartCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Chưa có dòng phụ tùng." });
    var dup = lines.GroupBy(l => l.PartCode!.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dup != null) return Results.BadRequest(new { error = $"Mã phụ tùng {dup.Key} bị trùng!" });
    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    // 🔴 Số phiếu do CLIENT truyền rồi `.ToUpper()` (nguồn `StockOutAdjCreate`: tham số `strStockOutAdjNo`),
    //    KHÔNG phải server tự sinh — port cũ tự bịa "ADJyyMMddHHmmss" ⇒ không khớp số phiếu hệ nguồn.
    var no = (dto.StockAdjNo ?? "").Trim().ToUpperInvariant();
    if (no.Length == 0) return Results.BadRequest(new { error = "Bạn chưa nhập số phiếu điều chỉnh." });
    if (await db.StockAdjs.AnyAsync(x => x.OrgId == t.OrgId && x.StockAdjNo == no))
        return Results.BadRequest(new { error = $"Số phiếu {no} đã tồn tại!" });
    var h = new StockAdj { OrgId = t.OrgId, StockAdjNo = no, StorageCode = dto.StorageCode, DealerCode = dto.DealerCode, StockOutDate = dto.StockOutDate ?? DateTime.Now, Remark = dto.Remark, AdjStatus = "0", CreatedBy = by, CreatedAt = DateTime.Now };
    db.StockAdjs.Add(h); await db.SaveChangesAsync();
    foreach (var l in lines)
        db.StockAdjLines.Add(new StockAdjLine { OrgId = t.OrgId, StockAdjId = h.Id, PartCode = l.PartCode!.Trim(), PartName = l.PartName, Unit = l.Unit, QtyBalance = l.QtyBalance, QtyAdjust = l.QtyAdjust, BalanceLocation = l.BalanceLocation, InStockLocation = l.InStockLocation });
    await db.SaveChangesAsync();
    return Results.Ok(new { h.StockAdjNo, lines = lines.Count });
}).RequireAuthorization();

app.MapGet("/api/stockadjs/{no}/lines", async (string no, AppDbContext db, ITenantContext t) =>
{
    var h = await db.StockAdjs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StockAdjNo == no);
    if (h is null) return Results.NotFound(new { no });
    var lines = await db.StockAdjLines.Where(l => l.OrgId == t.OrgId && l.StockAdjId == h.Id)
        .Select(l => new { l.PartCode, l.PartName, l.Unit, l.QtyBalance, l.QtyAdjust, l.BalanceLocation, l.InStockLocation }).ToListAsync();
    return Results.Ok(new { h.StockAdjNo, h.AdjStatus, h.LogLUDateTime, h.LogLUBy, count = lines.Count, totalAdjust = lines.Sum(x => x.QtyAdjust), lines });
}).RequireAuthorization();

// 🔴 KẾT THÚC phiếu điều chỉnh — port `ProcessFinishStockOutAdj` (BizCarSv.Inventory.StockAdj.cs:240-378).
// Port cũ chỉ ĐỔI CỜ approve/reject mà **KHÔNG hề động vào tồn kho** ⇒ "điều chỉnh tồn kho" không điều chỉnh gì.
// Nguồn khi kết thúc: mỗi dòng TRỪ tồn ở kho CÂN ĐỐI rồi CHUYỂN sang kho ĐÍCH, có guard tồn tại tồn kho trước.
// ⚠️ Nhánh "reject" đã BỎ: nguồn không có huỷ phiếu điều chỉnh (`Ser_StockAdj` chỉ "0"/"1").
// ===== #176 SỬA và XOÁ phiếu điều chỉnh tồn — `Ser_StockAdj_Update` (5300) / `_Delete` (4829) =====
// Nguồn: TCMotor `DMSCarSv/TERP.BizCarSv/BizCarSv.Inventory.Stock.cs` — BƯỚC 3B: md5 cả file `d91ec639`
//   KHỚP 2 máy (laptop `V20.2023.Release.V2`, máy 150 `V20.2023.Release` — hai tên, một nội dung, xem #174).
// TWIN: `TERP.WSCarSv/App_Code/WSCarSv.cs` gọi `_biz.Ser_StockAdj_Create/_Update/_Delete/_Get` —
//   bốn lệnh, MiniHTC mới có Create + Get + finish ⇒ lượt này bù nốt Update và Delete.
//
// ⚠️ LƯU Ý BẢNG: cụm này ghi **`Ser_Inv_StockAdj`**, KHÁC bảng `Ser_Inv_StockOutAdj` của
//    `StockOutAdjCreate` (`BizCarSv.Inventory.StockAdj.cs`). Hai bảng, hai cụm — dễ lẫn vì tên gần giống.
app.MapPost("/api/stockadjs/{no}/update", async (string no, StockAdjDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.StockAdjs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StockAdjNo == no);
    if (h is null) return Results.NotFound(new { no });

    // 🔴 `Ser_StockAdj_NotAllowFinish`: phiếu đã kết thúc ("1") thì không sửa được nữa.
    if (h.AdjStatus != "0")
        return Results.BadRequest(new { error = $"Phiếu đang ở trạng thái '{h.AdjStatus}' — chỉ sửa được phiếu Mới tạo (0)." });

    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.PartCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Chưa có dòng phụ tùng." });

    var wh = dto.StorageCode ?? h.StorageCode ?? "";
    var seen = new HashSet<string>();
    foreach (var l in lines)
    {
        var part = l.PartCode!.Trim().ToUpperInvariant();
        var bal = (l.BalanceLocation ?? "").Trim();
        var dst = (l.InStockLocation ?? "").Trim();

        // 🔴 `Ser_StockAdj_LocationNotChange`: vị trí CÂN ĐỐI và vị trí ĐÍCH không được trùng nhau —
        //    điều chỉnh mà không đổi vị trí thì vô nghĩa. Guard này chỉ có ở `_Update`, `_Create` KHÔNG có.
        if (bal.Equals(dst, StringComparison.OrdinalIgnoreCase))
            return Results.BadRequest(new { error = $"{part}: vị trí cân đối và vị trí đích trùng nhau ('{bal}').", partCode = part });

        // 🔴 `Ser_StockAdj_QtyChangeOverBalance`: số lượng điều chỉnh không được vượt TỒN THỰC tại vị trí cân đối.
        // ⚠️ Nguồn chỉ kiểm KHI TÌM THẤY dòng tồn (`if (dtStockBalance != null && Rows.Count > 0)`);
        //    không có tồn thì **bỏ qua**, không báo lỗi. Giữ đúng — khác `/finish` vốn bắt buộc phải có tồn.
        var st = await db.PartStocks.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.WarehouseCode == wh
            && x.PartCode == part && (x.Location ?? "") == bal);
        if (st is not null && st.OnHand < l.QtyAdjust)
            return Results.BadRequest(new { error = $"{part}@{bal}: số lượng điều chỉnh {l.QtyAdjust} vượt tồn {st.OnHand}.", partCode = part });

        // `Ser_StockAdj_PartDuplicate`
        if (!seen.Add(part))
            return Results.BadRequest(new { error = $"Mã phụ tùng {part} bị trùng!", partCode = part });
    }

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    if (dto.StorageCode is not null) h.StorageCode = dto.StorageCode;
    if (dto.DealerCode is not null) h.DealerCode = dto.DealerCode;
    if (dto.StockOutDate is not null) h.StockOutDate = dto.StockOutDate;
    h.Remark = dto.Remark;
    h.LogLUDateTime = now; h.LogLUBy = who;

    // Nguồn dựng lại trọn bộ dòng theo bảng đầu vào.
    var old = await db.StockAdjLines.Where(l => l.OrgId == t.OrgId && l.StockAdjId == h.Id).ToListAsync();
    db.StockAdjLines.RemoveRange(old);
    foreach (var l in lines)
        db.StockAdjLines.Add(new StockAdjLine
        {
            OrgId = t.OrgId, StockAdjId = h.Id, PartCode = l.PartCode!.Trim().ToUpperInvariant(),
            PartName = l.PartName, Unit = l.Unit, QtyBalance = l.QtyBalance, QtyAdjust = l.QtyAdjust,
            BalanceLocation = l.BalanceLocation, InStockLocation = l.InStockLocation
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { h.StockAdjNo, h.AdjStatus, replaced = old.Count, lines = lines.Count, h.LogLUDateTime, h.LogLUBy });
}).RequireAuthorization();

// 🔴 `Ser_StockAdj_Delete` (4829): guard DUY NHẤT là **`Status == Finished` thì chặn**
//    (`Ser_StockAdj_DeleteNotAllow`) — tức phiếu Mới tạo xoá được, phiếu đã kết thúc thì không.
app.MapDelete("/api/stockadjs/{no}", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.StockAdjs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StockAdjNo == no);
    if (h is null) return Results.NotFound(new { no });
    if (h.AdjStatus == "1")
        return Results.BadRequest(new { error = "Phiếu đã kết thúc — không xoá được." });
    var lines = await db.StockAdjLines.Where(l => l.OrgId == t.OrgId && l.StockAdjId == h.Id).ToListAsync();
    db.StockAdjLines.RemoveRange(lines);
    db.StockAdjs.Remove(h);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = no, linesDeleted = lines.Count });
}).RequireAuthorization();

app.MapPost("/api/stockadjs/{no}/finish", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.StockAdjs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StockAdjNo == no);
    if (h is null) return Results.NotFound(new { no });
    if (h.AdjStatus != "0") return Results.BadRequest(new { error = "Chỉ kết thúc được phiếu ở trạng thái Mới tạo." });
    var lines = await db.StockAdjLines.Where(l => l.OrgId == t.OrgId && l.StockAdjId == h.Id).ToListAsync();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Phiếu không có dòng phụ tùng." });

    var wh = h.StorageCode ?? "";
    // Guard theo nguồn: CheckNotExistStockBalance / CheckNotFoundPartInstance — thiếu tồn ở kho cân đối là LỖI, không âm thầm bỏ qua.
    foreach (var l in lines)
    {
        var bal = l.BalanceLocation ?? "";
        var st = await db.PartStocks.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.WarehouseCode == wh && x.PartCode == l.PartCode && (x.Location ?? "") == bal);
        if (st is null) return Results.BadRequest(new { error = $"Không tìm thấy tồn kho của {l.PartCode} tại vị trí cân đối '{bal}'." });
        if (st.OnHand < l.QtyAdjust) return Results.BadRequest(new { error = $"Tồn không đủ cho {l.PartCode}@{bal}: cần {l.QtyAdjust}, còn {st.OnHand}." });
    }
    foreach (var l in lines)
    {
        var bal = l.BalanceLocation ?? "";
        var src = await db.PartStocks.FirstAsync(x => x.OrgId == t.OrgId && x.WarehouseCode == wh && x.PartCode == l.PartCode && (x.Location ?? "") == bal);
        src.OnHand -= l.QtyAdjust; src.UpdatedAt = DateTime.Now;

        // ⚠️ MÂU THUẪN NGUỒN (đã ghi C0-bug3, KHÔNG tự sửa nguồn): nhánh "chưa có bản ghi kho đích" nguồn GÁN
        //    `= dActualQuantity` (cộng vào) còn nhánh "đã có" lại viết `- dActualQuantity` (trừ tiếp).
        //    Port theo nhánh insert + đúng ngữ nghĩa comment nguồn "Chuyển số lượng" ⇒ CỘNG vào kho đích.
        var dst0 = l.InStockLocation ?? "";
        var dst = await db.PartStocks.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.WarehouseCode == wh && x.PartCode == l.PartCode && (x.Location ?? "") == dst0);
        if (dst is null)
        {
            dst = new PartStock { OrgId = t.OrgId, WarehouseCode = wh, PartCode = l.PartCode, PartName = l.PartName, Location = l.InStockLocation, OnHand = 0 };
            db.PartStocks.Add(dst);
        }
        dst.OnHand += l.QtyAdjust; dst.UpdatedAt = DateTime.Now;
    }
    h.AdjStatus = "1"; h.ApprovedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.StockAdjNo, status = h.AdjStatus, statusName = "Kết thúc", adjustedLines = lines.Count });
}).RequireAuthorization();

