// Trace twin LIVE: `FrmVinUnmap` nút **"Chặn Map Vin"** → `SalesService.DisableMapVin(carId)` (`:98`)
//   → WS `CarCarUpdate01` (`WSHTC.asmx.cs:13545`) → **`_biz.CarCarUpdate01_New20181119`**
//   (`Biz.HTC.WH.cs:59243`).
// 🔴 MỘT HÀM, BA NHÁNH ĐỘC LẬP theo tham số nào KHÁC RỖNG (`:59345`, `:59363`, `:59369`) —
//    mỗi nhánh guard riêng, `alColumnEffective` riêng:
//   (a) `strUnitPriceActualNew` ≠ rỗng ⇒ guard **`PaymentStatus` phải = `Stage.Pending` ("P")**
//       (`..._PaymentStatusNotMatched`), ghi `UnitPriceActual`.
//   (b) `strMapVINRankingNew`  ≠ rỗng ⇒ guard **xe chưa map VIN** (`..._VINMapped`), ghi `MapVINRanking`.
//   (c) `strFlagAllowChangeVINNew` ≠ rỗng ⇒ guard giá trị **BẮT BUỘC là `Flag.Inactive` ("0")**
//       (`..._InvalidFlagAllowChangeVINNew` — **không cho bật lại "1"**) **và** xe chưa map VIN;
//       ghi `FlagAllowChangeVIN`.  ← Đây là nhánh mà nút "Chặn Map Vin" dùng (client truyền `Flag.No`).
// 🔴 Guard PHỤ THUỘC VAI TRÒ: chỉ khi `strIsUserFromSales == Flag.Active` mới chạy kiểm
//    "xe đã có dòng bảo lãnh **ở MỌI trạng thái**" (`inner join Pmt_GuaranteeDetail`, `:59409-59440`)
//    ⇒ `..._ExistGrtDetail`. Client `DisableMapVin` truyền **chuỗi rỗng** ⇒ nhánh này KHÔNG chạy.
// 🔴 RBAC `myCommon_CheckHTCDirect(..., Flag.Active)` (`:59308`) là DÒNG ACTIVE.
app.MapPost("/api/cars/{carId}/update01", async (
    string carId, CarUpdate01Dto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user, string? flagDirect) =>
{
    if (flagDirect == "0") return Results.BadRequest(new { error = "Chỉ người dùng HTC trực tiếp (FlagDirect='1') được sửa thông tin này." });
    var cid = carId.Trim().ToUpperInvariant();
    // `myCar_CheckCar(..., Flag.Active exist, Flag.Active active)`
    var car = await db.CarVinMasters.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.VIN == cid);
    if (car is null) return Results.NotFound(new { carId = cid });
    if (car.FlagActive == "0") return Results.BadRequest(new { error = $"Xe {cid} đã ngưng hoạt động." });

    var written = new List<string>();
    var vinMapped = !string.IsNullOrWhiteSpace(car.VIN) && car.VINFreeStatus == "0";

    // (a) Sửa ĐƠN GIÁ THỰC TẾ.
    if (dto.UnitPriceActualNew is not null)
    {
        if ((car.PaymentStatus ?? "P") != "P")
            return Results.BadRequest(new { error = $"Xe {cid}: chỉ sửa được đơn giá khi trạng thái thanh toán = 'P' (đang '{car.PaymentStatus}')." });
        car.UnitPriceActual = dto.UnitPriceActualNew; written.Add("UnitPriceActual");
    }
    // (b) Sửa HẠNG MAP VIN.
    if (!string.IsNullOrWhiteSpace(dto.MapVINRankingNew))
    {
        if (vinMapped) return Results.BadRequest(new { error = $"Xe {cid} đã map VIN — không sửa được hạng map VIN.", vin = car.VIN });
        car.MapVINRanking = dto.MapVINRankingNew!.Trim(); written.Add("MapVINRanking");
    }
    // (c) CHẶN MAP VIN — chỉ nhận "0".
    if (!string.IsNullOrWhiteSpace(dto.FlagAllowChangeVINNew))
    {
        if (dto.FlagAllowChangeVINNew!.Trim() != "0")
            return Results.BadRequest(new { error = "FlagAllowChangeVIN chỉ được đặt về '0' (chặn) — nguồn không cho bật lại '1'." });
        if (vinMapped) return Results.BadRequest(new { error = $"Xe {cid} đã map VIN — không chặn map VIN được.", vin = car.VIN });
        car.FlagAllowChangeVIN = "0"; written.Add("FlagAllowChangeVIN");
    }
    if (written.Count == 0) return Results.BadRequest(new { error = "Không có trường nào để cập nhật (cả ba tham số đều rỗng)." });

    // Guard PHỤ THUỘC VAI TRÒ: chỉ chạy khi người dùng thuộc phòng Sales.
    if (dto.IsUserFromSales == "1")
    {
        var hasGrt = await db.BankGuaranteeDtls.AnyAsync(d => d.OrgId == t.OrgId && d.VIN == cid);
        if (hasGrt) return Results.BadRequest(new { error = $"Xe {cid} đã có dòng bảo lãnh (mọi trạng thái) — người dùng phòng Sales không sửa được.", guard = "CarCarUpdate01_ExistGrtDetail" });
    }

    car.LogLUDateTime = DateTime.Now; car.LogLUBy = user.Identity?.Name ?? "system";
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        carId = cid, columnsWritten = written,
        car.UnitPriceActual, car.MapVINRanking, car.FlagAllowChangeVIN, car.PaymentStatus,
        branchNote = "Một hàm nguồn, BA nhánh độc lập theo tham số nào khác rỗng — mỗi nhánh guard riêng và tập cột ghi riêng.",
        salesGuardNote = "Kiểm 'đã có bảo lãnh' CHỈ chạy khi IsUserFromSales='1'; nút 'Chặn Map Vin' truyền rỗng nên bỏ qua."
    });
}).RequireAuthorization();
app.MapGet("/api/cars/for-dealer-create-cdr", async (
    AppDbContext db, ITenantContext t, string? vins, string? buPattern) =>
{
    var vinList = string.IsNullOrWhiteSpace(vins)
        ? new List<string>()
        : vins.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
              .Select(v => v.ToUpperInvariant()).Distinct().ToList();
    if (vinList.Count == 0) return Results.BadRequest(new { error = "Cần danh sách VIN (tham số `vins`, ngăn bởi dấu phẩy)." });

    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();
    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && vinList.Contains(c.VIN)).ToListAsync();

    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId)
        .Select(d => new { d.DealerCode, d.DealerName, d.BUCode, d.ProvinceCode }).ToListAsync();
    var provinces = await db.MstProvinces.Where(p => p.OrgId == t.OrgId).Select(p => new { p.ProvinceCode, p.ProvinceName }).ToListAsync();
    var specs = await db.CarSpecs.Where(s => s.OrgId == t.OrgId).Select(s => new { s.SpecCode, s.SpecDesc, s.AssemblyStatus }).ToListAsync();
    var models = await db.CarModelStds.Where(m => m.OrgId == t.OrgId).Select(m => new { m.ModelCode, m.ModelName }).ToListAsync();
    var colors = await db.MstCarColors.Where(c => c.OrgId == t.OrgId).Select(c => new { c.ModelCode, c.ColorCode, c.ColorExtName, c.ColorExtNameVN }).ToListAsync();
    var orders = await db.SalesOrders.Where(o => o.OrgId == t.OrgId).Select(o => new { o.SoCode, o.SPCode, o.DealerCode }).ToListAsync();
    var tkhqs = await db.CtTkhqs.Where(k => k.OrgId == t.OrgId).Select(k => new { k.DeclarationNo, k.OpenDate, k.TaxPaymentDate }).ToListAsync();

    var items = new List<object>();
    int droppedByDealerJoin = 0, notFoundVin = 0;
    foreach (var v in vinList)
    {
        var car = cars.FirstOrDefault(c => c.VIN == v);
        if (car is null) { notFoundVin++; continue; }
        // `inner join Mst_Dealer` — đại lý không có trong danh mục, hoặc ngoài BUPattern ⇒ **mất dòng**.
        var dl = dealers.FirstOrDefault(d => d.DealerCode == car.DealerCode);
        if (dl is null) { droppedByDealerJoin++; continue; }
        if (pattern is not null && !(dl.BUCode ?? "").ToUpperInvariant().StartsWith(pattern)) { droppedByDealerJoin++; continue; }

        // Toàn bộ phần dưới là LEFT JOIN — thiếu master không loại dòng.
        var sp = specs.FirstOrDefault(s => s.SpecCode == car.SpecCode);
        var mo = models.FirstOrDefault(m => m.ModelCode == car.ModelCode);
        var co = colors.FirstOrDefault(c => c.ModelCode == car.ModelCode && c.ColorCode == car.ColorCode);
        var pv = provinces.FirstOrDefault(p => p.ProvinceCode == dl.ProvinceCode);
        var so = car.SOCode is null ? null : orders.FirstOrDefault(o => o.SoCode == car.SOCode);
        // `left join CT_TKHQ ctt on ctt.DeclarationNo = cv.DeclarationNo` — nối qua **Car_VIN**, không qua Car_Car.
        var tk = car.DeclarationNo is null ? null : tkhqs.FirstOrDefault(k => k.DeclarationNo == car.DeclarationNo);

        items.Add(new
        {
            carId = car.VIN, vin = car.VIN, car.SpecCode, specDescription = sp?.SpecDesc, assemblyStatus = sp?.AssemblyStatus,
            car.ModelCode, modelName = mo?.ModelName, car.ColorCode, colorExtName = co?.ColorExtName, colorExtNameVN = co?.ColorExtNameVN,
            dealerCode = dl.DealerCode, dealerName = dl.DealerName, provinceCode = dl.ProvinceCode, provinceName = pv?.ProvinceName,
            soCode = car.SOCode, spCode = so?.SPCode,
            car.EngineNo, car.ActualSpec, car.SerialNo, car.PackingListNo,
            declarationNo = car.DeclarationNo, tkhqOpenDate = tk?.OpenDate, tkhqTaxPaymentDate = tk?.TaxPaymentDate,
            car.BillNo, car.MortageStartDate, car.MortageEndDate, car.DocDeliveryReqDate, car.FlagDocReq
        });
    }

    return Results.Ok(new
    {
        count = items.Count, items,
        filterShape = "VIN IN (danh sách) — client chỉ dựng đúng một điều kiện `in`, không có LIKE.",
        rbacJoinColumn = "Car_Car.DealerCode (đại lý ĐANG GIỮ xe) — khác các màn giao dịch dùng DealerCodeBuyer.",
        joinNote = "Chỉ Mst_Dealer là INNER; spec/model/color/province/đơn hàng/Car_VIN/TKHQ/packing list đều LEFT ⇒ thiếu master không mất dòng xe.",
        droppedByDealerJoin, notFoundVin,
        debt = "NỢ: nguồn còn left join CT_DealerContractDetail và CT_PackingList — MiniHTC chưa nối 2 bảng này ở truy vấn này."
    });
}).RequireAuthorization();
app.MapGet("/api/paymentdiscountreqs/eligible-vins", async (
    AppDbContext db, ITenantContext t, string? vin, DateTime? dateFrom, DateTime? dateTo) =>
{
    var vinKey = string.IsNullOrWhiteSpace(vin) ? null : vin.Trim().ToUpperInvariant();

    // Nền: giao dịch BÁN LẺ (DealerCodeBuyer rỗng, CustomerCodeBuyer có) + dòng HIỆN HÀNH.
    var deals = await db.DealerDeals.Where(d => d.OrgId == t.OrgId
        && (d.DealerCodeBuyer == null || d.DealerCodeBuyer == "")
        && d.CustomerCodeBuyer != null && d.CustomerCodeBuyer != "").ToListAsync();
    var dealIds = deals.Select(d => d.Id).ToList();
    var lines = await db.DealerDealDetails
        .Where(x => x.OrgId == t.OrgId && dealIds.Contains(x.DealId) && x.FlagCurrent == "1").ToListAsync();
    var carIds = lines.Select(x => x.CarId).Distinct().ToList();
    if (vinKey is not null) carIds = carIds.Where(c => c.Contains(vinKey)).ToList();

    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && carIds.Contains(c.VIN)).ToListAsync();
    var specs = await db.CarSpecs.Where(s => s.OrgId == t.OrgId).Select(s => new { s.SpecCode, s.AssemblyStatus }).ToListAsync();

    // Thanh toán đã HOÀN THÀNH: `pmp.PaymentStatus in ('F')`.
    var pays = await (from d in db.PmtPaymentDetails.Where(d => d.OrgId == t.OrgId && d.CarId != null && carIds.Contains(d.CarId!))
                      join p in db.PmtPayments.Where(p => p.OrgId == t.OrgId && p.PaymentStatus == "F")
                           on d.PaymentNo equals p.PaymentNo
                      select new { d.CarId, d.Amount, d.GuaranteeNo, p.PaymentEndDate }).ToListAsync();
    if (dateFrom is not null) pays = pays.Where(x => x.PaymentEndDate >= dateFrom).ToList();
    if (dateTo is not null) pays = pays.Where(x => x.PaymentEndDate <= dateTo).ToList();

    var items = new List<object>();
    int droppedNoCar = 0, droppedNoAssembly = 0, notReachedThreshold = 0;
    foreach (var cid in carIds.Distinct())
    {
        var car = cars.FirstOrDefault(c => c.VIN == cid);
        if (car is null) { droppedNoCar++; continue; }
        // `Min(mcs.AssemblyStatus)` + `and mcs.AssemblyStatus in ('CBU','CKD')`
        var asm = specs.Where(s => s.SpecCode == car.SpecCode && (s.AssemblyStatus == "CBU" || s.AssemblyStatus == "CKD"))
                       .Select(s => s.AssemblyStatus).OrderBy(x => x, StringComparer.Ordinal).FirstOrDefault();
        if (asm is null) { droppedNoAssembly++; continue; }

        var mine = pays.Where(p => p.CarId == cid).ToList();
        // temp1: cọc + thanh toán bảo lãnh · temp2: CHỈ tiền cọc (`GuaranteeNo is null`)
        var totalDepositAndGrt = mine.Sum(p => p.Amount ?? 0m);
        var totalDepositOnly = mine.Where(p => p.GuaranteeNo == null).Sum(p => p.Amount ?? 0m);
        // `AmountAccum` = luỹ kế theo mốc `PaymentEndDate` (nguồn self-join `pmp.PaymentEndDate >= pmp_Accum…`)
        var accumRows = mine.Where(p => p.PaymentEndDate != null)
            .GroupBy(p => p.PaymentEndDate!.Value)
            .Select(g => new { EndDate = g.Key, AmountAccum = mine.Where(x => x.PaymentEndDate <= g.Key).Sum(x => x.Amount ?? 0m) })
            .OrderBy(x => x.EndDate).ToList();

        var price = car.UnitPriceActual ?? 0m;
        var need = asm == "CBU" ? 30.00m / 100m * price : 15.00m / 100m * price;
        // Ngày đạt ngưỡng = mốc `PaymentEndDate` ĐẦU TIÊN có luỹ kế >= ngưỡng.
        var reached = price > 0 ? accumRows.FirstOrDefault(x => x.AmountAccum >= need) : null;
        if (reached is null) { notReachedThreshold++; continue; }

        items.Add(new
        {
            carId = cid, vin = car.VIN, car.SpecCode, car.ModelCode,
            assemblyStatus = asm, unitPriceActual = price,
            thresholdPercent = asm == "CBU" ? 30 : 15, thresholdAmount = need,
            amountTotalDepositAndGuarantee = totalDepositAndGrt,
            amountTotalDepositOnly = totalDepositOnly,
            amountAccumAtReach = reached.AmountAccum,
            paymentEndDateCbu30Ckd15 = reached.EndDate    // alias nguồn: cmp1_PaymentEndDate_CBU30_CKD15
        });
    }

    return Results.Ok(new
    {
        count = items.Count, items,
        baseFilter = "Chỉ giao dịch BÁN LẺ (DealerCodeBuyer rỗng, CustomerCodeBuyer có) + dòng FlagCurrent='1'; thanh toán chỉ tính PaymentStatus='F'.",
        thresholdRule = "CBU ≥ 30% × UnitPriceActual · CKD ≥ 15% × UnitPriceActual (hai ngưỡng khác nhau, không có ngưỡng chung).",
        droppedNoCar, droppedNoAssembly, notReachedThreshold,
        debt = "NỢ: nguồn còn loại theo `cdodtl.ConfirmStatus not in ('R','C')` đặt trong mệnh đề `on` của LEFT JOIN (không loại dòng cha) — MiniHTC chưa nối lệnh giao ở truy vấn này."
    });
}).RequireAuthorization();
app.MapGet("/api/paymentdiscountreqs/eligible-guarantees", async (
    AppDbContext db, ITenantContext t, string? dealerCode, DateTime? dateEndFrom, DateTime? dateEndTo) =>
{
    if (dateEndFrom is null || dateEndTo is null)
        return Results.BadRequest(new { error = "Cần khoảng ngày tất toán bảo lãnh (dateEndFrom, dateEndTo)." });
    var dealerKey = string.IsNullOrWhiteSpace(dealerCode) ? null : dealerCode.Trim().ToUpperInvariant();

    // `(@strDealerCode = '' or pg.DealerCode = @strDealerCode)` — rỗng nghĩa là KHÔNG lọc.
    var grts = await db.BankGuarantees.Where(g => g.OrgId == t.OrgId
        && g.DateEnd >= dateEndFrom && g.DateEnd <= dateEndTo      // `pg.DateEnd >= … and <= …`
        && g.DiscountPmtValue == null                               // `pg.DiscountPmtValue is null`
        && g.Status == "A")                                         // `pg.GuaranteeStatus = Stage.Approved`
        .ToListAsync();
    if (dealerKey is not null) grts = grts.Where(g => g.DealerCode == dealerKey).ToList();

    var grtIds = grts.Select(g => g.Id).ToList();
    var dtls = await db.BankGuaranteeDtls.Where(d => d.OrgId == t.OrgId && grtIds.Contains(d.GuaranteeId)).ToListAsync();
    var vins = dtls.Select(d => d.VIN).Distinct().ToList();
    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && vins.Contains(c.VIN))
        .Select(c => new { c.VIN, c.SOCode, c.DealerCode }).ToListAsync();
    var soCodes = cars.Where(c => c.SOCode != null).Select(c => c.SOCode!).Distinct().ToList();
    var orders = await db.SalesOrders.Where(o => o.OrgId == t.OrgId && soCodes.Contains(o.SoCode))
        .Select(o => new { o.SoCode, o.SPCode }).ToListAsync();

    // --- Bước 1 (`#tbl_Pmt_Guarantee_Temp1_1`): dòng THOẢ mọi điều kiện ---
    var temp1 = new List<(long GrtId, string GuaranteeNo, string VIN)>();
    int droppedNoCar = 0, droppedNoOrder = 0, droppedPolicy = 0, droppedNoDateStart = 0, droppedDtlStatus = 0;
    foreach (var d in dtls)
    {
        var g = grts.First(x => x.Id == d.GuaranteeId);
        var car = cars.FirstOrDefault(c => c.VIN == d.VIN);
        if (car is null) { droppedNoCar++; continue; }                    // `inner join Car_Car`
        var so = car.SOCode is null ? null : orders.FirstOrDefault(o => o.SoCode == car.SOCode);
        if (so is null) { droppedNoOrder++; continue; }                   // `inner join Ord_SalesOrder`
        // `and not oso.SPCode in ('KCK', 'NG')`
        if (so.SPCode == "KCK" || so.SPCode == "NG") { droppedPolicy++; continue; }
        if (d.DateStart is null) { droppedNoDateStart++; continue; }      // `pgdt.DateStart is not null`
        if (d.GuaranteeDetailStatus != "A") { droppedDtlStatus++; continue; }  // `in (Stage.Approved)`
        temp1.Add((g.Id, g.GuaranteeNo, d.VIN));
    }

    // --- Bước 2 (`#tbl_Pmt_Guarantee_Temp1_2`): bảo lãnh CÒN dòng VI PHẠM ⇒ bị loại ---
    var candidateGrtIds = temp1.Select(x => x.GrtId).Distinct().ToHashSet();
    var violating = dtls
        .Where(d => candidateGrtIds.Contains(d.GuaranteeId)
                    && d.DateStart is null                                          // chưa có ngày hiệu lực
                    && d.GuaranteeDetailStatus != "C" && d.GuaranteeDetailStatus != "R")  // không thuộc {Cancel, Rejected}
        .Select(d => d.GuaranteeId).Distinct().ToHashSet();

    var items = temp1.Where(x => !violating.Contains(x.GrtId))
        .Select(x =>
        {
            var g = grts.First(z => z.Id == x.GrtId);
            var car = cars.First(c => c.VIN == x.VIN);
            var so = orders.FirstOrDefault(o => o.SoCode == car.SOCode);
            return new
            {
                guaranteeNo = x.GuaranteeNo, vin = x.VIN, carId = x.VIN,
                dealerCode = g.DealerCode, carDealerCode = car.DealerCode,
                g.DateEnd, g.DiscountPmtValue, guaranteeStatus = g.Status,
                soCode = car.SOCode, spCode = so?.SPCode
            };
        }).ToList();

    return Results.Ok(new
    {
        count = items.Count, items,
        excludedGuarantees = violating.Count(),
        excludeRule = "Bảo lãnh bị loại nếu CÒN dòng xe có DateStart null và trạng thái dòng KHÔNG thuộc {C, R} — đúng cơ chế 2 temp + left-join-loại-trừ của nguồn.",
        constants = new { salesPolicyExcluded = new[] { "KCK", "NG" }, guaranteeStatus = "A", detailStatus = "A", detailStatusIgnored = new[] { "C", "R" } },
        droppedNoCar, droppedNoOrder, droppedPolicy, droppedNoDateStart, droppedDtlStatus
    });
}).RequireAuthorization();
app.MapPost("/api/deliveryorders/{doNo}/cars/{carId}/confirm-delivered", async (
    string doNo, string carId, BigUpdateCdodDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    var no = doNo.Trim().ToUpperInvariant();
    var cid = carId.Trim().ToUpperInvariant();

    var order = await db.DeliveryOrders.FirstOrDefaultAsync(o => o.OrgId == t.OrgId && o.DoNo == no);
    if (order is null) return Results.NotFound(new { deliveryOrderNo = no });
    // `myCar_CheckDeliveryOrderDetail(..., strConfirmStatusListToCheck = "A,F")`
    var line = await db.DeliveryOrderCars.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.DoId == order.Id && c.Vin == cid);
    if (line is null) return Results.NotFound(new { deliveryOrderNo = no, carId = cid });
    if (line.ConfirmStatus != "A" && line.ConfirmStatus != "F")
        return Results.BadRequest(new { error = $"Dòng lệnh giao phải ở trạng thái A hoặc F (đang '{line.ConfirmStatus}').", confirmStatusListToCheck = "A,F" });

    // `myCar_CheckCar(...)` — bốn điều kiện, hai trong đó NGƯỢC với màn sửa quy cách.
    var car = await db.CarVinMasters.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.VIN == cid);
    if (car is null) return Results.BadRequest(new { error = $"Xe {cid} chưa khai báo trên hệ thống." });
    if (car.FlagActive == "0") return Results.BadRequest(new { error = $"Xe {cid} đã bị huỷ/ngưng hoạt động." });
    if (car.DeliveryStatus is not null && car.DeliveryStatus != "A" && car.DeliveryStatus != "F")
        return Results.BadRequest(new { error = $"Xe {cid}: DeliveryStatus phải thuộc 'A,F' (đang '{car.DeliveryStatus}')." });
    if ((car.FlagAllowChangeVIN ?? "0") != "0")
        return Results.BadRequest(new { error = $"Xe {cid}: FlagAllowChangeVIN phải = '0' cho thao tác này (ngược với màn sửa quy cách)." });
    if ((car.VINFreeStatus ?? "0") != "0")
        return Results.BadRequest(new { error = $"Xe {cid}: VINFreeStatus phải = '0' cho thao tác này." });

    // `myCommon_CheckDealer(..., Flag.Active, Flag.Active)` theo `Car_Car.DealerCode`.
    var dealerCode = car.DealerCode;
    if (!string.IsNullOrWhiteSpace(dealerCode))
    {
        var dl = await db.Dealers.FirstOrDefaultAsync(d => d.OrgId == t.OrgId && d.DealerCode == dealerCode);
        if (dl is null) return Results.BadRequest(new { error = $"Đại lý {dealerCode} của xe không tồn tại." });
        if ((dl.FlagActive ?? dl.Status) == "0") return Results.BadRequest(new { error = $"Đại lý {dealerCode} đang ngưng hoạt động." });
    }
    // ⚠️ `myCommon_CheckAccessDealerData(BUCode)` — nợ tầng ability chung fleet.

    var who = user.Identity?.Name ?? "system"; var now = DateTime.Now;
    // Ghi `Car_DeliveryOrderDetail` (`:6258-6266`): `DeliveryOutDate` **ghi CÓ ĐIỀU KIỆN**, còn
    // `DeliveryEndDate` + `ConfirmStatus="F"` + `ConfirmDate` + `ConfirmBy` ghi vô điều kiện.
    var written = new List<string>();
    if (dto.DeliveryOutDate is not null) { line.DeliveryOutDate = dto.DeliveryOutDate; written.Add("DeliveryOutDate"); }
    line.DeliveryEndDate = dto.DeliveryEndDate; written.Add("DeliveryEndDate");
    line.ConfirmStatus = "F";        // TConst.Stage.Finished
    line.ConfirmDate = now; line.ConfirmBy = who;
    written.AddRange(new[] { "ConfirmStatus", "ConfirmDate", "ConfirmBy" });

    // Ghi `Car_Car.DeliveryStatus = Stage.Finished` — chú thích nguồn: "Xe đã được giao tới Đại lý".
    car.DeliveryStatus = "F";
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        deliveryOrderNo = no, carId = cid, columnsWritten = written,
        carDeliveryStatus = car.DeliveryStatus,
        guardNote = "DeliveryStatus/ConfirmStatus phải thuộc DANH SÁCH 'A,F'; FlagAllowChangeVIN và VINFreeStatus phải = '0' (NGƯỢC với #B17).",
        backupDebt = "NỢ: nguồn sao lưu 8 bảng vào *_MyBk (Car_DeliveryOrderDetail/Car_Car/HMC_Report/Car_VIN/DLS_DealDetail/Sto_DlvMinutes/Sto_TranspReqDtl/Sto_TranspReq) TRƯỚC khi sửa — MiniHTC chưa có tầng _MyBk.",
        remainingDebt = "NỢ: các bước sau của nguồn chưa port — cập nhật DLS_DealDetail, post-check Sto_TranspReqDtl, cập nhật Car_VIN.StorageCodeCurrent, sinh HMC_Report."
    });
}).RequireAuthorization();
app.MapPost("/api/carstatusupdates/import", async (CarStatusImportDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user, string? flagDirect) =>
{
    // `myCommon_CheckHTCDirect(..., Flag.Active)` (`:59765`) — DÒNG ACTIVE.
    if (flagDirect == "0") return Results.BadRequest(new { error = "Chỉ người dùng HTC trực tiếp (FlagDirect='1') được cập nhật trạng thái xe." });
    var typeStatus = (dto.TypeStatus ?? "CPTC").Trim().ToUpperInvariant();
    if (typeStatus is not ("TTC" or "CPTC"))
        return Results.BadRequest(new { error = "TypeStatus phải thuộc TConst.CarCarTypeStatus: TTC | CPTC" });

    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.CarId)).ToList();
    // `..._TableDetailBeBlank`
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có xe để cập nhật." });
    var dup = rows.GroupBy(r => r.CarId!.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dup != null) return Results.BadRequest(new { error = $"CarId {dup.Key} bị trùng trong file." });

    // Guard từng dòng — nguồn kiểm hết rồi mới ghi (cùng transaction).
    foreach (var r in rows)
    {
        var val = typeStatus == "TTC" ? r.TTCStatus : r.CPTCStatus;
        // `..._InvalidTTCStatus` / `..._InvalidCPTCStatus`: cột tương ứng phải CÓ MẶT trong bảng input.
        if (val is null)
            return Results.BadRequest(new { error = $"Xe {r.CarId}: thiếu cột {typeStatus}Status trong bảng gửi lên.", typeStatus });
        // `..._InvalidTypeTTCStatus` / `..._InvalidTypeCPTCStatus`: giá trị phải là "1" hoặc "0".
        if (val != "1" && val != "0")
            return Results.BadRequest(new { error = $"Xe {r.CarId}: {typeStatus}Status phải là '1' hoặc '0' (nhận '{val}').", typeStatus });
    }

    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var ids = rows.Select(r => r.CarId!.Trim()).ToHashSet();
    // `myCar_CheckCar` từng dòng — xe phải tồn tại.
    var knownCars = (await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && ids.Contains(c.VIN)).Select(c => c.VIN).ToListAsync()).ToHashSet();
    var missing = ids.FirstOrDefault(x => !knownCars.Contains(x));
    if (missing is not null) return Results.BadRequest(new { error = $"Xe {missing} chưa khai báo trên hệ thống." });

    var existing = await db.CarStatusUpdates.Where(x => x.OrgId == t.OrgId && ids.Contains(x.CarId)).ToListAsync();
    var byId = existing.ToDictionary(x => x.CarId, x => x);
    int added = 0, updated = 0; var now = DateTime.Now;
    foreach (var r in rows)
    {
        var cid = r.CarId!.Trim();
        if (!byId.TryGetValue(cid, out var row)) { row = new CarStatusUpdate { OrgId = t.OrgId, CarId = cid }; db.CarStatusUpdates.Add(row); added++; } else updated++;
        // 🔴 CHỈ ghi cột thuộc `typeStatus` — cột kia GIỮ NGUYÊN, đúng `alColumnEffective` của nguồn.
        if (typeStatus == "TTC") row.TTCStatus = r.TTCStatus!;
        else row.CPTCStatus = r.CPTCStatus!;
        row.UpdatedBy = by; row.UpdatedAt = now;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        added, updated, typeStatus,
        columnsWritten = new[] { typeStatus + "Status", "LogLUDateTime", "LogLUBy" },
        note = "Nguồn chỉ ghi ĐÚNG MỘT trong hai cột theo strTypeStatus — cột còn lại giữ nguyên."
    });
}).RequireAuthorization();

// ===== Huỷ / phục hồi xe hàng loạt (CarActiveStatus — port 1:1 FrmCapNhatTTHuyXe, 2010.HTC Views/Sales) =====
// TWIN đã trace: SalesService.Car_Car_UpdSpecial_HuyXe / _PhucHoi
//   → biz Car_Car_UpdSpecial_HuyXeX / Car_Car_UpdSpecial_PhucHoiX (TERP.BizHTC/DataWH/Biz.HTC.WH.cs).
// Form nhập Excel đúng MỘT cột mã xe (header dòng 2), rồi bấm "Hủy xe" hoặc "Active xe" cho cả lô.

/// <summary>Chuẩn hoá + kiểm danh sách mã xe của lô: bắt buộc nhập, không trùng (đúng thứ tự kiểm của form).</summary>
static (List<string>? CarIds, string? Error) NormalizeCarIdBatch(List<string>? rawCarIds)
{
    var lines = rawCarIds ?? new List<string>();
    if (lines.Count == 0) return (null, "Lưới dữ liệu xe trống!");
    var carIds = new List<string>();
    foreach (var raw in lines)
    {
        var carId = (raw ?? "").Trim();
        if (carId.Length == 0) return (null, "Mã xe bắt buộc nhập!");
        if (carIds.Contains(carId, StringComparer.OrdinalIgnoreCase))
            return (null, $"Xe '{carId}' bị lặp!");
        carIds.Add(carId);
    }
    return (carIds, null);
}

app.MapGet("/api/caractivestatuses", async (AppDbContext db, ITenantContext t, string? carId, string? flagActive) =>
{
    var q = db.CarActiveStatuses.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(carId)) q = q.Where(x => x.CarId.Contains(carId!));
    if (!string.IsNullOrWhiteSpace(flagActive)) q = q.Where(x => x.FlagActive == flagActive);
    var items = await q.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.CarId, x.Vin, x.FlagActive, x.CarCancelRemark, x.CarCancelDate, x.CarCancelBy,
        x.CarCancelType, x.UpdatedAt, x.UpdatedBy
    }).ToListAsync();
    return Results.Ok(new
    {
        count = items.Count,
        active = items.Count(i => i.FlagActive == "1"),
        cancelled = items.Count(i => i.FlagActive == "0"),
        items
    });
}).RequireAuthorization();

// Huỷ xe hàng loạt: FlagActive 1 → 0, ghi kèm thông tin huỷ.
app.MapPost("/api/caractivestatuses/cancel", async (
    CarIdBatchDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var (carIds, batchError) = NormalizeCarIdBatch(dto.CarIds);
    if (batchError is not null) return Results.BadRequest(new { error = batchError });

    var rows = await db.CarActiveStatuses
        .Where(x => x.OrgId == t.OrgId && carIds!.Contains(x.CarId)).ToListAsync();
    var byCarId = rows.ToDictionary(x => x.CarId, StringComparer.OrdinalIgnoreCase);

    foreach (var carId in carIds!)
    {
        if (!byCarId.TryGetValue(carId, out var row))
            return Results.BadRequest(new { error = $"Xe '{carId}' không có trong hệ thống!" });
        // Nguồn chỉ nhận xe đang Active (strFlagActiveListToCheck = Flag.Active).
        if (row.FlagActive != "1")
            return Results.BadRequest(new { error = $"Xe '{carId}' không ở trạng thái hoạt động!" });
        // 🔴 Guard chính: đã map VIN thì KHÔNG được huỷ (Car_Car_UpdSpecial_HuyXe_NotAllowUpdate).
        if (!string.IsNullOrWhiteSpace(row.Vin))
            return Results.BadRequest(new { error = $"Xe '{carId}' đã có VIN '{row.Vin}', không được phép cập nhật!" });
    }

    var actor = user.Identity?.Name ?? "system";
    var now = DateTime.Now;
    foreach (var carId in carIds!)
    {
        var row = byCarId[carId];
        row.FlagActive = "0";
        row.CarCancelRemark = "Huy Xe upd for MapVIN support";   // giữ nguyên chuỗi của nguồn
        row.CarCancelDate = now.Date;
        row.CarCancelBy = actor;
        row.CarCancelType = "NONE";
        row.UpdatedAt = now; row.UpdatedBy = actor;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { cancelled = carIds!.Count, message = "Hủy xe thành công!" });
}).RequireAuthorization();

// Phục hồi xe hàng loạt: FlagActive 0 → 1, XOÁ sạch thông tin huỷ.
app.MapPost("/api/caractivestatuses/restore", async (
    CarIdBatchDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var (carIds, batchError) = NormalizeCarIdBatch(dto.CarIds);
    if (batchError is not null) return Results.BadRequest(new { error = batchError });

    var rows = await db.CarActiveStatuses
        .Where(x => x.OrgId == t.OrgId && carIds!.Contains(x.CarId)).ToListAsync();
    var byCarId = rows.ToDictionary(x => x.CarId, StringComparer.OrdinalIgnoreCase);

    foreach (var carId in carIds!)
    {
        if (!byCarId.TryGetValue(carId, out var row))
            return Results.BadRequest(new { error = $"Xe '{carId}' không có trong hệ thống!" });
        // Nguồn chỉ nhận xe đang Inactive (strFlagActiveListToCheck = Flag.Inactive).
        if (row.FlagActive != "0")
            return Results.BadRequest(new { error = $"Xe '{carId}' chưa bị hủy!" });
        // Guard giống nhánh huỷ: đã map VIN thì cấm (Car_Car_UpdSpecial_PhucHoi_NotAllowUpdate).
        if (!string.IsNullOrWhiteSpace(row.Vin))
            return Results.BadRequest(new { error = $"Xe '{carId}' đã có VIN '{row.Vin}', không được phép cập nhật!" });
    }

    var actor = user.Identity?.Name ?? "system";
    var now = DateTime.Now;
    foreach (var carId in carIds!)
    {
        var row = byCarId[carId];
        row.FlagActive = "1";
        // Nguồn set NULL cả 3 cột thông tin huỷ, riêng CarCancelType vẫn giữ "NONE".
        row.CarCancelRemark = null;
        row.CarCancelDate = null;
        row.CarCancelBy = null;
        row.CarCancelType = "NONE";
        row.UpdatedAt = now; row.UpdatedBy = actor;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { restored = carIds!.Count, message = "Active xe thành công!" });
}).RequireAuthorization();

// Nạp danh sách xe (thay cho bước import Excel của form) — dùng để dựng dữ liệu thử/đồng bộ.
app.MapPost("/api/caractivestatuses/import", async (
    CarActiveImportDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var lines = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.CarId)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Lưới dữ liệu xe trống!" });
    var duplicated = lines.GroupBy(r => r.CarId!.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (duplicated is not null) return Results.BadRequest(new { error = $"Xe '{duplicated.Key}' bị lặp!" });

    var carIds = lines.Select(r => r.CarId!.Trim()).ToList();
    var existing = await db.CarActiveStatuses
        .Where(x => x.OrgId == t.OrgId && carIds.Contains(x.CarId)).ToListAsync();
    var byCarId = existing.ToDictionary(x => x.CarId, StringComparer.OrdinalIgnoreCase);

    var actor = user.Identity?.Name ?? "system";
    var now = DateTime.Now;
    int added = 0, updated = 0;
    foreach (var line in lines)
    {
        var carId = line.CarId!.Trim();
        if (!byCarId.TryGetValue(carId, out var row))
        {
            row = new CarActiveStatus { OrgId = t.OrgId, CarId = carId };
            db.CarActiveStatuses.Add(row); byCarId[carId] = row; added++;
        }
        else updated++;
        row.Vin = string.IsNullOrWhiteSpace(line.Vin) ? null : line.Vin.Trim().ToUpperInvariant();
        if (!string.IsNullOrWhiteSpace(line.FlagActive)) row.FlagActive = line.FlagActive == "0" ? "0" : "1";
        row.UpdatedAt = now; row.UpdatedBy = actor;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { added, updated });
}).RequireAuthorization();

