// Tạo đề nghị (đại lý) — khớp btnSave_Click/PRD_PaymentReqDiscount_Create gốc: cần chọn Chính sách hỗ trợ BH + ≥1 dòng VIN.
app.MapPost("/api/paymentreqdiscounts", async (PaymentReqDiscountDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (string.IsNullOrWhiteSpace(dto.SPCode)) return Results.BadRequest(new { error = "Chưa chọn \"Chính sách hỗ trợ BH\"" });
    var lines = dto.Lines ?? new List<PaymentReqDiscountVinDto>();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Chưa có dữ liệu" });

    var no = string.IsNullOrWhiteSpace(dto.PRDiscountNo) ? "PRD" + DateTime.Now.ToString("yyMMddHHmmss") : dto.PRDiscountNo.Trim();
    if (await db.PaymentReqDiscounts.AnyAsync(x => x.OrgId == t.OrgId && x.PRDiscountNo == no))
        return Results.BadRequest(new { error = $"Số đề nghị {no} đã tồn tại!" });
    // 🔴 #128 SỬA TAXONOMY: trạng thái theo `TConst.PRDiscountStatus` (Const.Main.cs:1114-1120):
    //    "P" chờ duyệt · "A1" duyệt cấp 1 · "A2" duyệt cấp 2 · "C" huỷ. Port cũ dùng "Draft" là SAI.
    var whoPrd = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var h = new PaymentReqDiscount
    {
        OrgId = t.OrgId, PRDiscountNo = no, DealerCode = dto.DealerCode,
        SPCode = dto.SPCode.Trim().ToUpperInvariant(), Remark = dto.Remark,
        Status = "P",
        AreaCode = dto.AreaCode,          // nguồn lấy từ dtDB_AreaDealer.AreaCodeDealer
        CreatedBy = whoPrd,
        LogLUDateTime = DateTime.Now, LogLUBy = whoPrd,
    };
    db.PaymentReqDiscounts.Add(h);
    foreach (var l in lines)
    {
        db.PaymentReqDiscountVins.Add(new PaymentReqDiscountVin
        {
            OrgId = t.OrgId, PRDiscountNo = no, VIN = (l.Vin ?? "").Trim().ToUpperInvariant(), CarId = l.CarId, SpecCode = l.SpecCode, SpecDescription = l.SpecDescription,
            DeliveryOutDate = l.DeliveryOutDate, DeliveryEndDate = l.DeliveryEndDate, DeliveryDate = l.DeliveryDate, DlrContractNo = l.DlrContractNo, SMName = l.SMName,
            CusInvoiceDate = l.CusInvoiceDate, UnitPriceActual = l.UnitPriceActual, AmountDealerRequest = l.AmountDealerRequest, CustomerName = l.CustomerName, UpdatedAt = DateTime.Now,
            // 🔴 #128: nguồn để `AmountHTCAppr` NULL khi tạo (chỉ điền khi HTC duyệt) và
            //    nhận `HTCApprDate` từ bảng đầu vào; kèm dấu vết tạo/sửa (Biz.HTC.WH.My.cs:1265-1276).
            AmountHTCAppr = null,
            HTCApprDate = l.HTCApprDate,
            CreatedDate = DateTime.Now, CreatedBy = whoPrd,
            LogLUDateTime = DateTime.Now, LogLUBy = whoPrd,
});
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { h.PRDiscountNo, h.Status, lines = lines.Count });
}).RequireAuthorization();

// ===== #167 bốn lệnh của HTC trên đề nghị chiết khấu — `PRD_PaymentReqDiscount_*` =====
// Nguồn: `TERP.BizHTC/DataWH/Biz.HTC.WH.My.cs` (csproj 273) — BƯỚC 3B: md5 CẢ FILE `7ef389d0` KHỚP 2 máy.
//   `_Approve1` (4267) · `_Approve2` (4526) · `_Cancel` (4783) · `_Delete` (4131).
// TWIN: WS 64-bit và 32-bit gọi CÙNG bản cho bốn lệnh này (khác `_Create`/`_Get`/`_UpdateMulti` có bản mới).
//
// 🔴 SỬA BUG CÂM (cùng lớp #140/#161, lần thứ BA). Lượt #128 đã sửa `POST` tạo sang đúng
//    `TConst.PRDiscountStatus` ("P"/"A1"/"A2"/"C") **nhưng bỏ quên endpoint duyệt**, nơi vẫn giữ bộ tự đặt
//    "Draft"/"Approved1"/"Approved2"/"Cancelled" ⇒ đề nghị vừa tạo ("P") **không bao giờ duyệt được**.
//
// 🔴 VÀ "Cancel" KHÔNG PHẢI HUỶ. Nguồn (4783) guard `PRDiscountStatus = "A1"` rồi ghi
//    `PRDiscountStatus = TConst.PRDiscountStatus.**Pending**` kèm `CancelDate`/`CancelBy`
//    ⇒ đây là **BỎ DUYỆT cấp 1, trả về chờ duyệt**. Hằng `PRDiscountStatus.Cancel = "C"`
//    **không có đường vào** trong cả cụm — đúng motif `C0-ducentesimusquintusdecimus`.
//
// Bảng trạng thái thật:  _Approve1: "P"→"A1"  ·  _Approve2: "A1"→"A2"  ·  _Cancel: "A1"→**"P"**  ·  _Delete: "P"→xoá.
// Cả bốn đều gọi `myCommon_CheckHTCDirect` (thao tác của HTC) — **nợ RBAC chung fleet**.
app.MapPost("/api/paymentreqdiscounts/{no}/{action}", async (string no, string action, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (action is not ("approve1" or "approve2" or "unapprove1" or "delete")) return Results.NotFound();
    no = no.Trim();
    var h = await db.PaymentReqDiscounts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PRDiscountNo == no);
    if (h is null) return Results.NotFound(new { no });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;

    if (action == "approve1")
    {
        if (h.Status != "P") return Results.BadRequest(new { error = $"Đề nghị đang ở '{h.Status}' — chỉ duyệt cấp 1 khi còn chờ duyệt (P)." });
        h.Status = "A1"; h.Approve1At = now; h.Appr1By = who;
    }
    else if (action == "approve2")
    {
        if (h.Status != "A1") return Results.BadRequest(new { error = $"Đề nghị đang ở '{h.Status}' — phải duyệt cấp 1 (A1) trước." });
        h.Status = "A2"; h.Approve2At = now; h.Appr2By = who;
    }
    else if (action == "unapprove1")
    {
        // `_Cancel`: vào từ "A1", ra "P" — BỎ DUYỆT, không phải huỷ. Đặt tên endpoint theo NGHĨA THẬT.
        if (h.Status != "A1") return Results.BadRequest(new { error = $"Đề nghị đang ở '{h.Status}' — chỉ bỏ duyệt được bản đã duyệt cấp 1 (A1)." });
        h.Status = "P"; h.CancelledAt = now; h.CancelBy = who;
    }
    else
    {
        // `_Delete`: guard "P" — chỉ xoá được đề nghị còn chờ duyệt; xoá luôn dòng VIN.
        if (h.Status != "P") return Results.BadRequest(new { error = $"Đề nghị đang ở '{h.Status}' — chỉ xoá được khi còn chờ duyệt (P)." });
        var dead = await db.PaymentReqDiscountVins.Where(l => l.OrgId == t.OrgId && l.PRDiscountNo == no).ToListAsync();
        db.PaymentReqDiscountVins.RemoveRange(dead);
        db.PaymentReqDiscounts.Remove(h);
        await db.SaveChangesAsync();
        return Results.Ok(new { PRDiscountNo = no, deleted = 1, lines = dead.Count });
    }
    h.LogLUDateTime = now; h.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.PRDiscountNo, h.Status, h.Approve1At, h.Appr1By, h.Approve2At, h.Appr2By, h.CancelledAt, h.CancelBy });
}).RequireAuthorization();

// 🔴 `PRD_PaymentReqDiscount_Save` (Biz.HTC.WH.My.cs:3209) — lệnh RIÊNG, khác `_Create`:
//    sửa lại **bộ dòng VIN** của đề nghị khi còn chờ duyệt (guard `PRDiscountStatus = "P"`),
//    và bắt `AmountDealerRequest` hợp lệ (`Save_InvalidAmountDealerRequest`).
app.MapPost("/api/paymentreqdiscounts/{no}/lines", async (string no, PaymentReqDiscountDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim();
    var h = await db.PaymentReqDiscounts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PRDiscountNo == no);
    if (h is null) return Results.NotFound(new { no });
    if (h.Status != "P") return Results.BadRequest(new { error = $"Đề nghị đang ở '{h.Status}' — chỉ sửa dòng khi còn chờ duyệt (P)." });
    var lines = dto.Lines ?? new List<PaymentReqDiscountVinDto>();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Chưa có dữ liệu" });
    foreach (var l in lines)
    {
        if (string.IsNullOrWhiteSpace(l.Vin)) return Results.BadRequest(new { error = "Có dòng chưa nhập số khung." });
        if (l.AmountDealerRequest <= 0) return Results.BadRequest(new { error = $"VIN {l.Vin}: số tiền đại lý đề nghị không hợp lệ." });
    }
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var old = await db.PaymentReqDiscountVins.Where(l => l.OrgId == t.OrgId && l.PRDiscountNo == no).ToListAsync();
    db.PaymentReqDiscountVins.RemoveRange(old);
    foreach (var l in lines)
        db.PaymentReqDiscountVins.Add(new PaymentReqDiscountVin
        {
            OrgId = t.OrgId, PRDiscountNo = no, VIN = l.Vin!.Trim().ToUpperInvariant(), CarId = l.CarId,
            SpecCode = l.SpecCode, SpecDescription = l.SpecDescription, DeliveryOutDate = l.DeliveryOutDate,
            DeliveryEndDate = l.DeliveryEndDate, DeliveryDate = l.DeliveryDate, DlrContractNo = l.DlrContractNo,
            SMName = l.SMName, CusInvoiceDate = l.CusInvoiceDate, UnitPriceActual = l.UnitPriceActual,
            AmountDealerRequest = l.AmountDealerRequest, CustomerName = l.CustomerName,
            AmountHTCAppr = null, HTCApprDate = l.HTCApprDate,   // nguồn vẫn để trống số tiền HTC duyệt ở bước này
            CreatedDate = now, CreatedBy = who, LogLUDateTime = now, LogLUBy = who, UpdatedAt = now
        });
    h.LogLUDateTime = now; h.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.PRDiscountNo, h.Status, replaced = old.Count, lines = lines.Count });
}).RequireAuthorization();

// 🔴 `PRD_PaymentReqDiscount_UpdateMulti_New20190809` (3725) — 🔴 TWIN lệch bit: WS 64-bit gọi bản
//    **2019**, WS 32-bit gọi bản trần. Đây là chỗ DUY NHẤT điền `AmountHTCAppr` (số tiền HTC duyệt):
//    guard `PRDiscountStatus ∈ **{"A1","A2"}**` — tức chỉ sửa được **SAU KHI** đã duyệt, ngược với `_Save`.
//    Khoá dòng của nguồn là `(PRDiscountNo, VIN)`.
app.MapPost("/api/paymentreqdiscounts/{no}/htc-amounts", async (string no, PrdHtcAmountDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim();
    var h = await db.PaymentReqDiscounts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PRDiscountNo == no);
    if (h is null) return Results.NotFound(new { no });
    if (h.Status is not ("A1" or "A2"))
        return Results.BadRequest(new { error = $"Đề nghị đang ở '{h.Status}' — chỉ cập nhật số tiền HTC duyệt sau khi đã duyệt (A1 hoặc A2)." });
    var rows = dto.Lines ?? new List<PrdHtcAmountLineDto>();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Chưa có dữ liệu" });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    int updated = 0;
    foreach (var r in rows)
    {
        var vin = (r.Vin ?? "").Trim().ToUpperInvariant();
        var l = await db.PaymentReqDiscountVins.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PRDiscountNo == no && x.VIN == vin);
        if (l is null) return Results.BadRequest(new { error = $"VIN {vin} không thuộc đề nghị {no}.", vin });
        // `UpdateMulti_InvalidAmountHTCAppr`
        if (r.AmountHTCAppr < 0) return Results.BadRequest(new { error = $"VIN {vin}: số tiền HTC duyệt không hợp lệ.", vin });
        l.AmountHTCAppr = r.AmountHTCAppr;
        l.HTCApprDate = r.HTCApprDate ?? now;
        if (!string.IsNullOrWhiteSpace(r.CustomerName)) l.CustomerName = r.CustomerName;
        if (r.AmountDealerRequest is not null) l.AmountDealerRequest = r.AmountDealerRequest.Value;
        l.LogLUDateTime = now; l.LogLUBy = who; l.UpdatedAt = now;
        updated++;
    }
    h.LogLUDateTime = now; h.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.PRDiscountNo, h.Status, updated });
}).RequireAuthorization();

// ===== Hỗ trợ bán lẻ theo VIN (SPSupportRetail — port 1:1 FrmPolicySales_Mng, 2010.HTC/Sales) =====
// CHÚ Ý: gốc DateFullStatus tự tính qua join SO/DO/HTCInvoice/PaymentReqDiscount (SPL_SPSupportRetail_Calc_DateFullStatus) — ở đây nhập tay (đơn giản hoá, xem ghi chú entity).
app.MapGet("/api/spsupportretails", async (AppDbContext db, ITenantContext t, string? vin, string? spsrCode, string? dealer) =>
{
    var qry = db.SPSupportRetails.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(vin)) qry = qry.Where(x => x.VIN.Contains(vin!.Trim().ToUpperInvariant()));
    if (!string.IsNullOrWhiteSpace(spsrCode)) qry = qry.Where(x => x.SPSRCode == spsrCode.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(dealer)) qry = qry.Where(x => x.DealerCode == dealer.Trim().ToUpperInvariant());
    var items = await qry.OrderByDescending(x => x.Id).Take(500).Select(x => new
    { x.VIN, x.SPSRCode, x.DealerCode, x.SpecCode, x.ModelCode, x.PRDiscountNo, x.AmountSupport, x.DateSupport, x.DateFullStatus, x.HTCInvoiceNo, x.HTCInvoiceDate, x.Remark }).ToListAsync();
    return Results.Ok(new { count = items.Count, totalAmount = items.Sum(x => x.AmountSupport), items });
}).RequireAuthorization();

// Tạo hàng loạt (khớp btnSave_Click/SPL_SPSupportRetail_Create gốc) — guard VIN + Số chính sách bắt buộc.
app.MapPost("/api/spsupportretails", async (SPSupportRetailImportDto dto, AppDbContext db, ITenantContext t) =>
{
    var rows = dto.Rows ?? new List<SPSupportRetailRowDto>();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dòng để lưu" });
    foreach (var r in rows)
    {
        if (string.IsNullOrWhiteSpace(r.Vin)) return Results.BadRequest(new { error = "VIN không để trống" });
        if (string.IsNullOrWhiteSpace(r.SPSRCode)) return Results.BadRequest(new { error = "Số chính sách không để trống" });
        // Biz.HTC.WH.cs SPL_SPSupportRetail_Create: PRD_PaymentReqDiscount_CheckDB bắt buộc PRDiscountNo tồn tại + đã duyệt (strConfirmStatusListToCheck "A2").
        if (string.IsNullOrWhiteSpace(r.PRDiscountNo)) return Results.BadRequest(new { error = $"VIN {r.Vin}: thiếu số đề nghị chiết khấu (PRDiscountNo)." });
    }
    // Biz.HTC.WH.cs SPL_SPSupportRetail_Create: strKeyDetail = |VIN|SPSRCode| — chặn trùng key trong cùng batch trước khi ghi.
    var dupKey = rows.GroupBy(r => (r.Vin!.Trim().ToUpperInvariant(), r.SPSRCode!.Trim().ToUpperInvariant())).FirstOrDefault(g => g.Count() > 1);
    if (dupKey != null) return Results.BadRequest(new { error = $"Trùng (VIN {dupKey.Key.Item1} × SPSRCode {dupKey.Key.Item2}) trong file." });
    var prdCodes = rows.Select(r => r.PRDiscountNo!.Trim()).ToHashSet();
    var prdStatusByCode = await db.PaymentReqDiscounts.Where(x => x.OrgId == t.OrgId && prdCodes.Contains(x.PRDiscountNo)).ToDictionaryAsync(x => x.PRDiscountNo, x => x.Status);
    foreach (var r in rows)
    {
        var prd = r.PRDiscountNo!.Trim();
        if (!prdStatusByCode.TryGetValue(prd, out var prdStatus))
            return Results.BadRequest(new { error = $"VIN {r.Vin}: không tìm thấy đề nghị chiết khấu {prd}." });
        // 🔴 #128: mã trạng thái đúng của nguồn là "A1"/"A2" (TConst.PRDiscountStatus), không phải "Approved1/2".
        if (prdStatus is not ("A1" or "A2"))
            return Results.BadRequest(new { error = $"VIN {r.Vin}: đề nghị chiết khấu {prd} chưa được duyệt (hiện {prdStatus})." });
    }
    // Biz.HTC.WH.cs SPL_SPSupportRetail_Create: VIN phải tồn tại trong Car_Vin+Car_Car; DealerCode/SpecCode/ModelCode LẤY TỪ VIN master (ghi đè giá trị caller gửi), không tin caller.
    var vins = rows.Select(r => r.Vin!.Trim().ToUpperInvariant()).ToHashSet();
    var vinMasterByVin = await db.CarVinMasters.Where(x => x.OrgId == t.OrgId && vins.Contains(x.VIN)).ToDictionaryAsync(x => x.VIN, x => x);
    foreach (var r in rows)
    {
        var vin = r.Vin!.Trim().ToUpperInvariant();
        if (!vinMasterByVin.ContainsKey(vin))
            return Results.BadRequest(new { error = $"VIN {vin}: không tìm thấy trong danh mục xe (Car_Vin)." });
    }
    // Biz.HTC.WH.cs SPL_SPSupportRetail_Create: SPSRCode+Spec+Model(+Dealer) phải eligible trong SPL_SalesPolicyMstDetail (áp mọi đại lý) hoặc MstDetailDealer (riêng đại lý đó).
    var spsrCodes = rows.Select(r => r.SPSRCode!.Trim().ToUpperInvariant()).ToHashSet();
    var eligRows = await db.SalesPolicyEligibilities.Where(x => x.OrgId == t.OrgId && spsrCodes.Contains(x.SPSRCode)).ToListAsync();
    foreach (var r in rows)
    {
        var vin = r.Vin!.Trim().ToUpperInvariant();
        var vm = vinMasterByVin[vin];
        var spsr = r.SPSRCode!.Trim().ToUpperInvariant();
        var eligible = eligRows.Any(e => e.SPSRCode == spsr && e.ModelCode == vm.ModelCode && e.SpecCode == vm.SpecCode && (e.DealerCode == null || e.DealerCode == vm.DealerCode));
        if (!eligible)
            return Results.BadRequest(new { error = $"VIN {vin}: chính sách {spsr} không áp dụng cho model/spec/đại lý này." });
    }
    foreach (var r in rows)
    {
        var vin = r.Vin!.Trim().ToUpperInvariant();
        var vm = vinMasterByVin[vin];
        db.SPSupportRetails.Add(new SPSupportRetail
        {
            OrgId = t.OrgId, VIN = vin, SPSRCode = r.SPSRCode!.Trim().ToUpperInvariant(), DealerCode = vm.DealerCode,
            SpecCode = vm.SpecCode, ModelCode = vm.ModelCode, PRDiscountNo = r.PRDiscountNo!.Trim(), AmountSupport = r.AmountSupport, DateSupport = r.DateSupport ?? DateTime.Now,
            DateFullStatus = r.DateFullStatus, HTCInvoiceNo = r.HTCInvoiceNo, HTCInvoiceDate = r.HTCInvoiceDate, Remark = r.Remark
        });
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { added = rows.Count });
}).RequireAuthorization();

