// Tạo đơn hàng gốc (khớp DMS40_Ord_SalesOrderRoot_Save flagIsDelete=0 gốc)
app.MapPost("/api/dms40/soroots", async (Dms40SoRootDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Cần mã đại lý." });
    // WinForm line 810: OrderMonth bắt buộc
    if (dto.OrderMonth is null) return Results.BadRequest(new { error = "Chưa chọn tháng đơn hàng." });
    var lines = dto.Lines ?? new List<Dms40SoRootLineDto>();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu model." });

    var no = string.IsNullOrWhiteSpace(dto.SORCode) ? "SOR" + DateTime.Now.ToString("yyMMddHHmmss") : dto.SORCode.Trim().ToUpperInvariant();
    if (await db.Dms40SoRoots.AnyAsync(x => x.OrgId == t.OrgId && x.SORCode == no))
        return Results.BadRequest(new { error = $"Số {no} đã tồn tại!" });
    var h = new Dms40SoRoot { OrgId = t.OrgId, SORCode = no, SOType = dto.SOType, DealerCode = dto.DealerCode.Trim().ToUpperInvariant(), SPCode = dto.SPCode, OrderMonth = dto.OrderMonth, Status = "P" };
    db.Dms40SoRoots.Add(h); await db.SaveChangesAsync();
    foreach (var l in lines)
        db.Dms40SoRootDetails.Add(new Dms40SoRootDetail { OrgId = t.OrgId, SoRootId = h.Id, ModelCode = l.ModelCode, SpecCode = l.SpecCode, ColorCode = l.ColorCode, UnitPriceInit = l.UnitPriceInit, RequestedQuantity = l.RequestedQuantity, Remark = l.Remark,
            RequestedDate = l.RequestedDate, SORStatusDtl = "P" });
    await db.SaveChangesAsync();
    return Results.Ok(new { h.SORCode, h.Status, lines = lines.Count });
}).RequireAuthorization();

// Duyệt số lượng theo dòng (khớp btnApprove_Click/DMS40_Ord_SalesOrderRoot_Approve gốc: P→A) — Approved1Quantity theo ModelCode+SpecCode+ColorCode.
// ===== #B88 VÁ PARITY `FlagAuto` — `DMS40_Ord_SalesOrderRoot_ApproveX_New20181119` =====
// Nguồn: `Biz.HTC.WH.cs:76363`. 3B đo thật: md5 **khớp cả 2 máy** `7d29c5f7e3dc6892be89b5088d3d88ab`
//   (start lệch 76363/76368 — bình thường, định vị bằng TÊN, xem `C0-…quinquagesimusprimus`).
// 🔴 **`objFlagAuto` NỚI HAI THỨ CÙNG LÚC** (`bIsAuto = StringEqual(objFlagAuto, Flag.Yes)`):
//    1) **Trạng thái được phép**: `!bIsAuto` ⇒ chỉ **`"P"`**; `bIsAuto` ⇒ **`"P, A"`**
//       (tức chế độ tự động **được duyệt LẠI** đơn đã duyệt).
//    2) **RBAC**: `!bIsAuto` mới chạy `myCommon_CheckHTCDirect(…)`; `bIsAuto` thì **BỎ QUA kiểm quyền**
//       (job nền không có người dùng).
//    ⚠️ Vì cờ này **vừa nới trạng thái vừa tắt RBAC**, để client tự bật được nó là **mở đường vòng
//      qua phân quyền**. Port **KHÔNG** nhận `flagAuto` từ body; chỉ luồng nội bộ (`Spp_Dls_Deal_Update`,
//      job tự động) mới truyền `"1"`.
// 🔴 Hàm hỗ trợ **`Spp_Dls_Deal_Update`** (`DataWH/Biz.HTC.Support.cs:22`) **chỉ là VỎ**: gọi thẳng
//    `…_ApproveX_New20181119` với `objFlagAuto = TConst.Flag.**Inactive**` ⇒ **KHÔNG** bật chế độ auto,
//    tức vẫn kiểm `"P"` và vẫn kiểm quyền. ⚠️ **Không có lời gọi nào** tới `Spp_Dls_Deal_Update` trong
//    `TERP.WSHTC.64/` lẫn `TERP.HTCClient/` ⇒ **không lộ ra qua WS**; là cửa hỗ trợ chạy tay.
//    Vì hành vi của nó **trùng khít** endpoint approve này, KHÔNG đẻ route riêng.
app.MapPost("/api/dms40/soroots/{no}/approve", async (string no, Dms40SoRootApproveDto dto, AppDbContext db, ITenantContext t, [Microsoft.AspNetCore.Mvc.FromQuery] string? flagAuto) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.Dms40SoRoots.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SORCode == no);
    if (h is null) return Results.NotFound(new { no });
    // 🔴 #B88: `flagAuto` CHỈ dành cho luồng nội bộ — không đọc từ body (xem khối chú thích trên).
    var isAuto = flagAuto == "1";
    // `!bIsAuto` ⇒ chỉ "P"; `bIsAuto` ⇒ "P, A" (auto được duyệt LẠI đơn đã duyệt).
    var allowed = isAuto ? new[] { "P", "A" } : new[] { "P" };
    if (!allowed.Contains(h.Status))
        return Results.BadRequest(new
        {
            error = "DMS40_Ord_SalesOrderRoot_Approve_InvalidStatus",
            check = new { h.SORCode, h.Status, Allowed = string.Join(", ", allowed), FlagAuto = isAuto ? "1" : "0" }
        });
    var rows = dto.Lines ?? new List<Dms40SoRootApproveLineDto>();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu được duyệt." });
    var lines = await db.Dms40SoRootDetails.Where(l => l.OrgId == t.OrgId && l.SoRootId == h.Id).ToListAsync();
    int updated = 0;
    foreach (var r in rows)
    {
        var l = lines.FirstOrDefault(x => x.ModelCode == r.ModelCode && x.SpecCode == r.SpecCode && x.ColorCode == r.ColorCode);
        if (l is null) continue;
        if (r.Approved1Quantity > l.RequestedQuantity) return Results.BadRequest(new { error = $"Model {r.ModelCode}: số lượng duyệt vượt số lượng yêu cầu." });
        l.Approved1Quantity = r.Approved1Quantity;
        // #163: nguồn ghi NGÀY duyệt cấp 1 theo TỪNG DÒNG — bước hoàn tất đọc lại cột này
        // để map sang `ApprovedDate` của dòng đơn bán, và để sao sang `Approved2Date`.
        l.Approved1Date = r.Approved1Date ?? DateTime.Now;
        l.SORStatusDtl = "A";
        updated++;
    }
    h.Status = "A"; h.ApprDTime = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.SORCode, h.Status, updated });
}).RequireAuthorization();

// ===== #163 hoàn tất đơn hàng gốc DMS40 — `DMS40_Ord_SalesOrderRoot_Finish_New20210521` =====
// Nguồn: `TERP.BizHTC/DataWH/BizHTC.Order.cs:1478` (csproj 315), thân thật ở `..._FinishX_New20210521`.
// 🔴 TWIN: WS **64-bit** gọi `_New20210521`; WS **32-bit** vẫn gọi `_New20181119` (Biz.HTC.WH.cs:76779) ⇒ LIVE là bản 2021.
// BƯỚC 3B: hàm bắt đầu **cùng dòng 1478 ở CẢ HAI máy**, vùng 2551 dòng md5 `22c18bb1` KHỚP.
//
// 🔴 Port cũ chỉ làm HAI việc (đổi `Status = "F"` + `Approved2Quantity = Approved1Quantity`) — mất hẳn phần
//    NẶNG NHẤT của nghiệp vụ: hoàn tất đơn gốc là **TỰ SINH RA MỘT ĐƠN BÁN (`Ord_SalesOrder`) đã duyệt sẵn**.
app.MapPost("/api/dms40/soroots/{no}/finish", async (string no, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;

    var h = await db.Dms40SoRoots.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SORCode == no);
    if (h is null) return Results.NotFound(new { no });
    // `DMS40_Ord_SalesOrderRoot_CheckDB(..., strStatusListToCheck: SORStatus.Approved)`
    if (h.Status != "A") return Results.BadRequest(new { error = "Chỉ có thể hoàn tất khi trạng thái là A (đã duyệt)." });

    // `myCommon_CheckDealer(..., FlagExist: Active, FlagActiveList: Active)` — đại lý phải TỒN TẠI và còn HOẠT ĐỘNG.
    var dlr = await db.Dealers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == h.DealerCode);
    if (dlr is null) return Results.BadRequest(new { error = $"Đại lý {h.DealerCode} không tồn tại." });
    if (dlr.FlagActive != "1") return Results.BadRequest(new { error = $"Đại lý {h.DealerCode} đang ngừng hoạt động." });

    // 🔴 SINH MÃ ĐƠN BÁN THEO CHÍNH SÁCH BÁN — quy tắc HẬU TỐ của nguồn, và là một GUARD CHẶN:
    //    CSC → giữ nguyên mã đơn gốc; KCK/CCK/DLM/NG → mã gốc + "." + mã chính sách;
    //    chính sách khác (kể cả `CKTT` có trong bảng hằng) → LỖI `NotAllowSPCode`, KHÔNG cho hoàn tất.
    var sp = (h.SPCode ?? "").Trim().ToUpperInvariant();
    string soCode;
    if (sp == "CSC") soCode = h.SORCode;
    else if (sp is "KCK" or "CCK" or "DLM" or "NG") soCode = h.SORCode + "." + sp;
    else return Results.BadRequest(new { error = $"Chính sách bán \"{sp}\" không được phép hoàn tất đơn hàng gốc (chỉ CSC/KCK/CCK/DLM/NG).", sorCode = h.SORCode, spCode = sp });

    var lines = await db.Dms40SoRootDetails.Where(l => l.OrgId == t.OrgId && l.SoRootId == h.Id).ToListAsync();

    // ---- Sinh đơn bán: nguồn chạy chuỗi OrderSOCreateX → OrderSOApprove1X → OrderSOApprove2X ----
    //      ⇒ đơn bán ra đời ở trạng thái **A2 (đã duyệt cấp 2)** ngay, không qua tay người duyệt.
    //      Chỉ lấy dòng có `Approved1Quantity > 0` (điều kiện `where t.Approved1Quantity > 0` trong SQL nguồn).
    string? generated = null;
    var srcLines = lines.Where(l => l.Approved1Quantity > 0).ToList();
    if (srcLines.Count > 0)
    {
        if (await db.SalesOrders.AnyAsync(x => x.OrgId == t.OrgId && x.SoCode == soCode))
            return Results.BadRequest(new { error = $"Đơn bán {soCode} đã tồn tại — đơn hàng gốc này có thể đã được hoàn tất.", soCode });

        var so = new SalesOrder
        {
            OrgId = t.OrgId,
            SoCode = soCode,
            // Nguồn bê nguyên `SOType` và `DealerCode` của đơn gốc sang đơn bán.
            OrderType = string.IsNullOrWhiteSpace(h.SOType) ? "Plan" : h.SOType!,
            DealerCode = h.DealerCode,
            SPCode = sp,
            // Chuỗi Create→Approve1→Approve2 chạy liền ⇒ trạng thái cuối là "A2".
            Status = "A2",
            CreatedAt = now, Approved1At = now, Approved2At = now, ApprovedBy1 = who
        };
        db.SalesOrders.Add(so);
        await db.SaveChangesAsync();

        foreach (var l in srcLines)
            db.SalesOrderLines.Add(new SalesOrderLine
            {
                OrgId = t.OrgId, SalesOrderId = so.Id,
                ModelCode = l.ModelCode ?? "", SpecCode = l.SpecCode, ColorCode = l.ColorCode,
                RequestedQuantity = (int)l.RequestedQuantity, RequestedDate = l.RequestedDate,
                UnitPrice = l.UnitPriceInit, UnitPriceInit = l.UnitPriceInit,
                // `t.Approved1Quantity AS ApprovedQuantity` · `t.Approved1Date AS ApprovedDate` trong SQL nguồn.
                ApprovedQuantity = (int)l.Approved1Quantity, ApprovedDate = l.Approved1Date,
                MapVINRanking = 5.0m,     // Approve1 của nguồn gán CỨNG 5.0
                Remark = l.Remark
            });
        generated = soCode;
    }

    // ---- SaveDB: cập nhật header và TỪNG DÒNG của đơn gốc ----
    h.Status = "F"; h.FinishDTime = now; h.FinishBy = who; h.GeneratedSoCode = generated;
    foreach (var l in lines)
    {
        l.Approved2Quantity = l.Approved1Quantity;
        // Nguồn sao chép `Approved2Date = Approved1Date` (không nhập tay) và ghi trạng thái RIÊNG của dòng.
        l.Approved2Date = l.Approved1Date;
        l.SORStatusDtl = "F";
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { h.SORCode, h.Status, h.FinishDTime, h.FinishBy, generatedSoCode = generated, soLines = srcLines.Count });
}).RequireAuthorization();

// ===== 🔴 #208 HUỶ ĐƠN GỐC — `DMS40_Ord_SalesOrderRoot_Cancel1` (78681) / `Cancel2` (79242) =====
// Nguồn: `DataWH/Biz.HTC.WH.cs` (csproj <Compile> 272). TWIN FILE: hai hàm này CÒN ở
//   `DataWH/Biz.HTC.WH.Rel.20230823.cs` (74835/75396) — file đó KHÔNG có trong csproj ⇒ **FILE CHẾT** (xác định ở #200).
//
// 🔴 BƯỚC 3B — bài học đo đúng: md5 theo SỐ DÒNG cố định (78681-79800) cho kết quả LỆCH giữa 2 máy
//   (`2325b86e` vs `07dfeaa7`), nhưng diff cho thấy chỉ là **lệch offset 5 dòng** — bản 150 có thêm 5 dòng
//   ở TRƯỚC vùng này. Căn lại theo **MỐC HÀM** (150 tại 78686): md5 = `2325b86e` **KHỚP**. Nội dung y hệt.
//
// Hai lệnh, hai guard khác nhau — port cũ gộp thành một điều kiện `P or A` (đúng về TẬP HỢP, nên giữ),
//   nhưng bỏ sót phần GHI:
//     `Cancel1`: guard `SORStatus = SORStatus.Pending` ("P")   → `SORStatus = "C"`
//     `Cancel2`: guard `SORStatus = SORStatus.Approved` ("A")  → `SORStatus = "C"`
//   Cả hai đều ghi `CancelDTime` · `CancelBy` · `LogLUDateTime` · `LogLUBy`,
//   và 🔴 **CASCADE** `DMS40_Ord_SalesOrderRootDetail.SORStatusDtl = "C"` + `LogLU*` trên MỌI dòng chi tiết.
app.MapPost("/api/dms40/soroots/{no}/cancel", async (string no, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.Dms40SoRoots.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SORCode == no);
    if (h is null) return Results.NotFound(new { no });
    // Giữ điều kiện gộp: `Cancel1` nhận "P", `Cancel2` nhận "A" — hợp lại đúng bằng tập {P, A}.
    if (h.Status is not ("P" or "A")) return Results.BadRequest(new { error = "Chỉ có thể hủy khi trạng thái là P hoặc A." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var branch = h.Status == "P" ? "Cancel1" : "Cancel2";   // ghi lại nhánh nguồn tương ứng
    h.Status = "C";
    h.CancelDTime = now; h.CancelBy = who;
    h.LogLUDateTime = now; h.LogLUBy = who;

    var dtls = await db.Dms40SoRootDetails.Where(x => x.OrgId == t.OrgId && x.SoRootId == h.Id).ToListAsync();
    foreach (var d in dtls) { d.SORStatusDtl = "C"; d.LogLUDateTime = now; d.LogLUBy = who; }

    await db.SaveChangesAsync();
    return Results.Ok(new { h.SORCode, h.Status, h.CancelDTime, h.CancelBy, branch, cancelledDetailRows = dtls.Count });
}).RequireAuthorization();

// ===== Mẫu hợp đồng của đại lý (DealerContractForm — port 1:1 FrmDlr_Mst_DealerContractForm, 2010.HTC) =====
app.MapGet("/api/dealercontractforms", async (AppDbContext db, ITenantContext t, string? dealer, string? q, bool? all) =>
{
    var qry = db.DealerContractForms.Where(x => x.OrgId == t.OrgId);
    if (all != true) qry = qry.Where(x => x.FlagActive == "1");
    if (!string.IsNullOrWhiteSpace(dealer)) qry = qry.Where(x => x.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(q)) qry = qry.Where(x => x.ContractFNo.Contains(q!) || x.ContractFName!.Contains(q!));
    var items = await qry.OrderBy(x => x.DealerCode).Take(500).Select(x => new { x.Id, x.DealerCode, x.ContractFNo, x.ContractFName, x.FlagActive }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/dealercontractforms", async (DealerContractFormDto dto, AppDbContext db, ITenantContext t) =>
{
