// 🔴 DUYỆT 2 CẤP + HUỶ DUYỆT — `Plan_EstimateOrder_Appr1` (BizHTC.zTemp.cs:54702) ·
// `_Appr2`→`_Appr2X` (55070→54820) · `_Cancel`→`_CancelX` (55440→55189).
// ⚠️ Port cũ chỉ có một bước `confirm` — mất cả hai cấp duyệt lẫn đường huỷ duyệt.
// ⚠️ **Nguồn làm THEO LÔ**: cả ba hàm nhận một BẢNG `Plan_EstimateOrder` nhiều dòng và
//    `foreach` từng `PLEOrdNo` — port cũ hạ xuống thao tác từng đơn. Endpoint này nhận danh sách số đơn.
// ⚠️ Bẫy tên đã kiểm: hàm public `_Appr2` là DUYỆT cấp 2 (gọi `_Appr2X`), còn phần đặt lại "P"
//    nằm ở `_CancelX` — đọc lướt rất dễ gán nhầm nhánh.
app.MapPost("/api/estimateorders/{action}", async (string action, EstOrderApproveDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (action is not ("approve" or "approve2" or "cancel"))
        return Results.BadRequest(new { error = "action = approve (cấp 1) | approve2 (cấp 2) | cancel (huỷ duyệt)" });
    var nos = (dto.OrderNos ?? new()).Where(x => !string.IsNullOrWhiteSpace(x)).Select(x => x.Trim().ToUpperInvariant()).Distinct().ToList();
    if (nos.Count == 0) return Results.BadRequest(new { error = "Chưa chọn đơn dự kiến nào." });

    var rows = await db.EstimateOrders.Where(x => x.OrgId == t.OrgId && nos.Contains(x.EstOrderNo)).ToListAsync();
    var missing = nos.Except(rows.Select(x => x.EstOrderNo)).ToList();
    if (missing.Count > 0) return Results.BadRequest(new { error = $"Không tìm thấy đơn: {string.Join(", ", missing)}" });

    // Guard trạng thái của nguồn: Appr1 vào từ "P"; Appr2 vào từ "A1"; Cancel vào từ "A1" HOẶC "A2".
    string[] from = action switch { "approve" => new[] { "P" }, "approve2" => new[] { "A1" }, _ => new[] { "A1", "A2" } };
    var bad = rows.FirstOrDefault(x => !from.Contains(x.Status));
    if (bad is not null)
        return Results.BadRequest(new { error = $"Đơn {bad.EstOrderNo} đang ở trạng thái '{bad.Status}' — yêu cầu {string.Join("/", from)}." });

    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    foreach (var h in rows)
    {
        if (action == "approve") { h.Status = "A1"; h.Appr1DTime = now; h.Appr1By = who; }
        else if (action == "approve2") { h.Status = "A2"; h.Appr2DTime = now; h.Appr2By = who; }
        else { h.Status = "P"; h.CancelDTime = now; h.CancelBy = who; }   // huỷ duyệt: trả về "P", KHÔNG xoá đơn
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { action, affected = rows.Count, status = rows[0].Status });
}).RequireAuthorization();

// ===== Ánh xạ xe ↔ đơn hàng SX (WOMapping — port 1:1 FrmWO_Mapping, 2010.HTC/Sales) =====
app.MapGet("/api/womappings", async (AppDbContext db, ITenantContext t, string? car, string? so) =>
{
    var q = db.WOMappings.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(car)) q = q.Where(x => x.CarId.Contains(car!));
    if (!string.IsNullOrWhiteSpace(so)) q = q.Where(x => x.SoCode == so);
    var items = await q.OrderBy(x => x.CarId).Take(1000)
        .Select(x => new { x.Id, x.CarId, x.ColorCode, x.ColorNameVN, x.Description, x.SoCode, x.WorkOrderNoTemp }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/womappings", async (WOMappingDto dto, AppDbContext db, ITenantContext t) =>
{
    var cid = (dto.CarId ?? "").Trim().ToUpperInvariant();
    if (cid == "") return Results.BadRequest(new { error = "Thiếu mã xe (CarID/VIN)." });
    // WinForm line 175: WorkOrderNoTemp bắt buộc
    if (string.IsNullOrWhiteSpace(dto.WorkOrderNoTemp)) return Results.BadRequest(new { error = "Chưa nhập WorkOrder tạm cho xe này." });
    var w = await db.WOMappings.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CarId == cid);
    if (w is null) { w = new WOMapping { OrgId = t.OrgId, CarId = cid }; db.WOMappings.Add(w); }
    w.ColorCode = dto.ColorCode; w.ColorNameVN = dto.ColorNameVN; w.Description = dto.Description; w.SoCode = dto.SoCode;
    w.WorkOrderNoTemp = dto.WorkOrderNoTemp!.Trim(); w.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { w.Id, w.CarId, w.WorkOrderNoTemp });
}).RequireAuthorization();

// ===== Kế hoạch bán hàng theo quý (SalePlan — port 1:1 FrmSalePlan, 2010.HTC/Sales) =====
app.MapGet("/api/saleplans", async (AppDbContext db, ITenantContext t, string? dealer, int? year, string? model) =>
{
    var q = db.SalePlans.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(x => x.DealerCode == dealer);
    if (year.HasValue) q = q.Where(x => x.YearPlan == year.Value);
    if (!string.IsNullOrWhiteSpace(model)) q = q.Where(x => x.ModelCode == model);
    var items = await q.OrderBy(x => x.DealerCode).ThenBy(x => x.ModelCode).Take(500)
        .Select(x => new { x.Id, x.DealerCode, x.ModelCode, x.YearPlan, x.Q1, x.Q2, x.Q3, x.Q4, total = x.Q1 + x.Q2 + x.Q3 + x.Q4, x.FlagActive }).ToListAsync();
    return Results.Ok(new { count = items.Count, grandTotal = items.Sum(i => i.total), items });
}).RequireAuthorization();

app.MapPost("/api/saleplans", async (SalePlanDto dto, AppDbContext db, ITenantContext t) =>
{
    var dc = (dto.DealerCode ?? "").Trim(); var mc = (dto.ModelCode ?? "").Trim();
    if (dc == "" || mc == "") return Results.BadRequest(new { error = "Thiếu mã đại lý hoặc model." });
    if (dto.YearPlan < 2000 || dto.YearPlan > 2100) return Results.BadRequest(new { error = "Năm kế hoạch không hợp lệ." });
    if (dto.Q1 < 0 || dto.Q2 < 0 || dto.Q3 < 0 || dto.Q4 < 0) return Results.BadRequest(new { error = "Số lượng quý không được âm." });
    var p = await db.SalePlans.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == dc && x.ModelCode == mc && x.YearPlan == dto.YearPlan);
    if (p is null) { p = new SalePlan { OrgId = t.OrgId, DealerCode = dc, ModelCode = mc, YearPlan = dto.YearPlan }; db.SalePlans.Add(p); }
    p.Q1 = dto.Q1; p.Q2 = dto.Q2; p.Q3 = dto.Q3; p.Q4 = dto.Q4; p.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { p.Id, p.DealerCode, p.ModelCode, p.YearPlan, total = p.Q1 + p.Q2 + p.Q3 + p.Q4 });
}).RequireAuthorization();

app.MapPost("/api/saleplans/{id}/toggle", async (long id, AppDbContext db, ITenantContext t) =>
{
    var p = await db.SalePlans.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (p is null) return Results.NotFound(new { id });
    p.FlagActive = p.FlagActive == "1" ? "0" : "1"; p.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { p.Id, p.FlagActive });
}).RequireAuthorization();

// ===== Thông tin thùng xe tải (CabinInfo — port 1:1 FrmUpdate_Cabin, 2010.HTC/Sales) =====
app.MapGet("/api/cabininfos", async (AppDbContext db, ITenantContext t, string? vin, bool? onlyMissing) =>
{
    var q = db.CabinInfos.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(vin)) q = q.Where(x => x.Vin.Contains(vin!));
    if (onlyMissing == true) q = q.Where(x => x.CabinCertificateNo == null || x.CabinCertificateNo == "");
    var items = await q.OrderBy(x => x.Vin).Take(1000).Select(x => new
    {
        x.Id, x.Vin, x.SpecCode, x.CabinCertificateNo,
        cabinCertificateDate = x.CabinCertificateDate.HasValue ? x.CabinCertificateDate.Value.ToString("yyyy-MM-dd") : "",
        x.CabinCONo, x.CabinInvoiceNo,
        cabinInvoiceDate = x.CabinInvoiceDate.HasValue ? x.CabinInvoiceDate.Value.ToString("yyyy-MM-dd") : ""
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();


