// ===== #B21 CẬP NHẬT THÔNG TIN TỜ TRÌNH TRÊN ĐỀ NGHỊ GIAO HỒ SƠ (port 1:1 `FrmUpdateDocReq`) =====
// Trace twin LIVE: `FrmUpdateDocReq.cs:145` → `salesSv.CarDocReqListUpdate_LetterRepresentationInfo(tableSave)`
//   (`SalesService.cs:25842`) → WS (`WSHTC.asmx.cs:39104`)
//   → **`_biz.CarDocReqListUpdate_LetterRepresentationInfo`** (`BizHTC.zTemp.cs:10651`).
//   Input là **BẢNG**; `MyBuildDBDT_Common` khoá theo **`DRListCode`** ⇒ ghi ở **ĐẦU đề nghị**, không phải dòng xe.
// 🔴 LUẬT "BỘ BA TẤT CẢ-HOẶC-KHÔNG": `LetterRepresentationNo`, `LetterRepresentationDate`, `LoanSupportDay`
//    phải **cùng có** hoặc **cùng rỗng**. Nguồn viết thành BA guard đối xứng (`:10780-10828`), mỗi guard bắt
//    một trường có giá trị mà một trong hai trường kia rỗng:
//      · có No mà thiếu (Day hoặc Date)   → `..._InvalidLoanSupportDayOrLetterRepresentationDate`
//      · có Date mà thiếu (Day hoặc No)   → `..._InvalidLoanSupportDayOrLetterRepresentationNo`
//      · có Day mà thiếu (Date hoặc No)   → `..._InvalidLetterRepresentationDateOrLetterRepresentationNo`
// 🔴 `LoanSupportDay < 0` → `..._InvalidLoanSupportDay` (nguồn `Convert.ToInt16`, chặn số ÂM, cho phép 0).
app.MapPost("/api/docreqs/update-letter-representation", async (
    List<DocReqLetterRepDto> rows, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    // `..._TableBlank`
    if (rows is null || rows.Count == 0) return Results.BadRequest(new { error = "Bảng đề nghị cần cập nhật đang rỗng." });
    var list = rows.Where(r => !string.IsNullOrWhiteSpace(r.DRListCode)).ToList();
    if (list.Count == 0) return Results.BadRequest(new { error = "Bảng đề nghị cần cập nhật đang rỗng." });

    var codes = list.Select(r => r.DRListCode!.Trim()).ToList();
    var reqs = await db.DocReqs.Where(x => x.OrgId == t.OrgId && codes.Contains(x.DocReqNo)).ToListAsync();

    foreach (var r in list)
    {
        var code = r.DRListCode!.Trim();
        // `Car_DocReqList_CheckDB(..., TConst.Flag.Yes)` — đề nghị phải tồn tại.
        if (!reqs.Any(x => x.DocReqNo == code)) return Results.BadRequest(new { error = $"Đề nghị {code} không tồn tại." });

        var hasNo = !string.IsNullOrWhiteSpace(r.LetterRepresentationNo);
        var hasDate = r.LetterRepresentationDate is not null;
        var hasDay = r.LoanSupportDay is not null;
        if (hasDay && r.LoanSupportDay < 0)
            return Results.BadRequest(new { error = $"Đề nghị {code}: số ngày hỗ trợ vay vốn không được âm.", drListCode = code, loanSupportDay = r.LoanSupportDay });
        if (hasNo && (!hasDay || !hasDate))
            return Results.BadRequest(new { error = $"Đề nghị {code}: có số tờ trình thì phải có CẢ ngày tờ trình và số ngày hỗ trợ vay vốn.", drListCode = code });
        if (hasDate && (!hasDay || !hasNo))
            return Results.BadRequest(new { error = $"Đề nghị {code}: có ngày tờ trình thì phải có CẢ số tờ trình và số ngày hỗ trợ vay vốn.", drListCode = code });
        if (hasDay && (!hasDate || !hasNo))
            return Results.BadRequest(new { error = $"Đề nghị {code}: có số ngày hỗ trợ vay vốn thì phải có CẢ số tờ trình và ngày tờ trình.", drListCode = code });
    }

    var who = user.Identity?.Name ?? "system"; var now = DateTime.Now;
    int updated = 0;
    foreach (var r in list)
    {
        var d = reqs.First(x => x.DocReqNo == r.DRListCode!.Trim());
        // 6 cột của `MyBuildDBDT_Common` (:10844-10850): DRListCode (khoá) + 3 trường + LogLU*.
        // Bộ ba ghi VÔ ĐIỀU KIỆN (kể cả về null) vì luật trên đã bảo đảm chúng cùng có hoặc cùng rỗng.
        d.LetterRepresentationNo = string.IsNullOrWhiteSpace(r.LetterRepresentationNo) ? null : r.LetterRepresentationNo!.Trim();
        d.LetterRepresentationDate = r.LetterRepresentationDate;
        d.LoanSupportDay = r.LoanSupportDay;
        d.LogLUDateTime = now; d.LogLUBy = who;
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        updated,
        columnsWritten = new[] { "LetterRepresentationNo", "LetterRepresentationDate", "LoanSupportDay", "LogLUDateTime", "LogLUBy" },
        tripleRule = "Ba trường tờ trình phải CÙNG CÓ hoặc CÙNG RỖNG (3 guard đối xứng của nguồn); LoanSupportDay >= 0.",
        tableNote = "Nguồn khoá theo DRListCode ⇒ ghi ở ĐẦU đề nghị (Car_DocReqList). Port cũ đặt nhầm 3 cột này trên DÒNG XE (DocReqCar) — cột cũ giữ nguyên để không phá dữ liệu."
    });
}).RequireAuthorization();

// ===== #B27 CẬP NHẬT HÀNG LOẠT CỜ "ĐÃ LẬP ĐỀ NGHỊ GIAO HỒ SƠ" (port 1:1 `FrmCapNhatThongTinHoaDon`) =====
// Trace twin LIVE: `FrmCapNhatThongTinHoaDon.cs:466` → `new SalesService().Car_VIN_UpdMulti_FlagDocReq(dtbCarVin)`
//   → WS `Car_VIN_UpdMulti_FlagDocReq` (`WSHTC.asmx.cs:34626`) → **`_biz.Car_VIN_UpdMulti_FlagDocReq`**
//   (`BizHTC.Car.cs:3146` — **KHÔNG** ở `Biz.HTC.WH.cs`).
// 🔴 LUẬT LỌC NẰM Ở CLIENT (`:440-444`): chỉ những dòng có `FlagDocReq` **đúng "0" hoặc "1"** mới được đưa
//    vào lô gửi lên; dòng có giá trị khác bị **bỏ qua ngay ở lưới**, không gửi. Biz chuẩn hoá bằng `StdFlag`.
//    ⇒ Port server phải tự kiểm lại (client web có thể gửi bất kỳ giá trị nào).
// 🔴 `alColumnEffective` đúng **3 cột**: `FlagDocReq` + `LogLUDateTime` + `LogLUBy`; update join `t.VIN = f.VIN`.
// ⚠️ Ghi chú lượt này: hàm anh em `Car_VIN_Upd_Profile` (`SalesService.cs:21208`) có **TOÀN BỘ lời gọi WS
//    bị COMMENT** (`:21226-21237`) ⇒ **DEAD CODE, không port**. Đã kiểm để không phí công.
app.MapPost("/api/carvinmasters/update-multi-flagdocreq", async (
    List<CarVinFlagDocReqDto> rows, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    // `..._TableCar_VINBlank`
    if (rows is null || rows.Count == 0) return Results.BadRequest(new { error = "Bảng VIN cần cập nhật đang rỗng." });
    var list = rows.Where(r => !string.IsNullOrWhiteSpace(r.Vin)).ToList();
    if (list.Count == 0) return Results.BadRequest(new { error = "Bảng VIN cần cập nhật đang rỗng." });

    var who = user.Identity?.Name ?? "system"; var now = DateTime.Now;
    var vins = list.Select(r => r.Vin!.Trim().ToUpperInvariant()).ToList();
    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && vins.Contains(c.VIN)).ToListAsync();

    foreach (var r in list)
    {
        var v = r.Vin!.Trim().ToUpperInvariant();
        // `myCar_CheckVIN(..., TConst.Flag.Active, "" /* không kiểm DocumentsStatus */)`
        if (!cars.Any(c => c.VIN == v)) return Results.BadRequest(new { error = $"VIN {v} chưa khai báo trên hệ thống." });
        // Luật lọc của client, kiểm lại ở server: chỉ nhận "0" hoặc "1".
        if (r.FlagDocReq != "0" && r.FlagDocReq != "1")
            return Results.BadRequest(new { error = $"VIN {v}: FlagDocReq phải là '0' hoặc '1' (nhận '{r.FlagDocReq}')." });
    }

    int updated = 0;
    foreach (var r in list)
    {
        var car = cars.First(c => c.VIN == r.Vin!.Trim().ToUpperInvariant());
        car.FlagDocReq = r.FlagDocReq;              // 3 cột của alColumnEffective
        car.LogLUDateTime = now; car.LogLUBy = who;
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        updated, columnsWritten = new[] { "FlagDocReq", "LogLUDateTime", "LogLUBy" },
        acceptedValues = new[] { "0", "1" },
        deadCodeNote = "Hàm anh em Car_VIN_Upd_Profile (SalesService.cs:21208) có TOÀN BỘ lời gọi WS bị COMMENT ⇒ dead code, không port."
    });
}).RequireAuthorization();
app.MapPost("/api/carvinmasters/update-docdeliveryreqdate", async (
    List<CarVinDocDlvReqDto> rows, AppDbContext db, ITenantContext t, string? flagDirect) =>
{
    // `..._TableDetailBeBlank`
    if (rows is null || rows.Count == 0) return Results.BadRequest(new { error = "Bảng VIN cần cập nhật đang rỗng." });
    var list = rows.Where(r => !string.IsNullOrWhiteSpace(r.Vin)).ToList();
    if (list.Count == 0) return Results.BadRequest(new { error = "Bảng VIN cần cập nhật đang rỗng." });
    if (flagDirect == "0") return Results.BadRequest(new { error = "Chỉ người dùng HTC trực tiếp (FlagDirect='1') được cập nhật ngày đề nghị giao hồ sơ." });

    // `..._DuplicateKeyDetail`
    var dup = list.GroupBy(r => r.Vin!.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dup != null) return Results.BadRequest(new { error = $"VIN {dup.Key} bị trùng trong bảng!" });

    var vins = list.Select(r => r.Vin!.Trim().ToUpperInvariant()).ToList();
    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && vins.Contains(c.VIN)).ToListAsync();

    // Nguồn kiểm TỪNG DÒNG trong cùng transaction rồi mới ghi cả lô ⇒ validate hết trước.
    foreach (var r in list)
    {
        var v = r.Vin!.Trim().ToUpperInvariant();
        // `myCar_CheckVIN(..., TConst.Flag.Active)`
        if (!cars.Any(c => c.VIN == v)) return Results.BadRequest(new { error = $"VIN {v} chưa khai báo trên hệ thống." });
        // `..._InvalidDocDeliveryReqDate` — nguồn chặn ngày RỖNG (`StandardizeDate` ra null/độ dài < 1).
        if (r.DocDeliveryReqDate is null) return Results.BadRequest(new { error = $"VIN {v} thiếu ngày đề nghị giao hồ sơ." });
    }

    int updated = 0;
    foreach (var r in list)
    {
        var car = cars.First(c => c.VIN == r.Vin!.Trim().ToUpperInvariant());
        car.DocDeliveryReqDate = r.DocDeliveryReqDate;   // cột DUY NHẤT của alColumnEffective
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        updated, columnsWritten = new[] { "DocDeliveryReqDate" },
        note = "alColumnEffective của nguồn chỉ có ĐÚNG cột này — không ghi LogLUDateTime/LogLUBy.",
        rbacNote = "myCommon_CheckHTCDirect(Flag.Active) là DÒNG ACTIVE ở nguồn — nhận qua cờ flagDirect (nợ tầng ability)."
    });
}).RequireAuthorization();
app.MapPost("/api/carvinmasters/{vin}/billno-mortage", async (
    string vin, CarVinBillNoDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user, string? flagDirect) =>
{
    var v = vin.Trim().ToUpperInvariant();
    if (flagDirect == "0") return Results.BadRequest(new { error = "Chỉ người dùng HTC trực tiếp (FlagDirect='1') được cập nhật hồ sơ xe." });

    // `myCar_CheckVIN(..., TConst.Flag.Active)`
    var car = await db.CarVinMasters.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.VIN == v);
    if (car is null) return Results.NotFound(new { vin = v });

    var newEnd = dto.MortageEndDate;
    // 🔴 `..._InvalidMortageEndDate01` — chú thích nguyên văn của nguồn (`:61881`):
    //    *"Không được sửa ngày hiệu lực từ A về NULL"* ⇒ đang CÓ ngày mà gửi rỗng thì CHẶN.
    if (car.MortageEndDate is not null && newEnd is null)
        return Results.BadRequest(new { error = "Không được sửa ngày hiệu lực (hết thế chấp) từ có giá trị về rỗng.", vin = v, mortageEndDateOld = car.MortageEndDate });
    // `..._InvalidPackingListNo` — xe chưa có packing list thì không cho cập nhật.
    if (string.IsNullOrWhiteSpace(car.PackingListNo))
        return Results.BadRequest(new { error = $"Xe {v} chưa có số packing list — không cập nhật được vận đơn/ngày hết thế chấp." });
    // `..._InvalidMortageEnd02`: có cả hai mốc mà End < Start.
    if (car.MortageStartDate is not null && newEnd is not null && newEnd < car.MortageStartDate)
        return Results.BadRequest(new { error = "Ngày hết thế chấp không được nhỏ hơn ngày bắt đầu thế chấp.", mortageStartDate = car.MortageStartDate, mortageEndDate = newEnd });
    // `..._InvalidMortageEndNull`: KHÔNG có ngày bắt đầu mà lại đặt ngày kết thúc.
    if (car.MortageStartDate is null && newEnd is not null)
        return Results.BadRequest(new { error = "Xe chưa có ngày bắt đầu thế chấp — không đặt được ngày hết thế chấp.", vin = v });

    // `..._InvalidDRDtlStatus`: còn dòng đề nghị giao hồ sơ ở trạng thái **'P' hoặc 'A1'** ⇒ CHẶN.
    var pendingDr = await db.DocReqCars
        .Where(x => x.OrgId == t.OrgId && x.Vin == v && (x.DRDtlStatus == "P" || x.DRDtlStatus == "A1"))
        .Select(x => new { x.DocReqId, x.DRDtlStatus }).FirstOrDefaultAsync();
    if (pendingDr is not null)
        return Results.BadRequest(new { error = $"Xe {v} còn đề nghị giao hồ sơ ở trạng thái {pendingDr.DRDtlStatus} (đề nghị id {pendingDr.DocReqId}) — không cập nhật được.", drDtlStatusChecked = "in (P, A1)" });

    var who = user.Identity?.Name ?? "system"; var now = DateTime.Now;
    var written = new List<string>();
    // Ba cột GHI CÓ ĐIỀU KIỆN — gửi rỗng/null = giữ nguyên.
    if (newEnd is not null) { car.MortageEndDate = newEnd; written.Add("MortageEndDate"); }
    if (!string.IsNullOrWhiteSpace(dto.BillNo)) { car.BillNo = dto.BillNo!.Trim(); written.Add("BillNo"); }
    if (!string.IsNullOrWhiteSpace(dto.HandOverBankCode)) { car.HandOverBankCode = dto.HandOverBankCode!.Trim(); written.Add("HandOverBankCode"); }
    car.LogLUDateTime = now; car.LogLUBy = who; written.Add("LogLUDateTime"); written.Add("LogLUBy");

    // Side-effect 2/3: `Pmt_GuaranteeDetail.DateWarning` (`:62253-62256`) — chỉ khi có bảo lãnh khớp.
    // ⚠️ NỢ: công thức `dtimeDateWarning` nguồn tính từ cấu hình bảo lãnh; MiniHTC chưa có tầng đó
    //    ⇒ **KHÔNG suy công thức**, để nguyên và ghi nợ (luật "không đoán công thức rồi ghi DB").
    // Side-effect 3/3: update `Car_DocReqDtl` khi có `MortageEndDate` — cũng ghi nợ, chưa port.
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        vin = v, columnsWritten = written,
        car.BillNo, car.MortageEndDate, car.HandOverBankCode, car.MortageStartDate, car.PackingListNo,
        conditionalWriteNote = "BillNo/HandOverBankCode chỉ ghi khi KHÁC RỖNG; MortageEndDate chỉ ghi khi khác null — gửi rỗng là GIỮ NGUYÊN.",
        pendingDebt = "NỢ: 2 side-effect còn lại của nguồn chưa port — Pmt_GuaranteeDetail.DateWarning (công thức từ cấu hình bảo lãnh) và update Car_DocReqDtl khi có MortageEndDate."
    });
}).RequireAuthorization();
app.MapPost("/api/cabininfos/update-multi", async (
    List<CabinInfoDto> rows, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user, string? flagDirect) =>
{
    // `..._CarVINTableBlank`
    if (rows is null || rows.Count == 0) return Results.BadRequest(new { error = "Bảng VIN cần cập nhật thùng đang rỗng." });
    var list = rows.Where(r => !string.IsNullOrWhiteSpace(r.Vin)).ToList();
    if (list.Count == 0) return Results.BadRequest(new { error = "Bảng VIN cần cập nhật thùng đang rỗng." });
    // `myCommon_CheckHTCDirect(Flag.Active)` — dòng ACTIVE.
    if (flagDirect == "0") return Results.BadRequest(new { error = "Chỉ người dùng HTC trực tiếp (FlagDirect='1') được cập nhật thùng hàng loạt." });

    var who = user.Identity?.Name ?? "system"; var now = DateTime.Now;
    var vins = list.Select(r => r.Vin!.Trim().ToUpperInvariant()).ToList();
    var dupVin = list.GroupBy(r => r.Vin!.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupVin != null) return Results.BadRequest(new { error = $"VIN {dupVin.Key} bị trùng trong bảng!" });

    var carVins = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && vins.Contains(c.VIN)).ToListAsync();
    var certs = await db.CabinCertificates.Where(c => c.OrgId == t.OrgId).ToListAsync();
    var infos = await db.CabinInfos.Where(c => c.OrgId == t.OrgId && vins.Contains(c.Vin)).ToListAsync();

    // Nguồn kiểm TỪNG DÒNG trong cùng transaction rồi mới ghi cả lô ⇒ validate hết trước.
    foreach (var r in list)
    {
        var v = r.Vin!.Trim().ToUpperInvariant();
        // `myCar_CheckVIN(..., TConst.Flag.Active)` — VIN phải tồn tại.
        if (!carVins.Any(c => c.VIN == v)) return Results.BadRequest(new { error = $"VIN {v} chưa khai báo trên hệ thống." });
        // 🔴 `Mst_CabinCertificate_CheckDB(..., Flag.Active exist, Flag.Active active)` — **CHỈ kiểm khi
        //    `CabinCertificateNo != null`** (`Biz.HTC.WH.My.cs:628-639`). Gửi null nghĩa là "không đổi".
        if (r.CabinCertificateNo is not null)
        {
            var cert = certs.FirstOrDefault(c => c.CabinCertificateNo == r.CabinCertificateNo!.Trim());
            if (cert is null) return Results.BadRequest(new { error = $"Số chứng nhận thùng {r.CabinCertificateNo} không tồn tại." });
            if (cert.FlagActive == "0") return Results.BadRequest(new { error = $"Số chứng nhận thùng {r.CabinCertificateNo} đang ngưng hoạt động." });
        }
    }

    int updated = 0, keptFromDb = 0;
    foreach (var r in list)
    {
        var v = r.Vin!.Trim().ToUpperInvariant();
        var c = infos.FirstOrDefault(x => x.Vin == v);
        if (c is null) { c = new CabinInfo { OrgId = t.OrgId, Vin = v }; db.CabinInfos.Add(c); }
        // 🔴 `if (strCabinCertificateNo == null) strCabinCertificateNo = dt_Car_VIN_Check.Rows[0]["CabinCertificateNo"]`
        //    (`:640-644`) — null ⇒ **GIỮ giá trị đang có trong DB**, KHÔNG xoá về null.
        if (r.CabinCertificateNo is null) keptFromDb++;
        else c.CabinCertificateNo = r.CabinCertificateNo.Trim();
        c.CabinCertificateDate = r.CabinCertificateDate ?? c.CabinCertificateDate;
        c.CabinCONo = r.CabinCONo ?? c.CabinCONo;
        c.CabinInvoiceNo = r.CabinInvoiceNo ?? c.CabinInvoiceNo;
        c.CabinInvoiceDate = r.CabinInvoiceDate ?? c.CabinInvoiceDate;
        c.UpdatedAt = now;                      // ↔ LogLUDateTime của nguồn
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        updated, keptCertificateFromDb = keptFromDb,
        columnsWritten = new[] { "CabinCertificateNo", "CabinCONo", "CabinInvoiceNo", "CabinInvoiceDate", "CabinCertificateDate", "LogLUDateTime", "LogLUBy" },
        rbacNote = "myCommon_CheckHTCDirect(Flag.Active) là DÒNG ACTIVE ở nguồn — nhận qua cờ flagDirect (nợ tầng ability).",
        storageNote = "NỢ mô hình: nguồn ghi thẳng Car_VIN; MiniHTC lưu ở bảng tách CabinInfo (khoá VIN)."
    });
}).RequireAuthorization();
app.MapPost("/api/cabininfos", async (CabinInfoDto dto, AppDbContext db, ITenantContext t) =>
{
    var vin = (dto.Vin ?? "").Trim().ToUpperInvariant();
    if (vin == "") return Results.BadRequest(new { error = "Thiếu số khung (VIN)." });
    if (dto.CabinInvoiceDate.HasValue && dto.CabinInvoiceDate.Value.Date > DateTime.Today)
        return Results.BadRequest(new { error = "Ngày hóa đơn thùng không được ở tương lai." });
    var c = await db.CabinInfos.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Vin == vin);
    if (c is null) { c = new CabinInfo { OrgId = t.OrgId, Vin = vin }; db.CabinInfos.Add(c); }
    c.SpecCode = dto.SpecCode; c.CabinCertificateNo = dto.CabinCertificateNo; c.CabinCertificateDate = dto.CabinCertificateDate;
    c.CabinCONo = dto.CabinCONo; c.CabinInvoiceNo = dto.CabinInvoiceNo; c.CabinInvoiceDate = dto.CabinInvoiceDate; c.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { c.Id, c.Vin });
}).RequireAuthorization();

// ===== Yêu cầu chiết khấu thanh toán (PaymentDiscountReq — port 1:1 FrmReq_PaymentDiscount, 2010.HTC/Sales) =====
app.MapGet("/api/paymentdiscountreqs", async (AppDbContext db, ITenantContext t, string? status, string? dealer) =>
{
    var q = db.PaymentDiscountReqs.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.Status == status);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(x => x.DealerCode == dealer);
    var items = await q.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.Id, x.ReqNo, x.DealerCode, x.GuaranteeNo, x.BankGuaranteeNo, x.BankCode, x.SpecDescription, x.DiscountAmount, x.Status, x.Note
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, totalAmount = items.Sum(i => i.DiscountAmount),
        pending = items.Count(i => i.Status == "Draft"), approved = items.Count(i => i.Status == "Approved"), items });
}).RequireAuthorization();

app.MapPost("/api/paymentdiscountreqs", async (PaymentDiscountReqDto dto, AppDbContext db, ITenantContext t) =>
{
    if (dto.DiscountAmount <= 0) return Results.BadRequest(new { error = "Số tiền chiết khấu phải lớn hơn 0." });
    if (string.IsNullOrWhiteSpace(dto.GuaranteeNo) && string.IsNullOrWhiteSpace(dto.BankGuaranteeNo))
        return Results.BadRequest(new { error = "Cần số bảo lãnh hoặc số bảo lãnh ngân hàng." });
    var no = "PDR" + DateTime.Now.ToString("yyMMddHHmmss");
    var r = new PaymentDiscountReq { OrgId = t.OrgId, ReqNo = no, DealerCode = dto.DealerCode, GuaranteeNo = dto.GuaranteeNo,
        BankGuaranteeNo = dto.BankGuaranteeNo, BankCode = dto.BankCode, SpecDescription = dto.SpecDescription, DiscountAmount = dto.DiscountAmount, Status = "Draft" };
    db.PaymentDiscountReqs.Add(r); await db.SaveChangesAsync();
    return Results.Ok(new { r.Id, r.ReqNo, r.Status });
}).RequireAuthorization();

app.MapPost("/api/paymentdiscountreqs/{id}/status", async (long id, PaymentDiscountStatusDto dto, AppDbContext db, ITenantContext t) =>
{
    var r = await db.PaymentDiscountReqs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (r is null) return Results.NotFound(new { id });
    var s = (dto.Status ?? "").Trim();
    if (s != "Approved" && s != "Rejected") return Results.BadRequest(new { error = "Trạng thái phải là Approved hoặc Rejected." });
    if (r.Status != "Draft") return Results.BadRequest(new { error = $"Chỉ duyệt được yêu cầu đang Nháp (hiện {r.Status})." });
    if (s == "Rejected" && string.IsNullOrWhiteSpace(dto.Note)) return Results.BadRequest(new { error = "Từ chối phải ghi lý do." });
    r.Status = s; if (!string.IsNullOrWhiteSpace(dto.Note)) r.Note = dto.Note; r.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { r.Id, r.Status });
}).RequireAuthorization();

