app.MapGet("/api/report/warranty-accept", async (AppDbContext db, ITenantContext t, string? month) =>
{
    var q = db.ServiceWarrantyClaims.Where(x => x.OrgId == t.OrgId && x.Status == "Accepted");
    if (!string.IsNullOrWhiteSpace(month) && DateTime.TryParse(month + "-01", out var m0))
    {
        var m1 = m0.AddMonths(1);
        q = q.Where(x => x.UpdatedAt >= m0 && x.UpdatedAt < m1);
    }
    var rows = await q.GroupBy(x => x.DealerCode)
        .Select(g => new { dealerCode = g.Key ?? "(không rõ)", claims = g.Count(), totalAmount = g.Sum(x => x.Amount) })
        .OrderByDescending(x => x.totalAmount).ToListAsync();
    return Results.Ok(new { count = rows.Count, grandTotal = rows.Sum(r => r.totalAmount), rows });
}).RequireAuthorization();

// Báo cáo NHẬP KHO CHI TIẾT — port 1:1 khối SQL báo cáo nhập của BizCarSv.Inventory.Report.
// Nguồn trả RIÊNG hai cột tiền: Total (trước thuế) và VATAmount (phần thuế), kèm vị trí THỰC nhập.
app.MapGet("/api/report/stockin-detail", async (
    AppDbContext db, ITenantContext t, DateTime? from, DateTime? to, string? dealer, string? supplier) =>
{
    // Nguồn lọc: sti.status = 3 (đã duyệt) + khoảng StockInDate + DealerCode + SupplierID.
    var headers = db.ServiceStockIns.Where(o => o.OrgId == t.OrgId && o.Status == "Confirmed");
    if (from.HasValue) headers = headers.Where(o => o.StockInDate >= from);
    if (to.HasValue) headers = headers.Where(o => o.StockInDate <= to);
    if (!string.IsNullOrWhiteSpace(dealer)) headers = headers.Where(o => o.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(supplier)) headers = headers.Where(o => o.SupplierCode == supplier);

    var rows = await (from line in db.ServiceStockInLines.Where(l => l.OrgId == t.OrgId)
                      join header in headers on line.ServiceStockInId equals header.Id
                      orderby header.StockInDate, header.StockInNo
                      select new
                      {
                          line.PartCode, line.PartName,
                          date = header.StockInDate, header.StockInNo,
                          header.SupplierCode, header.DealerCode,
                          line.Quantity, line.Price,
                          total = line.TotalBeforeVat,
                          line.Vat, vatAmount = line.VatAmount,
                          location = line.ActualLocationCode
                      }).Take(2000).ToListAsync();

    return Results.Ok(new
    {
        count = rows.Count,
        totalBeforeVat = rows.Sum(r => r.total),
        totalVat = rows.Sum(r => r.vatAmount),
        grandTotal = rows.Sum(r => r.total + r.vatAmount),
        rows
    });
}).RequireAuthorization();

// ===== Báo cáo nhập-xuất-tồn + thẻ kho (report tái-dùng ServiceStockIn/Out — port 1:1 FrmReportInOutStock + FrmReportCardStock, TCMotor) =====
// Nhập-xuất-tồn theo mã PT: tổng nhập (phiếu Confirmed), tổng xuất (phiếu Confirmed), tồn hiện tại (ServicePart.Quantity).
app.MapGet("/api/report/stock-inout", async (AppDbContext db, ITenantContext t, DateTime? fromDate, DateTime? toDate) =>
{
    var ins = db.ServiceStockIns.Where(o => o.OrgId == t.OrgId && o.Status == "Confirmed");
    var outs = db.ServiceStockOuts.Where(o => o.OrgId == t.OrgId && o.Status == "Confirmed");
    if (fromDate.HasValue) { ins = ins.Where(o => o.StockInDate.HasValue && o.StockInDate.Value.Date >= fromDate.Value.Date); outs = outs.Where(o => o.StockOutDate.HasValue && o.StockOutDate.Value.Date >= fromDate.Value.Date); }
    if (toDate.HasValue) { ins = ins.Where(o => o.StockInDate.HasValue && o.StockInDate.Value.Date <= toDate.Value.Date); outs = outs.Where(o => o.StockOutDate.HasValue && o.StockOutDate.Value.Date <= toDate.Value.Date); }
    var inIds = ins.Select(o => o.Id); var outIds = outs.Select(o => o.Id);
    var inByPart = await db.ServiceStockInLines.Where(l => l.OrgId == t.OrgId && inIds.Contains(l.ServiceStockInId))
        .GroupBy(l => l.PartCode).Select(g => new { partCode = g.Key, qty = g.Sum(x => x.Quantity) }).ToListAsync();
    var outByPart = await db.ServiceStockOutLines.Where(l => l.OrgId == t.OrgId && outIds.Contains(l.ServiceStockOutId))
        .GroupBy(l => l.PartCode).Select(g => new { partCode = g.Key, qty = g.Sum(x => x.Quantity) }).ToListAsync();
    var parts = await db.ServiceParts.Where(p => p.OrgId == t.OrgId).Select(p => new { p.PartCode, p.PartName, p.Unit, p.Quantity }).ToListAsync();
    var inMap = inByPart.ToDictionary(x => x.partCode, x => x.qty);
    var outMap = outByPart.ToDictionary(x => x.partCode, x => x.qty);
    var codes = parts.Select(p => p.PartCode).Union(inMap.Keys).Union(outMap.Keys).Distinct();
    var pMap = parts.ToDictionary(p => p.PartCode, p => p);
    var rows = codes.Select(c => {
        pMap.TryGetValue(c, out var p);
        var tin = inMap.TryGetValue(c, out var vi) ? vi : 0m;
        var tout = outMap.TryGetValue(c, out var vo) ? vo : 0m;
        return new { partCode = c, partName = p?.PartName, unit = p?.Unit, totalIn = tin, totalOut = tout, current = p?.Quantity ?? 0m };
    }).Where(r => r.totalIn != 0 || r.totalOut != 0).OrderBy(r => r.partCode).ToList();
    return Results.Ok(new { count = rows.Count, sumIn = rows.Sum(r => r.totalIn), sumOut = rows.Sum(r => r.totalOut), rows });
}).RequireAuthorization();

// Thẻ kho 1 mã PT: sổ nhập/xuất theo thời gian + tồn lũy kế (chỉ phiếu Confirmed).
app.MapGet("/api/report/stock-card", async (AppDbContext db, ITenantContext t, string partCode) =>
{
    var code = (partCode ?? "").Trim();
    if (code == "") return Results.BadRequest(new { error = "Cần mã phụ tùng." });
    var inMoves = await (from l in db.ServiceStockInLines.Where(x => x.OrgId == t.OrgId && x.PartCode == code)
                         join h in db.ServiceStockIns.Where(x => x.OrgId == t.OrgId && x.Status == "Confirmed") on l.ServiceStockInId equals h.Id
                         select new { docNo = h.StockInNo, date = h.StockInDate, inQty = l.Quantity, outQty = 0m }).ToListAsync();
    var outMoves = await (from l in db.ServiceStockOutLines.Where(x => x.OrgId == t.OrgId && x.PartCode == code)
                          join h in db.ServiceStockOuts.Where(x => x.OrgId == t.OrgId && x.Status == "Confirmed") on l.ServiceStockOutId equals h.Id
                          select new { docNo = h.StockOutNo, date = h.StockOutDate, inQty = 0m, outQty = l.Quantity }).ToListAsync();
    var moves = inMoves.Concat(outMoves).OrderBy(m => m.date ?? DateTime.MaxValue).ThenBy(m => m.docNo).ToList();
    decimal bal = 0; var ledger = moves.Select(m => { bal += m.inQty - m.outQty; return new { m.docNo, date = m.date.HasValue ? m.date.Value.ToString("yyyy-MM-dd") : "", m.inQty, m.outQty, balance = bal }; }).ToList();
    return Results.Ok(new { partCode = code, totalIn = moves.Sum(m => m.inQty), totalOut = moves.Sum(m => m.outQty), closing = bal, ledger });
}).RequireAuthorization();

// ===== Báo cáo phụ tùng (report tái-dùng ServicePart + ServiceStockOut — port 1:1 FrmReportPartMinQuantity/TopProfit/TopRotate, TCMotor) =====
// Phụ tùng dưới định mức tồn (Quantity < MinQuantity) — cần đặt hàng bổ sung.
app.MapGet("/api/report/part-minquantity", async (AppDbContext db, ITenantContext t) =>
{
    var rows = await db.ServiceParts.Where(x => x.OrgId == t.OrgId && x.FlagActive == "1" && x.Quantity < x.MinQuantity)
        .OrderBy(x => x.Quantity - x.MinQuantity)
        .Select(x => new { x.PartCode, x.PartName, x.Unit, x.Quantity, x.MinQuantity, shortage = x.MinQuantity - x.Quantity, x.Location, x.PartGroupCode }).ToListAsync();
    return Results.Ok(new { count = rows.Count, totalShortage = rows.Sum(r => r.shortage), rows });
}).RequireAuthorization();

// Top phụ tùng lãi cao: lợi nhuận đơn vị = giá bán - giá vốn, và % lãi trên giá vốn.
app.MapGet("/api/report/part-topprofit", async (AppDbContext db, ITenantContext t, int? top) =>
{
    var n = top is > 0 and <= 200 ? top.Value : 20;
    var rows = await db.ServiceParts.Where(x => x.OrgId == t.OrgId && x.FlagActive == "1" && x.Price > 0)
        .Select(x => new { x.PartCode, x.PartName, x.Price, x.Cost, unitProfit = x.Price - x.Cost,
            marginPct = x.Cost > 0 ? Math.Round((x.Price - x.Cost) / x.Cost * 100, 1) : (decimal?)null })
        .OrderByDescending(x => x.unitProfit).Take(n).ToListAsync();
    return Results.Ok(new { count = rows.Count, rows });
}).RequireAuthorization();

// Top phụ tùng luân chuyển: tổng số lượng đã xuất kho (chỉ phiếu đã duyệt) theo mã PT.
app.MapGet("/api/report/part-toprotate", async (AppDbContext db, ITenantContext t, int? top) =>
{
    var n = top is > 0 and <= 200 ? top.Value : 20;
    var confirmedIds = db.ServiceStockOuts.Where(o => o.OrgId == t.OrgId && o.Status == "Confirmed").Select(o => o.Id);
    var rows = await db.ServiceStockOutLines.Where(l => l.OrgId == t.OrgId && confirmedIds.Contains(l.ServiceStockOutId))
        .GroupBy(l => new { l.PartCode, l.PartName })
        .Select(g => new { g.Key.PartCode, g.Key.PartName, totalOut = g.Sum(x => x.Quantity), timesOut = g.Count() })
        .OrderByDescending(x => x.totalOut).Take(n).ToListAsync();
    return Results.Ok(new { count = rows.Count, totalOut = rows.Sum(r => r.totalOut), rows });
}).RequireAuthorization();

// Top phụ tùng doanh thu: doanh thu = SL xuất (phiếu Confirmed) × giá bán hiện tại của PT, lọc khoảng ngày xuất.
app.MapGet("/api/report/part-toprevenue", async (AppDbContext db, ITenantContext t, DateTime? fromDate, DateTime? toDate, int? top) =>
{
    var n = top is > 0 and <= 200 ? top.Value : 20;
    var outs = db.ServiceStockOuts.Where(o => o.OrgId == t.OrgId && o.Status == "Confirmed");
    if (fromDate.HasValue) outs = outs.Where(o => o.StockOutDate.HasValue && o.StockOutDate.Value.Date >= fromDate.Value.Date);
    if (toDate.HasValue) outs = outs.Where(o => o.StockOutDate.HasValue && o.StockOutDate.Value.Date <= toDate.Value.Date);
    var outIds = outs.Select(o => o.Id);
    var qtyByPart = await db.ServiceStockOutLines.Where(l => l.OrgId == t.OrgId && outIds.Contains(l.ServiceStockOutId))
        .GroupBy(l => l.PartCode).Select(g => new { partCode = g.Key, qty = g.Sum(x => x.Quantity) }).ToListAsync();
    var parts = await db.ServiceParts.Where(p => p.OrgId == t.OrgId).Select(p => new { p.PartCode, p.PartName, p.Unit, p.Price }).ToListAsync();
    var priceMap = parts.ToDictionary(p => p.PartCode, p => p);
    var rows = qtyByPart.Select(q => {
        priceMap.TryGetValue(q.partCode, out var p);
        var price = p?.Price ?? 0m;
        return new { q.partCode, partName = p?.PartName, unit = p?.Unit, qtyOut = q.qty, price, revenue = q.qty * price };
    }).OrderByDescending(x => x.revenue).Take(n).ToList();
    return Results.Ok(new { count = rows.Count, totalRevenue = rows.Sum(r => r.revenue), rows });
}).RequireAuthorization();

// Biến động giá phụ tùng: từ các phiếu nhập kho — số lần giá khác nhau, giá thấp nhất/cao nhất theo mã PT.
app.MapGet("/api/report/part-variationprice", async (AppDbContext db, ITenantContext t) =>
{
    var lines = await db.ServiceStockInLines.Where(l => l.OrgId == t.OrgId)
        .Select(l => new { l.PartCode, l.PartName, l.Price }).ToListAsync();
    var rows = lines.GroupBy(l => l.PartCode).Select(g => new
    {
        partCode = g.Key, partName = g.Select(x => x.PartName).FirstOrDefault(x => x != null),
        countPrice = g.Select(x => x.Price).Distinct().Count(), minPrice = g.Min(x => x.Price), maxPrice = g.Max(x => x.Price),
        variation = g.Max(x => x.Price) - g.Min(x => x.Price)
    }).Where(r => r.countPrice > 1).OrderByDescending(r => r.variation).ToList();
    return Results.Ok(new { count = rows.Count, rows });
}).RequireAuthorization();

// ===== Lịch hẹn dịch vụ + bảng khoang/bay (ServiceAppointment — port 1:1 FrmAppList + FrmShowCavityStatus, TCMotor) =====
app.MapGet("/api/appointments", async (AppDbContext db, ITenantContext t, string? plate, string? status, DateTime? date) =>
{
    var q = db.ServiceAppointments.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(plate)) q = q.Where(x => x.PlateNo != null && x.PlateNo.Contains(plate!));
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.Status == status);
    if (date.HasValue) { var d0 = date.Value.Date; var d1 = d0.AddDays(1); q = q.Where(x => x.AppFrom >= d0 && x.AppFrom < d1); }
    var items = await q.OrderBy(x => x.AppFrom).Take(500).Select(x => new
    {
        x.Id, x.AppNo, x.CavityName, x.PlateNo, x.CusName, x.Mobile, x.ModelName, x.AppType,
        appFrom = x.AppFrom.ToString("yyyy-MM-dd HH:mm"), appTo = x.AppTo.ToString("yyyy-MM-dd HH:mm"), x.Status, x.Note, x.EngineerNo, x.QuoteNo, x.CusRequest,
        serviceItems = db.AppointmentServiceItems.Count(i => i.OrgId == t.OrgId && i.AppNo == x.AppNo),
        partItems = db.AppointmentPartItems.Count(i => i.OrgId == t.OrgId && i.AppNo == x.AppNo)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Đặt lịch hẹn. Guard: giờ kết thúc > bắt đầu; không trùng khoang cùng lúc (bay không được đặt chồng giờ).
app.MapPost("/api/appointments", async (AppointmentDto dto, AppDbContext db, ITenantContext t) =>
{
    if (dto.AppTo <= dto.AppFrom) return Results.BadRequest(new { error = "Giờ kết thúc phải sau giờ bắt đầu." });
    var cavity = (dto.CavityName ?? "").Trim();
    if (cavity != "")
    {
        // Kiểm tra khoang có tồn tại trong danh mục Cavity (nếu đã khai báo).
        var hasCavityMaster = await db.Cavities.AnyAsync(c => c.OrgId == t.OrgId);
        if (hasCavityMaster && !await db.Cavities.AnyAsync(c => c.OrgId == t.OrgId && c.CavityName == cavity))
            return Results.BadRequest(new { error = "Khoang/bay không có trong danh mục: " + cavity });
        // Chống đặt chồng giờ cùng 1 khoang (bỏ qua lệnh đã hủy).
        var overlap = await db.ServiceAppointments.AnyAsync(x => x.OrgId == t.OrgId && x.CavityName == cavity && x.Status != "Cancelled"
            && x.AppFrom < dto.AppTo && dto.AppFrom < x.AppTo);
        if (overlap) return Results.BadRequest(new { error = "Khoang " + cavity + " đã có lịch trùng khung giờ." });
    }
    var engineerNo = (dto.EngineerNo ?? "").Trim().ToUpperInvariant();
    if (engineerNo != "" && !await db.ServiceEngineers.AnyAsync(e => e.OrgId == t.OrgId && e.EngineerNo == engineerNo))
        return Results.BadRequest(new { error = "CVDV không tồn tại: " + engineerNo });
    // TWIN đã trace: WS gọi `Ser_App_Create_New20201230` (BizCarSv.ZTemp.cs) — KHÔNG phải `Ser_App_Create` trần.
    // Bản LIVE NÉM LỖI khi dòng dịch vụ/phụ tùng thiếu mã (bản cũ chỉ ghi DBNull) ⇒ port theo bản LIVE.
    var serviceItems = dto.ServiceItems ?? new();
    foreach (var line in serviceItems)
        if (string.IsNullOrWhiteSpace(line.SerCode))
            return Results.BadRequest(new { error = "Dịch vụ không có trong danh mục!" });
    var partItems = dto.PartItems ?? new();
    foreach (var line in partItems)
        if (string.IsNullOrWhiteSpace(line.PartCode))
            return Results.BadRequest(new { error = "Phụ tùng không có trong kho!" });

    var no = "APP" + DateTime.Now.ToString("yyMMddHHmmss");
    var a = new ServiceAppointment { OrgId = t.OrgId, AppNo = no, CavityName = cavity == "" ? null : cavity, PlateNo = dto.PlateNo,
        CusName = dto.CusName, Mobile = dto.Mobile, ModelName = dto.ModelName, AppType = dto.AppType, AppFrom = dto.AppFrom, AppTo = dto.AppTo, Note = dto.Note, Status = "Booked",
        EngineerNo = engineerNo == "" ? null : engineerNo, QuoteNo = dto.QuoteNo, CusRequest = dto.CusRequest };
    db.ServiceAppointments.Add(a);

    foreach (var line in serviceItems)
        db.AppointmentServiceItems.Add(new AppointmentServiceItem
        {
            OrgId = t.OrgId, AppNo = no,
            SerCode = line.SerCode!.Trim().ToUpperInvariant(), SerName = line.SerName,
            StdManHour = line.StdManHour, Note = line.Note
        });
    foreach (var line in partItems)
        db.AppointmentPartItems.Add(new AppointmentPartItem
        {
            OrgId = t.OrgId, AppNo = no,
            PartCode = line.PartCode!.Trim().ToUpperInvariant(), PartName = line.PartName, EngName = line.EngName,
            Unit = line.Unit, Quantity = line.Quantity, Note = line.Note
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { a.Id, a.AppNo, a.Status, serviceItems = serviceItems.Count, partItems = partItems.Count });
}).RequireAuthorization();

// Nội dung đặt trước của lịch hẹn: danh sách dịch vụ + phụ tùng khách yêu cầu.
app.MapGet("/api/appointments/{no}/items", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var a = await db.ServiceAppointments.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.AppNo == no);
    if (a is null) return Results.NotFound(new { no });
    var services = await db.AppointmentServiceItems.Where(x => x.OrgId == t.OrgId && x.AppNo == no)
        .Select(x => new { x.SerCode, x.SerName, x.StdManHour, x.Note }).ToListAsync();
    var parts = await db.AppointmentPartItems.Where(x => x.OrgId == t.OrgId && x.AppNo == no)
        .Select(x => new { x.PartCode, x.PartName, x.EngName, x.Unit, x.Quantity, x.Note }).ToListAsync();
    return Results.Ok(new
    {
        a.AppNo, a.PlateNo, a.CusName, a.CusRequest, a.AppFrom, a.AppTo, a.Status,
        services, parts,
        // Tổng giờ công định mức — cơ sở ước tính thời gian giữ khoang cho lịch hẹn.
        totalStdManHour = services.Sum(s => s.StdManHour ?? 0)
    });
}).RequireAuthorization();

// 🔴 Trạng thái lịch hẹn theo ĐÚNG nguồn (TConst.Ser_App) — port cũ thiếu bước XÁC NHẬN.
// Nguồn: CREA (mới tạo) → CONF (xác nhận) → ACCE (tiếp nhận, xe đã tới xưởng) · REJ (huỷ).
// "Confirmed" là bước gọi khách xác nhận TRƯỚC khi tới — thiếu nó thì không phân biệt được
// lịch mới đặt với lịch khách đã xác nhận sẽ đến (cơ sở để xưởng giữ khoang).
var appointmentStatusSourceCodes = new Dictionary<string, string>
{
    ["Booked"] = "CREA",       // Mới tạo
    ["Confirmed"] = "CONF",    // Xác nhận  ← port cũ THIẾU
    ["Arrived"] = "ACCE",      // Tiếp nhận (xe đã tới)
    ["Cancelled"] = "REJ",     // Huỷ
    // "Done" KHÔNG có trong TConst.Ser_App — port cũ tự thêm. Giữ cho dữ liệu cũ, đánh dấu rõ.
    ["Done"] = "(port-only)",
};

var appointmentTransitions = new Dictionary<string, string[]>
{
    ["Booked"] = new[] { "Confirmed", "Arrived", "Cancelled" },
    ["Confirmed"] = new[] { "Arrived", "Cancelled" },
    ["Arrived"] = new[] { "Done", "Cancelled" },
    ["Done"] = Array.Empty<string>(),
    ["Cancelled"] = Array.Empty<string>(),
};

app.MapGet("/api/appointments/statuses", () => Results.Ok(new
{
    statuses = appointmentStatusSourceCodes.Select(kv => new { status = kv.Key, sourceCode = kv.Value }),
    transitions = appointmentTransitions.Select(kv => new { from = kv.Key, to = kv.Value }),
    note = "Done không có ở nguồn (TConst.Ser_App chỉ có CREA/CONF/ACCE/REJ) — giữ cho dữ liệu port cũ."
})).RequireAuthorization();

app.MapPost("/api/appointments/{id}/status", async (long id, AppointmentStatusDto dto, AppDbContext db, ITenantContext t) =>
{
    var a = await db.ServiceAppointments.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (a is null) return Results.NotFound(new { id });
    var s = (dto.Status ?? "").Trim();
    if (!appointmentStatusSourceCodes.ContainsKey(s))
        return Results.BadRequest(new { error = $"Trạng thái hợp lệ: {string.Join(", ", appointmentStatusSourceCodes.Keys)}" });
    // Chỉ cho đi theo bảng chuyển tiếp — port cũ cho nhảy tự do giữa mọi trạng thái.
    if (!appointmentTransitions.TryGetValue(a.Status, out var allowedNext) || !allowedNext.Contains(s))
        return Results.BadRequest(new { error = $"Không thể chuyển từ '{a.Status}' sang '{s}'. Cho phép: {string.Join(", ", allowedNext ?? Array.Empty<string>())}" });
    a.Status = s; await db.SaveChangesAsync();
    return Results.Ok(new { a.Id, a.Status, sourceCode = appointmentStatusSourceCodes[s] });
}).RequireAuthorization();

// Bảng trạng thái khoang/bay theo ngày: mỗi khoang trong danh mục + lịch hẹn CÒN HIỆU LỰC của khoang đó
// (Booked/Confirmed/Arrived — tức mọi trạng thái chưa huỷ).
app.MapGet("/api/appointments/cavity-board", async (AppDbContext db, ITenantContext t, DateTime? date) =>
{
    var d0 = (date ?? DateTime.Today).Date; var d1 = d0.AddDays(1);
    var cavities = await db.Cavities.Where(c => c.OrgId == t.OrgId && c.FlagActive == "1").OrderBy(c => c.CavityName).Select(c => c.CavityName).ToListAsync();
    var apps = await db.ServiceAppointments.Where(x => x.OrgId == t.OrgId && x.CavityName != null && x.Status != "Cancelled" && x.AppFrom >= d0 && x.AppFrom < d1)
        .OrderBy(x => x.AppFrom).Select(x => new { x.CavityName, x.AppNo, x.PlateNo, x.CusName, x.ModelName, x.Status, appFrom = x.AppFrom.ToString("HH:mm"), appTo = x.AppTo.ToString("HH:mm") }).ToListAsync();
    var board = cavities.Select(cv => new { cavityName = cv, appointments = apps.Where(a => a.CavityName == cv).ToList() }).ToList();
    return Results.Ok(new { date = d0.ToString("yyyy-MM-dd"), totalCavity = cavities.Count, totalApp = apps.Count, board });
}).RequireAuthorization();

// ===== Công nợ bảo hiểm + thu tiền (InsDebit — port 1:1 FrmInsDebitSearch/FrmInsPaymentCreate, TCMotor) =====
app.MapGet("/api/insdebits", async (AppDbContext db, ITenantContext t, string? q, string? status) =>
{
    var query = db.InsDebits.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(x => x.DebitNo.Contains(q!) || (x.InsName != null && x.InsName.Contains(q!)) || (x.InsNo != null && x.InsNo.Contains(q!)) || (x.RONo != null && x.RONo.Contains(q!)));
    if (!string.IsNullOrWhiteSpace(status)) query = query.Where(x => x.Status == status);
    var items = await query.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.DebitNo, x.InsNo, x.InsName, x.RONo, x.DebitAmount, x.PaidAmount, balance = x.DebitAmount - x.PaidAmount, x.Status, x.Note,
        debitDate = x.DebitDate.HasValue ? x.DebitDate.Value.ToString("yyyy-MM-dd") : ""
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, totalDebit = items.Sum(i => i.DebitAmount), totalPaid = items.Sum(i => i.PaidAmount), totalBalance = items.Sum(i => i.balance), items });
}).RequireAuthorization();

// Tạo công nợ bảo hiểm (hãng BH nợ tiền bồi thường theo RO). DebitAmount > 0.
app.MapPost("/api/insdebits", async (InsDebitDto dto, AppDbContext db, ITenantContext t) =>
{
    if (dto.DebitAmount <= 0) return Results.BadRequest(new { error = "Số tiền công nợ phải lớn hơn 0." });
    var no = "ID" + DateTime.Now.ToString("yyMMddHHmmss");
    var r = new InsDebit { OrgId = t.OrgId, DebitNo = no, InsNo = dto.InsNo, InsName = dto.InsName, RONo = dto.RONo, DebitAmount = dto.DebitAmount, PaidAmount = 0, DebitDate = dto.DebitDate ?? DateTime.Now, Note = dto.Note, Status = "Open" };
    db.InsDebits.Add(r); await db.SaveChangesAsync();
    return Results.Ok(new { r.DebitNo });
}).RequireAuthorization();

app.MapGet("/api/insdebits/{no}/payments", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.InsDebits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DebitNo == no);
    if (h is null) return Results.NotFound(new { no });
    var pays = await db.InsDebitPayments.Where(p => p.OrgId == t.OrgId && p.InsDebitId == h.Id).OrderBy(p => p.Id)
        .Select(p => new { p.PaymentAmount, p.Note, p.PaymentNo, p.DealerCode, p.PayPersonName, p.PayPersonIDCardNo, payDate = p.PayDate.HasValue ? p.PayDate.Value.ToString("yyyy-MM-dd") : "" }).ToListAsync();
    return Results.Ok(new { h.DebitNo, h.DebitAmount, h.PaidAmount, balance = h.DebitAmount - h.PaidAmount, h.Status, count = pays.Count, payments = pays });
}).RequireAuthorization();

// Thu tiền công nợ bảo hiểm (không vượt số dư; đủ tiền -> Paid).
app.MapPost("/api/insdebits/{no}/payments", async (string no, InsDebitPaymentDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.InsDebits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DebitNo == no);
    if (h is null) return Results.NotFound(new { no });
    if (dto.PaymentAmount <= 0) return Results.BadRequest(new { error = "Số tiền thu phải lớn hơn 0." });
    // Guard của nguồn (checkPaymentFieldEmpty): đại lý + người nộp + CMND/CCCD + ngày thu đều BẮT BUỘC.
    // ⚠️ CusID KHÔNG bắt buộc — nguồn đã COMMENT dòng truyền strCusID vào hàm check (luật "port dòng active").
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Chưa nhập mã đại lý." });
    if (string.IsNullOrWhiteSpace(dto.PayPersonName)) return Results.BadRequest(new { error = "Chưa nhập tên người nộp tiền." });
    if (string.IsNullOrWhiteSpace(dto.PayPersonIDCardNo)) return Results.BadRequest(new { error = "Chưa nhập số CMND/CCCD người nộp tiền." });
    if (dto.PayDate is null) return Results.BadRequest(new { error = "Chưa nhập ngày thu tiền." });
    var balance = h.DebitAmount - h.PaidAmount;
    if (dto.PaymentAmount > balance) return Results.BadRequest(new { error = $"Số tiền thu vượt số dư công nợ ({balance})." });
    db.InsDebitPayments.Add(new InsDebitPayment { OrgId = t.OrgId, InsDebitId = h.Id, PaymentAmount = dto.PaymentAmount, PayDate = dto.PayDate ?? DateTime.Now, Note = dto.Note,
        PaymentNo = "PM" + DateTime.Now.ToString("yyMMddHHmmss"), DealerCode = dto.DealerCode, PayPersonName = dto.PayPersonName, PayPersonIDCardNo = dto.PayPersonIDCardNo });
    h.PaidAmount += dto.PaymentAmount;
    if (h.PaidAmount >= h.DebitAmount) h.Status = "Paid";
    await db.SaveChangesAsync();
    return Results.Ok(new { h.DebitNo, paidAmount = h.PaidAmount, balance = h.DebitAmount - h.PaidAmount, status = h.Status });
}).RequireAuthorization();

// ===== Công nợ nhà cung cấp phụ tùng + thu tiền (SupplierDebit — port 1:1 FrmSuplierDebitCreate/FrmSupplierDebitSearch/FrmSupplierPaymentCreate, TCMotor DMSCarSv/Debit) =====
app.MapGet("/api/supplierdebits", async (AppDbContext db, ITenantContext t, string? supplier, string? status) =>
{
    var query = db.SupplierDebits.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(supplier)) query = query.Where(x => x.SupplierCode == supplier);
    if (!string.IsNullOrWhiteSpace(status)) query = query.Where(x => x.Status == status);
    var items = await query.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.Id, x.SupplierCode, x.StockInNo, x.DebitAmount, x.PaidAmount, balance = x.DebitAmount - x.PaidAmount, x.Status, x.Note,
        debitDate = x.DebitDate.HasValue ? x.DebitDate.Value.ToString("yyyy-MM-dd") : ""
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, totalDebit = items.Sum(i => i.DebitAmount), totalPaid = items.Sum(i => i.PaidAmount), totalBalance = items.Sum(i => i.balance), items });
}).RequireAuthorization();

// Tạo/cộng dồn nợ NCC theo (SupplierCode, StockInNo) — khớp Check_HaveDebit_01 WinForm gốc.
app.MapPost("/api/supplierdebits", async (SupplierDebitDto dto, AppDbContext db, ITenantContext t) =>
{
    var supplier = (dto.SupplierCode ?? "").Trim();
    if (string.IsNullOrWhiteSpace(supplier)) return Results.BadRequest(new { error = "Chưa chọn nhà cung cấp." });
    if (dto.DebitAmount <= 0) return Results.BadRequest(new { error = "Số tiền nợ phải lớn hơn 0." });
    if (dto.DebitDate is null) return Results.BadRequest(new { error = "Chưa nhập ngày trả nợ." });
    var stockIn = (dto.StockInNo ?? "").Trim();
    // audit 2026-09-03: CheckDebitAmount() gốc chặn số tiền nợ > dDefaultDebitAmount (số tiền phải trả = tổng phiếu nhập) — port trước thiếu guard này.
    if (!string.IsNullOrWhiteSpace(stockIn))
    {
        var stockInTotal = await db.ServiceStockIns.Where(x => x.OrgId == t.OrgId && x.StockInNo == stockIn).Select(x => (decimal?)x.TotalAmount).FirstOrDefaultAsync();
        if (stockInTotal is not null)
        {
            var already = await db.SupplierDebits.Where(x => x.OrgId == t.OrgId && x.SupplierCode == supplier && x.StockInNo == stockIn).Select(x => x.DebitAmount).FirstOrDefaultAsync();
            if (already + dto.DebitAmount > stockInTotal.Value)
                return Results.BadRequest(new { error = $"Số tiền nợ vượt quá số tiền phải trả ({stockInTotal.Value})." });
        }
    }
    var row = await db.SupplierDebits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SupplierCode == supplier && x.StockInNo == stockIn);
    var isNew = row is null;
    if (isNew) { row = new SupplierDebit { OrgId = t.OrgId, SupplierCode = supplier, StockInNo = stockIn, Status = "Open" }; db.SupplierDebits.Add(row); }
    row!.DebitAmount += dto.DebitAmount; row.DebitDate = dto.DebitDate; row.Note = dto.Note;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.SupplierCode, row.StockInNo, row.DebitAmount, isNew });
}).RequireAuthorization();

app.MapDelete("/api/supplierdebits/{id:long}", async (long id, AppDbContext db, ITenantContext t) =>
{
    var row = await db.SupplierDebits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (row is null) return Results.NotFound(new { id });
    db.SupplierDebits.Remove(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = id });
}).RequireAuthorization();

app.MapGet("/api/supplierdebits/{id:long}/payments", async (long id, AppDbContext db, ITenantContext t) =>
{
    var h = await db.SupplierDebits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { id });
    var pays = await db.SupplierDebitPayments.Where(p => p.OrgId == t.OrgId && p.SupplierDebitId == h.Id).OrderBy(p => p.Id)
        .Select(p => new { p.PaymentAmount, p.Note, p.PaymentNo, p.DealerCode, p.PayPersonName, p.PayPersonIDCardNo, payDate = p.PayDate.HasValue ? p.PayDate.Value.ToString("yyyy-MM-dd") : "" }).ToListAsync();
    return Results.Ok(new { h.Id, h.DebitAmount, h.PaidAmount, balance = h.DebitAmount - h.PaidAmount, h.Status, count = pays.Count, payments = pays });
}).RequireAuthorization();

// Thanh toán nợ NCC (không vượt số dư; đủ tiền -> Paid).
app.MapPost("/api/supplierdebits/{id:long}/payments", async (long id, SupplierDebitPaymentDto dto, AppDbContext db, ITenantContext t) =>
{
    var h = await db.SupplierDebits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { id });
    if (dto.PaymentAmount <= 0) return Results.BadRequest(new { error = "Số tiền trả phải lớn hơn 0." });
    // Guard của nguồn (checkPaymentFieldEmpty): đại lý + người nộp + CMND/CCCD + ngày thu đều BẮT BUỘC.
    // ⚠️ CusID KHÔNG bắt buộc — nguồn đã COMMENT dòng truyền strCusID vào hàm check (luật "port dòng active").
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Chưa nhập mã đại lý." });
    if (string.IsNullOrWhiteSpace(dto.PayPersonName)) return Results.BadRequest(new { error = "Chưa nhập tên người nộp tiền." });
    if (string.IsNullOrWhiteSpace(dto.PayPersonIDCardNo)) return Results.BadRequest(new { error = "Chưa nhập số CMND/CCCD người nộp tiền." });
    if (dto.PayDate is null) return Results.BadRequest(new { error = "Chưa nhập ngày thu tiền." });
    var balance = h.DebitAmount - h.PaidAmount;
    if (dto.PaymentAmount > balance) return Results.BadRequest(new { error = $"Số tiền trả vượt số dư công nợ ({balance})." });
    db.SupplierDebitPayments.Add(new SupplierDebitPayment { OrgId = t.OrgId, SupplierDebitId = h.Id, PaymentAmount = dto.PaymentAmount, PayDate = dto.PayDate ?? DateTime.Now, Note = dto.Note,
        PaymentNo = "PM" + DateTime.Now.ToString("yyMMddHHmmss"), DealerCode = dto.DealerCode, PayPersonName = dto.PayPersonName, PayPersonIDCardNo = dto.PayPersonIDCardNo });
    h.PaidAmount += dto.PaymentAmount;
    if (h.PaidAmount >= h.DebitAmount) h.Status = "Paid";
    await db.SaveChangesAsync();
    return Results.Ok(new { h.Id, paidAmount = h.PaidAmount, balance = h.DebitAmount - h.PaidAmount, status = h.Status });
}).RequireAuthorization();

// ===== 🔴 PHÂN BỔ 1 PHIẾU THU sang NHIỀU CÔNG NỢ (luật của nguồn mà port cũ làm mất) =====
// Nguồn BizCarSv.Debit.cs:2976-3007: 1 phiếu thu (Ser_Payment) sinh NHIỀU dòng Ser_PaymentDetail,
// trả lần lượt các công nợ CHƯA HẾT DƯ cho tới khi hết tiền. Port cũ gắn CHẶT 1 lần thu = 1 công nợ
// ⇒ thu 1 lần cho nhiều RO phải tự tay bổ ra từng dòng, và số phiếu thu không nối được các dòng đó với nhau.
// Ba chủ thể (khách hàng / bảo hiểm / nhà cung cấp) dùng CHUNG luật này — nguồn chỉ khác cột khoá.
app.MapPost("/api/debits/allocate-payment", async (
    string subject, SerPaymentAllocateDto dto, AppDbContext db, ITenantContext t) =>
{
    subject = (subject ?? "").Trim().ToLowerInvariant();
    if (subject != "cus" && subject != "ins" && subject != "supplier")
        return Results.BadRequest(new { error = "subject phải là cus | ins | supplier." });

    // Guard của nguồn (checkPaymentFieldEmpty).
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Chưa nhập mã đại lý." });
    if (dto.PaymentAmount <= 0) return Results.BadRequest(new { error = "Số tiền thu phải lớn hơn 0." });
    if (string.IsNullOrWhiteSpace(dto.PayPersonName)) return Results.BadRequest(new { error = "Chưa nhập tên người nộp tiền." });
    if (string.IsNullOrWhiteSpace(dto.PayPersonIDCardNo)) return Results.BadRequest(new { error = "Chưa nhập số CMND/CCCD người nộp tiền." });
    if (dto.PayDate is null) return Results.BadRequest(new { error = "Chưa nhập ngày thu tiền." });
    if (string.IsNullOrWhiteSpace(dto.SubjectKey))
        return Results.BadRequest(new { error = "Chưa chọn chủ thể công nợ (mã KH / số HĐ bảo hiểm / mã NCC)." });

    var payNo = "PM" + DateTime.Now.ToString("yyMMddHHmmss");
    var payDate = dto.PayDate;
    var remaining = dto.PaymentAmount;
    var allocated = new List<object>();

    // ⚠️ LỆCH CÓ CHỦ ĐÍCH so với nguồn: nguồn so sánh "dư nợ > tiền còn lại" nên khi BẰNG NHAU sẽ đi nhánh
    // else rồi vòng sau sinh thêm 1 dòng phân bổ SỐ TIỀN 0. Ở đây dừng ngay khi hết tiền.
    // Tiền dư (nếu trả quá tổng nợ) KHÔNG bị chặn — giống nguồn — mà trả về ở "unallocated".
    if (subject == "cus")
    {
        var debts = await db.CusDebits.Where(x => x.OrgId == t.OrgId && x.CusId == dto.SubjectKey
                        && x.DebitAmount > x.PaidAmount).OrderBy(x => x.Id).ToListAsync();
        foreach (var h in debts)
        {
            if (remaining <= 0) break;
            var left = h.DebitAmount - h.PaidAmount;
            var take = left > remaining ? remaining : left;
            db.CusDebitPayments.Add(new CusDebitPayment { OrgId = t.OrgId, CusDebitId = h.Id, PaymentAmount = take,
                PayDate = payDate, Note = dto.Note, PaymentNo = payNo, DealerCode = dto.DealerCode,
                PayPersonName = dto.PayPersonName, PayPersonIDCardNo = dto.PayPersonIDCardNo });
            h.PaidAmount += take;
            if (h.PaidAmount >= h.DebitAmount) h.Status = "Paid";
            remaining -= take;
            allocated.Add(new { debitNo = h.DebitNo, amount = take, status = h.Status });
        }
    }
    else if (subject == "ins")
    {
        var debts = await db.InsDebits.Where(x => x.OrgId == t.OrgId && x.InsNo == dto.SubjectKey
                        && x.DebitAmount > x.PaidAmount).OrderBy(x => x.Id).ToListAsync();
        foreach (var h in debts)
        {
            if (remaining <= 0) break;
            var left = h.DebitAmount - h.PaidAmount;
            var take = left > remaining ? remaining : left;
            db.InsDebitPayments.Add(new InsDebitPayment { OrgId = t.OrgId, InsDebitId = h.Id, PaymentAmount = take,
                PayDate = payDate, Note = dto.Note, PaymentNo = payNo, DealerCode = dto.DealerCode,
                PayPersonName = dto.PayPersonName, PayPersonIDCardNo = dto.PayPersonIDCardNo });
            h.PaidAmount += take;
            if (h.PaidAmount >= h.DebitAmount) h.Status = "Paid";
            remaining -= take;
            allocated.Add(new { debitNo = h.DebitNo, amount = take, status = h.Status });
        }
    }
    else
    {
        var debts = await db.SupplierDebits.Where(x => x.OrgId == t.OrgId && x.SupplierCode == dto.SubjectKey
                        && x.DebitAmount > x.PaidAmount).OrderBy(x => x.Id).ToListAsync();
        foreach (var h in debts)
        {
            if (remaining <= 0) break;
            var left = h.DebitAmount - h.PaidAmount;
            var take = left > remaining ? remaining : left;
            db.SupplierDebitPayments.Add(new SupplierDebitPayment { OrgId = t.OrgId, SupplierDebitId = h.Id, PaymentAmount = take,
                PayDate = payDate, Note = dto.Note, PaymentNo = payNo, DealerCode = dto.DealerCode,
                PayPersonName = dto.PayPersonName, PayPersonIDCardNo = dto.PayPersonIDCardNo });
            h.PaidAmount += take;
            if (h.PaidAmount >= h.DebitAmount) h.Status = "Paid";
            remaining -= take;
            allocated.Add(new { debitNo = h.StockInNo ?? "", amount = take, status = h.Status });
        }
    }

    if (allocated.Count == 0)
        return Results.BadRequest(new { error = "Chủ thể này không còn công nợ nào chưa trả hết." });

    await db.SaveChangesAsync();
    return Results.Ok(new { paymentNo = payNo, subject, subjectKey = dto.SubjectKey,
        paymentAmount = dto.PaymentAmount, allocatedAmount = dto.PaymentAmount - remaining,
        unallocated = remaining, count = allocated.Count, allocated });
}).RequireAuthorization();

// Tra 1 phiếu thu theo SỐ PHIẾU — gom các dòng phân bổ của cùng lần nộp (cả 3 chủ thể).
app.MapGet("/api/debits/payments/{paymentNo}", async (string paymentNo, AppDbContext db, ITenantContext t) =>
{
    var no = paymentNo.Trim();
    var cus = await db.CusDebitPayments.Where(x => x.OrgId == t.OrgId && x.PaymentNo == no)
        .Select(x => new { subject = "cus", x.PaymentAmount, x.DealerCode, x.PayPersonName, x.PayPersonIDCardNo, x.Note,
            payDate = x.PayDate.HasValue ? x.PayDate.Value.ToString("yyyy-MM-dd") : "" }).ToListAsync();
    var ins = await db.InsDebitPayments.Where(x => x.OrgId == t.OrgId && x.PaymentNo == no)
        .Select(x => new { subject = "ins", x.PaymentAmount, x.DealerCode, x.PayPersonName, x.PayPersonIDCardNo, x.Note,
            payDate = x.PayDate.HasValue ? x.PayDate.Value.ToString("yyyy-MM-dd") : "" }).ToListAsync();
    var sup = await db.SupplierDebitPayments.Where(x => x.OrgId == t.OrgId && x.PaymentNo == no)
        .Select(x => new { subject = "supplier", x.PaymentAmount, x.DealerCode, x.PayPersonName, x.PayPersonIDCardNo, x.Note,
            payDate = x.PayDate.HasValue ? x.PayDate.Value.ToString("yyyy-MM-dd") : "" }).ToListAsync();
    var all = cus.Concat(ins).Concat(sup).ToList();
    if (all.Count == 0) return Results.NotFound(new { paymentNo = no });
    return Results.Ok(new { paymentNo = no, count = all.Count, totalAmount = all.Sum(x => x.PaymentAmount), lines = all });
}).RequireAuthorization();

// ===== Báo cáo công nợ (report tái-dùng CusDebit + InsDebit — port 1:1 FrmReportTotalCusDebit/InsDebit/ReceivableDebit + FrmReportSerPaymentGet, TCMotor) =====
// Tổng công nợ phải thu: gộp dư nợ khách hàng + hãng bảo hiểm (mỗi bên 1 nhóm), có tổng cộng.
app.MapGet("/api/report/receivable-debt", async (AppDbContext db, ITenantContext t, string? debtorType) =>
{
    var cus = await db.CusDebits.Where(x => x.OrgId == t.OrgId && x.DebitAmount > x.PaidAmount)
        .GroupBy(x => new { x.CusId, x.CusName })
        .Select(g => new { debtorType = "Customer", code = g.Key.CusId, name = g.Key.CusName, debit = g.Sum(x => x.DebitAmount), paid = g.Sum(x => x.PaidAmount), balance = g.Sum(x => x.DebitAmount - x.PaidAmount) }).ToListAsync();
    var ins = await db.InsDebits.Where(x => x.OrgId == t.OrgId && x.DebitAmount > x.PaidAmount)
        .GroupBy(x => new { x.InsNo, x.InsName })
        .Select(g => new { debtorType = "Insurance", code = g.Key.InsNo, name = g.Key.InsName, debit = g.Sum(x => x.DebitAmount), paid = g.Sum(x => x.PaidAmount), balance = g.Sum(x => x.DebitAmount - x.PaidAmount) }).ToListAsync();
    var all = cus.Concat(ins).ToList();
    if (!string.IsNullOrWhiteSpace(debtorType)) all = all.Where(r => r.debtorType == debtorType).ToList();
    all = all.OrderByDescending(r => r.balance).ToList();
    return Results.Ok(new { totalCustomer = cus.Sum(r => r.balance), totalInsurance = ins.Sum(r => r.balance), grandTotal = all.Sum(r => r.balance), rows = all });
}).RequireAuthorization();

// ===== 🔴 #215 TÌM KIẾM CÔNG NỢ (3 loại) — `SerCusDebitSearch` =====
// Màn gốc: `Views/Debit/FrmCusDebitSearch.cs` (258 dòng, DMSCarSv) — hai nút `btnSearch` · `btnExit`.
// Nguồn: `TERP.BizCarSv/BizCarSv.Debit.cs:1632`; WS LIVE (`WSCarSv.asmx.cs:18250`) gọi đúng hàm này.
// BƯỚC 3B: md5 CẢ FILE `9119d491` (3784 dòng) KHỚP 2 máy.
//
// 🔴 PHÁT HIỆN GIẢI THÍCH #213/#214: nguồn lọc **`d.DebitType = @DebitType` VÀ `r.PaymentType = @DebitType`**
//    — tức mã loại nợ và mã loại phiếu thu DÙNG CHUNG một bộ hằng `TConst.SerDebitType` (Const.Main.cs:372):
//      **1 = khách hàng · 2 = bảo hiểm · 3 = nhà cung cấp**.
//    ⇒ `PaymentType='1'` ở #213 và `'2'` ở #214 không phải hai quy ước rời rạc mà là CÙNG một bảng mã.
//    Nguồn có hẳn ba nhánh SQL theo `DebitType` (1632: khách hàng · 1876: bảo hiểm · 1930: nhà cung cấp).
//
// 🔴 Bộ lọc của nguồn dựng bằng `SqlUtils.BuildClause` với chuỗi điều kiện đã ghép sẵn ở tầng service:
//    tên/hãng BH/NCC nhận dạng `"like %giá trị%"` ⇒ **so khớp CHỨA, không phân biệt hoa thường**.
//    Riêng `strIsDebit`: nếu = `Flag.Active` ("1") thì thành `"> 0"`, ngược lại **chuỗi rỗng ⇒ BỎ HẲN điều kiện**
//    (không phải lọc `= 0`). Nghĩa là: bật cờ ⇒ chỉ hiện dòng CÒN nợ; tắt cờ ⇒ hiện TẤT CẢ.
app.MapGet("/api/debits/search", async (AppDbContext db, ITenantContext t,
    string? debitType, string? name, string? plateNo, string? insName, string? supplierName, string? isDebit) =>
{
    var dt = (debitType ?? "1").Trim();
    if (dt is not ("1" or "2" or "3"))
        return Results.BadRequest(new { error = "Loại công nợ chỉ nhận 1 (khách hàng) | 2 (bảo hiểm) | 3 (nhà cung cấp)." });
    var onlyDebt = (isDebit ?? "").Trim() == "1";   // nguồn: Flag.Active ⇒ "> 0"; ngược lại bỏ hẳn điều kiện

    var rows = new List<object>();
    if (dt == "1")
    {
        var q1 = db.CusDebits.Where(x => x.OrgId == t.OrgId);
        if (!string.IsNullOrWhiteSpace(name)) q1 = q1.Where(x => x.CusName != null && x.CusName.ToLower().Contains(name!.Trim().ToLower()));
        var list = await q1.GroupBy(x => new { x.CusId, x.CusName })
            .Select(g => new { g.Key.CusId, g.Key.CusName, Debit = g.Sum(x => x.DebitAmount), Paid = g.Sum(x => x.PaidAmount) })
            .ToListAsync();
        rows.AddRange(list.Select(x => new { code = x.CusId, itemName = x.CusName, debitType = dt,
                                            debitAmount = x.Debit, paymentAmount = x.Paid, remain = x.Debit - x.Paid })
                          .Where(r => !onlyDebt || r.remain > 0).Cast<object>());
    }
    else if (dt == "2")
    {
        var q2 = db.InsDebits.Where(x => x.OrgId == t.OrgId);
        if (!string.IsNullOrWhiteSpace(insName)) q2 = q2.Where(x => x.InsName != null && x.InsName.ToLower().Contains(insName!.Trim().ToLower()));
        var list = await q2.GroupBy(x => new { x.InsNo, x.InsName })
            .Select(g => new { g.Key.InsNo, g.Key.InsName, Debit = g.Sum(x => x.DebitAmount), Paid = g.Sum(x => x.PaidAmount) })
            .ToListAsync();
        rows.AddRange(list.Select(x => new { code = x.InsNo, itemName = x.InsName, debitType = dt,
                                            debitAmount = x.Debit, paymentAmount = x.Paid, remain = x.Debit - x.Paid })
                          .Where(r => !onlyDebt || r.remain > 0).Cast<object>());
    }
    else
    {
        var q3 = db.SupplierDebits.Where(x => x.OrgId == t.OrgId);
        // Entity MiniHTC chỉ có SupplierCode (không lưu tên NCC) ⇒ lọc theo MÃ; tên do bảng NCC riêng giữ.
        if (!string.IsNullOrWhiteSpace(supplierName)) q3 = q3.Where(x => x.SupplierCode.ToLower().Contains(supplierName!.Trim().ToLower()));
        var list = await q3.GroupBy(x => new { x.SupplierCode })
            .Select(g => new { g.Key.SupplierCode, Debit = g.Sum(x => x.DebitAmount), Paid = g.Sum(x => x.PaidAmount) })
            .ToListAsync();
        rows.AddRange(list.Select(x => new { code = x.SupplierCode, itemName = (string?)null, debitType = dt,
                                            debitAmount = x.Debit, paymentAmount = x.Paid, remain = x.Debit - x.Paid })
                          .Where(r => !onlyDebt || r.remain > 0).Cast<object>());
    }

    return Results.Ok(new { debitType = dt, onlyDebt, count = rows.Count, rows,
        note = "DebitType dùng chung bảng mã với PaymentType (TConst.SerDebitType: 1 KH · 2 BH · 3 NCC).",
        skipped = "Bộ lọc biển số/nhóm KH của nguồn cần bảng Ser_Car + Ser_CustomerGroup — chưa nối, KHÔNG bịa." });
}).RequireAuthorization();

// ===== 🔴 #214 CÔNG NỢ BẢO HIỂM theo KỲ — `Ser_InvReportInsuranceDebitRpt_New20210618` =====
// Màn gốc: `Views/Debit/FrmReportTotalInsDebit.cs` (303 dòng, DMSCarSv) — 4 nút Search/Print/Export/Thoát.
// Nguồn: `TERP.BizCarSv/BizCarSv.Service.Report.cs:2392`. md5 CẢ FILE `b7ecca4c` KHỚP 2 máy.
//
// 🔴 TWIN + FILE CHẾT (bắt được nhờ trace, không theo tên):
//   · Biz có HAI hàm cùng tên: `Ser_InvReportInsuranceDebitRpt` (2184) và `..._New20210618` (2392).
//   · Thư mục WS có BA file: `WSCarSv.asmx.20210208.cs` · `WSCarSv.asmx.20210412.cs` · `WSCarSv.asmx.cs`;
//     csproj chỉ `<Compile Include="WSCarSv.asmx.cs">` ⇒ hai file có ngày trong tên là **FILE CHẾT**.
//   · Hai file chết gọi bản 2184; **bản LIVE (13080) gọi `_New20210618`** ⇒ port theo 2392.
//
// Báo cáo theo KỲ (FromDate..ToDate), mỗi hãng bảo hiểm 4 chỉ tiêu:
//   `TGD` dư đầu kỳ  = (nợ phát sinh TRƯỚC FromDate) − (thu TRƯỚC FromDate)
//   `PST` phát sinh tăng = nợ trong kỳ          `PSG` phát sinh giảm = thu trong kỳ
//   `TGC` dư cuối kỳ = TGD + PST − PSG
// 🔴 Thu của nhánh BẢO HIỂM lọc `PaymentType = '2'` — khác nhánh KHÁCH HÀNG dùng `'1'` (xem #213).
//    Hai mã này là hai loại phiếu thu khác nhau, KHÔNG được dùng lẫn.
// 🔴 Guard cuối của nguồn: `where (deb.InsNo is not null or dk.InsNo is not null)` — hãng nào **không có
//    phát sinh trong kỳ VÀ không có dư đầu kỳ** thì KHÔNG lên báo cáo (khác với lọc `số dư != 0` ở #213).
app.MapGet("/api/report/insurance-debit", async (AppDbContext db, ITenantContext t, DateTime? fromDate, DateTime? toDate) =>
{
    var from = (fromDate ?? DateTime.Today.AddMonths(-1)).Date;
    var to = (toDate ?? DateTime.Today).Date;
    if (from > to) return Results.BadRequest(new { error = "Từ ngày phải nhỏ hơn hoặc bằng đến ngày." });

    var debits = await db.InsDebits.Where(x => x.OrgId == t.OrgId).ToListAsync();
    var pays = await (from p in db.InsDebitPayments.Where(x => x.OrgId == t.OrgId)
                      join h in db.InsDebits.Where(x => x.OrgId == t.OrgId) on p.InsDebitId equals h.Id
                      select new { h.InsNo, h.InsName, p.PaymentAmount, p.PayDate }).ToListAsync();

    var keys = debits.Select(d => new { d.InsNo, d.InsName })
        .Concat(pays.Select(p => new { p.InsNo, p.InsName }))
        .Distinct().ToList();

    var rows = new List<object>();
    decimal sTGD = 0, sPST = 0, sPSG = 0, sTGC = 0;
    foreach (var k in keys)
    {
        // dư ĐẦU KỲ: mọi phát sinh TRƯỚC FromDate (nguồn: substring(...) < @FromDate).
        var debBefore = debits.Where(d => d.InsNo == k.InsNo && d.DebitDate.HasValue && d.DebitDate.Value.Date < from).Sum(d => d.DebitAmount);
        var payBefore = pays.Where(p => p.InsNo == k.InsNo && p.PayDate.HasValue && p.PayDate.Value.Date < from).Sum(p => p.PaymentAmount);
        var tgd = debBefore - payBefore;

        // trong kỳ
        var pst = debits.Where(d => d.InsNo == k.InsNo && d.DebitDate.HasValue && d.DebitDate.Value.Date >= from && d.DebitDate.Value.Date <= to).Sum(d => d.DebitAmount);
        var psg = pays.Where(p => p.InsNo == k.InsNo && p.PayDate.HasValue && p.PayDate.Value.Date >= from && p.PayDate.Value.Date <= to).Sum(p => p.PaymentAmount);

        // guard của nguồn: không có phát sinh trong kỳ VÀ không có dư đầu kỳ thì bỏ hẳn dòng.
        var hasInPeriod = pst != 0 || psg != 0;
        if (!hasInPeriod && tgd == 0) continue;

        var tgc = tgd + pst - psg;
        sTGD += tgd; sPST += pst; sPSG += psg; sTGC += tgc;
        rows.Add(new { insNo = k.InsNo, insName = k.InsName, tgd, pst, psg, tgc });
    }

    return Results.Ok(new
    {
        fromDate = from, toDate = to,
        totalTGD = sTGD, totalPST = sPST, totalPSG = sPSG, totalTGC = sTGC,
        count = rows.Count, rows,
        note = "PSG chỉ gồm phiếu thu loại bảo hiểm (nguồn lọc PaymentType='2'); nhánh khách hàng dùng '1'."
    });
}).RequireAuthorization();

// ===== 🔴 #213 CÔNG NỢ PHẢI THU tại thời điểm — `Ser_ReportReceivableDebitRpt` =====
// Màn gốc: `TERP.HTCServiceClient/Views/Debit/FrmReportTotalReceivableDebit.cs` (274 dòng, DMSCarSv) —
//   bốn nút `btnSearch` · `btnPrint` · `btnExportExcel` · `btnThoat` (đã grep KHÔNG phân biệt hoa/thường).
// Nguồn: `TERP.BizCarSv/BizCarSv.Service.Report.cs:2605`.
// BƯỚC 3B: md5 CẢ FILE `b7ecca4c` (7315 dòng) KHỚP 2 máy (laptop `.Release.V2` ≡ máy 150 `.Release`).
//
// Nguồn gom **BA nguồn nợ** rồi ghép, lọc bỏ dòng có số dư = 0:
//  1. **Bảo hiểm nợ**: `ser_insurance` ⟗ (nợ `ser_cusdebit` gom theo `InsNo`) − (thu `Ser_Payment` gom theo `InsNo`);
//  2. **Khách hàng nợ**: `ser_customer` ⟗ (nợ gom theo `CusID`) − (thu gom theo `CusID`, **chỉ `PaymentType='1'`**);
//  3. **Bảng chốt lịch sử** `BaoCoCongNoKhachHang_20170101` — dữ liệu cũ, ghép bằng `union` (khử trùng).
//
// 🔴 BA CHI TIẾT DỄ MẤT khi port:
//  · Lọc mốc thời gian của nguồn là `substring(DebitDate,1,11) <= @ToDate` ⇒ cột ngày ở nguồn là **VARCHAR**;
//    MiniHTC lưu `DateTime?` nên so sánh theo NGÀY (`.Date <=`) — cùng ngữ nghĩa, ghi rõ để khỏi tưởng lệch.
//  · Nhánh KHÁCH HÀNG lọc `PaymentType='1'`; nhánh BẢO HIỂM **không** lọc — bất đối xứng CÓ CHỦ Ý, giữ nguyên.
//  · Hai nhánh đầu ghép bằng `union all` (giữ trùng), riêng bảng lịch sử ghép bằng `union` (khử trùng).
// ⚠️ NỢ: bảng chốt `BaoCoCongNoKhachHang_20170101` nằm ở DB CommonCenter, MiniHTC chưa có ⇒ **KHÔNG bịa**;
//   endpoint trả `legacyRows: null` kèm ghi chú thay vì lặng lẽ bỏ nguồn thứ ba.
app.MapGet("/api/report/receivable-debit", async (AppDbContext db, ITenantContext t, DateTime? toDate) =>
{
    var cut = (toDate ?? DateTime.Today).Date;

    // (1) nợ + thu theo KHÁCH HÀNG
    var cusDebits = await db.CusDebits.Where(x => x.OrgId == t.OrgId)
        .Where(x => x.DebitDate == null || x.DebitDate.Value.Date <= cut)
        .GroupBy(x => new { x.CusId, x.CusName })
        .Select(g => new { g.Key.CusId, g.Key.CusName, Debit = g.Sum(x => x.DebitAmount), Paid = g.Sum(x => x.PaidAmount) })
        .ToListAsync();

    // (2) nợ + thu theo HÃNG BẢO HIỂM
    var insDebits = await db.InsDebits.Where(x => x.OrgId == t.OrgId)
        .Where(x => x.DebitDate == null || x.DebitDate.Value.Date <= cut)
        .GroupBy(x => new { x.InsNo, x.InsName })
        .Select(g => new { g.Key.InsNo, g.Key.InsName, Debit = g.Sum(x => x.DebitAmount), Paid = g.Sum(x => x.PaidAmount) })
        .ToListAsync();

    var insRows = insDebits
        .Select(x => new { itemCode = x.InsNo, itemName = x.InsName, remark = "Bảo hiểm nợ", debitAmount = x.Debit - x.Paid })
        .Where(r => r.debitAmount != 0).ToList();
    var cusRows = cusDebits
        .Select(x => new { itemCode = x.CusId, itemName = x.CusName, remark = "Khách hàng nợ", debitAmount = x.Debit - x.Paid })
        .Where(r => r.debitAmount != 0).ToList();

    // union all giữa hai nhánh — đúng nguồn (không khử trùng).
    var rows = insRows.Concat(cusRows).OrderByDescending(r => r.debitAmount).ToList();

    return Results.Ok(new
    {
        toDate = cut,
        totalInsurance = insRows.Sum(r => r.debitAmount),
        totalCustomer = cusRows.Sum(r => r.debitAmount),
        grandTotal = rows.Sum(r => r.debitAmount),
        count = rows.Count,
        rows,
        legacyRows = (object?)null,
        note = "Nguồn còn union bảng chốt lịch sử BaoCoCongNoKhachHang_20170101 (DB CommonCenter) — MiniHTC chưa có bảng này, KHÔNG bịa dữ liệu."
    });
}).RequireAuthorization();

// Báo cáo tổng công nợ khách hàng: đầu kỳ 0, phát sinh tăng = tổng nợ, phát sinh giảm = tổng thu, cuối kỳ = dư nợ.
app.MapGet("/api/report/cusdebit-total", async (AppDbContext db, ITenantContext t) =>
{
    var rows = await db.CusDebits.Where(x => x.OrgId == t.OrgId)
        .GroupBy(x => new { x.CusId, x.CusName })
        .Select(g => new { code = g.Key.CusId, name = g.Key.CusName, increase = g.Sum(x => x.DebitAmount), decrease = g.Sum(x => x.PaidAmount), closing = g.Sum(x => x.DebitAmount - x.PaidAmount), count = g.Count() })
        .OrderByDescending(r => r.closing).ToListAsync();
    return Results.Ok(new { totalIncrease = rows.Sum(r => r.increase), totalDecrease = rows.Sum(r => r.decrease), totalClosing = rows.Sum(r => r.closing), rows });
}).RequireAuthorization();

// Báo cáo lịch sử thu tiền dịch vụ: gộp thu tiền khách hàng + bảo hiểm theo ngày.
app.MapGet("/api/report/service-payments", async (AppDbContext db, ITenantContext t, DateTime? fromDate, DateTime? toDate) =>
{
    var cusPay = await (from p in db.CusDebitPayments.Where(x => x.OrgId == t.OrgId)
                        join h in db.CusDebits.Where(x => x.OrgId == t.OrgId) on p.CusDebitId equals h.Id
                        select new { p.PaymentAmount, p.PayDate, debitNo = h.DebitNo, payer = h.CusName, payerType = "Customer", p.Note }).ToListAsync();
    var insPay = await (from p in db.InsDebitPayments.Where(x => x.OrgId == t.OrgId)
                        join h in db.InsDebits.Where(x => x.OrgId == t.OrgId) on p.InsDebitId equals h.Id
                        select new { p.PaymentAmount, p.PayDate, debitNo = h.DebitNo, payer = h.InsName, payerType = "Insurance", p.Note }).ToListAsync();
    var all = cusPay.Concat(insPay);
    if (fromDate.HasValue) all = all.Where(x => x.PayDate.HasValue && x.PayDate.Value.Date >= fromDate.Value.Date);
    if (toDate.HasValue) all = all.Where(x => x.PayDate.HasValue && x.PayDate.Value.Date <= toDate.Value.Date);
    var rows = all.OrderByDescending(x => x.PayDate).Select(x => new { x.debitNo, x.payer, x.payerType, x.PaymentAmount, payDate = x.PayDate.HasValue ? x.PayDate.Value.ToString("yyyy-MM-dd") : "", x.Note }).ToList();
    return Results.Ok(new { count = rows.Count, total = rows.Sum(r => r.PaymentAmount), rows });
}).RequireAuthorization();

// ===== Chia sẻ phụ tùng giữa đại lý (SharePart — port 1:1 FrmSharePart/ShareDealer, TCMotor) =====
app.MapGet("/api/shareparts", async (AppDbContext db, ITenantContext t, string? dealer, string? part, string? status) =>
{
    var query = db.ShareParts.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) query = query.Where(x => x.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(part)) query = query.Where(x => x.PartCode.Contains(part!.ToUpper()) || (x.PartName != null && x.PartName.Contains(part!)));
    if (!string.IsNullOrWhiteSpace(status)) query = query.Where(x => x.Status == status);
    var items = await query.OrderByDescending(x => x.Id).Take(500)
        .Select(x => new { x.ShareNo, x.DealerCode, x.PartCode, x.PartName, x.Unit, x.InStock, x.QuantityShare, x.Remark, x.Status, createdAt = x.CreatedAt.ToString("yyyy-MM-dd") }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Đăng chia sẻ 1 phụ tùng (SL chia sẻ không vượt tồn).
app.MapPost("/api/shareparts", async (SharePartDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Chưa chọn đại lý." });
    if (string.IsNullOrWhiteSpace(dto.PartCode)) return Results.BadRequest(new { error = "Chưa chọn phụ tùng." });
    if (dto.QuantityShare <= 0) return Results.BadRequest(new { error = "Số lượng chia sẻ phải lớn hơn 0." });
    if (dto.QuantityShare > dto.InStock) return Results.BadRequest(new { error = "Số lượng chia sẻ không được vượt quá tồn kho." });
    var no = "SP" + DateTime.Now.ToString("yyMMddHHmmss");
    var r = new SharePart { OrgId = t.OrgId, ShareNo = no, DealerCode = dto.DealerCode.Trim().ToUpperInvariant(), PartCode = dto.PartCode.Trim().ToUpperInvariant(), PartName = dto.PartName, Unit = dto.Unit, InStock = dto.InStock, QuantityShare = dto.QuantityShare, Remark = dto.Remark, Status = "Open" };
    db.ShareParts.Add(r); await db.SaveChangesAsync();
    return Results.Ok(new { r.ShareNo, r.PartCode });
}).RequireAuthorization();

// Đóng tin chia sẻ (Open -> Closed).
app.MapPost("/api/shareparts/{no}/close", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var x = await db.ShareParts.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.ShareNo == no);
    if (x is null) return Results.NotFound(new { no });
    if (x.Status == "Closed") return Results.BadRequest(new { error = "Tin chia sẻ đã đóng." });
    x.Status = "Closed"; await db.SaveChangesAsync();
    return Results.Ok(new { x.ShareNo, status = x.Status });
}).RequireAuthorization();

// ===== Thông báo kỹ thuật (Bulletin — port 1:1 FrmBulletinHTCCreate/Modify/Search, TCMotor) =====
app.MapGet("/api/bulletins", async (AppDbContext db, ITenantContext t, string? q, string? part, string? active) =>
{
    var query = db.Bulletins.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(x => x.BulletinNo.Contains(q!) || (x.Remark != null && x.Remark.Contains(q!)));
    if (!string.IsNullOrWhiteSpace(part)) query = query.Where(x => x.PartCode == part);
    if (!string.IsNullOrWhiteSpace(active)) query = query.Where(x => x.FlagActive == active);
    var items = await query.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.BulletinNo, x.BulletinNoHMC, x.Remark, x.PartCode, x.PartName, x.SerCode, x.SerName, x.FileNameAttachment, x.FlagActive, x.CreateDate, x.UserCreate,
        vins = db.BulletinVins.Count(v => v.OrgId == t.OrgId && v.BulletinNo == x.BulletinNo),
        dateExpired = x.DateExpired.HasValue ? x.DateExpired.Value.ToString("yyyy-MM-dd") : ""
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Upsert theo số thông báo (số trống = auto-gen).
// TWIN đã trace: WS gọi `Blt_BulletinCreate_20210224` / `Blt_BulletinUpdate_20210224`
// (KHÔNG phải Blt_BulletinCreate / Blt_BulletinUpdate trần — có tới 4 phiên bản trong biz).
app.MapPost("/api/bulletins", async (BulletinDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.Remark)) return Results.BadRequest(new { error = "Chưa nhập nội dung thông báo." });
    // Biz chặn thiếu số bản tin hãng (Blt_Bulletin_InvalidBulletinNoHMC) — form không có luật này.
    if (string.IsNullOrWhiteSpace(dto.BulletinNoHMC)) return Results.BadRequest(new { error = "Chưa nhập số bản tin HMC!" });

    var vinLines = dto.Vins ?? new();
    foreach (var line in vinLines)
    {
        // Nguồn gọi CheckVINEmpty cho từng dòng trước khi ghi.
        if (string.IsNullOrWhiteSpace(line.VinNo)) return Results.BadRequest(new { error = "Số khung không được để trống!" });
    }
    var duplicatedVin = vinLines
        .GroupBy(v => v.VinNo!.Trim().ToUpperInvariant())
        .FirstOrDefault(g => g.Count() > 1);
    if (duplicatedVin is not null)
        return Results.BadRequest(new { error = $"Số khung '{duplicatedVin.Key}' bị trùng trong danh sách!" });

    var no = string.IsNullOrWhiteSpace(dto.BulletinNo) ? "BLT" + DateTime.Now.ToString("yyMMddHHmmss") : dto.BulletinNo.Trim().ToUpperInvariant();
    var row = await db.Bulletins.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.BulletinNo == no);
    var updated = row is not null;
    if (row is null) { row = new Bulletin { OrgId = t.OrgId, BulletinNo = no }; db.Bulletins.Add(row); }

    row.BulletinNoHMC = dto.BulletinNoHMC!.Trim();
    row.Remark = dto.Remark;
    row.PartCode = dto.PartCode; row.PartName = dto.PartName;
    row.SerCode = dto.SerCode; row.SerName = dto.SerName;
    row.DateExpired = dto.DateExpired;
    row.FileNameAttachment = dto.FileNameAttachment;
    row.CreateDate = dto.CreateDate; row.UserCreate = dto.UserCreate;
    row.FlagActive = "1";
    await db.SaveChangesAsync();

    // Hai bảng chi tiết: chỉ thay khi client CÓ gửi lên (không gửi = giữ nguyên).
    if (dto.Details is not null)
    {
        db.BulletinDtls.RemoveRange(db.BulletinDtls.Where(d => d.OrgId == t.OrgId && d.BulletinNo == no));
        foreach (var line in dto.Details)
            db.BulletinDtls.Add(new BulletinDtl
            {
                OrgId = t.OrgId, BulletinNo = no,
                SerCode = line.SerCode, SerName = line.SerName,
                PartCode = line.PartCode, PartName = line.PartName
            });
    }
    if (dto.Vins is not null)
    {
        db.BulletinVins.RemoveRange(db.BulletinVins.Where(v => v.OrgId == t.OrgId && v.BulletinNo == no));
        foreach (var line in vinLines)
            db.BulletinVins.Add(new BulletinVin
            {
                OrgId = t.OrgId, BulletinNo = no,
                VinNo = line.VinNo!.Trim().ToUpperInvariant(),
                DealerCode = line.DealerCode,
                // Không truyền trạng thái thì mặc định "P" đúng như `isnull(bv.Status,'P')` của nguồn.
                Status = string.IsNullOrWhiteSpace(line.Status) ? "P" : line.Status!.Trim().ToUpperInvariant()
            });
    }
    await db.SaveChangesAsync();

    return Results.Ok(new { row.BulletinNo, row.BulletinNoHMC, details = dto.Details?.Count ?? 0, vins = vinLines.Count, updated });
}).RequireAuthorization();

// Chi tiết một bản tin: dịch vụ/phụ tùng liên quan + danh sách VIN áp dụng kèm trạng thái từng xe.
app.MapGet("/api/bulletins/{no}/details", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var row = await db.Bulletins.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.BulletinNo == no);
    if (row is null) return Results.NotFound(new { no });
    var details = await db.BulletinDtls.Where(d => d.OrgId == t.OrgId && d.BulletinNo == no)
        .Select(d => new { d.SerCode, d.SerName, d.PartCode, d.PartName }).ToListAsync();
    var vins = await db.BulletinVins.Where(v => v.OrgId == t.OrgId && v.BulletinNo == no)
        .Select(v => new { v.VinNo, v.DealerCode, v.Status }).ToListAsync();
    return Results.Ok(new
    {
        row.BulletinNo, row.BulletinNoHMC, row.Remark, row.CreateDate, row.UserCreate,
        row.DateExpired, row.FileNameAttachment, row.FlagActive,
        details, vins,
        pendingVins = vins.Count(v => v.Status == "P")
    });
}).RequireAuthorization();

// Đại lý cập nhật trạng thái xử lý của MỘT xe trên bản tin (FrmBulletinDealerSearch).
app.MapPost("/api/bulletins/{no}/vins/{vin}/status", async (
    string no, string vin, BulletinVinStatusDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    vin = vin.Trim().ToUpperInvariant();
    var row = await db.BulletinVins.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.BulletinNo == no && v.VinNo == vin);
    if (row is null) return Results.NotFound(new { no, vin });
    var status = (dto.Status ?? "").Trim().ToUpperInvariant();
    if (string.IsNullOrWhiteSpace(status)) return Results.BadRequest(new { error = "Chưa chọn trạng thái." });
    row.Status = status;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.BulletinNo, row.VinNo, row.Status });
}).RequireAuthorization();

app.MapPost("/api/bulletins/{no}/toggle", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var x = await db.Bulletins.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.BulletinNo == no);
    if (x is null) return Results.NotFound(new { no });
    x.FlagActive = x.FlagActive == "1" ? "0" : "1";
    await db.SaveChangesAsync();
    return Results.Ok(new { x.BulletinNo, flagActive = x.FlagActive });
}).RequireAuthorization();

// ===== Báo giá phụ tùng dịch vụ (PartQuote header-detail — port 1:1 FrmPartQuotation/Search, TCMotor) =====
app.MapGet("/api/partquotes", async (AppDbContext db, ITenantContext t, string? q, string? status) =>
{
    var query = db.PartQuotes.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(x => x.QuoteNo.Contains(q!) || (x.CusName != null && x.CusName.Contains(q!)));
    if (!string.IsNullOrWhiteSpace(status)) query = query.Where(x => x.Status == status);
    var items = await query.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.QuoteNo, x.CusId, x.CusName, x.Mobile, x.ReceiveName, x.PaymentMethod, x.TotalAmount, x.Status,
        createdAt = x.CreatedAt.ToString("yyyy-MM-dd"),
        x.SumAmountNoFactor,
        lines = db.PartQuoteLines.Count(l => l.OrgId == t.OrgId && l.PartQuoteId == x.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Tạo báo giá (header + dòng phụ tùng; tính Amount=Qty*Price*(1+VAT/100) + tổng).
app.MapPost("/api/partquotes", async (PartQuoteDto dto, AppDbContext db, ITenantContext t) =>
{
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.PartCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Chưa có dòng phụ tùng." });
    if (lines.Any(l => l.Quantity <= 0)) return Results.BadRequest(new { error = "Số lượng phải lớn hơn 0." });
    var no = "PQ" + DateTime.Now.ToString("yyMMddHHmmss");
    var h = new PartQuote { OrgId = t.OrgId, QuoteNo = no, CusId = dto.CusId, CusName = dto.CusName, Mobile = dto.Mobile, ReceiveName = dto.ReceiveName, PaymentMethod = dto.PaymentMethod, Remark = dto.Remark, Status = "Draft" };
    db.PartQuotes.Add(h); await db.SaveChangesAsync();
    decimal total = 0m, sumAmountNoFactor = 0m;
    foreach (var l in lines)
    {
        // Hệ số giảm giá: nguồn đọc `isnull(sst.Factor, 1)` ⇒ không nhập thì coi như 1 (không giảm).
        var factor = l.Factor ?? 1m;
        // Công thức nguyên văn nguồn (Issue 813) — hệ số nhân vào CẢ phần gốc LẪN phần thuế:
        //   Amount = Qty*Price*Factor + Qty*Price*0.01*VAT*Factor
        var amountBeforeVat = l.Quantity * l.UnitPrice * factor;
        var amount = amountBeforeVat + l.Quantity * l.UnitPrice * (l.Vat / 100m) * factor;
        total += amount;
        // 🔴 Cột SumAmount của nguồn tính KHÔNG có Factor:
        //   sum(Qty*Price + Qty*Price*0.01*VAT)
        // Nguồn bất đối xứng giữa dòng và tổng — giữ nguyên cả hai, không tự sửa cho khớp.
        sumAmountNoFactor += l.Quantity * l.UnitPrice * (1 + l.Vat / 100m);
        db.PartQuoteLines.Add(new PartQuoteLine
        {
            OrgId = t.OrgId, PartQuoteId = h.Id,
            PartCode = l.PartCode.Trim().ToUpperInvariant(), PartName = l.PartName, Unit = l.Unit,
            Quantity = l.Quantity, UnitPrice = l.UnitPrice, Vat = l.Vat,
            Factor = factor, PartPriceId = l.PartPriceId, Note = l.Note,
            AmountBeforeVat = amountBeforeVat, Amount = amount
        });
    }
    h.TotalAmount = total;
    h.SumAmountNoFactor = sumAmountNoFactor;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.QuoteNo, lines = lines.Count, totalAmount = total, sumAmountNoFactor });
}).RequireAuthorization();

