// ===== #B170/#B171 PHÍ BẢO HIỂM THEO HỢP ĐỒNG — `Mst_InsuranceFee_Save` (`DataWH/Biz.HTC.WH.cs`)
//       + màn `FrmMst_InsuranceFee` =====
// 🔴 WS64 **chỉ có MỘT cửa `_Save`** (`grep -o "_biz.Mst_InsuranceFee_[A-Za-z]*"`) — **không có
//   `_Get` riêng**; màn nạp dữ liệu bằng đường khác. Bảng **cũng có** trong danh sách trắng cửa chung.
// **3B khớp cả 2 máy** (căn theo TÊN — lại lệch 5 dòng, cùng file với #B159):
//   laptop `197467,197830` · máy 150 `197472,197835` ⇒ **`7cad72471debff47c4afb0c56c726a1f`**.
//   ⚠️ Đo cùng dải số cho md5 khác (`7cad7247…` vs `cd2a3cb8…`) — **ca lệch offset thứ ba**.
// 🔴🔴 **CLIENT CHIA BA LÔ, GỌI CÙNG MỘT HÀM BA LẦN** (`FrmMst_InsuranceFee.cs:263,272,281`):
//     · lô **thêm**  → `Mst_InsuranceFee_Save(objFlagIsDelete = **"0"**, …)`
//     · lô **sửa**   → `Mst_InsuranceFee_Save(objFlagIsDelete = **"0"**, …)`
//     · lô **xoá**   → `Mst_InsuranceFee_Save(objFlagIsDelete = **"1"**, …)`
//   ⇒ Biz **không phân biệt thêm với sửa** — cả hai đều `FlagIsDelete = "0"`; việc tách lô là **của
//     client**, dựa trên `TblCommon.Status == EditStatus.ITEM_VALUE_STT_DELETE`.
//   ⇒ Port thành một endpoint nhận **cả ba lô cùng lúc** là **đổi ngữ nghĩa giao dịch**: ở nguồn, ba
//     lô là **ba lời gọi độc lập** — lô sau lỗi thì lô trước **đã ghi rồi**. Giữ đúng: mỗi lô một lời gọi.
// 🔴 **BỐN guard, mỗi cái một mã lỗi**, kiểm trên **`Rows[0]`** (bảng đầu vào chỉ dùng dòng đầu):
//     · bảng thiếu ⇒ `…_Input_Mst_InsuranceFeeTblNotFound`
//     · `InsuranceContractNo` rỗng ⇒ `…_InvalidInsuranceContractNo`
//     · `EffStartDate` rỗng ⇒ `…_InvalidEffStartDate`  (chuẩn hoá bằng **`StdDate`**)
//     · `InsurancePercent` rỗng **hoặc `< 0`** ⇒ `…_InvalidInsurancePercent`
//       ⚠️ **Không chặn `> 100`** — khác `Mst_CarAllocationByArea` (#B166) chặn `[0,100]`. Không tự thêm.
// 🔴🔴 **GUARD TRÙNG CHỈ CHẠY Ở NHÁNH XOÁ**: `if (bIsDelete) { … select top 1 … where
//   t.InsuranceContractNo = @… ; if (rows > 0) throw …_ExistInsuranceContractNo; }`
//   ⇒ Tên mã lỗi là *"Exist…"* nhưng nó **chặn khi TÌM THẤY** trong lúc **xoá** — đọc lướt theo tên
//     sẽ tưởng là guard chống trùng lúc **thêm**. **Nhánh thêm KHÔNG có guard trùng.**
// 🔴 Cột ghi: `InsuranceContractNo` · `InsurancePercent` · `EffStartDate` · `FlagActive` ·
//   `LogLUDateTime` · `LogLUBy`. Cột thật (`DbDefine.cs:5284`) viết HOA: `INSURANCECONTRACTNO`,
//   `INSURANCEPERCENT`, `EFFSTARTDATE`, `FLAGACTIVE` (bẫy tên hằng ≠ giá trị — luật `C0-…quadragesimusseptimus`).
// 📌 Thực thể `InsuranceFee` **đã có sẵn** trong MiniHTC (port trước từ nguồn khác) và có **thêm** cột
//   `Code`/`InsCompanyCode`/`InsTypeCode`/`Fee` **không thuộc** `Mst_InsuranceFee`. Giữ nguyên, chỉ
//   dùng đúng bốn cột của nguồn; ghi rõ để người sau không tưởng nguồn có các cột kia.
app.MapGet("/api/masters/insurance-fees", async (
    AppDbContext db, ITenantContext t, string? insuranceContractNo, string? flagActive) =>
{
    var q = db.InsuranceFees.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(insuranceContractNo)) q = q.Where(x => x.ContractNo == insuranceContractNo.Trim());
    if (!string.IsNullOrWhiteSpace(flagActive)) q = q.Where(x => x.Status == flagActive.Trim());
    var items = await q.OrderBy(x => x.ContractNo).ThenBy(x => x.EffStartDate).ToListAsync();
    return Results.Ok(new
    {
        count = items.Count,
        Mst_InsuranceFee = items.Select(x => new
        {
            INSURANCECONTRACTNO = x.ContractNo,
            INSURANCEPERCENT = x.Percent,
            EFFSTARTDATE = x.EffStartDate,
            FLAGACTIVE = x.Status
        }),
        noGetDoorNote = "WS64 CHI CO MOT cua _Save cho bang nay - KHONG co _Get rieng; man nap du lieu bang duong khac. Endpoint GET nay la tien ich cua MiniHTC de doi soat, khong phai port mot cua nguon.",
        extraColumnNote = "Thuc the InsuranceFee cua MiniHTC co THEM cot Code/InsCompanyCode/InsTypeCode/Fee KHONG THUOC Mst_InsuranceFee (port truoc tu nguon khac). Chi dung dung bon cot cua nguon: INSURANCECONTRACTNO, INSURANCEPERCENT, EFFSTARTDATE, FLAGACTIVE."
    });
}).RequireAuthorization();

app.MapPost("/api/masters/insurance-fees/save", async (
    InsuranceFeeSaveDto dto, AppDbContext db, ITenantContext t) =>
{
    // 🔴 Bảng đầu vào bắt buộc; nguồn chỉ dùng Rows[0].
    if (dto.Rows is null || dto.Rows.Count == 0)
        return Results.BadRequest(new { error = "Mst_InsuranceFee_Save_Input_Mst_InsuranceFeeTblNotFound" });

    var isDelete = (dto.FlagIsDelete ?? "0").Trim() == "1";
    var r = dto.Rows[0];
    var contractNo = (r.InsuranceContractNo ?? "").Trim();

    if (contractNo.Length == 0)
        return Results.BadRequest(new { error = "Mst_InsuranceFee_Save_InvalidInsuranceContractNo", check = new { InsuranceContractNo = contractNo } });
    if (r.EffStartDate is null)
        return Results.BadRequest(new { error = "Mst_InsuranceFee_Save_InvalidEffStartDate" });
    if (r.InsurancePercent is null || r.InsurancePercent < 0)
        return Results.BadRequest(new
        {
            error = "Mst_InsuranceFee_Save_InvalidInsurancePercent",
            check = new { r.InsurancePercent },
            note = "Nguon chi chan RONG hoac < 0 - KHONG chan > 100 (khac Mst_CarAllocationByArea #B166 chan [0,100]). Khong tu them."
        });

    var cur = await db.InsuranceFees
        .FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ContractNo == contractNo
                                  && x.EffStartDate == r.EffStartDate);

    if (isDelete)
    {
        // 🔴 Guard TRÙNG CHỈ Ở NHÁNH XOÁ — tên là "Exist…" nhưng chặn khi TÌM THẤY.
        if (cur is not null)
            return Results.BadRequest(new
            {
                error = "Mst_InsuranceFee_Save_ExistInsuranceContractNo",
                check = new { InsuranceContractNo = contractNo },
                deleteGuardNote = "GUARD TRUNG CHI CHAY O NHANH XOA: 'if (bIsDelete) { select top 1 ... where t.InsuranceContractNo = @...; if (rows > 0) throw ..._ExistInsuranceContractNo; }'. Ten ma loi la 'Exist...' nhung no CHAN KHI TIM THAY trong luc XOA - doc luot theo ten se tuong la guard chong trung luc THEM. Nhanh THEM KHONG co guard trung."
            });
        return Results.Ok(new { deleted = 0, flagIsDelete = "1", note = "Khong tim thay dong khop - nguon khong nem loi o truong hop nay." });
    }

    // 🔴 Nhánh ghi: thêm hoặc sửa — biz KHÔNG phân biệt (client mới tách lô).
    if (cur is null)
    {
        cur = new InsuranceFee
        {
            OrgId = t.OrgId, ContractNo = contractNo,
            Percent = r.InsurancePercent.Value,
            EffStartDate = r.EffStartDate,
            Status = string.IsNullOrWhiteSpace(r.FlagActive) ? "1" : r.FlagActive.Trim()
        };
        db.InsuranceFees.Add(cur);
    }
    else
    {
        cur.Percent = r.InsurancePercent.Value;
        if (!string.IsNullOrWhiteSpace(r.FlagActive)) cur.Status = r.FlagActive.Trim();
    }
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        insuranceContractNo = contractNo,
        insurancePercent = cur.Percent,
        effStartDate = cur.EffStartDate,
        flagActive = cur.Status,
        flagIsDelete = "0",
        threeBatchNote = "CLIENT CHIA BA LO, GOI CUNG MOT HAM BA LAN (FrmMst_InsuranceFee.cs:263,272,281): lo THEM -> FlagIsDelete '0'; lo SUA -> FlagIsDelete '0'; lo XOA -> FlagIsDelete '1'. Biz KHONG phan biet them voi sua - viec tach lo la CUA CLIENT, dua tren TblCommon.Status == EditStatus.ITEM_VALUE_STT_DELETE. Port thanh MOT endpoint nhan CA BA LO cung luc la DOI NGU NGHIA GIAO DICH: o nguon, ba lo la BA LOI GOI DOC LAP - lo sau loi thi lo truoc DA GHI ROI.",
        rowsZeroNote = "Nguon kiem guard tren Rows[0] - bang dau vao chi dung DONG DAU.",
        columnNote = "Cot ghi: InsuranceContractNo, InsurancePercent, EffStartDate, FlagActive, LogLUDateTime, LogLUBy. Cot that (DbDefine.cs:5284) VIET HOA: INSURANCECONTRACTNO, INSURANCEPERCENT, EFFSTARTDATE, FLAGACTIVE - bay ten hang khac gia tri (luat C0-...quadragesimusseptimus).",
        stdDateNote = "EffStartDate duoc chuan hoa bang StdDate truoc khi kiem rong."
    });
}).RequireAuthorization();

// ===== #B58 AUDIT TOÀN CỤM BỘ LỌC ZONE CỦA 2010.HTC (kết quả quét, không đổi hành vi) =====
// Bối cảnh: sổ đã có luật "bind `@strZoneCode = NULL` trong filter `(@x='' or …)` ⇒ loại sạch dòng"
// (ghi cho DMS.Sales). Lượt này quét **toàn bộ** `TERP.BizHTC.SQLQuery/RptSQLQuery.cs` của 2010.HTC.
// 🔴 **HAI DẠNG cùng tồn tại** trong cùng đợt rollout zone `_New20260514`:
//   · **BAKE** — `('@strZoneCode' = '' or mdz.ZoneCode = '@strZoneCode')`, **có bọc nháy**: **10** site.
//     Được `CmUtils.StringUtils.Replace` thay chuỗi ⇒ null thành rỗng ⇒ **an toàn**.
//     (Báo cáo **công nợ** `RptDebitReport02_New20260514` thuộc nhóm này — đã kiểm, KHÔNG dính bug.)
//   · **PARAM runtime** — `(@strZoneCode = '' or mdz.ZoneCode = @strZoneCode)`, **không nháy**: **29** site.
//     Với `@strZoneCode = NULL`: `NULL = ''` → UNKNOWN và `ZoneCode = NULL` → UNKNOWN ⇒ **loại sạch dòng**.
// ✅ **ĐÃ ĐẾM TOÀN BỘ (#B61 đính chính #B58)** — `TERP.BizHTC/` (bỏ `Backup/`):
//    **37** site bind `"@strZoneCode", strZoneCode` · **35** site có dòng coalesce
//    `strZoneCode = TUtils.CUtils.IsNullOrEmpty(strZoneCode) ? "" : TUtils.CUtils.StandardizeParam(strZoneCode);`
//    (cần vì `StandardizeParam` **trả `null`** khi rỗng — `TERP.Utils/Utils.cs:351-355`).
//    **Hai site còn lại KHÔNG phải bug**, đã kiểm từng cái:
//      · `RptDebitReport02_New20260514` (`BizHTC.Report.cs:1829`) — bind qua **`Replace` (bake)**, khớp
//        dạng `N'@strZoneCode'` trong SQL ⇒ null thành rỗng ⇒ an toàn.
//      · `Mst_DealerZone_Update` (`BizHTC.MasterData.cs:5566`) — `@strZoneCode` dùng trong
//        `t.ZoneCode <> @strZoneCode` (kiểm trùng khi SỬA master), **không phải** filter tuỳ chọn.
//    ⇒ **KHÔNG có site nào bị bỏ sót** ở 2010.HTC. Bản ghi trước của #B58 nói
//      `Rpt_DlrContractGet_WH_New20190619` "thiếu coalesce" là **SAI**: nó **CÓ** dòng coalesce
//      (`BizHTC.Contract.cs:10940`, bind ở `:10956`) — lần quét trước dùng cửa sổ `awk NR<s+120`
//      nên không tới được offset 288 của hàm. Xem luật `C0-…vicesimusnonus`.
// ✅ **MiniHTC KHÔNG mắc bẫy này**: mọi bộ lọc tuỳ chọn ở đây dùng `if (!string.IsNullOrWhiteSpace(x))`
//    rồi mới thêm điều kiện — null/rỗng ⇒ **bỏ qua bộ lọc**, đúng ý định. Giữ nguyên khuôn này.
// ⚠️ NỢ CÓ NHÃN: các báo cáo vừa port ở #B54–#B57 **chưa có** bộ lọc zone dù nguồn có — cần bổ sung khi
//    MiniHTC nối `Mst_DealerZone` vào tầng báo cáo.

// ===== Vùng đại lý (DealerZone — port 1:1 FrmMst_DealerZone, 2010.HTC/Admin/Product) =====
app.MapGet("/api/dealerzones", async (AppDbContext db, ITenantContext t, string? zone, string? dealer, string? active) =>
{
    var q = db.DealerZones.Where(z => z.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(zone)) q = q.Where(z => z.ZoneCode == zone);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(z => z.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(active)) q = q.Where(z => z.FlagActive == active);
    var items = await q.OrderByDescending(z => z.Id).Take(500).Select(z => new { z.DealerCode, z.ZoneCode, z.FlagActive, z.Remark, z.LogLUDateTime, z.LogLUBy }).ToListAsync();   // #B92 §12
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// ===== #B92 GẮN ĐẠI LÝ VÀO VÙNG — `Mst_DealerZone_Add` (viết lại) =====
// Trace LIVE: WS → `_biz.Mst_DealerZone_Add` (`BizHTC.MasterData.cs:5078`, thân **`Mst_DealerZone_AddX`**
//   `:5208`). 3B đo thật, **khớp cả 2 máy**: start=5208 md5 `7eb65378ebb16e8f7b50965aa3bf21f8`.
// 🔴 **"Add" THỰC CHẤT LÀ UPSERT CÓ HỒI SINH — port cũ chặn nhầm**:
//      · cặp (Dealer, Zone) **đã có VÀ `FlagActive = '1'`** ⇒ **NÉM** `…_DealerZoneExist`;
//      · cặp **đã có NHƯNG `FlagActive = '0'`** ⇒ `bIsUpdate = true` ⇒ **UPDATE bật lại (HỒI SINH)**;
//      · cặp **chưa có** ⇒ `bIsUpdate = false` ⇒ **INSERT**.
//    ⇒ Nguồn **không bao giờ sinh dòng thứ hai** cho cùng cặp, và **luôn** bật lại được cặp đã tắt.
//    Port cũ chặn **mọi** cặp đã tồn tại (kể cả đã tắt) ⇒ cặp bị tắt **vĩnh viễn không thêm lại được**.
// 🔴 **`bIsUpdate` đi xuống SQL dưới dạng CHUỖI** `'true'` / `'false'`
//    (`and f.bIsUpdate = 'true'` / `and t.bIsUpdate = 'false'`) vì `MyBuildDBDT_Common` đổ `bool`
//    ra chuỗi. Port đừng quy ước `1/0`.
// 🔴 **HAI guard danh mục — CẢ HAI đều đòi ĐANG HOẠT ĐỘNG**:
//      `Mst_Dealer_CheckDB_New20210415(…, Flag.Yes, **Flag.Active**, …)`
//      `Mst_Zone_CheckDB(…, Flag.Yes, **Flag.Active**, …)`
//    ⚠️ **Chú ý đối chiếu #B89**: cũng là `Mst_Zone_CheckDB` nhưng ở `Mst_Zone_Update` tham số thứ ba
//      truyền **chuỗi RỖNG** (cố ý không kiểm active, để còn bật lại vùng đã tắt). **Cùng một hàm
//      check, hai cách gọi khác nhau tuỳ nghiệp vụ** — phải đọc từng lời gọi.
// 🔴 Nguồn ghi **cả `_dbMain` và `_dbWH`**; đầu vào là **BẢNG** (`#input_Mst_DealerZone`) nhiều dòng,
//    rỗng ⇒ **BỊ TỪ CHỐI** (`…_Input_DealerZoneTblInvalid`) — khuôn #B82/#B86.
// 🔴 Cột dấu vết là **`LogLUDTime`** ở nguồn (như #B89); MiniHTC đặt `LogLUDateTime` — giữ ánh xạ.
app.MapPost("/api/dealerzones", async (List<DealerZoneDto> rows, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    // Đầu vào là BẢNG; rỗng ⇒ TỪ CHỐI.
    if (rows is null || rows.Count == 0)
        return Results.BadRequest(new { error = "Mst_DealerZone_AddX_Input_DealerZoneTblInvalid" });

    var now = DateTime.Now;
    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var inserted = new List<object>(); var revived = new List<object>();

    foreach (var (r, i) in rows.Select((r, i) => (r, i)))
    {
        var dl = (r.DealerCode ?? "").Trim().ToUpperInvariant();
        var zn = (r.ZoneCode ?? "").Trim().ToUpperInvariant();
        if (dl.Length == 0 || zn.Length == 0)
            return Results.BadRequest(new { error = "Mst_DealerZone_AddX_Input_DealerZoneTblInvalid", check = new { Idx = i, DealerCode = dl, ZoneCode = zn } });

        // Guard 1: đại lý phải TỒN TẠI và ĐANG HOẠT ĐỘNG.
        var dealer = await db.Dealers.FirstOrDefaultAsync(d => d.OrgId == t.OrgId && d.DealerCode == dl);
        if (dealer is null || dealer.FlagActive != "1")
            return Results.BadRequest(new { error = "Common_InvalidDealerCode", check = new { Idx = i, DealerCode = dl } });

        // Guard 2: VÙNG phải TỒN TẠI và ĐANG HOẠT ĐỘNG (khác #B89 vốn truyền "" = không kiểm).
        var zone = await db.MstZones.FirstOrDefaultAsync(z => z.OrgId == t.OrgId && z.ZoneCode == zn);
        if (zone is null || zone.FlagActive != "1")
            return Results.BadRequest(new { error = "Mst_Zone_InvalidOrInactive", check = new { Idx = i, ZoneCode = zn } });

        var cur = await db.DealerZones.FirstOrDefaultAsync(z => z.OrgId == t.OrgId && z.DealerCode == dl && z.ZoneCode == zn);
        if (cur is not null && cur.FlagActive == "1")
            return Results.BadRequest(new
            {
                error = "Mst_DealerZone_AddX_Input_DealerZoneExist",
                check = new { Idx = i, DealerCode = dl, ZoneCode = zn, FlagActiveDB = cur.FlagActive }
            });

        if (cur is not null)
        {
            // bIsUpdate = true ⇒ HỒI SINH, KHÔNG insert dòng mới.
            cur.FlagActive = "1"; cur.Remark = r.Remark;
            cur.LogLUDateTime = now; cur.LogLUBy = by;
            revived.Add(new { dealerCode = dl, zoneCode = zn });
        }
        else
        {
            db.DealerZones.Add(new DealerZone
            {
                OrgId = t.OrgId, DealerCode = dl, ZoneCode = zn, FlagActive = "1",
                Remark = r.Remark, LogLUDateTime = now, LogLUBy = by
            });
            inserted.Add(new { dealerCode = dl, zoneCode = zn });
        }
    }
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        insertedCount = inserted.Count, revivedCount = revived.Count, inserted, revived,
        upsertReviveNote = "'Add' THUC CHAT LA UPSERT CO HOI SINH: cap da co VA FlagActive='1' => NEM _DealerZoneExist; cap da co NHUNG FlagActive='0' => bIsUpdate=true => UPDATE BAT LAI (hoi sinh); cap chua co => INSERT. Nguon KHONG BAO GIO sinh dong thu hai cho cung cap. Port cu chan MOI cap da ton tai (ke ca da tat) => cap bi tat VINH VIEN khong them lai duoc.",
        bIsUpdateNote = "bIsUpdate di xuong SQL duoi dang CHUOI 'true'/'false' (and f.bIsUpdate = 'true' / and t.bIsUpdate = 'false') vi MyBuildDBDT_Common do bool ra chuoi. Dung quy uoc 1/0.",
        twoGuardsNote = "HAI guard danh muc, CA HAI deu doi DANG HOAT DONG: Mst_Dealer_CheckDB_New20210415(..., Flag.Yes, Flag.Active) va Mst_Zone_CheckDB(..., Flag.Yes, Flag.Active). DOI CHIEU #B89: cung la Mst_Zone_CheckDB nhung o Mst_Zone_Update tham so thu ba truyen CHUOI RONG (co y khong kiem active, de con bat lai vung da tat). CUNG MOT HAM CHECK, HAI CACH GOI KHAC NHAU tuy nghiep vu.",
        emptyInputNote = "Dau vao la BANG nhieu dong; RONG => BI TU CHOI (_Input_DealerZoneTblInvalid) - khuon #B82/#B86.",
        columnNameNote = "Cot dau vet o nguon la LogLUDTime (nhu #B89); MiniHTC dat LogLUDateTime - giu anh xa.",
        twoDbNote = "Nguon ghi CA _dbMain va _dbWH."
    });
}).RequireAuthorization();

app.MapPost("/api/dealerzones/{dealer}/{zone}/toggle", async (string dealer, string zone, AppDbContext db, ITenantContext t) =>
{
    dealer = dealer.Trim().ToUpperInvariant(); zone = zone.Trim().ToUpperInvariant();
    var z = await db.DealerZones.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == dealer && x.ZoneCode == zone);
    if (z is null) return Results.NotFound(new { dealer, zone });
    z.FlagActive = z.FlagActive == "1" ? "0" : "1";
    await db.SaveChangesAsync();
    return Results.Ok(new { z.DealerCode, z.ZoneCode, flagActive = z.FlagActive });
}).RequireAuthorization();

// ===== Điều khoản thanh toán (PaymentTerm — port 1:1 FrmMst_Dieu_Khoan_ThanhToan, 2010.HTC/Admin/Product) =====
app.MapGet("/api/paymentterms", async (AppDbContext db, ITenantContext t, string? active, string? model) =>
{
    var q = db.PaymentTerms.Where(p => p.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(active)) q = q.Where(p => p.FlagActive == active);
    if (!string.IsNullOrWhiteSpace(model)) q = q.Where(p => p.ModelCode == model);
    var items = await q.OrderByDescending(p => p.Id).Take(500).Select(p => new
    {
        p.PMTermNo, p.EffectiveDateFrom, p.EffectiveDateTo, p.ModelCode, p.SpecCode, p.FlagDepositPmt, p.DepositPercent, p.GuaranteePercent,
        p.GuaranteeDays, p.DepositDutyEndDays, p.GuaranteeEndDays, p.DepositDealDateDays, p.FlagActive,
        // Số dòng model/quy cách áp dụng — chi tiết lấy ở /api/paymentterms/{no}/details.
        details = db.PaymentTermDetails.Count(d => d.OrgId == t.OrgId && d.PMTermNo == p.PMTermNo)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

/// <summary>
/// Kiểm phần đầu (header) của điều khoản thanh toán — giữ NGUYÊN VĂN thứ tự và câu thông báo
/// của btnSave_Click (FrmNew_Dieu_Khoan_ThanhToan), rồi tới các luật số học của biz Mst_PaymentTerm_Create.
/// </summary>
static string? ValidatePaymentTermHeader(PaymentTermDto dto)
{
    if (dto.EffectiveDateFrom is null) return "Chưa nhập Ngày XNĐH từ!";
    if (dto.EffectiveDateTo is null) return "Chưa nhập Ngày XNĐH đến!";
    if (dto.DepositPercent is null) return "Chưa nhập % Cọc!";
    if (dto.GuaranteePercent is null) return "Chưa nhập % Bảo lãnh!";
    if (dto.GuaranteeDays is null) return "Chưa nhập Chính sách gia hạn thời gian BL (ngày)!";
    if (dto.DepositDutyEndDays is null) return "Chưa nhập Thời hạn TTC!";
    if (dto.GuaranteeEndDays is null) return "Chưa nhập Thời hạn PHBL!";
    if (dto.DepositDealDateDays is null) return "Chưa nhập Thời hạn TTC theo Ngày báo bán!";

    // Biz: ngày đến không được nhỏ hơn ngày từ.
    if (dto.EffectiveDateTo < dto.EffectiveDateFrom) return "Ngày XNĐH đến phải >= Ngày XNĐH từ!";

    // Biz chỉ đòi >= 0 cho MỌI số (không có trần 100 cho phần trăm).
    if (dto.DepositPercent < 0) return "% Cọc không hợp lệ!";
    if (dto.GuaranteePercent < 0) return "% Bảo lãnh không hợp lệ!";
    if (dto.GuaranteeDays < 0) return "Chính sách gia hạn thời gian BL (ngày) không hợp lệ!";
    if (dto.DepositDutyEndDays < 0) return "Thời hạn TTC không hợp lệ!";
    if (dto.GuaranteeEndDays < 0) return "Thời hạn PHBL không hợp lệ!";
    if (dto.DepositDealDateDays < 0) return "Thời hạn TTC theo Ngày báo bán không hợp lệ!";
    return null;
}

/// <summary>Kiểm lưới model/quy cách: bắt buộc có dòng, không trùng CẶP (model, quy cách).</summary>
static string? ValidatePaymentTermDetails(List<PaymentTermDetailDto>? details)
{
    var lines = (details ?? new()).Where(d => !string.IsNullOrWhiteSpace(d.ModelCode)).ToList();
    // Biz: Mst_PaymentTerm_Create_TableDtlBlank; form: "Lưới danh sách model không có dữ liệu!".
    if (lines.Count == 0) return "Lưới danh sách model không có dữ liệu!";
    var duplicated = lines
        .GroupBy(d => $"{d.ModelCode!.Trim().ToUpperInvariant()}|{(d.SpecCode ?? "").Trim().ToUpperInvariant()}")
        .FirstOrDefault(g => g.Count() > 1);
    if (duplicated is not null) return $"Model/quy cách '{duplicated.Key}' bị trùng!";
    return null;
}

/// <summary>Ghi lại toàn bộ lưới model/quy cách của một điều khoản (thay thế trọn, đúng cách nguồn lưu bảng chi tiết).</summary>
static void ReplacePaymentTermDetails(
    AppDbContext db, Guid orgId, string pmTermNo, List<PaymentTermDetailDto> details)
{
    db.PaymentTermDetails.RemoveRange(
        db.PaymentTermDetails.Where(d => d.OrgId == orgId && d.PMTermNo == pmTermNo));
    foreach (var line in details)
        db.PaymentTermDetails.Add(new PaymentTermDetail
        {
            OrgId = orgId,
            PMTermNo = pmTermNo,
            ModelCode = line.ModelCode!.Trim().ToUpperInvariant(),
            ModelName = line.ModelName,
            SpecCode = (line.SpecCode ?? "").Trim().ToUpperInvariant(),
            SpecDescription = line.SpecDescription,
            FlagDepositPmt = line.FlagDepositPmt == "1" ? "1" : "0"
        });
}

// Danh sách model/quy cách áp dụng cho 1 điều khoản (lưới của FrmNew_Dieu_Khoan_ThanhToan).
app.MapGet("/api/paymentterms/{no}/details", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var term = await db.PaymentTerms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PMTermNo == no);
    if (term is null) return Results.NotFound(new { no });
    var details = await db.PaymentTermDetails
        .Where(d => d.OrgId == t.OrgId && d.PMTermNo == no)
        .Select(d => new { d.ModelCode, d.ModelName, d.SpecCode, d.SpecDescription, d.FlagDepositPmt })
        .ToListAsync();
    return Results.Ok(new
    {
        term.PMTermNo, term.EffectiveDateFrom, term.EffectiveDateTo,
        term.DepositPercent, term.GuaranteePercent, term.GuaranteeDays,
        term.DepositDutyEndDays, term.GuaranteeEndDays, term.DepositDealDateDays,
        term.FlagActive, count = details.Count, details
    });
}).RequireAuthorization();

app.MapPost("/api/paymentterms", async (PaymentTermDto dto, AppDbContext db, ITenantContext t) =>
{
    var headerError = ValidatePaymentTermHeader(dto);
    if (headerError is not null) return Results.BadRequest(new { error = headerError });
    var detailError = ValidatePaymentTermDetails(dto.Details);
    if (detailError is not null) return Results.BadRequest(new { error = detailError });
    var details = dto.Details!.Where(d => !string.IsNullOrWhiteSpace(d.ModelCode)).ToList();

    var no = "PMT" + DateTime.Now.ToString("yyMMddHHmmss");
    var p = new PaymentTerm
    {
        OrgId = t.OrgId, PMTermNo = no,
        EffectiveDateFrom = dto.EffectiveDateFrom!.Value, EffectiveDateTo = dto.EffectiveDateTo!.Value,
        DepositPercent = dto.DepositPercent!.Value, GuaranteePercent = dto.GuaranteePercent!.Value,
        GuaranteeDays = dto.GuaranteeDays!.Value, DepositDutyEndDays = dto.DepositDutyEndDays!.Value,
        GuaranteeEndDays = dto.GuaranteeEndDays!.Value, DepositDealDateDays = dto.DepositDealDateDays!.Value,
        FlagActive = "1"
    };
    db.PaymentTerms.Add(p);
    ReplacePaymentTermDetails(db, t.OrgId, no, details);
    await db.SaveChangesAsync();
    return Results.Ok(new { p.PMTermNo, details = details.Count, message = "Tạo thành công" });
}).RequireAuthorization();

// Sửa điều khoản (MODE_EDIT của form → biz Mst_PaymentTerm_Update): thay TRỌN header + lưới model.
app.MapPost("/api/paymentterms/{no}", async (
    string no, PaymentTermDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var p = await db.PaymentTerms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PMTermNo == no);
    if (p is null) return Results.NotFound(new { no });

    var headerError = ValidatePaymentTermHeader(dto);
    if (headerError is not null) return Results.BadRequest(new { error = headerError });
    var detailError = ValidatePaymentTermDetails(dto.Details);
    if (detailError is not null) return Results.BadRequest(new { error = detailError });
    var details = dto.Details!.Where(d => !string.IsNullOrWhiteSpace(d.ModelCode)).ToList();

    p.EffectiveDateFrom = dto.EffectiveDateFrom!.Value;
    p.EffectiveDateTo = dto.EffectiveDateTo!.Value;
    p.DepositPercent = dto.DepositPercent!.Value;
    p.GuaranteePercent = dto.GuaranteePercent!.Value;
    p.GuaranteeDays = dto.GuaranteeDays!.Value;
    p.DepositDutyEndDays = dto.DepositDutyEndDays!.Value;
    p.GuaranteeEndDays = dto.GuaranteeEndDays!.Value;
    p.DepositDealDateDays = dto.DepositDealDateDays!.Value;
    ReplacePaymentTermDetails(db, t.OrgId, no, details);
    await db.SaveChangesAsync();
    return Results.Ok(new { p.PMTermNo, details = details.Count, message = "Sửa thành công" });
}).RequireAuthorization();

