        c.FlagDutyComplete, c.DutyCompleteFrom, c.DutyCompleteTo, c.FlagModel, c.FlagActive, c.CreatedAt,
        models = db.DOATConditionModels.Count(m => m.OrgId == t.OrgId && m.DOATConditionId == c.Id)
    }).ToListAsync();
