app.MapPost("/api/bankingtrans/{no}/send", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var b = await db.BankingTranses.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no);
    if (b is null) return Results.NotFound(new { no });
    if (b.BkTransStatus != "Draft") return Results.BadRequest(new { error = "Đề nghị đã gửi." });
    b.BkTransStatus = "Sent"; b.SentAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { b.RQ_BankingTransNo, status = b.BkTransStatus });
}).RequireAuthorization();

app.MapPost("/api/bankingtrans/{no}/{action}", async (string no, string action, AppDbContext db, ITenantContext t) =>
{
    if (action is not ("approve" or "reject")) return Results.BadRequest(new { error = "action = approve|reject" });
    no = no.Trim().ToUpperInvariant();
    var b = await db.BankingTranses.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no);
    if (b is null) return Results.NotFound(new { no });
    if (b.BkTransStatus != "Sent") return Results.BadRequest(new { error = "Chỉ duyệt/từ chối đề nghị đã gửi." });
    if (action == "approve") { b.BkTransStatus = "Approved"; b.ApprovedDate = DateTime.Now; }
    else b.BkTransStatus = "Rejected";
    await db.SaveChangesAsync();
    return Results.Ok(new { b.RQ_BankingTransNo, status = b.BkTransStatus });
}).RequireAuthorization();

// ===== Biên bản giao xe (DlvMinutes — port 1:1 FrmDealerNewDlvMinutes/FrmHTCNewDlvMinutes, 2010.HTC/Sales/DlvMinutes) =====
// ⛔ HỢP NHẤT NỢ ### C0 (treo từ #14, xử lý #60): cụm `/api/dlvminutes` trước đây ghi vào bộ
// `DlvMinutes` (bảng "DlvMinutesSet") RIÊNG, trong khi `/api/transpdlv` ghi vào
// `TranspDlvConfirm` + `TranspDlvConfirmCar` + `DlvMinutesCheckItem` — **cùng bảng nguồn `Sto_DlvMinutes`**.
// Hợp nhất theo kiểu BỔ KHUYẾT: giữ bộ có 2 phía duyệt F/T + checklist dạng BẢNG,
// và mang TUYẾN vận chuyển từ bộ cũ sang — nhưng đặt ở **DÒNG XE**, đúng mô hình nguồn.
// ===== #159: DUYỆT BIÊN BẢN GIAO XE — ghi ngược NGÀY XUẤT KHO lên chứng từ nguồn =====
// Nguồn: `Sto_DlvMinutes_Approve_New20190416` (DataWH/Biz.HTC.WH.cs:138340, csproj 272).
// BƯỚC 3B: vùng hàm md5 78160161 khớp 2 máy (laptop 138340 / máy 150 138345 — căn theo MỐC HÀM).
// TWIN: CẢ HAI WS đều gọi `_New20190416` ⇒ không lệch.
//
// 🔴 Đây là side-effect mà port cũ bỏ sót TRỌN VẸN: duyệt biên bản không chỉ đổi trạng thái biên bản,
//    mà còn ghi "ngày xuất kho" NGƯỢC lên **chứng từ nguồn** của từng xe. Bốn nhánh theo loại chứng từ,
//    mỗi nhánh một CỘT KHÁC TÊN — chính vì khác tên nên khi port từng màn riêng lẻ thì không ai thấy:
//      Car_DeliveryOrderDetail   → DeliveryOutDate    (lệnh giao xe)
//      Sto_StorageRearrangeDetail→ RearrangeOutDate   (điều chuyển kho)   — guard: dòng đang "A2" hoặc "F"
//      Sto_CarRetrieveDetail     → RetrieveOutDate    (thu hồi xe)
//      Sto_RearrangeCBDetail     → RearCBOutDate      (điều chuyển đóng thùng)
//                                   — chỉ khi TypeCB ≠ ChuaDongThung; guard: dòng đang "A" hoặc "F"
// 🔴 Trạng thái biên bản: nguồn đặt `Approved` khi duyệt, `Rejected` khi bỏ duyệt
//    (`bFromApprove = FlagUnapprove == "0"`).
app.MapPost("/api/dlvminutes/{no}/approve", async (string no, DlvMinutesApproveDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.TranspDlvConfirms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlvMinutesNo == no);
    if (m is null) return Results.NotFound(new { no });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var now = DateTime.Now;
    var outDate = dto.DeliveryOutDate ?? now;
    var unapprove = (dto.FlagUnapprove ?? "0").Trim() == "1";

    // 🔴 #200 GUARD CÒN THIẾU — `// Check DlvMnNo:` (DataWH/Biz.HTC.WH.cs:138651-138675).
    //    Nguồn kiểm trên bảng tạm: `SDMDlvMnNo is null OR SMDFDlvMnStatus not in ('P')` ⇒ ném
    //    `Sto_DlvMinutes_Approve_InvalidTransportReqStatus`. Tức biên bản phải tồn tại VÀ đang ở "P".
    //    🔴 Guard này áp cho **CẢ HAI** nhánh: `strFromFlagUnapprove` chỉ quyết định ghi "A" hay "R",
    //    KHÔNG nới guard. Nghĩa là nhánh false là **TỪ CHỐI** (P → R), không phải "bỏ duyệt" (A → P).
    if (m.FDlvMnStatus != "P")
        return Results.BadRequest(new { error = "Biên bản bàn giao đã được phê duyệt", current = m.FDlvMnStatus });

    // nguồn: bFromApprove = (FlagUnapprove == Flag.Inactive) ⇒ Approved, ngược lại Rejected (TỪ CHỐI).
    m.FDlvMnStatus = unapprove ? "R" : "A";

    var vins = (dto.Vins ?? new()).Select(v => (v ?? "").Trim().ToUpperInvariant()).Where(v => v.Length > 0).ToList();
    if (vins.Count == 0)
        vins = await db.TranspDlvConfirmCars.Where(c => c.OrgId == t.OrgId && c.TranspDlvConfirmId == m.Id)
            .Select(c => c.VIN).ToListAsync();   // khoá nối là Id, không phải số biên bản

    int doHit = 0, rearrHit = 0, retrHit = 0, cbHit = 0; var skipped = new List<string>();
    foreach (var vin in vins)
    {
        // (1) lệnh giao xe
        foreach (var x in await db.DeliveryOrderCars.Where(x => x.OrgId == t.OrgId && x.Vin == vin).ToListAsync())
        { x.DeliveryOutDate = outDate; doHit++; }

        // (2) điều chuyển kho — guard trạng thái dòng "A2"/"F" đúng như nguồn
        foreach (var x in await db.StorageRearrangeDetails.Where(x => x.OrgId == t.OrgId && x.VIN == vin).ToListAsync())
        {
            if (x.RearrangeDtlStatus is not ("A2" or "F")) { skipped.Add($"{vin}: điều chuyển kho đang \"{x.RearrangeDtlStatus}\""); continue; }
            x.RearrangeOutDate = outDate; rearrHit++;
        }

        // (3) thu hồi xe
        foreach (var x in await db.CarRetrieves.Where(x => x.OrgId == t.OrgId && x.Vin == vin).ToListAsync())
        { x.RetrieveOutDate = outDate; retrHit++; }

        // (4) điều chuyển đóng thùng — guard trạng thái dòng "A"/"F"
        foreach (var x in await db.StoRearCBDtls.Where(x => x.OrgId == t.OrgId && x.VIN == vin).ToListAsync())
        {
            if (x.RearCBDtlStatus is not ("A" or "F")) { skipped.Add($"{vin}: đóng thùng đang \"{x.RearCBDtlStatus}\""); continue; }
            x.RearCBOutDate = outDate; cbHit++;
        }
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { dlvMinutesNo = no, status = m.FDlvMnStatus, deliveryOutDate = outDate, cars = vins.Count,
        updated = new { deliveryOrder = doHit, storageRearrange = rearrHit, carRetrieve = retrHit, rearrangeCB = cbHit },
        skipped });
}).RequireAuthorization();

app.MapGet("/api/dlvminutes", async (AppDbContext db, ITenantContext t, string? status, string? vin) =>
{
    var qy = db.TranspDlvConfirms.Where(m => m.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) qy = qy.Where(m => m.FDlvMnStatus == status);
    if (!string.IsNullOrWhiteSpace(vin))
    {
        var v = vin.Trim().ToUpperInvariant();
        qy = qy.Where(m => db.TranspDlvConfirmCars.Any(c => c.OrgId == t.OrgId && c.TranspDlvConfirmId == m.Id && c.VIN.Contains(v)));
    }
    var items = await qy.OrderByDescending(m => m.Id).Take(500).Select(m => new
    {
        m.DlvMinutesNo, m.TransporterCode, m.DealerCode, m.FDlvMnStatus, m.TDlvMnStatus,
        m.FApprovedDate, m.FApprovedBy, m.TApprovedDate, m.TApprovedBy, m.CreatedAt,
        m.CorrectDate, m.CorrectBy, m.TFValReal, m.TPValReal, m.TFInputDate, m.TFInputBy,
        m.TFVCode, m.TPValSys, m.TPVCode, m.GPSDvNo, m.DlvEndDateTime, m.DlvEndBy,
        cars = db.TranspDlvConfirmCars.Count(c => c.OrgId == t.OrgId && c.TranspDlvConfirmId == m.Id),
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/dlvminutes", async (DlvMinutesDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.VIN)) return Results.BadRequest(new { error = "Cần VIN." });
    if (string.IsNullOrWhiteSpace(dto.TransporterCode)) return Results.BadRequest(new { error = "Cần đơn vị vận tải." });
    var no = "DLV" + DateTime.Now.ToString("yyMMddHHmmss");
    var m = new TranspDlvConfirm
    {
        OrgId = t.OrgId, DlvMinutesNo = no, TransporterCode = dto.TransporterCode.Trim(),
        FDlvMnStatus = "P", TDlvMnStatus = "P",     // hai phía duyệt ĐỘC LẬP (TConst.Stage)
        // #169: bản biểu phí áp cho biên bản — bước xác nhận đọc lại cột này để tra ExpectedDays.
        TFVCode = dto.TFVCode,
    };
    db.TranspDlvConfirms.Add(m); await db.SaveChangesAsync();

    // Tuyến đi theo XE (đúng mô hình nguồn), không nằm ở header.
    db.TranspDlvConfirmCars.Add(new TranspDlvConfirmCar
    {
        OrgId = t.OrgId, TranspDlvConfirmId = m.Id, VIN = dto.VIN.Trim().ToUpperInvariant(),
        FProvinceCode = dto.FProvinceCode, TProvinceCode = dto.TProvinceCode,
        FDistrictCode = dto.FDistrictCode, TDistrictCode = dto.TDistrictCode,
        DriverCode = dto.DriverCode, DlvStartDate = dto.DlvStartDate, DlvEndDate = dto.DlvEndDate,
    });

    // Checklist: bộ cũ lưu JSON, bộ giữ lưu thành BẢNG (DlvMinutesCheckItem) — ghi theo bảng.
    foreach (var kv in dto.Checklist ?? new Dictionary<string, bool>())
    {
        var parts = kv.Key.Split('.', 2);
        db.DlvMinutesCheckItems.Add(new DlvMinutesCheckItem
        {
            OrgId = t.OrgId, TranspDlvConfirmId = m.Id,
            ItemGroup = parts.Length == 2 ? parts[0] : "OS",
            ItemCode = parts.Length == 2 ? parts[1] : kv.Key,
            FStatus = kv.Value ? "1" : "0",
        });
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { m.DlvMinutesNo, vin = dto.VIN.Trim().ToUpperInvariant() });
}).RequireAuthorization();

app.MapGet("/api/dlvminutes/{no}", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.TranspDlvConfirms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlvMinutesNo.ToUpper() == no);
    if (m is null) return Results.NotFound(new { no });
    var cars = await db.TranspDlvConfirmCars.Where(c => c.OrgId == t.OrgId && c.TranspDlvConfirmId == m.Id)
        .Select(c => new { c.VIN, c.ModelCode, c.FProvinceCode, c.TProvinceCode, c.FDistrictCode, c.TDistrictCode,
            c.DriverCode, c.DlvStartDate, c.DlvEndDate }).ToListAsync();
    var checklist = await db.DlvMinutesCheckItems.Where(x => x.OrgId == t.OrgId && x.TranspDlvConfirmId == m.Id)
        .Select(x => new { x.ItemGroup, x.ItemCode, x.FStatus, x.TStatus }).ToListAsync();
    return Results.Ok(new { m.DlvMinutesNo, m.TransporterCode, m.DealerCode,
        m.FDlvMnStatus, m.TDlvMnStatus, m.FApprovedDate, m.FApprovedBy, m.TApprovedDate, m.TApprovedBy,
        m.TPlateNo, m.TDriverId, m.TDriverName, m.TGPSDvStatus, m.TRemark, m.TStatusIaKm, m.TStatusIaRemark,
        m.CorrectDate, m.CorrectBy, m.TFValReal, m.TPValReal, m.TFRemark, m.TFInputDate, m.TFInputBy,
        m.TFVCode, m.TPValSys, m.TPVCode, m.GPSDvNo, m.DlvEndGPSDateTime, m.DlvEndGPSBy,
        m.GPSDvAddress, m.GPSDvResponse, m.DlvEndDateTime, m.DlvEndBy,
        cars, checklist });
}).RequireAuthorization();

// Hỗ trợ sửa biên bản theo lô — khoá là CẶP (số biên bản, VIN): một biên bản chở nhiều xe, mỗi xe một tuyến.
// ===== #168 nhập phí vận chuyển thực tế — `Sto_DlvMinutes_InputFee_New20190416` =====
// Nguồn: `TERP.BizHTC/BizHTC.Storage.DlvMinutes.cs:8811` (csproj 120). BƯỚC 3B: md5 cả file `0b3b957d` KHỚP 2 máy.
// TWIN: WS 32-bit và 64-bit gọi **cùng** bản `_New20190416` cho cả cụm (chỉ `_DeleteSupport` là 64-bit-only).
// 🔴 Cờ `strFlagFeeOrPer` chỉ nhận **"FEE"** hoặc **"PER"**, **mỗi lần chỉ nhập MỘT trong hai**:
//    "FEE" ⇒ `TFValReal` (phí vận chuyển), "PER" ⇒ `TPValReal` (phạt trễ hạn). Cờ khác ⇒ `InputFee_InvalidFeeOrPer`.
// ===== #169 ĐẠI LÝ XÁC NHẬN nhận xe — `Sto_DlvMinutes_Confirm_New20190416` =====
// Nguồn: `TERP.BizHTC/BizHTC.Storage.DlvMinutes.cs:2822` (csproj 120). BƯỚC 3B: md5 cả file `0b3b957d` KHỚP 2 máy.
// TWIN: WS 32-bit và 64-bit gọi CÙNG bản `_New20190416`.
// Đây là đầu NHẬN, đối xứng với `/approve` (đầu GỬI) đã port: nó đóng trục `TDlvMnStatus`.
//
// 🔴 NĂM guard, và một CÔNG THỨC PHẠT — port cũ không có gì:
//   1. Vận tải tại nơi nhận đủ CẢ BA (`Confirm_InvalidTTVanTai`).
//   2. `FDlvMnStatus = "A"` **và** `TDlvMnStatus = "P"` (`Confirm_InvalidStatus`) — đầu gửi duyệt xong đầu nhận mới ký.
//   3. `DlvStartDate <= DlvEndDate` (`Confirm_InvalidDateEnd`).
//   4. 🔴 **LUẬT 12 GIỜ TRƯA**:
//        · bấm **trước 12h** ⇒ được nhập ngày nhận LÙI, nhưng nếu giữa ngày nhận và hôm nay còn
//          **ngày LÀM VIỆC** nào trong `Mst_Calendar` (`CalendarType='WorkingDay'`, `StatusValue=0`)
//          thì chặn (`Confirm_HolidayNotBeSet`) — tức chỉ được lùi qua chuỗi ngày NGHỈ;
//        · bấm **sau 12h** ⇒ ngày nhận **bắt buộc = hôm nay** (`Create_InvalidDlvEndDate`).
//   5. Phải có bản biểu phạt đang hiệu lực (`Confirm_InvalidPenaltyVer`).
// ===== #170 SỬA NGÀY NHẬN XE sau khi biên bản đã chốt — `Sto_DlvMinutes_UpdateDlvEndDate_New20181115` =====
// Nguồn: `TERP.BizHTC/BizHTC.Storage.DlvMinutes.cs:9329` (csproj 120). BƯỚC 3B: md5 cả file `0b3b957d` KHỚP 2 máy.
// TWIN: WS 32-bit và 64-bit gọi CÙNG bản `_New20181115`.
//
// ⚠️ KHÁC HẲN `/api/dlvminutes/update-dates` đã có: cái đó sửa **ngày XUẤT kho** (`DlvStartDate`) hàng loạt
//    và ghi lịch sử; cái này sửa **ngày NHẬN xe** (`DlvEndDate`) của MỘT biên bản đã chốt hai đầu,
//    rồi **lan ngược** ngày đó sang chứng từ gốc.
//
// 🔴 BA guard:
//   1. `FDlvMnStatus = "A"` **và** `TDlvMnStatus = "A"` (`UpdateDlvEndDate_InvalidStatus`) — cả hai đầu đã chốt.
//   2. `DlvStartDate <= DlvEndDate` (`UpdateDlvEndDate_InvalidDateEnd`).
//   3. Ngày nhận **không được rỗng** (`UpdateDlvEndDate_DateEndIsNotNull`).
//   4. Phải join được dòng YCVT `Sto_TranspReqDtl` với `TranspReqDtlStatus ∈ {"A","F"}` (`Approve_JoinTransReq`).
//
// 🔴 LAN NGƯỢC theo `TranspReqType` của DÒNG YCVT (`TConst.Sto_TranspReqType`) — bốn nhánh LOẠI TRỪ nhau:
//   · "CARTRANSPORT"     → `Car_DeliveryOrderDetail`: `DeliveryEndDate`, `ConfirmStatus = "F"`, `ConfirmDate`/`ConfirmBy`
//                          **và** `DLS_DealDetail`: `DeliveryDate`, `DeliveryStatus = "A"`, `ConfirmDate`/`ConfirmBy`
//   · "STORAGEREARRANGE" → `Sto_StorageRearrangeDetail`: `RearrangeEndDate`, `ConfirmDate`/`ConfirmBy`
//   · "CARRETRIEVE"      → `Sto_CarRetrieveDetail`: `RetrieveEndDate`
//   · "STORAGEREARRCB"   → `Sto_RearrangeCBDetail`: `RearCBEndDate`, `ConfirmDate`/`ConfirmBy`
app.MapPost("/api/dlvminutes/{no}/update-enddate", async (string no, DlvUpdEndDateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.TranspDlvConfirms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlvMinutesNo.ToUpper() == no);
    if (m is null) return Results.NotFound(new { no });
    if (m.FDlvMnStatus != "A" || m.TDlvMnStatus != "A")
        return Results.BadRequest(new { error = $"Chỉ sửa ngày nhận khi CẢ HAI đầu đã duyệt (đang là F='{m.FDlvMnStatus}', T='{m.TDlvMnStatus}')." });
    if (dto.DlvEndDate is null) return Results.BadRequest(new { error = "Ngày nhận xe không được để trống." });
    var endDate = dto.DlvEndDate.Value;
    if (m.DlvStartDate is not null && m.DlvStartDate.Value > endDate)
        return Results.BadRequest(new { error = $"Ngày nhận xe ({endDate:yyyy-MM-dd}) không được trước ngày xuất kho ({m.DlvStartDate:yyyy-MM-dd})." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;

    var vins = await db.TranspDlvConfirmCars.Where(c => c.OrgId == t.OrgId && c.TranspDlvConfirmId == m.Id)
        .Select(c => c.VIN).ToListAsync();
    if (vins.Count == 0) return Results.BadRequest(new { error = "Biên bản không có xe nào." });

    m.DlvEndDate = endDate;
    int doHit = 0, rearrHit = 0, retrHit = 0, cbHit = 0;
    var skipped = new List<string>();

    foreach (var vin in vins)
    {
        // Dòng YCVT quyết định lan sang chứng từ NÀO — guard `TranspReqDtlStatus ∈ {"A","F"}`.
        var dtl = await db.RetrieveReqCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Vin == vin
            && (x.DtlStatus == "A" || x.DtlStatus == "F"));
        if (dtl is null) { skipped.Add($"{vin}: không có dòng yêu cầu vận chuyển ở trạng thái A/F"); continue; }
        var reqType = (dtl.TranspReqType ?? "").Trim().ToUpperInvariant();

        if (reqType == "CARTRANSPORT")
        {
            foreach (var x in await db.DeliveryOrderCars.Where(x => x.OrgId == t.OrgId && x.Vin == vin).ToListAsync())
            {
                x.DeliveryEndDate = endDate;
                x.ConfirmStatus = "F";                       // nguồn: TConst.Stage.Finished
                x.ConfirmDate = now; x.ConfirmBy = who;
                x.LogLUDateTime = now; x.LogLUBy = who;
                doHit++;
            }
            // ⚠️ NỢ: nhánh này còn ghi `DLS_DealDetail` (`DeliveryDate`, `DeliveryStatus = "A"`, `ConfirmDate`/`ConfirmBy`).
            //    MiniHTC chưa port bảng `DLS_DealDetail` ⇒ ghi nợ, KHÔNG bịa bảng thay thế.
        }
        else if (reqType == "STORAGEREARRANGE")
        {
            foreach (var x in await db.StorageRearrangeDetails.Where(x => x.OrgId == t.OrgId && x.VIN == vin).ToListAsync())
            {
                x.RearrangeEndDate = endDate; x.ConfirmDate = now; x.ConfirmBy = who; rearrHit++;
            }
        }
        else if (reqType == "CARRETRIEVE")
        {
            foreach (var x in await db.CarRetrieves.Where(x => x.OrgId == t.OrgId && x.Vin == vin).ToListAsync())
            {
                x.RetrieveEndDate = endDate;
                // 🔴 LỆCH CÓ CHỦ ĐÍCH: nguồn gán `LogLUDateTime = LogLUBy = objDlvEndDate` cho nhánh này —
                //    tức nhét NGÀY vào cột NGƯỜI. Đây là lỗi copy-paste hiển nhiên của nguồn (ba nhánh kia
                //    đều gán đúng `DateTime.Now` / `strPartnerUserCode`), không phải luật nghiệp vụ ⇒ ghi đúng.
                x.LogLUDateTime = now; x.LogLUBy = who;
                retrHit++;
            }
        }
        else if (reqType == "STORAGEREARRCB")
        {
            foreach (var x in await db.StoRearCBDtls.Where(x => x.OrgId == t.OrgId && x.VIN == vin).ToListAsync())
            {
                x.RearCBEndDate = endDate; x.ConfirmDate = now; x.ConfirmBy = who; cbHit++;
            }
        }
        else skipped.Add($"{vin}: loại yêu cầu vận chuyển \"{reqType}\" không thuộc bốn loại nguồn xử lý");
    }

    m.LogLUDateTime = now; m.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { m.DlvMinutesNo, m.DlvEndDate, cars = vins.Count,
        updated = new { deliveryOrder = doHit, storageRearrange = rearrHit, carRetrieve = retrHit, rearrangeCB = cbHit },
        skipped });
}).RequireAuthorization();

app.MapPost("/api/dlvminutes/{no}/confirm", async (string no, DlvConfirmDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.TranspDlvConfirms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlvMinutesNo.ToUpper() == no);
    if (m is null) return Results.NotFound(new { no });

    var plate = (dto.TPlateNo ?? "").Trim(); var drvId = (dto.TDriverId ?? "").Trim(); var drvNm = (dto.TDriverName ?? "").Trim();
    if (plate.Length == 0 || drvId.Length == 0 || drvNm.Length == 0)
        return Results.BadRequest(new { error = "Thiếu thông tin vận tải tại nơi nhận (biển số / CMND lái xe / tên lái xe)." });
    if (m.FDlvMnStatus != "A" || m.TDlvMnStatus != "P")
        return Results.BadRequest(new { error = $"Trạng thái không cho xác nhận (đầu gửi='{m.FDlvMnStatus}', đầu nhận='{m.TDlvMnStatus}'): đầu gửi phải đã duyệt (A) và đầu nhận còn chờ (P)." });
    if (dto.DlvEndDate is null) return Results.BadRequest(new { error = "Chưa nhập ngày nhận xe." });
    var endDate = dto.DlvEndDate.Value;
    if (m.DlvStartDate is not null && m.DlvStartDate.Value > endDate)
        return Results.BadRequest(new { error = $"Ngày nhận xe ({endDate:yyyy-MM-dd}) không được trước ngày xuất kho ({m.DlvStartDate:yyyy-MM-dd})." });

    var now = DateTime.Now;
    var noon = now.Date.AddHours(12);
    if (now <= noon)
    {
        // Trước 12h: chỉ được lùi ngày nhận qua chuỗi ngày NGHỈ — còn ngày làm việc xen giữa là chặn.
        var hasWorkingDay = await db.MstCalendars.AnyAsync(c => c.OrgId == t.OrgId
            && c.CalendarType == "WorkingDay" && c.StatusValue == "0"
            && c.Date > endDate.Date && c.Date < now.Date);
        if (hasWorkingDay)
            return Results.BadRequest(new { error = $"Giữa ngày nhận ({endDate:yyyy-MM-dd}) và hôm nay còn ngày làm việc — không lùi ngày nhận được." });
    }
    else if (endDate.Date != now.Date)
        return Results.BadRequest(new { error = $"Sau 12h trưa chỉ được nhập ngày nhận là hôm nay ({now:yyyy-MM-dd})." });

    // Bản biểu PHẠT đang hiệu lực (nguồn: `Mst_TranspPenaltyVer` top 1 theo `FlagActive='1'`).
    var pen = await db.TranspFees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.FlagPenaltyVer == "1");
    if (pen is null) return Results.BadRequest(new { error = "Chưa thiết lập bản biểu phạt trễ hạn đang hiệu lực." });

    // Biểu phí của ĐÚNG tuyến (tỉnh/huyện đi–đến + nhà vận chuyển + model xe suy từ VIN) ⇒ số ngày ĐỊNH MỨC.
    var firstVin = await db.TranspDlvConfirmCars.Where(c => c.OrgId == t.OrgId && c.TranspDlvConfirmId == m.Id)
        .Select(c => c.VIN).FirstOrDefaultAsync();
    string? modelCode = firstVin is null ? null
        : await db.CarVinMasters.Where(v => v.OrgId == t.OrgId && v.VIN == firstVin).Select(v => v.ModelCode).FirstOrDefaultAsync();
    var fee = modelCode is null ? null : await db.TranspFees.FirstOrDefaultAsync(f => f.OrgId == t.OrgId
        && f.TFVCode == m.TFVCode && f.ProvinceCodeFrom == m.FProvinceCode && f.ProvinceCodeTo == m.TProvinceCode
        && f.DistrictCodeFrom == m.FDistrictCode && f.DistrictCodeTo == m.TDistrictCode
        && f.TransporterCode == m.TransporterCode && f.ModelCode == modelCode);

    // 🔴 Không có biểu phí khớp ⇒ nguồn KHÔNG ném lỗi (throw bị comment) và nhánh tính phạt nằm trong `else`
    //    ⇒ kết quả là KHÔNG PHẠT. Giữ đúng, không "tiện tay" phạt từ ngày 0.
    decimal penalty = 0m;
    int lateDays = 0;
    if (fee is not null && m.DlvStartDate is not null)
    {
        var span = (endDate.Date - m.DlvStartDate.Value.Date).Days;
        lateDays = span - fee.ExpectedDays;
        // Bậc thang GIẢM DẦN: ngày trễ đầu chịu ValBased + (n−1)·ValEx, ngày trễ cuối chỉ ValBased.
        for (int i = lateDays; i > 0; i--) penalty += pen.ValBased + (i - 1) * pen.ValEx;
        if (lateDays < 0) lateDays = 0;
    }

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    m.TDlvMnStatus = "A";
    // ⚠️ Nguồn ghi `TApprovedDate` bằng **"yyyy-MM-dd"** (chỉ NGÀY, comment 20140106) — không phải cả giờ.
    m.TApprovedDate = now.Date; m.TApprovedBy = who;
    m.DlvEndDate = endDate;
    m.DlvEndDateTime = now; m.DlvEndBy = who;     // mốc bấm "Lưu", khác ngày nhận xe
    m.TPValSys = penalty; m.TPValReal = penalty;  // nguồn gán TPValReal = TPValSys ngay tại đây
    m.TPVCode = pen.TPVCode;
    m.TPlateNo = plate; m.TDriverId = drvId; m.TDriverName = drvNm;
    m.TGPSDvStatus = dto.TGPSDvStatus; m.TRemark = dto.TRemark; m.TStatusIaRemark = dto.TStatusIaRemark;
    if (dto.TStatusIaKm is not null) m.TStatusIaKm = dto.TStatusIaKm;
    // GPS: nguồn tra `Sto_StoBalanceGPS` theo VIN rồi gọi Veloca (3 lần, nuốt mọi lỗi) để lấy địa chỉ.
    // ⚠️ NỢ: MiniHTC chưa có `Sto_StoBalanceGPS` lẫn tầng gọi Veloca ⇒ nhận sẵn từ client, KHÔNG bịa.
    m.GPSDvNo = dto.GPSDvNo; m.GPSDvAddress = dto.GPSDvAddress; m.GPSDvResponse = dto.GPSDvResponse;
    if (!string.IsNullOrWhiteSpace(dto.GPSDvNo)) { m.DlvEndGPSDateTime = now; m.DlvEndGPSBy = who; }

    int items = 0;
    foreach (var it in dto.Items ?? new())
    {
        var row = await db.DlvMinutesCheckItems.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TranspDlvConfirmId == m.Id && x.ItemCode == it.ItemCode);
        if (row is null) return Results.BadRequest(new { error = $"Danh mục '{it.ItemCode}' không thuộc biên bản {no}." });
        row.TStatus = it.TStatus; items++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { m.DlvMinutesNo, m.TDlvMnStatus, m.TApprovedDate, m.TApprovedBy, m.DlvEndDate,
        m.DlvEndDateTime, m.DlvEndBy, m.TPValSys, m.TPValReal, m.TPVCode, expectedDays = fee?.ExpectedDays,
        lateDays, m.GPSDvNo, m.GPSDvAddress, itemsUpdated = items });
}).RequireAuthorization();

app.MapPost("/api/dlvminutes/{no}/inputfee", async (string no, DlvInputFeeDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.TranspDlvConfirms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlvMinutesNo.ToUpper() == no);
    if (m is null) return Results.NotFound(new { no });
    var flag = (dto.FlagFeeOrPer ?? "").Trim().ToUpperInvariant();
    if (flag is not ("FEE" or "PER")) return Results.BadRequest(new { error = "Cờ nhập phí chỉ nhận FEE hoặc PER." });
    if (dto.Value is null || dto.Value < 0)
        return Results.BadRequest(new { error = flag == "FEE" ? "Phí vận chuyển thực tế không hợp lệ." : "Tiền phạt trễ hạn không hợp lệ." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    if (flag == "FEE") m.TFValReal = dto.Value.Value; else m.TPValReal = dto.Value.Value;
    m.TFRemark = dto.TFRemark; m.TFInputDate = DateTime.Now; m.TFInputBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { m.DlvMinutesNo, flag, m.TFValReal, m.TPValReal, m.TFRemark, m.TFInputDate, m.TFInputBy });
}).RequireAuthorization();

// ===== #168 ĐÍNH CHÍNH biên bản giao xe — `Sto_DlvMinutes_Correct_New20190416` (4915) =====
// 🔴 BỐN guard, port cũ không có cái nào:
//   1. `TApprovedDate` phải CÓ (`Correct_TApprovedDateNotFound`) — chưa được đại lý xác nhận thì không đính chính.
//   2. Vận tải **tại nơi nhận** đủ CẢ BA: biển số · CMND lái xe · tên lái xe (`Correct_InvalidTTVanTai`).
//   3. **CẢ HAI** trục `FDlvMnStatus` **và** `TDlvMnStatus` phải `TConst.Stage.Approved` (`Correct_InvalidStatus`).
//   4. 🔴 **Hạn 2 NGÀY** kể từ `TApprovedDate` (`new TimeSpan(2,0,0,0)`; vượt ⇒ `Correct_OverTime`).
// Ghi `CorrectDate`/`CorrectBy` + đè lại danh mục tình trạng xe (bảng con `DlvMinutesCheckItems`, cột `TStatus`)
// và thông tin vận tải nơi nhận. Nguồn lưu danh mục thành 36 cột phẳng `TStatus_OS_*`/`_IS_*`/`_SP_*`/`_DA_*`;
// MiniHTC đã TÁCH thành bảng con — ánh xạ 1:1 theo `ItemCode`.
// ===== #171 XÁC NHẬN QUYỀN QUẢN TRỊ — `Sto_DlvMinutes_Confirm_sysadmin_New20190416` =====
// Nguồn: `TERP.BizHTC/BizHTC.Storage.DlvMinutes.cs:6701` (csproj 120). BƯỚC 3B: md5 cả file `0b3b957d` KHỚP 2 máy.
// 🔴 Đây là bản SONG SONG của `_Confirm` (#169), khác ĐÚNG MỘT điểm: **toàn bộ khối LUẬT 12 GIỜ TRƯA
//    bị comment** (nguồn 6957-6990) ⇒ quản trị viên nhập được ngày nhận BẤT KỲ trong quá khứ,
//    không bị chặn bởi "chỉ lùi qua ngày nghỉ" hay "sau 12h phải là hôm nay".
//    Ba guard còn lại và CÔNG THỨC PHẠT thì **giữ nguyên** — bộ mã lỗi cũng đổi thành `*_sysadmin`.
// ⚠️ Vì bỏ chốt thời gian nên đây là endpoint đặc quyền: đặt route riêng để không lẫn với `/confirm`.
app.MapPost("/api/dlvminutes/{no}/confirm-sysadmin", async (string no, DlvConfirmDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.TranspDlvConfirms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlvMinutesNo.ToUpper() == no);
    if (m is null) return Results.NotFound(new { no });

    var plate = (dto.TPlateNo ?? "").Trim(); var drvId = (dto.TDriverId ?? "").Trim(); var drvNm = (dto.TDriverName ?? "").Trim();
    if (plate.Length == 0 || drvId.Length == 0 || drvNm.Length == 0)
        return Results.BadRequest(new { error = "Thiếu thông tin vận tải tại nơi nhận (biển số / CMND lái xe / tên lái xe)." });
    if (m.FDlvMnStatus != "A" || m.TDlvMnStatus != "P")
        return Results.BadRequest(new { error = $"Trạng thái không cho xác nhận (đầu gửi='{m.FDlvMnStatus}', đầu nhận='{m.TDlvMnStatus}')." });
    if (dto.DlvEndDate is null) return Results.BadRequest(new { error = "Chưa nhập ngày nhận xe." });
    var endDate = dto.DlvEndDate.Value;
    if (m.DlvStartDate is not null && m.DlvStartDate.Value > endDate)
        return Results.BadRequest(new { error = $"Ngày nhận xe ({endDate:yyyy-MM-dd}) không được trước ngày xuất kho ({m.DlvStartDate:yyyy-MM-dd})." });

    // 🔴 KHÔNG có luật 12h ở đây — đúng nguồn. Đây là điểm KHÁC DUY NHẤT so với `/confirm`.

    var pen = await db.TranspFees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.FlagPenaltyVer == "1");
    if (pen is null) return Results.BadRequest(new { error = "Chưa thiết lập bản biểu phạt trễ hạn đang hiệu lực." });

    var firstVin = await db.TranspDlvConfirmCars.Where(c => c.OrgId == t.OrgId && c.TranspDlvConfirmId == m.Id)
        .Select(c => c.VIN).FirstOrDefaultAsync();
    string? modelCode = firstVin is null ? null
        : await db.CarVinMasters.Where(v => v.OrgId == t.OrgId && v.VIN == firstVin).Select(v => v.ModelCode).FirstOrDefaultAsync();
    var fee = modelCode is null ? null : await db.TranspFees.FirstOrDefaultAsync(f => f.OrgId == t.OrgId
        && f.TFVCode == m.TFVCode && f.ProvinceCodeFrom == m.FProvinceCode && f.ProvinceCodeTo == m.TProvinceCode
        && f.DistrictCodeFrom == m.FDistrictCode && f.DistrictCodeTo == m.TDistrictCode
        && f.TransporterCode == m.TransporterCode && f.ModelCode == modelCode);

    decimal penalty = 0m;
    int lateDays = 0;
    if (fee is not null && m.DlvStartDate is not null)
    {
        var span = (endDate.Date - m.DlvStartDate.Value.Date).Days;
        lateDays = span - fee.ExpectedDays;
        for (int i = lateDays; i > 0; i--) penalty += pen.ValBased + (i - 1) * pen.ValEx;
        if (lateDays < 0) lateDays = 0;
    }

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    m.TDlvMnStatus = "A";
    m.TApprovedDate = now.Date; m.TApprovedBy = who;
    m.DlvEndDate = endDate;
    m.DlvEndDateTime = now; m.DlvEndBy = who;
    m.TPValSys = penalty; m.TPValReal = penalty;
    m.TPVCode = pen.TPVCode;
    m.TPlateNo = plate; m.TDriverId = drvId; m.TDriverName = drvNm;
    m.TGPSDvStatus = dto.TGPSDvStatus; m.TRemark = dto.TRemark; m.TStatusIaRemark = dto.TStatusIaRemark;
    if (dto.TStatusIaKm is not null) m.TStatusIaKm = dto.TStatusIaKm;
    m.GPSDvNo = dto.GPSDvNo; m.GPSDvAddress = dto.GPSDvAddress; m.GPSDvResponse = dto.GPSDvResponse;
    if (!string.IsNullOrWhiteSpace(dto.GPSDvNo)) { m.DlvEndGPSDateTime = now; m.DlvEndGPSBy = who; }
    m.LogLUDateTime = now; m.LogLUBy = who;

    int items = 0;
    foreach (var it in dto.Items ?? new())
    {
        var row = await db.DlvMinutesCheckItems.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TranspDlvConfirmId == m.Id && x.ItemCode == it.ItemCode);
        if (row is null) return Results.BadRequest(new { error = $"Danh mục '{it.ItemCode}' không thuộc biên bản {no}." });
        row.TStatus = it.TStatus; items++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { m.DlvMinutesNo, m.TDlvMnStatus, m.TApprovedDate, m.TApprovedBy, m.DlvEndDate,
        m.DlvEndDateTime, m.DlvEndBy, m.TPValSys, m.TPValReal, m.TPVCode, expectedDays = fee?.ExpectedDays,
        lateDays, m.GPSDvNo, m.GPSDvAddress, itemsUpdated = items, sysadmin = true });
}).RequireAuthorization();

app.MapPost("/api/dlvminutes/{no}/correct", async (string no, DlvCorrectDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.TranspDlvConfirms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlvMinutesNo.ToUpper() == no);
    if (m is null) return Results.NotFound(new { no });
    if (m.TApprovedDate is null)
        return Results.BadRequest(new { error = "Biên bản chưa được đại lý xác nhận — không đính chính được." });
    var plate = (dto.TPlateNo ?? "").Trim(); var drvId = (dto.TDriverId ?? "").Trim(); var drvNm = (dto.TDriverName ?? "").Trim();
    if (plate.Length == 0 || drvId.Length == 0 || drvNm.Length == 0)
        return Results.BadRequest(new { error = "Thiếu thông tin vận tải tại nơi nhận (biển số / CMND lái xe / tên lái xe)." });
    if (m.FDlvMnStatus != "A" || m.TDlvMnStatus != "A")
        return Results.BadRequest(new { error = $"Trạng thái hai đầu phải đều đã duyệt (đang là F='{m.FDlvMnStatus}', T='{m.TDlvMnStatus}')." });
    var now = DateTime.Now;
    if (now - m.TApprovedDate.Value > TimeSpan.FromDays(2))
        return Results.BadRequest(new { error = $"Quá hạn đính chính: chỉ được sửa trong 2 ngày kể từ {m.TApprovedDate:yyyy-MM-dd HH:mm}." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    m.CorrectDate = now; m.CorrectBy = who;
    m.TPlateNo = plate; m.TDriverId = drvId; m.TDriverName = drvNm;
    m.TGPSDvStatus = dto.TGPSDvStatus; m.TRemark = dto.TRemark; m.TStatusIaRemark = dto.TStatusIaRemark;
    if (dto.TStatusIaKm is not null) m.TStatusIaKm = dto.TStatusIaKm;
    int items = 0;
    foreach (var it in dto.Items ?? new())
    {
        var row = await db.DlvMinutesCheckItems.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TranspDlvConfirmId == m.Id && x.ItemCode == it.ItemCode);
        if (row is null) return Results.BadRequest(new { error = $"Danh mục '{it.ItemCode}' không thuộc biên bản {no}." });
        row.TStatus = it.TStatus; items++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { m.DlvMinutesNo, m.CorrectDate, m.CorrectBy, m.TPlateNo, m.TDriverId, m.TDriverName,
        m.TGPSDvStatus, m.TRemark, m.TStatusIaKm, m.TStatusIaRemark, itemsUpdated = items });
}).RequireAuthorization();

app.MapPost("/api/dlvminutes/patch-batch", async (
    DlvMinutesBatchPatchDto dto, AppDbContext db, ITenantContext t) =>
{
    var lines = (dto.Rows ?? new()).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu được thay đổi" });

    // Nguồn kiểm TỪNG DÒNG: rỗng CẢ BỐN cột mới mới báo lỗi.
    foreach (var line in lines)
    {
        if (string.IsNullOrWhiteSpace(line.FProvinceCodeNew)
            && string.IsNullOrWhiteSpace(line.FDistrictCodeNew)
            && string.IsNullOrWhiteSpace(line.TProvinceCodeNew)
            && string.IsNullOrWhiteSpace(line.TDistrictCodeNew))
            return Results.BadRequest(new { error = "Các cột dữ liệu mới không được để trống toàn bộ!" });
    }

    int updated = 0;
    var notFound = new List<string>();
    foreach (var line in lines)
    {
        var minutesNo = (line.DlvMinutesNo ?? "").Trim().ToUpperInvariant();
        var vin = (line.VIN ?? "").Trim().ToUpperInvariant();
        var row = await db.TranspDlvConfirmCars
            .Where(c => c.OrgId == t.OrgId && c.VIN.ToUpper() == vin)
            .Join(db.TranspDlvConfirms.Where(h => h.OrgId == t.OrgId && h.DlvMinutesNo.ToUpper() == minutesNo),
                  c => c.TranspDlvConfirmId, h => h.Id, (c, h) => c)
            .FirstOrDefaultAsync();
        if (row is null) { notFound.Add($"{minutesNo}/{vin}"); continue; }

        // Cột mới bỏ trống = GIỮ NGUYÊN giá trị cũ, không xoá.
        if (!string.IsNullOrWhiteSpace(line.FProvinceCodeNew)) row.FProvinceCode = line.FProvinceCodeNew.Trim().ToUpperInvariant();
        if (!string.IsNullOrWhiteSpace(line.FDistrictCodeNew)) row.FDistrictCode = line.FDistrictCodeNew.Trim().ToUpperInvariant();
        if (!string.IsNullOrWhiteSpace(line.TProvinceCodeNew)) row.TProvinceCode = line.TProvinceCodeNew.Trim().ToUpperInvariant();
        if (!string.IsNullOrWhiteSpace(line.TDistrictCodeNew)) row.TDistrictCode = line.TDistrictCodeNew.Trim().ToUpperInvariant();
        updated++;
    }

    if (updated == 0) return Results.BadRequest(new { error = "Không có dữ liệu được thay đổi", notFound });
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, notFound, message = "Lưu Thành công!" });
}).RequireAuthorization();

// Hỗ trợ xóa biên bản (port 1:1 FrmSupportSto_DlvMinutes_Delete).
// TWIN: WS gọi biz `Sto_DlvMinutes_Del_New20181115` (KHÔNG phải bản trần).
// 🔴 Luật nguồn dùng ĐÚNG cột `FDlvMnStatus`: SQL chặn `FDlvMnStatus not in ('P')`
// ⇒ chỉ xoá khi phía GIAO còn chờ duyệt. Trước hợp nhất, port cũ kiểm cột `Status` tự đặt ("Draft").
app.MapDelete("/api/dlvminutes/{no}", async (string no, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.TranspDlvConfirms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlvMinutesNo.ToUpper() == no);
    if (m is null) return Results.NotFound(new { no });
    // ===== #171 🔴 VÁ LẠI GUARD — sửa một KẾT LUẬN SAI của lượt trước =====
    // Lượt trước đọc trong SQL của `Sto_DlvMinutes_DeleteSupport` (Biz.HTC.WH.cs:139330-139338) hai dòng
    //   `--and t.FDlvMnStatus in ('P', 'A')` và `--and t.FDlvMnStatus = 'P'` **bị comment**,
    // rồi kết luận "nguồn không guard trạng thái" và GỠ guard đi. SAI: guard không biến mất, nó được
    // **VIẾT LẠI BẰNG C# ngay bên dưới** (139358-139385) và **throw thật**:
    //   · `FDlvMnStatus` phải là "P" hoặc "A"  ⇒ `DeleteSupport_FDlvMnStatusInvalid`
    //   · `TDlvMnStatus` phải là "P"           ⇒ `DeleteSupport_TDlvMnStatusInvalid`
    // ⇒ chỉ xoá được biên bản mà **đầu nhận chưa xác nhận**. Đã khôi phục đúng nguồn.
    // 🔴 TWIN: `_DeleteSupport` CHỈ có ở WS 64-bit (`WSHTC.asmx.cs:36313`), WS 32-bit không có lệnh này.
    if (m.FDlvMnStatus is not ("P" or "A"))
        return Results.BadRequest(new { error = $"Đầu gửi đang ở '{m.FDlvMnStatus}' — chỉ xoá được khi P hoặc A." });
    if (m.TDlvMnStatus != "P")
        return Results.BadRequest(new { error = $"Đầu nhận đang ở '{m.TDlvMnStatus}' — chỉ xoá được khi đầu nhận CHƯA xác nhận (P)." });
    var carCount = await db.TranspDlvConfirmCars.CountAsync(x => x.OrgId == t.OrgId && x.TranspDlvConfirmId == m.Id);
    // 🔴 Nguồn CHÉP TOÀN BỘ dòng (69 cột) sang `Sto_DlvMinutes_HisDel` TRƯỚC khi xoá — port cũ xoá trắng.
    db.DlvMinutesHisDels.Add(new DlvMinutesHisDel
    {
        OrgId = t.OrgId, DlvMinutesNo = m.DlvMinutesNo, DealerCode = m.DealerCode,
        TransporterCode = m.TransporterCode, FDlvMnStatus = m.FDlvMnStatus, TDlvMnStatus = m.TDlvMnStatus,
        ConfirmStatus = m.ConfirmStatus, DlvStartDate = m.DlvStartDate, DlvEndDate = m.DlvEndDate,
        FProvinceCode = m.FProvinceCode, FDistrictCode = m.FDistrictCode,
        TProvinceCode = m.TProvinceCode, TDistrictCode = m.TDistrictCode,
        Remark = m.Remark, CarCount = carCount,
        DelDTime = DateTime.Now, DelBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system",
    });
    db.DlvMinutesCheckItems.RemoveRange(db.DlvMinutesCheckItems.Where(x => x.OrgId == t.OrgId && x.TranspDlvConfirmId == m.Id));
    db.TranspDlvConfirmCars.RemoveRange(db.TranspDlvConfirmCars.Where(x => x.OrgId == t.OrgId && x.TranspDlvConfirmId == m.Id));
    db.TranspDlvConfirms.Remove(m);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = no, snapshotSaved = true, carCount });
}).RequireAuthorization();

// ===== Đề nghị nhận xe/PDI (HtmvPdi — port 1:1 FrmNewPDI, 2010.HTC/Sales/HTMV) =====
app.MapGet("/api/htmvpdis", async (AppDbContext db, ITenantContext t, string? status) =>
{
    var q = db.HtmvPdis.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(r => r.Status == status);
    var items = await q.OrderByDescending(r => r.Id).Take(500).Select(r => new
    {
        r.PDINo, r.Status, r.CreatedAt, r.DoneAt,
        cars = db.HtmvPdiDtls.Count(c => c.OrgId == t.OrgId && c.HtmvPdiId == r.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/htmvpdis", async (HtmvPdiDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var cars = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.VIN)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "VIN không để trống." });
    var dupe = cars.GroupBy(c => c.VIN.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });
    var no = "PDI" + DateTime.Now.ToString("yyMMddHHmmss");
    var r = new HtmvPdi { OrgId = t.OrgId, PDINo = no, Status = "P", Remark = dto.Remark, CreatedBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system" };
    db.HtmvPdis.Add(r); await db.SaveChangesAsync();
    foreach (var c in cars)
        db.HtmvPdiDtls.Add(new HtmvPdiDtl { OrgId = t.OrgId, HtmvPdiId = r.Id, VIN = c.VIN.Trim().ToUpperInvariant(), ColorCode = c.ColorCode, SpecCode = c.SpecCode, LCTemp = c.LCTemp, RefNo = c.RefNo, ProductionMonth = c.ProductionMonth, EngineNo = c.EngineNo });
    await db.SaveChangesAsync();
    return Results.Ok(new { r.PDINo, cars = cars.Count, message = "Tạo đề nghị nhận xe thành công" });
}).RequireAuthorization();

app.MapGet("/api/htmvpdis/{no}/cars", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.HtmvPdis.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PDINo == no);
    if (r is null) return Results.NotFound(new { no });
    var cars = await db.HtmvPdiDtls.Where(c => c.OrgId == t.OrgId && c.HtmvPdiId == r.Id)
        .Select(c => new { c.VIN, c.ColorCode, c.SpecCode, c.ModelCode, c.LCTemp, c.RefNo, c.ProductionMonth, c.EngineNo, c.PdiResult, c.PDIDtlStatus, c.PDIStorageStatus }).ToListAsync();
    return Results.Ok(new { r.PDINo, r.Status, count = cars.Count, cars });
}).RequireAuthorization();

// 🔴 DUYỆT — `HTMV_PDIApprove_New20181115`. ⚠️ Bản LIVE nằm ở **file KHÁC**:
// `MMSIntergration/BizHTC.MMSIntergration.cs:2213` (Create/Cancel ở `BizHTC.HTMV.cs`);
// hàm `HTMV_PDIApprove` không hậu tố ở `BizHTC.HTMV.cs:1988` **không được WS gọi** — bản chết.
// Guard `PDIStorageStatus = "P"` rồi gán **"F" (Finished)** — KHÔNG phải "A".
app.MapPost("/api/htmvpdis/{no}/approve", async (string no, HtmvPdiCarsActionDto? dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.HtmvPdis.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PDINo == no);
    if (r is null) return Results.NotFound(new { no });
    var qy = db.HtmvPdiDtls.Where(c => c.OrgId == t.OrgId && c.HtmvPdiId == r.Id);
    var vins = (dto?.Vins ?? new()).Where(v => !string.IsNullOrWhiteSpace(v)).Select(v => v.Trim().ToUpperInvariant()).ToList();
    if (vins.Count > 0) qy = qy.Where(c => vins.Contains(c.VIN));
    var cars = await qy.ToListAsync();
    var bad = cars.FirstOrDefault(c => c.PDIStorageStatus != "P");
    if (bad is not null) return Results.BadRequest(new { error = $"VIN {bad.VIN} có trạng thái kho PDI '{bad.PDIStorageStatus}' — chỉ duyệt khi đang chờ (P)." });
    foreach (var c in cars) c.PDIStorageStatus = "F";
    r.ApprovedDate = DateTime.Now;
    r.ApprovedBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    await db.SaveChangesAsync();
    return Results.Ok(new { r.PDINo, approved = cars.Count, storageStatus = "F" });
}).RequireAuthorization();

// Xác nhận từng xe đạt/không đạt PDI (port 1:1 FrmMngPDI btnApproved_Click/btnCancel_Click — salesSv.PDIApproved/PDICancel, 2010.HTC/Sales/HTMV) — theo checkbox chọn VIN.
app.MapPost("/api/htmvpdis/{no}/{action}-cars", async (string no, string action, HtmvPdiCarsActionDto dto, AppDbContext db, ITenantContext t) =>
{
    if (action is not ("approve" or "cancel")) return Results.NotFound();
    no = no.Trim().ToUpperInvariant();
    var r = await db.HtmvPdis.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PDINo == no);
    if (r is null) return Results.NotFound(new { no });
    var vins = (dto.Vins ?? new()).Where(v => !string.IsNullOrWhiteSpace(v)).Select(v => v.Trim().ToUpperInvariant()).ToList();
    if (vins.Count == 0) return Results.BadRequest(new { error = "Chưa chọn dữ liệu" });
    var cars = await db.HtmvPdiDtls.Where(c => c.OrgId == t.OrgId && c.HtmvPdiId == r.Id && vins.Contains(c.VIN)).ToListAsync();
    // 🔴 Hai hành động chạm HAI TRỤC KHÁC NHAU trên cùng một dòng (không phải một cột "kết quả"):
    //  · duyệt  ⇒ `PDIStorageStatus` "P" → **"F"** (`HTMV_PDIApprove_New20181115`);
    //  · huỷ    ⇒ `PDIDtlStatus` "P" → **"C"**, guard thêm `PDIStorageStatus in ("P","C")`
    //             (`HTMV_PDICancel_New20181115`, BizHTC.HTMV.cs:2558+).
    if (action == "approve")
    {
        var bad = cars.FirstOrDefault(c => c.PDIStorageStatus != "P");
        if (bad is not null) return Results.BadRequest(new { error = $"VIN {bad.VIN} có trạng thái kho PDI '{bad.PDIStorageStatus}' — chỉ duyệt khi đang chờ (P)." });
        foreach (var c in cars) { c.PDIStorageStatus = "F"; c.PdiResult = "Passed"; }
    }
    else
    {
        var bad = cars.FirstOrDefault(c => c.PDIDtlStatus != "P" || (c.PDIStorageStatus != "P" && c.PDIStorageStatus != "C"));
        if (bad is not null) return Results.BadRequest(new { error = $"VIN {bad.VIN}: dòng '{bad.PDIDtlStatus}' / kho PDI '{bad.PDIStorageStatus}' — không huỷ được." });
        foreach (var c in cars) { c.PDIDtlStatus = "C"; c.PdiResult = "Failed"; }
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { updated = cars.Count, action });
}).RequireAuthorization();

// ===== Xe nhập kho PDI (StoragePdiVin — port 1:1 FrmStoragePDI, 2010.HTC/Sales/HTMV) =====
app.MapGet("/api/storagepdivins", async (AppDbContext db, ITenantContext t, string? vin, string? model, string? active) =>
