    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/storagepdivins", async (List<StoragePdiVinDto> dto, AppDbContext db, ITenantContext t) =>
{
    var rows = (dto ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.VIN)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "VIN không để trống." });
    var dupe = rows.GroupBy(c => c.VIN.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });
    int inserted = 0, updated = 0;
    foreach (var c in rows)
    {
        var vin = c.VIN.Trim().ToUpperInvariant();
        var ex = await db.StoragePdiVins.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.VIN == vin);
        if (ex is null) { db.StoragePdiVins.Add(new StoragePdiVin { OrgId = t.OrgId, VIN = vin, ModelCode = c.ModelCode, SpecCode = c.SpecCode, ColorCode = c.ColorCode, OrderNoMMS = c.OrderNoMMS, EngineNo = c.EngineNo, KeyNo = c.KeyNo, AVNSerialNo = c.AVNSerialNo, BatteryNo = c.BatteryNo, FlagActive = c.FlagActive == "0" ? "0" : "1", Remark = c.Remark, FinishDTime = c.FinishDTime }); inserted++; }
        else { ex.ModelCode = c.ModelCode; ex.SpecCode = c.SpecCode; ex.ColorCode = c.ColorCode; ex.OrderNoMMS = c.OrderNoMMS; ex.EngineNo = c.EngineNo; ex.KeyNo = c.KeyNo; ex.AVNSerialNo = c.AVNSerialNo; ex.BatteryNo = c.BatteryNo; ex.Remark = c.Remark; ex.FinishDTime = c.FinishDTime ?? ex.FinishDTime; ex.UpdatedAt = DateTime.Now; updated++; }
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { total = rows.Count, inserted, updated, message = "Lưu thành công!" });
}).RequireAuthorization();

// ===== #B03 BÁO CÁO XE NHẬP KHO VÀ LẮP GPS (port 1:1 FrmRptXeNhapKhoVaLapGPS, 2010.HTC/StoFGPS) =====
// Trace twin LIVE: btnSearch_Click → `ReportStoFGPSService.Rpt_CarInStoAndMapGPS` (:364) rẽ theo `checkWH`:
//   false → WS `Rpt_CarInStoAndMapGPS` (WSHTC.asmx.cs:45569) → `_biz.Rpt_CarInStoAndMapGPS_New20181115`
//           (BizHTC.ZTempGPS.cs:9198, `_dbMain`)
//   true  → WS `Rpt_CarInStoAndMapGPS_WH` (:69653) → `..._WH_New20181119` (Biz.HTC.WH.cs:150689, `_dbWH`)
//   Hai hàm CÙNG THUẬT TOÁN, chỉ khác DB đích.
// 🔴 Báo cáo này KHÔNG chạy được chỉ bằng dữ liệu DMS: giữa hai bước SQL nguồn **gọi web-service NHÀ MÁY**
//    `WSNM.WS.MMS_Rpt_CarInStoAndMapGPS(...)` để lấy bảng (VIN, VINReal, GPSNo) rồi mới ghép ra kết quả.
//    MiniHTC không có đường tới MMS ⇒ tách làm HAI bước như luồng auto-unmap GPS đã làm:
//      B1 GET  …/mms-payload  → trả đúng `#tbl_Return` để đem gọi MMS
//      B2 POST …              → nhận kết quả MMS (body) và ghép ra báo cáo
//    Đây là XẤP XỈ CÓ NHÃN ở tầng vận chuyển, **thuật toán ghép giữ nguyên 1:1**.
static (DateTime from, DateTime to, string? err) RptCarInStoRange(DateTime? finishFrom, DateTime? finishTo)
{
    // Form chặn rỗng: "Chưa chọn Thời gian nhập kho!" (FrmRptXeNhapKhoVaLapGPS.cs:95-99)
    if (finishFrom is null) return (default, default, "Chưa chọn Thời gian nhập kho!");
    // `deFinishDTimeFrom.Properties.MinValue = new DateTime(2018, 10, 1)` (:52) — biên cứng của màn.
    if (finishFrom.Value < new DateTime(2018, 10, 1)) return (default, default, "Thời gian nhập kho phải từ 01/10/2018 trở đi.");
    // To rỗng ⇒ nguồn lấy giờ SERVER hiện tại (:103-105), không phải cuối ngày.
    return (finishFrom.Value, finishTo ?? DateTime.Now, null);
}

// Bước 1 — dựng `#tbl_PDI_VIN_Filter_Draft` → `#tbl_Return` (BizHTC.ZTempGPS.cs SQL khối 1).
app.MapGet("/api/reports/car-insto-and-mapgps/mms-payload", async (
    AppDbContext db, ITenantContext t,
    DateTime? finishFrom, DateTime? finishTo, DateTime? mapFrom, DateTime? mapTo, string? vin, string? gpsDvNo) =>
{
    var (ff, ft, err) = RptCarInStoRange(finishFrom, finishTo);
    if (err is not null) return Results.BadRequest(new { error = err });

    var vinKey = string.IsNullOrWhiteSpace(vin) ? null : vin.Trim().ToUpperInvariant();
    var gpsKey = string.IsNullOrWhiteSpace(gpsDvNo) ? null : gpsDvNo.Trim().ToUpperInvariant();

    // `from PDI_VIN pdiv left join Sto_StoTransactionGPS sstgps on pdiv.VIN = sstgps.VIN
    //  left join Sto_StoBalanceGPS ssbgps on sstgps.StorageCode = ssbgps.StorageCode and GPSDvNo = GPSDvNo`
    // ⚠️ nguồn so `=` TUYỆT ĐỐI cho VIN và GPSDvNo (KHÔNG phải LIKE) — khác màn #B02.
    var draft = await (
        from p in db.StoragePdiVins.Where(x => x.OrgId == t.OrgId && x.FinishDTime >= ff && x.FinishDTime <= ft)
        from s in db.GpsTransactions.Where(s => s.OrgId == t.OrgId && s.Vin == p.VIN).DefaultIfEmpty()
        from b in db.GpsInstalls.Where(b => b.OrgId == t.OrgId && s != null
                                            && b.StorageCode == s.StorageCode && b.GpsNo == s.GpsDvNo).DefaultIfEmpty()
        select new { VINReal = p.VIN, GPSNo = b == null ? null : b.GpsNo, p.FinishDTime, MapDateTime = (DateTime?)(s == null ? null : s.MapDateTime) }
    ).ToListAsync();

    if (mapFrom is not null) draft = draft.Where(d => d.MapDateTime >= mapFrom).ToList();
    if (mapTo is not null) draft = draft.Where(d => d.MapDateTime <= mapTo).ToList();
    if (vinKey is not null) draft = draft.Where(d => d.VINReal == vinKey).ToList();
    if (gpsKey is not null) draft = draft.Where(d => d.GPSNo == gpsKey).ToList();

    // 🔴 DÒNG MỒI của nguồn (`insert into #tbl_PDI_VIN_Filter_Draft(...) values('zzzzzVINReal', N'strGPSDvNo',
    //    '2100-01-01 00:00:00','2100-01-01 00:00:00')`) — luôn thêm 1 dòng giả mang **chính mã GPS đang tìm**
    //    để bảng gửi sang MMS không bao giờ rỗng và MMS vẫn tra được theo GPS. Port nguyên, không bỏ.
    var sentinel = new { VINReal = "zzzzzVINReal", GPSNo = gpsKey, FinishDTime = (DateTime?)new DateTime(2100, 1, 1), MapDateTime = (DateTime?)new DateTime(2100, 1, 1) };
    var tblReturn = draft.Append(sentinel)
        .GroupBy(d => new { d.VINReal, d.GPSNo, d.FinishDTime, d.MapDateTime }).Select(g => g.Key).ToList();   // `select distinct`

    return Results.Ok(new
    {
        count = tblReturn.Count, tblReturn,
        note = "Gửi bảng này sang WS nhà máy MMS_Rpt_CarInStoAndMapGPS, rồi POST kết quả (VIN, VINReal, GPSNo) sang /api/reports/car-insto-and-mapgps."
    });
}).RequireAuthorization();

// Bước 2 — ghép `#tbl_Return` × `#tbl_Mnf_VIN` (kết quả MMS) → báo cáo (khối SQL 2 của nguồn).
app.MapPost("/api/reports/car-insto-and-mapgps", async (
    List<MnfVinGpsDto> mnfVins, AppDbContext db, ITenantContext t,
    DateTime? finishFrom, DateTime? finishTo, DateTime? mapFrom, DateTime? mapTo, string? vin, string? gpsDvNo) =>
{
    var (ff, ft, err) = RptCarInStoRange(finishFrom, finishTo);
    if (err is not null) return Results.BadRequest(new { error = err });
    if (mnfVins is null) return Results.BadRequest(new { error = "Thiếu bảng kết quả nhà máy (VIN, VINReal, GPSNo)." });

    var vinKey = string.IsNullOrWhiteSpace(vin) ? null : vin.Trim().ToUpperInvariant();
    var gpsKey = string.IsNullOrWhiteSpace(gpsDvNo) ? null : gpsDvNo.Trim().ToUpperInvariant();

    var draft = await (
        from p in db.StoragePdiVins.Where(x => x.OrgId == t.OrgId && x.FinishDTime >= ff && x.FinishDTime <= ft)
        from s in db.GpsTransactions.Where(s => s.OrgId == t.OrgId && s.Vin == p.VIN).DefaultIfEmpty()
        from b in db.GpsInstalls.Where(b => b.OrgId == t.OrgId && s != null
                                            && b.StorageCode == s.StorageCode && b.GpsNo == s.GpsDvNo).DefaultIfEmpty()
        select new { VINReal = p.VIN, GPSNo = b == null ? null : b.GpsNo, p.FinishDTime, MapDateTime = (DateTime?)(s == null ? null : s.MapDateTime) }
    ).ToListAsync();
    if (mapFrom is not null) draft = draft.Where(d => d.MapDateTime >= mapFrom).ToList();
    if (mapTo is not null) draft = draft.Where(d => d.MapDateTime <= mapTo).ToList();
    if (vinKey is not null) draft = draft.Where(d => d.VINReal == vinKey).ToList();
    if (gpsKey is not null) draft = draft.Where(d => d.GPSNo == gpsKey).ToList();
    var sentinel = new { VINReal = "zzzzzVINReal", GPSNo = gpsKey, FinishDTime = (DateTime?)new DateTime(2100, 1, 1), MapDateTime = (DateTime?)new DateTime(2100, 1, 1) };
    var tblReturn = draft.Append(sentinel)
        .GroupBy(d => new { d.VINReal, d.GPSNo, d.FinishDTime, d.MapDateTime }).Select(g => g.Key).ToList();

    var mnf = mnfVins.Select(m => new { VIN = m.VIN?.Trim().ToUpperInvariant(), VINReal = m.VINReal?.Trim().ToUpperInvariant(), GPSNo = m.GPSNo?.Trim().ToUpperInvariant() }).ToList();

    // `#tbl_GPS_Map_VIN` = (Return ⋈ Mnf trên VINReal) **UNION** (Return ⋈ Mnf trên GPSNo) — union = distinct.
    var byVin = tblReturn.Join(mnf, r => r.VINReal, f => f.VINReal, (r, f) => new { f.GPSNo, f.VINReal });
    var byGps = tblReturn.Join(mnf, r => r.GPSNo, f => f.GPSNo, (r, f) => new { f.GPSNo, f.VINReal });
    var gpsMapVin = byVin.Concat(byGps).GroupBy(x => new { x.GPSNo, x.VINReal }).Select(g => g.Key).ToList();

    var vinList = gpsMapVin.Where(x => x.VINReal != null).Select(x => x.VINReal!).Distinct().ToList();
    var pdis = await db.StoragePdiVins.Where(p => p.OrgId == t.OrgId && vinList.Contains(p.VIN))
        .Select(p => new { p.VIN, p.FinishDTime, p.ModelCode, p.ColorCode, p.SpecCode }).ToListAsync();
    var models = await db.CarModelStds.Where(m => m.OrgId == t.OrgId).Select(m => new { m.ModelCode, m.ModelName }).ToListAsync();
    var colors = await db.MstCarColors.Where(c => c.OrgId == t.OrgId).Select(c => new { c.ModelCode, c.ColorCode, c.ColorExtName, c.ColorExtNameVN }).ToListAsync();
    var specs = await db.CarSpecs.Where(s => s.OrgId == t.OrgId).Select(s => new { s.SpecCode, s.SpecDesc }).ToListAsync();

    var items = gpsMapVin.Select(g =>
    {
        var r = tblReturn.FirstOrDefault(x => x.VINReal == g.VINReal);         // `left join #tbl_Return`
        var p = pdis.FirstOrDefault(x => x.VIN == g.VINReal);                  // `left join PDI_VIN`
        var m = p is null ? null : models.FirstOrDefault(x => x.ModelCode == p.ModelCode);
        var c = p is null ? null : colors.FirstOrDefault(x => x.ModelCode == p.ModelCode && x.ColorCode == p.ColorCode);
        var s = p is null ? null : specs.FirstOrDefault(x => x.SpecCode == p.SpecCode);
        return new
        {
            gpsDvNo = g.GPSNo,
            vin = g.VINReal,
            finishDTime = p?.FinishDTime,
            // `case when f.GPSNo is null then '' else t.MapDateTime end` — không có GPS ⇒ để TRỐNG.
            mapDateTime = g.GPSNo is null ? null : r?.MapDateTime,
            modelCode = p?.ModelCode, modelName = m?.ModelName,
            colorCode = p?.ColorCode, colorExtName = c?.ColorExtName, colorExtNameVN = c?.ColorExtNameVN,
            specCode = p?.SpecCode,
            specDescription = s?.SpecDesc     // nguồn `Mst_CarSpec.SpecDescription` ↔ MiniHTC `CarSpec.SpecDesc`
        };
    }).ToList();

    return Results.Ok(new
    {
        count = items.Count, items,
        mmsRows = mnf.Count,
        note = items.Count == 0 ? "Không có kết quả nào phù hợp điều kiện tìm kiếm" : null   // Nonsense.MESS_NOTFOUND_RESULT
    });
}).RequireAuthorization();

// ===== Đề nghị giao hồ sơ (ReqInvoice — port 1:1 FrmNewRDInvoice, 2010.HTC/Sales/Redeem) =====
// ⛔ HỢP NHẤT THỰC THỂ SONG TRÙNG (ca thứ 3, #56): `/api/reqinvoices` trước đây ghi vào bộ
// `ReqInvoice`/`ReqInvoiceDtl` RIÊNG, trong khi `/api/redeeminvoicerequests` ghi vào
// `RedeemInvoiceRequest`/`RedeemInvoiceRequestLine` — **cùng bảng nguồn `RD_ReqInvoice`**.
app.MapGet("/api/reqinvoices", async (AppDbContext db, ITenantContext t, string? status) =>
{
    var qy = db.RedeemInvoiceRequests.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) qy = qy.Where(r => r.Status == status);
    var items = await qy.OrderByDescending(r => r.Id).Take(500).Select(r => new
    {
        reqIVNo = r.ReqRDInvoiceNo, r.Status, r.CreatedAt, r.ApprovedDate, r.ApprovedBy,
        cars = db.RedeemInvoiceRequestLines.Count(c => c.OrgId == t.OrgId && c.RequestId == r.Id),
        carsPending = db.RedeemInvoiceRequestLines.Count(c => c.OrgId == t.OrgId && c.RequestId == r.Id && c.RDReqIvDtlStatus == "P"),
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/reqinvoices", async (
    ReqInvoiceDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var cars = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.VIN)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "VIN không để trống." });
    var dupe = cars.GroupBy(c => c.VIN.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });

    var no = "RIV" + DateTime.Now.ToString("yyMMddHHmmss");
    var h = new RedeemInvoiceRequest
    {
        OrgId = t.OrgId, ReqRDInvoiceNo = no, CreatedDate = DateTime.Now, CreatedAt = DateTime.Now,
        VinCount = cars.Count, Status = "P",     // TConst.Stage.Pending (Biz.HTC.WH.cs:127385)
        CreatedBy = user.Identity?.Name ?? "system",
    };
    db.RedeemInvoiceRequests.Add(h); await db.SaveChangesAsync();
    foreach (var c in cars)
        db.RedeemInvoiceRequestLines.Add(new RedeemInvoiceRequestLine
        {
            OrgId = t.OrgId, RequestId = h.Id, VIN = c.VIN.Trim().ToUpperInvariant(),
            RDReqIvDtlStatus = "P",              // nguồn tạo dòng ở Pending (Biz.HTC.WH.cs:127423)
            HTCInvoiceNo = c.HTCInvoiceNo, InvoiceNoFactory = c.InvoiceNoFactory, TCGInvoiceNo = c.TCGInvoiceNo,
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { reqIVNo = h.ReqRDInvoiceNo, cars = cars.Count, status = h.Status, message = "Tạo đề nghị giao hồ sơ thành công" });
}).RequireAuthorization();

app.MapGet("/api/reqinvoices/{no}/cars", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.RedeemInvoiceRequests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ReqRDInvoiceNo.ToUpper() == no);
    if (h is null) return Results.NotFound(new { no });
    var cars = await db.RedeemInvoiceRequestLines.Where(c => c.OrgId == t.OrgId && c.RequestId == h.Id)
        .Select(c => new { c.VIN, c.CarId, typeRDReqIv = c.ReqType, c.RDReqIvDtlStatus, c.DealerCode,
            c.MortageBankCode, c.ApprovedDate, c.ApprovedBy, c.Remark,
            c.HTCInvoiceNo, c.InvoiceNoFactory, c.TCGInvoiceNo }).ToListAsync();
    return Results.Ok(new { reqIVNo = h.ReqRDInvoiceNo, h.Status, count = cars.Count, cars });
}).RequireAuthorization();

// 🔴 DUYỆT GIAO HỒ SƠ THEO TỪNG VIN — đúng chiều nguồn (Biz.HTC.WH.cs:128108-128142).
// Comment nguyên văn của nguồn: "Nếu Dtl đã được duyệt hết thì chuyển trạng thái Mng".
// ⚠️ KHÁC đề nghị giải chấp (#55): ở đây nguồn KHÔNG ghi đè MortageBankCode = "HTC.HO".
app.MapPost("/api/reqinvoices/{no}/approve-vin", async (
    string no, string vin, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var v = (vin ?? "").Trim().ToUpperInvariant();
    if (v.Length == 0) return Results.BadRequest(new { error = "Chưa chọn VIN cần duyệt." });
    var h = await db.RedeemInvoiceRequests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ReqRDInvoiceNo.ToUpper() == no);
    if (h is null) return Results.NotFound(new { no });
    var line = await db.RedeemInvoiceRequestLines
        .FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RequestId == h.Id && x.VIN != null && x.VIN.ToUpper() == v);
    if (line is null) return Results.NotFound(new { no, vin = v });
    if (line.RDReqIvDtlStatus != "P")
        return Results.BadRequest(new { error = $"Dòng VIN {v} đang '{line.RDReqIvDtlStatus}', chỉ duyệt khi 'P'." });

    var actor = user.Identity?.Name ?? "system";
    var now = DateTime.Now;
    line.RDReqIvDtlStatus = "A"; line.ApprovedDate = now; line.ApprovedBy = actor;

    var stillPending = await db.RedeemInvoiceRequestLines
        .CountAsync(x => x.OrgId == t.OrgId && x.RequestId == h.Id && x.RDReqIvDtlStatus == "P" && x.Id != line.Id);
    if (stillPending == 0) { h.Status = "A"; h.ApprovedDate = now; h.ApprovedBy = actor; }

    await db.SaveChangesAsync();
    return Results.Ok(new { reqIVNo = h.ReqRDInvoiceNo, vin = v, lineStatus = line.RDReqIvDtlStatus,
        headerStatus = h.Status, remainingPending = stillPending });
}).RequireAuthorization();

app.MapGet("/api/reqinvoices/statuses", () => Results.Ok(new
{
    statuses = new[] {
        new { code = "P", name = "Chờ duyệt" },
        new { code = "A", name = "Đã duyệt" },
        new { code = "R", name = "Từ chối" } },
    reqTypes = new[] {
        new { code = "DEALER", name = "Đại lý" },
        new { code = "BANKBL", name = "Ngân hàng bảo lãnh" },
        new { code = "BANKLC", name = "Ngân hàng LC" } },
    note = "Header là giá trị DẪN XUẤT: chỉ 'A' khi mọi dòng VIN đã duyệt.",
})).RequireAuthorization();

// ===== Hợp đồng đại lý (DealerContract/DC — port 1:1 FrmNewDC/FrmMngDC, 2010.HTC/Sales/Contract) =====
app.MapGet("/api/dealercontracts", async (AppDbContext db, ITenantContext t, string? status, string? dealer) =>
{
    var q = db.DealerContracts.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(c => c.Status == status);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(c => c.DealerCode == dealer);
    var items = await q.OrderByDescending(c => c.Id).Take(500).Select(c => new
    {
        c.DealerContractNo, c.DealerContractNoUser, c.DealerCode, c.ContractDate, c.TotalAmount, c.Status, c.CreatedAt, c.ApprovedAt,
        c.ApprovedBy, c.Remark, c.ReceiptContractDate,
        cars = db.DealerContractDetails.Count(l => l.OrgId == t.OrgId && l.DealerContractId == c.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/dealercontracts", async (DealerContractDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Cần mã đại lý." });
    var cars = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.CarId)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 xe." });
    var dupe = cars.GroupBy(c => c.CarId.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"Xe {dupe.Key} bị trùng!" });
    var no = string.IsNullOrWhiteSpace(dto.DealerContractNo) ? "DC" + DateTime.Now.ToString("yyMMddHHmmss") : dto.DealerContractNo.Trim();
    if (await db.DealerContracts.AnyAsync(c => c.OrgId == t.OrgId && c.DealerContractNo == no))
        return Results.BadRequest(new { error = $"Số HĐ {no} đã tồn tại!" });
    var total = cars.Sum(c => c.UnitPrice);
    var c2 = new DealerContract { OrgId = t.OrgId, DealerContractNo = no, DealerContractNoUser = dto.DealerContractNoUser, DealerCode = dto.DealerCode.Trim().ToUpperInvariant(), ContractDate = dto.ContractDate, TotalAmount = total, Status = "P" };
    db.DealerContracts.Add(c2); await db.SaveChangesAsync();
    foreach (var c in cars)
        db.DealerContractDetails.Add(new DealerContractDetail { OrgId = t.OrgId, DealerContractId = c2.Id,
            // 🔴 #123 parity: nguồn khoá dòng bằng SỐ hợp đồng (CT_DealerContractDetail.DealerContractNo)
            //    và có trạng thái DÒNG riêng, đặt "P" khi tạo (Biz.HTC.WH.cs:30965-30968).
            DealerContractNo = c2.DealerContractNo, ContractDetailStatus = "P", CarId = c.CarId.Trim().ToUpperInvariant(), UnitPrice = c.UnitPrice });
    await db.SaveChangesAsync();
    return Results.Ok(new { c2.DealerContractNo, cars = cars.Count, total });
}).RequireAuthorization();

app.MapGet("/api/dealercontracts/{no}/cars", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim();
    var c = await db.DealerContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerContractNo == no);
    if (c is null) return Results.NotFound(new { no });
    var cars = await db.DealerContractDetails.Where(l => l.OrgId == t.OrgId && l.DealerContractId == c.Id)
        .Select(l => new { l.DealerContractNo, l.CarId, l.UnitPrice, l.ContractDetailStatus }).ToListAsync();
    return Results.Ok(new { c.DealerContractNo, c.DealerCode, c.TotalAmount, c.Status, count = cars.Count, cars });
}).RequireAuthorization();

// 🔴 DUYỆT / TỪ CHỐI / HUỶ — `ContractDealerContractApprove_New201811119` (Biz.HTC.WH.cs:31068) và
// `ContractDealerContractCancel_New20181119` (31350).
// ⚠️ **Guard KHÁC NHAU giữa hai hành động** (đúng nguồn, không sắp lại cho "hợp lý"):
//    · duyệt/từ chối vào từ **"P"** → "A" / "R";
//    · **HUỶ vào từ "A"** → "C" — tức chỉ huỷ được hợp đồng **ĐÃ DUYỆT**, không huỷ hợp đồng đang chờ.
// ⚠️ Cả hai đều ghi `Remark` và **dùng CHUNG cặp cột** `ApprovedDate`/`ApprovedBy` (kể cả khi huỷ).
// ⚠️ Nguồn còn cho **sửa `DealerContractNoUser` và `ContractDate` ngay trong bước duyệt**.
app.MapPost("/api/dealercontracts/{no}/{action}", async (string no, string action, DealerContractActionDto? dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (action is not ("approve" or "reject" or "cancel")) return Results.BadRequest(new { error = "action = approve|reject|cancel" });
    no = no.Trim();
    var c = await db.DealerContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerContractNo == no);
    if (c is null) return Results.NotFound(new { no });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    if (action == "cancel")
    {
        if (c.Status != "A") return Results.BadRequest(new { error = "Chỉ huỷ được hợp đồng đã duyệt (A)." });
        c.Status = "C";
    }
    else
    {
        if (c.Status != "P") return Results.BadRequest(new { error = "Chỉ duyệt/từ chối hợp đồng đang chờ duyệt (P)." });
        c.Status = action == "approve" ? "A" : "R";
        // Nguồn cho sửa hai trường này ngay lúc duyệt.
        if (!string.IsNullOrWhiteSpace(dto?.DealerContractNoUser)) c.DealerContractNoUser = dto!.DealerContractNoUser!.Trim();
        if (dto?.ContractDate is not null) c.ContractDate = dto.ContractDate;
    }
    c.Remark = dto?.Remark; c.ApprovedAt = now; c.ApprovedBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { c.DealerContractNo, status = c.Status });
}).RequireAuthorization();

// 🔴 CẬP NHẬT NGÀY NHẬN HỢP ĐỒNG — `ContractDealerContractUpdate_New20181119` (31556).
// Guard trạng thái **"A,P,F"** — chấp nhận cả **"F"**, trạng thái mà port cũ không hề có;
// và **KHÔNG** cho sửa khi hợp đồng đã huỷ ("C").
app.MapPost("/api/dealercontracts/{no}/receipt", async (string no, DealerContractReceiptDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim();
    var c = await db.DealerContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerContractNo == no);
    if (c is null) return Results.NotFound(new { no });
    if (c.Status is not ("A" or "P" or "F"))
        return Results.BadRequest(new { error = $"Hợp đồng ở trạng thái '{c.Status}' — chỉ cập nhật được khi P, A hoặc F." });
    c.ReceiptContractDate = dto.ReceiptContractDate;
    await db.SaveChangesAsync();
    return Results.Ok(new { c.DealerContractNo, c.ReceiptContractDate, status = c.Status });
}).RequireAuthorization();

// ===== Hợp đồng đại lý DMS40 ký 2 bên (DmsDealerContract — port 1:1 FrmDMS40_CT_DealerContractHTC_New, 2010.HTC/Sales/DMS40) =====
app.MapGet("/api/dmsdealercontracts", async (AppDbContext db, ITenantContext t, string? status, string? dealer) =>
{
    var q = db.DmsDealerContracts.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(c => c.DlrCtrStatus == status);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(c => c.DealerCode == dealer);
    var items = await q.OrderByDescending(c => c.Id).Take(500)
        .Select(c => new { c.DlrCtrNo, c.DealerCode, c.ContractDate, c.DlrSignStatus, c.HTCSignStatus, c.DlrCtrStatus, c.CreatedAt, c.DlrApprDTime, c.HTCAppr2DTime, c.BankCodeMD, c.FlagDlrCtrAdjust, c.DlrCtrNoParent,
            c.HTCAppr1DTime, c.HTCAppr1By, c.HTCAppr2By, c.DlrApprBy, c.RejectDTime, c.RejectBy, c.FilePath, c.Remark, c.LogLUDateTime, c.LogLUBy,
            c.DCPType, c.TotalAmount, c.CreateDTime, c.CreateBy, c.LUDTime, c.LUBy,
            c.PMTermNo, c.DepositPercent, c.GuaranteePercent, c.GuaranteeDays, c.DepositDutyEndDays, c.GuaranteeEndDays,
            lines = db.DmsDealerContractDtls.Count(l => l.OrgId == t.OrgId && l.DlrCtrNo == c.DlrCtrNo) }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Chọn ngân hàng phát hành bảo lãnh MD (port 1:1 FrmDMS40_SelectedBankMD btnApply_Click) — chỉ khi chưa chọn NH (BankCodeMD rỗng).
// #164: đọc dòng hợp đồng đại lý DMS40 (`DMS40_CT_DealerContractDetail`).
app.MapGet("/api/dmsdealercontracts/{no}/lines", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim();
    var c = await db.DmsDealerContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrCtrNo == no);
    if (c is null) return Results.NotFound(new { no });
    var lines = await db.DmsDealerContractDtls.Where(l => l.OrgId == t.OrgId && l.DlrCtrNo == no)
        .Select(l => new { l.CarId, l.OriginNo, l.ProductionYear, l.UnitPrice, l.ApprovedDate,
            l.DlrCtrStatusDtl, l.FlagDepositPmt, l.Remark, l.LogLUDateTime, l.LogLUBy }).ToListAsync();
    // Hiện luôn dấu vết mà bước duyệt cấp 2 để lại TRÊN XE (`Car_Car.FlagDealerContractDMS40`/`DlrCtrNo`).
    var carIds = lines.Select(l => l.CarId).ToList();
    var cars = await db.CarVinMasters.Where(v => v.OrgId == t.OrgId && carIds.Contains(v.VIN))
        .Select(v => new { v.VIN, v.DlrCtrNo, v.FlagDealerContractDMS40, v.LogLUDateTime, v.LogLUBy }).ToListAsync();
    return Results.Ok(new { c.DlrCtrNo, c.DlrCtrStatus, c.HTCSignStatus, c.DlrSignStatus, c.DlrApprDTime, c.DlrApprBy, c.FilePath, c.Remark, count = lines.Count, lines, cars });
}).RequireAuthorization();

// ===== #184 SỬA hợp đồng đại lý DMS40 — `DMS40_CT_DealerContract_Update_New20200130` =====
// Nguồn: `TERP.BizHTC/DMS40/0.34.Contract.cs:3486` (csproj 125).
// BƯỚC 3B: md5 CẢ FILE `e2f3680f` KHỚP 2 máy. TWIN: có ở CẢ HAI bit, cùng bản `_New20200130`.
// Đã liệt kê ranh giới hàm trước khi đọc: 3486 → 3783 (hàm kế tiếp `_UpdateBankCodeMDAndSendMail` ở 3784).
//
// 🔴 Cách tìm ra: biến mô-tip field-mask (#183) thành phép quét — `grep -rl "Ft_Cols_Upd"` toàn biz ra
//    **36 hàm** dùng cơ chế này. Đây là hàm thứ hai được port, và là lệnh còn thiếu của cụm
//    `DMS40_CT_DealerContract` (bề mặt WS 16 lệnh, #164–#166 đã đóng 6 cặp `_X`/`_XAdjust`).
//
// 🔴 FIELD-MASK với **HAI** cột (khác #183 chỉ một):
//    `bUpd_BankCodeMD = mask.Contains("DMS40_CT_DealerContract.BankCodeMD".ToUpper())`
//    `bUpd_FilePath   = mask.Contains("DMS40_CT_DealerContract.FilePath".ToUpper())`
//    Chỉ cột có trong mask mới vào `alColumnEffective`; `LogLUDateTime`/`LogLUBy` **luôn** được ghi.
//
// 🔴 GUARD THEO CỘT — chỉ chạy khi `bUpd_BankCodeMD`, gồm BỐN lớp:
//    1. `CheckDB(..., DlrSignStatus=Approved, HTCSignStatus=Approved2, DlrCtrStatus=Signed)`
//       ⇒ chỉ gán ngân hàng bảo lãnh MD cho hợp đồng **đã ký đủ hai bên và đã ở trạng thái Đã ký**;
//    2. `Update_InvalidExistBankCodeMD` — hợp đồng **đã có** `BankCodeMD` thì CHẶN
//       (muốn đổi phải qua biên bản huỷ NH bảo lãnh, xem #182);
//    3. `Mst_BankDealer_CheckDB(..., FlagActive, FlagBankGrt)` — ngân hàng phải tồn tại, còn hoạt động
//       và **được phép bảo lãnh**;
//    4. `Update_ExistCancelMinutesNoNotCancel` — nếu hợp đồng còn **biên bản huỷ chưa ở trạng thái huỷ**
//       thì CHẶN (không gán NH mới khi tiến trình huỷ đang dở).
//    ⇒ Nhánh `bUpd_FilePath` KHÔNG có guard nào — sửa file lúc nào cũng được.
app.MapPost("/api/dmsdealercontracts/{no}/update", async (string no, DealerContractUpdateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim();
    var c = await db.DmsDealerContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrCtrNo == no);
    if (c is null) return Results.NotFound(new { no });

    var mask = (dto.FtColsUpd ?? "").ToUpperInvariant();
    var updBank = mask.Contains("DMS40_CT_DEALERCONTRACT.BANKCODEMD");
    var updFile = mask.Contains("DMS40_CT_DEALERCONTRACT.FILEPATH");

    if (updBank)
    {
        // (1) ba trục phải đủ
        if (c.DlrSignStatus != "A" || c.HTCSignStatus != "A2" || c.DlrCtrStatus != "S")
            return Results.BadRequest(new { error = $"Chỉ gán ngân hàng bảo lãnh MD cho hợp đồng đã ký đủ (đang: đại lý '{c.DlrSignStatus}', bên A '{c.HTCSignStatus}', hợp đồng '{c.DlrCtrStatus}')." });
        // (2) đã có NH thì chặn — muốn đổi phải qua biên bản huỷ NH bảo lãnh
        if (!string.IsNullOrWhiteSpace(c.BankCodeMD))
            return Results.BadRequest(new { error = $"Hợp đồng đã có ngân hàng bảo lãnh '{c.BankCodeMD}' — muốn đổi phải lập biên bản huỷ NH bảo lãnh trước.", bankCodeMD = c.BankCodeMD });
        // (3) ngân hàng phải tồn tại, còn hoạt động và ĐƯỢC PHÉP BẢO LÃNH
        var bank = (dto.BankCodeMD ?? "").Trim().ToUpperInvariant();
        if (bank.Length == 0) return Results.BadRequest(new { error = "Chưa chọn ngân hàng bảo lãnh MD." });
        var bd = await db.DealerBanks.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.BankCode == bank && x.DealerCode == c.DealerCode);
        if (bd is null) return Results.BadRequest(new { error = $"Ngân hàng {bank} không thuộc danh sách của đại lý {c.DealerCode}.", bankCode = bank });
        if (bd.FlagActive != "1") return Results.BadRequest(new { error = $"Ngân hàng {bank} đã ngừng hoạt động.", bankCode = bank });
        if (bd.FlagBankGrt != "1") return Results.BadRequest(new { error = $"Ngân hàng {bank} không được phép bảo lãnh.", bankCode = bank });
        // (4) còn biên bản huỷ NH chưa ở trạng thái huỷ ⇒ chặn
        var pending = await db.DmsCancelMinutesSet
            .Where(x => x.OrgId == t.OrgId && x.DlrCtrNo == no && x.CancelMinutesStatus != "C")
            .Select(x => new { x.CancelMinutesNo, x.CancelMinutesStatus }).FirstOrDefaultAsync();
        if (pending is not null)
            return Results.BadRequest(new { error = $"Còn biên bản huỷ {pending.CancelMinutesNo} ở trạng thái '{pending.CancelMinutesStatus}' — chưa gán ngân hàng mới được.", cancelMinutesNo = pending.CancelMinutesNo });
    }

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    if (updFile) c.FilePath = (dto.FilePath ?? "").Trim();      // nhánh này KHÔNG có guard, đúng nguồn
    if (updBank) c.BankCodeMD = (dto.BankCodeMD ?? "").Trim().ToUpperInvariant();
    c.LogLUDateTime = now; c.LogLUBy = who;                     // luôn ghi, kể cả mask rỗng
    await db.SaveChangesAsync();
    return Results.Ok(new { c.DlrCtrNo, updatedBankCodeMD = updBank, updatedFilePath = updFile,
        c.BankCodeMD, c.FilePath, c.LogLUDateTime, c.LogLUBy });
}).RequireAuthorization();

app.MapPost("/api/dmsdealercontracts/{no}/selectbankmd", async (string no, DmsSelectBankMDDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim();
    var c = await db.DmsDealerContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrCtrNo == no);
    if (c is null) return Results.NotFound(new { no });
    if (string.IsNullOrWhiteSpace(dto.BankCodeMD)) return Results.BadRequest(new { error = "Chưa chọn ngân hàng phát hành bảo lãnh!" });
    if (!string.IsNullOrWhiteSpace(c.BankCodeMD)) return Results.BadRequest(new { error = "HĐ đã có ngân hàng phát hành bảo lãnh, hãy dùng chức năng Hủy NH trước." });
    c.BankCodeMD = dto.BankCodeMD.Trim().ToUpperInvariant();
    c.FlagDlrCtrAdjust = dto.FlagDlrCtrAdjust == "1" ? "1" : "0";
    await db.SaveChangesAsync();
    return Results.Ok(new { c.DlrCtrNo, c.BankCodeMD, c.FlagDlrCtrAdjust });
}).RequireAuthorization();

// ===== #166 lưu hợp đồng đại lý DMS40 — `DMS40_CT_DealerContract_SaveX_New20190404` =====
// Nguồn: `TERP.BizHTC/DMS40/0.34.Contract.cs:1442` (csproj 125) — BƯỚC 3B: md5 CẢ FILE `e2f3680f` KHỚP 2 máy.
// Đây là hàm **UPSERT + XOÁ trong một** (`objFlagIsDelete`), hoàn tất nốt cặp `_Save`/`_SaveAdjust`
// — cặp thứ 6 và cuối cùng của cụm `DMS40_CT_DealerContract` (xem #164/#165).
app.MapPost("/api/dmsdealercontracts", async (DmsDealerContractDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var no = string.IsNullOrWhiteSpace(dto.DlrCtrNo) ? "DLC40" + now.ToString("yyMMddHHmmss") : dto.DlrCtrNo!.Trim();
    var existing = await db.DmsDealerContracts.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.DlrCtrNo == no);

    // ---- nhánh XOÁ: nguồn `if (rows < 1 && bIsDelete) goto Done` ⇒ xoá cái không có là THÀNH CÔNG (idempotent).
    if (dto.FlagIsDelete)
    {
        if (existing is null) return Results.Ok(new { DlrCtrNo = no, deleted = 0, note = "Không tồn tại — nguồn coi là thành công." });
        var dead = await db.DmsDealerContractDtls.Where(l => l.OrgId == t.OrgId && l.DlrCtrNo == no).ToListAsync();
        db.DmsDealerContractDtls.RemoveRange(dead);
        db.DmsDealerContracts.Remove(existing);
        await db.SaveChangesAsync();
        return Results.Ok(new { DlrCtrNo = no, deleted = 1, lines = dead.Count });
    }

    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Cần mã đại lý." });
    var dealerCode = dto.DealerCode.Trim().ToUpperInvariant();

    // 🔴 Guard "chỉ sửa được khi CHƯA ai ký" — nguồn viết `!(DlrSignStatus == P) && !(DlrCtrStatus == NS)`.
    // ⚠️ Đây là **VÀ**, không phải HOẶC: nguồn chỉ chặn khi CẢ HAI đều lệch. Giữ nguyên đúng nguồn
    //    (cùng tinh thần `CKTT` ở #163: không "sửa cho hợp lý" một luật của nghiệp vụ), có ghi chú.
    if (existing is not null && existing.DlrSignStatus != "P" && existing.DlrCtrStatus != "NS")
        return Results.BadRequest(new { error = $"Hợp đồng đang ở DlrSignStatus='{existing.DlrSignStatus}', DlrCtrStatus='{existing.DlrCtrStatus}' — không sửa được." });

    // `myCommon_CheckDealer(..., Active, Active)`
    var dlr = await db.Dealers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == dealerCode);
    if (dlr is null) return Results.BadRequest(new { error = $"Đại lý {dealerCode} không tồn tại." });
    if (dlr.FlagActive != "1") return Results.BadRequest(new { error = $"Đại lý {dealerCode} đang ngừng hoạt động." });

    // `DlrCtr_PaymentType_CheckDB(strDCPType, Active, Active)` — loại điều khoản thanh toán PHẢI có và còn hiệu lực.
    var dcp = (dto.DCPType ?? "").Trim().ToUpperInvariant();
    if (dcp.Length == 0) return Results.BadRequest(new { error = "Chưa chọn loại điều khoản thanh toán (DCPType)." });
    var dcpRow = await db.PaymentTermMsts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DCPType == dcp);
    if (dcpRow is null) return Results.BadRequest(new { error = $"Loại điều khoản thanh toán '{dcp}' không tồn tại." });
    if (dcpRow.FlagActive != "1") return Results.BadRequest(new { error = $"Loại điều khoản thanh toán '{dcp}' đã ngừng hiệu lực." });

    var dtlIn = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.CarId)).ToList();
    // Nguồn ném `..._Input_DMS40_CT_DealerContractDetailTblNotFound` khi thiếu bảng dòng.
    if (dtlIn.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 xe trong hợp đồng." });

    // ---- Kiểm TỪNG XE + rút bộ điều khoản thanh toán ----
    string? pmTermNo = null; PaymentTerm? pmTerm = null;
    var built = new List<DmsDealerContractDtl>();
    foreach (var l in dtlIn)
    {
        var carId = l.CarId!.Trim().ToUpperInvariant();
        // `myCar_CheckCar(..., strDealerCodeToCheck: DealerCode của user)` — xe phải TỒN TẠI và thuộc ĐÚNG đại lý đó.
        // ⚠️ Hai vế còn lại của guard nguồn (`FlagActive` và `PaymentStatus ∈ {P,A,F}`) chưa có cột trong
        //    `CarVinMaster` ⇒ **ĐÃ GHI NỢ**, không bịa.
        var car = await db.CarVinMasters.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.VIN == carId);
        if (car is null) return Results.BadRequest(new { error = $"Xe {carId} không tồn tại.", carId });
        if (!string.IsNullOrWhiteSpace(car.DealerCode) && car.DealerCode != dealerCode)
            return Results.BadRequest(new { error = $"Xe {carId} thuộc đại lý {car.DealerCode}, không phải {dealerCode}.", carId });

        // 🔴 Xe ĐÃ nằm trong một hợp đồng đại lý khác:
        //    · `FlagDealerContractDMS40 = "0"` ⇒ LỖI `ExistDlrCtrNo` (hợp đồng cũ chưa DMS40-hoá, chặn thẳng);
        //    · `= "1"` ⇒ chỉ cho dùng lại khi hợp đồng cũ **đã HUỶ** (`DlrCtrStatus = "C"`).
        if (!string.IsNullOrWhiteSpace(car.DlrCtrNo) && car.DlrCtrNo != no)
        {
            if (car.FlagDealerContractDMS40 != "1")
                return Results.BadRequest(new { error = $"Xe {carId} đã thuộc hợp đồng {car.DlrCtrNo}.", carId });
            var old = await db.DmsDealerContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrCtrNo == car.DlrCtrNo);
            if (old is not null && old.DlrCtrStatus != "C")
                return Results.BadRequest(new { error = $"Xe {carId} đang thuộc hợp đồng {car.DlrCtrNo} (trạng thái '{old.DlrCtrStatus}') — chỉ dùng lại được khi hợp đồng đó đã huỷ (C).", carId });
        }

        // `Ord_SalesOrderDetail_CheckDB(CarId, exist)` — xe phải đã map vào một dòng đơn bán.
        var soLine = await db.SalesOrderLines.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CarId == carId);
        if (soLine is null) return Results.BadRequest(new { error = $"Xe {carId} chưa có dòng đơn bán (Ord_SalesOrderDetail).", carId });

        // `Mst_PaymentTerm_CheckSpecCode(SpecCode, EffectiveDate = ApprovedDate của DÒNG SO)` — phải ra ĐÚNG MỘT dòng.
        var eff = soLine.ApprovedDate ?? now;
        var terms = await db.PaymentTerms.Where(x => x.OrgId == t.OrgId && x.SpecCode == car.SpecCode && x.FlagActive == "1"
                && x.EffectiveDateFrom <= eff && (x.EffectiveDateTo == null || x.EffectiveDateTo >= eff)).ToListAsync();
        if (terms.Count != 1)
            return Results.BadRequest(new { error = $"Xe {carId} (spec {car.SpecCode}): tìm thấy {terms.Count} điều khoản thanh toán hiệu lực ngày {eff:yyyy-MM-dd} — nguồn đòi đúng 1.", carId });
        var term = terms[0];

        // 🔴 MỌI XE trong hợp đồng phải CÙNG một `PMTermNo` (lỗi `PaymentTermNotMatch`):
        //    xe đầu tiên ấn định bộ điều khoản, xe sau lệch là chặn.
        if (pmTermNo is null) { pmTermNo = term.PMTermNo; pmTerm = term; }
        else if (pmTermNo != term.PMTermNo)
            return Results.BadRequest(new { error = $"Xe {carId} có điều khoản '{term.PMTermNo}', khác điều khoản '{pmTermNo}' của các xe trước — hợp đồng phải thuần nhất.", carId });

        built.Add(new DmsDealerContractDtl { OrgId = t.OrgId, DlrCtrNo = no, CarId = carId,
            OriginNo = l.OriginNo, ProductionYear = l.ProductionYear, UnitPrice = l.UnitPrice,
            // `drScan["ApprovedDate"]` lấy từ **dòng SO**, KHÔNG phải ngày hệ thống (nguồn có comment đã đổi).
            ApprovedDate = soLine.ApprovedDate,
            DlrCtrStatusDtl = "NS",
            FlagDepositPmt = term.FlagDepositPmt,   // chép từ điều khoản, không lấy input
            Remark = (l.Remark ?? "").Trim(),
            LogLUDateTime = now, LogLUBy = who });
    }

    var c = existing ?? new DmsDealerContract { OrgId = t.OrgId, DlrCtrNo = no };
    c.DealerCode = dealerCode;
    c.DCPType = dcp;
    // Nguồn KHÔNG lấy ngày hợp đồng từ input: `ContractDate = dtimeSys`, `TotalAmount = 0.0`.
    c.ContractDate = now.Date;
    c.TotalAmount = 0m;
    c.BankCodeMD = null; c.FilePath = null;
    c.DlrApprDTime = null; c.DlrApprBy = null;
    c.HTCAppr1DTime = null; c.HTCAppr1By = null;
    c.HTCAppr2DTime = null; c.HTCAppr2By = null;
    c.RejectDTime = null; c.RejectBy = null;
    c.FlagDlrCtrAdjust = "0"; c.DlrSignStatus = "P"; c.HTCSignStatus = "P"; c.DlrCtrStatus = "NS";
    c.Remark = (dto.Remark ?? "").Trim();
    // 🔴 CreateDTime/CreateBy: GIỮ NGUYÊN của bản ghi cũ khi lưu đè, chỉ điền mới khi chưa có.
    c.CreateDTime ??= now; c.CreateBy ??= who;
    c.LUDTime = now; c.LUBy = who;
    // Bộ SÁU cột điều khoản chép từ điều khoản của xe đầu tiên (sau khi đã bắt mọi xe thuần nhất).
    c.PMTermNo = pmTermNo;
    c.DepositPercent = pmTerm?.DepositPercent; c.GuaranteePercent = pmTerm?.GuaranteePercent;
    c.GuaranteeDays = pmTerm?.GuaranteeDays; c.DepositDutyEndDays = pmTerm?.DepositDutyEndDays;
    c.GuaranteeEndDays = pmTerm?.GuaranteeEndDays;
    c.LogLUDateTime = now; c.LogLUBy = who;
    if (existing is null) db.DmsDealerContracts.Add(c);

    // Lưu đè ⇒ thay trọn bộ dòng (nguồn dựng lại `#input` rồi merge theo DlrCtrNo).
    var oldDtls = await db.DmsDealerContractDtls.Where(l => l.OrgId == t.OrgId && l.DlrCtrNo == no).ToListAsync();
    if (oldDtls.Count > 0) db.DmsDealerContractDtls.RemoveRange(oldDtls);
    db.DmsDealerContractDtls.AddRange(built);
    await db.SaveChangesAsync();
    return Results.Ok(new { c.DlrCtrNo, c.DealerCode, c.DCPType, c.ContractDate, c.TotalAmount,
        c.PMTermNo, c.DepositPercent, c.GuaranteePercent, c.GuaranteeDays, c.DepositDutyEndDays, c.GuaranteeEndDays,
        c.CreateDTime, c.CreateBy, c.LUDTime, c.LUBy, lines = built.Count });
}).RequireAuthorization();

// 🔴 TẠO HỢP ĐỒNG ĐIỀU CHỈNH — `DMS40_CT_DealerContract_SaveAdjust_New20181115` (0.34.Contract.cs:2410).
// Sinh một hợp đồng MỚI trỏ về hợp đồng gốc qua `DlrCtrNoParent`, cờ `FlagDlrCtrAdjust = "1"`,
// hai trục ký quay lại "P" và trạng thái "NS". Hợp đồng gốc **chưa** đổi ở bước này —
// nó chỉ thành **"AJ"** khi đại lý duyệt bản điều chỉnh.
// ⚠️ Nguồn sinh số bằng `SequenceGetForDlrCtrNoAdjust_New20190523` (tách số gốc theo "/" rồi lấy
//    sequence từ DB). MiniHTC chưa có bảng sequence ⇒ dùng quy ước `<số gốc>/ĐC<n>` — **đã ghi nợ**.
app.MapPost("/api/dmsdealercontracts/{no}/adjust", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim();
    var parent = await db.DmsDealerContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrCtrNo == no);
    if (parent is null) return Results.NotFound(new { no });
    if (parent.DlrCtrStatus == "C") return Results.BadRequest(new { error = "Hợp đồng đã huỷ — không điều chỉnh được." });
    if (parent.DlrCtrStatus == "AJ") return Results.BadRequest(new { error = "Hợp đồng đã có bản điều chỉnh." });
    var seq = await db.DmsDealerContracts.CountAsync(x => x.OrgId == t.OrgId && x.DlrCtrNoParent == no) + 1;
    var newNo = no + "/ĐC" + seq;
    if (await db.DmsDealerContracts.AnyAsync(x => x.OrgId == t.OrgId && x.DlrCtrNo == newNo))
        return Results.BadRequest(new { error = $"Số hợp đồng điều chỉnh {newNo} đã tồn tại!" });
    var adj = new DmsDealerContract
    {
        OrgId = t.OrgId, DlrCtrNo = newNo, DlrCtrNoParent = parent.DlrCtrNo,
        DealerCode = parent.DealerCode, ContractDate = DateTime.Now,
        DlrSignStatus = "P", HTCSignStatus = "P", DlrCtrStatus = "NS",
        FlagDlrCtrAdjust = "1", BankCodeMD = parent.BankCodeMD,
    };
    db.DmsDealerContracts.Add(adj);
    await db.SaveChangesAsync();
    return Results.Ok(new { adj.DlrCtrNo, adj.DlrCtrNoParent, status = adj.DlrCtrStatus, adj.FlagDlrCtrAdjust });
}).RequireAuthorization();

// 🔴 ĐẠI LÝ (bên B) DUYỆT — `DMS40_CT_DealerContract_DlrApprove_New20190531` (0.34.Contract.cs:4069):
// gán `DlrSignStatus = TConst.DlrSignStatus.**Approved** ("A")` — KHÔNG phải "S" như port cũ.
// ===== #165 bên B (đại lý) duyệt hợp đồng — BA lệnh WS, KHÔNG phải một =====
// Nguồn: `TERP.BizHTC/DMS40/0.34.Contract.cs` (csproj 125), md5 cả file `e2f3680f` **KHỚP 2 máy**:
//   · `_DlrApprove_New20190531`                  (4069) — hợp đồng THƯỜNG
//   · `_DlrApproveAdjust_New20181115`            (4410) — hợp đồng ĐIỀU CHỈNH
//   · `_DlrApproveAdjustAndSendMail_New20190529` (4743) — điều chỉnh + gửi mail
//
// 🔴 Port cũ phân biệt hai luồng bằng "có `DlrCtrNoParent` hay không" — **SAI TRỤC**. Nguồn phân biệt
//    bằng cờ `FlagDlrCtrAdjust` (`strFlagDlrCtrAdjustListToCheck`: Inactive vs Active), và hai bản còn
//    **khác nhau ở guard `HTCSignStatus`** — trục mà port cũ **không kiểm gì cả**:
//      · THƯỜNG      → `HTCSignStatus = "P"`  (bên B ký TRƯỚC, bên A duyệt SAU)
//      · ĐIỀU CHỈNH  → `HTCSignStatus = "A2"` (bên A đã duyệt cấp 2 rồi bên B mới ký)
//    ⇒ khớp đúng cặp đối lập đã phát hiện ở #164, nhìn từ phía bên B.
// ⚠️ Cả ba đều KHÔNG gọi `myCommon_CheckHTCDirect` (dòng đó bị comment trong nguồn) — hợp lý vì
//    đây là thao tác của ĐẠI LÝ, không phải của HTC. Giữ nguyên, không tự thêm RBAC.
app.MapPost("/api/dmsdealercontracts/{no}/dlr-approve", async (string no, DmsDlrApproveDto? dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim();
    var c = await db.DmsDealerContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrCtrNo == no);
    if (c is null) return Results.NotFound(new { no });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;

    // Ba guard chung của cả ba bản: đại lý còn chờ, hợp đồng chưa ký.
    if (c.DlrSignStatus != "P") return Results.BadRequest(new { error = $"Bên B đang ở trạng thái '{c.DlrSignStatus}' — chỉ duyệt khi đang chờ (P)." });
    if (c.DlrCtrStatus != "NS") return Results.BadRequest(new { error = $"Hợp đồng đang ở '{c.DlrCtrStatus}' — bên B chỉ ký khi chưa ký (NS)." });

    var isAdjust = c.FlagDlrCtrAdjust == "1";
    if (!isAdjust && c.HTCSignStatus != "P")
        return Results.BadRequest(new { error = $"Bên A đang ở '{c.HTCSignStatus}' — hợp đồng thường thì bên B ký khi bên A còn chờ (P)." });
    if (isAdjust && c.HTCSignStatus != "A2")
        return Results.BadRequest(new { error = $"Bên A đang ở '{c.HTCSignStatus}' — hợp đồng điều chỉnh thì bên B chỉ ký SAU khi bên A duyệt cấp 2 (A2)." });

    c.DlrSignStatus = "A"; c.DlrApprDTime = now; c.DlrApprBy = who;
    // Nguồn upload file hợp đồng vào `Contracts_Temp` rồi MOVE sang `Contracts` và ghi lại đường dẫn ĐÍCH.
    // MiniHTC chưa có tầng lưu file ⇒ nhận sẵn đường dẫn — **đã ghi nợ** (cùng món nợ #164).
    if (!string.IsNullOrWhiteSpace(dto?.FilePath)) c.FilePath = dto!.FilePath!.Trim();

    var dtls = await db.DmsDealerContractDtls.Where(l => l.OrgId == t.OrgId && l.DlrCtrNo == c.DlrCtrNo).ToListAsync();
    string? parentMarked = null;

    if (!isAdjust)
    {
        // Bản THƯỜNG: **KHÔNG đổi `DlrCtrStatus`** (hợp đồng vẫn "NS" chờ bên A duyệt).
        //   Dòng nhận `DlrCtrStatusDtl = f.DlrSignStatus` ⇒ "A", LogLU lấy từ `DlrAppr*`.
        foreach (var l in dtls) { l.DlrCtrStatusDtl = c.DlrSignStatus; l.LogLUDateTime = now; l.LogLUBy = who; }
    }
    else
    {
        // Bản ĐIỀU CHỈNH: bên B ký là bước CUỐI ⇒ hợp đồng con chuyển thẳng sang **"S" (đã ký)**,
        //   và nguồn chạy **BỐN** câu update: header con · header GỐC · dòng con · dòng GỐC.
        c.DlrCtrStatus = "S";
        c.Remark = dto?.Remark;
        foreach (var l in dtls) { l.DlrCtrStatusDtl = c.DlrCtrStatus; l.LogLUDateTime = now; l.LogLUBy = who; }

        if (!string.IsNullOrWhiteSpace(c.DlrCtrNoParent))
        {
            var parent = await db.DmsDealerContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrCtrNo == c.DlrCtrNoParent);
            if (parent is null)
                return Results.BadRequest(new { error = $"Không tìm thấy hợp đồng gốc {c.DlrCtrNoParent}." });
            // `on t.DlrCtrNo = f.DlrCtrNoParent` ⇒ hợp đồng GỐC bị đánh **"AJ" (đã điều chỉnh)**.
            parent.DlrCtrStatus = "AJ"; parent.LogLUDateTime = now; parent.LogLUBy = who;
            parentMarked = parent.DlrCtrNo;
            // Câu update thứ TƯ: dòng của hợp đồng GỐC cũng nhận "AJ" — port cũ bỏ hẳn.
            var pDtls = await db.DmsDealerContractDtls.Where(l => l.OrgId == t.OrgId && l.DlrCtrNo == parent.DlrCtrNo).ToListAsync();
            foreach (var l in pDtls) { l.DlrCtrStatusDtl = "AJ"; l.LogLUDateTime = now; l.LogLUBy = who; }

            // Bản `AndSendMail` chỉ khác bản `Adjust` ở HAI điểm: (1) CheckDB **lần hai** trên hợp đồng
            // GỐC để lấy `BankCodeMD` của bản gốc; (2) gọi `DMS40_Email_BatchSendEmail_SendForDealerContractDlrApproveAdjustX`.
            // ⇒ ở đây chỉ port điểm (1); việc gửi mail thật **ghi nợ**.
            if (dto?.SendMail == true && string.IsNullOrWhiteSpace(parent.BankCodeMD))
                return Results.BadRequest(new { error = $"Hợp đồng gốc {parent.DlrCtrNo} chưa có ngân hàng bảo lãnh MD — không gửi thông báo được." });
        }
    }

    c.LogLUDateTime = now; c.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { c.DlrCtrNo, c.DlrSignStatus, c.DlrCtrStatus, c.DlrApprDTime, c.DlrApprBy,
        adjust = isAdjust, parentAdjusted = parentMarked, lines = dtls.Count,
        mailQueued = dto?.SendMail == true ? "NỢ: chưa nối tầng gửi mail thật" : null });
}).RequireAuthorization();

// 🔴 HTC (bên A) duyệt **HAI CẤP** — `_HTCApprove1Adjust` (5748) rồi `_HTCApprove2Adjust` (5870),
// và `_HTCRejectAdjust` (6548). Cấp 2 guard `HTCSignStatus = "A1"` **VÀ** `DlrCtrStatus = "NS"`,
// sau khi duyệt vẫn **giữ `DlrCtrStatus = "NS"`** — port cũ tự suy "hai bên ký ⇒ Signed" là SAI.
app.MapPost("/api/dmsdealercontracts/{no}/htc-approve", async (string no, DmsHtcApproveDto? dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim();
    var c = await db.DmsDealerContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrCtrNo == no);
    if (c is null) return Results.NotFound(new { no });
    if (c.DlrCtrStatus == "C") return Results.BadRequest(new { error = "Hợp đồng đã huỷ." });
    var level = dto?.Level ?? 1;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;

    // ===== #164 họ hàm KHÔNG-điều-chỉnh =====
    // 🔴 SỬA KẾT LUẬN SAI của lượt trước ("Nguồn KHÔNG có bản không-Adjust"). Bề mặt WS 64-bit
    //    (`WSHTC.asmx.cs`) liệt kê **HAI HỌ SONG SONG**, mỗi thao tác có đúng hai bản:
    //      `_HTCApprove1_New20181115`   ·  `_HTCApprove1Adjust_New20181115`
    //      `_HTCApprove2_New20190531`   ·  `_HTCApprove2Adjust_New20190531`
    //      `_HTCReject_New20181115`     ·  `_HTCRejectAdjust_New20181115`
    //    Thân bản thường ở `DMS40/zTemp.0.34.Contract.cs` (318 · 769 · 1115), csproj 129.
    //    BƯỚC 3B: `_HTCApprove2X_New20190531` bắt đầu **cùng dòng 769 ở CẢ HAI máy**, md5 `4ffbda55` KHỚP.
    //
    // 🔴 HAI HỌ ĐỐI LẬP NHAU Ở TRỤC "ĐẠI LÝ ĐÃ KÝ CHƯA":
    //    · hợp đồng THƯỜNG (`FlagDlrCtrAdjust = "0"`) → guard `DlrSignStatus = **"A"**` (đại lý ký TRƯỚC, bên A duyệt SAU);
    //    · hợp đồng ĐIỀU CHỈNH (`= "1"`)              → guard `DlrSignStatus = **"P"**` (bên A duyệt TRƯỚC).
    //    Port cũ áp guard của họ ĐIỀU CHỈNH cho MỌI hợp đồng ⇒ hợp đồng thường **không bao giờ duyệt được**,
    //    và trạng thái `DlrCtrStatus = "S"` (đã ký) **không có đường vào** — đúng motif "AJ" ở `DlrCtrNoParent`.
    if (c.FlagDlrCtrAdjust != "1")
    {
        // Cả ba hàm thường đều guard `FlagDlrCtrAdjust = Inactive` + `DlrSignStatus = Approved`.
        if (c.DlrSignStatus != "A")
            return Results.BadRequest(new { error = $"Đại lý đang ở '{c.DlrSignStatus}' — hợp đồng thường thì bên A chỉ thao tác SAU khi đại lý đã ký (A)." });
        if (c.DlrCtrStatus != "NS")
            return Results.BadRequest(new { error = $"Hợp đồng đang ở '{c.DlrCtrStatus}' — bên A chỉ thao tác khi chưa ký (NS)." });

        if (dto?.Reject == true)
        {
            // `_HTCRejectX`: guard HTC ∈ **{"P","A1"}** (một danh sách "P, A1"), rồi "R" + huỷ hợp đồng "C".
            // ⚠️ Khác hẳn bản điều chỉnh: bản thường KHÔNG có nhánh "bỏ duyệt về P".
            if (c.HTCSignStatus is not ("P" or "A1"))
                return Results.BadRequest(new { error = $"Bên A đang ở '{c.HTCSignStatus}' — chỉ từ chối khi còn chờ (P) hoặc mới duyệt cấp 1 (A1)." });
            c.HTCSignStatus = "R"; c.DlrCtrStatus = "C";
            c.RejectDTime = now; c.RejectBy = who;      // nguồn dùng CẶP CỘT RIÊNG cho từ chối
        }
        else if (level == 1)
        {
            // `_HTCApprove1X`: "P" → "A1", **giữ nguyên** DlrCtrStatus = "NS".
            if (c.HTCSignStatus != "P")
                return Results.BadRequest(new { error = $"Bên A đang ở '{c.HTCSignStatus}' — duyệt cấp 1 chỉ từ chờ (P)." });
            c.HTCSignStatus = "A1"; c.DlrCtrStatus = "NS";
            c.HTCAppr1DTime = now; c.HTCAppr1By = who;
        }
        else
        {
            // `_HTCApprove2X_New20190531`: "A1" → "A2" **VÀ hợp đồng chuyển sang "S" (đã ký)**.
            if (c.HTCSignStatus != "A1")
                return Results.BadRequest(new { error = "Phải duyệt cấp 1 (A1) trước." });
            c.HTCSignStatus = "A2"; c.DlrCtrStatus = "S";
            c.HTCAppr2DTime = now; c.HTCAppr2By = who;
            // Nguồn upload file hợp đồng đã ký rồi MOVE sang thư mục đích và ghi lại đường dẫn ĐÍCH.
            // ⚠️ MiniHTC chưa có tầng lưu file ⇒ nhận sẵn đường dẫn từ client, **đã ghi nợ**.
            if (!string.IsNullOrWhiteSpace(dto?.FilePath)) c.FilePath = dto!.FilePath!.Trim();
            c.Remark = dto?.Remark;

            var dtls = await db.DmsDealerContractDtls.Where(l => l.OrgId == t.OrgId && l.DlrCtrNo == c.DlrCtrNo).ToListAsync();
            foreach (var l in dtls)
            {
                // `t.DlrCtrStatusDtl = f.DlrCtrStatus` và LogLU của dòng lấy từ **HTCAppr2***.
                l.DlrCtrStatusDtl = c.DlrCtrStatus;
                l.LogLUDateTime = now; l.LogLUBy = who;
            }

            // 🔴 Khối `// Update Car_Car:` — duyệt TỪNG DÒNG hợp đồng để GẮN hợp đồng vào xe:
            //    `FlagDealerContractDMS40 = '1'` (gán CỨNG) + `DealerContractNo`/`DlrCtrNo` = số hợp đồng.
            //    Sau đó nguồn còn gọi `Car_Car_UpdEndDays` để tính lại các mốc hết hạn theo hợp đồng — **ĐÃ GHI NỢ**.
            var carIds = dtls.Select(l => l.CarId).Where(x => x.Length > 0).Distinct().ToList();
            if (carIds.Count > 0)
            {
                var cars = await db.CarVinMasters.Where(v => v.OrgId == t.OrgId && carIds.Contains(v.VIN)).ToListAsync();
                foreach (var v in cars)
                {
                    v.DlrCtrNo = c.DlrCtrNo;
                    v.FlagDealerContractDMS40 = "1";
                    v.LogLUDateTime = now; v.LogLUBy = who;
                }
            }
        }
        c.LogLUDateTime = now; c.LogLUBy = who;
        await db.SaveChangesAsync();
        return Results.Ok(new { c.DlrCtrNo, c.HTCSignStatus, c.DlrCtrStatus, adjust = false });
    }

    // ===== họ hàm ĐIỀU CHỈNH (`_HTCApprove1AdjustX` 5539 · `_HTCApprove2AdjustX` 5919 · `_HTCRejectAdjustX` 6320) =====
    // ⚠️ Luật phản trực giác: cả ba đều yêu cầu `DlrSignStatus = "P"` — bên A duyệt **TRƯỚC** khi đại lý ký.
    if (dto?.Reject == true)
    {
        // `_HTCRejectAdjustX`: guard Dlr="P", HTC ∈ {"A1","A2"}, HĐ ∈ {"NS","S"} —
        // **không từ chối được khi HTC chưa duyệt gì**.
        if (c.DlrSignStatus != "P") return Results.BadRequest(new { error = $"Đại lý đang ở '{c.DlrSignStatus}' — bên A chỉ thao tác khi đại lý còn chờ (P)." });
        if (c.HTCSignStatus is not ("A1" or "A2")) return Results.BadRequest(new { error = "Chỉ từ chối sau khi bên A đã duyệt cấp 1 (A1) hoặc cấp 2 (A2)." });
        if (c.DlrCtrStatus is not ("NS" or "S")) return Results.BadRequest(new { error = $"Hợp đồng đang ở '{c.DlrCtrStatus}' — không từ chối được." });
        // 🔴 HAI NHÁNH KHÁC HẲN NHAU tuỳ trạng thái hiện tại (nguồn 6389-6399):
        if (c.HTCSignStatus == "A1")
        {
            // Đang cấp 1 ⇒ **BỎ DUYỆT**: quay về "P", hợp đồng trở lại "NS". KHÔNG phải từ chối.
            c.HTCSignStatus = "P"; c.DlrCtrStatus = "NS";
        }
        else
        {
            // Đang cấp 2 ⇒ từ chối thật: "R" **và HUỶ luôn hợp đồng** ("C").
            c.HTCSignStatus = "R"; c.DlrCtrStatus = "C";
        }
    }
    else if (level == 1)
    {
        // `_HTCApprove1AdjustX`: guard Dlr="P", HTC="P", HĐ="NS".
        if (c.DlrSignStatus != "P") return Results.BadRequest(new { error = $"Đại lý đang ở '{c.DlrSignStatus}' — bên A chỉ duyệt khi đại lý còn chờ (P)." });
        if (c.HTCSignStatus != "P") return Results.BadRequest(new { error = $"Bên A đang ở '{c.HTCSignStatus}' — duyệt cấp 1 chỉ từ chờ (P)." });
        if (c.DlrCtrStatus != "NS") return Results.BadRequest(new { error = $"Hợp đồng đang ở '{c.DlrCtrStatus}' — duyệt cấp 1 chỉ khi chưa ký (NS)." });
        c.HTCSignStatus = "A1";
    }
    else
    {
        // `_HTCApprove2AdjustX`: guard Dlr="P", HTC="A1", HĐ="NS".
        if (c.DlrSignStatus != "P") return Results.BadRequest(new { error = $"Đại lý đang ở '{c.DlrSignStatus}' — bên A chỉ duyệt khi đại lý còn chờ (P)." });
        if (c.HTCSignStatus != "A1") return Results.BadRequest(new { error = "Phải duyệt cấp 1 (A1) trước." });
        if (c.DlrCtrStatus != "NS") return Results.BadRequest(new { error = $"Hợp đồng đang ở '{c.DlrCtrStatus}' — duyệt cấp 2 chỉ khi chưa ký (NS)." });
        c.HTCSignStatus = "A2"; c.HTCAppr2DTime = DateTime.Now;
        // ⚠️ Nguồn giữ nguyên DlrCtrStatus = "NS" sau cấp 2 — KHÔNG tự chuyển sang "S".
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { c.DlrCtrNo, c.HTCSignStatus, c.DlrCtrStatus });
}).RequireAuthorization();

// ===== 🔴 #207 HUỶ HĐ ĐẠI LÝ — `DMS40_CT_DealerContract_DlrCancel_New20190404` (DMS40/0.34.Contract.cs:5246) =====
// BƯỚC 3B: md5 CẢ FILE `e2f3680f` KHỚP 2 máy.
//
// 🔴 GUARD BA TRỤC của nguồn — port cũ chỉ chặn hai giá trị của MỘT trục nên LỎNG hơn hẳn:
//     `DlrSignStatus`  phải = `DlrSignStatus.Approved` ("A")   — đại lý đã ký duyệt
//     `HTCSignStatus`  phải = `HTCSignStatus.Pending` ("P")    — HTC CHƯA ký
//     `DlrCtrStatus`   phải = `DlrCtrStatus.NotSign` ("NS")    — hợp đồng chưa ký
//   (`TConst.DlrCtrStatus`: NS chưa ký · S đã ký · AJ điều chỉnh · C huỷ — Const.Main.DMS40.cs:147.)
//   ⇒ Chỉ huỷ được đúng MỘT trạng thái: đại lý đã ký nhưng HTC chưa ký.
//
// Nguồn ghi trên HEADER: `CancelDTime`/`CancelBy`, **và cùng giá trị đó** vào `LogLUDateTime`/`LogLUBy`
//   lẫn `LUDTime`/`LUBy` (ba cặp một giá trị), kèm `DlrSignStatus`, `DlrCtrStatus`, `Remark`.
// 🔴 CASCADE: bảng `DMS40_CT_DealerContractDetail` — `DlrCtrStatusDtl = f.DlrSignStatus` + `LogLU*`.
//   Port cũ chỉ đổi header ⇒ dòng chi tiết đứng nguyên (cùng lớp lỗi #193/#194).
app.MapPost("/api/dmsdealercontracts/{no}/cancel", async (string no, DmsCtrCancelDto? dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim();
    var c = await db.DmsDealerContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrCtrNo == no);
    if (c is null) return Results.NotFound(new { no });

    if ((c.DlrSignStatus ?? "") != "A")
        return Results.BadRequest(new { error = $"Đại lý chưa ký duyệt (DlrSignStatus = '{c.DlrSignStatus}') — không huỷ được." });
    if ((c.HTCSignStatus ?? "") != "P")
        return Results.BadRequest(new { error = $"HTC đã xử lý chữ ký (HTCSignStatus = '{c.HTCSignStatus}') — không huỷ được." });
    if ((c.DlrCtrStatus ?? "") != "NS")
        return Results.BadRequest(new { error = $"Hợp đồng đang '{c.DlrCtrStatus}' — chỉ huỷ khi chưa ký (NS)." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    c.DlrSignStatus = "C"; c.DlrCtrStatus = "C";
    c.CancelDTime = now; c.CancelBy = who;
    c.LogLUDateTime = now; c.LogLUBy = who;      // nguồn: LogLU* nhận đúng CancelDTime/CancelBy
    c.LUDTime = now; c.LUBy = who;               // nguồn: LUDTime/LUBy cũng nhận CÙNG giá trị
    if (!string.IsNullOrWhiteSpace(dto?.Remark)) c.Remark = dto!.Remark!.Trim();

    var dtls = await db.DmsDealerContractDtls.Where(x => x.OrgId == t.OrgId && x.DlrCtrNo == no).ToListAsync();
    foreach (var d in dtls) { d.DlrCtrStatusDtl = "C"; d.LogLUDateTime = now; d.LogLUBy = who; }

    await db.SaveChangesAsync();
    return Results.Ok(new { c.DlrCtrNo, c.DlrSignStatus, status = c.DlrCtrStatus, c.CancelDTime, c.CancelBy,
                            cancelledDetailRows = dtls.Count });
}).RequireAuthorization();

