app.MapPost("/api/dmscancelminutes", async (DmsCancelMinutesDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DlrCtrNo)) return Results.BadRequest(new { error = "Cần số hợp đồng." });
    var dlr = dto.DlrCtrNo.Trim();
    var c = await db.DmsDealerContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrCtrNo == dlr);
    if (c is null) return Results.BadRequest(new { error = $"Không tìm thấy HĐ {dlr}." });
    var seq = await db.DmsCancelMinutesSet.CountAsync(m => m.OrgId == t.OrgId && m.DlrCtrNo == dlr) + 1;
    var no = dlr + "." + seq;
    var m = new DmsCancelMinutes { OrgId = t.OrgId, CancelMinutesNo = no, DlrCtrNo = dlr, Remark = dto.Remark, FlagIsDelete = dto.FlagIsDelete == "1" ? "1" : "0" };
    db.DmsCancelMinutesSet.Add(m);
    // 🔴 Port cũ huỷ hợp đồng NGAY khi tạo biên bản — SAI. Nguồn (`_Save_New20181115`) chỉ tạo biên bản
    //    ở trạng thái "NS" với hai trục ký đang chờ ("P"); hợp đồng chỉ bị huỷ khi **HTC duyệt cấp 2**.
    await db.SaveChangesAsync();
    return Results.Ok(new { m.CancelMinutesNo, m.DlrCtrNo, status = m.CancelMinutesStatus, message = "Tạo biên bản hủy hợp đồng thành công!" });
}).RequireAuthorization();

// 🔴 QUY TRÌNH KÝ BIÊN BẢN HUỶ HĐ — `DMS40_DlrCtr_CancelMinutes_*` (0.34.Contract.cs:6767-9000).
// Bốn hành động, mỗi hành động guard **đồng thời hai trục ký**:
//   · `_DlrApprove` (7556): Dlr="P" ⇒ Dlr="A"
//   · `_DlrCancel`  (7872): Dlr="A", HTC="P" ⇒ Dlr="C" **và** biên bản "C"
//   · `_HTCAppr1`   (8098): Dlr="A", HTC="P" ⇒ HTC="A1"
//   · `_HTCAppr2`   (8328): Dlr="A", HTC="A1" ⇒ HTC="A", biên bản **"S"**,
//        **và huỷ luôn HỢP ĐỒNG** (`DMS40_CT_DealerContract.DlrCtrStatus = "C"`) — hiệu ứng LAN SANG BẢNG KHÁC
//   · `_Reject`     (8779): Dlr="A" ⇒ HTC="R" **và** biên bản "C"
// ===== #183 SỬA biên bản huỷ HĐ đại lý — `DMS40_DlrCtr_CancelMinutes_Update_New20181115` =====
// Nguồn: `TERP.BizHTC/DMS40/0.34.Contract.cs:7378` (csproj 125).
// BƯỚC 3B: md5 CẢ FILE `e2f3680f` KHỚP 2 máy. TWIN: lệnh có ở CẢ HAI bit, cùng bản `_New20181115`.
// Đã liệt kê ranh giới hàm trước khi đọc: vùng 7378–8700 chứa đúng 5 hàm của cụm.
//
// 🔴 Lệnh cuối còn thiếu của cụm `DMS40_DlrCtr_CancelMinutes` (nguồn 7 lệnh; MiniHTC đã có
//    dlr-approve / dlr-cancel / htc-appr1 / htc-appr2 / reject + POST tạo).
//
// 🔴 MÔ-TIP "CẬP NHẬT CÓ CHỌN CỘT" (field-mask) — lần đầu gặp trong hệ:
//    nguồn nhận tham số `objFt_Cols_Upd` là **chuỗi liệt kê cột được phép sửa**, rồi
//    `bUpd_FilePath = strFt_Cols_Upd.Contains("DMS40_DlrCtr_CancelMinutes.FilePath".ToUpper())`.
//    Chỉ cột nào **được liệt kê** mới vào `alColumnEffective` và mới được ghi.
//    ⇒ Không phải "sửa hết những gì client gửi": client phải **khai báo trước** cột định sửa.
//    Hiện nguồn chỉ hỗ trợ đúng MỘT cột: `FilePath`.
//
// 🔴 GUARD PHỤ THEO CỘT: `DlrSignCcMnStatus = Approved` **chỉ kiểm KHI có sửa `FilePath`**
//    (nằm trong `if (bUpd_FilePath)`), không phải guard chung của lệnh. Nếu mask rỗng thì lệnh
//    chỉ đụng `LogLUDateTime`/`LogLUBy` và không cần đại lý đã ký.
app.MapPost("/api/dmscancelminutes/{no}/update", async (string no, CancelMinutesUpdateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim();
    var m = await db.DmsCancelMinutesSet.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CancelMinutesNo == no);
    if (m is null) return Results.NotFound(new { no });

    // `strFt_Cols_Upd` — mask cột, so khớp KHÔNG phân biệt hoa thường đúng như nguồn (`.ToUpper()`).
    var mask = (dto.FtColsUpd ?? "").ToUpperInvariant();
    var updFilePath = mask.Contains("DMS40_DLRCTR_CANCELMINUTES.FILEPATH");

    if (updFilePath && m.DlrSignCcMnStatus != "A")
        return Results.BadRequest(new { error = $"Đại lý đang ở '{m.DlrSignCcMnStatus}' — chỉ sửa file khi đại lý đã ký (A)." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    if (updFilePath) m.FilePath = (dto.FilePath ?? "").Trim();
    // Hai cột nhật ký LUÔN được ghi, kể cả khi mask rỗng.
    m.LogLUDateTime = now; m.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { m.CancelMinutesNo, updatedFilePath = updFilePath, m.FilePath, m.LogLUDateTime, m.LogLUBy });
}).RequireAuthorization();

app.MapPost("/api/dmscancelminutes/{no}/{action}", async (string no, string action, AppDbContext db, ITenantContext t) =>
{
    if (action is not ("dlr-approve" or "dlr-cancel" or "htc-appr1" or "htc-appr2" or "reject"))
        return Results.BadRequest(new { error = "action = dlr-approve|dlr-cancel|htc-appr1|htc-appr2|reject" });
    no = no.Trim();
    var m = await db.DmsCancelMinutesSet.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CancelMinutesNo == no);
    if (m is null) return Results.NotFound(new { no });

    if (action == "dlr-approve")
    {
        if (m.DlrSignCcMnStatus != "P") return Results.BadRequest(new { error = $"Đại lý đang ở '{m.DlrSignCcMnStatus}' — chỉ duyệt khi đang chờ (P)." });
        m.DlrSignCcMnStatus = "A";
        await db.SaveChangesAsync();
        return Results.Ok(new { m.CancelMinutesNo, m.DlrSignCcMnStatus, m.CancelMinutesStatus });
    }

    // Bốn hành động còn lại đều yêu cầu đại lý đã duyệt ("A").
    if (m.DlrSignCcMnStatus != "A") return Results.BadRequest(new { error = "Đại lý chưa duyệt biên bản (cần Dlr = A)." });

    if (action == "dlr-cancel")
    {
        if (m.HTCSignCcMnStatus != "P") return Results.BadRequest(new { error = "Chỉ đại lý huỷ được khi HTC chưa duyệt (P)." });
        m.DlrSignCcMnStatus = "C"; m.CancelMinutesStatus = "C";
    }
    else if (action == "htc-appr1")
    {
        if (m.HTCSignCcMnStatus != "P") return Results.BadRequest(new { error = $"HTC đang ở '{m.HTCSignCcMnStatus}' — duyệt cấp 1 chỉ từ chờ (P)." });
        m.HTCSignCcMnStatus = "A1";
    }
    else if (action == "htc-appr2")
    {
        if (m.HTCSignCcMnStatus != "A1") return Results.BadRequest(new { error = "Phải duyệt cấp 1 (A1) trước." });
        m.HTCSignCcMnStatus = "A"; m.CancelMinutesStatus = "S";
        // 🔴 Chỉ ở BƯỚC NÀY hợp đồng mới thực sự bị huỷ.
        var c = await db.DmsDealerContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrCtrNo == m.DlrCtrNo);
        if (c is not null) { c.DlrCtrStatus = "C"; }
    }
    else // reject
    {
        if (m.HTCSignCcMnStatus is not ("P" or "A1")) return Results.BadRequest(new { error = "Chỉ từ chối khi HTC đang chờ (P) hoặc mới duyệt cấp 1 (A1)." });
        m.HTCSignCcMnStatus = "R"; m.CancelMinutesStatus = "C";
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { m.CancelMinutesNo, m.DlrSignCcMnStatus, m.HTCSignCcMnStatus, m.CancelMinutesStatus });
}).RequireAuthorization();

// Hủy NH phát hành bảo lãnh MD (FrmDMS40_DlrCtr_CancelBankMD)
// ===== #182 HOÀN TẤT / TỪ CHỐI biên bản huỷ ngân hàng bảo lãnh MD — cụm `DMS40_DlrCtr_CancelBankMD_*` =====
// Nguồn: `TERP.BizHTC/DMS40/0.34.Contract.cs` (csproj 125) — `_Reject_New20181115` (10152),
//   `_Finish_New20181115` (10372), `_FinishAndSendMail_New20181115` (10627).
// BƯỚC 3B: md5 CẢ FILE `e2f3680f` KHỚP 2 máy (đã đo ở #165, đo lại vẫn khớp).
// TWIN: cả ba lệnh có ở **CẢ HAI** bit, cùng bản `_New20181115`.
//
// 🔴 Cách tìm ra: lập **BẢNG ACTION THẬT** (luật `C0-ducentesimusquinquagesimusquintus` rút ra sau sự cố
//    port trùng #180/#181) — quét 55 endpoint gói nhiều lệnh trong MỘT route. Đối chiếu bề mặt WS thì cụm
//    `DMS40_DlrCtr_CancelBankMD` có **4 lệnh ghi** mà MiniHTC mới có GET + POST(tạo) ⇒ thiếu cả 3 lệnh dưới.
//
// Trạng thái theo `TConst.CancelBankMDStatus` ("N"/"P"/"C"/"A"/"A1"/"A2"/"F"):
//   · `_Reject` : guard **"A"** → **"R"**, ghi `RejectDTime`/`RejectBy`/`RemarkDlr`
//   · `_Finish` : guard **"A"** → **"F"**, ghi `FinishDTime`/`FinishBy`/`RemarkDlr`
//                 **VÀ side-effect lên `DMS40_CT_DealerContract`**: `BankCodeMD = f.BankCodeMD_Upd`
//                 với `BankCodeMD_Upd = DBNull.Value` ⇒ **XOÁ ngân hàng bảo lãnh MD khỏi hợp đồng**.
//                 Đây mới là mục đích thật của "hoàn tất biên bản huỷ NH bảo lãnh".
//   · `_FinishAndSendMail` = `_Finish` + xếp lô gửi mail ⇒ port bằng cờ `sendMail` (mail **ghi nợ**).
app.MapPost("/api/dmscancelbankmd/{no}/{action}", async (string no, string action, CancelBankMDActionDto? dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (action is not ("finish" or "reject")) return Results.BadRequest(new { error = "action = finish|reject" });
    no = no.Trim().ToUpperInvariant();
    var m = await db.DmsCancelBankMDs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CancelBankMDNo == no);
    if (m is null) return Results.NotFound(new { no });

    // Cả hai lệnh cùng guard: `DMS40_DlrCtr_CancelBankMD_CheckDB(..., CancelBankMDStatus.Approved)`.
    if (m.CancelBankMDStatus != "A")
        return Results.BadRequest(new { error = $"Biên bản đang ở '{m.CancelBankMDStatus}' — chỉ hoàn tất/từ chối khi đã duyệt (A)." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    m.RemarkDlr = dto?.RemarkDlr;
    m.LogLUDateTime = now; m.LogLUBy = who;
    m.LUDTime = now; m.LUBy = who;      // nguồn ghi CẢ hai cặp: LogLU* (nhật ký) và LU* (sửa lần cuối)

    string? clearedOn = null;
    if (action == "reject")
    {
        m.CancelBankMDStatus = "R";
        m.RejectDTime = now; m.RejectBy = who;
    }
    else
    {
        m.CancelBankMDStatus = "F";
        m.FinishDTime = now; m.FinishBy = who;
        // 🔴 SIDE-EFFECT: hoàn tất biên bản huỷ ⇒ **gỡ ngân hàng bảo lãnh MD khỏi hợp đồng đại lý**
        //    (`t.BankCodeMD = f.BankCodeMD_Upd`, mà `BankCodeMD_Upd = DBNull.Value`).
        if (!string.IsNullOrWhiteSpace(m.DlrCtrNo))
        {
            var ctr = await db.DmsDealerContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrCtrNo == m.DlrCtrNo);
            if (ctr is null) return Results.BadRequest(new { error = $"Không tìm thấy hợp đồng đại lý {m.DlrCtrNo}.", dlrCtrNo = m.DlrCtrNo });
            ctr.BankCodeMD = null;
            ctr.LogLUDateTime = now; ctr.LogLUBy = who;
            ctr.LUDTime = now; ctr.LUBy = who;
            clearedOn = ctr.DlrCtrNo;
        }
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { m.CancelBankMDNo, status = m.CancelBankMDStatus, m.DlrCtrNo, m.RemarkDlr,
        m.FinishDTime, m.FinishBy, m.RejectDTime, m.RejectBy,
        bankCodeMDClearedOn = clearedOn,
        mailQueued = (action == "finish" && dto?.SendMail == true) ? "NỢ: chưa nối tầng gửi mail thật (_FinishAndSendMail)" : null });
}).RequireAuthorization();

app.MapGet("/api/dmscancelbankmd", async (AppDbContext db, ITenantContext t, string? dlrCtrNo) =>
