// ===== Công văn bảo lãnh/claim (GrtClaim — port 1:1 FrmNewGrtClaim/FrmMngGrtClaim, 2010.HTC/Sales/GrtClaim) =====
app.MapGet("/api/grtclaims", async (AppDbContext db, ITenantContext t, string? status, string? dealer) =>
{
    var q = db.GrtClaims.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(r => r.Status == status);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(r => r.DealerCode == dealer);
    var items = await q.OrderByDescending(r => r.Id).Take(500).Select(r => new
    {
        r.GrtClaimNo, r.DealerCode, r.ContractDate, r.FlagisHTC, r.Status, r.CreatedAt, r.IssuedAt,
        r.SignStatus, r.SignDate, r.SignBy, r.FileSigned, r.CancelDate, r.CancelBy,
        r.RejectDate, r.RejectBy, r.RejectRemark, r.LogLUDateTime, r.LogLUBy,
        cars = db.GrtClaimDetails.Count(c => c.OrgId == t.OrgId && c.GrtClaimId == r.Id),
        total = db.GrtClaimDetails.Where(c => c.OrgId == t.OrgId && c.GrtClaimId == r.Id).Sum(c => (decimal?)c.UnitPrice) ?? 0
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/grtclaims", async (GrtClaimDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Cần mã đại lý." });
    if (string.IsNullOrWhiteSpace(dto.FlagisHTC)) return Results.BadRequest(new { error = "Chưa chọn phép nhận!" });
    var cars = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.VIN)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "Chưa có chi tiết xe để tạo công văn." });
    var dupe = cars.GroupBy(c => c.VIN.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });
    var no = "GRT" + DateTime.Now.ToString("yyMMddHHmmss");
    // 🔴 Guard nguồn (`Pmt_GrtClaimCreate_Multi_New20190312`, Biz.HTC.WH.My.cs:5415-5420):
    //    VIN đã nằm trong một công văn khác với `VinSignStatus not in ('C')` thì **KHÔNG thêm được**.
    foreach (var vinChk in cars.Select(x => x.VIN.Trim().ToUpperInvariant()).Distinct())
    {
        var dup = await db.GrtClaimDetails.Where(x => x.OrgId == t.OrgId && x.VIN == vinChk && x.VinSignStatus != "C")
            .Join(db.GrtClaims.Where(h => h.OrgId == t.OrgId), dt => dt.GrtClaimId, h => h.Id, (dt, h) => h.GrtClaimNo)
            .FirstOrDefaultAsync();
        if (dup != null) return Results.BadRequest(new { error = $"VIN {vinChk} đã nằm trong công văn {dup} (chưa huỷ)." });
    }
    var r = new GrtClaim { OrgId = t.OrgId, GrtClaimNo = no, DealerCode = dto.DealerCode.Trim().ToUpperInvariant(), ContractDate = dto.ContractDate, FlagisHTC = dto.FlagisHTC.Trim(), Status = "Draft" };
    db.GrtClaims.Add(r); await db.SaveChangesAsync();
    foreach (var c in cars)
        db.GrtClaimDetails.Add(new GrtClaimDetail { OrgId = t.OrgId, GrtClaimId = r.Id, VIN = c.VIN.Trim().ToUpperInvariant(), UnitPrice = c.UnitPrice, BankCode = c.BankCode });
    await db.SaveChangesAsync();
    return Results.Ok(new { r.GrtClaimNo, cars = cars.Count });
}).RequireAuthorization();

app.MapGet("/api/grtclaims/{no}/cars", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.GrtClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GrtClaimNo == no);
    if (r is null) return Results.NotFound(new { no });
    var cars = await db.GrtClaimDetails.Where(c => c.OrgId == t.OrgId && c.GrtClaimId == r.Id)
        .Select(c => new { c.VIN, c.UnitPrice, c.BankCode, c.VinSignStatus, c.LogLUDateTime, c.LogLUBy }).ToListAsync();
    return Results.Ok(new { r.GrtClaimNo, r.DealerCode, r.FlagisHTC, count = cars.Count, cars, total = cars.Sum(x => x.UnitPrice),
        signed = cars.Count(x => x.VinSignStatus == "A"), cancelled = cars.Count(x => x.VinSignStatus == "C") });
}).RequireAuthorization();

// 🔴 KÝ / HUỶ theo TỪNG VIN — trục thật của cụm là `Pmt_GrtClaimDetail.VinSignStatus`
// ("P" chưa ký → "A" đã ký, hoặc "C" huỷ). Header `Pmt_GrtClaim` KHÔNG có cột trạng thái,
// nên endpoint `issue`/`cancel` ở cấp công văn của port cũ là **bịa** — đã thay bằng thao tác theo dòng.
app.MapPost("/api/grtclaims/{no}/cars/{vin}/{action}", async (string no, string vin, string action, AppDbContext db, ITenantContext t) =>
{
    if (action is not ("sign" or "cancel")) return Results.BadRequest(new { error = "action = sign|cancel" });
    no = no.Trim().ToUpperInvariant(); vin = vin.Trim().ToUpperInvariant();
    var r = await db.GrtClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GrtClaimNo == no);
    if (r is null) return Results.NotFound(new { no });
    var d = await db.GrtClaimDetails.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GrtClaimId == r.Id && x.VIN == vin);
    if (d is null) return Results.NotFound(new { no, vin });
    if (action == "sign")
    {
        if (d.VinSignStatus != "P") return Results.BadRequest(new { error = $"VIN {vin} đang ở '{d.VinSignStatus}' — chỉ ký khi chưa ký (P)." });
        d.VinSignStatus = "A";
    }
    else
    {
        if (d.VinSignStatus == "C") return Results.BadRequest(new { error = $"VIN {vin} đã huỷ." });
        d.VinSignStatus = "C";
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { r.GrtClaimNo, d.VIN, d.VinSignStatus });
}).RequireAuthorization();

// 🔴 XOÁ cả công văn — `GrtClaimDelete_New20181115` (BizHTC.Payment.cs:3180): nguồn xoá thẳng
// `Pmt_GrtClaimDetail` rồi `Pmt_GrtClaim`, RBAC `myCommon_CheckHTCDirect`; **không có trạng thái huỷ ở header**.
// ===== #172 KÝ / HUỶ / XOÁ / TỪ CHỐI công văn bảo lãnh — cụm `Pmt_GrtClaim_*` =====
// Nguồn: `TERP.BizHTC/DataWH/Biz.HTC.WH.My.cs` (csproj 273). BƯỚC 3B: md5 cả file `7ef389d0` KHỚP 2 máy.
//   `_Approve` (5981) · `_DelMulti` (6322) · `_CancelMulti` (6549) · `_RejectGrtClaim` (7745).
// TWIN: bốn lệnh này có ở CẢ hai bit; riêng `_ApproveAndSignAndSendMail_New20190531` và toàn bộ cụm
//   `Pmt_GrtClaimExt_*` (5 lệnh) **CHỈ có ở WS 64-bit** — ghi nợ.
//
// 🔴 SỬA MỘT KẾT LUẬN SAI của lượt trước. Port cũ ghi trong `GrtClaim.Status`:
//    *"Nguồn KHÔNG có cột trạng thái cho HEADER … `grep GrtClaimStatus` = 0 hit ⇒ Draft/Issued/Cancelled
//    là trạng thái BỊA … Trục trạng thái THẬT nằm ở DÒNG (`VinSignStatus`)."*
//    Nửa sau đúng, **nửa đầu sai**: cột trạng thái header có thật, chỉ **không tên `GrtClaimStatus`** mà là
//    **`SignStatus`** (`TConst.SignStatus`: **"P" chưa ký · "A" đã ký · "C" huỷ**). Bốn hàm dưới đây đều
//    guard/ghi chính cột đó — grep sai TÊN nên kết luận sai SỰ TỒN TẠI.
//
// Bảng trạng thái header thật:
//   `_Approve`     : guard "P" → "A"  (+ `SignDate`, `FileSigned`; và ký TẤT CẢ dòng `VinSignStatus = "A"`)
//   `_DelMulti`    : guard "P" → xoá  (chỉ xoá được công văn CHƯA ký)
//   `_CancelMulti` : guard "A" → "C"  (+ `CancelDate`/`CancelBy`) — chỉ huỷ được công văn ĐÃ ký
//   `_RejectGrtClaim`: guard "C"      — chỉ GỬI MAIL từ chối cho công văn ĐÃ HUỶ; không đổi trạng thái
// ⇒ luồng thật: ký (P→A) → huỷ (A→C) → gửi mail từ chối (C). Cả bốn đều `myCommon_CheckHTCDirect` (nợ RBAC fleet).
app.MapPost("/api/grtclaims/{no}/approve", async (string no, GrtClaimApproveDto? dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.GrtClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GrtClaimNo == no);
    if (r is null) return Results.NotFound(new { no });
    if (r.SignStatus != "P")
        return Results.BadRequest(new { error = $"Công văn đang ở '{r.SignStatus}' — chỉ ký khi chưa ký (P)." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;

    var lines = await db.GrtClaimDetails.Where(x => x.OrgId == t.OrgId && x.GrtClaimId == r.Id).ToListAsync();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Công văn không có dòng VIN nào." });
    // Nguồn ký TOÀN BỘ dòng trong một lượt: `drScan["VinSignStatus"] = TConst.SignStatus.Signed`.
    foreach (var l in lines) { l.VinSignStatus = "A"; l.LogLUDateTime = now; l.LogLUBy = who; }

    r.SignStatus = "A"; r.SignDate = now; r.SignBy = who;
    r.FileSigned = dto?.FileSigned;     // nguồn ghi đường dẫn file đã ký cùng lượt
    r.LogLUDateTime = now; r.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { r.GrtClaimNo, r.SignStatus, r.SignDate, r.SignBy, r.FileSigned, signedLines = lines.Count });
}).RequireAuthorization();

// 🔴 `_CancelMulti` (6549) và `_DelMulti` (6322) đều nhận NHIỀU công văn một lượt (bảng đầu vào),
//    và **guard trạng thái NGƯỢC NHAU**: huỷ đòi "A" (đã ký), xoá đòi "P" (chưa ký).
app.MapPost("/api/grtclaims/{action}-multi", async (string action, GrtClaimMultiDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (action is not ("cancel" or "del")) return Results.NotFound();
    var nos = (dto.GrtClaimNos ?? new()).Select(x => (x ?? "").Trim().ToUpperInvariant()).Where(x => x.Length > 0).Distinct().ToList();
    if (nos.Count == 0) return Results.BadRequest(new { error = "Chưa chọn công văn nào." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var wanted = action == "cancel" ? "A" : "P";
    int done = 0, delLines = 0;
    foreach (var n in nos)
    {
        var r = await db.GrtClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GrtClaimNo == n);
        if (r is null) return Results.BadRequest(new { error = $"Công văn {n} không tồn tại.", grtClaimNo = n });
        if (r.SignStatus != wanted)
            return Results.BadRequest(new { error = $"Công văn {n} đang ở '{r.SignStatus}' — {(action == "cancel" ? "chỉ huỷ được công văn ĐÃ ký (A)" : "chỉ xoá được công văn CHƯA ký (P)")}.", grtClaimNo = n });
        var lines = await db.GrtClaimDetails.Where(x => x.OrgId == t.OrgId && x.GrtClaimId == r.Id).ToListAsync();
        if (action == "cancel")
        {
            r.SignStatus = "C"; r.CancelDate = now; r.CancelBy = who;
            r.LogLUDateTime = now; r.LogLUBy = who;
            // Nguồn dựng luôn bảng dòng để đồng bộ `VinSignStatus` theo header.
            foreach (var l in lines) { l.VinSignStatus = "C"; l.LogLUDateTime = now; l.LogLUBy = who; }
        }
        else
        {
            db.GrtClaimDetails.RemoveRange(lines); delLines += lines.Count;
            db.GrtClaims.Remove(r);
        }
        done++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { action, count = done, linesDeleted = delLines });
}).RequireAuthorization();

// 🔴 `_RejectGrtClaim` (7745): guard header **`SignStatus = "C"` ở CẢ HAI lần `Pmt_GrtClaim_CheckDB`**
//    ⇒ đây KHÔNG phải bước đổi trạng thái, mà là bước **gửi mail từ chối cho công văn ĐÃ HUỶ**
//    (`DMS40_Email_BatchSendEmail_Build_SendRejectX` → `_SaveX` → xếp lô gửi).
// ⚠️ NỢ: MiniHTC chưa nối tầng gửi mail thật ⇒ chỉ ghi mốc từ chối và trả về cảnh báo, KHÔNG bịa lô mail.
app.MapPost("/api/grtclaims/{no}/reject", async (string no, GrtClaimRejectDto? dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.GrtClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GrtClaimNo == no);
    if (r is null) return Results.NotFound(new { no });
    if (r.SignStatus != "C")
        return Results.BadRequest(new { error = $"Công văn đang ở '{r.SignStatus}' — chỉ gửi thông báo từ chối cho công văn ĐÃ HUỶ (C)." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    r.RejectDate = DateTime.Now; r.RejectBy = who; r.RejectRemark = dto?.Remark;
    r.LogLUDateTime = DateTime.Now; r.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { r.GrtClaimNo, r.SignStatus, r.RejectDate, r.RejectBy, r.RejectRemark,
        mailQueued = "NỢ: chưa nối tầng gửi mail thật (DMS40_Email_BatchSendEmail)" });
}).RequireAuthorization();

app.MapDelete("/api/grtclaims/{no}", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.GrtClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GrtClaimNo == no);
    if (r is null) return Results.NotFound(new { no });
    // #172: nguon `_DelMulti` guard `SignStatus = "P"` — chi xoa duoc cong van CHUA ky.
    if (r.SignStatus != "P")
        return Results.BadRequest(new { error = $"Cong van dang o '{r.SignStatus}' — chi xoa duoc khi chua ky (P)." });
    var lines = await db.GrtClaimDetails.Where(x => x.OrgId == t.OrgId && x.GrtClaimId == r.Id).ToListAsync();
    db.GrtClaimDetails.RemoveRange(lines);
    db.GrtClaims.Remove(r);
    await db.SaveChangesAsync();
    return Results.Ok(new { no, linesDeleted = lines.Count });
}).RequireAuthorization();

// ===== Yêu cầu đóng thùng (CBReq — port 1:1 FrmNewCBReq, 2010.HTC/Sales/Purchase) =====
// ===== #B63 HOP NHAT SONG TRUNG `CBReq`/`StoCBReq` (ca thu 7) =====
// `CBReq`+`CBReqDetail` va `StoCBReq`+`StoCBReqDtl` cung anh xa `Sto_CBReq`/`Sto_CBReqDetail`,
// cung khoa nghiep vu `CBReqNo`. Truoc luot nay: luong TAO dung `/api/stocbreqs` ghi vao
// `StoCBReq*`, con luong DUYET `/api/cbreqs/{no}/{action}` (#179) doc `CBReq*`
// => YEU CAU TAO RA KHONG DUYET DUOC, va nguoc lai. Bao cao/tim kiem (#B53) cung chia hai nua.
// Nay MOI SITE tro chung ve `StoCBReq*` (chon vi ten khop bang nguon `Sto_CBReq` va co du cot
// `CreatedDate`/`CBReqStatus`/`ApprovedBy`/`CreatedBy`). Da chuyen 4 cot cua `CBReqDetail` sang
// `StoCBReqDtl`: StorageCodeFrom / StorageCodeTo / TypeCB / Remark (du 4 noi §12).
// `CBReq`/`CBReqDetail` giu lai nhung KHONG con duoc ghi (tien le WholesaleDeal #B09, CtmVisit #B62).
app.MapGet("/api/cbreqs", async (AppDbContext db, ITenantContext t, string? status) =>
{
    var q = db.StoCBReqs.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(r => r.CBReqStatus == status);
    var items = await q.OrderByDescending(r => r.Id).Take(500).Select(r => new
    {
        r.CBReqNo, r.CBReqStatus, r.CreatedDate, r.ApprovedAt,
        cars = db.StoCBReqDtls.Count(c => c.OrgId == t.OrgId && c.StoCBReqId == r.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/cbreqs", async (CBReqDto dto, AppDbContext db, ITenantContext t) =>
{
    var cars = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.VIN)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 VIN." });
    if (cars.Any(c => string.IsNullOrWhiteSpace(c.StorageCodeTo))) return Results.BadRequest(new { error = "Mã kho đến không được để trống." });
    var dupe = cars.GroupBy(c => c.VIN.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });
    var no = "CB" + DateTime.Now.ToString("yyMMddHHmmss");
    var r = new StoCBReq { OrgId = t.OrgId, CBReqNo = no, CBReqStatus = "P", CreatedDate = DateTime.Now };  // #179: TConst.Stage, khong phai "Draft"
    db.StoCBReqs.Add(r); await db.SaveChangesAsync();
    foreach (var c in cars)
        db.StoCBReqDtls.Add(new StoCBReqDtl { OrgId = t.OrgId, StoCBReqId = r.Id, VIN = c.VIN.Trim().ToUpperInvariant(), StorageCodeFrom = c.StorageCodeFrom, StorageCodeTo = c.StorageCodeTo.Trim().ToUpperInvariant(), TypeCB = c.TypeCB, Remark = c.Remark });
    await db.SaveChangesAsync();
    return Results.Ok(new { r.CBReqNo, cars = cars.Count });
}).RequireAuthorization();

app.MapGet("/api/cbreqs/{no}/cars", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.StoCBReqs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CBReqNo == no);
    if (r is null) return Results.NotFound(new { no });
    var cars = await db.StoCBReqDtls.Where(c => c.OrgId == t.OrgId && c.StoCBReqId == r.Id)
        .Select(c => new { c.VIN, c.StorageCodeFrom, c.StorageCodeTo, c.TypeCB, c.Remark }).ToListAsync();
    return Results.Ok(new { r.CBReqNo, r.CBReqStatus, count = cars.Count, cars });
}).RequireAuthorization();

app.MapPost("/api/cbreqs/{no}/{action}", async (string no, string action, CbReqActionDto? dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    // ===== #179 DUYỆT / BỎ DUYỆT yêu cầu đóng thùng — `Sto_CBReqApprove_New20181119` =====
    // Nguồn: `TERP.BizHTC/DataWH/Biz.HTC.WH.cs:115992` (csproj 272).
    // BƯỚC 3B: hàm bắt đầu **KHÁC DÒNG** (laptop 115992 / máy 150 115997) — căn theo MỐC HÀM (luật #156),
    //   vùng 269 dòng md5 `d14ee3b4` KHỚP. TWIN: WS 32-bit và 64-bit gọi CÙNG bản.
    //
    // 🔴 Ba sai của port cũ:
    //   1. **Từ vựng trạng thái TỰ ĐẶT**: port cũ dùng `"Confirmed"`/`"Cancelled"`. Nguồn dùng
    //      `TConst.Stage`: `objCBReqStatusNew = bApprove ? Stage.Approved **"A"** : Stage.Rejected **"R"**`,
    //      và dòng chi tiết nhận `'A'` / `'R'` (`CBReqDtlStatus`). Không có mã "Confirmed"/"Cancelled" nào.
    //   2. Thiếu hẳn `Remark` — nguồn nhận `strRemark` và **ghi vào header ở CẢ HAI ngả**.
    //   3. 🔴 Thiếu guard riêng của ngả bỏ duyệt (`Sto_CBReqApprove_ExistSto_RearrangeCB`),
    //      nguồn ghi rõ trong comment: *"Chỉ Hủy YCĐT A khi chưa có lệnh ĐT A"* —
    //      nếu đã tồn tại **lệnh điều chuyển đóng thùng** (`Sto_RearrangeCBDetail`) còn sống
    //      (`RearCBDtlStatus not in ('R','C')`) cho cùng VIN thì **KHÔNG được bỏ duyệt**.
    // Guard vào: nguồn `CheckDB(..., TConst.Stage.Pending)` — cả hai ngả đều vào từ "P".
    if (action is not ("approve" or "unapprove")) return Results.BadRequest(new { error = "action = approve|unapprove" });
    no = no.Trim().ToUpperInvariant();
    var r = await db.StoCBReqs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CBReqNo == no);
    if (r is null) return Results.NotFound(new { no });
    if (r.CBReqStatus != "P")
        return Results.BadRequest(new { error = $"Yêu cầu đang ở '{r.CBReqStatus}' — chỉ duyệt/bỏ duyệt khi còn chờ duyệt (P)." });

    var bApprove = action == "approve";
    var lines = await db.StoCBReqDtls.Where(x => x.OrgId == t.OrgId && x.StoCBReqId == r.Id).ToListAsync();

    if (!bApprove)
    {
        // `Sto_CBReqApprove_ExistSto_RearrangeCB`: đã có lệnh đóng thùng còn sống thì không huỷ được.
        var vins = lines.Where(l => l.CBReqDtlStatus != "R" && l.CBReqDtlStatus != "C").Select(l => l.VIN).ToList();
        var blocker = await db.StoRearCBDtls.Where(x => x.OrgId == t.OrgId && x.CBReqNo == no
                && vins.Contains(x.VIN) && x.RearCBDtlStatus != "R" && x.RearCBDtlStatus != "C")
            .Select(x => new { x.VIN, x.RearCBDtlStatus }).FirstOrDefaultAsync();
        if (blocker is not null)
            return Results.BadRequest(new { error = $"Đã tồn tại lệnh đóng thùng cho VIN {blocker.VIN} (trạng thái '{blocker.RearCBDtlStatus}') — không bỏ duyệt được yêu cầu.", vin = blocker.VIN });
    }

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    // `bApprove ? Stage.Approved : Stage.Rejected`
    r.CBReqStatus = bApprove ? "A" : "R";
    r.Remark = dto?.Remark;                 // nguồn ghi Remark ở CẢ HAI ngả
    r.ApprovedAt = bApprove ? now : null;
    foreach (var l in lines) l.CBReqDtlStatus = r.CBReqStatus;
    await db.SaveChangesAsync();
    return Results.Ok(new { r.CBReqNo, status = r.CBReqStatus, r.Remark, unapprove = !bApprove, linesUpdated = lines.Count });
}).RequireAuthorization();

// ===== Sắp xếp/chuyển kho (StorageRearrange/SC — port 1:1 FrmNewSC, 2010.HTC/Sales/Purchase) =====
app.MapGet("/api/storagerearranges", async (AppDbContext db, ITenantContext t, string? status) =>
{
    var q = db.StorageRearranges.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(r => r.Status == status);
    var items = await q.OrderByDescending(r => r.Id).Take(500).Select(r => new
    {
        r.SCNo, r.Status, r.CreatedAt, r.Approved1At, r.ConfirmedAt,
        cars = db.StorageRearrangeDetails.Count(c => c.OrgId == t.OrgId && c.StorageRearrangeId == r.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/storagerearranges", async (StorageRearrangeDto dto, AppDbContext db, ITenantContext t) =>
{
    var cars = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.VIN)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 VIN." });
    if (cars.Any(c => string.IsNullOrWhiteSpace(c.StorageCodeTo))) return Results.BadRequest(new { error = "Mã kho đến không được để trống." });
    var dupe = cars.GroupBy(c => c.VIN.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });
    var no = "SC" + DateTime.Now.ToString("yyMMddHHmmss");
    var r = new StorageRearrange { OrgId = t.OrgId, SCNo = no, Status = "P" };
    db.StorageRearranges.Add(r); await db.SaveChangesAsync();
    foreach (var c in cars)
        db.StorageRearrangeDetails.Add(new StorageRearrangeDetail { OrgId = t.OrgId, StorageRearrangeId = r.Id, VIN = c.VIN.Trim().ToUpperInvariant(), StorageCodeFrom = c.StorageCodeFrom, StorageCodeTo = c.StorageCodeTo.Trim().ToUpperInvariant(), Remark = c.Remark });
    await db.SaveChangesAsync();
    return Results.Ok(new { r.SCNo, cars = cars.Count });
}).RequireAuthorization();

app.MapGet("/api/storagerearranges/{no}/cars", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.StorageRearranges.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SCNo == no);
    if (r is null) return Results.NotFound(new { no });
    var cars = await db.StorageRearrangeDetails.Where(c => c.OrgId == t.OrgId && c.StorageRearrangeId == r.Id)
        .Select(c => new { c.VIN, c.StorageCodeFrom, c.StorageCodeTo, c.Remark, c.RearrangeDtlStatus, c.ExpectedStartDate, c.ExpectedEndDate,
            c.RearrangeOutDate, c.RearrangeEndDate, c.ConfirmDate, c.ConfirmBy }).ToListAsync();
    return Results.Ok(new { r.SCNo, r.Status, r.ApprovedBy1, r.ApprovedBy2, r.Remark, count = cars.Count, cars });
}).RequireAuthorization();

// action: confirm|cancel (1 bước, giữ nguyên) hoặc approve1|approve2 (2 cấp, khớp FrmMngSC: Draft→Approved1→Confirmed).
// 🔴 DUYỆT 2 CẤP — `StorageStorageRearrangeApprove1/Approve2_New20181119` (Biz.HTC.WH.cs:68013 / 68245).
// ⚠️ Nguồn KHÔNG có "xác nhận"/"huỷ" phiếu chuyển kho: port cũ tự thêm `confirm`/`cancel` — đã bỏ.
// ⚠️ Cờ NGHỊCH ĐẢO như cụm bảo hiểm: `strFlagUnapprove == Flag.Inactive("0")` mới là **DUYỆT**.
// Bất đối xứng giữa hai cấp (đúng nguồn, không sắp lại):
//   · cấp 1 không duyệt ⇒ **"R" (từ chối)** · cấp 2 không duyệt ⇒ **về "P" (bỏ duyệt)**.
// Mỗi cấp lan trạng thái xuống MỌI dòng: 'A1'/'R' ở cấp 1, 'A2'/'P' ở cấp 2.
app.MapPost("/api/storagerearranges/{no}/{action}", async (string no, string action, ScApproveDto? dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (action is not ("approve1" or "approve2")) return Results.BadRequest(new { error = "action = approve1|approve2" });
    no = no.Trim().ToUpperInvariant();
    var r = await db.StorageRearranges.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SCNo == no);
    if (r is null) return Results.NotFound(new { no });
    var ok = dto?.Approve ?? true;
    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var lines = await db.StorageRearrangeDetails.Where(x => x.OrgId == t.OrgId && x.StorageRearrangeId == r.Id).ToListAsync();
    string dtl;
    if (action == "approve1")
    {
        if (r.Status != "P") return Results.BadRequest(new { error = "Chỉ duyệt cấp 1 phiếu đang chờ duyệt (P)." });
        r.Status = ok ? "A1" : "R"; dtl = ok ? "A1" : "R";
        r.Approved1At = now; r.ApprovedBy1 = who;
    }
    else
    {
        if (r.Status != "A1") return Results.BadRequest(new { error = "Phải duyệt cấp 1 (A1) trước khi duyệt cấp 2." });
        r.Status = ok ? "A2" : "P"; dtl = ok ? "A2" : "P";
        r.Approved2At = now; r.ApprovedBy2 = who;
        if (ok) r.ConfirmedAt = now;
    }
    r.Remark = dto?.Remark;
    foreach (var l in lines) l.RearrangeDtlStatus = dtl;
    await db.SaveChangesAsync();
    return Results.Ok(new { r.SCNo, status = r.Status, linesUpdated = lines.Count });
}).RequireAuthorization();

// 🔴 SỬA DÒNG — `StorageStorageRearrangeDetailUpdate_New20181119` (68475): sửa `ExpectedEndDate` +
// `Remark` của MỘT xe, guard **ngày kết thúc dự kiến không được sớm hơn ngày bắt đầu dự kiến**.
app.MapPost("/api/storagerearranges/{no}/cars/{vin}", async (string no, string vin, ScCarUpdateDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant(); vin = vin.Trim().ToUpperInvariant();
    var r = await db.StorageRearranges.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SCNo == no);
    if (r is null) return Results.NotFound(new { no });
    var c = await db.StorageRearrangeDetails.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StorageRearrangeId == r.Id && x.VIN == vin);
    if (c is null) return Results.NotFound(new { no, vin });
    if (c.ExpectedStartDate is not null && dto.ExpectedEndDate is not null && c.ExpectedStartDate > dto.ExpectedEndDate)
        return Results.BadRequest(new { error = "Ngày kết thúc dự kiến không được sớm hơn ngày bắt đầu dự kiến." });
    c.ExpectedEndDate = dto.ExpectedEndDate; c.Remark = dto.Remark;
    await db.SaveChangesAsync();
    return Results.Ok(new { no, c.VIN, c.ExpectedStartDate, c.ExpectedEndDate, c.Remark });
}).RequireAuthorization();

// ===== Đề nghị bảo hiểm (InsuranceReq — port 1:1 FrmNewInsuranceReq, 2010.HTC/Sales/Purchase) =====
// ===== 🔴 Master BẢO HIỂM (Mst_InsuranceCompany / Mst_InsuranceType) — hệ `ERP.V15.DMSSales.Real` =====
// Hệ này **CHỈ có trên máy 150**. Cổng `TERP.WSINS` cho công ty bảo hiểm đăng nhập tra dữ liệu.
// 🔴 RBAC của nguồn: `and (mit.InsCompanyCode like @strAbilityOfUser)` (`TERP.BizInsurance/InsReq.cs:184`)
//    ⇒ người dùng của công ty bảo hiểm **chỉ thấy dữ liệu công ty mình**, lọc bằng PATTERN (`like`).
app.MapGet("/api/insurancecompanies", async (AppDbContext db, ITenantContext t, string? active) =>
{
    var qy = db.MstInsuranceCompanies.Where(x => x.OrgId == t.OrgId);
    if (active != "all") qy = qy.Where(x => x.FlagActive == "1");
    var items = await qy.OrderBy(x => x.InsCompanyCode).Take(500)
        .Select(x => new { x.Id, x.InsCompanyCode, x.InsCompanyName, x.FlagActive, x.UpdatedAt }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/insurancecompanies", async (MstInsCompanyDto dto, AppDbContext db, ITenantContext t) =>
{
    var code = (dto.InsCompanyCode ?? "").Trim().ToUpperInvariant();
    if (code.Length == 0) return Results.BadRequest(new { error = "Chưa nhập mã công ty bảo hiểm." });
    var row = await db.MstInsuranceCompanies.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.InsCompanyCode == code);
    if (row is null) { row = new MstInsuranceCompany { OrgId = t.OrgId, InsCompanyCode = code }; db.MstInsuranceCompanies.Add(row); }
    row.InsCompanyName = dto.InsCompanyName;
    if (!string.IsNullOrWhiteSpace(dto.FlagActive)) row.FlagActive = dto.FlagActive!;
    row.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.InsCompanyCode, row.InsCompanyName, row.FlagActive });
}).RequireAuthorization();

// ===== #B172/#B173/#B174 HÃNG BẢO HIỂM theo nguồn **2010.HTC** — `Mst_InsuranceCompanyCreate` /
//       `…Update` / `…Delete` / `…Get` (`_New20181119`, `DataWH/Biz.HTC.WH.cs`) =====
// 🔴🔴 **HAI HỆ CÙNG MỘT BẢNG**: bản port trước (`/api/insurancecompanies`) lấy từ hệ
//   **`ERP.V15.DMSSales.Real`** (cổng `TERP.WSINS`, chỉ có trên máy 150) — xem chú thích ngay trên đó.
//   Lượt này đọc **2010.HTC**, nơi có **BỐN cửa riêng** ở WS64. Hai hệ **khác tập cột**:
//     · bản cũ: `InsCompanyCode` · `InsCompanyName` · `FlagActive` · `UpdatedAt`;
//     · 2010.HTC ghi **TÁM cột**: thêm `Remark` · `CreatedDate` · `CreatedBy` · `LogLUDateTime` · `LogLUBy`.
//   ⇒ **§12 bổ sung 5 cột**, **không** phá endpoint cũ (hai hệ dùng chung một bảng ở MiniHTC).
// **3B khớp cả 2 máy** (căn theo TÊN, lệch **+5** dòng — cùng file với #B159/#B171):
//   `Create 123243,123436 / f28a8cc29145028a22d07b29c1d8b855`
//   `Update 123437,123671 / d6c542f9d0383863b758d0b40b971bd1`
//   `Delete 123672,123883 / 78ec0cae35012b4dd6347afb750016e1`
//   `Get    184446,184628 / 2df4a80f322eddde5d921bfb1d176779`
// 🔴 **`_Create` KHÔNG có guard trùng mã**: chỉ kiểm bảng rỗng (`…_TableDetailBeBlank`),
//   `InsCompanyCode` rỗng (`…_InvalidstrInsCompanyCode` — tên hằng có **`str`** giữa chừng),
//   `InsCompanyName` rỗng (`…_InvalidInsCompanyName`). ⇒ Gọi hai lần cùng mã ⇒ **hai dòng trùng**.
//   Ghi lại, **không tự thêm guard**. Ngoài ra `_Create` **ép `FlagActive = Flag.Active`**.
// 🔴 **`_Update` ghi theo LÔ qua bảng tạm**: `InsertHuge("#tbl_Mst_InsuranceCompany", …)` rồi
//   `update mic set InsCompanyName / FlagActive / Remark / LogLUDateTime / LogLUBy … inner join`.
//   ⇒ **`InsCompanyCode` không nằm trong `set`** ⇒ **khoá bất biến**; `CreatedDate`/`CreatedBy`
//     **không bị đụng** dù bảng tạm mang giá trị mới — **chỉ 5 cột được ghi**.
// 🔴 **`_Delete` XOÁ THẬT** (`delete … from Mst_InsuranceCompany`), không đổi cờ.
// 🔴 Cả ba đường ghi đều chạy **hai lần** (`_dbMain` và `_dbWH`).
app.MapPost("/api/insurancecompanies/htc-create", async (
    InsCompanyHtcSaveDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    if (dto.Rows is null || dto.Rows.Count == 0)
        return Results.BadRequest(new { error = "Mst_InsuranceCompanyCreate_TableDetailBeBlank" });

    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var added = new List<string>();

    foreach (var r in dto.Rows)
    {
        var code = (r.InsCompanyCode ?? "").Trim();
        if (code.Length == 0)
            return Results.BadRequest(new { error = "Mst_InsuranceCompanyCreate_InvalidstrInsCompanyCode" });
        if (string.IsNullOrWhiteSpace(r.InsCompanyName))
            return Results.BadRequest(new { error = "Mst_InsuranceCompanyCreate_InvalidInsCompanyName", check = new { InsCompanyCode = code } });

        // 🔴 KHÔNG kiểm trùng — đúng nguồn. FlagActive bị ÉP = "1".
        db.MstInsuranceCompanies.Add(new MstInsuranceCompany
        {
            OrgId = t.OrgId, InsCompanyCode = code, InsCompanyName = r.InsCompanyName,
            FlagActive = "1", Remark = r.Remark,
            CreatedDate = now, CreatedBy = by, LogLUDateTime = now, LogLUBy = by,
            UpdatedAt = now
        });
        added.Add(code);
    }
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        inserted = added.Count, codes = added,
        noDupGuardNote = "_Create KHONG co guard trung ma: chi kiem bang rong (_TableDetailBeBlank), InsCompanyCode rong (_InvalidstrInsCompanyCode - ten hang co 'str' giua chung), InsCompanyName rong (_InvalidInsCompanyName). Goi hai lan cung ma => HAI DONG TRUNG. Ghi lai, KHONG tu them guard.",
        forcedFlagNote = "_Create EP FlagActive = TERP.Constants.Flag.Active - client gui gi cung bi de.",
        twoSystemsNote = "HAI HE CUNG MOT BANG: ban port truoc (/api/insurancecompanies) lay tu he ERP.V15.DMSSales.Real (cong TERP.WSINS, chi co tren may 150); luot nay doc 2010.HTC voi BON cua rieng. 2010.HTC ghi TAM cot - S12 da bo sung 5 cot con thieu, KHONG pha endpoint cu.",
        twoDbNote = "Nguon InsertHuge hai lan (_dbMain va _dbWH)."
    });
}).RequireAuthorization();

app.MapPost("/api/insurancecompanies/htc-update", async (
    InsCompanyHtcSaveDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    if (dto.Rows is null || dto.Rows.Count == 0)
        return Results.BadRequest(new { error = "Mst_InsuranceCompanyUpdate_TableDetailBeBlank" });

    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var updated = 0; var notFound = new List<string>();

    foreach (var r in dto.Rows)
    {
        var code = (r.InsCompanyCode ?? "").Trim();
        if (code.Length == 0)
            return Results.BadRequest(new { error = "Mst_InsuranceCompanyUpdate_InvalidstrInsCompanyCode" });
        if (string.IsNullOrWhiteSpace(r.InsCompanyName))
            return Results.BadRequest(new { error = "Mst_InsuranceCompanyUpdate_InvalidInsCompanyName", check = new { InsCompanyCode = code } });

        var cur = await db.MstInsuranceCompanies.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.InsCompanyCode == code);
        if (cur is null) { notFound.Add(code); continue; }   // inner join ⇒ không khớp thì bỏ qua

        // 🔴 CHỈ 5 cột trong `set`; InsCompanyCode/CreatedDate/CreatedBy KHÔNG bị đụng.
        cur.InsCompanyName = r.InsCompanyName;
        if (!string.IsNullOrWhiteSpace(r.FlagActive)) cur.FlagActive = r.FlagActive.Trim();
        cur.Remark = r.Remark;
        cur.LogLUDateTime = now; cur.LogLUBy = by;
        updated++;
    }
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        updated, notFound,
        setColumnsNote = "_Update ghi theo LO qua bang tam: InsertHuge('#tbl_Mst_InsuranceCompany', ...) roi 'update mic set mic.InsCompanyName, mic.FlagActive, mic.Remark, mic.LogLUDateTime, mic.LogLUBy from Mst_InsuranceCompany mic inner join #tbl_... t on mic.InsCompanyCode = t.InsCompanyCode'. InsCompanyCode KHONG nam trong set => KHOA BAT BIEN; CreatedDate/CreatedBy KHONG bi dung du bang tam co mang gia tri moi - CHI 5 COT duoc ghi.",
        innerJoinNote = "Dung inner join => ma khong ton tai thi KHONG bao loi, chi la khong co dong nao duoc cap nhat. Port tra notFound de nguoi dung biet.",
        twoDbNote = "Nguon chay cau update hai lan (_dbMain va _dbWH)."
    });
}).RequireAuthorization();

app.MapPost("/api/insurancecompanies/htc-delete", async (
    InsCompanyHtcSaveDto dto, AppDbContext db, ITenantContext t) =>
{
    if (dto.Rows is null || dto.Rows.Count == 0)
        return Results.BadRequest(new { error = "Mst_InsuranceCompanyDelete_TableDetailBeBlank" });

    var codes = dto.Rows.Select(r => (r.InsCompanyCode ?? "").Trim()).Where(c => c.Length > 0).ToList();
    if (codes.Count == 0)
        return Results.BadRequest(new { error = "Mst_InsuranceCompanyDelete_InvalidInsCompanyCode" });

    var rows = await db.MstInsuranceCompanies
        .Where(x => x.OrgId == t.OrgId && codes.Contains(x.InsCompanyCode)).ToListAsync();

    // 🔴 XOÁ THẬT — nguồn `delete … from Mst_InsuranceCompany`, không đổi cờ.
    db.MstInsuranceCompanies.RemoveRange(rows);
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        deleted = rows.Count, codes,
        hardDeleteNote = "_Delete XOA THAT: nap bang tam roi 'delete ... from Mst_InsuranceCompany' - KHONG doi co. Doi chieu #B117 (ham '_Deleted' ben hoa don doi trang thai) - ten khong quyet dinh hanh vi.",
        twoDbNote = "Nguon chay cau delete hai lan (_dbMain va _dbWH)."
    });
}).RequireAuthorization();

// ===== #B175/#B176/#B177 LOẠI BẢO HIỂM theo nguồn **2010.HTC** — `Mst_InsuranceTypeCreate` /
//       `…Update` / `…Delete` (`_New20181119`, `DataWH/Biz.HTC.WH.cs`) =====
// **3B khớp cả 2 máy** (căn theo TÊN, lệch **+5** — cùng file với #B172):
//   `Create 123884,124189 / 8a44dd9728740fbbb06d349c4ee9d443`
//   `Update 124190,124447 / 7dfca81f7c6221682d6b991939f52137`
//   `Delete 124448,124659 / 36b456b4706b72e16259f52bc8ada752`
// 🔴🔴 **KHOÁ LÀ BỘ BA** `(InsCompanyCode, InsTypeCode, EffectiveDate)` — `EffectiveDate` là **phần
//   của khoá**, không phải cột phụ. Cùng công ty + cùng loại nhưng **khác ngày hiệu lực** là **hai
//   bản ghi khác nhau** (mô hình bảng giá theo thời gian).
// 🔴🔴 **`InsTypeCode` là TỪ VỰNG ĐÓNG — chỉ hai giá trị** (`TERP.Constants.InsTypeCode`,
//   `Const.Main.cs:872-876`): **`"MATERIALINS"`** (bảo hiểm vật chất) và
//   **`"TRANSPORTATIONINS"`** (bảo hiểm vận chuyển). Khác đi ⇒ `…_InvalidInsTypeCode01`.
//   ⇒ Đây **không** phải mã tự do; port cho nhập tuỳ ý là **đẻ trạng thái ngoài từ vựng nguồn**.
// 🔴 **NĂM guard ở `_Create`, mỗi cái một mã lỗi** — thứ tự đúng như nguồn:
//   1. bảng rỗng ⇒ `…_TableDetailBeBlank`;
//   2. `Rate` **không parse được double** ⇒ `…_RateNotFormat` (`double.TryParse`);
//   3. `Rate > 100` ⇒ `…_InvalidRate` — ⚠️ **KHÔNG chặn số ÂM** (khác `Mst_InsuranceFee` #B171 chỉ
//      chặn `< 0`, và khác `Mst_CarAllocationByArea` #B166 chặn `[0,100]`) — **ba bảng, ba luật khác nhau**;
//   4. `InsTypeCode.Length < 5` ⇒ `…_InvalidInsTypeCode` (`TConst.HTCConst.MinLengthCode = 5`);
//      **rồi** mới kiểm từ vựng ⇒ `…_InvalidInsTypeCode01`;
//   5. `InsTypeName.Length < 5` ⇒ `…_InvalidInsTypeName` — **tên cũng phải ≥ 5 ký tự**.
// 🔴 `_Create` **ép `FlagActive = Flag.Active`**; `EffectiveDate` chuẩn hoá bằng **`StandardizeDate`**
//   (chỉ ngày), `Rate` qua `GetDoubleValue`.
// 🔴 **`_Update` chỉ ghi 5 cột**: `InsTypeName` · `Rate` · `FlagActive` · `Remark` · `LogLU*`;
//   nối bằng **đủ bộ ba khoá** (`InsCompanyCode` + `InsTypeCode` + `EffectiveDate`) ⇒ **cả ba bất biến**.
// 📌 §12 bổ sung 6 cột (`Rate`, `Remark`, `CreatedDate`, `CreatedBy`, `LogLU*`) vào `MstInsuranceType`
//   **đã có sẵn** — không tạo thực thể thứ hai (luật `C0-…quinquagesimusprimus`).
app.MapPost("/api/insurancetypes/htc-create", async (
    InsTypeHtcSaveDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    if (dto.Rows is null || dto.Rows.Count == 0)
        return Results.BadRequest(new { error = "Mst_InsuranceTypeCreate_TableDetailBeBlank" });

    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var added = 0;

    foreach (var r in dto.Rows)
    {
        // (2) Rate phải parse được.
        if (r.Rate is null)
            return Results.BadRequest(new { error = "Mst_InsuranceTypeCreate_RateNotFormat", check = new { RateValid = "Double" } });
        // (3) CHỈ chặn > 100 — KHÔNG chặn âm (đúng nguồn).
        if (r.Rate > 100)
            return Results.BadRequest(new { error = "Mst_InsuranceTypeCreate_InvalidRate", check = new { r.Rate, RateValid = "< 100" } });

        var code = (r.InsTypeCode ?? "").Trim();
        // (4a) độ dài tối thiểu 5.
        if (code.Length < 5)
            return Results.BadRequest(new { error = "Mst_InsuranceTypeCreate_InvalidInsTypeCode", check = new { InsTypeCode = code, MinLengthCode = "5" } });
        // (4b) TỪ VỰNG ĐÓNG.
        if (!(string.Equals(code, "MATERIALINS", StringComparison.OrdinalIgnoreCase)
              || string.Equals(code, "TRANSPORTATIONINS", StringComparison.OrdinalIgnoreCase)))
            return Results.BadRequest(new
            {
                error = "Mst_InsuranceTypeCreate_InvalidInsTypeCode01",
                check = new { InsTypeCode = code, InsTypeCodeValid = "MATERIALINS | TRANSPORTATIONINS" }
            });

        var name = (r.InsTypeName ?? "").Trim();
        // (5) TÊN cũng phải >= 5 ký tự.
        if (name.Length < 5)
            return Results.BadRequest(new { error = "Mst_InsuranceTypeCreate_InvalidInsTypeName", check = new { InsTypeName = name, MinLengthCode = "5" } });

        db.MstInsuranceTypes.Add(new MstInsuranceType
        {
            OrgId = t.OrgId,
            InsCompanyCode = (r.InsCompanyCode ?? "").Trim(),
            InsTypeCode = code,
            EffectiveDate = (r.EffectiveDate ?? now).Date,   // StandardizeDate ⇒ chỉ NGÀY
            InsTypeName = name,
            Rate = r.Rate,
            FlagActive = "1",                                 // bị ÉP
            Remark = r.Remark,
            CreatedDate = now, CreatedBy = by,
            LogLUDateTime = now, LogLUBy = by,
            UpdatedAt = now
        });
        added++;
    }
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        inserted = added,
        tripleKeyNote = "KHOA LA BO BA (InsCompanyCode, InsTypeCode, EffectiveDate) - EffectiveDate la PHAN CUA KHOA, khong phai cot phu. Cung cong ty + cung loai nhung KHAC NGAY HIEU LUC la HAI BAN GHI KHAC NHAU (mo hinh bang gia theo thoi gian).",
        closedVocabNote = "InsTypeCode la TU VUNG DONG - chi hai gia tri (TERP.Constants.InsTypeCode, Const.Main.cs:872-876): 'MATERIALINS' (bao hiem vat chat) va 'TRANSPORTATIONINS' (bao hiem van chuyen). Khac di => _InvalidInsTypeCode01. Port cho nhap tuy y la DE TRANG THAI NGOAI TU VUNG NGUON.",
        fiveGuardNote = "NAM guard, moi cai mot ma loi: (1) bang rong _TableDetailBeBlank; (2) Rate khong parse duoc double _RateNotFormat; (3) Rate > 100 _InvalidRate - KHONG chan SO AM; (4) InsTypeCode.Length < 5 _InvalidInsTypeCode roi moi kiem tu vung _InvalidInsTypeCode01; (5) InsTypeName.Length < 5 _InvalidInsTypeName - TEN CUNG phai >= 5 ky tu.",
        threeTablesThreeRulesNote = "BA BANG, BA LUAT KHAC NHAU ve nguong: Mst_InsuranceType chan > 100 (khong chan am); Mst_InsuranceFee (#B171) chan < 0 (khong chan > 100); Mst_CarAllocationByArea (#B166) chan [0,100]. Khong suy luat cua bang nay sang bang kia.",
        forcedFlagNote = "_Create EP FlagActive = Flag.Active; EffectiveDate chuan hoa bang StandardizeDate (CHI NGAY); Rate qua GetDoubleValue."
    });
}).RequireAuthorization();

app.MapPost("/api/insurancetypes/htc-update", async (
    InsTypeHtcSaveDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    if (dto.Rows is null || dto.Rows.Count == 0)
        return Results.BadRequest(new { error = "Mst_InsuranceTypeUpdate_TableDetailBeBlank" });

    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var updated = 0; var notFound = new List<object>();

    foreach (var r in dto.Rows)
    {
        var comp = (r.InsCompanyCode ?? "").Trim();
        var code = (r.InsTypeCode ?? "").Trim();
        var eff = (r.EffectiveDate ?? now).Date;

        // 🔴 Nối bằng ĐỦ BỘ BA khoá ⇒ cả ba bất biến.
        var cur = await db.MstInsuranceTypes.FirstOrDefaultAsync(x =>
            x.OrgId == t.OrgId && x.InsCompanyCode == comp && x.InsTypeCode == code && x.EffectiveDate == eff);
        if (cur is null) { notFound.Add(new { comp, code, eff }); continue; }

        // 🔴 CHỈ 5 cột trong `set`.
        cur.InsTypeName = r.InsTypeName;
        cur.Rate = r.Rate;
        if (!string.IsNullOrWhiteSpace(r.FlagActive)) cur.FlagActive = r.FlagActive.Trim();
        cur.Remark = r.Remark;
        cur.LogLUDateTime = now; cur.LogLUBy = by;
        updated++;
    }
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        updated, notFound,
        setColumnsNote = "_Update CHI ghi 5 cot: InsTypeName, Rate, FlagActive, Remark, LogLUDateTime/LogLUBy; noi bang DU BO BA KHOA (InsCompanyCode + InsTypeCode + EffectiveDate) => CA BA BAT BIEN.",
        innerJoinNote = "Dung inner join qua bang tam => bo khoa khong ton tai thi KHONG bao loi, chi la khong dong nao duoc cap nhat. Port tra notFound (luat C0-...quinquagesimussecundus)."
    });
}).RequireAuthorization();

app.MapPost("/api/insurancetypes/htc-delete", async (
    InsTypeHtcSaveDto dto, AppDbContext db, ITenantContext t) =>
{
    if (dto.Rows is null || dto.Rows.Count == 0)
        return Results.BadRequest(new { error = "Mst_InsuranceTypeDelete_TableDetailBeBlank" });

    var deleted = 0;
    foreach (var r in dto.Rows)
    {
        var comp = (r.InsCompanyCode ?? "").Trim();
        var code = (r.InsTypeCode ?? "").Trim();
        var eff = (r.EffectiveDate ?? DateTime.Now).Date;
        var cur = await db.MstInsuranceTypes.FirstOrDefaultAsync(x =>
            x.OrgId == t.OrgId && x.InsCompanyCode == comp && x.InsTypeCode == code && x.EffectiveDate == eff);
        if (cur is null) continue;
        db.MstInsuranceTypes.Remove(cur);   // 🔴 XOÁ THẬT
        deleted++;
    }
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        deleted,
        hardDeleteNote = "XOA THAT (khuon #B174) - nap bang tam roi 'delete ... from Mst_InsuranceType', khong doi co.",
        tripleKeyNote = "Xoa theo DU BO BA khoa (InsCompanyCode, InsTypeCode, EffectiveDate)."
    });
}).RequireAuthorization();

// ===== #B178/#B179/#B180 XE LÁI THỬ theo nguồn **2010.HTC** — `Mst_CarDrvTestCreate` / `…Update`
//       (`_New20181119`, `DataWH/Biz.HTC.WH.cs`) =====
// **3B khớp cả 2 máy** (căn theo TÊN, lệch **+5**):
//   `Create 114902,115189 / ab9fab4b7da45a40f22e1b199e08a1b2`
//   `Update 115190,115484 / 9e75c7f0856f88f6f8cb7e7a5c49bf43`
// 🔴🔴 **HAI HỆ, HAI LUẬT KIỂM — bản port cũ `/api/cardrivertests` lấy từ `DMSales.Foton`**:
//     · **Biển số**: Foton dùng **regex** (`^[0-9]{1,2}[A-Z]{1,2}-[0-9]{4,5}$` …);
//       **2010.HTC** chỉ kiểm **ĐỘ DÀI 7..10** (`Length > 10 || Length < 7` ⇒ `…_InvalidPlateNo`)
//       ⇒ 2010.HTC **chấp nhận** biển số mà regex Foton từ chối, và ngược lại.
//     · **VIN**: Foton bắt **đúng 17**; **2010.HTC** chỉ bắt **`>= 17`** (`Length < 17` mới lỗi)
//       ⇒ VIN **dài hơn 17** được 2010.HTC chấp nhận.
//   ⇒ **Không đồng nhất hai luật**; endpoint này đi theo **đúng nhánh 2010.HTC**, giữ nguyên bản Foton.
// 🔴 **Tiền chỉ kiểm KHI KHÁC RỖNG, và là `Int64` — không phải số thực**:
//   `if (str != null && str != "") { if (!Int64.TryParse(str, out _)) throw …_InvalidPrice/…Support1/…Support2; }`
//   ⇒ **bỏ trống là hợp lệ**; **số âm KHÔNG bị chặn**; số thập phân **bị từ chối** (parse `Int64`).
// 🔴🔴 **`_Update`: VIN và MODEL BẤT BIẾN** — dòng
//   `//dt_Mst_CarDriverTest.Rows[0]["DrvTestVIN"] = strDrvTestVIN; alColumnEffective.Add("DrvTestVIN");`
//   **bị comment**, và `ModelCode` **không có** trong `alColumnEffective`.
//   ⇒ Sửa được: `DealerCode` · `SpecCode` · `ColorCode` · `FlagActive` · `Remark` · `DrvTestEngineNo` ·
//     `Price` · `AmountSupport1/2` · `DateSupport1/2` · `ClaimNoSupport` · `CarDrvTestGPS` (**12 cột**).
//   ⇒ Khoá thao tác là **`DrvTestPlateNo`**; không tồn tại ⇒ `…_Update_PlateNoNotFound`.
app.MapPost("/api/cardrivertests/htc-create", async (
    CarDrvTestHtcDto dto, AppDbContext db, ITenantContext t) =>
{
    // 🔴 Tiền: chỉ kiểm khi KHÁC RỖNG; phải là số nguyên (Int64); KHÔNG chặn âm.
    static bool BadMoney(string? s) => !string.IsNullOrEmpty(s) && !long.TryParse(s, out _);
    if (BadMoney(dto.Price))
        return Results.BadRequest(new { error = "Mst_CarDrvTestCreate_InvalidPrice", check = new { dto.Price } });
    if (BadMoney(dto.AmountSupport1))
        return Results.BadRequest(new { error = "Mst_CarDrvTestCreate_InvalidAmountSupport1", check = new { dto.AmountSupport1 } });
    if (BadMoney(dto.AmountSupport2))
        return Results.BadRequest(new { error = "Mst_CarDrvTestCreate_InvalidAmountSupport2", check = new { dto.AmountSupport2 } });

    var vin = (dto.DrvTestVIN ?? "").Trim();
    // 🔴 2010.HTC: VIN chỉ cần >= 17 (KHÁC bản Foton bắt đúng 17).
    if (vin.Length < 17)
        return Results.BadRequest(new { error = "Mst_CarDrvTestCreate_InvalidVIN", check = new { DrvTestVIN = vin, MinLength = 17 } });

    var plate = (dto.DrvTestPlateNo ?? "").Trim();
    // 🔴 2010.HTC: biển số chỉ kiểm ĐỘ DÀI 7..10 (KHÔNG regex).
    if (plate.Length > 10 || plate.Length < 7)
        return Results.BadRequest(new { error = "Mst_CarDrvTestCreate_InvalidPlateNo", check = new { DrvTestPlateNo = plate, ValidLength = "7..10" } });

    var row = new CarDriverTest
    {
        OrgId = t.OrgId,
        DrvTestPlateNo = plate, DrvTestVIN = vin,
        DealerCode = dto.DealerCode, ModelCode = dto.ModelCode, SpecCode = dto.SpecCode,
        ColorCode = dto.ColorCode, DrvTestEngineNo = dto.DrvTestEngineNo,
        FlagActive = string.IsNullOrWhiteSpace(dto.FlagActive) ? "1" : dto.FlagActive.Trim(),
        Remark = dto.Remark, ClaimNoSupport = dto.ClaimNoSupport, CarDrvTestGPS = dto.CarDrvTestGPS,
        Price = string.IsNullOrEmpty(dto.Price) ? 0m : long.Parse(dto.Price),
        AmountSupport1 = string.IsNullOrEmpty(dto.AmountSupport1) ? 0m : long.Parse(dto.AmountSupport1),
        AmountSupport2 = string.IsNullOrEmpty(dto.AmountSupport2) ? 0m : long.Parse(dto.AmountSupport2),
        DateSupport1 = dto.DateSupport1, DateSupport2 = dto.DateSupport2
    };
    db.CarDriverTests.Add(row);
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        row.DrvTestPlateNo, row.DrvTestVIN, row.ModelCode, row.SpecCode, row.ColorCode,
        twoSystemsNote = "HAI HE, HAI LUAT KIEM. Ban port cu /api/cardrivertests lay tu DMSales.Foton: bien so dung REGEX, VIN bat DUNG 17. Nguon 2010.HTC: bien so chi kiem DO DAI 7..10 (_InvalidPlateNo), VIN chi bat >= 17 (Length < 17 moi loi) => 2010.HTC CHAP NHAN bien so ma regex Foton tu choi, va chap nhan VIN dai hon 17. KHONG dong nhat hai luat; endpoint nay di theo dung nhanh 2010.HTC, giu nguyen ban Foton.",
        moneyGuardNote = "Tien CHI KIEM KHI KHAC RONG va la Int64 - khong phai so thuc: 'if (str != null && str != \"\") { if (!Int64.TryParse(...)) throw ...; }'. => BO TRONG LA HOP LE; SO AM KHONG BI CHAN; so thap phan BI TU CHOI."
    });
}).RequireAuthorization();

