        keyNote = "Khoa thao tac la DrvTestPlateNo; khong ton tai => _Update_PlateNoNotFound.",
        noVinGuardNote = "_Update KHONG kiem lai do dai VIN/bien so (chi _Create kiem) - vi VIN bat bien va bien so la khoa tra cuu."
    });
}).RequireAuthorization();



// ===== #B183 NGÂN HÀNG CỦA ĐẠI LÝ — `Mst_DealerBankGet_New20181119` (`:184080`) — ĐỐI CHIẾU PARITY =====
// **3B khớp cả 2 máy** (căn theo tên, lệch **+5**): `184080,184268 / d325bbb7fde5c0dbea499261c4c615c5`.
// 📌 Màn **đã port** (`/api/dealerbanks`, entity `DealerBank` đủ cột). Lượt này đọc nguồn để đối chiếu:
// 🔴 Nguồn `select mdb.* from Mst_DealerBank mdb **inner join Mst_Bank mb on mb.BankCode = mdb.BankCode**`
//   ⇒ **`inner join`**: dòng có `BankCode` **không tồn tại** trong `Mst_Bank` sẽ **biến mất khỏi kết quả**
//     — không phải `left join`. Bản port cũ đọc thẳng bảng ⇒ **hiện cả dòng mồ côi**.
//   ⇒ Bổ sung endpoint đối chiếu để thấy **chênh lệch số dòng** giữa hai cách.
// 🔴 Nguồn trả **một bảng** tên `Mst_DealerBank`, có tiền tố bí danh **`mdb.`** cho cột và join thêm
//   `Mst_CarSpec` ở khối cột phụ.
app.MapGet("/api/dealerbanks/htc-paged", async (
    AppDbContext db, ITenantContext t, string? dealerCode, string? bankCode,
    int? recordStart, int? recordCount) =>
{
    var q = db.DealerBanks.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealerCode)) q = q.Where(x => x.DealerCode == dealerCode.Trim());
    if (!string.IsNullOrWhiteSpace(bankCode)) q = q.Where(x => x.BankCode == bankCode.Trim());
    var all = await q.OrderBy(x => x.DealerCode).ThenBy(x => x.BankCode).ToListAsync();

    var banks = (await db.MstBanks.Where(b => b.OrgId == t.OrgId)
        .Select(b => new { b.BankCode, b.BankName }).ToListAsync())
        .GroupBy(b => b.BankCode).ToDictionary(g => g.Key, g => g.First().BankName);

    // 🔴 INNER JOIN như nguồn: dòng có BankCode không tồn tại trong Mst_Bank BỊ LOẠI.
    var joined = all.Where(x => banks.ContainsKey(x.BankCode)).ToList();
    var orphans = all.Where(x => !banks.ContainsKey(x.BankCode))
        .Select(x => new { x.DealerCode, x.BankCode }).ToList();

    var myCount = joined.Count;
    var start = recordStart ?? 0;
    var count = recordCount ?? myCount;
    var page = joined.Skip(start).Take(count <= 0 ? myCount : count).ToList();

    return Results.Ok(new
    {
        MySummaryTable = new[] { new { MyCount = myCount } },
        Mst_DealerBank = page.Select((x, i) => new
        {
            MyIdxSeq = start + i,
            mdb_DealerCode = x.DealerCode, mdb_BankCode = x.BankCode,
            mdb_BankBranchCode = x.BankBranchCode, mdb_BankBranchName = x.BankBranchName,
            mdb_CreditContractNo = x.CreditContractNo, mdb_CreditContractDate = x.CreditContractDate,
            mdb_CreditAmount = x.CreditAmount, mdb_FlagBankGrt = x.FlagBankGrt,
            mdb_FlagBankPmt = x.FlagBankPmt, mdb_FlagActive = x.FlagActive, mdb_Remark = x.Remark,
            mb_BankName = banks[x.BankCode]
        }),
        rowsBeforeJoin = all.Count,
        orphanRows = orphans,
        innerJoinNote = "Nguon dung INNER JOIN Mst_Bank on mb.BankCode = mdb.BankCode => dong co BankCode KHONG TON TAI trong Mst_Bank se BIEN MAT khoi ket qua - khong phai left join. Ban port cu (/api/dealerbanks) doc thang bang => HIEN CA DONG MO COI. Endpoint nay tra rowsBeforeJoin va orphanRows de thay chenh lech.",
        aliasNote = "Nguon tra MOT bang ten 'Mst_DealerBank', cot mang tien to bi danh 'mdb.'."
    });
}).RequireAuthorization();

// `insCompanyPattern` = quyền của người dùng công ty BH (nguồn dùng `like`); bỏ trống = xem tất cả (nội bộ HTC).
app.MapGet("/api/insurancetypes", async (
    AppDbContext db, ITenantContext t, string? insCompanyPattern, string? company, string? active) =>
{
    var qy = db.MstInsuranceTypes.Where(x => x.OrgId == t.OrgId);
    if (active != "all") qy = qy.Where(x => x.FlagActive == "1");
    if (!string.IsNullOrWhiteSpace(company)) qy = qy.Where(x => x.InsCompanyCode == company);
    if (!string.IsNullOrWhiteSpace(insCompanyPattern))
    {
        var pat = insCompanyPattern!.Trim().Replace("%", "");
        qy = qy.Where(x => x.InsCompanyCode.Contains(pat));
    }
    var items = await qy
        .OrderBy(x => x.InsTypeCode).ThenByDescending(x => x.EffectiveDate).Take(500)
        .Select(x => new { x.Id, x.InsCompanyCode, x.InsTypeCode, x.EffectiveDate, x.InsTypeName, x.FlagActive, x.UpdatedAt })
        .ToListAsync();
    // Nguồn LEFT JOIN Mst_InsuranceCompany để lấy tên công ty.
    var names = await db.MstInsuranceCompanies.Where(c => c.OrgId == t.OrgId)
        .ToDictionaryAsync(c => c.InsCompanyCode, c => c.InsCompanyName);
    return Results.Ok(new { count = items.Count,
        items = items.Select(i => new { i.Id, i.InsCompanyCode,
            insCompanyName = names.ContainsKey(i.InsCompanyCode) ? names[i.InsCompanyCode] : null,
            i.InsTypeCode, i.EffectiveDate, i.InsTypeName, i.FlagActive, i.UpdatedAt }) });
}).RequireAuthorization();

// Upsert theo ĐÚNG khoá BỘ BA của nguồn: công ty + mã loại + NGÀY HIỆU LỰC.
app.MapPost("/api/insurancetypes", async (MstInsTypeDto dto, AppDbContext db, ITenantContext t) =>
{
    var comp = (dto.InsCompanyCode ?? "").Trim().ToUpperInvariant();
    var type = (dto.InsTypeCode ?? "").Trim().ToUpperInvariant();
    if (comp.Length == 0) return Results.BadRequest(new { error = "Chưa nhập mã công ty bảo hiểm." });
    if (type.Length == 0) return Results.BadRequest(new { error = "Chưa nhập mã loại hình bảo hiểm." });
    if (dto.EffectiveDate is null) return Results.BadRequest(new { error = "Chưa nhập ngày hiệu lực (là PHẦN CỦA KHOÁ)." });
    var eff = dto.EffectiveDate.Value.Date;

    var row = await db.MstInsuranceTypes.FirstOrDefaultAsync(x => x.OrgId == t.OrgId
        && x.InsCompanyCode == comp && x.InsTypeCode == type && x.EffectiveDate == eff);
    if (row is null)
    {
        row = new MstInsuranceType { OrgId = t.OrgId, InsCompanyCode = comp, InsTypeCode = type, EffectiveDate = eff };
        db.MstInsuranceTypes.Add(row);
    }
    row.InsTypeName = dto.InsTypeName;
    if (!string.IsNullOrWhiteSpace(dto.FlagActive)) row.FlagActive = dto.FlagActive!;
    row.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.InsCompanyCode, row.InsTypeCode, row.EffectiveDate, row.InsTypeName });
}).RequireAuthorization();

app.MapGet("/api/insurancereqs", async (AppDbContext db, ITenantContext t, string? status, string? company, string? insCompanyPattern) =>
{
    var q = db.InsuranceReqs.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(r => r.Status == status);
    if (!string.IsNullOrWhiteSpace(company)) q = q.Where(r => r.InsCompanyCode == company);
    // 🔴 RBAC của nguồn (TERP.BizInsurance/InsReq.cs): người dùng công ty bảo hiểm CHỈ thấy dữ liệu
    // của công ty mình — nguồn lọc bằng PATTERN `InsCompanyCode like @strAbilityOfUser`.
    // Port cũ KHÔNG có tầng lọc này ở BẤT KỲ đường đọc nào.
    if (!string.IsNullOrWhiteSpace(insCompanyPattern)) { var _p = insCompanyPattern!.Trim().Replace("%", ""); q = q.Where(r => r.InsCompanyCode.Contains(_p)); }
    var items = await q.OrderByDescending(r => r.Id).Take(500).Select(r => new
    {
        r.InsReqNo, r.InsCompanyCode, r.InsTypeCode, r.Status, r.CreatedAt, r.ConfirmedAt,
        cars = db.InsuranceReqDtls.Count(c => c.OrgId == t.OrgId && c.InsuranceReqId == r.Id),
        totalAmount = db.InsuranceReqDtls.Where(c => c.OrgId == t.OrgId && c.InsuranceReqId == r.Id).Sum(c => (decimal?)c.InsAmount) ?? 0
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/insurancereqs", async (InsuranceReqDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.InsCompanyCode)) return Results.BadRequest(new { error = "Phải chọn hãng bảo hiểm." });
    if (string.IsNullOrWhiteSpace(dto.InsTypeCode)) return Results.BadRequest(new { error = "Phải chọn loại hình bảo hiểm." });
    var cars = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.VIN)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "VIN không để trống." });
    var dupe = cars.GroupBy(c => c.VIN.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });
    var no = "INS" + DateTime.Now.ToString("yyMMddHHmmss");
    var r = new InsuranceReq { OrgId = t.OrgId, InsReqNo = no, InsCompanyCode = dto.InsCompanyCode.Trim(), InsTypeCode = dto.InsTypeCode.Trim(), Status = "P" };
    db.InsuranceReqs.Add(r); await db.SaveChangesAsync();
    foreach (var c in cars)
        db.InsuranceReqDtls.Add(new InsuranceReqDtl { OrgId = t.OrgId, InsuranceReqId = r.Id, VIN = c.VIN.Trim().ToUpperInvariant(), ExpectedStartDate = c.ExpectedStartDate, InsAmount = c.InsAmount, InsuranceDay = c.InsuranceDay, LocationFrom = c.LocationFrom, LocationTo = c.LocationTo, Price = c.Price, Rate = c.Rate, TransporterCode = c.TransporterCode, Remark = c.Remark });
    await db.SaveChangesAsync();
    return Results.Ok(new { r.InsReqNo, cars = cars.Count });
}).RequireAuthorization();

