// ===== #B07 VÒNG ĐỜI THẬT CỦA PHIẾU BẢO TRÌ — BỐN BƯỚC, HAI TRỤC ĐỘC LẬP =====
// Nguồn `BizHTC.StorageFG.Frm.cs`: `StoF_Maintain_Save` (106) → `_Approve` (740) → `_SaveEval` (1011)
//   → `_ApproveEval` (1523); WS gọi đúng bốn hàm này (`WSHTC.asmx.cs:16253/16326/16395/16465`).
// 🔴 Port cũ chỉ có Save + một nút `/complete` **tự chế**: đặt header `Status="Done"` (bảng nguồn KHÔNG có
//    cột `Status`) và đặt **`MtnStatusMain = "C"`** — `TConst.MtnStatus` chỉ có **"P"/"A"**, không có "C".
//    Hậu quả THẬT: guard bảo dưỡng gia hạn (#B06) đòi `MtnStatusMain = "A"` ⇒ mọi phiếu đi qua `/complete`
//    đều **không bao giờ vào được bảo dưỡng gia hạn**. `/complete` đã bị GỠ, thay bằng ba bước dưới đây.
app.MapPost("/api/stofmaintains/{no}/approve", async (string no, StoFMaintainStepDto? dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.StoFMaintains.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SfMtnNo == no);
    if (m is null) return Results.NotFound(new { no });
    // `StoF_Maintain_CheckDB(..., MtnStatus.Pending, MtnEvalStatus.Pending)` (:817-818) — cả HAI trục phải "P".
    if (m.MtnStatus != "P") return Results.BadRequest(new { error = "Phiếu không ở trạng thái chờ duyệt (MtnStatus phải = 'P')." });
    if (m.MtnEvalStatus != "P") return Results.BadRequest(new { error = "Phiếu đã duyệt đánh giá (MtnEvalStatus phải = 'P')." });
    var who = user.Identity?.Name ?? "system"; var now = DateTime.Now;
    // 8 cột của `zzB_Update_StoF_Maintain_ClauseSet_zzE` (:872-880) — LU* lấy CHÍNH mốc duyệt.
    m.MtnStatus = "A"; m.ApproveDateTime = now; m.ApproveBy = who;
    m.LUDateTime = now; m.LUBy = who; m.LogLUDateTime = now; m.LogLUBy = who;
    if (!string.IsNullOrWhiteSpace(dto?.Remark)) m.Remark = dto!.Remark;
    // 🔴 Duyệt phiếu GHI LAN XUỐNG hai bảng con: `MtnStatusMain = MtnStatus` (:898) và
    //    `MtnStatusMix = MtnStatus` (:919) — port cũ không có bước lan này.
    var mains = await db.StoFMaintainMains.Where(c => c.OrgId == t.OrgId && c.StoFMaintainId == m.Id).ToListAsync();
    foreach (var c in mains) { c.MtnStatusMain = "A"; c.LogLUDateTime = now; c.LogLUBy = who; }
    var mixes = await db.StoFMaintainMixes.Where(c => c.OrgId == t.OrgId && c.SF_MtnNo == no).ToListAsync();
    foreach (var c in mixes) { c.MtnStatusMix = "A"; c.LogLUDateTime = now; c.LogLUBy = who; }
    await db.SaveChangesAsync();
    return Results.Ok(new { m.SfMtnNo, m.MtnStatus, m.MtnEvalStatus, m.ApproveDateTime, m.ApproveBy, mains = mains.Count, mixes = mixes.Count });
}).RequireAuthorization();

// Nhập kết quả đánh giá (`StoF_Maintain_SaveEval_New20181115`, :1011) — guard MtnStatus="A" + MtnEvalStatus="P".
app.MapPost("/api/stofmaintains/{no}/save-eval", async (string no, StoFMaintainEvalDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.StoFMaintains.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SfMtnNo == no);
    if (m is null) return Results.NotFound(new { no });
    if (m.MtnStatus != "A") return Results.BadRequest(new { error = "Phiếu chưa duyệt (MtnStatus phải = 'A')." });
    if (m.MtnEvalStatus != "P") return Results.BadRequest(new { error = "Phiếu đã duyệt đánh giá (MtnEvalStatus phải = 'P')." });
    var who = user.Identity?.Name ?? "system"; var now = DateTime.Now;
    var mains = await db.StoFMaintainMains.Where(c => c.OrgId == t.OrgId && c.StoFMaintainId == m.Id).ToListAsync();
    int updated = 0;
    foreach (var line in dto.Lines ?? new())
    {
        if (string.IsNullOrWhiteSpace(line.VIN)) continue;
        var vin = line.VIN!.Trim().ToUpperInvariant();
        var c = mains.FirstOrDefault(x => x.VIN == vin);
        if (c is null) continue;
        // Nguồn đặt `MtnStatusMain = MtnStatus.Approve` cho dòng đánh giá (:1236).
        c.MtnStatusMain = "A";
        c.BeforeMtnStatusMain = line.BeforeMtnStatusMain ?? c.BeforeMtnStatusMain;
        c.AfterMtnStatusMain = line.AfterMtnStatusMain ?? c.AfterMtnStatusMain;
        c.UserCodeMtn = line.UserCodeMtn ?? c.UserCodeMtn;
        c.MapLatitude = line.MapLatitude ?? c.MapLatitude;
        c.MapLongitude = line.MapLongitude ?? c.MapLongitude;
        c.Remark = line.Remark ?? c.Remark;
        c.LogLUDateTime = now; c.LogLUBy = who;
        updated++;
    }
    if (updated == 0) return Results.BadRequest(new { error = "Không có dòng VIN nào khớp phiếu để ghi đánh giá." });
    m.LUDateTime = now; m.LUBy = who; m.LogLUDateTime = now; m.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { m.SfMtnNo, updated, m.MtnStatus, m.MtnEvalStatus });
}).RequireAuthorization();

// Duyệt đánh giá (`StoF_Maintain_ApproveEval_New20181115`, :1523) — guard giống SaveEval.
app.MapPost("/api/stofmaintains/{no}/approve-eval", async (string no, StoFMaintainStepDto? dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.StoFMaintains.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SfMtnNo == no);
    if (m is null) return Results.NotFound(new { no });
    if (m.MtnStatus != "A") return Results.BadRequest(new { error = "Phiếu chưa duyệt (MtnStatus phải = 'A')." });
    if (m.MtnEvalStatus != "P") return Results.BadRequest(new { error = "Phiếu đã duyệt đánh giá rồi (MtnEvalStatus phải = 'P')." });
    var who = user.Identity?.Name ?? "system"; var now = DateTime.Now;
    // 8 cột của `ClauseSet` (:1655-1663) — LU* lấy chính mốc duyệt đánh giá.
    m.MtnEvalStatus = "A"; m.ApproveEvalDateTime = now; m.ApproveEvalBy = who;
    m.LUDateTime = now; m.LUBy = who; m.LogLUDateTime = now; m.LogLUBy = who;
    if (!string.IsNullOrWhiteSpace(dto?.Remark)) m.Remark = dto!.Remark;
    // Giữ tương thích ngược với trục BỊA cũ để dữ liệu/khách hàng cũ không vỡ.
    m.Status = "Done"; m.DoneAt = now;

    // ===== #B08 TRẢ NỢ #B07: side-effect `myVIN_MaintainPeriod_UpdX` của `_ApproveEval` =====
    // Nguồn (`BizHTC.StorageFG.Frm.cs:1700-1731`) đọc mọi dòng `StoF_MaintainMain` của phiếu rồi gọi
    // `myVIN_MaintainPeriod_UpdX(..., TConst.RefTypeMtn.Mtn, ...)`; hàm đó rẽ nhánh theo RefType, nhánh
    // `Mtn` chạy `myVIN_MaintainPeriod_UpdMtnX` (`BizHTC.StorageFG.cs:1414`) ghi lịch sử bảo dưỡng theo VIN.
    // 🔴 HẰNG ≠ GIÁ TRỊ: `TConst.RefTypeMtn.Mtn` = **"MAINTAINANCE"** — nguồn viết SAI CHÍNH TẢ đúng như vậy
    //    (`Const.Main.StorageFG.1.cs:22`); ghi "Mtn" hoặc "MAINTENANCE" đều làm mọi truy vấn trượt câm.
    var mainsEval = await db.StoFMaintainMains.Where(c => c.OrgId == t.OrgId && c.StoFMaintainId == m.Id).ToListAsync();
    var evalVins = mainsEval.Select(c => c.VIN).Distinct().ToList();
    // `dblMtnTimes = <MtnTimes hiện tại của VIN> + 1` (BizHTC.StorageFG.cs:1479).
    var lastTimes = await db.CarMaintenances
        .Where(x => x.OrgId == t.OrgId && x.MtnType == "MAINTAINANCE" && evalVins.Contains(x.Vin))
        .GroupBy(x => x.Vin).Select(g => new { Vin = g.Key, Max = g.Max(x => x.MtnTimes) }).ToListAsync();
    foreach (var c in mainsEval)
    {
        var prevTimes = lastTimes.FirstOrDefault(x => x.Vin == c.VIN)?.Max ?? 0;
        db.CarMaintenances.Add(new CarMaintenance
        {
            OrgId = t.OrgId, Vin = c.VIN,
            StorageCode = c.StorageCodeCurrent, ModelCode = c.ModelCode,
            MtnType = "MAINTAINANCE",          // GIÁ TRỊ của TConst.RefTypeMtn.Mtn, không phải tên hằng
            RefNo = m.SfMtnNo,                 // nguồn: `t.SF_MtnNo RefNo` (Frm.cs:1706)
            MtnTimes = prevTimes + 1,
            MtnDate = now,                     // `MtnLastDate` = mốc duyệt đánh giá
            // `MtnNextDate = MtnLastDate + TConst.StorageMtnVINFG.Default_QtyDateMtn` = **+15 ngày**
            // (`Const.Main.StorageFG.1.cs:10`) — hằng THẬT của nguồn, không suy đoán chu kỳ.
            MtnNextDate = now.AddDays(15),
            UserCode = c.UserCodeMtn, Remark = c.Remark
        });
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { m.SfMtnNo, m.MtnStatus, m.MtnEvalStatus, m.ApproveEvalDateTime, m.ApproveEvalBy,
        maintainHistRows = mainsEval.Count,
        note = "Sau bước này các dòng có MtnStatusMain='A' mới đủ điều kiện vào bảo dưỡng gia hạn (/api/maintext)." });
}).RequireAuthorization();

// ===== Master xe lái thử (CarDriverTest — port 1:1 FrmMstCarDriverTestHTC/Dealer, DMSales.Foton/RetailContract) =====
app.MapGet("/api/cardrivertests", async (AppDbContext db, ITenantContext t, string? dealer, string? model, string? active) =>
{
    var q = db.CarDriverTests.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(c => c.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(model)) q = q.Where(c => c.ModelCode == model);
    if (!string.IsNullOrWhiteSpace(active)) q = q.Where(c => c.FlagActive == active);
    var items = await q.OrderByDescending(c => c.Id).Take(500).Select(c => new
    {
        c.DrvTestPlateNo, c.DealerCode, c.DrvTestVIN, c.DrvTestEngineNo, c.ModelCode, c.SpecCode, c.ColorCode, c.FlagActive,
        c.Price, c.AmountSupport1, c.DateSupport1, c.AmountSupport2, c.DateSupport2, c.ClaimNoSupport, c.Remark, c.CarDrvTestGPS
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/cardrivertests", async (CarDriverTestDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DrvTestPlateNo)) return Results.BadRequest(new { error = "Biển số không hợp lệ." });
    // audit 2026-09-03: bổ sung guard đúng nguồn FrmMstCarDriverTestHTC.gviewOrderDetail_ValidateRow (regex biển số 2 dạng + VIN đúng 17 ký tự)
    var plateCheck = dto.DrvTestPlateNo.Trim();
    if (!System.Text.RegularExpressions.Regex.IsMatch(plateCheck, @"^[0-9]{1}[0-9]{0,1}[A-Z]{1,2}-[0-9]{4,5}$") &&
        !System.Text.RegularExpressions.Regex.IsMatch(plateCheck, @"^[A-Z]{2}-[0-9]{4,5}$"))
        return Results.BadRequest(new { error = "Biển số không hợp lệ" });
    if (!string.IsNullOrWhiteSpace(dto.DrvTestVIN) && dto.DrvTestVIN.Trim().Length != 17)
        return Results.BadRequest(new { error = "Số VIN không hợp lệ" });
    if (string.IsNullOrWhiteSpace(dto.ModelCode)) return Results.BadRequest(new { error = "Chưa nhập Model." });
    if (string.IsNullOrWhiteSpace(dto.SpecCode)) return Results.BadRequest(new { error = "Chưa nhập Spec." });
    if (string.IsNullOrWhiteSpace(dto.ColorCode)) return Results.BadRequest(new { error = "Chưa nhập Màu." });
    // audit 2026-09-03: nguồn (btnSave_Click) chỉ báo lỗi khi Date1 > Date2 (Date1==Date2 hợp lệ) — port trước chặn cả trường hợp bằng nhau (sai, chặt hơn nguồn)
    if (dto.DateSupport1 is not null && dto.DateSupport2 is not null && dto.DateSupport1 > dto.DateSupport2)
        return Results.BadRequest(new { error = "Ngày hỗ trợ đợt 2 phải lớn hơn Ngày hỗ trợ đợt 1" });
    var plate = dto.DrvTestPlateNo.Trim().ToUpperInvariant();
    if (await db.CarDriverTests.AnyAsync(c => c.OrgId == t.OrgId && c.DrvTestPlateNo == plate))
        return Results.BadRequest(new { error = $"Biển số {plate} đã tồn tại (trùng)!" });
    var c = new CarDriverTest
    {
        OrgId = t.OrgId, DrvTestPlateNo = plate, DealerCode = (dto.DealerCode ?? "").Trim().ToUpperInvariant(), DrvTestVIN = dto.DrvTestVIN, DrvTestEngineNo = dto.DrvTestEngineNo,
        ModelCode = dto.ModelCode.Trim(), SpecCode = dto.SpecCode.Trim(), ColorCode = dto.ColorCode.Trim(), Remark = dto.Remark, FlagActive = dto.FlagActive == "0" ? "0" : "1",
        CarDrvTestGPS = dto.CarDrvTestGPS, Price = dto.Price, AmountSupport1 = dto.AmountSupport1, DateSupport1 = dto.DateSupport1, AmountSupport2 = dto.AmountSupport2, DateSupport2 = dto.DateSupport2, ClaimNoSupport = dto.ClaimNoSupport
    };
    db.CarDriverTests.Add(c); await db.SaveChangesAsync();
    return Results.Ok(new { c.DrvTestPlateNo, message = "Thêm mới thành công" });
}).RequireAuthorization();

app.MapPost("/api/cardrivertests/{plate}/toggle", async (string plate, AppDbContext db, ITenantContext t) =>
{
    plate = plate.Trim().ToUpperInvariant();
    var c = await db.CarDriverTests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DrvTestPlateNo == plate);
    if (c is null) return Results.NotFound(new { plate });
    c.FlagActive = c.FlagActive == "1" ? "0" : "1";
    await db.SaveChangesAsync();
    return Results.Ok(new { c.DrvTestPlateNo, flagActive = c.FlagActive });
}).RequireAuthorization();

// ===== #B62 HOP NHAT THUC THE SONG TRUNG (ca thu 6) =====
// `CtmVisit` (DMSales.Foton `DLR_CtmVisit`) va `CustomerVisit` (2010.HTC `Dlr_CtmVisit`) la
// **CUNG MOT BANG NGUON**: cung khoa `CusVisitCode`, cung cot DealerCode/Gender/ModelCode, chi khac
// ten cot do tuoi (`RangeAge` vs `RangeAgeCode`). Truoc luot nay CA HAI deu duoc GHI
// (`db.CtmVisits.Add` va `db.CustomerVisits.Add`) => luot khach vao HAI BANG KHAC NHAU tuy endpoint,
// nen bao cao pivot (#B62 `RptPivot_DlrCtmVisit`) chi thay mot nua du lieu du nguoi dung nhap dung.
// Nay ca hai endpoint tro chung ve **`CustomerVisits`** - chon bang nay vi cot `RangeAgeCode` khop
// dung khoa join cua nguon 2010.HTC (`Mst_CtmRangeAge.RangeAgeCode`). `CtmVisit` giu lai nhung
// KHONG con duoc ghi (cung tien le voi `WholesaleDeal` o #B09).
app.MapGet("/api/ctmvisits", async (AppDbContext db, ITenantContext t, string? dealer, string? model) =>
{
    var q = db.CustomerVisits.Where(v => v.OrgId == t.OrgId);   // #B62 tro chung bang
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(v => v.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(model)) q = q.Where(v => v.ModelCode == model);
    var items = await q.OrderByDescending(v => v.Id).Take(500).Select(v => new { v.CusVisitCode, v.DealerCode, v.Gender, RangeAge = v.RangeAgeCode, v.ModelCode, v.CreatedAt }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/ctmvisits", async (CtmVisitDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.ModelCode)) return Results.BadRequest(new { error = "Hãy chọn loại xe khách quan tâm." });
    if (string.IsNullOrWhiteSpace(dto.Gender)) return Results.BadRequest(new { error = "Hãy chọn giới tính." });
    if (string.IsNullOrWhiteSpace(dto.RangeAge)) return Results.BadRequest(new { error = "Hãy chọn độ tuổi." });
    var code = "CV" + DateTime.Now.ToString("yyMMddHHmmssfff");
    var v = new CustomerVisit { OrgId = t.OrgId, CusVisitCode = code, DealerCode = (dto.DealerCode ?? "").Trim().ToUpperInvariant(), Gender = dto.Gender.Trim(), RangeAgeCode = dto.RangeAge.Trim(), ModelCode = dto.ModelCode.Trim() };
    db.CustomerVisits.Add(v); await db.SaveChangesAsync();   // #B62 tro chung bang
    return Results.Ok(new { v.CusVisitCode, message = "Thêm mới lượt khách thăm showroom thành công" });
}).RequireAuthorization();

// ===== Lượt khách lái thử (DriveTest — port 1:1 FrmNewTestDriver, DMSales.Foton/RetailContract) =====
app.MapGet("/api/drivetests", async (AppDbContext db, ITenantContext t, string? dealer, string? model, string? phone, string? status) =>
{
    var q = db.DriveTests.Where(d => d.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(d => d.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(model)) q = q.Where(d => d.TestModelCode == model);
    if (!string.IsNullOrWhiteSpace(phone)) q = q.Where(d => d.PhoneNo.Contains(phone));
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(d => d.DriverTestStatus == status);
    var items = await q.OrderByDescending(d => d.Id).Take(500).Select(d => new { d.DriveTestCode, d.DealerCode, d.DriverTestType, d.DrvTestPlateNo, d.TestModelCode, d.DriveDate, d.CustomerName, d.PhoneNo, d.DriverLicenseNo, d.DriverTestStatus, d.ApprovedBy, d.ApprovedDate }).ToListAsync();
    return Results.Ok(new { count = items.Count, pending = items.Count(x => x.DriverTestStatus == "P"), items });
}).RequireAuthorization();

// Quản lý lái thử: xác nhận KH (P->A) / huỷ (P->R) — port 1:1 FrmMngTestDriver (DLR_DriveTestApprove).
// 🔴 DUYỆT / TỪ CHỐI — `DLR_DriveTestApprove_New20181119` (Biz.HTC.WH.cs:106928-107045).
// Nguồn dùng MỘT hàm với cờ **NGHỊCH ĐẢO** `strFlagUnapprove`: `Flag.Inactive("0")` ⇒ **DUYỆT ("A")`,
// ngược lại ⇒ "R"; và ghi `ApprovedDate`/`ApprovedBy` cho **CẢ HAI** nhánh (port cũ chỉ đổi cờ).
// Tên action đổi `confirm`→`approve` cho khớp tên hàm nguồn (giữ `confirm` như bí danh để không vỡ UI cũ).
app.MapPost("/api/drivetests/{code}/{action}", async (string code, string action, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (action is not ("approve" or "confirm" or "reject")) return Results.BadRequest(new { error = "action = approve|reject" });
    var d = await db.DriveTests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DriveTestCode == code);
    if (d is null) return Results.NotFound(new { code });
    if (d.DriverTestStatus != "P") return Results.BadRequest(new { error = "Lượt lái thử không ở trạng thái chờ (P)." });
    d.DriverTestStatus = action == "reject" ? "R" : "A";
    d.ApprovedDate = DateTime.Now;
    d.ApprovedBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    await db.SaveChangesAsync();
    return Results.Ok(new { d.DriveTestCode, d.DriverTestStatus, d.ApprovedBy, d.ApprovedDate });
}).RequireAuthorization();

// 🔴 SỬA lượt lái thử — `DLR_DriveTestUpdate_New20181119` (106538-106760).
// ⚠️ Luật rẽ theo **LOẠI lái thử** (`TConst.DriverTestType`): với loại **"HTC"**, biển số xe lái thử
//    PHẢI tồn tại trong master `Mst_CarDriverTest` và còn `FlagActive='1'` (lỗi `PlateNoNotFound`);
//    loại **"DEALER"** thì KHÔNG kiểm. Port cũ không có màn sửa nên mất hẳn luật này.
app.MapPost("/api/drivetests/{code}", async (string code, DriveTestUpdateDto dto, AppDbContext db, ITenantContext t) =>
{
    var d = await db.DriveTests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DriveTestCode == code);
    if (d is null) return Results.NotFound(new { code });
    var plate = (dto.DrvTestPlateNo ?? "").Trim();
    var model = (dto.TestModelCode ?? d.TestModelCode).Trim();
    if (string.Equals(d.DriverTestType, "HTC", StringComparison.OrdinalIgnoreCase))
    {
        if (plate.Length == 0) return Results.BadRequest(new { error = "Lái thử xe HTC phải chọn biển số xe lái thử." });
        var okPlate = await db.CarDriverTests.AnyAsync(x => x.OrgId == t.OrgId && x.DrvTestPlateNo == plate && x.ModelCode == model && x.FlagActive == "1");
        if (!okPlate) return Results.BadRequest(new { error = $"Không tìm thấy xe lái thử biển số {plate} (model {model}) đang hoạt động." });
    }
    if (dto.DriveDate is not null && dto.DriveDate.Value.Date > DateTime.Now.Date)
        return Results.BadRequest(new { error = "Ngày lái thử phải nhỏ hơn hoặc là Ngày hiện tại." });
    if (plate.Length > 0) d.DrvTestPlateNo = plate;
    if (!string.IsNullOrWhiteSpace(dto.TestModelCode)) d.TestModelCode = model;
    if (dto.DriveDate is not null) d.DriveDate = dto.DriveDate.Value;
    if (dto.CustomerName is not null) d.CustomerName = dto.CustomerName.Trim();
    if (dto.PhoneNo is not null) d.PhoneNo = dto.PhoneNo.Trim();
    if (dto.Address is not null) d.Address = dto.Address.Trim();
    if (dto.Email is not null) d.Email = dto.Email;
    await db.SaveChangesAsync();
    return Results.Ok(new { d.DriveTestCode, d.DrvTestPlateNo, d.TestModelCode, d.DriveDate });
}).RequireAuthorization();

// 🔴 XOÁ — `DLR_DriveTestDel_New20181115` (187383): guard trạng thái **"P,R"** ⇒ lượt **đã duyệt ("A")
// KHÔNG xoá được**, nhưng lượt đã từ chối thì xoá được.
app.MapDelete("/api/drivetests/{code}", async (string code, AppDbContext db, ITenantContext t) =>
{
    var d = await db.DriveTests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DriveTestCode == code);
    if (d is null) return Results.NotFound(new { code });
    if (d.DriverTestStatus is not ("P" or "R"))
        return Results.BadRequest(new { error = "Chỉ xoá được lượt lái thử đang chờ (P) hoặc đã từ chối (R)." });
    db.DriveTests.Remove(d);
    await db.SaveChangesAsync();
    return Results.Ok(new { code });
}).RequireAuthorization();

app.MapPost("/api/drivetests", async (DriveTestDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DriverTestType)) return Results.BadRequest(new { error = "Phải chọn loại lái thử." });
    if (string.IsNullOrWhiteSpace(dto.TestModelCode)) return Results.BadRequest(new { error = "Hãy chọn loại xe khách quan tâm." });
    if (dto.DriveDate is null) return Results.BadRequest(new { error = "Hãy chọn Ngày lái thử." });
    if (dto.DriveDate.Value.Date > DateTime.Now.Date) return Results.BadRequest(new { error = "Ngày lái thử phải nhỏ hơn hoặc là Ngày hiện tại." });
    if (string.IsNullOrWhiteSpace(dto.PhoneNo)) return Results.BadRequest(new { error = "Hãy nhập Số điện thoại." });
    if (!dto.PhoneNo.All(char.IsDigit)) return Results.BadRequest(new { error = "Số điện thoại chỉ được nhập số." });
    if (string.IsNullOrWhiteSpace(dto.Address)) return Results.BadRequest(new { error = "Hãy nhập Địa chỉ." });
    if (string.IsNullOrWhiteSpace(dto.CustomerName)) return Results.BadRequest(new { error = "Hãy nhập Họ tên Khách hàng." });
    if (string.IsNullOrWhiteSpace(dto.DriverLicenseNo)) return Results.BadRequest(new { error = "Phải nhập GPLX." });
    if (dto.DriverLicenseNo.Any(ch => !char.IsLetterOrDigit(ch))) return Results.BadRequest(new { error = "GPLX không được nhập ký tự đặc biệt." });
    if (!string.IsNullOrWhiteSpace(dto.Email) && !(dto.Email.Contains('@') && dto.Email.Contains('.'))) return Results.BadRequest(new { error = "Email không hợp lệ." });
    // 🔴 Loại "HTC" bắt buộc biển số nằm trong master xe lái thử còn hoạt động (`Mst_CarDriverTest`),
    //    theo đúng guard `DLR_DriveTestUpdate`; loại "DEALER" không kiểm.
    if (string.Equals(dto.DriverTestType.Trim(), "HTC", StringComparison.OrdinalIgnoreCase))
    {
        var plate0 = (dto.DrvTestPlateNo ?? "").Trim();
        if (plate0.Length == 0) return Results.BadRequest(new { error = "Lái thử xe HTC phải chọn biển số xe lái thử." });
        var ok0 = await db.CarDriverTests.AnyAsync(x => x.OrgId == t.OrgId && x.DrvTestPlateNo == plate0 && x.ModelCode == dto.TestModelCode.Trim() && x.FlagActive == "1");
        if (!ok0) return Results.BadRequest(new { error = $"Không tìm thấy xe lái thử biển số {plate0} (model {dto.TestModelCode.Trim()}) đang hoạt động." });
    }
    var code = "DT" + DateTime.Now.ToString("yyMMddHHmmssfff");
    var d = new DriveTest
    {
        OrgId = t.OrgId, DriveTestCode = code, DealerCode = (dto.DealerCode ?? "").Trim().ToUpperInvariant(), DriverTestType = dto.DriverTestType.Trim(),
        DrvTestPlateNo = dto.DrvTestPlateNo, TestModelCode = dto.TestModelCode.Trim(), DriveDate = dto.DriveDate.Value, CustomerCode = dto.CustomerCode,
        CustomerName = dto.CustomerName.Trim(), PhoneNo = dto.PhoneNo.Trim(), Address = dto.Address.Trim(), DriverLicenseNo = dto.DriverLicenseNo.Trim(), RangeAge = dto.RangeAge, Email = dto.Email
    };
    db.DriveTests.Add(d); await db.SaveChangesAsync();
    return Results.Ok(new { d.DriveTestCode, message = "Thêm mới lượt khách lái thử xe thành công" });
}).RequireAuthorization();

// ===== Hợp đồng bán lẻ (DlrContract — port 1:1 FrmNewRetailContract/FrmMngRetailContractHTC, DMSales.Foton/RetailContract) =====
app.MapGet("/api/dlrcontracts", async (AppDbContext db, ITenantContext t, string? status, string? dealer, string? customer) =>
{
    var q = db.DlrContracts.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(c => c.Status == status);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(c => c.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(customer)) q = q.Where(c => c.CustomerCode == customer || c.CustomerName.Contains(customer));
    var items = await q.OrderByDescending(c => c.Id).Take(500).Select(c => new
    {
        c.DlrContractNo, c.DlrContractNoUser, c.DealerCode, c.SalesManCode, c.SalesType, c.CustomerName, c.SignDate, c.Status,
        c.ApproveBy, c.ApproveDTime, c.CancelBy, c.CancelDTime, c.FinishBy, c.FinishDTime,
        lines = db.DlrContractDetails.Count(l => l.OrgId == t.OrgId && l.ContractId == c.Id),
        total = db.DlrContractDetails.Where(l => l.OrgId == t.OrgId && l.ContractId == c.Id).Sum(l => (decimal?)l.TotalAmountAfterVAT) ?? 0
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/dlrcontracts", async (DlrContractDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (string.IsNullOrWhiteSpace(dto.DlrContractNoUser)) return Results.BadRequest(new { error = "Phải nhập số hợp đồng người dùng." });
    if (string.IsNullOrWhiteSpace(dto.SalesManCode)) return Results.BadRequest(new { error = "Hãy chọn nhân viên bán hàng." });
    if (string.IsNullOrWhiteSpace(dto.SalesType)) return Results.BadRequest(new { error = "Phải chọn kiểu bán lẻ." });
    if (string.IsNullOrWhiteSpace(dto.CustomerName)) return Results.BadRequest(new { error = "Hãy chọn khách hàng." });
    if (string.IsNullOrWhiteSpace(dto.IDCardNo)) return Results.BadRequest(new { error = "Khách hàng chưa có Số giấy tờ tùy thân." });
    if (string.IsNullOrWhiteSpace(dto.IDCardType)) return Results.BadRequest(new { error = "Khách hàng chưa có Loại giấy tờ tùy thân." });
    if (dto.DateOfBirth is null) return Results.BadRequest(new { error = "Khách hàng chưa có Ngày sinh nhật/ thành lập Công ty." });
    if (dto.SignDate is null) return Results.BadRequest(new { error = "Chưa chọn Ngày ký HĐ." });
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.ModelCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 dòng model." });
    if (lines.Any(l => l.Qty <= 0)) return Results.BadRequest(new { error = "Số lượng phải > 0." });
    var no = "DLC" + DateTime.Now.ToString("yyMMddHHmmss");
    var c = new DlrContract
    {
        OrgId = t.OrgId, DlrContractNo = no, DlrContractNoUser = dto.DlrContractNoUser.Trim(), DealerCode = (dto.DealerCode ?? "").Trim().ToUpperInvariant(),
        SalesManCode = dto.SalesManCode.Trim(), SalesType = dto.SalesType.Trim(), CustomerCode = (dto.CustomerCode ?? "").Trim().ToUpperInvariant(),
        CustomerName = dto.CustomerName.Trim(), IDCardNo = dto.IDCardNo.Trim(), IDCardType = dto.IDCardType.Trim(), DateOfBirth = dto.DateOfBirth.Value,
        SignDate = dto.SignDate.Value, BankCode = dto.BankCode
    };
    db.DlrContracts.Add(c); await db.SaveChangesAsync();
    var whoCtr = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var ctrCarSeq = 1;   // đếm chung toàn hợp đồng, đúng mẫu "{SốHĐ}.{j:00}" của nguồn
    // 🔴 #130: nguồn đặt MỐC PHIÊN BẢN ở phần đầu rồi ghi CÙNG giá trị đó vào mọi dòng lịch sử
    //    (Biz.HTC.WH.cs:93118 và 93290) ⇒ nhóm theo mốc này dựng lại được nguyên trạng từng phiên bản.
    var versionStamp = DateTime.Now;
    c.VersionDTimeCurr = versionStamp;
    foreach (var l in lines)
    {
        var amountVat = l.Price * l.Qty * l.VAT / 100m;
        var totalAfter = l.Price * l.Qty + amountVat;
        // 🔴 #129 parity Dlr_ContractDtl: bổ sung khoá nghiệp vụ + loại cập nhật + dấu vết sửa
        //    (Biz.HTC.WH.cs:93222-93238, bản SellToDealer_New20230306).
        db.DlrContractDetails.Add(new DlrContractDetail
        {
            OrgId = t.OrgId, ContractId = c.Id,
            DlrContractNo = c.DlrContractNo,
            ContractUpdateType = null,          // nguồn để NULL khi tạo
            ModelCode = l.ModelCode.Trim(), SpecCode = l.SpecCode, ColorCode = l.ColorCode,
            Qty = l.Qty, DlvExpectedDate = l.DlvExpectedDate,
            Price = l.Price, VAT = l.VAT, AmountVAT = amountVat, TotalAmountAfterVAT = totalAfter,
            LogLUDateTime = DateTime.Now, LogLUBy = whoCtr,
        });

        // 🔴 #130 ghi lịch sử dòng (`Dlr_ContractDtlHis`, Biz.HTC.WH.cs:93285-93305): snapshot dòng
        //    theo PHIÊN BẢN — mang `VersionDTimeCurr` bằng đúng mốc của phần đầu. KHÔNG có cặp Old/New.
        //    `ContractUpdateType` để NULL vì đây là bản ghi lúc TẠO (chỉ hàm SỬA mới truyền giá trị).
        db.DlrContractDtlHiss.Add(new DlrContractDtlHis
        {
            OrgId = t.OrgId, VersionDTimeCurr = versionStamp,
            DlrContractNo = c.DlrContractNo,
            SpecCode = l.SpecCode, ModelCode = l.ModelCode.Trim(), ColorCode = l.ColorCode,
            Qty = l.Qty,
            ContractUpdateType = null,
            UpdateBy = whoCtr, DlvExpectedDate = l.DlvExpectedDate,
            LogLUDateTime = DateTime.Now, LogLUBy = whoCtr,
        });

        // 🔴 #129 NỞ DÒNG THEO TỪNG XE sang `Dlr_ContractCar` (Biz.HTC.WH.cs:93240-93280) —
        //    bảng này CHỈ có ở bản SellToDealer_New20230306 mà WS 64-bit gọi; bản 2018 (WS 32-bit) không có.
        //    Một dòng Dtl có Qty = 3 ⇒ sinh 3 dòng ở đây, `CtrCarId` = "<SốHĐ>.01/.02/.03" (2 chữ số).
        for (var j = 1; j <= l.Qty; j++)
            db.DlrContractCars.Add(new DlrContractCar
            {
                OrgId = t.OrgId, DlrContractNo = c.DlrContractNo,
                CtrCarId = $"{c.DlrContractNo}.{ctrCarSeq++:00}",
                SpecCode = l.SpecCode, ModelCode = l.ModelCode.Trim(), ColorCode = l.ColorCode,
                DlvExpectedDate = l.DlvExpectedDate,
                FlagCancel = "0", FlagDelivery = "0",   // TConst.Flag.Inactive
                LogLUDateTime = DateTime.Now, LogLUBy = whoCtr,
            });
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { c.DlrContractNo, c.CustomerName, lines = lines.Count });
}).RequireAuthorization();

// ===== PHIẾU HUỶ hợp đồng bán lẻ (Dlr_ContractCancel + Dtl + Car) =====
// Nguồn: `BizHTC.Contract.cs` — `Dlr_ContractCancel_SaveX_New20230306` (2375), ghi 3 bảng tại
// 2976 / 3010 / 3042; csproj `<Compile>` 110 ⇒ LIVE. md5 647641a1 khớp nguyên file 2 máy.
// 🔴 MỎ MỚI (#136): ba bảng này ghi bằng `insert into … select`, **KHÔNG qua `SaveData`** ⇒ lệnh kiểm kê
//    ở #117 không bắt được. Mỏ `insert…select` có **241 bảng chưa port**.
// 🔴 TWIN: cụm `Dlr_ContractCancel_*` **chỉ có ở WS 64-bit**; WS 32-bit chỉ có hàm cũ
//    `ContractDealerContractCancel_New20181119` → `_SaveX` (1726) **không ghi bảng `…CancelCar`**.
//    Ca thứ NĂM dạng "chỉ 64-bit", và lặp đúng mẫu #129: bản mới **ghi thêm cả một bảng**.
// 🔴 `ContractCancelStatus` lấy từ `TConst.ContractCancelStatus` ở **`Const.Main.DMS40.cs:140-145`**
//    ("P"/"A"/"C") — hằng nằm ở file DMS40, không phải `Const.Main.cs`.
// 🔴 Huỷ ở **MỨC TỪNG XE**: `…CancelCar.CtrCarId` trỏ về dòng xe của hợp đồng gốc (`Dlr_ContractCar`, #129),
//    trong khi `…CancelDtl` chỉ gộp nhóm theo model.
app.MapGet("/api/dlrcontractcancels", async (AppDbContext db, ITenantContext t, string? contractCNo, string? dealerCode, string? status) =>
{
    var qy = db.DlrContractCancels.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(contractCNo)) qy = qy.Where(x => x.ContractCNo == contractCNo);
    if (!string.IsNullOrWhiteSpace(dealerCode)) qy = qy.Where(x => x.DealerCode == dealerCode);
    if (!string.IsNullOrWhiteSpace(status)) qy = qy.Where(x => x.ContractCancelStatus == status);
    var items = await qy.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.ContractCNo, x.DealerCode, x.ContractCancelStatus, x.Remark,
        x.CreatedDate, x.CreatedBy, x.LUDateTime, x.LUBy, x.ApprovedDate, x.ApprovedBy,
        x.LogLUDateTime, x.LogLUBy,
    }).ToListAsync();
    var nos = items.Select(i => i.ContractCNo).ToList();
    var dtls = await db.DlrContractCancelDtls.Where(d => d.OrgId == t.OrgId && nos.Contains(d.ContractCNo))
        .Select(d => new
        {
            d.ContractCNo, d.DlrContractNo, d.SpecCode, d.ModelCode, d.ColorCode,
            d.ContractUpdateType, d.Qty, d.ContractCancelDtlStatus, d.Remark, d.LogLUDateTime, d.LogLUBy,
        }).ToListAsync();
    var cars = await db.DlrContractCancelCars.Where(c => c.OrgId == t.OrgId && nos.Contains(c.ContractCNo))
        .Select(c => new
        {
            c.ContractCNo, c.DlrContractNo, c.SpecCode, c.ModelCode, c.ColorCode,
            c.CtrCarId, c.DlvExpectedDate, c.CtrCType, c.CtrCTDNo, c.Remark, c.LogLUDateTime, c.LogLUBy,
        }).ToListAsync();
    return Results.Ok(new { count = items.Count, items, details = dtls, cars });
}).RequireAuthorization();

app.MapPost("/api/dlrcontractcancels/save", async (DlrContractCancelSaveDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var no = (dto.ContractCNo ?? "").Trim();
    var dealer = (dto.DealerCode ?? "").Trim();
    if (no.Length < 1) return Results.BadRequest(new { error = "Số phiếu huỷ rỗng." });
    if (dealer.Length < 1) return Results.BadRequest(new { error = "Chưa chọn đại lý." });
    var head = await db.DlrContractCancels.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ContractCNo == no);
    if (head is not null && head.ContractCancelStatus != "P")
        return Results.BadRequest(new { error = $"Phiếu đang '{head.ContractCancelStatus}', chỉ sửa được khi 'P'." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var isNew = head is null;
    if (isNew)
    {
        head = new DlrContractCancel
        {
            OrgId = t.OrgId, ContractCNo = no, DealerCode = dealer,
            ContractCancelStatus = "P", CreatedDate = now, CreatedBy = who,
        };
        db.DlrContractCancels.Add(head);
    }
    head!.Remark = dto.Remark;
    head.LUDateTime = now; head.LUBy = who;
    head.LogLUDateTime = now; head.LogLUBy = who;

    // Thay thế trọn bộ dòng của phiếu (nguồn xoá rồi insert … select lại).
    db.DlrContractCancelDtls.RemoveRange(
        await db.DlrContractCancelDtls.Where(d => d.OrgId == t.OrgId && d.ContractCNo == no).ToListAsync());
    db.DlrContractCancelCars.RemoveRange(
        await db.DlrContractCancelCars.Where(c => c.OrgId == t.OrgId && c.ContractCNo == no).ToListAsync());

    foreach (var d in dto.Details ?? new())
        db.DlrContractCancelDtls.Add(new DlrContractCancelDtl
        {
            OrgId = t.OrgId, ContractCNo = no, DlrContractNo = (d.DlrContractNo ?? "").Trim(),
            SpecCode = d.SpecCode, ModelCode = d.ModelCode, ColorCode = d.ColorCode,
            ContractUpdateType = d.ContractUpdateType, Qty = d.Qty,
            ContractCancelDtlStatus = "P", Remark = d.Remark,
            LogLUDateTime = now, LogLUBy = who,
        });
    foreach (var c in dto.Cars ?? new())
        db.DlrContractCancelCars.Add(new DlrContractCancelCar
        {
            OrgId = t.OrgId, ContractCNo = no, DlrContractNo = (c.DlrContractNo ?? "").Trim(),
            SpecCode = c.SpecCode, ModelCode = c.ModelCode, ColorCode = c.ColorCode,
            CtrCarId = (c.CtrCarId ?? "").Trim(), DlvExpectedDate = c.DlvExpectedDate,
            CtrCType = c.CtrCType,      // loại huỷ — nguồn cho phép để trống (dòng 2725)
            CtrCTDNo = c.CtrCTDNo, Remark = c.Remark,
            LogLUDateTime = now, LogLUBy = who,
        });
    await db.SaveChangesAsync();

    // ===== 🔴 #198 SIDE-EFFECT bị bỏ sót: HỢP ĐỒNG TỰ CHUYỂN "HOÀN THÀNH" =====
    // Nguồn: `TERP.BizHTC/BizHTC.Contract.cs` — khối `// Upd: Dlr_Contract.DlrCtrStatus.` (3244-3298)
    //   nằm BÊN TRONG `Dlr_ContractCancel_SaveX_New20230306` (2375).
    //   BƯỚC 3B: md5 cả file `647641a1`, md5 vùng hàm 2375-3310 `6c93a6b1` — KHỚP 2 máy.
    //
    // 🔴 `DlrCtrStatus = "F"` KHÔNG PHẢI một hành động người dùng bấm: đây là **chỗ DUY NHẤT** trong toàn
    //    `TERP.BizHTC` đặt giá trị "F" (đã grep: 3282 là hit duy nhất; các chỗ khác chỉ đặt P/A/C).
    //    Hợp đồng tự "hoàn thành" khi lưu phiếu huỷ xe mà SAU đó hợp đồng **không còn xe nào chưa xử lý**.
    //
    // Điều kiện của nguồn, dịch từ 3 bảng tạm:
    //   `#tblDlr_Contract`        = các `DlrContractNo` xuất hiện trong DANH SÁCH XE của phiếu vừa lưu;
    //   `#tblDlr_Contract_NotUpd` = trong số đó, HĐ nào CÒN ít nhất một xe `FlagCancel <> '1'`
    //                               **và** `FlagDelivery <> '1'` (xe chưa huỷ và cũng chưa giao);
    //   `#tblDlr_Contract_Upd`    = phần còn lại ⇒ set `DlrCtrStatus = 'F'` + `LogLUBy`/`LogLUDateTime`.
    //   ⇒ Chỉ xét các HĐ CÓ MẶT trên phiếu này, không quét toàn bảng.
    var finishedContracts = new List<string>();
    var ctrNos = (dto.Cars ?? new()).Select(c => (c.DlrContractNo ?? "").Trim())
                                    .Where(x => x.Length > 0).Distinct().ToList();
    foreach (var ctrNo in ctrNos)
    {
        var stillOpen = await db.DlrContractCars.AnyAsync(x => x.OrgId == t.OrgId && x.DlrContractNo == ctrNo
                                                            && x.FlagCancel != "1" && x.FlagDelivery != "1");
        if (stillOpen) continue;
        var ctr = await db.DlrContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrContractNo == ctrNo);
        if (ctr is null) continue;
        ctr.Status = "F";                       // `TConst.DlrCtrStatus1.Finish`
        ctr.LogLUDateTime = now; ctr.LogLUBy = who;
        finishedContracts.Add(ctrNo);
    }
    if (finishedContracts.Count > 0) await db.SaveChangesAsync();

    return Results.Ok(new { no, created = isNew, details = (dto.Details ?? new()).Count,
                            cars = (dto.Cars ?? new()).Count, finishedContracts });
}).RequireAuthorization();

// `ApproveMulti` / `CancelMulti` của nguồn — duyệt/huỷ NHIỀU phiếu trong một lệnh.
app.MapPost("/api/dlrcontractcancels/approvemulti", async (DlrContractCancelMultiDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
    await DlrCancelSetStatus(dto, "A", db, t, user)).RequireAuthorization();

app.MapPost("/api/dlrcontractcancels/cancelmulti", async (DlrContractCancelMultiDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
    await DlrCancelSetStatus(dto, "C", db, t, user)).RequireAuthorization();

// Thân chung: nguồn có hai hàm riêng nhưng chỉ khác giá trị đích ("A" vs "C"); cả hai đòi phiếu đang "P".
async Task<IResult> DlrCancelSetStatus(DlrContractCancelMultiDto dto, string target, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user)
{
    var nos = (dto.ContractCNos ?? new()).Select(x => (x ?? "").Trim()).Where(x => x.Length > 0).Distinct().ToList();
    if (nos.Count == 0) return Results.BadRequest(new { error = "Chưa chọn phiếu nào." });
    var rows = await db.DlrContractCancels.Where(x => x.OrgId == t.OrgId && nos.Contains(x.ContractCNo)).ToListAsync();
    var missing = nos.Except(rows.Select(r => r.ContractCNo)).ToList();
    if (missing.Count > 0) return Results.BadRequest(new { error = $"Không có phiếu: {string.Join(", ", missing.Take(10))}." });
    var bad = rows.Where(r => r.ContractCancelStatus != "P").Select(r => $"{r.ContractCNo}({r.ContractCancelStatus})").ToList();
    if (bad.Count > 0) return Results.BadRequest(new { error = $"Phiếu không ở 'P': {string.Join(", ", bad.Take(10))}." });

    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    foreach (var r in rows)
    {
        r.ContractCancelStatus = target;
        r.ApprovedDate = now; r.ApprovedBy = who;   // nguồn ghi chung cột này cho cả duyệt lẫn huỷ
        r.LogLUDateTime = now; r.LogLUBy = who;
    }
    var dtls = await db.DlrContractCancelDtls.Where(d => d.OrgId == t.OrgId && nos.Contains(d.ContractCNo)).ToListAsync();
    foreach (var d in dtls) { d.ContractCancelDtlStatus = target; d.LogLUDateTime = now; d.LogLUBy = who; }
    await db.SaveChangesAsync();
    return Results.Ok(new { count = rows.Count, status = target, detailsSynced = dtls.Count });
}

// ===== HẠNG MỤC gói bảo dưỡng (Mst_MaintainTaskItem) =====
// Port 1:1 cụm 4 hàm `_Create/_Update/_Delete/_Get_New20181119` (Biz.HTC.WH.cs:7236).
// TWIN: cả hai bit khớp hoàn toàn (5/5 hàm, kể cả `Mst_MaintainTask_Get` của bảng cha).
// ⚠️ Bảng cha `Mst_MaintainTask` CHỈ có hàm `_Get` ⇒ danh mục gói bảo dưỡng do DBA nạp; chỉ hạng mục
//    bên trong mới sửa được qua ứng dụng.
// 🔴 `FlagActive` nguồn LUÔN đặt "1" khi tạo, không nhận từ đầu vào.
app.MapGet("/api/maintaintaskitems", async (AppDbContext db, ITenantContext t, string? mtnTkCode, string? flagActive) =>
{
    var qy = db.MstMaintainTaskItems.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(mtnTkCode)) qy = qy.Where(x => x.MtnTkCode == mtnTkCode);
    if (!string.IsNullOrWhiteSpace(flagActive)) qy = qy.Where(x => x.FlagActive == flagActive);
    var items = await qy.OrderBy(x => x.MtnTkCode).ThenBy(x => x.ViewIdx).Select(x => new
    { x.MtnTkCode, x.MtnTkItemCode, x.MtnTkItemName, x.ViewIdx, x.FlagActive }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/maintaintaskitems/create", async (MaintainTaskItemDto dto, AppDbContext db, ITenantContext t) =>
{
    var tk = (dto.MtnTkCode ?? "").Trim();
    var item = (dto.MtnTkItemCode ?? "").Trim();
    if (tk.Length < 1) return Results.BadRequest(new { error = "Mã gói bảo dưỡng rỗng." });
    if (item.Length < 1) return Results.BadRequest(new { error = "Mã hạng mục rỗng." });
    if (await db.MstMaintainTaskItems.AnyAsync(x => x.OrgId == t.OrgId && x.MtnTkCode == tk && x.MtnTkItemCode == item))
        return Results.BadRequest(new { error = $"Hạng mục {item} đã có trong gói {tk}." });
    db.MstMaintainTaskItems.Add(new MstMaintainTaskItem
    {
        OrgId = t.OrgId, MtnTkCode = tk, MtnTkItemCode = item,
        MtnTkItemName = dto.MtnTkItemName, ViewIdx = dto.ViewIdx,
        FlagActive = "1",   // nguồn luôn đặt Flag.Active khi tạo
    });
    await db.SaveChangesAsync();
    return Results.Ok(new { mtnTkCode = tk, mtnTkItemCode = item });
}).RequireAuthorization();

app.MapPost("/api/maintaintaskitems/update", async (MaintainTaskItemDto dto, AppDbContext db, ITenantContext t) =>
{
    var tk = (dto.MtnTkCode ?? "").Trim();
    var item = (dto.MtnTkItemCode ?? "").Trim();
    var row = await db.MstMaintainTaskItems.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MtnTkCode == tk && x.MtnTkItemCode == item);
    if (row is null) return Results.NotFound(new { error = $"Gói {tk} không có hạng mục {item}." });
    row.MtnTkItemName = dto.MtnTkItemName;
    row.ViewIdx = dto.ViewIdx;
    if (!string.IsNullOrWhiteSpace(dto.FlagActive)) row.FlagActive = dto.FlagActive!;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.MtnTkCode, row.MtnTkItemCode, row.ViewIdx, row.FlagActive });
}).RequireAuthorization();

app.MapPost("/api/maintaintaskitems/delete", async (MaintainTaskItemKeyDto dto, AppDbContext db, ITenantContext t) =>
{
    var tk = (dto.MtnTkCode ?? "").Trim();
    var item = (dto.MtnTkItemCode ?? "").Trim();
    var row = await db.MstMaintainTaskItems.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MtnTkCode == tk && x.MtnTkItemCode == item);
    if (row is null) return Results.NotFound(new { error = $"Gói {tk} không có hạng mục {item}." });
    db.MstMaintainTaskItems.Remove(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = $"{tk}/{item}" });
}).RequireAuthorization();

// ===== CẤU HÌNH KỲ BÁO CÁO kế hoạch bán lẻ (St_SettingRptPlanRetail) =====
// Port 1:1 `St_SettingRptPlanRetail_Create` (BizHTC.Report.cs:35073).
// 🔴 Cụm CHỈ có ở WS 64-bit — ca thứ TƯ cùng dạng (sau #131, #132, #133).
// 🔴 `PlanTimes` TỰ TĂNG: nguồn lấy bản ghi mới nhất cùng `PlanMonth` (order by PlanTimes desc) rồi +1;
//    chưa có bản nào thì "1" (dòng 35127-35145) ⇒ mỗi tháng có thể chốt kế hoạch NHIỀU LẦN, đánh số 1,2,3…
//    KHÔNG nhận `PlanTimes` từ client.
// `ReportDate` là ngày chốt số liệu của lần đó — chính là mốc mà báo cáo `Rpt_PlanRetail` (#100) dùng.
app.MapGet("/api/settingrptplanretail", async (AppDbContext db, ITenantContext t, string? planMonth, string? flagActive) =>
{
    var qy = db.StSettingRptPlanRetails.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(planMonth)) qy = qy.Where(x => x.PlanMonth == planMonth);
    if (!string.IsNullOrWhiteSpace(flagActive)) qy = qy.Where(x => x.FlagActive == flagActive);
    var items = await qy.OrderByDescending(x => x.PlanMonth).ThenByDescending(x => x.Id).Select(x => new
    { x.PlanMonth, x.PlanTimes, x.ReportDate, x.FlagActive, x.CreateDTime, x.CreateBy, x.LogLUDateTime, x.LogLUBy })
    .ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/settingrptplanretail/create", async (SettingRptPlanRetailDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var month = (dto.PlanMonth ?? "").Trim();
    if (month.Length < 1) return Results.BadRequest(new { error = "Tháng kế hoạch rỗng." });

    // 🔴 PlanTimes tự tăng theo tháng, đúng như nguồn: lấy bản mới nhất của tháng rồi +1; chưa có thì "1".
    var last = await db.StSettingRptPlanRetails
        .Where(x => x.OrgId == t.OrgId && x.PlanMonth == month)
        .OrderByDescending(x => x.Id).FirstOrDefaultAsync();
    var planTimes = "1";
    if (last is not null && int.TryParse(last.PlanTimes, out var n)) planTimes = (n + 1).ToString();

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    db.StSettingRptPlanRetails.Add(new StSettingRptPlanRetail
    {
        OrgId = t.OrgId, PlanMonth = month, PlanTimes = planTimes,
        ReportDate = dto.ReportDate,
        FlagActive = "1",
        CreateDTime = now, CreateBy = who, LogLUDateTime = now, LogLUBy = who,
    });
    await db.SaveChangesAsync();
    return Results.Ok(new { planMonth = month, planTimes, note = "PlanTimes do server tự tăng theo tháng, đúng như nguồn." });
}).RequireAuthorization();

// ===== KẾ HOẠCH SẢN XUẤT THEO NGÀY (WO_ScheduleDetailDate) — tầng thứ BA của cụm lịch SX =====
// Nguồn: `BizHTC.WorkOrder.cs:563`, trong `WO_Schedule_Add_New20181115` (174).
// TWIN: cả hai bit khớp hoàn toàn (5/5 hàm). csproj `<Compile>` 134 ⇒ LIVE. md5 khớp nguyên file 2 máy.
// 🔴 Port cũ mới có HAI tầng: `WO_Schedule` (đầu) và `WO_ScheduleDetail` (theo model/spec/màu, tổng SL).
//    Tầng này rải kế hoạch ra TỪNG NGÀY (`PlanDate` + `QtyPlan`) — thiếu nó thì chỉ biết tổng,
//    không biết kế hoạch nằm ở ngày nào.
// 🔴 Guard nguồn: `QtyPlan` âm ⇒ LỖI; `QtyPlan == 0` ⇒ `continue`, **KHÔNG ghi dòng** (dòng 544)
//    ⇒ ngày không có kế hoạch thì KHÔNG tồn tại dòng, chứ không phải dòng mang số 0.
// ⚠️ Cả ba bảng của cụm chỉ ghi `_dbMain`, KHÔNG có `_dbWH` (561-564) — khác đa số cụm khác.
app.MapGet("/api/woscheduledates", async (AppDbContext db, ITenantContext t, string? workOrderNo, DateTime? from, DateTime? to) =>
{
    var qy = db.WoScheduleDetailDates.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(workOrderNo)) qy = qy.Where(x => x.WorkOrderNo == workOrderNo);
    if (from is not null) qy = qy.Where(x => x.PlanDate >= from);
    if (to is not null) qy = qy.Where(x => x.PlanDate <= to);
    var items = await qy.OrderBy(x => x.PlanDate).ThenBy(x => x.WorkOrderNo).Select(x => new
    {
        x.WorkOrderNo, x.SpecCode, x.ModelCode, x.ColorCode, x.PlanDate, x.QtyPlan, x.CreatedDate,
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items, totalQty = items.Sum(i => i.QtyPlan) });
}).RequireAuthorization();

app.MapPost("/api/woscheduledates/add", async (WoScheduleDateAddDto dto, AppDbContext db, ITenantContext t) =>
{
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.WorkOrderNo) && r.PlanDate is not null).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Bảng kế hoạch rỗng." });
    // 🔴 Guard nguồn: âm thì lỗi, bằng 0 thì BỎ QUA (không ghi dòng).
    foreach (var r in rows)
        if ((r.QtyPlan ?? 0) < 0)
            return Results.BadRequest(new { error = $"WorkOrder {r.WorkOrderNo} ngày {r.PlanDate:yyyy-MM-dd}: QtyPlan âm." });

    var now = DateTime.Now;
    var added = 0; var skippedZero = 0;
    foreach (var r in rows)
    {
        if ((r.QtyPlan ?? 0) == 0) { skippedZero++; continue; }   // continue đúng như nguồn
        db.WoScheduleDetailDates.Add(new WoScheduleDetailDate
        {
            OrgId = t.OrgId, CreatedDate = now, WorkOrderNo = r.WorkOrderNo!.Trim(),
            SpecCode = r.SpecCode, ModelCode = r.ModelCode, ColorCode = r.ColorCode,
            PlanDate = r.PlanDate!.Value, QtyPlan = r.QtyPlan!.Value,
        });
        added++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { added, skippedZero, note = "Dòng có QtyPlan = 0 bị bỏ qua, đúng như nguồn." });
}).RequireAuthorization();

// ===== THIẾT BỊ kèm dòng hoá đơn HTC (VAT_HTCInvoiceDeviceDetail) =====
// Nguồn: `HDDTIntergration/BizHTC.HDDTIntergration.cs:4140`.
// 🔴 `SpecCode` của bảng này lấy từ cột **`ActualSpec`** của bảng đầu vào (dòng 4131) — tức **spec THỰC TẾ
//    của xe**, KHÔNG phải spec khai trên chứng từ. Port theo phản xạ "SpecCode ← SpecCode" là ghi sai dữ liệu.
// Khoá dòng = bộ (HTCInvoiceCode, VIN, DeviceCode): một xe trên hoá đơn kèm được nhiều thiết bị.
app.MapGet("/api/invoicedevicedetails", async (AppDbContext db, ITenantContext t, string? htcInvoiceCode, string? vin) =>
{
    var qy = db.VatHtcInvoiceDeviceDetails.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(htcInvoiceCode)) qy = qy.Where(x => x.HTCInvoiceCode == htcInvoiceCode);
    if (!string.IsNullOrWhiteSpace(vin)) qy = qy.Where(x => x.VIN == vin);
    var items = await qy.OrderBy(x => x.HTCInvoiceCode).ThenBy(x => x.VIN).ThenBy(x => x.DeviceCode)
        .Select(x => new
        {
            x.HTCInvoiceCode, x.VIN, x.SpecCode, x.DeviceTypeCode, x.DeviceCode,
            x.EffectiveDate, x.LogLUDateTime, x.LogLUBy,
        }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/invoicedevicedetails/save", async (InvoiceDeviceSaveDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.HTCInvoiceCode ?? "").Trim();
    if (code.Length < 1) return Results.BadRequest(new { error = "Mã hoá đơn HTC rỗng." });
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.VIN) && !string.IsNullOrWhiteSpace(r.DeviceCode)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Bảng thiết bị rỗng." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var saved = 0;
    foreach (var r in rows)
    {
        var vin = r.VIN!.Trim().ToUpperInvariant();
        var dev = r.DeviceCode!.Trim();
        var row = await db.VatHtcInvoiceDeviceDetails
            .FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.HTCInvoiceCode == code && x.VIN == vin && x.DeviceCode == dev);
        if (row is null)
        {
            row = new VatHtcInvoiceDeviceDetail { OrgId = t.OrgId, HTCInvoiceCode = code, VIN = vin, DeviceCode = dev };
            db.VatHtcInvoiceDeviceDetails.Add(row);
        }
        // 🔴 SpecCode lấy từ ActualSpec, đúng như nguồn.
        row.SpecCode = r.ActualSpec;
        row.DeviceTypeCode = r.DeviceTypeCode;
        row.EffectiveDate = r.EffectiveDate;
        row.LogLUDateTime = now; row.LogLUBy = who;
        saved++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { htcInvoiceCode = code, saved });
}).RequireAuthorization();

// ===== LỊCH SỬ NGHỈ VIỆC của nhân viên bán hàng (Mst_SalesManHistoryInactive) =====
// Nguồn: `Biz.HTC.WH.cs:19236`, ghi **bên trong** `Mst_SalesMan_Update_New20230306` (18505).
// 🔴 Bảng KHÔNG có hàm riêng — chỉ được ghi như **tác dụng phụ của lệnh SỬA nhân viên**: khi NVBH bị cho
//    nghỉ, nguồn chụp nguyên trạng hồ sơ sang đây. Tra bằng danh sách WS sẽ không thấy; phải tra `SaveData`.
// 🔴 `SMFlagActive` lấy từ `Mst_SalesMan.FlagActive` (ĐỔI TÊN khi sang bảng lịch sử).
// 🔴 `IdentityCardNo`/`SMEndDate`/`SMReason`/`SMDesc` là **dữ liệu MỚI** do lệnh sửa truyền vào;
//    phần còn lại là ảnh chụp hồ sơ cũ.
app.MapGet("/api/salesmaninactivehistory", async (AppDbContext db, ITenantContext t, string? smCode, string? dealerCode) =>
{
    var qy = db.SalesManHistoryInactives.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(smCode)) qy = qy.Where(x => x.SMCode == smCode);
    if (!string.IsNullOrWhiteSpace(dealerCode)) qy = qy.Where(x => x.DealerCode == dealerCode);
    var items = await qy.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.SMCode, x.SMHyundaiCode, x.DealerCode, x.SMStatus, x.IdentityCardNo, x.SMFlagActive,
        x.SMStartDate, x.SMEndDate, x.SMReason, x.SMDesc, x.InactiveDateTime, x.InactiveBy,
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Cho nghỉ việc: chụp hồ sơ hiện tại sang bảng lịch sử rồi hạ cờ hoạt động — đúng thứ tự của nguồn.
app.MapPost("/api/salesmen/inactivate", async (SalesManInactivateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.SMCode ?? "").Trim();
    var sm = await db.SalesMen.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SalesManCode == code);
    if (sm is null) return Results.NotFound(new { error = $"Không có nhân viên bán hàng {code}." });

    db.SalesManHistoryInactives.Add(new SalesManHistoryInactive
    {
        OrgId = t.OrgId,
        // --- ảnh chụp hồ sơ hiện tại ---
        SMCode = sm.SalesManCode, DealerCode = sm.DealerCode, SMStatus = sm.Status,
        SMFlagActive = sm.Status,          // nguồn chép từ FlagActive của bảng nhân viên
        SMStartDate = dto.SMStartDate,
        // --- dữ liệu MỚI của lần cho nghỉ này ---
        IdentityCardNo = dto.IdentityCardNo,
        SMEndDate = dto.SMEndDate, SMReason = (dto.SMReason ?? "").Trim(), SMDesc = (dto.SMDesc ?? "").Trim(),
        InactiveDateTime = DateTime.Now,
        InactiveBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system",
    });
