// 🔴 #124 Sửa KH đại lý — port `DealerSalesDealerCustomerUpdateAll_New20210109` (Biz.HTC.WH.cs:108188).
// TWIN: WS 64-bit gọi bản 2021 này, WS 32-bit vẫn gọi bản 2018 — canonical là bản 2021 ("Nâng cấp ghi log").
// Sau khi ghi bản chính, nguồn **chụp SNAPSHOT toàn bộ bản ghi** sang `DLS_DealerCustomer_Upd`
// (`AcceptChanges()` + `SetAdded()` rồi SaveData, dòng 108529-108541) — KHÔNG phải cặp Old/New.
app.MapPost("/api/dealercustomers/update", async (DealerCustomerUpdateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.CustomerCode ?? "").Trim().ToUpperInvariant();
    var c = await db.DealerCustomers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CustomerCode == code);
    if (c is null) return Results.NotFound(new { error = $"Không có khách hàng {code}." });

    // Nguồn ghi các cột này không điều kiện; riêng IDCardType/IDCardNo chỉ ghi khi KHÔNG rỗng
    // (`if (!IsEmpty(...))`, dòng 108515-108516) — giữ đúng để không xoá mất giấy tờ đã lưu.
    if (!string.IsNullOrWhiteSpace(dto.FullName)) c.FullName = dto.FullName!.Trim();
    c.FullNameEN = dto.FullNameEN;
    c.Gender = dto.Gender;
    if (!string.IsNullOrWhiteSpace(dto.Address)) c.Address = dto.Address!.Trim();
    if (!string.IsNullOrWhiteSpace(dto.PhoneNo)) c.PhoneNo = dto.PhoneNo!.Trim();
    c.TaxCode = dto.TaxCode;
    c.ProvinceCode = dto.ProvinceCode;
    c.DistrictCode = dto.DistrictCode;
    c.CusBaseCode = dto.CusBaseCode;          // cột nguồn: CustomerBaseCode
    c.DateOfBirth = dto.DateOfBirth;
    c.Email = dto.Email;
    c.RepresentName = dto.RepresentName;
    c.Position = dto.Position;
    c.CusAccountBank = dto.CusAccountBank;
    if (!string.IsNullOrWhiteSpace(dto.IDCardType)) c.IDCardType = dto.IDCardType;
    if (!string.IsNullOrWhiteSpace(dto.IDCardNo)) c.IDCardNo = dto.IDCardNo;

    // 🔴 Snapshot SAU khi sửa, đúng như nguồn.
    db.DealerCustomerUpdLogs.Add(new DealerCustomerUpdLog
    {
        OrgId = t.OrgId, CustomerCode = c.CustomerCode, DealerCode = c.DealerCode,
        CusBaseCode = c.CusBaseCode, FullName = c.FullName, FullNameEN = c.FullNameEN,
        Address = c.Address, PhoneNo = c.PhoneNo, Email = c.Email, TaxCode = c.TaxCode,
        ProvinceCode = c.ProvinceCode, DistrictCode = c.DistrictCode,
        IDCardNo = c.IDCardNo, IDCardType = c.IDCardType, Gender = c.Gender, DateOfBirth = c.DateOfBirth,
        RepresentName = c.RepresentName, Position = c.Position, CusAccountBank = c.CusAccountBank,
        LoggedAt = DateTime.Now,
        LoggedBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system",
    });
    await db.SaveChangesAsync();
    return Results.Ok(new { c.CustomerCode, c.FullName, logged = true });
}).RequireAuthorization();

// Đọc nhật ký sửa. Vì nguồn lưu SNAPSHOT (không phải Old/New), muốn biết "đổi gì" phải so hai bản liên tiếp.
app.MapGet("/api/dealercustomers/updlogs", async (AppDbContext db, ITenantContext t, string? customerCode) =>
{
    var qy = db.DealerCustomerUpdLogs.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(customerCode)) qy = qy.Where(x => x.CustomerCode == customerCode);
    var items = await qy.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.CustomerCode, x.DealerCode, x.CusBaseCode, x.FullName, x.FullNameEN, x.Address, x.PhoneNo,
        x.Email, x.TaxCode, x.ProvinceCode, x.DistrictCode, x.IDCardNo, x.IDCardType, x.Gender,
        x.DateOfBirth, x.RepresentName, x.Position, x.CusAccountBank, x.LoggedAt, x.LoggedBy,
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items, note = "Mỗi dòng là SNAPSHOT toàn bộ bản ghi sau một lần sửa (nguồn không lưu Old/New)." });
}).RequireAuthorization();

app.MapPost("/api/dealercustomers", async (DealerCustomerDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (string.IsNullOrWhiteSpace(dto.CusTypeCode)) return Results.BadRequest(new { error = "Hãy nhập loại khách hàng." });
    if (string.IsNullOrWhiteSpace(dto.FullName)) return Results.BadRequest(new { error = "Hãy nhập Họ tên." });
    if (string.IsNullOrWhiteSpace(dto.Address)) return Results.BadRequest(new { error = "Hãy nhập Địa chỉ." });
    if (string.IsNullOrWhiteSpace(dto.PhoneNo)) return Results.BadRequest(new { error = "Hãy nhập Số điện thoại." });
    // audit 2026-09-03: regex đúng nguồn Util.IsPhoneNumber2 (FrmNewCustomer.txtPhone_Validating)
    if (!System.Text.RegularExpressions.Regex.IsMatch(dto.PhoneNo.Trim(), @"^(01[2689]|09|08|07|06|05|04|03|02)[0-9]{8,9}$"))
        return Results.BadRequest(new { error = "Số điện thoại không hợp lệ!" });
    if (!string.IsNullOrWhiteSpace(dto.IDCardNo) && dto.IDCardNo.Any(ch => !char.IsLetterOrDigit(ch)))
        return Results.BadRequest(new { error = "IDCardNo không được nhập ký tự đặc biệt." });
    // audit 2026-09-03: bổ sung guard thiếu — nguồn bắt buộc Tỉnh/Giới tính/Nguồn KH (btnApply_Click)
    if (string.IsNullOrWhiteSpace(dto.ProvinceCode)) return Results.BadRequest(new { error = "Hãy chọn Tỉnh." });
    if (string.IsNullOrWhiteSpace(dto.Gender)) return Results.BadRequest(new { error = "Hãy chọn Giới tính." });
    if (string.IsNullOrWhiteSpace(dto.CusBaseCode)) return Results.BadRequest(new { error = "Hãy chọn Nguồn khách hàng." });
    if (!string.IsNullOrWhiteSpace(dto.Email) && !System.Text.RegularExpressions.Regex.IsMatch(dto.Email, @"\w+([-+.']\w+)*@\w+([-.]\w+)*\.\w+([-.]\w+)*"))
        return Results.BadRequest(new { error = "Email không hợp lệ." });
    var code = string.IsNullOrWhiteSpace(dto.CustomerCode) ? "DC" + DateTime.Now.ToString("yyMMddHHmmss") : dto.CustomerCode.Trim().ToUpperInvariant();
    if (await db.DealerCustomers.AnyAsync(c => c.OrgId == t.OrgId && c.CustomerCode == code))
        return Results.BadRequest(new { error = $"Mã KH {code} đã tồn tại!" });
    var c = new DealerCustomer
    {
        OrgId = t.OrgId, CustomerCode = code, DealerCode = (dto.DealerCode ?? "").Trim().ToUpperInvariant(), CusTypeCode = dto.CusTypeCode.Trim(),
        CreatedBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system",
        CusBaseCode = dto.CusBaseCode, FullName = dto.FullName.Trim(), FullNameEN = dto.FullNameEN, Address = dto.Address.Trim(), PhoneNo = dto.PhoneNo.Trim(),
        Email = dto.Email, TaxCode = dto.TaxCode, ProvinceCode = dto.ProvinceCode, DistrictCode = dto.DistrictCode,
        IDCardNo = dto.IDCardNo, IDCardType = dto.IDCardType, Gender = dto.Gender, DateOfBirth = dto.DateOfBirth,
        RepresentName = dto.RepresentName, Position = dto.Position, CusAccountBank = dto.CusAccountBank
    };
    db.DealerCustomers.Add(c); await db.SaveChangesAsync();
    return Results.Ok(new { c.CustomerCode, c.FullName });
}).RequireAuthorization();

// ===== Giao dịch bán lẻ đại lý (DealerDeal — port 1:1 FrmNewDeal/FrmMngDeal, DMSales.Foton/SalesDealer) =====
// ===== Sửa ngày lập HĐ + cờ kiểm chứng CSKH (EditDeal — port 1:1 FrmEditDeal_DealDate/FrmEditDeal_KiemChung, 2010.HTC/SalesDealer) =====
app.MapGet("/api/editdeal/dealinfo", async (AppDbContext db, ITenantContext t, string? dealNo, string? dealer) =>
{
    var q = db.DealerDeals.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealNo)) q = q.Where(x => x.DealNo.Contains(dealNo!) || (x.DealNoUser != null && x.DealNoUser.Contains(dealNo!)));
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(x => x.DealerCode == dealer);
    var rows = await q.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.Id, x.DealNo, x.DealNoUser, x.DealerCode, dealDate = x.DealDate.ToString("yyyy-MM-dd"), x.CtmCareFlag,
        x.CtmCareUpdDate, x.CtmCareUpdBy, x.CtmCareRemark   // #196 §12
    }).ToListAsync();
    return Results.Ok(new { count = rows.Count, rows });
}).RequireAuthorization();

// Sửa ngày lập HĐ (không tương lai) và/hoặc cờ kiểm chứng CSKH (1=đã kiểm chứng / 0=chưa).
app.MapPost("/api/editdeal/dealinfo", async (List<DealInfoFixDto> fixes, AppDbContext db, ITenantContext t) =>
{
    if (fixes is null || fixes.Count == 0) return Results.BadRequest(new { error = "Không có dòng nào." });
    int updated = 0; var changes = new List<object>();
    foreach (var f in fixes)
    {
        var d = await db.DealerDeals.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == f.Id);
        if (d is null) { changes.Add(new { f.Id, error = "Không tìm thấy HĐ." }); continue; }
        DateTime newDate = d.DealDate;
        if (!string.IsNullOrWhiteSpace(f.DealDate))
        {
            if (!DateTime.TryParse(f.DealDate, out var dt)) { changes.Add(new { f.Id, error = "Ngày không hợp lệ." }); continue; }
            if (dt.Date > DateTime.Today) { changes.Add(new { f.Id, error = "Ngày lập HĐ không được ở tương lai." }); continue; }
            newDate = dt.Date;
        }
        var newFlag = d.CtmCareFlag;
        if (!string.IsNullOrWhiteSpace(f.CtmCareFlag))
        {
            var fl = f.CtmCareFlag.Trim();
            if (fl != "0" && fl != "1") { changes.Add(new { f.Id, error = "Cờ kiểm chứng phải là 0 hoặc 1." }); continue; }
            newFlag = fl;
        }
        if (newDate == d.DealDate && newFlag == d.CtmCareFlag) continue;
        changes.Add(new { d.Id, d.DealNo, oldDate = d.DealDate.ToString("yyyy-MM-dd"), newDate = newDate.ToString("yyyy-MM-dd"), oldFlag = d.CtmCareFlag, newFlag });
        d.DealDate = newDate; d.CtmCareFlag = newFlag; updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { total = fixes.Count, updated, changes });
}).RequireAuthorization();

// ===== Sửa biển số xe trong HĐ đại lý (EditDeal — port 1:1 FrmEditDeal_PlateNo, 2010.HTC/SalesDealer) =====
app.MapGet("/api/editdeal/plateno", async (AppDbContext db, ITenantContext t, string? dealNo, string? vin) =>
{
    var q = from d in db.DealerDealDetails.Where(x => x.OrgId == t.OrgId)
            join h in db.DealerDeals.Where(x => x.OrgId == t.OrgId) on d.DealId equals h.Id
            select new { d.Id, h.DealNo, d.CarId, d.PlateNo };
    if (!string.IsNullOrWhiteSpace(dealNo)) q = q.Where(x => x.DealNo.Contains(dealNo!));
    if (!string.IsNullOrWhiteSpace(vin)) q = q.Where(x => x.CarId.Contains(vin!));
    var rows = await q.OrderBy(x => x.DealNo).Take(500).ToListAsync();
    return Results.Ok(new { count = rows.Count, rows });
}).RequireAuthorization();

app.MapPost("/api/editdeal/plateno", async (List<PlateNoFixDto> fixes, AppDbContext db, ITenantContext t) =>
{
    if (fixes is null || fixes.Count == 0) return Results.BadRequest(new { error = "Không có dòng nào." });
    int updated = 0; var changes = new List<object>();
    foreach (var f in fixes)
    {
        var pl = (f.PlateNo ?? "").Trim().ToUpperInvariant();
        if (pl == "") { changes.Add(new { f.Id, error = "Biển số trống." }); continue; }
        var d = await db.DealerDealDetails.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == f.Id);
        if (d is null) { changes.Add(new { f.Id, error = "Không tìm thấy xe trong HĐ." }); continue; }
        // Chống trùng biển số trong cùng org (bỏ chính nó).
        if (await db.DealerDealDetails.AnyAsync(x => x.OrgId == t.OrgId && x.Id != d.Id && x.PlateNo == pl))
        { changes.Add(new { f.Id, error = "Biển số đã gán cho xe khác: " + pl }); continue; }
        if (d.PlateNo == pl) continue;
        changes.Add(new { d.Id, d.CarId, oldPlate = d.PlateNo, newPlate = pl });
        d.PlateNo = pl; updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { total = fixes.Count, updated, changes });
}).RequireAuthorization();

