// Sửa biển số xe hàng loạt (port 1:1 FrmEditDeal_PlateNo/DealerSalesDealUpdatePlateNoMulti gốc) — khóa theo (DealNo, CarId)
app.MapPost("/api/dealerdeals/edit-platenumber", async (EditDealPlateNoDto dto, AppDbContext db, ITenantContext t) =>
{
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.DealNo) && !string.IsNullOrWhiteSpace(r.CarId)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu được thay đổi" });
    int updated = 0; var notFound = new List<string>();
    foreach (var r in rows)
    {
        var no = r.DealNo!.Trim(); var carId = r.CarId!.Trim();
        var d = await db.DealerDeals.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealNo == no);
        if (d is null) { notFound.Add(no); continue; }
        var line = await db.DealerDealDetails.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealId == d.Id && x.CarId == carId);
        if (line is null) { notFound.Add($"{no}/{carId}"); continue; }
        line.PlateNo = r.PlateNo;
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// ===== #B08 TÌM XE ĐỂ BÁN CHO ĐẠI LÝ (port 1:1 FrmSearchCarForDealer, 2010.HTC/SalesDealer) =====
// Trace twin LIVE (đọc WS TRƯỚC): `btnQuery_Click` (:150) → `DealerService.SearchCarToSellToDealer`
//   (`DealerService.cs:1600`) → WS `DealerSalesDealGet_Car` (`WSHTC.asmx.cs:25421`)
//   → **`_biz.DealerSalesDealGet_Car_New20181115`** (`BizHTC.DealerSales.cs:3326`).
// ✅ grep `ws.` / `WSNM` trọn thân hàm ⇒ KHÔNG gọi WS ngoài (luật C0-…tertius).
// 🔴 HAI BIẾN THỂ CÙNG MỘT WS, khác **HÌNH DẠNG BỘ LỌC VIN** (luật C0-…quartus):
//   · `SearchCarToSellToDealer`        → `GenLikeCondition(vin)`     = MỘT giá trị, LIKE
//   · `SearchCarToSellToDealer_ListVIN`→ `GenContainsCondition(vin)` = DANH SÁCH VIN, IN
//   ⇒ endpoint nhận `vin` (một, LIKE) **hoặc** `vins` (nhiều, khớp tuyệt đối).

// ===== #B10 TÌM XE ĐỂ LÀM PDI (port 1:1 FrmSearchCarForPDI, 2010.HTC/SalesDealer) =====
// Trace twin LIVE (đọc WS TRƯỚC): `DealerService.SearchCarToPDI` → WS `SearchCarToPDI`
//   (`WSHTC.asmx.cs:84668`) → **`_biz.SearchCarToPDI`** (`BizHTC.DealerSales.cs:3679`).
// 🔴 HÌNH DẠNG BỘ LỌC — bốn ô, BA hình dạng khác nhau (đọc `Gen*Condition`, không đoán theo tên):
//   · `dealerCodeBuyer` → `GenEqualCondition2` ⇒ **"=" tuyệt đối**
//   · `modelCode`       → `GenEqualCondition2` ⇒ **"=" tuyệt đối**
//   · `vin`             → `GenLikeCondition`   ⇒ **LIKE %…%**
//   · `dlrContractNo`   → `GenEqualCondition`  ⇒ **"=" tuyệt đối**
//   · `isInStock`       → `GenEqualCondition2(Flag.Active)` gán vào `strDLSDDFlagCurrentConditionList`
//     ⇒ lại là **`DLS_DealDetail.FlagCurrent = '1'`**, KHÔNG phải tồn kho (giống bẫy ở #B08).
// 🔴 HAI NHÁNH SQL HOÀN TOÀN KHÁC NHAU tuỳ `dlrContractNo` có hay không (`:3749` vs `:3861`):
//   · CÓ số hợp đồng → nối thêm `Dlr_ContractDtl` + `Dlr_Contract`, trả `DlrContractNo`/`DDCFullName`/
//     `DlvExpectedDate` THẬT, và **tự thêm guard `dc.DlrCtrStatus = TConst.Stage.Approved` ("A")**
//     — guard này CHỈ tồn tại ở nhánh này (`:3837`).
//   · KHÔNG có → truy vấn gọn hơn, ba cột kia trả **chuỗi RỖNG** (nguồn `select '' DlrContractNo`…).

// ===== #B11 SỬA DÒNG XE TRÊN GIAO DỊCH BÁN (port 1:1 FrmMngDeal — 2 nút sửa) =====
// Trace twin LIVE (đọc WS TRƯỚC):
//   `DealerService.UpdateNormalInfoDealDetail` (:1384) → WS `DealerSalesDealDetailUpdate_NormalInfo`
//     → **`_biz.…_NormalInfo_New20181119`** (`Biz.HTC.WH.cs:94997`)
//   `DealerService.UpdateDeliveryDateDealDetail` (:1434) → WS `…_DeliveryDate`
//     → **`_biz.…_DeliveryDate_New20181119`** (`Biz.HTC.WH.cs:95592`)
// Khoá nghiệp vụ của CẢ HAI = cặp (`DealNo`, `CarId`).

// --- 1) Sửa BIỂN SỐ (NormalInfo) ---
app.MapPost("/api/deals/{dealNo}/cars/{carId}/plateno", async (
    string dealNo, string carId, DealDetailPlateNoDto dto, AppDbContext db, ITenantContext t) =>
{
    var no = dealNo.Trim().ToUpperInvariant();
    var cid = carId.Trim().ToUpperInvariant();
    // `..._InvalidPlateNo` — nguồn chặn biển số rỗng.
    if (string.IsNullOrWhiteSpace(dto.PlateNo)) return Results.BadRequest(new { error = "Biển số không hợp lệ." });
    var d = await db.DealerDeals.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealNo == no);
    if (d is null) return Results.NotFound(new { dealNo = no });
    var line = await db.DealerDealDetails.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealId == d.Id && x.CarId == cid);
    if (line is null) return Results.NotFound(new { dealNo = no, carId = cid });

    // `Car_Car_CheckDB(..., strCDODConfirmStatusListToCheck = TConst.Stage.Finished)`
    //   -- chú thích nguồn: "Đại lý phải đã Nhập xe."  (Stage.Finished = "F")
    var vinOfLine = line.VIN ?? line.CarId;
    var inStorage = await db.DeliveryOrderCars.AnyAsync(c => c.OrgId == t.OrgId && c.Vin == vinOfLine && c.ConfirmStatus == "F");
    if (!inStorage) return Results.BadRequest(new { error = $"Xe {vinOfLine} đại lý chưa nhập kho (ConfirmStatus phải = 'F')." });

    // `myCommon_CheckDealer(..., Flag.Active, Flag.Active)` — đại lý của giao dịch phải tồn tại & hoạt động.
    var dealer = await db.Dealers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == d.DealerCode);
    if (dealer is null) return Results.BadRequest(new { error = $"Đại lý {d.DealerCode} không tồn tại." });
    if ((dealer.FlagActive ?? dealer.Status) == "0") return Results.BadRequest(new { error = $"Đại lý {d.DealerCode} đang ngưng hoạt động." });
    // ⚠️ `myCommon_CheckAccessDealerData(BUCode)` — tầng ability BUPattern, nợ chung fleet.

    // 🔴 GUARD CỐT LÕI mà port cũ không có: `CtmCareFlag = TConst.Flag.Active` ("1") ⇒ CẤM sửa biển số.
    //    Nguyên văn thông điệp nguồn (Biz.HTC.WH.cs:95229): "Đã kiểm chứng, không được nhập (sửa) biển số".
    if (d.CtmCareFlag == "1")
        return Results.BadRequest(new { error = "Đã kiểm chứng, không được nhập (sửa) biển số", dealNo = no, ctmCareFlag = d.CtmCareFlag });

    // ===== #B14 CẢNH BÁO TRÙNG BIỂN SỐ (port `FrmMngDeal.cs:853-885` + `GetDealDetailByPlateNo` :2443) =====
    // Luật nguồn: **chỉ chạy khi người dùng KHÔNG phải HTC** (`if (!MasterInit.Instance.IsHTC())`), tức phía
    // ĐẠI LÝ. Tra mọi dòng đang mang biển số này (lọc kèm `FlagInitDeal = "0"` do client hardcode); nếu cặp
    // (`DealNo`, `CarId`) hiện tại **không nằm trong** kết quả (tức biển số thực sự đổi sang xe khác) thì hỏi:
    //   "Biển số '{plateNo}' đã được gắn cho xe '{danh sách CarId};…'. Bạn có chắc chắn muốn cập nhật…?"
    // ⚠️ Ở nguồn đây là **MessageBox phía CLIENT** (chọn No thì `return`, không gọi service). Chuyển sang
    //    server nên phải có cờ xác nhận — đây là **chuyển vị trí có nhãn**, không phải luật mới.
    var newPlate = dto.PlateNo.Trim();
    if (!dto.IsHTC)                                        // `!MasterInit.Instance.IsHTC()`
    {
        var dupLines = await (
            from f in db.DealerDealDetails.Where(f => f.OrgId == t.OrgId && f.PlateNo == newPlate)
            join z in db.DealerDeals.Where(z => z.OrgId == t.OrgId && z.FlagInitDeal == "0")
                 on f.DealId equals z.Id
            select new { f.CarId, DealNo = z.DealNo }).ToListAsync();
        // "Nếu biển số không thay đổi thì bỏ qua" — cặp (DealNo, CarId) hiện tại đã có trong kết quả.
        var isSameCar = dupLines.Any(x => x.DealNo == no && x.CarId == cid);
        if (dupLines.Count > 0 && !isSameCar && !dto.ConfirmDuplicatePlateNo)
        {
            var carDup = string.Join(";", dupLines.Select(x => x.CarId).Distinct());
            return Results.BadRequest(new
            {
                error = $"Biển số '{newPlate}' đã được gắn cho xe '{carDup}'. Bạn có chắc chắn muốn cập nhật biển số này cho xe {cid}?",
                needConfirm = true, plateNo = newPlate, duplicatedCarIds = carDup, duplicates = dupLines
            });
        }
    }

    // `alColumnEffective` chỉ có ĐÚNG MỘT cột: PlateNo (:95246).
    line.PlateNo = newPlate;
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        dealNo = no, carId = cid, line.PlateNo,
        // ⚠️ NỢ: sau khi lưu, nguồn gọi WS NGOÀI của hệ dịch vụ (`_strConfig_OS_URLWSCarSv`) đẩy thông tin
        //    người mua/người đứng tên sang CarSv; lỗi chỉ `SetWarning` (KHÔNG chặn lưu). MiniHTC chưa có tầng đó.
        carSvPushNote = "NỢ: nguồn đẩy thông tin KH sang WS CarSv sau khi lưu (lỗi chỉ cảnh báo, không chặn) — chưa port."
    });
}).RequireAuthorization();

// --- 2) Xác nhận / sửa NGÀY GIAO XE (DeliveryDate) ---
app.MapPost("/api/deals/{dealNo}/cars/{carId}/deliverydate", async (
    string dealNo, string carId, DealDetailDeliveryDateDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    var no = dealNo.Trim().ToUpperInvariant();
    var cid = carId.Trim().ToUpperInvariant();
    var d = await db.DealerDeals.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealNo == no);
    if (d is null) return Results.NotFound(new { dealNo = no });
    var line = await db.DealerDealDetails.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealId == d.Id && x.CarId == cid);
    if (line is null) return Results.NotFound(new { dealNo = no, carId = cid });

    var vinOfLine = line.VIN ?? line.CarId;
    var inStorage = await db.DeliveryOrderCars.AnyAsync(c => c.OrgId == t.OrgId && c.Vin == vinOfLine && c.ConfirmStatus == "F");
    if (!inStorage) return Results.BadRequest(new { error = $"Xe {vinOfLine} đại lý chưa nhập kho (ConfirmStatus phải = 'F')." });

    // 🔴 "Check SellToDealer" (:95706-95714): `DLSDDealerCodeBuyer` CÓ giá trị ⇒ ném
    //    `..._CannotUpdateDealWithAnotherDealer`. Nghĩa là **KHÔNG được sửa ngày giao của giao dịch
    //    bán buôn ĐL→ĐL** — chỉ giao dịch bán lẻ cho khách mới được.
    if (!string.IsNullOrWhiteSpace(d.DealerCodeBuyer))
        return Results.BadRequest(new { error = "Không sửa được ngày giao của giao dịch bán cho đại lý khác.", dealerCodeBuyer = d.DealerCodeBuyer });

    var dealer = await db.Dealers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == d.DealerCode);
    if (dealer is null) return Results.BadRequest(new { error = $"Đại lý {d.DealerCode} không tồn tại." });
    if ((dealer.FlagActive ?? dealer.Status) == "0") return Results.BadRequest(new { error = $"Đại lý {d.DealerCode} đang ngưng hoạt động." });

    var who = user.Identity?.Name ?? "system"; var now = DateTime.Now;
    var oldDate = line.DeliveryDate;
    // `bDeliveryConfirm` = client gửi ngày (form: rỗng ⇒ chuỗi ""), tức đây là lượt XÁC NHẬN giao.
    var bDeliveryConfirm = dto.DeliveryDate is not null;
    // `bConfirmFirstTime` = confirm && DeliveryStatus == Stage.Pending ("P")
    var bConfirmFirstTime = bDeliveryConfirm && line.DeliveryStatus == "P";
    // `bConfirmOrReconfirm` = confirm && ( "P"  ||  ("A" && ngày MỚI khác ngày CŨ) )
    var bConfirmOrReconfirm = bDeliveryConfirm &&
        (line.DeliveryStatus == "P" || (line.DeliveryStatus == "A" && oldDate != dto.DeliveryDate));

    if (bConfirmOrReconfirm)
    {
        // 4 cột của `alColumnEffective` (:95744-95747).
        line.DeliveryDate = dto.DeliveryDate;
        line.DeliveryStatus = "A";            // TConst.Stage.Approved
        line.ConfirmDate = now;
        line.ConfirmBy = who;
    }

    int hmcRows = 0;
    if (bConfirmFirstTime)
    {
        // 🔴 CHỈ lần xác nhận ĐẦU TIÊN mới có hai side-effect này (nhánh `bConfirmFirstTime`, :95770+):
        //   (a) `Car_Car.SellStatus = TConst.Stage.Finished` ("F") — xe chuyển sang trạng thái ĐÃ BÁN;
        //   (b) sinh `HMC_Report` với `DeliveryType = TConst.HTCConst.HMCRpt_DeliveryToEndUser` = **"001A"**.
        var car = await db.CarVinMasters.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.VIN == vinOfLine);
        if (car is not null) car.SellStatus = "F";
        var contents = BuildHmcPerformContents(d.DealerCode, dto.DeliveryDate ?? now, vinOfLine, "001A", d.SalesType, now);
        db.HmcReports.Add(new HmcReport { OrgId = t.OrgId, DealerCode = d.DealerCode, DealNo = no,
            CarId = cid, VIN = vinOfLine, DeliveryType = "001A", SalesType = d.SalesType,
            PerformDate = dto.DeliveryDate ?? now, CreatedDate = now, CreatedBy = who, PerformContents = contents });
        hmcRows = 1;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        dealNo = no, carId = cid, line.DeliveryDate, line.DeliveryStatus, line.ConfirmDate, line.ConfirmBy,
        bDeliveryConfirm, bConfirmFirstTime, bConfirmOrReconfirm, hmcReportRows = hmcRows,
        sellStatusSetToFinished = bConfirmFirstTime
    });
}).RequireAuthorization();
app.MapGet("/api/dealerdeals/cars-to-pdi", async (
    AppDbContext db, ITenantContext t,
    string? dealerCodeBuyer, string? vin, string? modelCode, string? dlrContractNo, string? inStock, string? buPattern) =>
{
    var buyerKey = string.IsNullOrWhiteSpace(dealerCodeBuyer) ? null : dealerCodeBuyer.Trim().ToUpperInvariant();
    var vinKey = string.IsNullOrWhiteSpace(vin) ? null : vin.Trim().ToUpperInvariant();
    var modelKey = string.IsNullOrWhiteSpace(modelCode) ? null : modelCode.Trim().ToUpperInvariant();
    var ctrKey = string.IsNullOrWhiteSpace(dlrContractNo) ? null : dlrContractNo.Trim().ToUpperInvariant();
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();
    var hasContract = ctrKey is not null;

    // `from DLS_Deal dlsd inner join Mst_Dealer md on dlsd.DealerCodeBuyer = md.DealerCode and BUCode like …`
    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId).Select(d => new { d.DealerCode, d.BUCode }).ToListAsync();
    var deals = await db.DealerDeals.Where(d => d.OrgId == t.OrgId && d.DealerCodeBuyer != null && d.DealerCodeBuyer != "").ToListAsync();
    if (buyerKey is not null) deals = deals.Where(d => d.DealerCodeBuyer == buyerKey).ToList();     // "=" tuyệt đối
    int droppedByDealerJoin = 0;
    deals = deals.Where(d =>
    {
        var dl = dealers.FirstOrDefault(x => x.DealerCode == d.DealerCodeBuyer);
        if (dl is null) { droppedByDealerJoin++; return false; }                    // nối TRONG ⇒ mất dòng
        if (pattern is not null && !(dl.BUCode ?? "").ToUpperInvariant().StartsWith(pattern)) { droppedByDealerJoin++; return false; }
        return true;
    }).ToList();

    var dealIds = deals.Select(d => d.Id).ToList();
    var details = await db.DealerDealDetails.Where(x => x.OrgId == t.OrgId && dealIds.Contains(x.DealId)).ToListAsync();
    // ô tick "còn trong kho" ⇒ `dlsdd.FlagCurrent = '1'` (Flag.Active) — lại là cột FlagCurrent.
    if (inStock == "1" || inStock == "true") details = details.Where(x => x.FlagCurrent == "1").ToList();

    // MiniHTC không có `Car_Car`; `DealerDealDetail.CarId` chính là VIN (ghi rõ ở entity) ⇒ nối thẳng Car_VIN.
    var carIds = details.Select(x => x.CarId).Distinct().ToList();
    var carsVin = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && carIds.Contains(c.VIN)).ToListAsync();
    // `inner join Car_DeliveryOrderDetail cdod on cc.CarId = cdod.CarId and cdod.ConfirmStatus = 'F'`
    //   -- chú thích nguồn: "Đại lý đã nhập Kho."  (Stage.Finished = "F")
    var confirmedVins = (await db.DeliveryOrderCars
        .Where(c => c.OrgId == t.OrgId && c.ConfirmStatus == "F" && carIds.Contains(c.Vin))
        .Select(c => c.Vin).ToListAsync()).ToHashSet();

    var specs = await db.CarSpecs.Where(s => s.OrgId == t.OrgId).Select(s => new { s.SpecCode, s.SpecDesc }).ToListAsync();
    var ctrDtls = hasContract
        ? await db.DlrContractDetails.Where(x => x.OrgId == t.OrgId && x.DlrContractNo == ctrKey).ToListAsync()
        : new List<DlrContractDetail>();
    var contracts = hasContract
        ? await db.DlrContracts.Where(c => c.OrgId == t.OrgId && c.DlrContractNo == ctrKey).ToListAsync()
        : new List<DlrContract>();
    var dealerCustomers = hasContract
        ? await db.DealerCustomers.Where(c => c.OrgId == t.OrgId).Select(c => new { c.CustomerCode, c.FullName }).ToListAsync()
        : null;

    var items = new List<object>();
    int droppedNoCar = 0, droppedNotInStorage = 0, droppedNoContractDtl = 0, droppedCtrNotApproved = 0;
    var seen = new HashSet<string>();                                   // `select distinct`
    foreach (var d in details)
    {
        var cv = carsVin.FirstOrDefault(c => c.VIN == d.CarId);
        if (cv is null) { droppedNoCar++; continue; }                   // inner join Car_Car/Car_VIN
        if (!confirmedVins.Contains(d.CarId)) { droppedNotInStorage++; continue; }
        if (vinKey is not null && !cv.VIN.ToUpperInvariant().Contains(vinKey)) continue;          // LIKE
        if (modelKey is not null && !string.Equals(cv.ModelCode, modelKey, StringComparison.OrdinalIgnoreCase)) continue;  // "="

        string? outCtrNo = null, outFullName = null; DateTime? outDlvExpected = null;
        if (hasContract)
        {
            // `inner join Dlr_ContractDtl dcd on cc.ModelCode = dcd.ModelCode and cc.SpecCode = dcd.SpecCode
            //  and **cv.ColorCode** = dcd.ColorCode` — chú thích nguồn (20210909, ToanNH): màu lấy theo màu
            // của VIN vì khi map VIN có luật bỏ qua màu, còn hợp đồng lại tạo theo màu của VIN.
            var dcd = ctrDtls.FirstOrDefault(x => x.ModelCode == cv.ModelCode && x.SpecCode == cv.SpecCode && x.ColorCode == cv.ColorCode);
            if (dcd is null) { droppedNoContractDtl++; continue; }
            var dc = contracts.FirstOrDefault(x => x.DlrContractNo == dcd.DlrContractNo);
            // 🔴 Guard `dc.DlrCtrStatus = Stage.Approved` ("A") — nguồn CHỈ thêm khi có số hợp đồng (:3837).
            if (dc is null || dc.Status != "A") { droppedCtrNotApproved++; continue; }
            outCtrNo = dcd.DlrContractNo;
            outDlvExpected = dcd.DlvExpectedDate;
            outFullName = dealerCustomers?.FirstOrDefault(x => x.CustomerCode == dc.CustomerCode)?.FullName;
        }

        var key = $"{cv.VIN}|{outCtrNo}";
        if (!seen.Add(key)) continue;
        items.Add(new
        {
            vin = cv.VIN, cvSpecCode = cv.SpecCode, cvModelCode = cv.ModelCode, cvColorCode = cv.ColorCode,
            cvActualSpec = cv.ActualSpec,
            cvActualSpecDescription = specs.FirstOrDefault(s => s.SpecCode == cv.ActualSpec)?.SpecDesc,
            // Nhánh KHÔNG có số hợp đồng: nguồn trả **chuỗi rỗng** cho ba cột này, không phải null.
            dlrContractNo = outCtrNo ?? "", ddcFullName = outFullName ?? "",
            dlvExpectedDate = hasContract ? (object?)outDlvExpected : ""
        });
    }

    return Results.Ok(new
    {
        count = items.Count, items,
        branch = hasContract ? "CÓ số hợp đồng (nối Dlr_ContractDtl + guard DlrCtrStatus='A')" : "KHÔNG có số hợp đồng (3 cột hợp đồng trả rỗng)",
        filterShapes = new { dealerCodeBuyer = "=", modelCode = "=", vin = "LIKE", dlrContractNo = "=", inStock = "DLS_DealDetail.FlagCurrent='1'" },
        droppedByDealerJoin, droppedNoCar, droppedNotInStorage, droppedNoContractDtl, droppedCtrNotApproved,
        note = items.Count == 0 ? "Không có kết quả nào phù hợp điều kiện tìm kiếm" : null
    });
}).RequireAuthorization();
app.MapGet("/api/dealerdeals/cars-to-sell-to-dealer", async (
    AppDbContext db, ITenantContext t,
    string? carId, string? vin, string? vins, string? specCode, string? actualSpec, string? modelCode,
    string? dealerCodeBuyer, string? inStock, string? buPattern) =>
{
    // 🔴 Ô "Spec" của form đi vào tham số **actualSpec**, KHÔNG phải specCode: form gọi
    //    `SearchCarToSellToDealer(carId, vin, "", spec, modelCode, …)` (FrmSearchCarForDealer.cs:150)
    //    trong khi chữ ký là `(cardId, vin, specCode, actualSpec, modelCode, …)`.
    //    Giữ cả hai tham số để không mất khả năng lọc, nhưng ghi rõ cái nào là của form.
    var vinList = string.IsNullOrWhiteSpace(vins)
        ? new List<string>()
        : vins.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
              .Select(v => v.ToUpperInvariant()).Distinct().ToList();

    // --- `#tbl_DLS_DealDetail_Filter` (BizHTC.DealerSales.cs:3437-3480) ---
    // `inner join Mst_Dealer md on dlsd.DealerCodeBuyer = md.DealerCode and md.BUCode like @strBUPatternOfUser`
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();
    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId).Select(d => new { d.DealerCode, d.DealerName, d.BUCode }).ToListAsync();

    var deals = await db.DealerDeals.Where(d => d.OrgId == t.OrgId && d.DealerCodeBuyer != null).ToListAsync();
    if (!string.IsNullOrWhiteSpace(dealerCodeBuyer))
    {
        var k = dealerCodeBuyer.Trim().ToUpperInvariant();      // GenLikeCondition ⇒ LIKE '%…%'
        deals = deals.Where(d => (d.DealerCodeBuyer ?? "").ToUpperInvariant().Contains(k)).ToList();
    }
    // `inner join Mst_Dealer` — đại lý mua không có trong danh mục ⇒ dòng bị LOẠI (không phải left join).
    var dealIds = deals.Select(d => d.Id).ToList();
    var details = await db.DealerDealDetails.Where(x => x.OrgId == t.OrgId && dealIds.Contains(x.DealId)).ToListAsync();
    if (!string.IsNullOrWhiteSpace(carId))
    {
        var k = carId.Trim().ToUpperInvariant();                 // GenLikeCondition ⇒ LIKE '%…%'
        details = details.Where(x => x.CarId.ToUpperInvariant().Contains(k)).ToList();
    }
    // 🔴 chkInStock ⇒ `strDLSDDFlagCurrentConditionList = GenEqualCondition(Flag.Yes)` = `FlagCurrent = '1'`
    //    (Flag.Yes = Flag.Active = "1", `Const.Main.cs:51-55`). Tên ô tick nói "InStock", cột là FlagCurrent.
    if (inStock == "1" || inStock == "true") details = details.Where(x => x.FlagCurrent == "1").ToList();

    // `inner join Car_VIN cv on cc.VIN = cv.VIN` — MiniHTC không có `Car_Car`, `DealerDealDetail.CarId`
    // chính là VIN (đã ghi ở entity: "CarId // VIN/CarID") ⇒ nối thẳng sang `CarVinMaster`.
    var carIds = details.Select(x => x.CarId).Distinct().ToList();
    var carsVin = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && carIds.Contains(c.VIN)).ToListAsync();
    // `inner join Car_DeliveryOrderDetail cdod on cc.CarId = cdod.CarId and cdod.ConfirmStatus = 'F'`
    //   -- chú thích của nguồn: "Đại lý đã nhập Kho".
    var doneVins = (await db.DeliveryOrderCars
        .Where(c => c.OrgId == t.OrgId && c.ConfirmStatus == "F" && carIds.Contains(c.Vin))
        .Select(c => c.Vin).ToListAsync()).ToHashSet();

    var specs = await db.CarSpecs.Where(s => s.OrgId == t.OrgId).Select(s => new { s.SpecCode, s.SpecDesc }).ToListAsync();

    // --- `#tblDlr_PDIRequest` + `#tblDlr_PDIRequestDtl` (:3486-3516) ---
    // RANK() OVER(PARTITION BY VIN ORDER BY dpr.ApprovedDate, dpr.DlrPDIReqNo DESC) rồi lấy Rank = '1';
    // guard: `dpr.DlrPDIReqStatus='A'` · `dc.DlrCtrStatus='A'` · `dcc.FlagCancel='0'` · `dcc.FlagDelivery='0'`.
    var pdiReqs = await db.DlrPdiRequests.Where(r => r.OrgId == t.OrgId && r.Status == "A")
        .Select(r => new { r.Id, r.DlrPdiReqNo, r.ApprovedDate }).ToListAsync();
    var pdiReqIds = pdiReqs.Select(r => r.Id).ToList();
    var pdiDtls = await db.DlrPdiRequestDetails
        .Where(d => d.OrgId == t.OrgId && pdiReqIds.Contains(d.DlrPdiReqId) && d.VIN != null && carIds.Contains(d.VIN!))
        .Select(d => new { d.DlrPdiReqId, d.VIN, d.CtrCarId, d.DlrContractNo }).ToListAsync();
    var ctrCars = await db.DlrContractCars.Where(c => c.OrgId == t.OrgId && c.FlagCancel == "0" && c.FlagDelivery == "0")
        .Select(c => new { c.CtrCarId }).ToListAsync();
    var ctrCarIds = ctrCars.Select(c => c.CtrCarId).ToHashSet();
    // `dc.DlrCtrStatus = 'A'` ⇒ MiniHTC `DlrContract.Status` (đã ghi chú: P mới tạo · A xác nhận · C huỷ · F hoàn thành)
    var activeContracts = (await db.DlrContracts.Where(c => c.OrgId == t.OrgId && c.Status == "A")
        .Select(c => c.DlrContractNo).ToListAsync()).ToHashSet();
    var pdiBest = pdiDtls
        .Where(d => d.CtrCarId != null && ctrCarIds.Contains(d.CtrCarId!)
                    && d.DlrContractNo != null && activeContracts.Contains(d.DlrContractNo!))
        .Select(d => new { d.VIN, d.CtrCarId, d.DlrContractNo, Req = pdiReqs.First(r => r.Id == d.DlrPdiReqId) })
        .GroupBy(x => x.VIN!)
        // Rank = 1 ⇒ ApprovedDate tăng dần, rồi DlrPDIReqNo GIẢM dần (đúng thứ tự ORDER BY của nguồn).
        .ToDictionary(g => g.Key, g => g.OrderBy(x => x.Req.ApprovedDate).ThenByDescending(x => x.Req.DlrPdiReqNo).First());

    var items = new List<object>();
    int skipNoDealer = 0, skipNoCar = 0, skipNotInStorage = 0;
    foreach (var d in details)
    {
        var deal = deals.First(x => x.Id == d.DealId);
        var dlBuyer = dealers.FirstOrDefault(x => x.DealerCode == deal.DealerCodeBuyer);
        if (dlBuyer is null) { skipNoDealer++; continue; }
        if (pattern is not null && !(dlBuyer.BUCode ?? "").ToUpperInvariant().StartsWith(pattern)) { skipNoDealer++; continue; }
        var cv = carsVin.FirstOrDefault(c => c.VIN == d.CarId);
        if (cv is null) { skipNoCar++; continue; }                       // inner join Car_VIN
        if (!doneVins.Contains(d.CarId)) { skipNotInStorage++; continue; } // inner join Car_DeliveryOrderDetail 'F'
        // Bộ lọc trên Car_VIN — LIKE từng cột (BuildClause "and", "cv.<Cột>", GenLikeCondition(...)).
        if (!string.IsNullOrWhiteSpace(vin) && !(cv.VIN ?? "").ToUpperInvariant().Contains(vin.Trim().ToUpperInvariant())) continue;
        if (vinList.Count > 0 && !vinList.Contains(cv.VIN.ToUpperInvariant())) continue;   // biến thể _ListVIN: IN
        if (!string.IsNullOrWhiteSpace(specCode) && !(cv.SpecCode ?? "").ToUpperInvariant().Contains(specCode.Trim().ToUpperInvariant())) continue;
        if (!string.IsNullOrWhiteSpace(actualSpec) && !(cv.ActualSpec ?? "").ToUpperInvariant().Contains(actualSpec.Trim().ToUpperInvariant())) continue;
        if (!string.IsNullOrWhiteSpace(modelCode) && !(cv.ModelCode ?? "").ToUpperInvariant().Contains(modelCode.Trim().ToUpperInvariant())) continue;

        // `left join Dls_Deal dlsd_Previous on dlsdd.DealNoPrevious = dlsd_Previous.DealNo`
        var prev = string.IsNullOrWhiteSpace(d.DealNoPrevious) ? null : deals.FirstOrDefault(x => x.DealNo == d.DealNoPrevious)
                   ?? await db.DealerDeals.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealNo == d.DealNoPrevious);
        // `left join Mst_CarSpec mcs on cv.ActualSpec = mcs.SpecCode` — join theo **ActualSpec**, không phải SpecCode.
        var actualSpecDesc = specs.FirstOrDefault(s => s.SpecCode == cv.ActualSpec)?.SpecDesc;
        pdiBest.TryGetValue(cv.VIN, out var pdi);
        items.Add(new
        {
            dealNo = deal.DealNo, carId = d.CarId, d.PlateNo, d.DeliveryDate, d.DeliveryStatus,
            d.ConfirmDate, d.ConfirmBy, d.FlagCurrent, d.DealNoPrevious, d.Price, d.PriceAFVAT,
            dealerCode = deal.DealerCode, dealerCodeBuyer = deal.DealerCodeBuyer, dealerNameBuyer = dlBuyer.DealerName,
            dlsdpDealerCode = prev?.DealerCode, dlsdpDealerCodeBuyer = prev?.DealerCodeBuyer,   // alias DLSDPDealerCode*
            vin = cv.VIN, cvSpecCode = cv.SpecCode, cvModelCode = cv.ModelCode, cvColorCode = cv.ColorCode,
            cv.EngineNo, cv.KeyNo, cv.TypeCB, cv.LoaiThung,
            cvActualSpec = cv.ActualSpec, cvSerialNo = cv.SerialNo, cvActualSpecDescription = actualSpecDesc,
            pdiCtrCarId = pdi?.CtrCarId, pdiDlrContractNo = pdi?.DlrContractNo
        });
    }

    return Results.Ok(new
    {
        count = items.Count, items,
        vinFilterShape = vinList.Count > 0 ? "IN (biến thể _ListVIN)" : "LIKE (biến thể một VIN)",
        skipNoDealer, skipNoCar, skipNotInStorage,
        note = items.Count == 0 ? "Không có kết quả nào phù hợp điều kiện tìm kiếm" : null   // Nonsense.MESS_NOTFOUND_RESULT
    });
}).RequireAuthorization();

// 🔴 #B09 ĐÃ GỠ `POST /api/dealerdeals/todealer` — bản port MỎNG TRÙNG của cùng màn `FrmNewDealToDealer`:
//    nó chỉ ghi 2/7 bảng, KHÔNG có guard nào của nguồn (xe phải `FlagCurrent="1"` + đã nhập kho
//    `ConfirmStatus="F"`, đại lý mua phải active, số giao dịch ≥ 5 ký tự), và **hardcode `SalesType = "F7"`**
//    trong khi nguồn nhận `strSalesType` từ client. Dùng `POST /api/wholesaledeals` (bản đầy đủ).

// ===== Yêu cầu PDI của đại lý (DlrPdiRequest — port 1:1 FrmNewDlr_PDIRequest, DMSales.Foton/SalesDealer) =====

// ===== #B16 TÌM YÊU CẦU PDI ĐẠI LÝ (port 1:1 `SearchDlrPDIRequest` → `DlrPDIRequest_Get`) =====
// Dùng bởi `FrmNewDlr_PDIRequest` (:216) và `FrmMngDlr_PDIRequest`.
// Trace: `Dlr_PDIRequestService.SearchDlrPDIRequest` (:145) → WS `DlrPDIRequest_Get`
//   (`WSHTC.asmx.cs:84951`) → `_biz.DlrPDIRequest_Get` (`…DlrPDIRequest.cs:1914`, **VỎ BỌC**)
//   → **`Dlr_PDIRequest_GetX`** (`:855`) — SQL thật.
// 🔴 `left join Dlr_PDIRequestDtl` RỒI `inner join Car_VIN cv on dprd.VIN = cv.VIN` ⇒ cái `left join`
//    **bị vô hiệu**: yêu cầu KHÔNG có dòng nào, hoặc dòng có VIN chưa khai trong `Car_VIN`, đều **bị LOẠI**.
//    Đây là mất dữ liệu lúc ĐỌC, không có cảnh báo nào.
// 🔴 Chín bộ lọc, HAI hình dạng: `DlrPDIReqNo`/`VIN`/`DlrContractNo`/`CtrCarId` = **LIKE %…%**;
//    `DealerCode`/`DlrPDIReqStatus`/`ROStatus` = **"="**; `CreatedDate` = **">=" và "<="** (một khoảng).

// ===== #B17 SỬA HÀNG LOẠT QUY CÁCH XE THEO CarId (port 1:1 `FrmUpdateSpec_CarID`, 2010.HTC/Sales) =====
// Trace twin LIVE: `FrmUpdateSpec_CarID.cs:136` → `sv.CarCar_UpdateMultiSpecCode(table)` → WS
//   `CarCar_UpdateMultiSpecCode` (`WSHTC.asmx.cs:13476`) → **`_biz.CarCar_UpdateMultiSpecCode`**
//   (`BizHTC.zTemp.cs:32`). Input là **BẢNG** (`#input_Car_Car`), update join theo `t.CarId = f.CarId`.
// 🔴 RBAC **DÒNG ACTIVE, không phải comment**: `myCommon_CheckHTCDirect(..., TConst.Flag.Active)` (`:97-101`)
//    ⇒ chỉ người dùng **HTC trực tiếp** được chạy màn này. (Đối chiếu: cùng file, nhiều hàm khác có khối này
//    bị comment — ở đây thì KHÔNG.) MiniHTC chưa có tầng ability ⇒ nhận cờ `flagDirect` và ghi rõ nợ.
// 🔴 `alColumnEffective` chỉ có **BA cột**: `SpecCode` + `LogLUDateTime` + `LogLUBy` (`:242-246`).
app.MapPost("/api/cars/update-multi-speccode", async (
    List<CarSpecBatchDto> rows, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user, string? flagDirect) =>
{
    // `..._CarCarTblNotFound` / `..._CarCarTblInvalid`
    if (rows is null) return Results.BadRequest(new { error = "Thiếu bảng xe cần sửa quy cách." });
    var list = rows.Where(r => !string.IsNullOrWhiteSpace(r.CarId) && !string.IsNullOrWhiteSpace(r.SpecCode)).ToList();
    if (list.Count == 0) return Results.BadRequest(new { error = "Bảng xe cần sửa quy cách rỗng hoặc thiếu CarId/SpecCode." });

    // `myCommon_CheckHTCDirect(..., Flag.Active)` — port thành cờ vì chưa có tầng ability.
    if (flagDirect == "0") return Results.BadRequest(new { error = "Chỉ người dùng HTC trực tiếp (FlagDirect='1') được sửa quy cách hàng loạt." });

    var who = user.Identity?.Name ?? "system"; var now = DateTime.Now;
    var carIds = list.Select(r => r.CarId!.Trim().ToUpperInvariant()).ToList();
    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && carIds.Contains(c.VIN)).ToListAsync();
    var specs = await db.CarSpecs.Where(s => s.OrgId == t.OrgId).ToListAsync();

    // Nguồn kiểm **TỪNG DÒNG rồi mới ghi cả lô** — một dòng hỏng là **ném lỗi, không ghi gì**
    // (toàn bộ nằm trong một transaction `_dbMain`). Port đúng: validate hết trước, ghi sau.
    foreach (var r in list)
    {
        var cid = r.CarId!.Trim().ToUpperInvariant();
        var spec = r.SpecCode!.Trim();
        // `myCar_CheckCar(..., FlagExist=Yes, FlagActive=Active, "", "",
        //                 strFlagAllowChangeVINListToCheck = Flag.Yes, strVINFreeStatusToCheck = Flag.Active, "")`
        // ⇒ xe phải TỒN TẠI, đang hoạt động, **cho phép đổi VIN** và **VIN đang TỰ DO**.
        var car = cars.FirstOrDefault(c => c.VIN == cid);
        if (car is null) return Results.BadRequest(new { error = $"Xe {cid} không tồn tại." });
        if ((car.FlagActive ?? "1") == "0") return Results.BadRequest(new { error = $"Xe {cid} đã bị huỷ/ngưng hoạt động." });
        // ⚠️ NỢ: `FlagAllowChangeVIN` và `VINFreeStatus` chưa có cột trong `CarVinMaster` ⇒ hai guard này
        //    CHƯA kiểm được. Ghi nợ, không giả vờ đã kiểm.
        // `myCommon_CheckSpecCode(..., Flag.Active)` + kiểm `FlagActive` của chính bản ghi quy cách.
        var sp = specs.FirstOrDefault(s => s.SpecCode == spec);
        if (sp is null) return Results.BadRequest(new { error = $"Quy cách {spec} không tồn tại." });
        if (sp.FlagActive == "0")
            return Results.BadRequest(new { error = $"Quy cách {spec} đang ngưng hoạt động (FlagActive='0')." });
        // `myCommon_CheckMatchingModelAndSpecCode(..., dt_Car_Car_Check["ModelCode"], drInput["SpecCode"])`
        // ⇒ quy cách mới phải THUỘC ĐÚNG dòng xe (ModelCode) của chiếc xe đó.
        if (!string.IsNullOrEmpty(sp.ModelCode) && !string.IsNullOrEmpty(car.ModelCode)
            && !string.Equals(sp.ModelCode, car.ModelCode, StringComparison.OrdinalIgnoreCase))
            return Results.BadRequest(new { error = $"Quy cách {spec} không thuộc dòng xe {car.ModelCode} của xe {cid}." });
    }

    int updated = 0;
    foreach (var r in list)
    {
        var cid = r.CarId!.Trim().ToUpperInvariant();
        var car = cars.First(c => c.VIN == cid);
        car.SpecCode = r.SpecCode!.Trim();          // 3 cột của `alColumnEffective`
        car.LogLUDateTime = now; car.LogLUBy = who;
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        updated, columnsWritten = new[] { "SpecCode", "LogLUDateTime", "LogLUBy" },
        rbacNote = "Nguồn có myCommon_CheckHTCDirect(Flag.Active) ở DÒNG ACTIVE — chỉ HTC trực tiếp; MiniHTC nhận qua cờ flagDirect (nợ tầng ability).",
        unverifiedGuards = "FlagAllowChangeVIN='1' và VINFreeStatus='1' chưa kiểm được — CarVinMaster chưa có 2 cột đó (nợ có nhãn)."
    });
}).RequireAuthorization();
app.MapGet("/api/dlrpdirequests/search", async (
    AppDbContext db, ITenantContext t,
    string? dlrPDIReqNo, string? dealerCode, DateTime? createdFrom, DateTime? createdTo,
    string? dlrPDIReqStatus, string? vin, string? dlrContractNo, string? roStatus, string? ctrCarId,
    string? buPattern, int? recordStart, int? recordCount) =>
{
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();
    var start = recordStart ?? 0;
    var count = recordCount ?? 200;

    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId).Select(d => new { d.DealerCode, d.BUCode }).ToListAsync();
    var reqs = await db.DlrPdiRequests.Where(r => r.OrgId == t.OrgId).ToListAsync();
    int droppedByDealerJoin = 0;
    reqs = reqs.Where(r =>
    {
        var dl = dealers.FirstOrDefault(x => x.DealerCode == r.DealerCode);
        if (dl is null) { droppedByDealerJoin++; return false; }
        if (pattern is not null && !(dl.BUCode ?? "").ToUpperInvariant().StartsWith(pattern)) { droppedByDealerJoin++; return false; }
        return true;
    }).ToList();

    // Bộ lọc trên ĐẦU yêu cầu.
    if (!string.IsNullOrWhiteSpace(dlrPDIReqNo)) { var k = dlrPDIReqNo.Trim().ToUpperInvariant(); reqs = reqs.Where(r => r.DlrPdiReqNo.ToUpperInvariant().Contains(k)).ToList(); }
    if (!string.IsNullOrWhiteSpace(dealerCode)) reqs = reqs.Where(r => r.DealerCode == dealerCode.Trim().ToUpperInvariant()).ToList();
    if (createdFrom is not null) reqs = reqs.Where(r => r.CreatedAt >= createdFrom).ToList();
    if (createdTo is not null) reqs = reqs.Where(r => r.CreatedAt <= createdTo).ToList();
    if (!string.IsNullOrWhiteSpace(dlrPDIReqStatus)) reqs = reqs.Where(r => r.Status == dlrPDIReqStatus.Trim()).ToList();

    var reqIds = reqs.Select(r => r.Id).ToList();
    var dtls = await db.DlrPdiRequestDetails.Where(x => x.OrgId == t.OrgId && reqIds.Contains(x.DlrPdiReqId)).ToListAsync();
    // Bộ lọc trên DÒNG.
    if (!string.IsNullOrWhiteSpace(vin)) { var k = vin.Trim().ToUpperInvariant(); dtls = dtls.Where(x => (x.VIN ?? "").ToUpperInvariant().Contains(k)).ToList(); }
    if (!string.IsNullOrWhiteSpace(dlrContractNo)) { var k = dlrContractNo.Trim().ToUpperInvariant(); dtls = dtls.Where(x => (x.DlrContractNo ?? "").ToUpperInvariant().Contains(k)).ToList(); }
    if (!string.IsNullOrWhiteSpace(roStatus)) dtls = dtls.Where(x => x.ROStatus == roStatus.Trim()).ToList();
    if (!string.IsNullOrWhiteSpace(ctrCarId)) { var k = ctrCarId.Trim().ToUpperInvariant(); dtls = dtls.Where(x => (x.CtrCarId ?? "").ToUpperInvariant().Contains(k)).ToList(); }

    // 🔴 `inner join Car_VIN` sau `left join` ⇒ dòng có VIN chưa khai bị LOẠI, và yêu cầu không còn dòng nào
    //    cũng biến mất khỏi kết quả.
    var vinKeys = dtls.Where(x => x.VIN != null).Select(x => x.VIN!).Distinct().ToList();
    var carsVin = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && vinKeys.Contains(c.VIN)).ToListAsync();
    var knownVins = carsVin.Select(c => c.VIN).ToHashSet();
    var droppedNoCarVin = dtls.Count(x => x.VIN == null || !knownVins.Contains(x.VIN));
    dtls = dtls.Where(x => x.VIN != null && knownVins.Contains(x.VIN)).ToList();
    var keptReqIds = dtls.Select(x => x.DlrPdiReqId).ToHashSet();
    var droppedReqNoLine = reqs.Count(r => !keptReqIds.Contains(r.Id));
    reqs = reqs.Where(r => keptReqIds.Contains(r.Id)).ToList();

    // Phân trang `identity(bigint,0,1) MyIdxSeq` trên `distinct DlrPDIReqNo`, `order by dpr.DlrPDIReqNo`.
    var orderedNos = reqs.Select(r => r.DlrPdiReqNo).Distinct().OrderBy(x => x, StringComparer.Ordinal).ToList();
    var myCount = orderedNos.Count;
    var pageNos = orderedNos.Skip(start).Take(count).ToHashSet();
    reqs = reqs.Where(r => pageNos.Contains(r.DlrPdiReqNo)).ToList();
    var pageReqIds = reqs.Select(r => r.Id).ToHashSet();
    dtls = dtls.Where(x => pageReqIds.Contains(x.DlrPdiReqId)).ToList();

    // `#tblDLS_Deal`: giao dịch bán của các VIN trong trang — 🔴 **chỉ `dd.FlagInitDeal = '0'`**.
    var pageVins = dtls.Select(x => x.VIN!).Distinct().ToList();
    var dealLines = await (
        from f in db.DealerDealDetails.Where(f => f.OrgId == t.OrgId && pageVins.Contains(f.CarId))
        join z in db.DealerDeals.Where(z => z.OrgId == t.OrgId && z.FlagInitDeal == "0") on f.DealId equals z.Id
        select new { VIN = f.CarId, z.DealNo, z.DealDate, z.SalesType, z.DealerCode, z.DealerCodeBuyer }).ToListAsync();

    var models = await db.CarModelStds.Where(m => m.OrgId == t.OrgId).Select(m => new { m.ModelCode, m.ModelName }).ToListAsync();
    var specs = await db.CarSpecs.Where(s => s.OrgId == t.OrgId).Select(s => new { s.SpecCode, s.SpecDesc }).ToListAsync();
    var colors = await db.MstCarColors.Where(c => c.OrgId == t.OrgId).Select(c => new { c.ModelCode, c.ColorCode, c.ColorExtNameVN, c.ColorIntNameVN }).ToListAsync();
    var ctrDtls = await db.DlrContractDetails.Where(x => x.OrgId == t.OrgId).ToListAsync();
    var custs = await db.DealerCustomers.Where(c => c.OrgId == t.OrgId).Select(c => new { c.CustomerCode, c.FullName, c.DealerCode }).ToListAsync();

    var items = dtls.Select(x =>
    {
        var r = reqs.First(z => z.Id == x.DlrPdiReqId);
        var cv = carsVin.First(c => c.VIN == x.VIN);
        var mo = models.FirstOrDefault(m => m.ModelCode == cv.ModelCode);
        var sp = specs.FirstOrDefault(s => s.SpecCode == cv.SpecCode);
        var co = colors.FirstOrDefault(c => c.ModelCode == cv.ModelCode && c.ColorCode == cv.ColorCode);
        var dcd = ctrDtls.FirstOrDefault(z => z.DlrContractNo == x.DlrContractNo
                                              && z.ModelCode == cv.ModelCode && z.SpecCode == cv.SpecCode && z.ColorCode == cv.ColorCode);
        var anyDeal = dealLines.FirstOrDefault(d => d.VIN == x.VIN);
        // 🔴 `DealNo`/`DealDate` chỉ lấy giao dịch có **`dd.DealerCodeBuyer is null`** — tức **bán LẺ**,
        //    loại giao dịch bán buôn ĐL→ĐL; còn `SalesType`/`DealerCode` KHÔNG có điều kiện đó.
        var retailDeal = dealLines.FirstOrDefault(d => d.VIN == x.VIN && string.IsNullOrEmpty(d.DealerCodeBuyer));
        var cust = custs.FirstOrDefault(c => c.DealerCode == r.DealerCode);
        return new
        {
            r.DlrPdiReqNo, dlrPDIReqStatus = r.Status, r.DealerCode, r.CreatedAt, r.CreatedBy,
            r.ApprovedDate, r.ApprovedBy, r.FlagAccessory, r.Remark,
            x.VIN, x.DlrContractNo, x.CtrCarId, x.RONo, x.ROCreatedDate, x.ROStatus, x.DlrPDIReqDtlStatus,
            cvVIN = cv.VIN, cvSerialNo = cv.SerialNo, cvSpecCode = cv.SpecCode, mcsSpecDescription = sp?.SpecDesc,
            cvModelCode = cv.ModelCode, mcmModelName = mo?.ModelName, cvColorCode = cv.ColorCode,
            mccColorNameVN = co is null ? null : $"{co.ColorExtNameVN}/{co.ColorIntNameVN}",   // `concat(…,'/',…)`
            cvActualSpec = cv.ActualSpec,
            ddcCustomerCode = cust?.CustomerCode, ddcFullName = cust?.FullName,
            dcdDlvExpectedDate = dcd?.DlvExpectedDate,
            flagDealNo = anyDeal is null ? "0" : "1",       // `IsNull((select top 1 '1' …), 0)`
            salesType = anyDeal?.SalesType, dealerCodeOfDeal = anyDeal?.DealerCode,
            dealNo = retailDeal?.DealNo, dealDate = retailDeal?.DealDate
        };
    }).ToList();

    return Results.Ok(new
    {
        myCount, recordStart = start, recordCount = count, count = items.Count, items,
        rowShape = "MỘT bản ghi = MỘT DÒNG XE của yêu cầu PDI",
        filterShapes = "LIKE: DlrPDIReqNo/VIN/DlrContractNo/CtrCarId · '=': DealerCode/DlrPDIReqStatus/ROStatus · khoảng: CreatedDate",
        dealNoRule = "DealNo/DealDate chỉ lấy giao dịch có DealerCodeBuyer rỗng (bán LẺ); SalesType/DealerCode không có điều kiện đó",
        droppedByDealerJoin, droppedNoCarVin, droppedReqNoLine,
        droppedNote = "inner join Car_VIN sau left join ⇒ dòng VIN chưa khai VÀ yêu cầu không còn dòng nào đều bị loại (đúng nguồn)"
    });
}).RequireAuthorization();
app.MapGet("/api/dlrpdirequests", async (AppDbContext db, ITenantContext t, string? status, string? dealer) =>
{
    var q = db.DlrPdiRequests.Where(p => p.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(p => p.Status == status);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(p => p.DealerCode == dealer);
    var items = await q.OrderByDescending(p => p.Id).Take(500).Select(p => new
    {
        p.DlrPdiReqNo, p.DealerCode, p.Status, p.CreatedAt, p.DoneAt,
        cars = db.DlrPdiRequestDetails.Count(c => c.OrgId == t.OrgId && c.DlrPdiReqId == p.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/dlrpdirequests", async (DlrPdiRequestDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    // ===== #B15 PORT LẠI 1:1 `DlrPDIRequestCreate` (FrmNewDlr_PDIRequest / …2) =====
    // Trace: `Dlr_PDIRequestService.DlrPDIRequestCreate` (:45) → WS `DlrPDIRequestCreate`
    //   (`WSHTC.asmx.cs:84744`) → `_biz.DlrPDIRequestCreate` (`Biz.HTC.WH.DlrPDIRequest.cs:1438`, **VỎ BỌC**)
    //   → **`DlrPDIRequestCreateX_New20230306`** (`:584`) — SQL/guard thật ở đây.
    // 🔴 KHOÁ DÒNG SAI Ở PORT CŨ: nguồn khoá theo **VIN** (`strKeyDetail = "|{VIN}|"`, :673) và bắt buộc
    //    `DlrContractNo` + `CtrCarId`; `RONo`/`ROCreatedDate` nguồn gán **DBNull lúc tạo** (:840-841),
    //    `ROStatus` khởi tạo bằng literal **"NORE"**. Port cũ **bắt buộc RONo** và dùng nó làm khoá ⇒
    //    không thể tạo yêu cầu đúng nghiệp vụ, và không lưu VIN/hợp đồng/xe-hợp-đồng.
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Cần mã đại lý." });
    var cars = (dto.Cars ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.VIN)).ToList();
    // `..._TableDetailBeBlank`
    if (cars.Count == 0) return Results.BadRequest(new { error = "Chưa chọn xe cho yêu cầu PDI." });

    var who = user.Identity?.Name ?? "system"; var now = DateTime.Now;
    var no = "PDIR" + now.ToString("yyMMddHHmmss");
    // `if (strDlrPDIReqNo.Length < TConst.HTCConst.MinLengthCode)` ⇒ **5** (Const.Main.cs:322)
    if (no.Length < 5) return Results.BadRequest(new { error = "Số yêu cầu PDI quá ngắn (tối thiểu 5 ký tự)." });
    var dealerCode = dto.DealerCode.Trim().ToUpperInvariant();

    // `myCommon_CheckDealer(..., Flag.Active exist, Flag.Active active)`
    var dealer = await db.Dealers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == dealerCode);
    if (dealer is null) return Results.BadRequest(new { error = $"Đại lý {dealerCode} không tồn tại." });
    if ((dealer.FlagActive ?? dealer.Status) == "0") return Results.BadRequest(new { error = $"Đại lý {dealerCode} đang ngưng hoạt động." });

    // `..._DuplicateKeyDetail` — khoá là **VIN**, không phải RONo.
    var dupVin = cars.GroupBy(r => r.VIN!.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupVin != null) return Results.BadRequest(new { error = $"VIN {dupVin.Key} bị trùng trong yêu cầu!" });
    // `..._DuplicateCtrCarId`
    var dupCtr = cars.Where(r => !string.IsNullOrWhiteSpace(r.CtrCarId))
        .GroupBy(r => r.CtrCarId!.Trim()).FirstOrDefault(g => g.Count() > 1);
    if (dupCtr != null) return Results.BadRequest(new { error = $"Xe hợp đồng {dupCtr.Key} bị trùng trong yêu cầu!" });

    var vinKeys = cars.Select(r => r.VIN!.Trim().ToUpperInvariant()).ToList();
    var vinMasters = await db.CarVinMasters.Where(x => x.OrgId == t.OrgId && vinKeys.Contains(x.VIN))
        .Select(x => new { x.VIN, x.ModelCode, x.SpecCode, x.ColorCode }).ToListAsync();
    // `Car_Car_CheckDB(..., strCDODConfirmStatusListToCheck = TConst.Stage.Finished)` — "Đại lý phải đã Nhập xe."
    var confirmedVins = (await db.DeliveryOrderCars
        .Where(x => x.OrgId == t.OrgId && x.ConfirmStatus == "F" && vinKeys.Contains(x.Vin))
        .Select(x => x.Vin).ToListAsync()).ToHashSet();
    var ctrCars = await db.DlrContractCars.Where(x => x.OrgId == t.OrgId).ToListAsync();
    var ctrDtls = await db.DlrContractDetails.Where(x => x.OrgId == t.OrgId).ToListAsync();

    foreach (var r in cars)
    {
        var v = r.VIN!.Trim().ToUpperInvariant();
        var m = vinMasters.FirstOrDefault(x => x.VIN == v);
        if (m is null) return Results.BadRequest(new { error = $"Xe {v} chưa khai báo trên hệ thống." });
        if (!confirmedVins.Contains(v)) return Results.BadRequest(new { error = $"Xe {v} đại lý chưa nhập kho (ConfirmStatus phải = 'F')." });
        // `..._InvalidDlrContractNo` / `..._InvalidCtrCarId`
        if (string.IsNullOrWhiteSpace(r.DlrContractNo)) return Results.BadRequest(new { error = $"Xe {v} thiếu số hợp đồng đại lý." });
        if (string.IsNullOrWhiteSpace(r.CtrCarId)) return Results.BadRequest(new { error = $"Xe {v} thiếu mã xe trên hợp đồng (CtrCarId)." });
        // `..._InputDetailNotInDlrContract` — bộ (Model, Spec, Color) của VIN phải khớp một dòng hợp đồng.
        var inCtr = ctrDtls.Any(x => x.DlrContractNo == r.DlrContractNo!.Trim()
                                     && x.ModelCode == m.ModelCode && x.SpecCode == m.SpecCode && x.ColorCode == m.ColorCode);
        if (!inCtr) return Results.BadRequest(new { error = $"Xe {v} không nằm trong hợp đồng {r.DlrContractNo}." });
        // `Dlr_ContractCar_CheckDB(..., FlagExist = Flag.Yes, FlagCancel = Inactive, FlagDelivery = Inactive)`
        var cc = ctrCars.FirstOrDefault(x => x.DlrContractNo == r.DlrContractNo!.Trim() && x.CtrCarId == r.CtrCarId!.Trim());
        if (cc is null) return Results.BadRequest(new { error = $"Xe hợp đồng {r.CtrCarId} không tồn tại." });
        if (cc.FlagCancel != "0") return Results.BadRequest(new { error = $"Xe hợp đồng {r.CtrCarId} đã huỷ." });
        if (cc.FlagDelivery != "0") return Results.BadRequest(new { error = $"Xe hợp đồng {r.CtrCarId} đã giao." });
    }

    // Đầu yêu cầu (`dt_Dlr_PDIRequest`, :806-820): Approved* để **NULL**, trạng thái **Stage.Pending "P"**.
    var p = new DlrPdiRequest
    {
        OrgId = t.OrgId, DlrPdiReqNo = no, DealerCode = dealerCode, Status = "P",
        CreatedAt = now, CreatedBy = who, ApprovedDate = null, ApprovedBy = null,
        FlagAccessory = dto.FlagAccessory, Remark = dto.Remark
    };
    db.DlrPdiRequests.Add(p); await db.SaveChangesAsync();
    foreach (var r in cars)
        db.DlrPdiRequestDetails.Add(new DlrPdiRequestDetail
        {
            OrgId = t.OrgId, DlrPdiReqId = p.Id,
            VIN = r.VIN!.Trim().ToUpperInvariant(),
            DlrContractNo = r.DlrContractNo!.Trim(), CtrCarId = r.CtrCarId!.Trim(),
            RONo = null, ROCreatedDate = null,      // nguồn gán DBNull lúc tạo
            ROStatus = "NORE",                       // literal của nguồn: NotResponding
            DlrPDIReqDtlStatus = "P"                 // TConst.Stage.Pending
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { p.DlrPdiReqNo, cars = cars.Count, status = p.Status, p.FlagAccessory,
        rowKey = "VIN (khoá dòng của nguồn), KHÔNG phải RONo — RONo/ROCreatedDate để NULL, ROStatus='NORE'" });
}).RequireAuthorization();

app.MapGet("/api/dlrpdirequests/{no}/cars", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var p = await db.DlrPdiRequests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrPdiReqNo == no);
    if (p is null) return Results.NotFound(new { no });
    var cars = await db.DlrPdiRequestDetails.Where(c => c.OrgId == t.OrgId && c.DlrPdiReqId == p.Id)
        .Select(c => new { c.RONo, c.ROCreatedDate, c.ROStatus, c.DlrPDIReqDtlStatus }).ToListAsync();
    return Results.Ok(new { p.DlrPdiReqNo, p.Status, p.ApprovedBy, p.ApprovedDate, p.Remark, count = cars.Count, cars });
}).RequireAuthorization();

// 🔴 DUYỆT — `DlrPDIRequestApprove` (Biz.HTC.WH.DlrPDIRequest.cs:1735-1870). Vào từ **"P"**, ra **"A"**;
// ghi `Remark`/`ApprovedDate`/`ApprovedBy` rồi **lan trạng thái 'A' xuống MỌI dòng** (`DlrPDIReqDtlStatus`).
// ⚠️ Port cũ gọi bước này là "complete" (Draft→Done) — mất hẳn ngữ nghĩa DUYỆT và cả tầng trạng thái dòng.
// ⚠️ Nguồn KHÔNG có từ chối/huỷ cho yêu cầu này.
app.MapPost("/api/dlrpdirequests/{no}/approve", async (string no, DlrPdiApproveDto? dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var p = await db.DlrPdiRequests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrPdiReqNo == no);
    if (p is null) return Results.NotFound(new { no });
    if (p.Status != "P") return Results.BadRequest(new { error = "Chỉ duyệt được yêu cầu đang chờ duyệt (P)." });
    var now = DateTime.Now;
    p.Status = "A"; p.DoneAt = now; p.ApprovedDate = now;
    p.ApprovedBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    p.Remark = dto?.Remark;
    var lines = await db.DlrPdiRequestDetails.Where(x => x.OrgId == t.OrgId && x.DlrPdiReqId == p.Id).ToListAsync();
    foreach (var l in lines) l.DlrPDIReqDtlStatus = "A";
    await db.SaveChangesAsync();
    return Results.Ok(new { p.DlrPdiReqNo, status = p.Status, statusName = "Đã duyệt", linesUpdated = lines.Count });
}).RequireAuthorization();

// 🔴 XOÁ — `DlrPDIRequestDelete` (1564-1735): guard header **"P"** (đã duyệt thì không xoá được);
// xoá dòng rồi xoá header. Đây là đường DUY NHẤT để bỏ một yêu cầu — nguồn không có huỷ/từ chối.
app.MapDelete("/api/dlrpdirequests/{no}", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var p = await db.DlrPdiRequests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrPdiReqNo == no);
    if (p is null) return Results.NotFound(new { no });
    if (p.Status != "P") return Results.BadRequest(new { error = "Chỉ xoá được yêu cầu đang chờ duyệt (P)." });
    var lines = await db.DlrPdiRequestDetails.Where(x => x.OrgId == t.OrgId && x.DlrPdiReqId == p.Id).ToListAsync();
    db.DlrPdiRequestDetails.RemoveRange(lines);
    db.DlrPdiRequests.Remove(p);
    await db.SaveChangesAsync();
    return Results.Ok(new { no, linesDeleted = lines.Count });
}).RequireAuthorization();

// ===== Chi tiết tờ khai hải quan (CtTkhq/CT_TKHQ — port 1:1 FrmNewCT_TKHQ, DMSales.Foton) =====
app.MapGet("/api/cttkhqs", async (AppDbContext db, ITenantContext t, string? port) =>
{
    var query = db.CtTkhqs.Where(k => k.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(port)) query = query.Where(k => k.PortCode == port);
    var items = await query.OrderByDescending(k => k.Id).Take(500).Select(k => new
    {
        k.DeclarationNo, k.OpenDate, k.PortCode, k.Remark, k.TaxPaymentDate, k.CreatedAt,
        vins = db.CtTkhqVins.Count(v => v.OrgId == t.OrgId && v.CtTkhqId == k.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Sửa hàng loạt ngày nộp thuế (port 1:1 FrmMngCT_TKHQ btnUpdateTaxPaymentDate_Click) — guard TaxPaymentDate >= OpenDate.
// ===== #B26 PARITY `ContractTKHQUpdate_TaxPaymentDate_New20181119` (Biz.HTC.WH.cs:38199) =====
// Trace twin LIVE: `FrmMngCT_TKHQ.cs:501` → `salesSv.ContractTKHQUpdate_TaxPaymentDate(ds_Car_VIN)`
//   → WS (`WSHTC.asmx.cs:8794`) → `_biz.ContractTKHQUpdate_TaxPaymentDate_New20181119`.
//   Khoá dòng của nguồn = **`DeclarationNo`** (`strKeyDetail = "|{DeclarationNo}|"`, `:38297`).
// 🔴 BỐN GUARD nguồn mà port cũ THIẾU — và ba trong đó nguồn **NÉM LỖI** còn port cũ **bỏ qua im lặng**:
//   · `..._DuplicateKeyDetail`   — trùng `DeclarationNo` trong bảng gửi lên
//   · `..._InvalidOpenDate`      — TKHQ **chưa có ngày mở** (`OpenDate` rỗng) ⇒ chặn
//   · `..._InvalidTaxPaymentDate`— ngày nộp thuế RỖNG ⇒ chặn (port cũ `continue`, coi như thành công)
//   · `CT_TKHQ_CheckDB(Flag.Active)` — TKHQ không tồn tại ⇒ **ném lỗi** (port cũ gom `notFound` rồi trả 200)
//   + `..._OpenDateAfterTaxPaymentDate` — `OpenDate > TaxPaymentDate` ⇒ chặn (port cũ đã có).
// 🔴 RBAC `myCommon_CheckHTCDirect(..., Flag.Active)` (`:38258`) là DÒNG ACTIVE.
// ⚠️ **QUIRK CỦA NGUỒN — CỐ Ý KHÔNG PORT NGUYÊN:** dòng ghi của nguồn là
//      `dt_CT_TKHQ.Rows[i]["TaxPaymentDate"] = dt_CT_TKHQ_Input.Rows[**0**]["TaxPaymentDate"];`  (`:38386`)
//    tức **mọi dòng đều nhận ngày của DÒNG ĐẦU TIÊN**, trong khi vòng kiểm phía trên lại kiểm **từng dòng**
//    (`dr = ..._Input.Rows[i]`). Đây gần như chắc chắn là **lỗi chỉ số của nguồn** và port nguyên sẽ **ghi sai
//    ngày cho các dòng 2..n**. Đã port theo ngữ nghĩa ĐÚNG (mỗi dòng ngày của chính nó) và **phơi quirk ra
//    trong response** (`sourceQuirk`) để người dùng quyết — KHÔNG im lặng chọn hộ.
app.MapPost("/api/cttkhqs/tax-payment-date", async (CtTkhqTaxDto dto, AppDbContext db, ITenantContext t, string? flagDirect) =>
{
    if (flagDirect == "0") return Results.BadRequest(new { error = "Chỉ người dùng HTC trực tiếp (FlagDirect='1') được cập nhật ngày nộp thuế." });
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.DeclarationNo)).ToList();
    // `..._TableDetailBeBlank`
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu được thay đổi" });
    // `..._DuplicateKeyDetail`
    var dup = rows.GroupBy(r => r.DeclarationNo!.Trim()).FirstOrDefault(g => g.Count() > 1);
    if (dup != null) return Results.BadRequest(new { error = $"Tờ khai {dup.Key} bị trùng trong bảng gửi lên!" });

    var nos = rows.Select(r => r.DeclarationNo!.Trim()).ToList();
    var tkhqs = await db.CtTkhqs.Where(x => x.OrgId == t.OrgId && nos.Contains(x.DeclarationNo)).ToListAsync();

    // Nguồn kiểm TỪNG DÒNG rồi mới ghi cả lô (một transaction) ⇒ validate hết trước, ghi sau.
    foreach (var r in rows)
    {
        var no = r.DeclarationNo!.Trim();
        var k = tkhqs.FirstOrDefault(x => x.DeclarationNo == no);
        if (k is null) return Results.BadRequest(new { error = $"Tờ khai {no} không tồn tại." });
        // `..._InvalidOpenDate` — `StandardizeDate(OpenDate)` rỗng ⇒ chặn.
        if (k.OpenDate == default) return Results.BadRequest(new { error = $"Tờ khai {no} chưa có ngày mở tờ khai." });
        // `..._InvalidTaxPaymentDate`
        if (r.TaxPaymentDate is null) return Results.BadRequest(new { error = $"Tờ khai {no} thiếu ngày nộp thuế." });
        // `..._OpenDateAfterTaxPaymentDate` — nguồn so bằng `strOpenDate.CompareTo(strTaxPaymentDate) > 0`
        //   trên chuỗi "yyyy-MM-dd" ⇒ so theo NGÀY, không theo giờ.
        if (k.OpenDate.Date > r.TaxPaymentDate.Value.Date)
            return Results.BadRequest(new { error = $"TKHQ: {no} ngày nộp thuế phải sau Ngày mở TKHQ!" });
    }

    int updated = 0;
    foreach (var r in rows)
    {
        var k = tkhqs.First(x => x.DeclarationNo == r.DeclarationNo!.Trim());
        k.TaxPaymentDate = r.TaxPaymentDate;   // ngữ nghĩa ĐÚNG: mỗi dòng ngày của chính nó
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        updated, columnsWritten = new[] { "TaxPaymentDate" },
        sourceQuirk = rows.Count > 1
            ? "⚠️ Nguồn gán ..._Input.Rows[0][TaxPaymentDate] cho MỌI dòng (Biz.HTC.WH.cs:38386) — gần như chắc chắn là lỗi chỉ số. Bản port này gán ĐÚNG ngày của từng dòng. Nếu cần khớp tuyệt đối hành vi nguồn, xác nhận để đổi."
            : null,
        guardsAdded = new[] { "DuplicateKeyDetail", "InvalidOpenDate", "InvalidTaxPaymentDate", "TKHQ không tồn tại ⇒ lỗi (không còn trả 200)", "CheckHTCDirect" }
    });
}).RequireAuthorization();

// Xóa hàng loạt tờ khai (port 1:1 FrmMngCT_TKHQ btnDeleteTk_Click)
app.MapPost("/api/cttkhqs/delete-batch", async (CtTkhqDeleteDto dto, AppDbContext db, ITenantContext t) =>
{
    var nos = (dto.DeclarationNos ?? new()).Where(n => !string.IsNullOrWhiteSpace(n)).Select(n => n.Trim()).ToList();
    if (nos.Count == 0) return Results.BadRequest(new { error = "Chưa chọn tờ khai để xóa" });
    var deleted = new List<string>();
    foreach (var no in nos)
    {
        var k = await db.CtTkhqs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DeclarationNo == no);
        if (k is null) continue;
        db.CtTkhqVins.RemoveRange(db.CtTkhqVins.Where(v => v.OrgId == t.OrgId && v.CtTkhqId == k.Id));
        db.CtTkhqs.Remove(k);
        deleted.Add(no);
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted });
}).RequireAuthorization();

app.MapPost("/api/cttkhqs", async (CtTkhqDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DeclarationNo)) return Results.BadRequest(new { error = "Cần số tờ khai." });
    if (dto.OpenDate is null) return Results.BadRequest(new { error = "Cần ngày mở tờ khai." });
    var no = dto.DeclarationNo.Trim();
    if (await db.CtTkhqs.AnyAsync(k => k.OrgId == t.OrgId && k.DeclarationNo == no))
        return Results.BadRequest(new { error = $"Số tờ khai {no} đã tồn tại!" });
    var vins = (dto.Vins ?? new()).Where(v => !string.IsNullOrWhiteSpace(v)).ToList();
    if (vins.Count == 0) return Results.BadRequest(new { error = "VIN không để trống." });
    var dupe = vins.GroupBy(v => v.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });
    var k = new CtTkhq { OrgId = t.OrgId, DeclarationNo = no, OpenDate = dto.OpenDate.Value, PortCode = dto.PortCode, Remark = dto.Remark };
    db.CtTkhqs.Add(k); await db.SaveChangesAsync();
    foreach (var v in vins)
        db.CtTkhqVins.Add(new CtTkhqVin { OrgId = t.OrgId, CtTkhqId = k.Id, Vin = v.Trim().ToUpperInvariant() });
    await db.SaveChangesAsync();
    return Results.Ok(new { k.DeclarationNo, vins = vins.Count });
}).RequireAuthorization();

app.MapGet("/api/cttkhqs/{no}/vins", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim();
    var k = await db.CtTkhqs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DeclarationNo == no);
    if (k is null) return Results.NotFound(new { no });
    var vins = await db.CtTkhqVins.Where(v => v.OrgId == t.OrgId && v.CtTkhqId == k.Id).Select(v => v.Vin).ToListAsync();
    return Results.Ok(new { k.DeclarationNo, count = vins.Count, vins });
}).RequireAuthorization();

// ===== Đơn đặt hàng (SalesOrder/So — port 1:1 FrmOrder, DMSales.Foton) =====
app.MapGet("/api/salesorders", async (AppDbContext db, ITenantContext t, string? status, string? dealer, string? type) =>
{
    var query = db.SalesOrders.Where(o => o.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) query = query.Where(o => o.Status == status);
    if (!string.IsNullOrWhiteSpace(dealer)) query = query.Where(o => o.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(type)) query = query.Where(o => o.OrderType == type);
    var items = await query.OrderByDescending(o => o.Id).Take(500).Select(o => new
    {
        o.SoCode, o.OrderType, o.PayType, o.SORCode, o.DealerCode, o.Status, o.CreatedAt, o.SentAt,
        o.SalesPolicy, o.ExpectedMonth, o.LatestDeliveryDate, o.Approved1At, o.Approved2At, o.RejectReason,
        lines = db.SalesOrderLines.Count(l => l.OrgId == t.OrgId && l.SalesOrderId == o.Id),
        qty = db.SalesOrderLines.Where(l => l.OrgId == t.OrgId && l.SalesOrderId == o.Id).Sum(l => (int?)l.RequestedQuantity) ?? 0
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/salesorders", async (SalesOrderDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Cần đại lý." });
    var type = (dto.OrderType ?? "Plan").Trim();
    if (type is not ("Plan" or "UnPlan")) return Results.BadRequest(new { error = "Loại đơn = Plan | UnPlan." });
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.ModelCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 dòng model." });
    if (lines.Any(l => l.RequestedQuantity <= 0)) return Results.BadRequest(new { error = "Số lượng phải > 0." });
    var no = (type == "Plan" ? "SOP" : "SOU") + DateTime.Now.ToString("yyMMddHHmmss");
    var o = new SalesOrder { OrgId = t.OrgId, SoCode = no, OrderType = type, PayType = dto.PayType, SORCode = string.IsNullOrWhiteSpace(dto.SORCode) ? null : dto.SORCode.Trim(), // 🔴 Nguồn tạo đơn là "P" (chờ duyệt) NGAY — không có bước nháp/gửi.
    DealerCode = dto.DealerCode.Trim().ToUpperInvariant(), Status = "P" };
    db.SalesOrders.Add(o); await db.SaveChangesAsync();
    foreach (var l in lines)
        db.SalesOrderLines.Add(new SalesOrderLine { OrgId = t.OrgId, SalesOrderId = o.Id, ModelCode = l.ModelCode.Trim(), SpecCode = l.SpecCode, ContractType = l.ContractType, YearProduction = l.YearProduction, RequestedQuantity = l.RequestedQuantity, RequestedDate = l.RequestedDate, UnitPrice = l.UnitPrice, RemarkDL = l.RemarkDL, ColorCode = l.ColorCode, CarId = l.CarId });
    await db.SaveChangesAsync();
    return Results.Ok(new { o.SoCode, o.OrderType, lines = lines.Count, status = o.Status });
}).RequireAuthorization();

app.MapGet("/api/salesorders/{no}/lines", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var o = await db.SalesOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SoCode == no);
    if (o is null) return Results.NotFound(new { no });
    var lines = await db.SalesOrderLines.Where(l => l.OrgId == t.OrgId && l.SalesOrderId == o.Id)
        .Select(l => new { l.ModelCode, l.SpecCode, l.ColorCode, l.ContractType, l.YearProduction, l.RequestedQuantity, l.RequestedDate, l.UnitPrice, l.RemarkDL, l.ApprovedQuantity, l.ApprovedDate, l.UnitPriceInit, l.MapVINRanking, l.Remark, l.CarId }).ToListAsync();
    return Results.Ok(new { o.SoCode, o.Status, count = lines.Count, lines, qty = lines.Sum(x => x.RequestedQuantity) });
}).RequireAuthorization();

// ⚠️ ĐÃ BỎ `/api/salesorders/{no}/send`: nguồn KHÔNG có bước "gửi đơn" — `OrderSOCreate_New20181119`
//    tạo thẳng `SOStatus = "P"`. "Draft"/"Sent" là hai trạng thái port cũ tự đặt.

// 🔴 HUỶ đơn hàng — `OrderSOCancel_New20181119` (Biz.HTC.WH.cs:24674-24782): chỉ từ "P", sang "C".
//    Nguồn phân biệt **Huỷ ("C")** với **Từ chối ("R")** là hai đường khác nhau; port cũ thiếu hẳn Huỷ.
// ===== #B38 AUDIT PARITY `OrderSOCancel_New20181119` (`FrmMngOrderDealer` → `sv.CancelSalesOrder`) =====
// Trace: `SalesService.CancelSalesOrder(List<string> lstSoCode)` (`:318`) — **nhận DANH SÁCH mã đơn** và
//   gọi WS `OrderSOCancel` **từng mã một trong vòng lặp**, trả `Hashtable<soCode, bool>`; mã nào lỗi thì
//   để `false`, **không làm hỏng các mã còn lại**.
// 🔴 GAP 1 — thiếu `myCommon_CheckDealer(…, TConst.Flag.Active)` (`:24747`): đại lý của đơn phải TỒN TẠI.
// 🔴 GAP 2 — thiếu `myCommon_CheckAccessDealerData(BUPattern, Mst_Dealer.BUCode)` (`:24755`) — RBAC phạm vi.
// 🔴 GAP 3 — `alColumnEffective` của nguồn có **ĐÚNG MỘT cột: `SOStatus`** (`:24765`). Port cũ còn ghi
//    `RejectReason` + `RejectedAt` — **cột NGOÀI nguồn**, và tệ hơn: mượn cột của đường **TỪ CHỐI ("R")**
//    cho hành động **HUỶ ("C")**, làm nhoè đúng hai đường mà nguồn cố tình tách. Đã bỏ.
// ⚠️ **DÒNG COMMENT, KHÔNG PORT**: guard `OrderSOCancel_Expired` (không cho đại lý huỷ đơn Plan sau ngày
//    15) nằm trong `if` **vẫn còn** nhưng **thân đã bị comment sạch** (`:24761-24772`), kèm chú thích
//    nguồn *"20110525.HoangTV: Requested by DucLA: Ignore this check."* ⇒ port dòng ACTIVE = **không chặn**.
app.MapPost("/api/salesorders/{no}/cancel", async (string no, AppDbContext db, ITenantContext t,
    string? buPattern) =>
{
    no = no.Trim().ToUpperInvariant();
    var o = await db.SalesOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SoCode == no);
    if (o is null) return Results.NotFound(new { no });
    // `myOrder_CheckSO(…, Flag.Active, Stage.Pending)`
    if (o.Status != "P") return Results.BadRequest(new { error = "Chỉ huỷ được đơn đang chờ duyệt (P).", guard = "myOrder_CheckSO(SOStatus=P)" });
    // GAP 1 — `myCommon_CheckDealer(…, Flag.Active)`
    var d = await db.Dealers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == o.DealerCode);
    if (d is null) return Results.BadRequest(new { error = $"Đại lý {o.DealerCode} của đơn không tồn tại.", guard = "myCommon_CheckDealer" });
    // GAP 2 — `myCommon_CheckAccessDealerData(BUPattern, BUCode)`
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();
    if (pattern is not null && !(d.BUCode ?? "").ToUpperInvariant().StartsWith(pattern))
        return Results.BadRequest(new { error = $"Ngoài phạm vi dữ liệu: BUCode {d.BUCode} không thuộc {buPattern}.", guard = "myCommon_CheckAccessDealerData" });

    o.Status = "C";   // GAP 3 — alColumnEffective của nguồn CHỈ có SOStatus
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        o.SoCode, status = o.Status, statusName = "Huỷ",
        columnsWritten = new[] { "SOStatus" },
        note = "Nguồn KHÔNG ghi lý do/người/thời điểm huỷ — huỷ ('C') và từ chối ('R') là hai đường tách biệt.",
        expiredGuard = "OrderSOCancel_Expired ở nguồn đã bị COMMENT (Requested by DucLA: Ignore this check) — không port."
    });
}).RequireAuthorization();

// #B38 — HUỶ HÀNG LOẠT, đúng khuôn `SalesService.CancelSalesOrder(List<string>)`:
// 🔴 nguồn **KHÔNG dùng một transaction chung**: nó lặp từng mã, gọi WS riêng lẻ, và trả
//    `Hashtable<soCode, bool>` — mã nào lỗi thì `false`, **các mã còn lại vẫn được huỷ**.
//    Vì vậy endpoint này trả **kết quả TỪNG MÃ** thay vì fail cả lô ở mã hỏng đầu tiên.

// ===== #B43 CỜ ĐÃ XỬ LÝ PHẠT TRẢ CHẬM — `OrderSO_Upd_02_New20181119` (`FrmMngOrderHtc`) =====
// Trace LIVE: `FrmMngOrderHtc` (`:706-726`) → `salesSV.OrDerSOFlagDone(so)` (`SalesService.cs:259`)
//   → WS `OrderSO_Upd_02` (`WSHTC.asmx.cs:6966`) → **`_biz.OrderSO_Upd_02_New20181119`**
//   (`DataWH/Biz.HTC.WH.cs:26469`). Bản chết: `Delete.BizHTC.Report.cs:69001` (`_New20181115`),
//   `Biz.HTC.WH.Rel.20230823.cs:24720` (ngoài csproj).
// 🔴 **`SearchSO` của màn này ĐÃ CHẾT**: bị comment ở **cả ba tầng** — form (`:357-358`),
//    `SalesService.cs:558` và `:771`. Tra theo tên hàm sẽ tưởng màn có chức năng tìm kiếm; **không có**.
//    Nghiệp vụ GHI duy nhất còn sống của màn là cờ này ⇒ port đúng phần còn sống.
// 🔴 `alColumnEffective` đúng **MỘT cột**: `FlagPmtDelayDone` (`:26597`), giá trị lấy thẳng từ input.
// 🔴 Bốn guard: `myCommon_CheckHTCDirect(Flag.Active)` — **dòng ACTIVE**; `myOrder_CheckSO(Flag.Active,
//    **Stage.Approved2**)` — đơn phải đã **duyệt cấp 2**; `myCommon_CheckDealer(Active, Active)`;
//    `myCommon_CheckAccessDealerData(BUPattern, BUCode)`.
// 🔴 Form chỉ gửi khi giá trị thuộc đúng **{"0","1"}** (`FrmMngOrderHtc.cs:611-617`) — không tự chế
//    giá trị khác; và **lặp từng đơn**, lỗi một đơn thì `break` (dừng hẳn), không bỏ qua như huỷ đơn (#B38).

// ===== #B44 KIỂM TRA TRƯỚC KHI TẠO GIAO DỊCH BÁN LẺ — `DealerSalesDealWarning_New20181119` =====
// Trace LIVE: `FrmNewDealFromRetail` → `salesSv.InsertDealWarning(deal)` (`DealerService.cs:1109`)
//   → WS `DealerSalesDealWarning` (`WSHTC.asmx.cs:25756`) → **`_biz.DealerSalesDealWarning_New20181119`**
//   (`DataWH/Biz.HTC.WH.cs:91694`). Bản chết: `BizHTC.DealerSales.cs:4511` (`_New20181115`),
//   `Delete.BizHTC.DealerSales.cs:3213`, `Biz.HTC.WH.Rel.20230823.cs:87757`.
// 🔴 Đây là **BƯỚC RIÊNG, chạy TRƯỚC** `InsertDeal` — form gọi hàm này để **cảnh báo** rồi mới lưu.
//    Port cũ chỉ có `DealerSalesDealCreate`, **thiếu hẳn bước cảnh báo** ⇒ người dùng mất hẳn lớp
//    kiểm tra "xe không khớp hợp đồng đại lý" trước khi ghi.
// 🔴 HAI mức, khác hẳn nhau — đừng gộp:
//   · **LỖI CỨNG** `_InputDetailNotInDlrContract`: bộ **(ModelCode, SpecCode)** của xe **không có**
//     trong hợp đồng đại lý (`:91963-91975`). Chú ý: **chỉ so Model+Spec, KHÔNG so màu**.
//   · **CẢNH BÁO** `_InputDetailNotColorDlrContract`: hợp đồng **có** (Model, Spec) nhưng **màu khác**
//     — điều kiện chính xác `arrColor.Count() > 0 && arrColorOther.Count() <= 0` (`:92022`), tức
//     "tồn tại dòng cùng Model+Spec màu KHÁC, và KHÔNG có dòng đúng màu này". Gom **tất cả** dòng
//     lệch màu rồi mới ném **một** lỗi liệt kê đủ (`:92073-92077`).
// ⚠️ **DÒNG COMMENT, KHÔNG PORT**: guard `_InputDetailValidQtyColor` (so SỐ LƯỢNG theo màu) đã bị rem
//    (`:92035-92042`) kèm chú thích nguồn *"20140324 case của anh Hương tạm thời rem lại"* — có ví dụ
//    nghiệp vụ đi kèm. Port theo dòng ACTIVE ⇒ **không kiểm số lượng theo màu**.
app.MapPost("/api/dealerdeals/warning", async (DealerDealDto dto, AppDbContext db, ITenantContext t) =>
{
    // Các guard đầu giống hệt `DealerSalesDealCreate` (nguồn chạy lại toàn bộ) — kiểm phần cốt lõi.
    if (string.IsNullOrWhiteSpace(dto.DlrContractNo))
        return Results.BadRequest(new { error = "Thiếu số hợp đồng đại lý.", guard = "DealerSalesDealCreate_InvalidDlrContractNo" });
    var cars = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.CarId)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "Chưa chọn xe.", guard = "DealerSalesDealCreate_TableDetailBeBlank" });
    var dupe = cars.GroupBy(c => c.CarId.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"Xe {dupe.Key} bị trùng!", guard = "DealerSalesDealCreate_DuplicateKeyDetail" });

    var ctrNo = dto.DlrContractNo!.Trim();
    // `dtContractDtl` — các dòng của hợp đồng đại lý.
    var ctrDtls = await db.DlrContractDetails.Where(x => x.OrgId == t.OrgId && x.DlrContractNo == ctrNo)
        .Select(x => new { x.ModelCode, x.SpecCode, x.ColorCode }).ToListAsync();

    var vins = cars.Select(c => c.CarId.Trim().ToUpperInvariant()).ToList();
    var vinInfo = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && vins.Contains(c.VIN))
        .Select(c => new { c.VIN, c.ModelCode, c.SpecCode, c.ColorCode }).ToListAsync();

    var colorWarnings = new List<object>();
    foreach (var vin in vins)
    {
        var v = vinInfo.FirstOrDefault(x => x.VIN == vin);
        if (v is null) return Results.BadRequest(new { error = $"Xe {vin} chưa khai báo trên hệ thống." });
        var model = (v.ModelCode ?? "").Trim(); var spec = (v.SpecCode ?? "").Trim(); var color = (v.ColorCode ?? "").Trim();

        // LỖI CỨNG — chỉ so (Model, Spec), KHÔNG so màu.
        var sameModelSpec = ctrDtls.Where(x => (x.ModelCode ?? "").Trim() == model && (x.SpecCode ?? "").Trim() == spec).ToList();
        if (sameModelSpec.Count == 0)
            return Results.BadRequest(new
            {
                error = $"Xe {vin} (model {model}, spec {spec}) không nằm trong hợp đồng đại lý {ctrNo}.",
                guard = "DealerSalesDealWarning_InputDetailNotInDlrContract"
            });

        // CẢNH BÁO — có cùng Model+Spec màu KHÁC, nhưng KHÔNG có dòng đúng màu này.
        var exactColor = sameModelSpec.Count(x => (x.ColorCode ?? "").Trim() == color);
        var otherColor = sameModelSpec.Count(x => (x.ColorCode ?? "").Trim() != color);
        if (otherColor > 0 && exactColor <= 0)
            colorWarnings.Add(new { vin, modelCode = model, specCode = spec, colorCode = color });
    }

    if (colorWarnings.Count > 0)
        return Results.BadRequest(new
        {
            error = "Có xe không đúng màu so với hợp đồng đại lý.",
            guard = "DealerSalesDealWarning_InputDetailNotColorDlrContract",
            isWarning = true,      // `CmUtils.CMyDataSet.SetWarning(ref mdsFinal, true)` của nguồn
            items = colorWarnings,
            note = "Nguồn gom TẤT CẢ dòng lệch màu rồi mới ném MỘT lỗi liệt kê đủ, không dừng ở dòng đầu."
        });

    return Results.Ok(new
    {
        ok = true, cars = vins.Count, dlrContractNo = ctrNo,
        checkedRules = new[] { "InputDetailNotInDlrContract (Model+Spec, KHÔNG so màu)", "InputDetailNotColorDlrContract (cảnh báo lệch màu)" },
        notPorted = "Guard _InputDetailValidQtyColor (so SỐ LƯỢNG theo màu) đã bị REM ở nguồn (:92035-92042, '20140324 case của anh Hương tạm thời rem lại') — không port."
    });
}).RequireAuthorization();
app.MapPost("/api/salesorders/flag-pmtdelay-done", async (List<SoFlagDoneDto> rows, AppDbContext db,
    ITenantContext t, string? flagDirect, string? buPattern) =>
{
    var list = (rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.SOCode)).ToList();
    if (list.Count == 0) return Results.BadRequest(new { error = "Không có đơn hàng thay đổi" });   // nguyên văn thông báo của form
    // `myCommon_CheckHTCDirect(Flag.Active)` — dòng ACTIVE.
    if (flagDirect == "0")
        return Results.BadRequest(new { error = "Chỉ người dùng HTC trực tiếp (FlagDirect='1') được cập nhật cờ này.", guard = "myCommon_CheckHTCDirect" });
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();

    var codes = list.Select(r => r.SOCode!.Trim().ToUpperInvariant()).Distinct().ToList();
    var orders = await db.SalesOrders.Where(o => o.OrgId == t.OrgId && codes.Contains(o.SoCode)).ToListAsync();
    var dealerCodes = orders.Select(o => o.DealerCode).Distinct().ToList();
    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId && dealerCodes.Contains(d.DealerCode))
        .Select(d => new { d.DealerCode, d.BUCode, d.FlagActive, d.Status }).ToListAsync();

    // Nguồn lặp từng đơn; form **dừng hẳn** ở đơn lỗi đầu tiên (`break`) — port giữ đúng: validate hết trước.
    foreach (var r in list)
    {
        var code = r.SOCode!.Trim().ToUpperInvariant();
        var flag = (r.FlagPmtDelayDone ?? "").Trim();
        // Form chỉ gửi khi thuộc {"0","1"} — không đẻ giá trị ngoài từ vựng nguồn.
        if (flag is not ("0" or "1"))
            return Results.BadRequest(new { error = $"Đơn {code}: FlagPmtDelayDone phải là '0' hoặc '1'.", allowed = new[] { "0", "1" } });
        var o = orders.FirstOrDefault(x => x.SoCode == code);
        if (o is null) return Results.BadRequest(new { error = $"Không tìm thấy đơn hàng {code}." });
        // `myOrder_CheckSO(…, Stage.Approved2)`
        if (o.Status != "A2")
            return Results.BadRequest(new { error = $"Đơn {code} đang ở '{o.Status}' — chỉ đơn đã duyệt cấp 2 ('A2') mới đặt được cờ.", guard = "myOrder_CheckSO(Stage.Approved2)" });
        // `myCommon_CheckDealer(Active, Active)`
        var d = dealers.FirstOrDefault(x => x.DealerCode == o.DealerCode);
        if (d is null) return Results.BadRequest(new { error = $"Đại lý {o.DealerCode} của đơn {code} không tồn tại.", guard = "myCommon_CheckDealer" });
        if ((d.FlagActive ?? d.Status) == "0")
            return Results.BadRequest(new { error = $"Đại lý {o.DealerCode} đang ngưng hoạt động.", guard = "myCommon_CheckDealer(FlagActive)" });
        // `myCommon_CheckAccessDealerData(BUPattern, BUCode)`
        if (pattern is not null && !(d.BUCode ?? "").ToUpperInvariant().StartsWith(pattern))
            return Results.BadRequest(new { error = $"Ngoài phạm vi dữ liệu: BUCode {d.BUCode} không thuộc {buPattern}.", guard = "myCommon_CheckAccessDealerData" });
    }

    foreach (var r in list)
    {
        var o = orders.First(x => x.SoCode == r.SOCode!.Trim().ToUpperInvariant());
        o.FlagPmtDelayDone = r.FlagPmtDelayDone!.Trim();   // alColumnEffective: ĐÚNG một cột
    }
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        updated = list.Count, soCodes = codes,
        columnsWritten = new[] { "FlagPmtDelayDone" },
        deadFunctionNote = "SearchSO của FrmMngOrderHtc đã bị comment ở CẢ BA tầng (form + SalesService:558 + :771) — màn không còn chức năng tìm kiếm ở hệ nguồn.",
        errorPolicy = "Form dừng hẳn ở đơn lỗi đầu tiên (break) — khác huỷ đơn hàng loạt (#B38) vốn bỏ qua đơn lỗi."
    });
}).RequireAuthorization();
app.MapPost("/api/salesorders/cancel-multi", async (List<string> soCodes, AppDbContext db,
    ITenantContext t, string? buPattern) =>
{
    var codes = (soCodes ?? new()).Where(s => !string.IsNullOrWhiteSpace(s))
        .Select(s => s.Trim().ToUpperInvariant()).Distinct().ToList();
    if (codes.Count == 0) return Results.BadRequest(new { error = "Chưa chọn đơn hàng nào để huỷ." });
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();

    var orders = await db.SalesOrders.Where(x => x.OrgId == t.OrgId && codes.Contains(x.SoCode)).ToListAsync();
    var dealerCodes = orders.Select(x => x.DealerCode).Distinct().ToList();
    var dealers = await db.Dealers.Where(x => x.OrgId == t.OrgId && dealerCodes.Contains(x.DealerCode))
        .Select(x => new { x.DealerCode, x.BUCode }).ToListAsync();

    var results = new List<object>(); int nOk = 0;
    foreach (var code in codes)
    {
        var o = orders.FirstOrDefault(x => x.SoCode == code);
        if (o is null) { results.Add(new { soCode = code, ok = false, reason = "Không tìm thấy đơn hàng." }); continue; }
        if (o.Status != "P") { results.Add(new { soCode = code, ok = false, reason = $"Đơn đang ở '{o.Status}', chỉ huỷ được đơn 'P'." }); continue; }
        var d = dealers.FirstOrDefault(x => x.DealerCode == o.DealerCode);
        if (d is null) { results.Add(new { soCode = code, ok = false, reason = $"Đại lý {o.DealerCode} không tồn tại." }); continue; }
        if (pattern is not null && !(d.BUCode ?? "").ToUpperInvariant().StartsWith(pattern))
        { results.Add(new { soCode = code, ok = false, reason = $"Ngoài phạm vi dữ liệu (BUCode {d.BUCode})." }); continue; }
        o.Status = "C";
        results.Add(new { soCode = code, ok = true, reason = (string?)null }); nOk++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        total = codes.Count, cancelled = nOk,
        results,
        perCodeRule = "Nguồn lặp từng mã, lỗi một mã KHÔNG chặn các mã còn lại (Hashtable<soCode,bool>)."
    });
}).RequireAuthorization();

// Duyệt cấp 1 (FrmOrderApprove): chính sách bán + tháng dự kiến/SX/ngày giao + SL duyệt từng dòng; mọi dòng phải có năm SX
app.MapPost("/api/salesorders/{no}/approve1", async (string no, SoApprove1Dto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var o = await db.SalesOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SoCode == no);
    if (o is null) return Results.NotFound(new { no });
    if (o.Status != "P") return Results.BadRequest(new { error = "Chỉ duyệt cấp 1 đơn đang chờ duyệt (P)." });
    var lines = await db.SalesOrderLines.Where(l => l.OrgId == t.OrgId && l.SalesOrderId == o.Id).ToListAsync();
    if (lines.Any(l => string.IsNullOrWhiteSpace(l.YearProduction)))
        return Results.BadRequest(new { error = "Có bản ghi chưa chọn năm sản xuất?" });

    // 🔴 Nguồn duyệt cấp 1 nhận TOÀN BỘ dòng chi tiết từ người duyệt và guard rất chặt
    //    (`OrderSOApprove1_new20181119`, Biz.HTC.WH.cs:25389-25485). Port cũ tự gán SL duyệt = SL yêu cầu.
    var inLines = dto.Lines ?? new();
    if (inLines.Count != lines.Count)
        return Results.BadRequest(new { error = $"Số dòng duyệt ({inLines.Count}) không khớp số dòng đơn hàng ({lines.Count})." });
    // Khoá đối chiếu ĐÚNG nguồn: |SOCode||SpecCode||ModelCode||ColorCode| — ColorCode là một phần khoá.
    static string LineKey(string so, string? spec, string model, string? color) => $"|{so}||{spec}||{model}||{color}|";
    var inByKey = new Dictionary<string, SoApprove1LineDto>();
    foreach (var il in inLines)
        inByKey[LineKey(o.SoCode, il.SpecCode, il.ModelCode ?? "", il.ColorCode)] = il;
    foreach (var l in lines)
    {
        if (!inByKey.TryGetValue(LineKey(o.SoCode, l.SpecCode, l.ModelCode, l.ColorCode), out var il))
            return Results.BadRequest(new { error = $"Dòng duyệt không khớp dữ liệu đơn hàng: {l.ModelCode}/{l.SpecCode}/{l.ColorCode}." });
        if (il.ApprovedQuantity < 0)
            return Results.BadRequest(new { error = $"Số lượng duyệt của {l.ModelCode} không hợp lệ." });
        // Nguồn bắt buộc UnitPriceInit **>= 1.0** (không phải chỉ > 0).
        if (il.UnitPriceInit < 1.0m)
            return Results.BadRequest(new { error = $"Đơn giá duyệt của {l.ModelCode} phải >= 1." });
        l.ApprovedQuantity = il.ApprovedQuantity;
        l.ApprovedDate = il.ApprovedDate;
        l.UnitPriceInit = il.UnitPriceInit;
        l.MapVINRanking = 5.0m;   // nguồn gán CỨNG 5.0, cố tình không lấy input (dòng `dr["MapVINRanking"] = 5.0;`)
        l.Remark = il.Remark;
    }
    o.SPCode = dto.SPCode; o.SalesPolicy = dto.SalesPolicy; o.ExpectedMonth = dto.ExpectedMonth;
    o.ProductionMonth = dto.ProductionMonth; o.LatestDeliveryDate = dto.LatestDeliveryDate;
    o.Status = "A1"; o.Approved1At = DateTime.Now;
    o.ApprovedBy1 = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    await db.SaveChangesAsync();
    return Results.Ok(new { o.SoCode, status = o.Status, statusName = "Duyệt cấp 1", approvedLines = lines.Count });
}).RequireAuthorization();

// Duyệt cấp 2 (duyệt cuối)
// 🔴 Duyệt cấp 2 — `OrderSOApprove2_New20181119` (Biz.HTC.WH.cs:25698-25813). Vào từ "A1".
//    Nguồn có **HAI ngả trong CÙNG một hàm**: mặc định → "A2"; nếu `strFlagUnapprove = Flag.Active`
//    thì **BỎ DUYỆT, trả đơn về "P"**. Port cũ thiếu hẳn ngả bỏ duyệt.
app.MapPost("/api/salesorders/{no}/approve2", async (string no, AppDbContext db, ITenantContext t, bool? unapprove) =>
{
    no = no.Trim().ToUpperInvariant();
    var o = await db.SalesOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SoCode == no);
    if (o is null) return Results.NotFound(new { no });
    if (o.Status != "A1") return Results.BadRequest(new { error = "Đơn phải duyệt cấp 1 (A1) trước." });
    if (unapprove == true)
    {
        o.Status = "P"; o.Approved1At = null; o.Approved2At = null;
        await db.SaveChangesAsync();
        return Results.Ok(new { o.SoCode, status = o.Status, statusName = "Chờ duyệt (đã bỏ duyệt)" });
    }
    o.Status = "A2"; o.Approved2At = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { o.SoCode, status = o.Status, statusName = "Duyệt cấp 2" });
}).RequireAuthorization();

app.MapPost("/api/salesorders/{no}/reject", async (string no, SoRejectDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var o = await db.SalesOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SoCode == no);
    if (o is null) return Results.NotFound(new { no });
    // 🔴 Nguồn (`OrderSOReject_New201811119`) guard `strSOStatusListToCheck = Stage.Pending` ⇒ **CHỈ từ "P"**.
    //    Port cũ cho từ chối cả đơn đã duyệt cấp 1 — guard RỘNG hơn nguồn (sai chiều).
    if (o.Status != "P") return Results.BadRequest(new { error = "Chỉ từ chối được đơn đang chờ duyệt (P)." });
    o.Status = "R"; o.RejectReason = dto.Reason; o.RejectedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { o.SoCode, status = o.Status });
}).RequireAuthorization();

// ===== #B77 TÍNH LẠI BA MỐC HẠN CỦA ĐƠN BÁN — `Ord_SalesOrder_Update_Calc` =====
// Trace LIVE: WS `Ord_SalesOrder_Update_Calc` (`WSHTC.asmx.cs:95559`) →
//   **`_biz.Ord_SalesOrder_Update_Calc`** (`DataWH/Biz.HTC.WH.My.cs:20631`) — **KHÔNG có hậu tố
//   `_NewYYYYMMDD`**, hiếm gặp; hàm dùng chung `mySql_GetClauseSelect_Mst_Calendar_GetForDayT()`
//   (`BizHTC.Common.cs:1682`).
//   3B đo thật, **khớp cả 2 máy**: start=20631 md5 `95d1d482a1736df64afc3797748a2d73`.
// 🔴 **"NGÀY THỨ T" LÀ NGÀY LÀM VIỆC THỨ T, KHÔNG PHẢI CỘNG T NGÀY LỊCH.** Cơ chế của nguồn:
//      `select identity(bigint, 0, 1) MyIdxSeq, … into #tbl_Mst_Calendar_Filter from Mst_Calendar`
//        `where CalendarType = 'WorkingDay' and StatusValue = 0 and Date >= @strMCALDate_From`
//      rồi `left join … on t.MyIdxSeq + @nDayT = t1.MyIdxSeq`
//    ⇒ đánh số **liên tiếp CÁC NGÀY LÀM VIỆC** đã lọc, rồi nhảy **T VỊ TRÍ** trong dãy đó.
//    ⚠️ **`StatusValue = 0` NGHĨA LÀ NGÀY LÀM VIỆC** (0 = không nghỉ) — cả hai mệnh đề đều kèm chú
//      thích *"Only WorkingDay"*. Hiểu ngược dấu là lệch toàn bộ mốc hạn.
//    ⚠️ Cửa sổ lọc bắt đầu từ **`@strMCALDate_From` = `ApprovedDate`**, nên `MyIdxSeq = 0` chính là
//      ngày làm việc **đầu tiên >= ngày duyệt**; không phải chỉ số toàn cục.
// 🔴 **BA MỐC, HAI CƠ CHẾ KHÁC NHAU — đừng gộp**:
//    1) `DepositDutyEndDate` (ngày ĐL cam kết thanh toán **hết cọc**) = ngày **làm việc** thứ
//       `Calendar_DepositDuty_DayT` kể từ `f_WorkingDate_Get_01(ApprovedDate)`.
//    2) `GrtEndDate` (ngày hết hạn **phát hành bảo lãnh**) = cùng cơ chế, tham số **riêng**
//       `Calendar_GrtDuty_DayT` (chú thích nguồn: **7 ngày**).
//    3) `CarDueDate` (ngày đến hạn **trả xe** cho ĐL) = `DepositDutyEndDate` **+ số NGÀY LỊCH**
//       (`dateadd(dd, …)`), **không** phải ngày làm việc.
// 🔴 **Bảng số ngày của `CarDueDate` và cái bẫy `else`**:
//      `AssemblyStatus='CKD'` và `FlagAmbulance='0'` ⇒ **45**
//      `AssemblyStatus='CBU'` và `FlagAmbulance='0'` ⇒ **60**
//      **else** ⇒ **80**
//    ⚠️ Nguồn `left join Mst_CarSpec` (theo **CẢ `SpecCode` VÀ `ModelCode`**). Dòng **không khớp spec**
//      có `AssemblyStatus` NULL ⇒ rơi vào `else` và **im lặng nhận 80 ngày**, KHÔNG báo lỗi. Nghĩa là
//      `else 80` gánh **hai** nhóm rất khác nhau: xe cứu thương (đúng ý đồ) và **spec sai/thiếu** (lỗi
//      dữ liệu bị che). Port trả `noSpecMatchCount` để đo, **không tự đổi thành lỗi**.
// 🔴 **HAI HẬU KIỂM CHẶN CỨNG**: sau khi điền, nguồn `select * … where DepositDutyEndDate is null`
//    (và tương tự `GrtEndDate is null`); **còn bất kỳ dòng NULL nào ⇒ NÉM**
//    `…_WorkingDayNotBeSet` / `…_WorkingDayNotBeSet_GrtDateEnd`, kèm 7 tham số chẩn đoán từ `Rows[0]`.
//    ⇒ **Lịch làm việc chưa khai báo đủ xa là CẢ LỆNH HỎNG**, không phải "để trống rồi tính sau".
//    Port giữ đúng: thiếu lịch ⇒ trả lỗi đó, **không** ghi mốc nào.
// 🔴 Bước 1 luôn chạy trước: `update Ord_SalesOrderDetail set ApprovedDate = @strApprovedDate
//    where SOCode = @strSOCode` — **mọi dòng** của đơn, không lọc thêm.
// 🔴 Nguồn ghi **cả `_dbMain` và `_dbWH`** ở **cả bốn** bước (cùng khuôn #B75/#B76).
// 📌 NỢ: hai tham số `Calendar_DepositDuty_DayT` / `Calendar_GrtDuty_DayT` nằm ở bảng tham số hệ thống
//    (`myUtils_GetParamsRaw`) **chưa có trong MiniHTC**. **KHÔNG đoán**: nhận qua query
//    `depositDutyDayT` / `grtDutyDayT`; thiếu ⇒ trả `Ord_SalesOrder_Update_Calc_ParamNotSet`.
//    Riêng `grtDutyDayT` có chú thích nguồn ghi 7 nhưng **vẫn không mặc định** — chú thích không phải dữ liệu.
app.MapPost("/api/salesorders/{no}/recalc-duedates", async (
    string no, AppDbContext db, ITenantContext t,
    DateTime? approvedDate, int? depositDutyDayT, int? grtDutyDayT) =>
{
    var soCode = (no ?? "").Trim().ToUpperInvariant();
    if (soCode.Length < 1)
        return Results.BadRequest(new { error = "Ord_SalesOrder_Update_Calc_SOCodeEmpty" });
    if (approvedDate is null)
        return Results.BadRequest(new { error = "Ord_SalesOrder_Update_Calc_ApprovedDateEmpty", check = new { SOCode = soCode } });
    if (depositDutyDayT is null || grtDutyDayT is null)
        return Results.BadRequest(new
        {
            error = "Ord_SalesOrder_Update_Calc_ParamNotSet",
            missing = new[] { depositDutyDayT is null ? "Calendar_DepositDuty_DayT" : null,
                              grtDutyDayT is null ? "Calendar_GrtDuty_DayT" : null }.Where(x => x != null),
            note = "Hai tham so nay nam o bang tham so he thong (myUtils_GetParamsRaw) chua co trong MiniHTC. KHONG doan gia tri - phai truyen vao."
        });

    var so = await db.SalesOrders.FirstOrDefaultAsync(o => o.OrgId == t.OrgId && o.SoCode == soCode);
    if (so is null)
        return Results.BadRequest(new { error = "Ord_SalesOrder_Update_Calc_SOCodeNotFound", check = new { SOCode = soCode } });

    var appr = approvedDate.Value.Date;
    var lines = await db.SalesOrderLines.Where(l => l.OrgId == t.OrgId && l.SalesOrderId == so.Id).ToListAsync();

    // ---- Bước 1: mọi dòng của đơn nhận ApprovedDate.
    foreach (var l in lines) l.ApprovedDate = appr;

    // ---- Dãy NGÀY LÀM VIỆC kể từ ApprovedDate (`StatusValue = 0` = ngày làm việc).
    var workDays = await db.MstCalendars
        .Where(c => c.OrgId == t.OrgId && c.CalendarType == "WorkingDay" && c.StatusValue == "0" && c.Date >= appr)
        .OrderBy(c => c.Date).Select(c => c.Date).ToListAsync();
    // `f_WorkingDate_Get_01(ApprovedDate)` — ngày làm việc đầu tiên >= ngày duyệt = phần tử MyIdxSeq 0.
    DateTime? DayT(int n) => (n >= 0 && n < workDays.Count) ? workDays[n] : (DateTime?)null;

    var depositEnd = DayT(depositDutyDayT.Value);
    var grtEnd = DayT(grtDutyDayT.Value);

    // ---- Hậu kiểm 1: còn dòng nào NULL ⇒ NÉM (không ghi gì).
    if (depositEnd is null)
    {
        var r0 = lines.FirstOrDefault();
        return Results.BadRequest(new
        {
            error = "Ord_SalesOrder_Update_Calc_WorkingDayNotBeSet",
            check = new
            {
                RowCount = lines.Count, SOCode = soCode, r0?.SpecCode, r0?.ModelCode, r0?.ColorCode,
                ApprovedDate = appr, DepositDutyEndDate = (DateTime?)null
            },
            calendarNote = $"Lich lam viec chi co {workDays.Count} ngay tu {appr:yyyy-MM-dd} tro di, can it nhat {depositDutyDayT + 1}. Nguon NEM loi nay chu KHONG de trong roi tinh sau."
        });
    }
    if (grtEnd is null)
    {
        var r0 = lines.FirstOrDefault();
        return Results.BadRequest(new
        {
            error = "Ord_SalesOrder_Update_Calc_WorkingDayNotBeSet_GrtDateEnd",
            check = new
            {
                RowCount = lines.Count, SOCode = soCode, r0?.SpecCode, r0?.ModelCode, r0?.ColorCode,
                ApprovedDate = appr, GrtEndDate = (DateTime?)null
            },
            calendarNote = $"Lich lam viec chi co {workDays.Count} ngay tu {appr:yyyy-MM-dd} tro di, can it nhat {grtDutyDayT + 1}."
        });
    }

    foreach (var l in lines) { l.DepositDutyEndDate = depositEnd; l.GrtEndDate = grtEnd; }

    // ---- Bước 4: CarDueDate = DepositDutyEndDate + số NGÀY LỊCH theo spec.
    var specs = await db.CarSpecs.Where(s => s.OrgId == t.OrgId)
        .Select(s => new { s.SpecCode, s.ModelCode, s.AssemblyStatus, s.FlagAmbulance }).ToListAsync();
    var noSpecMatchCount = 0;
    var byDays = new Dictionary<int, int>();
    foreach (var l in lines)
    {
        // `left join Mst_CarSpec` theo CẢ SpecCode VÀ ModelCode.
        var sp = specs.FirstOrDefault(s => s.SpecCode == (l.SpecCode ?? "") && (s.ModelCode ?? "") == l.ModelCode);
        if (sp is null) noSpecMatchCount++;
        var asm = sp?.AssemblyStatus;
        var amb = sp?.FlagAmbulance;
        // 🔴 `else 80` gánh CẢ xe cứu thương LẪN dòng không khớp spec (AssemblyStatus NULL).
        var nDay = (asm == "CKD" && amb == "0") ? 45
                 : (asm == "CBU" && amb == "0") ? 60
                 : 80;
        byDays.TryGetValue(nDay, out var c); byDays[nDay] = c + 1;
        l.CarDueDate = depositEnd.Value.AddDays(nDay);      // `dateadd(dd, …)` — NGÀY LỊCH.
    }

    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        soCode, approvedDate = appr,
        depositDutyDayT, grtDutyDayT,
        depositDutyEndDate = depositEnd, grtEndDate = grtEnd,
        lineCount = lines.Count,
        noSpecMatchCount,
        carDueDayBreakdown = byDays.OrderBy(x => x.Key).Select(x => new { nDay = x.Key, lines = x.Value }).ToList(),
        items = lines.Select(l => new
        {
            l.SpecCode, l.ModelCode, l.ColorCode, l.ApprovedDate,
            l.DepositDutyEndDate, l.GrtEndDate, l.CarDueDate
        }).ToList(),
        dayTNote = "'Ngay thu T' la NGAY LAM VIEC THU T, KHONG phai cong T ngay lich: nguon danh so lien tiep cac ngay da loc (CalendarType='WorkingDay' AND StatusValue=0, Date >= ApprovedDate) bang identity(bigint,0,1) MyIdxSeq roi self-join 't.MyIdxSeq + @nDayT = t1.MyIdxSeq' de nhay T VI TRI trong day do.",
        statusValueNote = "StatusValue = 0 NGHIA LA NGAY LAM VIEC (0 = khong nghi) - ca hai menh de deu kem chu thich 'Only WorkingDay'. Hieu nguoc dau la lech toan bo moc han.",
        threeDatesNote = "BA MOC, HAI CO CHE: DepositDutyEndDate va GrtEndDate dung NGAY LAM VIEC thu N (hai tham so RIENG); con CarDueDate = DepositDutyEndDate + so NGAY LICH (dateadd(dd,...)). Dung gop lam mot.",
        carDueRuleNote = "So ngay cong vao CarDueDate: CKD+FlagAmbulance='0' => 45 | CBU+FlagAmbulance='0' => 60 | else => 80. CANH BAO: nguon left join Mst_CarSpec theo CA SpecCode VA ModelCode; dong KHONG KHOP SPEC co AssemblyStatus NULL nen roi vao 'else' va IM LANG nhan 80 ngay, KHONG bao loi. Vay 'else 80' ganh HAI nhom rat khac nhau: xe cuu thuong (dung y do) va SPEC SAI/THIEU (loi du lieu bi che). Da do bang noSpecMatchCount; KHONG tu doi thanh loi.",
        postCheckNote = "HAI HAU KIEM CHAN CUNG: sau khi dien, nguon select lai cac dong con NULL; CON BAT KY DONG NAO ==> NEM WorkingDayNotBeSet / WorkingDayNotBeSet_GrtDateEnd kem 7 tham so chan doan tu Rows[0]. Lich lam viec chua khai bao du xa la CA LENH HONG, khong phai 'de trong roi tinh sau'.",
        twoDbNote = "Nguon ghi CA _dbMain va _dbWH o ca BON buoc - cung khuon #B75/#B76, khong phai 2-phase commit.",
        noSuffixNote = "Ten biz KHONG co hau to _NewYYYYMMDD - hiem gap trong 2010.HTC; dung dung ten khi tra cuu.",
        paramDebt = "NO: Calendar_DepositDuty_DayT / Calendar_GrtDuty_DayT nam o bang tham so he thong chua co trong MiniHTC. KHONG doan - nhan qua query. Chu thich nguon ghi GrtDuty = 7 ngay nhung VAN KHONG dat mac dinh: chu thich khong phai du lieu."
    });
}).RequireAuthorization();

// ===== Duyệt tự động đơn hàng theo luật (D4OSORA — port 1:1 FrmDuyetTuDongDonHang, 2010.HTC/Sales/Upgrade) =====
string[] _d4OsoraRules = { "Rule1", "Rule2", "Rule2A", "Rule3", "RuleCancel" };
app.MapGet("/api/dms40/so-root-approvals", async (AppDbContext db, ITenantContext t) =>
{
    var items = await db.Dms40SoRootApprovals.Where(x => x.OrgId == t.OrgId).OrderByDescending(x => x.Id).Take(100)
        .Select(x => new { x.ApprovalNo, x.RuleType, x.AffectedCount, x.RunAt }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Khớp btnApprove_Click gốc: chọn luật rồi chạy 1 lượt — RuleCancel hủy hàng loạt SO đang chờ (Sent→Rejected);
// các luật khác duyệt tự động hàng loạt SO đang chờ (Sent→Approved2, bỏ qua Approved1).
app.MapPost("/api/dms40/so-root-approvals/run", async (Dms40ApproveDto dto, AppDbContext db, ITenantContext t) =>
{
    var rule = (dto.RuleType ?? "").Trim();
    if (!_d4OsoraRules.Contains(rule)) return Results.BadRequest(new { error = "Luật không hợp lệ (Rule1|Rule2|Rule2A|Rule3|RuleCancel)." });
    var pending = await db.SalesOrders.Where(o => o.OrgId == t.OrgId && o.Status == "P").ToListAsync();
    var now = DateTime.Now;
    if (rule == "RuleCancel")
        foreach (var o in pending) { o.Status = "C"; o.RejectReason = "Hủy tự động (" + rule + ")"; o.RejectedAt = now; }
    else
        foreach (var o in pending) { o.Status = "A2"; o.Approved1At = now; o.Approved2At = now; }
    var no = "D4OSORA" + DateTime.Now.ToString("yyMMddHHmmss");
    var log = new Dms40SoRootApproval { OrgId = t.OrgId, ApprovalNo = no, RuleType = rule, AffectedCount = pending.Count, RunAt = now };
    db.Dms40SoRootApprovals.Add(log);
    await db.SaveChangesAsync();
    return Results.Ok(new { log.ApprovalNo, log.RuleType, affected = pending.Count });
}).RequireAuthorization();

// Đổi số đơn hàng SO (port 1:1 FrmOrderSOModify, DMSales.Foton/Sales). Chỉ đổi khi còn Draft; mã mới không được trùng.
app.MapPost("/api/salesorders/{no}/rename-code", async (string no, SoRenameDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var o = await db.SalesOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SoCode == no);
    if (o is null) return Results.NotFound(new { no });
    var newCode = (dto.NewSoCode ?? "").Trim().ToUpperInvariant();
    if (string.IsNullOrWhiteSpace(newCode)) return Results.BadRequest(new { error = "Chưa nhập số đơn hàng mới." });
    if (o.Status != "P") return Results.BadRequest(new { error = "Chỉ đổi số đơn hàng khi đơn còn chờ duyệt (P)." });
    if (newCode != no && await db.SalesOrders.AnyAsync(x => x.OrgId == t.OrgId && x.SoCode == newCode))
        return Results.BadRequest(new { error = $"Số đơn hàng '{newCode}' đã tồn tại." });
    var oldCode = o.SoCode;
    o.SoCode = newCode;
    await db.SaveChangesAsync();
    return Results.Ok(new { oldCode, newCode = o.SoCode });
}).RequireAuthorization();

