app.MapPost("/api/cardocrequests", async (CarDocRequestDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.ReceivedPerson)) return Results.BadRequest(new { error = "Cần người nhận." });
    if (string.IsNullOrWhiteSpace(dto.ReceivedAddress)) return Results.BadRequest(new { error = "Cần địa chỉ nhận." });
    var cars = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.CarId)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 xe." });
    var dupe = cars.GroupBy(c => c.CarId.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"Xe {dupe.Key} bị trùng!" });
    var no = "DR" + DateTime.Now.ToString("yyMMddHHmmss");
    // #B31 — `TypeCRR` phải nằm trong TỪ VỰNG `TConst.CarDocReqType`; không tự chế giá trị mới.
    var typeCRR = string.IsNullOrWhiteSpace(dto.TypeCRR) ? "NORMAL" : dto.TypeCRR.Trim().ToUpperInvariant();
    if (typeCRR is not ("NORMAL" or "SPECIAL" or "DEALER" or "DEALERTCG"))
        return Results.BadRequest(new { error = $"TypeCRR '{typeCRR}' không hợp lệ.", allowed = new[] { "NORMAL", "SPECIAL", "DEALER", "DEALERTCG" } });
    var r = new CarDocRequest { OrgId = t.OrgId, RequestNo = no, DealerCode = (dto.DealerCode ?? "").Trim().ToUpperInvariant(), ReceivedPerson = dto.ReceivedPerson.Trim(), ReceivedAddress = dto.ReceivedAddress.Trim(), Status = "Draft", TypeCRR = typeCRR };
    db.CarDocRequests.Add(r); await db.SaveChangesAsync();
    foreach (var c in cars)
        db.CarDocRequestCars.Add(new CarDocRequestCar { OrgId = t.OrgId, RequestId = r.Id, CarId = c.CarId.Trim().ToUpperInvariant(), Remark = c.Remark, DeliveryStartDate = c.DeliveryStartDate });
    await db.SaveChangesAsync();
    return Results.Ok(new { r.RequestNo, r.ReceivedPerson, r.TypeCRR, cars = cars.Count, status = r.Status });
}).RequireAuthorization();

app.MapGet("/api/cardocrequests/{no}/cars", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.CarDocRequests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RequestNo == no);
    if (r is null) return Results.NotFound(new { no });
    var cars = await db.CarDocRequestCars.Where(c => c.OrgId == t.OrgId && c.RequestId == r.Id)
        .Select(c => new { c.CarId, c.Remark, c.DeliveryStartDate }).ToListAsync();
    return Results.Ok(new { r.RequestNo, r.Status, r.TypeCRR, count = cars.Count, cars });
}).RequireAuthorization();


// ===== #B39 HUỶ DÒNG XE CỦA ĐỀ NGHỊ GIẤY TỜ — `CarDocReqDtlCancel_New20210223` =====
// Trace LIVE: `FrmMngDocReqDealer` → `salesSv.CancelCDRDetail(strDRListCode, List<string> lstVin)`
//   (`SalesService.cs:25935`) → WS `CarDocReqDtlCancel` (`WSHTC.asmx.cs:38387`) →
//   **`_biz.CarDocReqDtlCancel_New20210223`** (`DataWH/Biz.HTC.WH.cs:82986`).
//   ⚠️ **4 bản CHẾT** cùng họ: `Delete.BizHTC.Report.cs:118296` (không hậu tố) và `:118610`
//      (`_New20181115`), `DataWH/Delete.Biz.HTC.WH.My.cs:18445` (`_New20181119`), và bản trong
//      `Biz.HTC.WH.Rel.20230823.cs:79103` (file ngoài `TERP.BizHTC.csproj`).
// 🔴 Đây là **bước BẮT BUỘC TRƯỚC** lệnh xoá đã port ở #B31: `Car_DocReqDtlDelete` chỉ nhận dòng
//    đang ở `"C"`. Trước lượt này MiniHTC **không có đường nào đưa dòng về "C"** ⇒ lệnh xoá vô dụng.
// 🔴 Đầu vào là **một `DRListCode` + DANH SÁCH VIN**, nguồn lặp từng VIN trong CÙNG transaction.
// 🔴 `alColumnEffective` đúng **4 cột** (`:83262-83266`): `DRDtlStatus = Stage.Cancel ("C")` ·
//    `CancelDate` · `CancelBy` · `Remark`. Nguồn tách hẳn cặp HUỶ với cặp TỪ CHỐI (`RejectDate`/`RejectBy`).
// 🔴 NĂM guard, trong đó **hai guard cuối chính là NỢ đã ghi ở #B31** — nay đọc được SQL nên đóng luôn:
//    · `_ExistAnotherSpecial` — chú thích nguồn: *"Muốn hủy Đề nghị Normal ⇒ phải hủy ĐN Special trước"*;
//    · `_ExistInvoice` — `VAT_HTCInvoiceDetail.HTCInvoiceCode` hoặc `VAT_TCGInvoiceDetail.TCGInvoiceCode`;
//    · `_ExistRedeem` — `RD_ReqRedeemDtl` join **`DRListCode` VÀ `VIN`**, chỉ dòng `DMReqDtlStatus not in ('R','C')`;
//    · `_ExistRDInvoice` — `RD_ReqInvoiceDtl` join **CHỈ theo `VIN`** (KHÔNG kèm `DRListCode` — khác hẳn
//      nhánh giải chấp ngay bên trên; chép nhầm là đổi hẳn nghiệp vụ), dòng `RDReqIvDtlStatus not in ('R','C')`.
app.MapPost("/api/cardocrequests/{no}/cars/cancel", async (string no, CdrCancelDto dto,
    AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    // `CarDocReqDtlCancel_TblVINTblNotFound` / `_TblVINTblNotInvalid`
    var vins = (dto.Vins ?? new()).Where(v => !string.IsNullOrWhiteSpace(v))
        .Select(v => v.Trim().ToUpperInvariant()).Distinct().ToList();
    if (vins.Count == 0) return Results.BadRequest(new { error = "Chưa chọn xe nào để huỷ.", guard = "CarDocReqDtlCancel_TblVINTblNotFound" });

    var r = await db.CarDocRequests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RequestNo == no);
    if (r is null) return Results.NotFound(new { no });

    var who = user.Identity?.Name ?? "system"; var now = DateTime.Now;
    var lines = await db.CarDocRequestCars.Where(x => x.OrgId == t.OrgId && x.RequestId == r.Id && vins.Contains(x.CarId)).ToListAsync();

    // Nguồn lặp từng VIN trong CÙNG một transaction ⇒ validate hết trước, ghi sau.
    foreach (var vin in vins)
    {
        // `myCar_CheckCar_DocReqDtl(…, Flag.Active)`
        var line = lines.FirstOrDefault(x => x.CarId == vin);
        if (line is null) return Results.BadRequest(new { error = $"Xe {vin} không nằm trong đề nghị {no}." });

        // GUARD 1 — chéo NORMAL ↔ SPECIAL.
        if (string.Equals(r.TypeCRR, "NORMAL", StringComparison.OrdinalIgnoreCase))
        {
            var aliveSpecial = await (
                from c in db.CarDocRequestCars.Where(c => c.OrgId == t.OrgId && c.CarId == vin && c.DRDtlStatus != "R" && c.DRDtlStatus != "C")
                join h in db.CarDocRequests.Where(h => h.OrgId == t.OrgId && h.Id != r.Id
                                                       && h.TypeCRR != "NORMAL" && h.Status != "R" && h.Status != "C")
                     on c.RequestId equals h.Id
                select h.RequestNo).FirstOrDefaultAsync();
            if (aliveSpecial is not null)
                return Results.BadRequest(new { error = $"Xe {vin} còn trong đề nghị SPECIAL {aliveSpecial} còn sống — huỷ đề nghị SPECIAL trước.", guard = "CarDocReqDtlCancel_ExistAnotherSpecial" });
        }

        // GUARD 2 — đã có hoá đơn HTC hoặc TCG.
        var hasHtcInv = await db.VatHtcInvoiceDetails.AnyAsync(x => x.OrgId == t.OrgId && x.VIN == vin);
        var hasTcgInv = await db.VatTcgInvoiceDetails.AnyAsync(x => x.OrgId == t.OrgId && x.VIN == vin);
        if (hasHtcInv || hasTcgInv)
            return Results.BadRequest(new { error = $"Xe {vin} đã có hoá đơn (HTC={hasHtcInv}, TCG={hasTcgInv}) — không huỷ được dòng đề nghị.", guard = "CarDocReqDtlCancel_ExistInvoice" });

        // GUARD 3 — `_ExistRedeem`: join theo **DRListCode VÀ VIN**.
        var redeem = await db.ReqRedeemDtls.Where(x => x.OrgId == t.OrgId && x.VIN == vin
                && x.DRListCode == no && x.DMReqDtlStatus != "R" && x.DMReqDtlStatus != "C")
            .Select(x => x.ReqRedeemId).FirstOrDefaultAsync();
        if (redeem != 0)
            return Results.BadRequest(new { error = $"Xe {vin} đã có đề nghị GIẢI CHẤP còn sống (id {redeem}) — không huỷ được.", guard = "CarDocReqDtlCancel_ExistRedeem" });

        // GUARD 4 — `_ExistRDInvoice`: join **CHỈ theo VIN**, không kèm DRListCode.
        var rdInv = await db.ReqInvoiceDtls.Where(x => x.OrgId == t.OrgId && x.VIN == vin
                && x.RDReqIvDtlStatus != "R" && x.RDReqIvDtlStatus != "C")
            .Select(x => x.ReqInvoiceId).FirstOrDefaultAsync();
        if (rdInv != 0)
            return Results.BadRequest(new { error = $"Xe {vin} đã có đề nghị HOÁ ĐƠN giải chấp còn sống (id {rdInv}) — không huỷ được.", guard = "CarDocReqDtlCancel_ExistRDInvoice", joinNote = "Nguồn join CHỈ theo VIN, không kèm DRListCode." });
    }

    foreach (var vin in vins)
    {
        var line = lines.First(x => x.CarId == vin);
        line.DRDtlStatus = "C";                 // `TConst.Stage.Cancel`
        line.CancelDate = now; line.CancelBy = who;
        line.Remark = dto.Remark;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        requestNo = no, cancelled = vins.Count, vins,
        columnsWritten = new[] { "DRDtlStatus", "CancelDate", "CancelBy", "Remark" },
        nextStep = "Dòng đã ở 'C' — nay mới xoá được bằng DELETE /api/cardocrequests/{no}/cars/{carId} (#B31).",
        guardsChecked = new[] { "ExistAnotherSpecial", "ExistInvoice(HTC/TCG)", "ExistRedeem", "ExistRDInvoice" }
    });
}).RequireAuthorization();
// ===== #B42 CẢNH BÁO — **KHÔNG PORT** `Car_DocReqDtlDelete_ByDealer_New20181119` (`:84003`) =====
// Hàm anh em "ByDealer" của khối dưới đây là **HÀM CHẾT LOGIC**: nó gọi `myCar_CheckCarDocReq` **HAI LẦN**
// cho **CÙNG một `strDRListCode`**, với hai danh sách trạng thái **loại trừ nhau**:
//   · `:84076` → `TConst.Stage.Cancel` = `"C"`      (chú thích: *"chỉ xóa Đề nghị ở trạng thái C"*)
//   · `:84107` → `"P,A1,A2,F"`                       (**không chứa "C"**)
// `myCar_CheckCarDocReq` chỉ có **MỘT chữ ký** (`BizHTC.Car.Profile.cs:147`), luôn kiểm **cùng cột**
// `Car_DocReqList.DRListStatus` bằng `strRequestStatusListToCheck.Contains(status)` (`:190`).
// ⇒ Không trạng thái thật nào thoả **cả hai** ⇒ hàm **luôn ném `CommonAppData_DRListStatusNotMatched`**.
// ⚠️ Kẽ hở duy nhất: `.Contains` là so **chuỗi con**, nên `DRListStatus` **RỖNG** sẽ lọt cả hai guard
//    (`"C".Contains("")` và `"P,A1,A2,F".Contains("")` đều `true`). Thực tế mọi đề nghị đều có trạng thái.
// 🔴 Vì vậy **KHÔNG tạo endpoint** cho nó: port một hàm mà hệ nguồn không bao giờ chạy được thành API
//    chạy được chính là **bịa nghiệp vụ**. Ghi nhận ở đây để lượt sau không "port cho đủ danh sách".
// 📌 Cần người nghiệp vụ chốt ý định thật (đầu đề nghị phải "C" hay "P,A1,A2,F") rồi mới port.
// 📌 Đối chiếu: bản HTC (`Car_DocReqDtlDelete_New20181119`, ngay dưới) **không** mắc lỗi này — chỉ gọi
//    guard đầu đề nghị **một lần** với `"P,A1,A2,F"`.

// ===== #B31 XOÁ DÒNG XE KHỎI ĐỀ NGHỊ GIAO HỒ SƠ — `Car_DocReqDtlDelete_New20181119` =====
// Trace twin LIVE: `SalesService.DeleteCDRDetail` (`:26022`) → WS (`WSHTC.asmx.cs:38579`) →
//   **`_biz.Car_DocReqDtlDelete_New20181119`** (`Biz.HTC.WH.cs:83620`).
//   ⚠️ **4 bản CHẾT** cùng họ trong `Delete.BizHTC.Report.cs` (`:118913`, `:119297`, `:119670`, `:120022`),
//      và một biến thể `_ByDealer_New20181119` (`:84003`) dùng cho WS khác (`:38645`).
// 🔴 GUARD 1 — chỉ xoá được dòng đang ở **`Stage.Cancel` ("C")**: `myCar_CheckCar_DocReqDtl(..., TConst.Stage.Cancel)`
//    kèm chú thích nguyên văn của nguồn: *"chỉ xóa Đề nghị ở trạng thái C"*. ⇒ **phải HUỶ trước, rồi mới XOÁ**.
// 🔴 GUARD 2 — ĐỀ NGHỊ phải thuộc **"P,A1,A2,F"** (`myCar_CheckCarDocReq`).
// 🔴 GUARD 3 — **CHÉO Normal ↔ SPECIAL** (`..._ExistAnotherSpecial`): đề nghị loại `Normal` mà VIN đó còn nằm
//    trong một đề nghị **SPECIAL khác còn sống** ⇒ chặn. (Cùng cơ chế đã port ở lệnh TỪ CHỐI #209.)
// 🔴 GUARD 4 — **`..._ExistInvoice`**: VIN đã có **hoá đơn HTC** (`VHD_HTCInvoiceCode`) **hoặc** **hoá đơn TCG**
//    (`VTD_TCGInvoiceCode`) khác rỗng ⇒ chặn xoá.
// 🔴 GUARD 5/6 — `..._ExistRedeem` và `..._ExistRDInvoice`: đã có đề nghị giải chấp / hoá đơn giải chấp ⇒ chặn.
// 🔴 SIDE-EFFECT DỌN RÁC: sau khi xoá dòng, nguồn **xoá luôn ĐỀ NGHỊ nếu không còn dòng nào**
//    (`delete Car_DocReqList … left join Car_DocReqDtl … where cdrd.DRListCode is null` — "kỹ thuật lọc ngược",
//    chú thích của nguồn). Port cũ không có bước này ⇒ để lại đề nghị RỖNG treo trong danh sách.
app.MapDelete("/api/cardocrequests/{no}/cars/{carId}", async (string no, string carId,
    AppDbContext db, ITenantContext t, string? flagDirect) =>
{
    // `myCommon_CheckHTCDirect(..., Flag.Active)` (`:83680`) — DÒNG ACTIVE.
    if (flagDirect == "0") return Results.BadRequest(new { error = "Chỉ người dùng HTC trực tiếp (FlagDirect='1') được xoá dòng đề nghị." });
    no = no.Trim().ToUpperInvariant(); carId = carId.Trim().ToUpperInvariant();
    var r = await db.CarDocRequests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RequestNo == no);
    if (r is null) return Results.NotFound(new { no });
    var line = await db.CarDocRequestCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RequestId == r.Id && x.CarId == carId);
    if (line is null) return Results.NotFound(new { no, carId });

    // GUARD 1 — dòng phải đang "C" (đã huỷ).
    if (line.DRDtlStatus != "C")
        return Results.BadRequest(new { error = $"Chỉ xoá được dòng đang ở trạng thái huỷ 'C' (đang '{line.DRDtlStatus}') — phải HUỶ trước rồi mới xoá." });
    // GUARD 2 — đề nghị phải thuộc P,A1,A2,F.
    var listStatus = r.Status;
    if (listStatus is not ("P" or "A1" or "A2" or "F" or "Draft" or "Done"))
        return Results.BadRequest(new { error = $"Đề nghị phải thuộc 'P,A1,A2,F' (đang '{listStatus}').", note = "Từ vựng Draft/Done của port cũ là nợ đã ghi ở #209." });

    // GUARD 3 — chéo Normal ↔ SPECIAL.
    if (string.Equals(r.TypeCRR, "NORMAL", StringComparison.OrdinalIgnoreCase))
    {
        var aliveSpecial = await (
            from c in db.CarDocRequestCars.Where(c => c.OrgId == t.OrgId && c.CarId == carId && c.DRDtlStatus != "R" && c.DRDtlStatus != "C")
            join h in db.CarDocRequests.Where(h => h.OrgId == t.OrgId && h.Id != r.Id
                                                   && h.TypeCRR != "NORMAL" && h.Status != "R" && h.Status != "C")
                 on c.RequestId equals h.Id
            select h.RequestNo).FirstOrDefaultAsync();
        if (aliveSpecial is not null)
            return Results.BadRequest(new { error = $"Xe {carId} còn nằm trong đề nghị SPECIAL {aliveSpecial} còn sống — huỷ đề nghị SPECIAL trước.", guard = "CarDocReqDtlDelete_ExistAnotherSpecial" });
    }

    // GUARD 4 — đã có hoá đơn HTC hoặc TCG.
    var hasHtcInv = await db.VatHtcInvoiceDetails.AnyAsync(x => x.OrgId == t.OrgId && x.VIN == carId);
    var hasTcgInv = await db.VatTcgInvoiceDetails.AnyAsync(x => x.OrgId == t.OrgId && x.VIN == carId);
    if (hasHtcInv || hasTcgInv)
        return Results.BadRequest(new { error = $"Xe {carId} đã có hoá đơn (HTC={hasHtcInv}, TCG={hasTcgInv}) — không xoá được dòng đề nghị.", guard = "CarDocReqDtlDelete_ExistInvoice" });

    // ✅ #B39 ĐÓNG NỢ #B31 — hai guard cuối, SQL đọc được ở hàm HUỶ anh em (`Biz.HTC.WH.cs:83225-83246`).
    // GUARD 5 — `_ExistRedeem`: `RD_ReqRedeemDtl` join **DRListCode VÀ VIN**, dòng `not in ('R','C')`.
    var delRedeem = await db.ReqRedeemDtls.Where(x => x.OrgId == t.OrgId && x.VIN == carId
            && x.DRListCode == no && x.DMReqDtlStatus != "R" && x.DMReqDtlStatus != "C")
        .Select(x => x.ReqRedeemId).FirstOrDefaultAsync();
    if (delRedeem != 0)
        return Results.BadRequest(new { error = $"Xe {carId} đã có đề nghị GIẢI CHẤP còn sống (id {delRedeem}) — không xoá được.", guard = "Car_DocReqDtlDelete_ExistRedeem" });
    // GUARD 6 — `_ExistRDInvoice`: `RD_ReqInvoiceDtl` join **CHỈ theo VIN**, dòng `not in ('R','C')`.
    var delRdInv = await db.ReqInvoiceDtls.Where(x => x.OrgId == t.OrgId && x.VIN == carId
            && x.RDReqIvDtlStatus != "R" && x.RDReqIvDtlStatus != "C")
        .Select(x => x.ReqInvoiceId).FirstOrDefaultAsync();
    if (delRdInv != 0)
        return Results.BadRequest(new { error = $"Xe {carId} đã có đề nghị HOÁ ĐƠN giải chấp còn sống (id {delRdInv}) — không xoá được.", guard = "Car_DocReqDtlDelete_ExistRDInvoice" });

    db.CarDocRequestCars.Remove(line);
    await db.SaveChangesAsync();

    // SIDE-EFFECT: xoá luôn ĐỀ NGHỊ nếu không còn dòng nào ("kỹ thuật lọc ngược" của nguồn).
    var remain = await db.CarDocRequestCars.CountAsync(x => x.OrgId == t.OrgId && x.RequestId == r.Id);
    var headerDeleted = false;
    if (remain == 0) { db.CarDocRequests.Remove(r); await db.SaveChangesAsync(); headerDeleted = true; }

    return Results.Ok(new
    {
        deleted = new { no, carId }, remainingCars = remain, headerDeleted,
        headerDeleteRule = "Nguồn xoá luôn Car_DocReqList khi không còn Car_DocReqDtl tương ứng (left join … where is null).",
        guardsChecked = new[] { "DRDtlStatus='C'", "DRListStatus in (P,A1,A2,F)", "ExistAnotherSpecial", "ExistInvoice(HTC/TCG)" },
        debt = "ĐÃ ĐÓNG ở #B39: _ExistRedeem và _ExistRDInvoice nay đã kiểm (SQL đọc được từ hàm HUỶ anh em)."
    });
}).RequireAuthorization();

// ⚠️ #B31 ĐÃ GỠ `POST /api/cardocrequests/{no}/complete` — nút "hoàn tất" **TỰ CHẾ** (Draft→Done).
//    Họ lệnh THẬT của nguồn ở mức DÒNG: `CarDocReqDtlApprove2` · `CarDocReqDtlCancel` · `CarDocReqDtlReject`
//    · `Car_DocReqDtlDelete`; ở mức ĐỀ NGHỊ chỉ có `CarDocReqListCancel` / `CarDocReqListDelete`.
//    **Không có lệnh nào "hoàn tất" cả đề nghị** (luật C0-trecentesimusseptuagesimussextus).

// ===== 🔴 #209 TỪ CHỐI THEO DÒNG — `CarDocReqDtlReject_New20181119` (DataWH/Biz.HTC.WH.cs:83426) =====
// BƯỚC 3B: căn theo **MỐC HÀM** (laptop 83426 / máy 150 83431 — file này lệch offset, xem luật #208):
//   md5 vùng hàm `634c0032` KHỚP 2 máy.
// TWIN FILE: hàm còn ở `Biz.HTC.WH.Rel.20230823.cs:79543` — file KHÔNG có trong csproj ⇒ FILE CHẾT.
//
// ⚠️ ĐÃ BỎ `POST /api/cardocrequests/{no}/reject` (từ chối theo HEADER): nguồn **không có** lệnh nào từ chối
//    cả đề nghị. Cả họ lệnh đều ở mức DÒNG — `CarDocReqDtlApprove2` · `CarDocReqDtlCancel` ·
//    `CarDocReqDtlReject` · `Car_DocReqDtlDelete`; mức đề nghị chỉ có `CarDocReqListCancel`/`...ListDelete`.
//
// BA GUARD của nguồn, đúng thứ tự:
//  1. DÒNG phải đang **"A2"** (đã duyệt cấp 2) — `myCar_CheckCar_DocReqDtl(..., "A2")`;
//  2. ĐỀ NGHỊ phải thuộc **"P,A1,A2,F"** — `myCar_CheckCarDocReq(..., "P,A1,A2,F")`;
//  3. 🔴 **GUARD CHÉO Normal ↔ SPECIAL**: nếu đề nghị là loại `Normal` mà chính VIN đó còn nằm trong một
//     đề nghị **SPECIAL khác** còn sống (`DRListStatus not in ('R','C')` **và** `DRDtlStatus not in ('R','C')`)
//     ⇒ chặn với `CarDocReqDtlReject_ExistAnotherSpecial` — *muốn huỷ ĐN Normal phải huỷ ĐN Special trước*.
//
// Nguồn ghi trên DÒNG: `DRDtlStatus = Stage.Rejected ("R")` · `RejectDate` · `RejectBy` · `Remark` · `LogLU*`.
// ⚠️ NỢ: `CarDocRequest.Status` của port đang dùng từ vựng `Draft/Done/Rejected` — nguồn dùng `DRListStatus`
//    với bộ P/A1/A2/F/R/C. Đổi sẽ lan ra nhiều endpoint ⇒ để lượt riêng (giữ "một biến").
app.MapPost("/api/cardocrequests/{no}/cars/{carId}/reject", async (string no, string carId,
    SoRejectDto? dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant(); carId = carId.Trim().ToUpperInvariant();
    var r = await db.CarDocRequests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RequestNo == no);
    if (r is null) return Results.NotFound(new { no });
    var line = await db.CarDocRequestCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RequestId == r.Id && x.CarId == carId);
    if (line is null) return Results.NotFound(new { no, carId });

    // guard 1 — dòng phải đã duyệt cấp 2.
    if ((line.DRDtlStatus ?? "") != "A2")
        return Results.BadRequest(new { error = $"Dòng xe {carId} đang '{line.DRDtlStatus}' — chỉ từ chối dòng đã duyệt cấp 2 (A2)." });

    // guard 3 — Normal mà VIN còn trong một ĐN SPECIAL khác còn sống thì chặn.
    if (string.Equals(line.CarDocReqTypeCRR, "NORMAL", StringComparison.OrdinalIgnoreCase))
    {
        var conflict = await db.CarDocRequestCars
            .Where(x => x.OrgId == t.OrgId && x.CarId == carId && x.RequestId != r.Id
                     && x.DRDtlStatus != "R" && x.DRDtlStatus != "C"
                     && x.CarDocReqTypeCRR == "SPECIAL")
            .Select(x => x.RequestId).FirstOrDefaultAsync();
        if (conflict != 0)
            return Results.BadRequest(new { error = $"Xe {carId} còn nằm trong một đề nghị SPECIAL khác — phải huỷ đề nghị SPECIAL trước.", conflictRequestId = conflict });
    }

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    line.DRDtlStatus = "R";                      // TConst.Stage.Rejected
    line.RejectDate = now; line.RejectBy = who;
    if (!string.IsNullOrWhiteSpace(dto?.Reason)) line.Remark = dto!.Reason!.Trim();   // nguồn ghi vào `Remark`
    line.LogLUDateTime = now; line.LogLUBy = who;

    await db.SaveChangesAsync();
    return Results.Ok(new { r.RequestNo, line.CarId, drDtlStatus = line.DRDtlStatus, line.RejectDate, line.RejectBy, line.Remark });
}).RequireAuthorization();

// ===== Lệnh giao xe cho đại lý (DeliveryOrder — port 1:1 FrmNewDO/FrmMngDO, DMSales.Foton) =====
app.MapGet("/api/deliveryorders", async (AppDbContext db, ITenantContext t, string? status, string? dealer) =>
{
    var q = db.DeliveryOrders.Where(o => o.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(o => o.Status == status);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(o => o.DealerCode == dealer);
    var items = await q.OrderByDescending(o => o.Id).Take(500).Select(o => new
    {
        o.DoNo, o.DealerCode, o.Status, o.CreatedAt, o.DeliveredAt, o.Approved1At, o.Approved2At, o.RejectReason,
        o.DeliveryAddress, o.TransportCompanyName, o.TransportCompanyPhoneNo, o.TransportCompanyFaxNo, o.D4CDONo, o.D4CDOType,
        cars = db.DeliveryOrderCars.Count(c => c.OrgId == t.OrgId && c.DoId == o.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/deliveryorders", async (DeliveryOrderDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Cần DealerCode." });
    var vins = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.Vin)).ToList();
    if (vins.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 VIN." });
    var dupe = vins.GroupBy(c => c.Vin.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });
    var no = "DO" + DateTime.Now.ToString("yyMMddHHmmss");
    // 🔴 Nguồn `CarDeliveryOrderCreate_New20181119` (Biz.HTC.WH.cs:49868) tạo lệnh là "P" ngay.
    var o = new DeliveryOrder { OrgId = t.OrgId, DoNo = no, DealerCode = dto.DealerCode.Trim().ToUpperInvariant(), Status = "P" };
    db.DeliveryOrders.Add(o); await db.SaveChangesAsync();
    foreach (var c in vins)
        db.DeliveryOrderCars.Add(new DeliveryOrderCar { OrgId = t.OrgId, DoId = o.Id, Vin = c.Vin.Trim().ToUpperInvariant(), ModelCode = c.ModelCode, ColorCode = c.ColorCode, StorageCode = c.StorageCode, DeliveryExpectDate = c.DeliveryExpectDate });
    await db.SaveChangesAsync();
    return Results.Ok(new { o.DoNo, o.DealerCode, cars = vins.Count, status = o.Status });
}).RequireAuthorization();

// ===== #175 TỰ SINH LỆNH GIAO XE HÀNG LOẠT — `DMS40_Car_DeliveryOrder_CreateAuto_New20190125` =====
// Nguồn: `TERP.BizHTC/DMS40/zTemp.0.31.Car.cs:4601` (csproj 280).
// BƯỚC 3B: md5 CẢ FILE `9a2ec524` KHỚP 2 máy. TWIN: WS 32-bit và 64-bit gọi CÙNG bản `_New20190125`.
//
// 🔴 Đây là lệnh CUỐI CÙNG còn thiếu của cụm `Car_DeliveryOrder` — MiniHTC đã có
//    Create/Approve1/Approve2/DetailUpdate/DetailDelete, chỉ thiếu bản TỰ SINH.
//
// Nghiệp vụ: từ một **đợt tự sinh** (`D4CDONo`) đã gom sẵn danh sách đại lý (`Auto_Car_DeliveryOrder_Dealer`)
// và danh sách xe theo đại lý (`Auto_Car_DeliveryOrder_Car`), hàm **duyệt TỪNG đại lý** và với mỗi đại lý:
//   1. xin một số lệnh giao mới (`SequenceGetForDMS_MyGet`, `SequenceTypeDMS.CarDeliveryOrder`);
//   2. lấy địa chỉ giao = `Mst_Dealer.DealerAddress01` (KHÔNG nhập tay);
//   3. lấy xe của đại lý đó, mỗi dòng gồm `CarId` + `StorageCode` = **`Car_VIN.StorageCodeCurrent`**
//      (kho HIỆN TẠI của xe, không phải kho khai báo) + `DeliveryVIN`, còn `DeliveryOutDate`/`DeliveryRemark`
//      để **NULL** (điền ở bước giao thực tế);
//   4. gọi liền chuỗi **Create → Approve1 → Approve2** ⇒ lệnh giao ra đời **đã duyệt cấp 2 ngay**.
//
// 🔴 `D4CDOType` bắt buộc (`CreateAuto_InvalidD4CDOType`) và chỉ nhận **"RULE1"** hoặc **"RULE2"**
//    (`TConst.D4CDOType`). Khác biệt: RULE1 dùng `CarDeliveryOrderCreateX`, RULE2 dùng
//    `CarDeliveryOrderCreate_Rule2X`; **cả hai nhánh đều duyệt tiếp 1 rồi 2**.
// ⚠️ Nguồn gọi Approve2 với `dtimeTDate.AddSeconds(2)` — cố ý để mốc duyệt cấp 2 SAU cấp 1, tránh hai
//    mốc trùng giây. Đã giữ.
app.MapPost("/api/deliveryorders/create-auto", async (DoCreateAutoDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var batchNo = (dto.D4CDONo ?? "").Trim().ToUpperInvariant();
    if (batchNo.Length == 0) return Results.BadRequest(new { error = "Chưa nhập số đợt tự sinh (D4CDONo)." });
    var ruleType = (dto.D4CDOType ?? "").Trim().ToUpperInvariant();
    if (ruleType is not ("RULE1" or "RULE2"))
        return Results.BadRequest(new { error = "Loại tự sinh chỉ nhận RULE1 hoặc RULE2." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;

    // Danh sách đại lý của đợt.
    var dealerCodes = await db.AutoDoDealers.Where(x => x.OrgId == t.OrgId && x.D4CDONo == batchNo)
        .Select(x => x.DealerCode).Distinct().ToListAsync();
    if (dealerCodes.Count == 0)
        return Results.BadRequest(new { error = $"Đợt {batchNo} chưa có đại lý nào.", d4cdoNo = batchNo });

    var created = new List<object>();
    foreach (var dealerCode in dealerCodes)
    {
        // Địa chỉ giao lấy từ MASTER đại lý, không nhập tay.
        var dlr = await db.Dealers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == dealerCode);
        if (dlr is null) return Results.BadRequest(new { error = $"Đại lý {dealerCode} không tồn tại.", dealerCode });

        var cars = await db.AutoDoCars.Where(x => x.OrgId == t.OrgId && x.D4CDONo == batchNo && x.DealerCode == dealerCode).ToListAsync();
        if (cars.Count == 0) continue;   // đại lý không có xe trong đợt thì bỏ qua

        var doNo = "DO" + now.ToString("yyMMddHHmmss") + created.Count.ToString("00");
        var o = new DeliveryOrder
        {
            OrgId = t.OrgId, DoNo = doNo, DealerCode = dealerCode,
            DeliveryAddress = dlr.DealerAddress01,
            // chuỗi Create → Approve1 → Approve2 chạy liền ⇒ trạng thái cuối là "A2"
            Status = "A2", CreatedAt = now,
            Approved1At = now, ApprovedBy1 = who,
            Approved2At = now.AddSeconds(2), ApprovedBy2 = who,   // nguồn cộng 2 giây, giữ nguyên
            // Ba cot don vi van chuyen: nguon truyen vao CarDeliveryOrderCreateX qua tham so.
            TransportCompanyName = dto.TransportCompanyName, TransportCompanyPhoneNo = dto.TransportCompanyPhoneNo,
            TransportCompanyFaxNo = dto.TransportCompanyFaxNo,
            D4CDONo = batchNo, D4CDOType = ruleType,
        };
        db.DeliveryOrders.Add(o);
        await db.SaveChangesAsync();

        foreach (var c in cars)
        {
            // `StorageCode` lấy từ `Car_VIN.StorageCodeCurrent` — kho HIỆN TẠI của xe.
            var vinRow = await db.CarVinMasters.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.VIN == c.VIN);
            db.DeliveryOrderCars.Add(new DeliveryOrderCar
            {
                OrgId = t.OrgId, DoId = o.Id, Vin = c.VIN, CarId = c.CarId,
                StorageCode = vinRow?.StorageCodeCurrent ?? c.StorageCode,
                DeliveryOutDate = null, DeliveryRemark = null,   // nguồn để NULL, điền ở bước giao thực tế
                ConfirmStatus = "P",
            });
        }
        await db.SaveChangesAsync();
        created.Add(new { doNo, dealerCode, cars = cars.Count });
    }

    return Results.Ok(new { d4cdoNo = batchNo, d4cdoType = ruleType, dealers = dealerCodes.Count,
        ordersCreated = created.Count, orders = created });
}).RequireAuthorization();

app.MapGet("/api/deliveryorders/{no}/cars", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
