app.MapPost("/api/deliveryorders/{no}/edit-dates", async (string no, DoEditDatesDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var o = await db.DeliveryOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DoNo == no);
    if (o is null) return Results.NotFound(new { no });
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.Vin)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Không có xe thay đổi." });
    // validate: ngày KT >= ngày BĐ
    foreach (var l in lines)
        if (l.DeliveryStartDate.HasValue && l.DeliveryEndDate.HasValue && l.DeliveryEndDate < l.DeliveryStartDate)
            return Results.BadRequest(new { error = $"VIN {l.Vin}: ngày kết thúc phải >= ngày bắt đầu." });
    var cars = await db.DeliveryOrderCars.Where(c => c.OrgId == t.OrgId && c.DoId == o.Id).ToListAsync();
    var byVin = cars.ToDictionary(c => c.Vin.ToUpperInvariant(), c => c);
    int updated = 0; var notFound = new List<string>();
    foreach (var l in lines)
    {
        var key = l.Vin!.Trim().ToUpperInvariant();
        if (!byVin.TryGetValue(key, out var c)) { notFound.Add(l.Vin!.Trim()); continue; }
        c.DeliveryStartDate = l.DeliveryStartDate; c.DeliveryEndDate = l.DeliveryEndDate; c.DeliveryOutDate = l.DeliveryOutDate;
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// ⚠️ ĐÃ BỎ `/deliver`: nguồn KHÔNG có trạng thái "đã giao" trên `Car_DeliveryOrder`
//    (chỉ 3 điểm ghi cột trạng thái, đều là P/A1/A2/R). Giao xe thực tế thuộc màn Biên bản giao xe.
// ⚠️ ĐÃ BỎ `/reject` riêng: nguồn đặt **từ chối là NHÁNH FALSE của duyệt cấp 1**
//    (`objDeliveryOrderStatusNew = bApprove ? Approved1 : Rejected`), không phải một hành động độc lập.

// 🔴 Duyệt cấp 1 — `CarDeliveryOrderApprove1_New20181119` (Biz.HTC.WH.cs:50318-50420).
//    Vào từ "P". `approve=false` ⇒ **"R" (từ chối)** ngay trong hàm này. Ghi cả ngày LẪN người duyệt.
app.MapPost("/api/deliveryorders/{no}/approve1", async (string no, DoApproveDto? dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var o = await db.DeliveryOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DoNo == no);
    if (o is null) return Results.NotFound(new { no });
    if (o.Status != "P") return Results.BadRequest(new { error = "Chỉ duyệt cấp 1 lệnh đang chờ duyệt (P)." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var ok = dto?.Approve ?? true;
    var now1 = DateTime.Now;
    o.Status = ok ? "A1" : "R";
    o.Approved1At = now1; o.ApprovedBy1 = who;
    if (!ok) { o.RejectReason = dto?.Reason; o.RejectedAt = now1; }

    // 🔴 #197 CASCADE khi TỪ CHỐI — khối `if (!bApprove)` của nguồn (Biz.HTC.WH.cs:50424-50470).
    //    Vùng hàm 50318-50630 md5 `c5ffcc37` KHỚP 2 máy (file này CÓ lệch ở chỗ khác — dòng `65379 —
    //    nên phải đo md5 THEO VÙNG HÀM, không theo cả file; xem luật `C0-ducentesimusoctogesimusprimus`).
    //    Nguồn làm HAI việc mà port cũ bỏ cả hai:
    //      (a) mọi dòng xe của lệnh → `ConfirmStatus = "R"` + `LogLU*`;
    //      (b) 🔴 `Car_Car.FlagAllowChangeVIN = "1"` cho từng xe — **trả xe về trạng thái còn đổi VIN được**.
    //    Nhánh DUYỆT (`bApprove`) KHÔNG cascade gì — giữ đúng sự bất đối xứng đó.
    var rejectedRows = 0; var vinsFreed = 0;
    if (!ok)
    {
        var doCars = await db.DeliveryOrderCars.Where(x => x.OrgId == t.OrgId && x.DoId == o.Id).ToListAsync();
        foreach (var dc in doCars)
        { dc.ConfirmStatus = "R"; dc.LogLUDateTime = now1; dc.LogLUBy = who; rejectedRows++; }
        var vins = doCars.Select(x => x.Vin).ToList();
        foreach (var cv in await db.CarVinMasters.Where(x => x.OrgId == t.OrgId && vins.Contains(x.VIN)).ToListAsync())
        { cv.FlagAllowChangeVIN = "1"; cv.LogLUDateTime = now1; cv.LogLUBy = who; vinsFreed++; }
    }

    await db.SaveChangesAsync();
    return Results.Ok(new { o.DoNo, status = o.Status, statusName = ok ? "Duyệt cấp 1" : "Từ chối",
                            rejectedRows, vinsFreed });
}).RequireAuthorization();

// 🔴 Duyệt cấp 2 — `CarDeliveryOrderApprove2_New20181119` (50523-50626). Vào từ "A1".
//    `approve=false` ⇒ **BỎ DUYỆT, trả lệnh về "P"** (KHÁC cấp 1: cấp 1 từ chối sang "R").
app.MapPost("/api/deliveryorders/{no}/approve2", async (string no, DoApproveDto? dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var o = await db.DeliveryOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DoNo == no);
    if (o is null) return Results.NotFound(new { no });
    if (o.Status != "A1") return Results.BadRequest(new { error = "Lệnh phải duyệt cấp 1 (A1) trước." });
    var ok = dto?.Approve ?? true;
    o.Status = ok ? "A2" : "P";
    o.Approved2At = DateTime.Now; o.ApprovedBy2 = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    await db.SaveChangesAsync();
    return Results.Ok(new { o.DoNo, status = o.Status, statusName = ok ? "Duyệt cấp 2" : "Chờ duyệt (đã bỏ duyệt)" });
}).RequireAuthorization();

// 🔴 Sửa dòng xe trong lệnh — `CarDeliveryOrderDetailUpdate_New20181119` (50893-51010): sửa ngày xuất kho
//    + ghi chú giao xe của MỘT xe. Guard theo `ConfirmStatus` của DÒNG (`"P,A"`), KHÔNG theo trạng thái lệnh.
app.MapPost("/api/deliveryorders/{no}/cars/{vin}", async (string no, string vin, DoCarUpdateDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant(); vin = vin.Trim().ToUpperInvariant();
    var o = await db.DeliveryOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DoNo == no);
    if (o is null) return Results.NotFound(new { no });
    var c = await db.DeliveryOrderCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DoId == o.Id && x.Vin == vin);
    if (c is null) return Results.NotFound(new { no, vin });
    if (c.ConfirmStatus is not ("P" or "A"))
        return Results.BadRequest(new { error = $"Xe {vin} có trạng thái xác nhận '{c.ConfirmStatus}' — chỉ sửa khi P hoặc A." });
    c.DeliveryOutDate = dto.DeliveryOutDate; c.DeliveryRemark = dto.DeliveryRemark;
    await db.SaveChangesAsync();
    return Results.Ok(new { o.DoNo, c.Vin, c.DeliveryOutDate, c.DeliveryRemark });
}).RequireAuthorization();

// 🔴 Xoá dòng xe khỏi lệnh — `CarDeliveryOrderDetailDelete_New20181119` (51059-51400).
//    Nguồn chặn xoá bằng **4 ràng buộc hạ nguồn** rồi mới xoá; xoá xong nếu lệnh KHÔNG còn dòng nào
//    thì **xoá luôn header** (kỹ thuật lọc ngược trong SQL), và trả xe về cho phép đổi VIN.
app.MapDelete("/api/deliveryorders/{no}/cars/{vin}", async (string no, string vin, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant(); vin = vin.Trim().ToUpperInvariant();
    var o = await db.DeliveryOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DoNo == no);
    if (o is null) return Results.NotFound(new { no });
    var c = await db.DeliveryOrderCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DoId == o.Id && x.Vin == vin);
    if (c is null) return Results.NotFound(new { no, vin });

    // (1) Đã có yêu cầu vận chuyển tham chiếu chính lệnh này (nguồn: `Sto_TranspReqDtl.RefOrdNo = DO`,
    //     loại CARTRANSPORT, trạng thái dòng không thuộc R/C).
    //     ⚠️ `TransportReqCar` của MiniHTC CHƯA có cột trạng thái dòng ⇒ tạm lọc theo VIN + số lệnh; đã ghi nợ.
    if (await db.TransportReqCars.AnyAsync(x => x.OrgId == t.OrgId && x.Vin == vin && x.DoNo == no))
        return Results.BadRequest(new { error = $"Xe {vin} đã có yêu cầu vận chuyển — không xoá được khỏi lệnh giao." });
    // (2) Đã lên bảng kê hoá đơn (nguồn kiểm `InvoiceListCode`).
    if (await db.InvoiceLines.AnyAsync(x => x.OrgId == t.OrgId && x.Vin == vin))
        return Results.BadRequest(new { error = $"Xe {vin} đã nằm trong bảng kê hoá đơn — không xoá được." });
    // (3) Dòng đã xác nhận (A) hoặc hoàn tất (F) thì còn phải sạch hồ sơ đăng ký xe (`Car_DocReqDtl`).
    if (c.ConfirmStatus is "A" or "F" && await db.DocReqCars.AnyAsync(x => x.OrgId == t.OrgId && x.Vin == vin))
        return Results.BadRequest(new { error = $"Xe {vin} đã có hồ sơ đăng ký — không xoá được." });
    // (4) Đã có yêu cầu bảo hiểm (`Ins_InsuranceReqDtl`).
    if (await db.InsuranceReqDtls.AnyAsync(x => x.OrgId == t.OrgId && x.VIN == vin))
        return Results.BadRequest(new { error = $"Xe {vin} đã có yêu cầu bảo hiểm — không xoá được." });

    db.DeliveryOrderCars.Remove(c);
    await db.SaveChangesAsync();
    // Nguồn xoá luôn header khi lệnh không còn dòng nào.
    var left = await db.DeliveryOrderCars.CountAsync(x => x.OrgId == t.OrgId && x.DoId == o.Id);
    var headerRemoved = false;
    if (left == 0) { db.DeliveryOrders.Remove(o); headerRemoved = true; await db.SaveChangesAsync(); }
    // ✅ #197 TRẢ NỢ: nguồn còn `update Car_Car set FlagAllowChangeVIN = '1'` (trả xe về cho phép đổi VIN).
    //    Cột đã có ở `CarVinMaster` từ lượt này ⇒ ghi thật thay vì để nợ.
    var freed = false;
    var cvm = await db.CarVinMasters.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.VIN == vin);
    if (cvm is not null)
    {
        cvm.FlagAllowChangeVIN = "1";
        cvm.LogLUDateTime = DateTime.Now;
        cvm.LogLUBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
        freed = true;
        await db.SaveChangesAsync();
    }
    return Results.Ok(new { no, vin, carsLeft = left, headerRemoved, flagAllowChangeVinSet = freed });
}).RequireAuthorization();
// ===== #B64 HỢP NHẤT SONG TRÙNG `Tkhq`/`CtTkhq` (ca thứ 8) — cụm `/api/tkhqs` trỏ về `CtTkhq*` =====
// Hai thực thể cùng ánh xạ **`CT_TKHQ`** và **cùng khoá nghiệp vụ `DeclarationNo`**; cả hai đều đang
// được ghi (`db.Tkhqs.Add` `:32471`, `db.CtTkhqs.Add` `:31176`) ⇒ tờ khai vào **hai bảng khác nhau**.
// 🔴 **`Tkhq` là thực thể BỊA**, đối chiếu writer thật của nguồn (`Biz.HTC.WH.cs:37860-37917`,
//    `SaveData("CT_TKHQ", …)`) — cột nguồn đúng **6**: `DeclarationNo` · `OpenDate` · `PortCode` ·
//    `Remark` · `CreatedDate` · `CreatedBy`; bảng con là **VIN** (`dr["VIN"]`).
//    ⇒ `CT_TKHQ` **KHÔNG có `Status`** và **KHÔNG có `ContractNo`**. Vậy:
//      · `Status = "Open" → "Cleared"` là **từ vựng BỊA** ⇒ endpoint `POST /api/tkhqs/{no}/clear`
//        (thông quan) **không có ở nguồn** ⇒ **ĐÃ GỠ** (cùng loại vi phạm đã gỡ ở #B31, #B35).
//      · `ContractNo` là **cột ngoài nguồn** ⇒ bỏ khỏi guard bắt buộc.
//      · Bảng con `TkhqPL` (packing list) **không phải quan hệ của `CT_TKHQ`** ở nguồn — quan hệ thật là
//        **VIN** (`CtTkhqVin`, đã có). `TkhqPL` giữ lại, **ngừng ghi**.
// ⇒ Cụm `/api/tkhqs` nay đọc/ghi **`CtTkhqs` + `CtTkhqVins`**, giữ nguyên đường dẫn để không vỡ lời gọi cũ.
//    `Tkhq`/`TkhqPL` giữ lại nhưng không còn được ghi (tiền lệ `WholesaleDeal` #B09, `CtmVisit` #B62,
//    `CBReq` #B63) — xoá sẽ mất dữ liệu đã nhập.
app.MapGet("/api/tkhqs", async (AppDbContext db, ITenantContext t, string? contract, string? declarationNo) =>
{
    var q = db.CtTkhqs.Where(k => k.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(declarationNo))
    { var kk = declarationNo.Trim().ToUpperInvariant(); q = q.Where(k => k.DeclarationNo.Contains(kk)); }
    var items = await q.OrderByDescending(k => k.Id).Take(500).Select(k => new
    {
        k.DeclarationNo, k.PortCode, k.OpenDate, k.Remark, k.TaxPaymentDate, k.CreatedAt,
        vins = db.CtTkhqVins.Count(v => v.OrgId == t.OrgId && v.CtTkhqId == k.Id)
    }).ToListAsync();
    return Results.Ok(new
    {
        count = items.Count, items,
        droppedFilter = string.IsNullOrWhiteSpace(contract) ? null
            : "Bo loc 'contract' KHONG dung duoc: CT_TKHQ cua nguon khong co cot ContractNo (writer Biz.HTC.WH.cs:37860-37917).",
        mergeNote = "#B64 hop nhat song trung ca 8: cum /api/tkhqs nay doc CtTkhqs (bang dung theo nguon CT_TKHQ). Tkhq/TkhqPL ngung ghi."
    });
}).RequireAuthorization();

app.MapPost("/api/tkhqs", async (TkhqDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DeclarationNo)) return Results.BadRequest(new { error = "Cần số TKHQ (DeclarationNo)." });
    var no = dto.DeclarationNo.Trim().ToUpperInvariant();
    if (await db.CtTkhqs.AnyAsync(x => x.OrgId == t.OrgId && x.DeclarationNo == no))
        return Results.BadRequest(new { error = $"Số TKHQ {no} đã tồn tại." });
    // Sáu cột của writer nguồn; `ContractNo` KHÔNG có ở `CT_TKHQ` nên không nhận làm guard bắt buộc.
    var k = new CtTkhq
    {
        OrgId = t.OrgId, DeclarationNo = no, PortCode = dto.PortCode,
        OpenDate = dto.OpenDate ?? DateTime.Now, Remark = dto.Remark, CreatedAt = DateTime.Now
    };
    db.CtTkhqs.Add(k); await db.SaveChangesAsync();
    return Results.Ok(new
    {
        k.DeclarationNo, k.PortCode, k.OpenDate, k.Remark,
        columnsWritten = new[] { "DeclarationNo", "OpenDate", "PortCode", "Remark", "CreatedDate" },
        notPorted = "ContractNo va Status/ClearedAt KHONG co trong CT_TKHQ cua nguon - da bo. Quan he con cua CT_TKHQ la VIN (dung POST /api/cttkhqs de gan VIN), khong phai packing list."
    });
}).RequireAuthorization();

app.MapGet("/api/tkhqs/{no}/vins", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var k = await db.CtTkhqs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DeclarationNo == no);
    if (k is null) return Results.NotFound(new { no });
    var vins = await db.CtTkhqVins.Where(v => v.OrgId == t.OrgId && v.CtTkhqId == k.Id)
        .Select(v => v.Vin).ToListAsync();
    return Results.Ok(new
    {
        k.DeclarationNo, k.OpenDate, k.TaxPaymentDate, count = vins.Count, vins,
        replacesNote = "Thay cho GET /api/tkhqs/{no}/pls cu: quan he that cua CT_TKHQ la VIN, khong phai packing list."
    });
}).RequireAuthorization();
// ===== Thư tín dụng (LC — port 1:1 FrmNewLC/FrmMngLC, DMSales.Foton) =====
app.MapGet("/api/lcs", async (AppDbContext db, ITenantContext t, string? status, string? contract) =>
{
    var q = db.LettersOfCredit.Where(l => l.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(l => l.Status == status);
    if (!string.IsNullOrWhiteSpace(contract)) q = q.Where(l => l.ContractNo.Contains(contract.ToUpper()));
    var now = DateTime.Now;
    var items = await q.OrderByDescending(l => l.Id).Take(500).Select(l => new
    { l.LCNo, l.ContractNo, l.BankName, l.Amount, l.OpenDate, l.ExpiryDate, l.Status, expired = l.ExpiryDate != null && l.ExpiryDate < now && l.Status == "Open" }).ToListAsync();
    return Results.Ok(new { count = items.Count, totalAmount = items.Sum(x => x.Amount), items });
}).RequireAuthorization();

app.MapPost("/api/lcs", async (LcDto dto, AppDbContext db, ITenantContext t) =>
{
    // guard đúng FrmNewLC: cần ContractNo, LCNo, BankName
    if (string.IsNullOrWhiteSpace(dto.ContractNo)) return Results.BadRequest(new { error = "Cần số hợp đồng (ContractNo)." });
    if (string.IsNullOrWhiteSpace(dto.LCNo)) return Results.BadRequest(new { error = "Cần số LC (LCNo)." });
    if (string.IsNullOrWhiteSpace(dto.BankName)) return Results.BadRequest(new { error = "Cần ngân hàng (BankName)." });
    if (dto.ExpiryDate is DateTime ed && dto.OpenDate is DateTime od && ed < od)
        return Results.BadRequest(new { error = "Ngày hết hạn phải ≥ ngày mở." });
    var no = dto.LCNo.Trim().ToUpperInvariant();
    var l = await db.LettersOfCredit.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.LCNo == no);
    if (l is null) { l = new LetterOfCredit { OrgId = t.OrgId, LCNo = no }; db.LettersOfCredit.Add(l); }
    l.ContractNo = dto.ContractNo.Trim().ToUpperInvariant(); l.BankName = dto.BankName; l.Amount = dto.Amount;
    l.OpenDate = dto.OpenDate; l.ExpiryDate = dto.ExpiryDate; l.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { l.LCNo, l.ContractNo, l.BankName, l.Amount });
}).RequireAuthorization();

app.MapPost("/api/lcs/{no}/close", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var l = await db.LettersOfCredit.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.LCNo == no);
    if (l is null) return Results.NotFound(new { no });
    if (l.Status != "Open") return Results.BadRequest(new { error = "LC đã tất toán." });
    l.Status = "Closed"; l.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { l.LCNo, status = l.Status });
}).RequireAuthorization();

// ===== Proforma Invoice nhập xe (Pi — port 1:1 FrmNewPI/FrmMngPI, DMSales.Foton) =====
app.MapGet("/api/pis", async (AppDbContext db, ITenantContext t, string? status, string? flagAutoPL) =>
{
    var q = db.Pis.Where(p => p.OrgId == t.OrgId);
    // ⚠️ #B35 — `status` là TỪ VỰNG BỊA của port cũ (`Ord_PerformanceInvoice` không có cột trạng thái).
    //    Giữ tham số để không vỡ lời gọi cũ, nhưng cờ THẬT của nguồn là `FlagAutoPL`.
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(p => p.Status == status);
    if (!string.IsNullOrWhiteSpace(flagAutoPL)) q = q.Where(p => p.FlagAutoPL == flagAutoPL);
    var items = await q.OrderByDescending(p => p.Id).Take(500).Select(p => new
    {
        p.PiNo, p.RefNo, p.ProductionMonth, p.OrderMonth, p.ExpectedMonth, p.Status,
        p.FlagAutoPL, p.CreatedBy, p.CreatedAt,
        lines = db.PiLines.Count(l => l.OrgId == t.OrgId && l.PiId == p.Id),
        totalQty = db.PiLines.Where(l => l.OrgId == t.OrgId && l.PiId == p.Id).Sum(l => (int?)l.Quantity) ?? 0,
        totalAmount = db.PiLines.Where(l => l.OrgId == t.OrgId && l.PiId == p.Id).Sum(l => (decimal?)(l.Quantity * l.UnitPrice)) ?? 0
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// ===== #B35 PORT LẠI 1:1 `OrderPICreate` (`FrmNewPIHMC`, 2010.HTC/Sales) — 8 GAP =====
// Trace LIVE: `FrmNewPIHMC` → `salesSv.InsertPi` (`SalesService.cs:7354`) → WS `OrderPICreate`
//   (`WSHTC.asmx.cs:7366`) → `_biz.OrderPICreate_New20181119` (`Biz.HTC.WH.cs:29473`, **VỎ BỌC**)
//   → **`OrderPICreateX_New20181119`** (`:29242`) — guard và SQL thật ở đây.
//   ⚠️ **5 bản CHẾT** cùng họ trong `Delete.BizHTC.Report.cs` (`:69871`, `:170758`, `:170887`,
//      `:171005`, `:171134`) + bản trong `Biz.HTC.WH.Rel.20230823.cs` (**ngoài `TERP.BizHTC.csproj`**).
// Bảng nguồn: **`Ord_PerformanceInvoice`** / **`Ord_PerformanceInvoiceDetail`**.
// 🔴 GAP 1 — **KHOÁ LÀ `RefNo` DO NGƯỜI DÙNG NHẬP**, guard `Length >= TConst.HTCConst.MinLengthCode` (=5).
//    Port cũ tự sinh `PiNo = "PI"+timestamp` và coi `RefNo` là cột phụ ⇒ mã không tra được ở hệ nguồn.
// 🔴 GAP 2 — **TỪ VỰNG TRẠNG THÁI BỊA**: `Ord_PerformanceInvoice` **không có cột trạng thái**; cờ duy nhất
//    nguồn ghi là `FlagAutoPL = Flag.Active`. Port cũ đẻ `Draft → Confirmed` **và một nút `/confirm`** —
//    đúng loại vi phạm "cấm tự chế nút hoàn tất / đẻ trạng thái ngoài từ vựng nguồn". Nút đã bị **GỠ**.
// 🔴 GAP 3 — **`LCTemp` BẮT BUỘC** (`_InvalidDetailLCTemp`) và nằm trong **khoá dòng 5 thành phần**
//    `|RefNo||LCTemp||SpecCode||ModelCode||ColorCode|`. Port cũ thiếu hẳn cột này.
// 🔴 GAP 4 — **`WorkOrderNo` BẮT BUỘC**, `Length >= 5` (`_InvalidDetailWorkOrderNo`); port cũ để tuỳ chọn.
// 🔴 GAP 5 — **`ModelCode` SUY RA từ `SpecCode`** (`dr["ModelCode"] = dt_Mst_CarSpec.Rows[0]["ModelCode"]`),
//    KHÔNG lấy input; rồi cặp model–màu phải khớp master (`myCommon_CheckMatchingModelAndColor`).
// 🔴 GAP 6 — nguồn chỉ chặn `Quantity < 0` ⇒ **dòng 0 xe HỢP LỆ**; port cũ lọc `> 0` ⇒ vứt âm thầm.
// 🔴 GAP 7 — **ba mốc tháng do CLIENT gửi** (service truyền cả `OrderMonth`/`ProductionMonth`/
//    `ExpectedMonth`, `SalesService.cs:7364-7372`); port cũ tự chế `ExpectedMonth = ProductionMonth + 1`.
// 🔴 GAP 8 — **RBAC** `myCommon_CheckHTCDirect(…, TConst.Flag.Active)` (`:29268`) là **DÒNG ACTIVE**.
// ⚠️ NỢ CÓ NHÃN: nguồn **KHÔNG ghi `UnitPrice`** ở dòng PI (không có trong khối gán). Giữ cột để không mất
//    dữ liệu port cũ, nhưng ghi rõ là **cột ngoài nguồn**. Và `ContractNo` nguồn để `DBNull` lúc tạo.
app.MapPost("/api/pis", async (PiDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user, string? flagDirect) =>
{
    // `myCommon_CheckHTCDirect(Flag.Active)` — dòng ACTIVE.
    if (flagDirect == "0")
        return Results.BadRequest(new { error = "Chỉ người dùng HTC trực tiếp (FlagDirect='1') được tạo PI.", guard = "myCommon_CheckHTCDirect(Flag.Active)" });

    // `OrderPICreate_InvalidPIRefNo` — RefNo do NGƯỜI DÙNG nhập, tối thiểu `HTCConst.MinLengthCode` = 5.
    var refNo = (dto.RefNo ?? "").Trim().ToUpperInvariant();
    if (refNo.Length < 5)
        return Results.BadRequest(new { error = "Số PI (RefNo) phải có ít nhất 5 ký tự.", guard = "OrderPICreate_InvalidPIRefNo" });
    if (await db.Pis.AnyAsync(x => x.OrgId == t.OrgId && x.PiNo == refNo))
        return Results.BadRequest(new { error = $"PI {refNo} đã tồn tại!" });

    // `OrderPICreate_TableDetailBeBlank`
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.SpecCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Chưa có dòng chi tiết nào.", guard = "OrderPICreate_TableDetailBeBlank" });
    if (dto.ProductionMonth is null) return Results.BadRequest(new { error = "Cần ProductionMonth." });

    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";

    var seen = new HashSet<string>();
    var built = new List<PiLine>();
    foreach (var l in lines)
    {
        var spec = l.SpecCode.Trim().ToUpperInvariant();
        var color = (l.ColorCode ?? "").Trim().ToUpperInvariant();
        var lcTemp = (l.LCTemp ?? "").Trim();
        var wo = (l.WorkOrderNo ?? "").Trim();

        // `OrderPICreate_InvalidDetailLCTemp` — `Convert.ToString(dr["LCTemp"]).Trim().Length < 1`.
        if (lcTemp.Length < 1)
            return Results.BadRequest(new { error = $"Spec {spec}: thiếu LC tạm (LCTemp).", guard = "OrderPICreate_InvalidDetailLCTemp" });
        // `OrderPICreate_InvalidDetailQuantity` — chặn ÂM, **0 hợp lệ**.
        if (l.Quantity < 0)
            return Results.BadRequest(new { error = $"Spec {spec}: số lượng không hợp lệ.", guard = "OrderPICreate_InvalidDetailQuantity" });
        // `OrderPICreate_InvalidDetailWorkOrderNo` — bắt buộc, tối thiểu 5 ký tự.
        if (wo.Length < 5)
            return Results.BadRequest(new { error = $"Spec {spec}: số lệnh sản xuất (WorkOrderNo) phải có ít nhất 5 ký tự.", guard = "OrderPICreate_InvalidDetailWorkOrderNo" });

        // `myCommon_CheckSpecCode(…, Flag.Active)` rồi **SUY RA** ModelCode từ spec.
        var sp = await db.CarSpecs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SpecCode == spec && x.FlagActive == "1");
        if (sp is null) return Results.BadRequest(new { error = $"Spec {spec} không tồn tại hoặc đã ngừng hoạt động." });
        var model = sp.ModelCode;   // KHÔNG lấy từ input

        // `myCommon_CheckMatchingModelAndColor`
        if (color.Length > 0)
        {
            var okColor = await db.MstCarColors.AnyAsync(x => x.OrgId == t.OrgId && x.ModelCode == model && x.ColorCode == color && x.FlagActive == "1");
            if (!okColor) return Results.BadRequest(new { error = $"Màu {color} không thuộc model {model}.", specCode = spec });
        }

        // `OrderPICreate_DuplicateKeyDetail` — khoá NĂM thành phần, có `LCTemp`.
        var key = $"|{refNo}||{lcTemp}||{spec}||{model}||{color}|";
        if (!seen.Add(key))
            return Results.BadRequest(new { error = $"Dòng trùng khoá (LCTemp/Spec/Model/Màu): {lcTemp}/{spec}/{model}/{color}.", key });

        built.Add(new PiLine
        {
            OrgId = t.OrgId, LCTemp = lcTemp, SpecCode = spec, ModelCode = model, ColorCode = color,
            WorkOrderNo = wo, PortCode = l.PortCode, PlantCode = l.PlantCode,
            Quantity = l.Quantity, UnitPrice = l.UnitPrice,
            ContractNo = null   // nguồn gán DBNull lúc tạo
        });
    }

    var p = new Pi
    {
        OrgId = t.OrgId,
        PiNo = refNo, RefNo = refNo,          // khoá của nguồn CHÍNH LÀ RefNo
        OrderMonth = dto.OrderMonth,
        ProductionMonth = dto.ProductionMonth.Value,
        ExpectedMonth = dto.ExpectedMonth ?? dto.ProductionMonth.Value,   // client gửi; không tự chế +1
        FlagAutoPL = "1",                     // `Flag.Active` — cờ DUY NHẤT của đầu PI
        CreatedAt = now, CreatedBy = who
    };
    db.Pis.Add(p); await db.SaveChangesAsync();
    foreach (var b in built) { b.PiId = p.Id; db.PiLines.Add(b); }
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        refNo = p.PiNo, p.OrderMonth, p.ProductionMonth, p.ExpectedMonth, p.FlagAutoPL, p.CreatedBy,
        lines = built.Count, totalQty = built.Sum(l => l.Quantity),
        rowKey = "|RefNo||LCTemp||SpecCode||ModelCode||ColorCode| — khoá NĂM thành phần của nguồn",
        noStatusNote = "Ord_PerformanceInvoice KHÔNG có cột trạng thái; luồng tạo không ghi Status và lệnh /confirm đã bị gỡ.",
        debt = "NỢ: UnitPrice là cột NGOÀI nguồn (nguồn không ghi đơn giá ở dòng PI); ContractNo để NULL, điền khi gắn hợp đồng ngoại."
    });
}).RequireAuthorization();
app.MapGet("/api/pis/{no}/lines", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var p = await db.Pis.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PiNo == no);
    if (p is null) return Results.NotFound(new { no });
    var lines = await db.PiLines.Where(l => l.OrgId == t.OrgId && l.PiId == p.Id)
        // #B35 — `LCTemp` (thành phần khoá dòng) + `ContractNo` phải ĐỌC RA ĐƯỢC, không chỉ ghi vào.
        .Select(l => new { l.LCTemp, l.SpecCode, l.ModelCode, l.ColorCode, l.PortCode, l.PlantCode, l.WorkOrderNo, l.ContractNo, l.Quantity, l.UnitPrice, lineTotal = l.Quantity * l.UnitPrice }).ToListAsync();
    return Results.Ok(new { p.PiNo, p.RefNo, p.FlagAutoPL, p.CreatedBy, p.Status, count = lines.Count, lines, totalQty = lines.Sum(x => x.Quantity), totalAmount = lines.Sum(x => x.lineTotal) });
}).RequireAuthorization();

// #B35 GO endpoint BIA: POST /api/pis/{no}/confirm (Draft->Confirmed).
// Bang nguon Ord_PerformanceInvoice KHONG co cot trang thai; khong co lenh "xac nhan PI" o nguon.
// ===== #B76 LƯU NHIỀU DÒNG PI — `OrderPIDetailSaveMulti_New20181119` =====
// Trace LIVE: WS → **`_biz.OrderPIDetailSaveMulti_New20181119`** (`Biz.HTC.WH.cs:29847`).
//   3B đo thật, **khớp cả 2 máy**: start=29847 md5 `dcb41693c28d5ca9bac96a52c9bbde91`.
// 🔴 **PORT CŨ SAI HẲN MÔ HÌNH**: bản cũ **xoá sạch rồi chèn lại** toàn bộ dòng. Nguồn là
//    **upsert TỪNG DÒNG** theo cờ `FlagDelete` của chính dòng đó — ba nhánh Xoá / Sửa / Thêm.
//    Hệ quả của bản cũ: `ContractNo` (chỉ nguồn mới biết cách gán) **bị thổi bay** mỗi lần lưu.
// 🔴 **KHI SỬA, NGUỒN CHỈ GHI ĐÚNG MỘT CỘT**: `alColumnEffective` của nhánh Update chỉ có
//    **`"Quantity"`** (`:30049`). `WorkOrderNo`/`ContractNo` được **ĐỌC NGƯỢC ra từ dòng đang có**
//    (`:30047-30048`), **không** lấy từ đầu vào. ⇒ Sửa `PortCode`/`PlantCode`/`WorkOrderNo` qua màn
//    này **không có tác dụng** — đó là hành vi THẬT. Port ghi đúng một cột `Quantity`.
// 🔴 **Kiểm tra bất đối xứng theo cờ xoá**:
//      `LCTemp` rỗng ⇒ ném `OrderPIDetailSave_InvalidLCTemp` — **kiểm LUÔN LUÔN**, kể cả khi xoá.
//      `WorkOrderNo.Length < TConst.HTCConst.MinLengthCode` (**= 5**) và `Quantity < 0`
//        ⇒ chỉ kiểm **khi KHÔNG xoá** (`if (!bFlagDelete)`).
//    ⚠️ Điều kiện là `Quantity < 0`, **không phải `<= 0`** ⇒ **dòng số lượng 0 là HỢP LỆ**.
//      (Port cũ chặn `Quantity <= 0` — chặt hơn nguồn, sai.)
// 🔴 **Nhánh Xoá**: chặn nếu `Rows[0]["ContractNo"] != DBNull.Value` ⇒
//    `OrderPIDetailSave_CannotDelRefToContract`. Lưu ý phép so là **`!= DBNull.Value`** nên
//    **chuỗi RỖNG vẫn xoá được** — không phải `string.IsNullOrWhiteSpace`.
// 🔴 **Nhánh Thêm — `ContractNo` KHÔNG lấy từ đầu vào mà KẾ THỪA từ dòng anh em cùng `(RefNo, LCTemp)`**:
//      `select top 1 t.ContractNo from Ord_PerformanceInvoiceDetail where RefNo=@RefNo and LCTemp=@LCTemp`
//    ⇒ `ContractNo` thực chất là thuộc tính của **nhóm LC tạm**, không phải của dòng.
//    ⚠️ `top 1` **KHÔNG có `order by`** ⇒ nếu nhóm có nhiều `ContractNo` khác nhau thì kết quả
//      **không tất định**. Port lấy dòng đầu và ghi rõ khác biệt này.
//    Dòng mới luôn khởi tạo `ContractNo = DBNull` trước, rồi mới kế thừa nếu tìm thấy.
// 🔴 **Nhánh Thêm còn hai kiểm chéo danh mục**: `Mst_CarSpec.ModelCode` phải **trùng** `ModelCode` đầu vào
//    (`OrderPIDetailSave_InvalidModelCode`) và `myCommon_CheckMatchingModelAndColor(Model, Color)`.
// 🔴 **Đầu PI (`FlagAutoPL`) chỉ ghi KHI GIÁ TRỊ THAY ĐỔI** (`if (!…Equals(strFlagAutoPL))`, `:30140`)
//    — ghi có canh, không phải ghi vô điều kiện.
// 🔴 **BỐN hậu kiểm sau khi lưu** (`:30154-30176`), chạy **sau** `SaveData`, trong cùng transaction:
//      `WO_WorkOrder_DelSmart_New20181119` ← **cùng guard PHẠM VI TOÀN CỤC của #B75**: một VIN mồ côi
//        WO **ở bất kỳ đâu** trong hệ thống cũng làm **hỏng cả lệnh LƯU này**, không riêng lệnh xoá.
//      `OrderPICheck_01` · `OrderPICheck_QtyPLOverPIByWorkOrder("RefNo", …)`
//      · `OrderPICheck_QtyPLOverPIByContractOversea("RefNo", …)`.
// 🔴 Nguồn ghi **cả `_dbMain` và `_dbWH`** (`SaveData` hai lần), không phải 2-phase commit (như #B75).
// ⚠️ Kiểm "bảng chi tiết rỗng" (`OrderPIDetailSaveMulti_TableDetailBeBlank`) **ĐÃ BỊ COMMENT**
//    (`:29920-29928`) ⇒ nguồn **CHẤP NHẬN danh sách rỗng** (không làm gì). Port cũ bắt buộc ≥1 dòng —
//    chặt hơn nguồn. Port theo dòng ACTIVE: rỗng ⇒ trả về không lỗi.
// ✅ RBAC: `myCommon_CheckHTCDirect(…, TConst.Flag.Active)`; `myOrder_CheckPI(…, Flag.Active, …)`.
// 📌 NỢ: `WO_WorkOrder_AddSmart_New20181119` (tự tạo WO khi thêm dòng) và ba hàm `OrderPICheck_*`
//    cần bảng `WO_WorkOrder` / `CT_PackingList` ở mức chưa có ⇒ **không dựng**, cờ
//    `postChecksSkipped` liệt kê đúng tên bốn hậu kiểm. Không bịa.
app.MapPost("/api/pis/{no}/detail", async (string no, List<PiLineDto> lines, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    // `myOrder_CheckPI(…, Flag.Active, …)` — PI phải tồn tại. (Nguồn KHÔNG gác theo trạng thái:
    //  bảng `Ord_PerformanceInvoice` không có cột trạng thái nào — xem #B35.)
    var p = await db.Pis.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PiNo == no);
    if (p is null) return Results.NotFound(new { no, error = "OrderPIDetailSaveMulti_PINotExist" });

    var rows = lines ?? new();
    // Kiểm "bảng rỗng" đã BỊ COMMENT ở nguồn ⇒ chấp nhận danh sách rỗng.
    if (rows.Count == 0)
        return Results.Ok(new { p.PiNo, inserted = 0, updated = 0, deleted = 0, emptyInputAccepted = true });

    var existing = await db.PiLines.Where(l => l.OrgId == t.OrgId && l.PiId == p.Id).ToListAsync();
    var specs = await db.CarSpecs.Where(s => s.OrgId == t.OrgId)
        .Select(s => new { s.SpecCode, s.ModelCode }).ToListAsync();
    var colors = await db.MstCarColors.Where(c => c.OrgId == t.OrgId)
        .Select(c => new { c.ModelCode, c.ColorCode }).ToListAsync();

    int nIns = 0, nUpd = 0, nDel = 0;
    var inheritedContract = new List<object>();

    foreach (var d in rows)
    {
        var flagDelete = (d.FlagDelete ?? "").Trim() == "1";
        var lcTemp = (d.LCTemp ?? "").Trim();
        // `LCTemp` kiểm LUÔN LUÔN — kể cả khi xoá.
        if (lcTemp.Length < 1)
            return Results.BadRequest(new { error = "OrderPIDetailSave_InvalidLCTemp", check = new { LCTemp = lcTemp } });

        var specCode = (d.SpecCode ?? "").Trim();
        var modelCode = (d.ModelCode ?? "").Trim();
        var colorCode = (d.ColorCode ?? "").Trim();
        var workOrderNo = (d.WorkOrderNo ?? "").Trim();

        if (!flagDelete)
        {
            // `TConst.HTCConst.MinLengthCode` = 5.
            if (workOrderNo.Length < 5)
                return Results.BadRequest(new { error = "OrderPIDetailSave_InvalidWorkOrderNo", check = new { WorkOrderNo = workOrderNo } });
            // 🔴 `< 0`, KHÔNG phải `<= 0` — dòng số lượng 0 là HỢP LỆ.
            if (d.Quantity < 0)
                return Results.BadRequest(new { error = "OrderPIDetailSave_InvalidQuantity", check = new { d.Quantity } });
        }

        // `myOrder_CheckPIDetail` — khoá dòng 5 phần: RefNo|LCTemp|SpecCode|ModelCode|ColorCode.
        var cur = existing.FirstOrDefault(l =>
            (l.LCTemp ?? "") == lcTemp && l.SpecCode == specCode
            && (l.ModelCode ?? "") == modelCode && (l.ColorCode ?? "") == colorCode);

        if (flagDelete)
        {
            if (cur is null) continue;
            // 🔴 `!= DBNull.Value` — chuỗi RỖNG vẫn xoá được.
            if (cur.ContractNo is not null)
                return Results.BadRequest(new
                {
                    error = "OrderPIDetailSave_CannotDelRefToContract",
                    check = new { cur.ContractNo, cur.LCTemp, cur.SpecCode, cur.ModelCode, cur.ColorCode }
                });
            db.PiLines.Remove(cur); existing.Remove(cur); nDel++;
            continue;
        }

        if (cur is not null)
        {
            // 🔴 alColumnEffective = { "Quantity" } — CHỈ ghi số lượng. Các cột khác giữ nguyên.
            cur.Quantity = d.Quantity; nUpd++;
            continue;
        }

        // ---- Nhánh Thêm: hai kiểm chéo danh mục.
        var sp = specs.FirstOrDefault(s => s.SpecCode == specCode);
        if (sp is null)
            return Results.BadRequest(new { error = "Common_InvalidSpecCode", check = new { SpecCode = specCode } });
        if (!string.Equals(sp.ModelCode ?? "", modelCode, StringComparison.OrdinalIgnoreCase))
            return Results.BadRequest(new
            {
                error = "OrderPIDetailSave_InvalidModelCode",
                check = new { SpecCode = specCode, ModelCodeOfSpec = sp.ModelCode, ModelCodeInput = modelCode }
            });
        if (!colors.Any(c => c.ModelCode == modelCode && c.ColorCode == colorCode))
            return Results.BadRequest(new
            {
                error = "Common_InvalidMatchingModelAndColor",
                check = new { ModelCode = modelCode, ColorCode = colorCode }
            });

        // 🔴 `ContractNo` KHÔNG lấy từ đầu vào: khởi tạo NULL rồi KẾ THỪA từ dòng anh em cùng (RefNo, LCTemp).
        string? contractNo = null;
        var sibling = existing.FirstOrDefault(l => (l.LCTemp ?? "") == lcTemp && l.ContractNo != null);
        if (sibling is not null) { contractNo = sibling.ContractNo; inheritedContract.Add(new { lcTemp, contractNo }); }

        var row = new PiLine
        {
            OrgId = t.OrgId, PiId = p.Id, LCTemp = lcTemp, SpecCode = specCode,
            ModelCode = modelCode, ColorCode = colorCode,
            PortCode = d.PortCode, PlantCode = d.PlantCode, WorkOrderNo = workOrderNo,
            Quantity = d.Quantity, UnitPrice = d.UnitPrice, ContractNo = contractNo
        };
        db.PiLines.Add(row); existing.Add(row); nIns++;
    }

    // Đầu PI: `FlagAutoPL` chỉ ghi KHI THAY ĐỔI.
    var flagAutoPlChanged = false;
    var flagAutoPlIn = (rows.FirstOrDefault()?.FlagAutoPL ?? "").Trim();
    if (flagAutoPlIn.Length > 0 && p.FlagAutoPL != flagAutoPlIn) { p.FlagAutoPL = flagAutoPlIn; flagAutoPlChanged = true; }

    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        p.PiNo, p.RefNo,
        inserted = nIns, updated = nUpd, deleted = nDel,
        flagAutoPlChanged,
        inheritedContract,
        modelNote = "Nguon la UPSERT TUNG DONG theo co FlagDelete cua chinh dong do (Xoa/Sua/Them), KHONG phai xoa-sach-chen-lai nhu port cu. Port cu lam ContractNo bi thoi bay moi lan luu.",
        updateOnlyQuantityNote = "alColumnEffective cua nhanh Update CHI CO 'Quantity'. WorkOrderNo/ContractNo duoc DOC NGUOC ra tu dong dang co, KHONG lay tu dau vao => sua PortCode/PlantCode/WorkOrderNo qua man nay KHONG CO TAC DUNG. Day la hanh vi THAT cua nguon.",
        validationAsymmetryNote = "LCTemp rong => InvalidLCTemp, kiem LUON LUON ke ca khi xoa. WorkOrderNo (min 5 = TConst.HTCConst.MinLengthCode) va Quantity chi kiem KHI KHONG XOA. Dieu kien la 'Quantity < 0' KHONG phai '<= 0' => dong so luong 0 la HOP LE (port cu chan <= 0, chat hon nguon).",
        deleteGuardNote = "Chan xoa neu Rows[0]['ContractNo'] != DBNull.Value => CannotDelRefToContract. Phep so la '!= DBNull.Value' nen CHUOI RONG VAN XOA DUOC, khong phai IsNullOrWhiteSpace.",
        contractInheritNote = "Nhanh Them: ContractNo KHONG lay tu dau vao ma KE THUA tu dong anh em cung (RefNo, LCTemp) qua 'select top 1 t.ContractNo ... where RefNo=@RefNo and LCTemp=@LCTemp'. => ContractNo la thuoc tinh cua NHOM LC TAM, khong phai cua dong. CANH BAO: 'top 1' KHONG CO order by => neu nhom co nhieu ContractNo khac nhau thi ket qua KHONG TAT DINH.",
        emptyInputNote = "Kiem 'bang chi tiet rong' (OrderPIDetailSaveMulti_TableDetailBeBlank) DA BI COMMENT (:29920-29928) => nguon CHAP NHAN danh sach rong. Port cu bat buoc >=1 dong - chat hon nguon.",
        twoDbNote = "Nguon goi SaveData HAI LAN (_dbMain va _dbWH), khong phai 2-phase commit - cung khuon #B75.",
        postChecksSkipped = new[] { "WO_WorkOrder_DelSmart_New20181119", "OrderPICheck_01", "OrderPICheck_QtyPLOverPIByWorkOrder", "OrderPICheck_QtyPLOverPIByContractOversea" },
        postChecksDebt = "NO: bon hau kiem chay SAU SaveData trong cung transaction. Dac biet WO_WorkOrder_DelSmart mang GUARD PHAM VI TOAN CUC cua #B75 - mot VIN mo coi WO o BAT KY DAU cung lam HONG CA LENH LUU nay, khong rieng lenh xoa. Chua dung duoc vi thieu bang WO_WorkOrder / CT_PackingList o muc can. Khong bia.",
        rbacNote = "myCommon_CheckHTCDirect(..., TConst.Flag.Active) + myOrder_CheckPI(..., Flag.Active)."
    });
}).RequireAuthorization();

// ===== #B75 XOÁ PI (Performance Invoice) — `OrderPIDelete_New20181119` =====
// Trace LIVE: WS `OrderPIDelete` (`WSHTC.asmx.cs:7438`) → **`_biz.OrderPIDelete_New20181119`**
//   (`Biz.HTC.WH.cs:29601`), kèm hàm con **`WO_WorkOrder_DelSmart_New20181119`** (`:29790`).
//   ⚠️ Ba file khác cũng chứa tên này đều là RÁC: `BK.WSHTC/WSHTC.asmx.20210208.cs`,
//     `WSHTC.asmx - Copy.cs`, `Web References/…/Reference.cs` (proxy sinh tự động). Đã bỏ qua.
//   3B đo thật, **khớp cả 2 máy**: `OrderPIDelete_New20181119` start=29601 md5
//   `cb0c3efae8634aa4c66ed7c4dc8b2281` · `WO_WorkOrder_DelSmart_New20181119` start=29790 md5
//   `03ba60852eb47f10a774b1510081bc27`.
// 🔴 **KHOÁ LÀ `RefNo`, KHÔNG PHẢI `PiNo`** — mọi mệnh đề của nguồn (`opid.RefNo = @RefNo`,
//    `delete … where t.RefNo = @RefNo`) đều theo `RefNo`. Endpoint này vì thế nhận `refNo`.
// 🔴 **GHI VÀO HAI CƠ SỞ DỮ LIỆU**: cùng một câu delete chạy trên **`_dbMain` VÀ `_dbWH`**, mỗi bên một
//    transaction riêng (`bNeedTransaction` / `bNeedTransaction_WH`), rồi `CommitSafety` **lần lượt**.
//    ⚠️ Đây **KHÔNG phải 2-phase commit**: nếu `_dbWH` hỏng **sau khi** `_dbMain` đã commit thì hai DB
//    **lệch vĩnh viễn**. MiniHTC chỉ có một DB nên port ghi một lần — ghi nhận khác biệt, không mô phỏng.
// 🔴 **GUARD 1 — từ chối xoá nếu PI đã gắn HỢP ĐỒNG NGOẠI**: `select top 1 … where opid.RefNo = @RefNo
//    and opid.ContractNo is not null` ⇒ ném `OrderPIDelete_ExistRefToContract`, kèm **6 tham số chẩn
//    đoán** (`RefNo, LCTemp, SpecCode, ModelCode, ColorCode, ContractNo`) lấy từ **`Rows[0]`**.
// 🔴 **GUARD 2 — `WO_WorkOrder_DelSmart`: PHẠM VI TOÀN CỤC, KHÔNG giới hạn theo PI đang xoá.**
//    Câu kiểm là `select t.* from Car_VIN t left join Ord_PerformanceInvoiceDetail opid
//    on t.WorkOrderNo = opid.WorkOrderNo where opid.RefNo is null` — **không có `@RefNo`**, không có
//    mệnh đề nào buộc về PI vừa xoá. ⇒ **Xoá BẤT KỲ PI nào cũng thất bại nếu TRONG TOÀN HỆ THỐNG còn
//    một VIN trỏ tới WO không còn dòng PI nào**, kể cả VIN chẳng liên quan gì tới PI này.
//    Lỗi: `WO_WorkOrder_DelSmart_PIBlankButVINExist`. Đây là hành vi THẬT của nguồn, port giữ nguyên
//    và trả `orphanVinScope = "GLOBAL"` để người dùng hiểu vì sao bị chặn.
// 🔴 **DÒNG ACTIVE vs DÒNG COMMENT — lệch Main/WH CÓ THẬT**: lệnh dọn `WO_WorkOrder` chỉ chạy trên
//    `_dbWH`; lời gọi `_dbMain.ExecQuery(strSqlSave)` **bị comment** (`:29838-29840`).
//    ⇒ `WO_WorkOrder` bên **DB Main giữ lại dòng mồ côi vĩnh viễn**. Port theo dòng ACTIVE (chỉ WH).
// 🔴 Thứ tự xoá: **DÒNG trước, ĐẦU sau** (`Ord_PerformanceInvoiceDetail` → `Ord_PerformanceInvoice`).
// ✅ RBAC: `myCommon_CheckHTCDirect(…, TConst.Flag.Active)` — **bắt buộc FlagDirect**.
// ✅ `myOrder_CheckPI(…, TConst.Flag.Active, …)` — PI **phải tồn tại** trước khi xoá.
// 📌 NỢ: bảng `WO_WorkOrder` chưa có trong MiniHTC ⇒ **GUARD 2 port được** (chỉ cần `Car_VIN.WorkOrderNo`
//    — đã thêm ở #B74 — và `PiLine.WorkOrderNo`), nhưng **lệnh DỌN `WO_WorkOrder` thì không**;
//    cờ `woWorkOrderCleanupSkipped` báo rõ, không bịa.
app.MapDelete("/api/pis/by-ref/{refNo}", async (string refNo, AppDbContext db, ITenantContext t) =>
{
    refNo = refNo.Trim().ToUpperInvariant();

    // `myOrder_CheckPI(…, Flag.Active, …)` — PI phải tồn tại.
    var heads = await db.Pis.Where(p => p.OrgId == t.OrgId && p.RefNo != null
                                        && p.RefNo.ToUpper() == refNo).ToListAsync();
    if (heads.Count == 0) return Results.NotFound(new { refNo, error = "OrderPIDelete_PINotExist" });
    var headIds = heads.Select(h => h.Id).ToHashSet();
    var lines = await db.PiLines.Where(l => l.OrgId == t.OrgId && headIds.Contains(l.PiId)).ToListAsync();

    // ---- GUARD 1: có dòng nào đã gắn hợp đồng ngoại ⇒ TỪ CHỐI.
    var hit = lines.FirstOrDefault(l => !string.IsNullOrWhiteSpace(l.ContractNo));   // `Rows[0]` của nguồn
    if (hit is not null)
        return Results.BadRequest(new
        {
            error = "OrderPIDelete_ExistRefToContract",
            check = new
            {
                RefNo = refNo, hit.LCTemp, hit.SpecCode, hit.ModelCode, hit.ColorCode, hit.ContractNo
            },
            note = "Nguon tu choi xoa PI khi con dong tro toi HOP DONG NGOAI (opid.ContractNo is not null), kem 6 tham so chan doan lay tu Rows[0]."
        });

    // ---- GUARD 2: VIN mồ côi WO — PHẠM VI TOÀN CỤC (nguồn KHÔNG lọc theo @RefNo).
    var woWithPi = (await db.PiLines.Where(l => l.OrgId == t.OrgId && l.WorkOrderNo != null)
        .Select(l => l.WorkOrderNo!).ToListAsync()).ToHashSet();
    var orphanVin = await db.CarVinMasters
        .Where(c => c.OrgId == t.OrgId && c.WorkOrderNo != null)
        .Select(c => new { c.VIN, c.WorkOrderNo }).ToListAsync();
    var orphan = orphanVin.FirstOrDefault(v => !woWithPi.Contains(v.WorkOrderNo!));
    if (orphan is not null)
        return Results.BadRequest(new
        {
            error = "WO_WorkOrder_DelSmart_PIBlankButVINExist",
            check = new { orphan.WorkOrderNo, orphan.VIN },
            orphanVinScope = "GLOBAL",
            note = "Cau kiem cua nguon KHONG co @RefNo: 'select t.* from Car_VIN t left join Ord_PerformanceInvoiceDetail opid on t.WorkOrderNo = opid.WorkOrderNo where opid.RefNo is null'. => xoa BAT KY PI nao cung that bai neu TRONG TOAN HE THONG con mot VIN tro toi WO khong con dong PI nao, ke ca VIN chang lien quan gi toi PI nay. Day la hanh vi THAT cua nguon."
        });

    // ---- Xoá: DÒNG trước, ĐẦU sau.
    db.PiLines.RemoveRange(lines);
    db.Pis.RemoveRange(heads);
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        refNo,
        deletedHeads = heads.Count,
        deletedLines = lines.Count,
        keyNote = "KHOA LA RefNo, KHONG PHAI PiNo - moi menh de cua nguon deu theo RefNo.",
        deleteOrderNote = "Xoa DONG truoc (Ord_PerformanceInvoiceDetail), DAU sau (Ord_PerformanceInvoice), trong cung mot batch.",
        twoDbNote = "Nguon chay CUNG cau delete tren CA _dbMain VA _dbWH, moi ben mot transaction rieng roi CommitSafety LAN LUOT - KHONG phai 2-phase commit: neu _dbWH hong SAU KHI _dbMain da commit thi hai DB lech vinh vien. MiniHTC chi co mot DB nen ghi mot lan.",
        activeVsCommentNote = "Lenh don WO_WorkOrder chi chay tren _dbWH; loi goi _dbMain.ExecQuery(strSqlSave) BI COMMENT (Biz.HTC.WH.cs:29838-29840) => WO_WorkOrder ben DB Main giu lai dong mo coi VINH VIEN. Port theo dong ACTIVE.",
        woWorkOrderCleanupSkipped = true,
        woDebt = "NO: bang WO_WorkOrder chua co trong MiniHTC => GUARD 2 port duoc (chi can Car_VIN.WorkOrderNo - them o #B74 - va PiLine.WorkOrderNo) nhung LENH DON WO_WorkOrder thi khong. Khong bia.",
        rbacNote = "Nguon goi myCommon_CheckHTCDirect(..., TConst.Flag.Active) - BAT BUOC FlagDirect."
    });
}).RequireAuthorization();

// ===== #B79 DỰNG NỘI DUNG UỶ NHIỆM CHI (UNC) — `Pmt_Payment_GetUNCContent_New20221111` =====
// Trace LIVE: WS `Pmt_Payment_GetUNCContent` (`WSHTC.asmx.cs:11049`) →
//   **`_biz.Pmt_Payment_GetUNCContent_New20221111`** (`DataWH/Biz.HTC.WH.My.cs:26601`).
// 🔴 **BẪY SINH ĐÔI — đã TRACE**: cùng file còn `Pmt_Payment_GetUNCContent_New20200327` (`:25895`).
//    WS **chỉ gọi bản `_New20221111`** ⇒ bản 2020 **CHẾT**. Không đoán theo tên/hậu tố lớn hơn.
//   3B đo thật, **khớp cả 2 máy**: start=26601 md5 `5bf8e8859096fbbccf1bbf28d00d0c81`.
// 🔴 **Đầu vào là BẢNG `Input_CarId`**, không phải danh sách phẳng: thiếu bảng ⇒ ném
//    `Pmt_Payment_GetUNCContent_InputVinTblNotFound`.
// ⚠️ **LỖI MÃ LỖI TRONG NGUỒN (ghi nhận, KHÔNG tự sửa)**: `if (String.IsNullOrEmpty(strDealerCode))`
//    ném **`…_InvalidPaymentType`** (`:26684`) — đáng lẽ phải là mã lỗi của mã đại lý. Hơn nữa phép
//    kiểm này đứng **SAU** `myCommon_CheckDealer(strDealerCode, …)` vốn đã ném khi rỗng ⇒ nhánh này
//    **không bao giờ chạy tới**. Port giữ đúng thứ tự và mã của nguồn, ghi rõ ở `sourceQuirks`.
// 🔴 **NHÁNH `TTC` — dựng mã đơn nhiều tầng, KHÔNG phải nối chuỗi đơn giản**:
//    Chuỗi join: `Input_CarId → Car_Car.SOCode → Ord_SalesOrder.SOCode`, rồi
//    `Ord_SalesOrder.SORCode → DMS40_Ord_SalesOrderRoot.SORCode`.
//    Với **mỗi `SORCode`**: lấy phần **trước dấu `.` ĐẦU TIÊN** làm gốc, rồi lọc lại các `SOCode`
//    bằng **`like '<gốc>%'`** (⚠️ `SOCode` **mang `SORCode` làm TIỀN TỐ**), lấy phần **sau dấu `.`**
//    của từng `SOCode` và nối:
//      · phần tử **ĐẦU TIÊN** nối bằng **`.`**  → `GOC.suffix1`
//      · các phần tử **SAU** nối bằng **`-`**   → `GOC.suffix1-suffix2-…`
//    Nhiều `SORCode` thì nối tiếp bằng **`-`**.
//    ⚠️ **Bộ lọc ký tự**: chỉ nhận `suffix` mà **KÝ TỰ ĐẦU là chữ số 0-9** (nguồn viết hẳn 10 phép
//      `StringEqualIgnoreCase` liệt kê "0".."9"); suffix bắt đầu bằng chữ **bị BỎ IM LẶNG**.
//    Không có `SORCode` nào ⇒ ném `…_SOCodeNotFound`.
//    Kết quả: **`DealerCode-PaymentType-PaymentNo-<multiSOCode>`**, `.Trim()`.
// 🔴 **NHÁNH `TTBL` — rẽ theo `Mst_Dealer.FlagTCG`** (`:26940` / `:27005`):
//    · `FlagTCG = '1'` ⇒ nối **6 KÝ TỰ CUỐI của VIN** (`Right(cv.VIN, 6)`), ngăn bằng `-`.
//    · `FlagTCG = '0'` ⇒ nối theo **`BankGuaranteeNo`** của bảo lãnh, kèm danh sách VIN mỗi bảo lãnh
//      (`'-' + BankGuaranteeNo + '-' + MultiVIN`), và **lọc `BankGuaranteeNo is not null`**.
//    Không tìm được bảo lãnh ⇒ ném `…_GuaranteeNoNotFound`.
//    ⚠️ Nguồn nối chuỗi bằng `STUFF(( … FOR XML PATH('') ), 1, 1, '')` — kỹ thuật SQL Server thuần;
//      port dùng `string.Join`, **thứ tự do `order by` của nguồn quyết định** (nguồn KHÔNG có
//      `order by` ⇒ thứ tự **không tất định**; port sắp theo VIN/số bảo lãnh để tái lập được).
// ✅ RBAC/validate: `myCommon_CheckDealer(…, Active, Active, …)` (đại lý phải tồn tại **và** đang hoạt
//    động) và `myCar_CheckCar(…, Active, Active, …)` cho **TỪNG** `CarId` trong bảng đầu vào.
// 📌 §12: `SalesOrder.SORCode` (entity + Seeder + DTO + POST + GET) — không có thì nhánh `TTC` không dựng được.
app.MapPost("/api/payments/unc-content", async (
    UncContentDto dto, AppDbContext db, ITenantContext t) =>
{
    var dealerCode = (dto.DealerCode ?? "").Trim().ToUpperInvariant();
    var paymentType = (dto.PaymentType ?? "").Trim().ToUpperInvariant();
    var paymentNo = (dto.PaymentNo ?? "").Trim();
    var carIds = (dto.CarIds ?? new()).Select(x => (x ?? "").Trim()).Where(x => x.Length > 0).ToList();

    // Thứ tự kiểm ĐÚNG như nguồn: đại lý trước (tồn tại + đang hoạt động).
    var dealer = await db.Dealers.FirstOrDefaultAsync(d => d.OrgId == t.OrgId
                    && d.DealerCode != null && d.DealerCode.ToUpper() == dealerCode);
    if (dealer is null || dealer.FlagActive != "1")
        return Results.BadRequest(new { error = "Common_InvalidDealerCode", check = new { DealerCode = dealerCode } });
    // ⚠️ Nhánh của nguồn dùng SAI mã lỗi và không bao giờ chạy tới — giữ nguyên để đối chiếu.
    if (dealerCode.Length < 1)
        return Results.BadRequest(new { error = "Pmt_Payment_GetUNCContent_InvalidPaymentType" });
    if (paymentType.Length < 1)
        return Results.BadRequest(new { error = "Pmt_Payment_GetUNCContent_InvalidPaymentType" });
    if (paymentNo.Length < 1)
        return Results.BadRequest(new { error = "Pmt_Payment_GetUNCContent_InvalidPaymentNo" });
    if (dto.CarIds is null)
        return Results.BadRequest(new { error = "Pmt_Payment_GetUNCContent_InputVinTblNotFound" });

    // `myCar_CheckCar(…, Active, Active, …)` cho TỪNG CarId.
    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && carIds.Contains(c.VIN)).ToListAsync();
    var missing = carIds.Where(id => !cars.Any(c => c.VIN == id)).ToList();
    if (missing.Count > 0)
        return Results.BadRequest(new { error = "Common_InvalidCarId", check = new { CarId = missing[0] }, missing });
    var inactive = cars.Where(c => c.FlagActive != "1").Select(c => c.VIN).ToList();
    if (inactive.Count > 0)
        return Results.BadRequest(new { error = "Common_InvalidCarIdNotActive", check = new { CarId = inactive[0] }, inactive });

    string result;
    var skippedSuffixes = new List<string>();

    if (paymentType == "TTC")
    {
        // `Car_Car.SOCode → Ord_SalesOrder.SOCode`, rồi `SORCode → DMS40_Ord_SalesOrderRoot.SORCode`.
        var soCodes = cars.Select(c => c.SOCode).Where(x => x != null).Distinct().ToList();
        var sos = await db.SalesOrders.Where(o => o.OrgId == t.OrgId && soCodes.Contains(o.SoCode))
            .Select(o => new { o.SoCode, o.SORCode }).ToListAsync();
        var roots = (await db.Dms40SoRoots.Where(r => r.OrgId == t.OrgId).Select(r => r.SORCode).ToListAsync()).ToHashSet();
        // `inner join DMS40_Ord_SalesOrderRoot` — đơn không có gốc bị LOẠI.
        var pairs = sos.Where(o => o.SORCode != null && roots.Contains(o.SORCode))
            .Select(o => new { o.SoCode, SORCode = o.SORCode! }).Distinct().ToList();

        var sorList = pairs.Select(p => p.SORCode).Distinct().OrderBy(x => x, StringComparer.Ordinal).ToList();
        if (sorList.Count == 0)
            return Results.BadRequest(new { error = "Pmt_Payment_GetUNCContent_SOCodeNotFound" });

        string? multi = null;
        foreach (var sor in sorList)
        {
            // Gốc = phần TRƯỚC dấu '.' ĐẦU TIÊN.
            var rootCode = sor.Split('.')[0];
            var built = rootCode.Trim();
            // Lọc lại SOCode bằng `like '<gốc>%'` — SOCode MANG SORCode làm TIỀN TỐ.
            var mine = pairs.Where(p => p.SoCode.StartsWith(rootCode, StringComparison.Ordinal))
                .Select(p => p.SoCode).Distinct().OrderBy(x => x, StringComparer.Ordinal).ToList();
            var idx = 0;
            foreach (var soCode in mine)
            {
                var parts = soCode.Split('.');
                if (parts.Length <= 1 || parts[1].Length < 1) continue;
                var suffix = parts[1].Trim();
                // ⚠️ Chỉ nhận suffix có KÝ TỰ ĐẦU là chữ số 0-9; còn lại BỎ IM LẶNG.
                if (!char.IsDigit(suffix[0])) { skippedSuffixes.Add(soCode); continue; }
                built = idx == 0 ? $"{built}.{suffix}".Trim() : $"{built}-{suffix}".Trim();
                idx++;
            }
            multi = string.IsNullOrEmpty(multi) ? built.Trim() : $"{multi}-{built}".Trim();
        }
        result = $"{dealerCode}-{paymentType}-{paymentNo}-{multi}".Trim();
    }
    else if (paymentType == "TTBL")
    {
        if (dealer.FlagTCG == "1")
        {
            // `Right(cv.VIN, 6)` nối bằng '-'.
            var six = cars.Select(c => c.VIN.Length >= 6 ? c.VIN.Substring(c.VIN.Length - 6) : c.VIN)
                .OrderBy(x => x, StringComparer.Ordinal).ToList();
            if (six.Count == 0)
                return Results.BadRequest(new { error = "Pmt_Payment_GetUNCContent_GuaranteeNoNotFound" });
            result = $"{dealerCode}-{paymentType}-{paymentNo}-{string.Join("-", six)}".Trim();
        }
        else
        {
            // `FlagTCG = '0'`: theo BankGuaranteeNo + danh sách VIN mỗi bảo lãnh; lọc BankGuaranteeNo is not null.
            var vins = cars.Select(c => c.VIN).ToHashSet();
            var dtls = await db.BankGuaranteeDtls.Where(x => x.OrgId == t.OrgId && vins.Contains(x.VIN))
                .Select(x => new { x.GuaranteeId, x.VIN }).ToListAsync();
            var grtIds = dtls.Select(x => x.GuaranteeId).Distinct().ToList();
            var grts = await db.BankGuarantees.Where(g => g.OrgId == t.OrgId && grtIds.Contains(g.Id))
                .Select(g => new { g.Id, g.BankGuaranteeNo }).ToListAsync();
            var usable = grts.Where(g => !string.IsNullOrWhiteSpace(g.BankGuaranteeNo)).ToList();
            if (usable.Count == 0)
                return Results.BadRequest(new { error = "Pmt_Payment_GetUNCContent_GuaranteeNoNotFound" });
            var chunks = usable.OrderBy(g => g.BankGuaranteeNo, StringComparer.Ordinal).Select(g =>
            {
                var mine = dtls.Where(d => d.GuaranteeId == g.Id).Select(d => d.VIN)
                    .Distinct().OrderBy(x => x, StringComparer.Ordinal).ToList();
                return $"{g.BankGuaranteeNo}-{string.Join("-", mine)}";
            }).ToList();
            result = $"{dealerCode}-{paymentType}-{paymentNo}-{string.Join("-", chunks)}".Trim();
        }
    }
    else
        return Results.BadRequest(new { error = "Pmt_Payment_GetUNCContent_InvalidPaymentType", check = new { PaymentType = paymentType } });

    return Results.Ok(new
    {
        uncContent = result,
        dealerCode, paymentType, paymentNo,
        carCount = carIds.Count,
        flagTCG = dealer.FlagTCG,
        skippedSuffixes,
        twinNote = "BAY SINH DOI DA TRACE: cung file con Pmt_Payment_GetUNCContent_New20200327 (:25895); WS CHI goi ban _New20221111 (:26601) => ban 2020 CHET. Khong doan theo hau to lon hon.",
        ttcRuleNote = "Nhanh TTC dung ma don NHIEU TANG: Input_CarId -> Car_Car.SOCode -> Ord_SalesOrder.SOCode, roi SORCode -> DMS40_Ord_SalesOrderRoot.SORCode. Voi MOI SORCode: lay phan TRUOC dau '.' DAU TIEN lam goc, loc lai SOCode bang like '<goc>%' (SOCode MANG SORCode lam TIEN TO), lay phan SAU dau '.' cua tung SOCode roi noi: phan tu DAU TIEN bang '.', cac phan tu SAU bang '-'. Nhieu SORCode noi tiep bang '-'.",
        digitFilterNote = "BO LOC KY TU: chi nhan suffix ma KY TU DAU la chu so 0-9 (nguon viet han 10 phep StringEqualIgnoreCase liet ke '0'..'9'); suffix bat dau bang chu BI BO IM LANG. Da liet ke o skippedSuffixes.",
        ttblRuleNote = "Nhanh TTBL re theo Mst_Dealer.FlagTCG: '1' => noi 6 KY TU CUOI cua VIN (Right(cv.VIN,6)) ngan bang '-'; '0' => noi theo BankGuaranteeNo kem danh sach VIN moi bao lanh, LOC BankGuaranteeNo is not null. Khong tim duoc bao lanh => GuaranteeNoNotFound.",
        orderNote = "Nguon noi chuoi bang STUFF((... FOR XML PATH('')),1,1,'') va KHONG CO 'order by' => thu tu KHONG TAT DINH. Port sap theo VIN / so bao lanh de tai lap duoc - day la KHAC BIET CO Y, khong phai port sai.",
        sourceQuirks = "LOI MA LOI TRONG NGUON (ghi nhan, KHONG tu sua): 'if (String.IsNullOrEmpty(strDealerCode))' nem _InvalidPaymentType (:26684) - dang le la ma loi cua ma dai ly. Hon nua phep kiem nay dung SAU myCommon_CheckDealer von da nem khi rong => nhanh nay KHONG BAO GIO chay toi.",
        validateNote = "myCommon_CheckDealer(..., Active, Active) (dai ly ton tai VA dang hoat dong) + myCar_CheckCar(..., Active, Active) cho TUNG CarId trong bang dau vao."
    });
}).RequireAuthorization();

// ===== #B80 SỬA CỜ TRẠNG THÁI CỦA XE — `CarCarUpdate02_New20260409` =====
// Trace LIVE: WS `CarCarUpdate02` (`WSHTC.asmx.cs:13561`) → **`_biz.CarCarUpdate02_New20260409`**
//   (`DataWH/Biz.HTC.WH.My.cs:27486`). 3B đo thật, **khớp cả 2 máy**: start=27486 md5
//   `528324fe3b941c1b7ad621d011f79fd2`.
// 🔴 **NĂM bản trùng tên — đã TRACE, KHÔNG đoán theo hậu tố**:
//      `…_New20260409` (`:27486`)  ← **WS gọi bản này**
//      `…_New20230306` (`:27320`)  ← cùng file, **CHẾT**
//      `…_New20200805` (`Delete.Biz.HTC.WH.My.cs`) · `CarCarUpdate02` + `…_New20181115`
//      (`Delete.BizHTC.Report.cs`) ← file RÁC.
// 🔴 **BẢN 2026 THÊM GÌ so với bản 2023** (đối chiếu `alColumnEffective` hai bên):
//    · tham số + cột **`FlagTestCar`** (xe chạy thử) — bản 2023 **không có**;
//    · **`LogLUDateTime` / `LogLUBy`** — bản 2023 **KHÔNG ghi dấu vết gì cả**.
//    ⇒ Port theo bản 2026: **7 cột** trong `alColumnEffective`, không phải 4.
// 🔴 **GUARD BẤT ĐỐI XỨNG — rất dễ port nhầm `&&` thành `||`** (`:27578-27581`):
//      `if (VIN != DBNull.Value)`
//         `if (strFlagMapVIN != Flag.Active && strFlagEarlyCancel != Flag.Inactive) throw …`
//    Đọc cho đúng: chỉ **NÉM** khi **cả hai** đồng thời — `FlagMapVIN` **khác "1"** *và*
//    `FlagEarlyCancel` **khác "0"**. Nghĩa nghiệp vụ: **xe ĐÃ ghép VIN chỉ được TẮT cờ `FlagMapVIN`
//    khi `FlagEarlyCancel = "0"`**; nếu xe đang ở diện huỷ sớm thì không được tắt.
//    ⚠️ Hai vế dùng **hằng NGƯỢC NHAU** (`Active` ở vế trái, `Inactive` ở vế phải) — không phải lỗi
//      gõ. Đổi `&&` thành `||`, hoặc "thống nhất" hai hằng, đều làm sai luật.
//    Lỗi: `CarCarUpdate02_CarIdMappedVIN_InvalidFlagMapVINorFlagEarlyCancel`, kèm `CarId` + `VINMapped`.
// 🔴 `TUtils.CUtils.StandardizeFlag` áp cho **cả bốn cờ** (không áp cho `CarCancelRemark`).
// 🔴 Nguồn `SaveData("Car_Car", …)` **hai lần** — `_dbMain` rồi `_dbWH` (cùng khuôn #B75/#B76/#B77).
// ✅ `myCar_CheckCar(…, Flag.Active, Flag.Active, "", "", "", "", "", …)` — xe phải **tồn tại và đang
//    hoạt động**; **năm** tham số kiểm còn lại truyền **chuỗi RỖNG** ⇒ **cố ý KHÔNG kiểm** trạng thái
//    thanh toán / giao xe / cho-đổi-VIN / VIN-free / đại lý. Đừng "thêm cho chặt".
// 📌 §12: `CarVinMaster.FlagMapVIN` · `.FlagCarDeliveryOrder` · `.FlagTestCar` · `.MappedVin` (= `Car_Car.VIN`,
//    VIN ĐÃ GHÉP — nguồn tách `CarId` khoá xe với `VIN` đã ghép; MiniHTC gộp bảng nên phải thêm cột này).
app.MapPost("/api/cars/{carId}/update-flags", async (
    string carId, CarUpdateFlagsDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    var id = (carId ?? "").Trim();
    var car = await db.CarVinMasters.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.VIN == id);
    // `myCar_CheckCar(…, Active, Active, …)` — tồn tại VÀ đang hoạt động.
    if (car is null) return Results.NotFound(new { error = "Common_InvalidCarId", check = new { CarId = id } });
    if (car.FlagActive != "1")
        return Results.BadRequest(new { error = "Common_InvalidCarIdNotActive", check = new { CarId = id } });

    static string? StdFlag(string? s) => string.IsNullOrWhiteSpace(s) ? null : s.Trim();
    var flagMapVIN = StdFlag(dto.FlagMapVIN);
    var flagEarlyCancel = StdFlag(dto.FlagEarlyCancel);
    var flagCarDeliveryOrder = StdFlag(dto.FlagCarDeliveryOrder);
    var flagTestCar = StdFlag(dto.FlagTestCar);

    // 🔴 GUARD: chỉ ném khi CẢ HAI — FlagMapVIN khác "1" VÀ FlagEarlyCancel khác "0".
    var mappedVin = car.MappedVin;   // = `Car_Car.VIN` (VIN đã ghép), KHÁC khoá dòng.
    if (!string.IsNullOrWhiteSpace(mappedVin))
    {
        if (flagMapVIN != "1" && flagEarlyCancel != "0")
            return Results.BadRequest(new
            {
                error = "CarCarUpdate02_CarIdMappedVIN_InvalidFlagMapVINorFlagEarlyCancel",
                check = new { CarId = id, VINMapped = mappedVin },
                guardNote = "Chi NEM khi CA HAI: FlagMapVIN khac '1' VA FlagEarlyCancel khac '0'. Nghia: xe DA ghep VIN chi duoc TAT co FlagMapVIN khi FlagEarlyCancel = '0'."
            });
    }

    // `alColumnEffective` của bản 2026: BẢY cột.
    car.CarCancelRemark = dto.CarCancelRemark;
    car.FlagMapVIN = flagMapVIN;
    car.FlagEarlyCancel = flagEarlyCancel;
    car.FlagCarDeliveryOrder = flagCarDeliveryOrder;
    car.FlagTestCar = flagTestCar;
    car.LogLUDateTime = DateTime.Now;
    car.LogLUBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        carId = id,
        car.CarCancelRemark, car.FlagMapVIN, car.FlagEarlyCancel,
        car.FlagCarDeliveryOrder, car.FlagTestCar, car.LogLUDateTime, car.LogLUBy,
        twinNote = "NAM ban trung ten - DA TRACE: WS goi _New20260409 (:27486); _New20230306 (:27320) cung file la CHET; _New20200805 (Delete.Biz.HTC.WH.My.cs) va CarCarUpdate02/_New20181115 (Delete.BizHTC.Report.cs) la file RAC.",
        versionDiffNote = "Ban 2026 THEM so voi ban 2023: (a) tham so + cot FlagTestCar; (b) LogLUDateTime/LogLUBy - ban 2023 KHONG ghi dau vet gi ca. Vay alColumnEffective la BAY cot, khong phai bon.",
        guardAsymmetryNote = "GUARD BAT DOI XUNG: 'if (VIN != DBNull) { if (strFlagMapVIN != Flag.Active && strFlagEarlyCancel != Flag.Inactive) throw }'. Hai ve dung HANG NGUOC NHAU (Active o ve trai, Inactive o ve phai) - KHONG phai loi go. Doi && thanh ||, hoac 'thong nhat' hai hang, deu lam SAI luat.",
        checkCarNote = "myCar_CheckCar(..., Flag.Active, Flag.Active, '', '', '', '', '', ...) - xe phai ton tai VA dang hoat dong; NAM tham so kiem con lai truyen CHUOI RONG => CO Y KHONG kiem trang thai thanh toan / giao xe / cho-doi-VIN / VIN-free / dai ly. Dung 'them cho chat'.",
        stdFlagNote = "StandardizeFlag ap cho CA BON co; KHONG ap cho CarCancelRemark.",
        twoDbNote = "Nguon SaveData('Car_Car', ...) HAI LAN - _dbMain roi _dbWH (cung khuon #B75/#B76/#B77).",
        vinIdentityNote = "Nguon phan biet Car_Car.CarId (khoa xe) voi Car_Car.VIN (VIN da ghep). MiniHTC gop lam mot bang CarVinMaster khoa theo VIN, nen 'da ghep VIN' doc qua cot rieng - xem MappedVin."
    });
}).RequireAuthorization();

// ===== #B81 DUYỆT PACKING LIST HỢP ĐỒNG — `ContractPackingListApproved_New20181115` =====
// Trace LIVE: `SalesService.cs:14250` → WS `ContractPackingListApproved` (`WSHTC.asmx.cs:8470`) →
//   **`_biz.ContractPackingListApproved_New20181115`** (`BizHTC.Contract.cs:396`) — **bản DUY NHẤT**,
//   không có sinh đôi (đã grep toàn `TERP.BizHTC/`, trừ file rác).
//   3B đo thật, **khớp cả 2 máy**: start=396 md5 `8363086db4bd9adb5e40d376510aee5c`.
// 🔴 **HAI BẢNG BỊ ĐỔI TRẠNG THÁI, KHÔNG PHẢI MỘT** — cùng một batch SQL:
//    1) `CT_PackingList.PLStatus = 'F'` (+ `LogLUDateTime` / `LogLUBy`) theo `PackingListNo`.
//    2) **`HTMV_PDIDtl.PDIStorageStatus = 'F'`** (+ `LogLU*`) cho **MỌI VIN thuộc packing list đó**,
//       nối qua `HTMV_PDIDtl.VIN = Car_VIN.VIN` rồi `Car_VIN.PackingListNo = CT_PackingList.PackingListNo`.
//    ⚠️ Bước 2 là **tác dụng phụ sang phân hệ PDI** — port thiếu thì kho PDI **đứng nguyên trạng thái
//      cũ** trong khi packing list đã duyệt xong, không ai thấy sai cho tới lúc đối soát kho.
//    ⚠️ Đường nối đi qua **`Car_VIN.PackingListNo`**, KHÔNG phải qua khoá ngoại của `HTMV_PDIDtl`.
//      Dòng PDI của VIN **không còn trỏ đúng packing list** sẽ **không** được cập nhật.
// 🔴 **`bCheckDataClosed = true`** trong `myContract_CheckPackingList(…)` — **kỳ dữ liệu ĐÃ CHỐT thì
//    TỪ CHỐI**. Đây là lời gọi hiếm hoi truyền `true` (các nơi khác trong phiên B đều `false`/không có).
// 🔴 **KHÔNG có điều kiện trạng thái trước đó**: nguồn `update … set PLStatus = 'F'` **không** kiểm
//    `PLStatus` hiện tại ⇒ duyệt lại một packing list đã duyệt là **hợp lệ và không đổi gì** (idempotent).
//    Đừng tự thêm guard "chỉ duyệt khi đang chờ" — sẽ chặt hơn nguồn (`C0-…quinquagesimussextus`).
// 🔴 **CHỈ GHI `_dbMain`** — hàm này **KHÔNG** ghi `_dbWH`, khác hẳn #B75/#B76/#B77/#B80 vốn ghi cả hai.
//    Ghi nhận nguyên trạng, không "cho đồng bộ".
// ✅ RBAC: `myCommon_CheckHTCDirect(…, TConst.Flag.Active)` — bắt buộc FlagDirect.
// 📌 Từ vựng: `'F'` = `TConst.Stage.Finished` — **thuộc từ vựng nguồn**, không phải trạng thái tự chế.
app.MapPost("/api/packinglists/{no}/approve-contract", async (
    string no, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var plNo = (no ?? "").Trim();
    var pl = await db.PackingLists.FirstOrDefaultAsync(p => p.OrgId == t.OrgId && p.PLNo == plNo);
    if (pl is null)
        return Results.NotFound(new { error = "Contract_InvalidPackingListNo", check = new { PackingListNo = plNo } });

    var now = DateTime.Now;
    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";

    // (1) `CT_PackingList.PLStatus = 'F'` — KHÔNG kiểm trạng thái trước đó.
    var plStatusBefore = pl.PLStatus;
    pl.PLStatus = "F";
    pl.LogLUDateTime = now;
    pl.LogLUBy = by;

    // (2) Tác dụng phụ sang PDI: đường nối đi qua `Car_VIN.PackingListNo`.
    var vinsOfPl = (await db.CarVinMasters
        .Where(c => c.OrgId == t.OrgId && c.PackingListNo == plNo)
        .Select(c => c.VIN).ToListAsync()).ToHashSet();
    var pdiRows = await db.HtmvPdiDtls
        .Where(d => d.OrgId == t.OrgId && vinsOfPl.Contains(d.VIN)).ToListAsync();
    foreach (var d in pdiRows)
    {
        d.PDIStorageStatus = "F";
        d.LogLUDateTime = now;
        d.LogLUBy = by;
    }

    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        packingListNo = plNo,
        plStatusBefore, plStatus = pl.PLStatus,
        vinCount = vinsOfPl.Count,
        pdiDtlUpdated = pdiRows.Count,
        logLUDateTime = now, logLUBy = by,
        cascadeNote = "HAI BANG bi doi trang thai, KHONG PHAI MOT: (1) CT_PackingList.PLStatus='F'; (2) HTMV_PDIDtl.PDIStorageStatus='F' cho MOI VIN thuoc packing list do. Port thieu buoc 2 thi kho PDI DUNG NGUYEN trang thai cu trong khi packing list da duyet xong - khong ai thay sai cho toi luc doi soat kho.",
        joinPathNote = "Duong noi di qua Car_VIN.PackingListNo (HTMV_PDIDtl.VIN = Car_VIN.VIN roi Car_VIN.PackingListNo = CT_PackingList.PackingListNo), KHONG phai qua khoa ngoai cua HTMV_PDIDtl. Dong PDI cua VIN khong con tro dung packing list se KHONG duoc cap nhat.",
        dataClosedNote = "Nguon goi myContract_CheckPackingList(..., bCheckDataClosed = TRUE) - ky du lieu DA CHOT thi TU CHOI. Day la loi goi hiem hoi truyen true. MiniHTC chua co tang 'ky du lieu da chot' => xem dataClosedDebt.",
        dataClosedDebt = "NO: MiniHTC chua co tang khoa ky du lieu (Data Closed) nen guard nay KHONG kiem duoc. Khong bia - chi ghi nhan.",
        idempotentNote = "KHONG co dieu kien trang thai truoc do: nguon 'update ... set PLStatus = F' khong kiem PLStatus hien tai => duyet lai mot packing list da duyet la HOP LE va khong doi gi. Dung tu them guard 'chi duyet khi dang cho' - se chat hon nguon.",
        singleDbNote = "Ham nay CHI ghi _dbMain, KHONG ghi _dbWH - khac han #B75/#B76/#B77/#B80 von ghi ca hai. Ghi nhan nguyen trang, khong 'cho dong bo'.",
        vocabNote = "'F' = TConst.Stage.Finished - THUOC tu vung nguon, khong phai trang thai tu che.",
        rbacNote = "myCommon_CheckHTCDirect(..., TConst.Flag.Active) - bat buoc FlagDirect."
    });
}).RequireAuthorization();

// ===== #B82 DUYỆT / HUỶ HÀNG LOẠT ĐỀ NGHỊ HUỶ HỢP ĐỒNG ĐẠI LÝ =====
//   `Dlr_ContractCancel_ApproveMulti` (`BizHTC.Contract.cs:3615` → `…MultiX` `:3323`)
//   `Dlr_ContractCancel_CancelMulti`  (`:3991` → `…MultiX` `:3745`)
//   3B đo thật, **khớp cả 2 máy**: ApproveMultiX start=3323 md5 `6a821f3dd4a185e74103fae0aef5131a`
//   · CancelMultiX start=3745 md5 `23342c4b781753efe3e6b4523eec35bb`.
// 🔴 **HAI HÀM GIỐNG NHAU GẦN NHƯ HOÀN TOÀN — KHÁC ĐÚNG MỘT DÒNG**:
//      duyệt : `drScan["ContractCancelStatus"] = TConst.ContractCancelStatus.**Approved**` ("A")
//      huỷ   : `drScan["ContractCancelStatus"] = TConst.ContractCancelStatus.**Cancel**`   ("C")
//    ⚠️ **CẢ HAI đều đóng dấu vào `ApprovedDate` / `ApprovedBy`** — hàm HUỶ **KHÔNG** có cặp
//      `CancelDate`/`CancelBy` riêng. Nghe phản trực giác nhưng là hành vi THẬT; port thêm cặp
//      `Cancel*` là **đẻ cột ngoài nguồn**.
// 🔴 **BOM HẸN GIỜ TỪ VỰNG — guard dùng HẰNG CỦA PHÂN HỆ KHÁC**:
//      `Dlr_ContractCancel_CheckDB(…, TConst.**TestCarStatus**.Pending, …)`  (`:3390` và `:3846`)
//    Đáng lẽ phải là `TConst.**ContractCancelStatus**.Pending`. Hiện **chạy đúng** vì cả hai hằng đều
//    `= "P"` (`Const.Main.DMS40.cs:127` và `:142`), nhưng đây là **liên kết chéo phân hệ**: đổi
//    `TestCarStatus.Pending` (xe chạy thử) sẽ **âm thầm làm hỏng** duyệt/huỷ hợp đồng đại lý.
//    Port dùng đúng từ vựng `ContractCancelStatus` và **ghi nhận** ở `vocabTimeBomb`, không tự sửa nguồn.
// 🔴 **Điều kiện vào**: chỉ phiếu đang **"P"** mới được duyệt/huỷ (`strStatusListToCheck`).
// 🔴 **CASCADE xuống DÒNG**: `update Dlr_ContractCancelDtl set t.ContractCancelDtlStatus =
//    **f.ContractCancelStatus**` — trạng thái dòng **bám theo trạng thái phiếu vừa gán**, không phải
//    một hằng cố định. Port thiếu bước này ⇒ phiếu "A" mà dòng vẫn "P".
// 🔴 **Đầu vào là BẢNG `Dlr_ContractCancel`** (`MyBuildDBDT_Common` → `#input_Dlr_ContractCancel`),
//    không phải danh sách phẳng: thiếu bảng ⇒ `…_Input_ContractCancelTblNotFound`; **rỗng** ⇒
//    `…_Input_ContractCancelTblInvalid`. ⚠️ Khác #B76: ở đây danh sách rỗng **BỊ TỪ CHỐI**.
// ✅ **RBAC ba tầng, kiểm THEO TỪNG DÒNG** (không phải một lần cho cả lô):
//    `myCommon_CheckHTCDirect(…, Active)` · `myCommon_CheckDealer(…, Active, Active)` ·
//    **`myCommon_CheckAccessDealerData(drAbilityOfUser["BUPattern"], md.BUCode)`** — phạm vi BU
//    **được thực thi thật**, đối chứng lành thứ hai sau #B78.
// 🔴 Ghi **cả `_dbMain` và `_dbWH`** (hai lần `MyBuildDBDT_Common` + hai lần update).
app.MapPost("/api/dlrcontractcancels/approve-multi", async (
    List<string> contractCNos, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user, string? buPattern, string? enforceBuScope) =>
    await DlrContractCancelSetStatusMulti(contractCNos, "A", db, t, user, buPattern, enforceBuScope))
    .RequireAuthorization();

app.MapPost("/api/dlrcontractcancels/cancel-multi", async (
    List<string> contractCNos, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user, string? buPattern, string? enforceBuScope) =>
    await DlrContractCancelSetStatusMulti(contractCNos, "C", db, t, user, buPattern, enforceBuScope))
    .RequireAuthorization();

// ===== #B83 LƯU / XOÁ ĐẦU HỢP ĐỒNG ĐẠI LÝ — `Dlr_ContractDetail_Save_New20230306` =====
// Trace LIVE: WS `Dlr_ContractDetail_Save` (`WSHTC.asmx.cs:37150`) →
//   **`_biz.Dlr_ContractDetail_Save_New20230306`** (`BizHTC.Contract.cs:9003`).
//   🔴 Sinh đôi: cùng file còn `…_New20190617` — WS **chỉ gọi bản 2023** ⇒ bản 2019 **CHẾT**.
//   3B đo thật, **khớp cả 2 máy**: start=9003 md5 `e27972c7b2659c4b627314345a81cdb7`.
// ⚠️ **KHÔNG phải cùng nghiệp vụ với `POST /api/dlrcontracts` đã có** (#130 — tạo hợp đồng từ
//    `DealerSalesDealCreate_SellToDealer_New20230306`). Hàm này là **UPSERT + XOÁ theo `DlrContractNo`**
//    kèm **đếm phiên bản**, WS riêng ⇒ route riêng.
// 🔴 **XOÁ CÁI KHÔNG TỒN TẠI = THÀNH CÔNG**, không phải lỗi: nguồn `if (Rows.Count < 1) { if (bIsDelete)
//    goto MyCodeLabel_Done; }` (`:9118-9121`) — nhảy thẳng tới nhánh **Thành công**. Port trả 200.
// 🔴 **BỘ ĐẾM PHIÊN BẢN — bốn cột đi cùng nhau**:
//    · **Thêm mới**: `VersionDTimeOld = null` · `VersionDTimeCurr = now` · **`VersionCount = 1`**
//    · **Sửa**:      `VersionDTimeOld` = **`VersionDTimeCurr` CŨ trong DB** · `VersionDTimeCurr = now`
//                    · `VersionCount` = **giá trị cũ + 1** · `VersionUpdateBy` = người sửa.
//    ⇒ `VersionCount` **đếm từ 1**, không phải 0; và `VersionDTimeOld` là **mốc của lần trước**,
//      không phải "ngày tạo". Port bỏ qua một trong bốn cột là mất khả năng dựng lại lịch sử.
// 🔴 **`CreatedDate`/`CreatedBy` LẤY LẠI TỪ BẢN GHI CŨ khi sửa** (`:9150-9151`), chỉ rơi về
//    `now`/người-đang-thao-tác khi **rỗng** (`:9160-9161`). Port gán thẳng `DateTime.Now` là **xoá
//    dấu vết tạo** của hợp đồng cũ.
// 🔴 **`FlagDealFinish` bị ĐẶT LẠI `Flag.Inactive` ("0") ở MỌI lần lưu** — kể cả khi SỬA
//    (`:9330`). Nghĩa: **sửa một hợp đồng đã chốt giao dịch sẽ mở chốt lại**. Hành vi THẬT,
//    không phải thiếu sót; ghi rõ ở `flagDealFinishResetNote`.
//    Cùng khối: `FlagActive` luôn gán `Active` ("1").
// 🔴 **`BankCode` rỗng ⇒ ĐỔI THÀNH `null`** trước khi ghi (`:9272-9275`) — chuỗi rỗng và NULL là hai
//    giá trị KHÁC nhau ở tầng dưới; port giữ `""` sẽ làm lệch mọi `is null` sau này.
// 🔴 **GUARD chéo đại lý — HAI trục RBAC KHÁC NHAU, đừng gộp**:
//    · `myCommon_CheckUpdateDealerData(drAbilityOfUser["**DealerCode**"], …)` — chú thích nguồn:
//      *"Đại lý không được sửa/xóa chéo nhau"*. Trục này theo **MÃ ĐẠI LÝ của người dùng**,
//      **KHÔNG** phải `BUPattern` như #B78/#B82.
//    · `Dlr_ContractDetail_Save_CustomerBelongToAnotherDealer` — khách hàng (`DLS_DealerCustomer`)
//      phải thuộc **đúng đại lý** đang lưu; người giao dịch (`DLS_DealerTransactor`) phải tồn tại.
// 🔴 Ghi **cả `_dbMain` và `_dbWH`** (hai lần `MyBuildDBDT_Common`, và chỉ dựng khi **không** xoá).
app.MapPost("/api/dlrcontracts/{no}/save-header", async (
    string no, DlrContractHeaderSaveDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user, string? dealerCodeOfUser) =>
{
    var ctrNo = (no ?? "").Trim();
    var isDelete = (dto.FlagIsDelete ?? "").Trim().ToUpperInvariant() is "Y" or "1";
    var now = DateTime.Now;
    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";

    var cur = await db.DlrContracts.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.DlrContractNo == ctrNo);

    // 🔴 Xoá cái KHÔNG tồn tại = THÀNH CÔNG (goto MyCodeLabel_Done).
    if (cur is null && isDelete)
        return Results.Ok(new
        {
            dlrContractNo = ctrNo, deleted = 0,
            deleteMissingNote = "Xoa cai KHONG ton tai = THANH CONG, khong phai loi: nguon 'if (Rows.Count < 1) { if (bIsDelete) goto MyCodeLabel_Done; }' nhay thang toi nhanh Thanh cong."
        });

    var dealerCode = (dto.DealerCode ?? cur?.DealerCode ?? "").Trim().ToUpperInvariant();

    // Đã tồn tại ⇒ kiểm chéo đại lý theo MÃ ĐẠI LÝ của người dùng (KHÔNG phải BUPattern).
    if (cur is not null)
    {
        var dl = await db.Dealers.FirstOrDefaultAsync(d => d.OrgId == t.OrgId && d.DealerCode == cur.DealerCode);
        if (dl is null || dl.FlagActive != "1")
            return Results.BadRequest(new { error = "Common_InvalidDealerCode", check = new { cur.DealerCode } });
        var userDealer = (dealerCodeOfUser ?? "").Trim().ToUpperInvariant();
        if (userDealer.Length > 0 && !string.Equals(userDealer, cur.DealerCode, StringComparison.OrdinalIgnoreCase))
            return Results.BadRequest(new
            {
                error = "Common_UpdateDealerDataDenied",
                check = new { DealerOfUser = userDealer, DealerNeedToUpdate = cur.DealerCode },
                note = "myCommon_CheckUpdateDealerData(drAbilityOfUser['DealerCode'], ...) - 'Dai ly khong duoc sua/xoa cheo nhau'. Truc nay theo MA DAI LY cua nguoi dung, KHONG phai BUPattern."
            });
    }

    if (isDelete)
    {
        var dtlsDel = await db.DlrContractDetails.Where(d => d.OrgId == t.OrgId && d.DlrContractNo == ctrNo).ToListAsync();
        db.DlrContractDetails.RemoveRange(dtlsDel);
        db.DlrContracts.Remove(cur!);
        await db.SaveChangesAsync();
        return Results.Ok(new { dlrContractNo = ctrNo, deleted = 1, deletedLines = dtlsDel.Count });
    }

    // ---- Kiểm khách hàng / người giao dịch thuộc đúng đại lý.
    var custCode = (dto.CustomerCode ?? "").Trim().ToUpperInvariant();
    if (custCode.Length > 0)
    {
        var link = await db.DealerCustomers
            .FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CustomerCode == custCode);
        if (link is null)
            return Results.BadRequest(new { error = "Common_InvalidCustomerCode", check = new { CustomerCode = custCode } });
        if (!string.Equals(link.DealerCode ?? "", dealerCode, StringComparison.OrdinalIgnoreCase))
            return Results.BadRequest(new
            {
                error = "Dlr_ContractDetail_Save_CustomerBelongToAnotherDealer",
                check = new { strCustomerCode = custCode, DealerCodeNotMatch = link.DealerCode }
            });
    }

    // ---- Bộ đếm phiên bản: BỐN cột đi cùng nhau.
    DateTime? versionOld; DateTime versionCurr = now; int versionCount; string versionBy = by;
    DateTime createdAt; string? createdBy;
    if (cur is null)
    {
        versionOld = null; versionCount = 1;            // 🔴 đếm từ 1, không phải 0
        createdAt = now; createdBy = by;
        cur = new DlrContract { OrgId = t.OrgId, DlrContractNo = ctrNo };
        db.DlrContracts.Add(cur);
    }
    else
    {
        versionOld = cur.VersionDTimeCurr;              // 🔴 mốc của LẦN TRƯỚC, không phải ngày tạo
        versionCount = cur.VersionCount + 1;
        // 🔴 Giữ dấu vết TẠO của bản ghi cũ; chỉ rơi về now/by khi RỖNG.
        createdAt = cur.CreatedAt == default ? now : cur.CreatedAt;
        createdBy = string.IsNullOrWhiteSpace(cur.CreatedBy) ? by : cur.CreatedBy;
    }

    cur.ContractDate = dto.ContractDate ?? cur.ContractDate;
    cur.CustomerCode = custCode;
    cur.TransactorCode = string.IsNullOrWhiteSpace(dto.TransactorCode) ? null : dto.TransactorCode.Trim();
    cur.DealerCode = dealerCode;
    cur.DealerCodeBuyer = string.IsNullOrWhiteSpace(dto.DealerCodeBuyer) ? null : dto.DealerCodeBuyer.Trim().ToUpperInvariant();
    cur.DlrContractNoUser = (dto.DlrContractNoUser ?? "").Trim();
    cur.SalesType = (dto.SalesType ?? "").Trim();
    cur.SalesManCode = (dto.SMCode ?? "").Trim();       // nguồn: `SMCode`
    // 🔴 BankCode rỗng ⇒ NULL (chuỗi rỗng và NULL là hai giá trị KHÁC nhau ở tầng dưới).
    cur.BankCode = string.IsNullOrEmpty((dto.BankCode ?? "").Trim()) ? null : dto.BankCode!.Trim();
    cur.CreatedAt = createdAt; cur.CreatedBy = createdBy;
    cur.VersionDTimeOld = versionOld; cur.VersionDTimeCurr = versionCurr;
    cur.VersionCount = versionCount; cur.VersionUpdateBy = versionBy;
    // 🔴 ĐẶT LẠI ở MỌI lần lưu — kể cả khi SỬA.
    cur.FlagDealFinish = "0";
    cur.FlagActive = "1";
    cur.LogLUDateTime = now; cur.LogLUBy = by;

    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        dlrContractNo = ctrNo,
        mode = versionCount == 1 ? "Insert" : "Update",
        cur.VersionDTimeOld, cur.VersionDTimeCurr, cur.VersionCount, cur.VersionUpdateBy,
        cur.CreatedAt, cur.CreatedBy, cur.FlagDealFinish, cur.FlagActive, cur.BankCode,
        twinNote = "Sinh doi: cung file con Dlr_ContractDetail_Save_New20190617; WS (WSHTC.asmx.cs:37216) CHI goi ban _New20230306 => ban 2019 CHET.",
        notSameAsCreateNote = "KHONG cung nghiep vu voi POST /api/dlrcontracts da co (#130 - tao hop dong tu DealerSalesDealCreate_SellToDealer_New20230306). Ham nay la UPSERT + XOA theo DlrContractNo kem dem phien ban, WS rieng => route rieng.",
        deleteMissingNote = "Xoa cai KHONG ton tai = THANH CONG (goto MyCodeLabel_Done), khong phai loi.",
        versionRuleNote = "BON cot phien ban di cung nhau. Them moi: VersionDTimeOld=null, VersionDTimeCurr=now, VersionCount=1 (DEM TU 1, khong phai 0). Sua: VersionDTimeOld = VersionDTimeCurr CU TRONG DB (moc cua LAN TRUOC, khong phai ngay tao), VersionDTimeCurr=now, VersionCount = gia tri cu + 1, VersionUpdateBy = nguoi sua. Bo qua mot trong bon cot la mat kha nang dung lai lich su.",
        createdTraceNote = "CreatedDate/CreatedBy LAY LAI TU BAN GHI CU khi sua, chi roi ve now/nguoi-dang-thao-tac khi RONG. Port gan thang DateTime.Now la XOA DAU VET TAO cua hop dong cu.",
        flagDealFinishResetNote = "FlagDealFinish bi DAT LAI Flag.Inactive ('0') o MOI lan luu - KE CA khi SUA => sua mot hop dong da chot giao dich se MO CHOT LAI. Hanh vi THAT, khong phai thieu sot.",
        bankCodeNullNote = "BankCode rong => DOI THANH null truoc khi ghi. Chuoi rong va NULL la hai gia tri KHAC nhau o tang duoi; giu '' se lam lech moi 'is null' sau nay.",
        rbacAxisNote = "HAI TRUC RBAC KHAC NHAU, dung gop: (1) myCommon_CheckUpdateDealerData(drAbilityOfUser['DealerCode'], ...) - 'Dai ly khong duoc sua/xoa cheo nhau', theo MA DAI LY cua nguoi dung, KHONG phai BUPattern nhu #B78/#B82; (2) khach hang (DLS_DealerCustomer) phai thuoc DUNG dai ly dang luu, nguoi giao dich (DLS_DealerTransactor) phai ton tai.",
        twoDbNote = "Nguon ghi CA _dbMain va _dbWH (hai lan MyBuildDBDT_Common, va CHI dung khi KHONG xoa)."
    });
}).RequireAuthorization();

// ===== #B84 KÊNH iDEALER (ứng dụng đại lý) — HAI ĐIỂM VÀO TRA DANH MỤC =====
//   `iDealer_MstDataCarModel_Get_New20190215` (`BizHTC.IDealer.cs:22`,  WS `:57078`)
//   `iDealer_Mst_CarDrvTest_Get_New20190215`  (`BizHTC.IDealer.cs:146`, WS `:57160`)
//   3B đo thật, **khớp cả 2 máy**: `22/0ca93e4adb9bc66f45dd3987107a3f6d` ·
//   `146/6332a5c20627d2853ef9ebeefdab0f6b`.
// 🔴 **CẢ HAI CHỈ LÀ VỎ** — gọi thẳng **cùng hàm `*_GetX` mà màn hình NỘI BỘ đang dùng**:
//      `Mst_CarModel_GetX`     (`Biz.HTC.WH.cs:1432`)
//      `Mst_CarDrvTest_GetX`   (`Biz.HTC.WH.cs:185081`)
//    ⇒ **kênh ĐỐI TÁC dùng lại nguyên truy vấn nội bộ**, kể cả tham số lọc tự do
//      `strFt_WhereClause` (ghép thẳng vào `where` qua `zzzzClauseWhere_strFilterWhereClause`).
//      Port **KHÔNG** nhận where-clause thô từ client; chỉ mở các tham số lọc có tên.
// 🔴🔴 **LỖ HỔNG RBAC — BIẾN THỂ THỨ TƯ, NẶNG NHẤT TỪ ĐẦU PHIÊN: THAY BẰNG HẰNG CỨNG.**
//    Trong `Mst_CarDrvTest_GetX` (`Biz.HTC.WH.cs:185084-185102`):
//      `//alParamsCoupleSql.AddRange(… "@strBUPatternOfUser", drAbilityOfUser["BUPattern"]);` ← COMMENT
//      `alParamsCoupleSql.AddRange(new object[] { "@strBUPatternOfUser", **"HTC%"** });`        ← ĐANG CHẠY
//      `ON md.DealerCode = mcdt.DealerCode AND (md.BUCode like (**'HTC%'**))--@strBUPatternOfUser)`
//    ⇒ phạm vi BU **bị đóng cứng `'HTC%'`**, quyền thật của người dùng bị comment **HAI LẦN**
//      (một ở chỗ bind, một ngay trong mệnh đề `on`). Hệ quả **hai chiều**:
//        · người dùng thuộc BU khác **không thấy gì** (dữ liệu của họ bị chặn); và
//        · dữ liệu nhóm **HTC bị lộ cho MỌI người gọi**, kể cả qua **kênh đối tác iDealer**.
//    Bốn biến thể đã ghi nhận: `left join` mang điều kiện (#B45) · khai mà không dùng
//    (#B46/#B47/#B50/#B52/#B53) · comment trong `on` (#B70) · **thay bằng hằng cứng (#B84)**.
//    Đối chứng LÀNH: #B78, #B82. 📌 **Ưu tiên cao trong hồ sơ gửi nghiệp vụ/bảo mật** vì chạm kênh ngoài.
//    Port **giữ đúng nguồn** (mặc định `HTC%`) nhưng cho truyền `buPattern` và trả `buPatternApplied`
//    + `buPatternHardcoded` để đo; **không tự bịt**.
// ✅ `Mst_CarModel_GetX` thì **không có RBAC nào cả** — danh mục model là dữ liệu chung; đây là
//    thiết kế, không phải điều kiện bị bỏ quên (phân biệt theo `C0-…quinquagesimus`).
// 🔴 **Phân trang theo khuôn chung**: `identity(bigint, 0, 1) MyIdxSeq` trên bảng nháp, rồi
//    `select Count(0) MyCount` **TRƯỚC** khi cắt trang ⇒ `myCount` là **tổng toàn bộ**, không phải
//    số dòng của trang. Port giữ đúng thứ tự này.
app.MapGet("/api/idealer/carmodels", async (
    AppDbContext db, ITenantContext t, int? recordStart, int? recordCount, string? modelCode, string? modelName) =>
{
    var start = Math.Max(0, recordStart ?? 0);
    var count = Math.Clamp(recordCount ?? 200, 1, 1000);
    var q = db.CarModelStds.Where(m => m.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(modelCode)) q = q.Where(m => m.ModelCode.Contains(modelCode.Trim()));
    if (!string.IsNullOrWhiteSpace(modelName)) q = q.Where(m => m.ModelName != null && m.ModelName.Contains(modelName.Trim()));
    var all = await q.OrderBy(m => m.ModelCode).ToListAsync();
    var myCount = all.Count;                       // `MyCount` đếm TRƯỚC khi cắt trang
    var items = all.Skip(start).Take(count).Select(m => new
    {
        mcmModelCode = m.ModelCode, mcmModelName = m.ModelName,
        mcmFlagActive = m.FlagActive, mcmFlagBusinessPlan = m.FlagBusinessPlan
    }).ToList();
    return Results.Ok(new
    {
        myCount, recordStart = start, recordCount = count, count = items.Count, items,
        wrapperNote = "iDealer_MstDataCarModel_Get_New20190215 CHI LA VO, goi thang Mst_CarModel_GetX (Biz.HTC.WH.cs:1432) - dung CHUNG ham voi man hinh noi bo.",
        rbacNote = "Mst_CarModel_GetX KHONG co RBAC nao ca - danh muc model la du lieu chung. Day la THIET KE, khong phai dieu kien bi bo quen (phan biet theo C0-...quinquagesimus).",
        whereClauseNote = "Nguon nhan strFt_WhereClause ghep THANG vao 'where' qua zzzzClauseWhere_strFilterWhereClause. Port KHONG nhan where-clause tho tu client; chi mo cac tham so loc co ten.",
        pagingNote = "Khuon chung: identity(bigint,0,1) MyIdxSeq tren bang nhap, roi 'select Count(0) MyCount' TRUOC khi cat trang => myCount la TONG TOAN BO, khong phai so dong cua trang."
    });
}).RequireAuthorization();

app.MapGet("/api/idealer/cardrivetests", async (
    AppDbContext db, ITenantContext t, int? recordStart, int? recordCount,
    string? dealerCode, string? modelCode, string? buPattern) =>
{
    var start = Math.Max(0, recordStart ?? 0);
    var count = Math.Clamp(recordCount ?? 200, 1, 1000);
    // 🔴 Nguồn ĐÓNG CỨNG 'HTC%'. Giữ đúng nguồn làm mặc định, cho phép truyền để ĐO.
    var hardcoded = "HTC%";
    var applied = string.IsNullOrWhiteSpace(buPattern) ? hardcoded : buPattern.Trim();
    var prefix = applied.TrimEnd('%').ToUpperInvariant();

    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId)
        .Select(d => new { d.DealerCode, d.DealerName, d.BUCode }).ToListAsync();
    // `inner join Mst_Dealer … AND (md.BUCode like 'HTC%')` — inner join nên đại lý ngoài mẫu BỊ LOẠI.
    var inScope = dealers.Where(d => (d.BUCode ?? "").ToUpperInvariant().StartsWith(prefix))
        .Select(d => d.DealerCode).ToHashSet();

    var q = db.CarDriverTests.Where(x => x.OrgId == t.OrgId);
    var all = await q.ToListAsync();
    var beforeScope = all.Count;
    all = all.Where(x => x.DealerCode != null && inScope.Contains(x.DealerCode)).ToList();
    var droppedOutOfBuPattern = beforeScope - all.Count;

    if (!string.IsNullOrWhiteSpace(dealerCode))
        all = all.Where(x => (x.DealerCode ?? "").ToUpperInvariant() == dealerCode.Trim().ToUpperInvariant()).ToList();
    if (!string.IsNullOrWhiteSpace(modelCode))
        all = all.Where(x => (x.ModelCode ?? "").ToUpperInvariant() == modelCode.Trim().ToUpperInvariant()).ToList();

    var myCount = all.Count;                       // `MyCount` đếm TRƯỚC khi cắt trang
    var items = all.OrderBy(x => x.DealerCode).ThenBy(x => x.DrvTestVIN ?? "", StringComparer.Ordinal)
        .Skip(start).Take(count).Select(x => new
        {
            mcdtDealerCode = x.DealerCode,
            mdDealerName = dealers.FirstOrDefault(d => d.DealerCode == x.DealerCode)?.DealerName,
            mcdtVIN = x.DrvTestVIN, mcdtPlateNo = x.DrvTestPlateNo, mcdtEngineNo = x.DrvTestEngineNo,
            mcdtModelCode = x.ModelCode, mcdtSpecCode = x.SpecCode, mcdtColorCode = x.ColorCode,
            mcdtFlagActive = x.FlagActive
        }).ToList();

    return Results.Ok(new
    {
        myCount, recordStart = start, recordCount = count, count = items.Count, items,
        buPatternApplied = applied,
        buPatternHardcoded = hardcoded,
        droppedOutOfBuPattern,
        rbacHoleVariant4 = "LO HONG RBAC - BIEN THE THU TU, NANG NHAT: THAY BANG HANG CUNG. Trong Mst_CarDrvTest_GetX (Biz.HTC.WH.cs:185084-185102): dong bind '@strBUPatternOfUser = drAbilityOfUser[BUPattern]' BI COMMENT, dong DANG CHAY bind hang 'HTC%'; va ngay trong menh de 'on' cung la (md.BUCode like ('HTC%'))--@strBUPatternOfUser). Quyen that cua nguoi dung bi comment HAI LAN.",
        rbacImpact = "He qua HAI CHIEU: (a) nguoi dung thuoc BU khac KHONG THAY GI - du lieu cua ho bi chan; (b) du lieu nhom HTC BI LO CHO MOI NGUOI GOI, ke ca qua KENH DOI TAC iDealer. Uu tien cao trong ho so gui nghiep vu/bao mat vi cham kenh ngoai.",
        rbacVariantsSoFar = "Bon bien the: left join mang dieu kien (#B45) | khai ma khong dung (#B46/#B47/#B50/#B52/#B53) | comment trong 'on' (#B70) | THAY BANG HANG CUNG (#B84). Doi chung LANH: #B78, #B82.",
        wrapperNote = "iDealer_Mst_CarDrvTest_Get_New20190215 CHI LA VO, goi thang Mst_CarDrvTest_GetX (Biz.HTC.WH.cs:185081) - KENH DOI TAC DUNG LAI NGUYEN TRUY VAN NOI BO.",
        whereClauseNote = "Nguon nhan strFt_WhereClause ghep THANG vao 'where'. Port KHONG nhan where-clause tho tu client.",
        pagingNote = "MyCount dem TRUOC khi cat trang => tong toan bo, khong phai so dong cua trang."
    });
}).RequireAuthorization();

// ===== #B86 TỰ SINH CÔNG VĂN GIA HẠN BẢO LÃNH — `Pmt_GrtClaimExt_GenAutoX_New20201210` =====
// Trace LIVE: WS `Pmt_GrtClaimExt_GenAuto` (`WSHTC.asmx.cs:82383`) →
//   `_biz.Pmt_GrtClaimExt_GenAuto_New20201210` (`Biz.HTC.PaymentGrtExt.cs:3072`) →
//   **`Pmt_GrtClaimExt_GenAutoX_New20201210`** (`:2774`).
//   ⚠️ Ngay tại lời gọi WS còn dấu vết bản cũ bị comment: `…_New20201210(//…_New20200522(` ⇒ bản
//     `_New20200522` **CHẾT**. 3B đo thật, **khớp cả 2 máy**: start=2774 md5 `f999e20e3047024e762262d27e5b4da0`.
// 🔴 **GOM NHÓM THEO CẶP `(DealerCode, BankCode)`** — `select distinct t.DealerCode, t.BankCode`
//    (`:2933-2938`) rồi lặp từng cặp. ⇒ **một công văn cho MỖI cặp (đại lý, ngân hàng)**:
//      · KHÔNG phải một công văn cho cả lô xe;
//      · KHÔNG phải một công văn cho mỗi xe.
//    Port gom sai khoá là **sinh sai số lượng công văn** — lỗi không lộ ra ở bất kỳ guard nào.
// 🔴 **Số công văn sinh THEO ĐẠI LÝ**: `SequenceGetForGrtClaimExtNo(…, TConst.SequenceTypeDMS
//    .GrtClaimExtNo, **strDealerCode**, …)` — tham số áp chót là **mã đại lý** ⇒ dãy số **riêng cho
//    từng đại lý**, không phải một dãy toàn cục.
//    ⚠️ Ngay trên đó, hai cách sinh cũ **bị comment**: `Seq_Common_MyGet(…)` và
//      `string.Format("{0}{1}{2}", yyMM, "GRTCEXTNO", …)`. Port theo dòng ACTIVE.
// 🔴 **TÁI DÙNG CHÍNH HÀM LƯU THỦ CÔNG**: mỗi nhóm gọi `Pmt_GrtClaimExt_SaveX_New20201210(…,
//    objFlagIsDelete = "0", …)` với danh sách xe **của riêng nhóm đó** (`where DealerCode = @… and
//    BankCode = @…`). ⇒ tự sinh **không có đường ghi riêng**; mọi guard của luồng thủ công vẫn áp dụng.
// 🔴 **`NumberOfGuaranteeExt` / `Remark` / `FlagisHTC` là THAM SỐ CẤP LÔ**, truyền thẳng xuống mọi
//    nhóm — **mặc dù bảng đầu vào CÓ cột `NumberOfGuaranteeExt` riêng cho từng xe**
//    (`MyBuildDBDT_Common` mang nó vào `#input_Car_Car`, `:2890`). Cột theo dòng **bị tham số cấp lô
//    ghi đè**. Đây là bất nhất CÓ THẬT của nguồn — port giữ nguyên, ghi ở `perRowVsBatchNote`.
// 🔴 **DÒNG ACTIVE vs COMMENT — cả khối kiểm bảo lãnh BỊ TẮT**: trong `#input_Car_Car_Full`, ba
//    `left join` **bị comment** (`Pmt_GuaranteeDetail` + điều kiện `GuaranteeDetailStatus not in
//    ('R','C')`, `Pmt_Guarantee` + `GuaranteeStatus not in ('R','C')`, và `Mst_CarInvoice`)
//    (`:2921-2932`). Dòng đang chạy chỉ còn `left join Car_VIN` rồi `left join Car_Car`.
//    ⇒ **tự sinh KHÔNG kiểm trạng thái bảo lãnh**: xe có bảo lãnh đã huỷ/từ chối vẫn được gom vào.
//    Hành vi THẬT; **không tự thêm điều kiện**, chỉ đo và báo.
// 🔴 Đầu vào là **BẢNG `Car_Car`**: thiếu ⇒ `…_Input_Car_CarTblNotFound`; **rỗng ⇒ BỊ TỪ CHỐI**
//    (`…_Input_Car_CarTblInvalid`) — cùng khuôn #B82, khác #B76.
// 📌 NỢ: `BankCode` **không có** trên `GrtClaimExt` của MiniHTC (chỉ có ở dòng xe nếu client gửi).
//    Vì nó là **một nửa khoá gom nhóm**, port nhận `bankCode` **theo từng xe trong body** và ghi rõ;
//    KHÔNG suy từ bảo lãnh (tầng `Pmt_Guarantee` chưa đủ) — xem `bankCodeDebt`.
app.MapPost("/api/grtclaimexts/gen-auto", async (
    GrtClaimExtGenAutoDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    if (dto.Cars is null)
        return Results.BadRequest(new { error = "Pmt_GrtClaimExt_GenAuto_Input_Car_CarTblNotFound" });
    var rows = dto.Cars.Where(c => !string.IsNullOrWhiteSpace(c.VIN)).ToList();
    if (rows.Count == 0)
        return Results.BadRequest(new { error = "Pmt_GrtClaimExt_GenAuto_Input_Car_CarTblInvalid" });

    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;

    // `#input_Car_Car_Full`: dòng ACTIVE chỉ `left join Car_VIN` rồi `left join Car_Car`
    // (khối kiểm bảo lãnh đã bị comment ở nguồn).
    var vins = rows.Select(r => (r.VIN ?? "").Trim().ToUpperInvariant()).ToHashSet();
    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && vins.Contains(c.VIN))
        .Select(c => new { c.VIN, c.DealerCode }).ToListAsync();
    var dealerByVin = cars.ToDictionary(c => c.VIN, c => c.DealerCode);
    var noCarRow = rows.Count(r => !dealerByVin.ContainsKey((r.VIN ?? "").Trim().ToUpperInvariant()));

    // 🔴 Gom nhóm theo CẶP (DealerCode, BankCode) — `select distinct`.
    var enriched = rows.Select(r =>
    {
        var vin = (r.VIN ?? "").Trim().ToUpperInvariant();
        dealerByVin.TryGetValue(vin, out var dcFromCar);
        return new
        {
            VIN = vin,
            CarId = (r.CarId ?? "").Trim(),
            DealerCode = (string.IsNullOrWhiteSpace(r.DealerCode) ? dcFromCar : r.DealerCode.Trim().ToUpperInvariant()) ?? "",
            BankCode = (r.BankCode ?? "").Trim().ToUpperInvariant(),
            GuaranteeNo = (r.GuaranteeNo ?? "").Trim()
        };
    }).ToList();

    var groups = enriched.GroupBy(x => (x.DealerCode, x.BankCode))
        .OrderBy(g => g.Key.DealerCode, StringComparer.Ordinal)
        .ThenBy(g => g.Key.BankCode, StringComparer.Ordinal).ToList();

    var created = new List<object>();
    foreach (var g in groups)
    {
        // 🔴 Dãy số RIÊNG theo đại lý (tham số áp chót của SequenceGetForGrtClaimExtNo là DealerCode).
        var seqPrefix = $"{now:yyMM}GRTCEXT{g.Key.DealerCode}";
        var used = await db.GrtClaimExts
            .Where(x => x.OrgId == t.OrgId && x.GrtClaimExtNo.StartsWith(seqPrefix)).CountAsync();
        var no = $"{seqPrefix}{(used + 1):D4}";

        var head = new GrtClaimExt
        {
            OrgId = t.OrgId,
            GrtClaimExtNo = no,
            DealerCode = g.Key.DealerCode,
            // 🔴 Tham số CẤP LÔ ghi đè cột theo dòng.
            NumberOfGuaranteeExt = dto.NumberOfGuaranteeExt <= 0 ? 1 : dto.NumberOfGuaranteeExt,
            TotalCarNoStart = g.Count(),
            SignStatus = "P",
            Remark = dto.Remark,
            CreatedBy = by,
            LogLUDateTime = now, LogLUBy = by
        };
        db.GrtClaimExts.Add(head);
        await db.SaveChangesAsync();

        foreach (var c in g)
            db.GrtClaimExtCars.Add(new GrtClaimExtCar
            {
                OrgId = t.OrgId, GrtClaimExtId = head.Id,
                CarId = c.CarId, VIN = c.VIN, GuaranteeNo = c.GuaranteeNo,
                SignStatusDtl = "P", LogLUDateTime = now, LogLUBy = by
            });
        await db.SaveChangesAsync();

        created.Add(new { grtClaimExtNo = no, dealerCode = g.Key.DealerCode, bankCode = g.Key.BankCode, carCount = g.Count() });
    }

    return Results.Ok(new
    {
        inputCars = rows.Count,
        groupCount = groups.Count,
        created,
        noCarRow,
        numberOfGuaranteeExt = dto.NumberOfGuaranteeExt,
        remark = dto.Remark,
        flagIsHTC = dto.FlagisHTC,
        groupingNote = "GOM NHOM THEO CAP (DealerCode, BankCode) - 'select distinct t.DealerCode, t.BankCode' roi lap tung cap => MOT cong van cho MOI cap (dai ly, ngan hang). KHONG phai mot cong van cho ca lo, cung KHONG phai mot cong van moi xe. Gom sai khoa la SINH SAI SO LUONG cong van - loi khong lo ra o bat ky guard nao.",
        sequenceNote = "So cong van sinh THEO DAI LY: SequenceGetForGrtClaimExtNo(..., SequenceTypeDMS.GrtClaimExtNo, strDealerCode, ...) - tham so ap chot la MA DAI LY => day so RIENG cho tung dai ly, khong phai mot day toan cuc. Hai cach sinh cu (Seq_Common_MyGet va string.Format yyMM+GRTCEXTNO) DA BI COMMENT.",
        reuseSaveNote = "TAI DUNG CHINH HAM LUU THU CONG: moi nhom goi Pmt_GrtClaimExt_SaveX_New20201210(..., objFlagIsDelete='0', ...) voi danh sach xe CUA RIENG NHOM DO. Tu sinh KHONG co duong ghi rieng; moi guard cua luong thu cong van ap dung.",
        perRowVsBatchNote = "NumberOfGuaranteeExt / Remark / FlagisHTC la THAM SO CAP LO, truyen thang xuong moi nhom - MAC DU bang dau vao CO cot NumberOfGuaranteeExt rieng cho tung xe (MyBuildDBDT_Common mang no vao #input_Car_Car). Cot theo dong BI THAM SO CAP LO GHI DE. Bat nhat CO THAT cua nguon - port giu nguyen.",
        guaranteeCheckDisabledNote = "DONG ACTIVE vs COMMENT: trong #input_Car_Car_Full, BA left join BI COMMENT - Pmt_GuaranteeDetail (+ GuaranteeDetailStatus not in ('R','C')), Pmt_Guarantee (+ GuaranteeStatus not in ('R','C')) va Mst_CarInvoice. Dong dang chay chi con left join Car_VIN roi left join Car_Car => TU SINH KHONG KIEM TRANG THAI BAO LANH: xe co bao lanh da huy/tu choi VAN duoc gom vao. Hanh vi THAT; KHONG tu them dieu kien.",
        emptyInputNote = "Dau vao la BANG Car_Car: thieu => Input_Car_CarTblNotFound; RONG => BI TU CHOI (Input_Car_CarTblInvalid). Cung khuon #B82, khac #B76.",
        deadVersionNote = "Ngay tai loi goi WS con dau vet ban cu bi comment: '_New20201210(//_New20200522(' => ban _New20200522 CHET.",
        bankCodeDebt = "NO: BankCode KHONG co tren GrtClaimExt cua MiniHTC (chi co o dong xe neu client gui). Vi no la MOT NUA KHOA GOM NHOM, port nhan bankCode theo TUNG XE trong body. KHONG suy tu bao lanh (tang Pmt_Guarantee chua du)."
    });
}).RequireAuthorization();

// ===== #B87 KIỂM TRƯỚC KHI SỬA DANH MỤC SPEC — `Mst_CarSpecUpdateCheck_New20181115` =====
// Trace LIVE: WS `Mst_CarSpecUpdateCheck` (`WSHTC.asmx.cs:34841`) →
//   **`_biz.Mst_CarSpecUpdateCheck_New20181115`** (`BizHTC.Car.Profile.cs:507`) — **bản DUY NHẤT**
//   trong file (file chỉ có đúng một hàm `public DataSet`).
//   3B đo thật, **khớp cả 2 máy**: start=507 md5 `6a67e7a8456429012fc1507795a34145`.
// ⚠️ **CHỈ KIỂM, KHÔNG GHI** — hàm không có `SaveData`/`update` nào; nó là **cổng chặn chạy TRƯỚC**
//    lệnh sửa spec. Port là endpoint `.../check`, **không** đụng dữ liệu.
// 🔴 **GUARD LÕI CÓ ĐIỀU KIỆN KÉP — rất dễ port thành một vế**:
//      `if (FlagInvoiceFactory_MỚI != FlagInvoiceFactory_CŨ)`
//         `if (đã có VIN dùng SpecCode này) → throw …_VINExist`
//    ⇒ **chỉ chặn khi ĐỔI cờ `FlagInvoiceFactory`** *VÀ* spec **đã phát sinh VIN**.
//    · Sửa các trường **khác** (tên, mô tả…) trên spec đã có VIN ⇒ **VẪN ĐƯỢC**.
//    · Đổi cờ trên spec **chưa có VIN** ⇒ **VẪN ĐƯỢC**.
//    Port thành "spec đã có VIN thì cấm sửa" là **chặt hơn nguồn** (`C0-…quinquagesimussextus`).
// 🔴 Cách nguồn tìm "đã có VIN": `#tbl_Mst_CarSpec_Filter` (theo `SpecCode`) rồi
//    **`INNER JOIN Car_VIN cv ON t.SpecCode = cv.SpecCode`** — dò theo **`Car_VIN.SpecCode`**,
//    KHÔNG phải `ActualSpec`. Hai cột này khác nhau ở nhiều màn khác; đừng dùng lẫn.
// 🔴 **Khoá trùng TRONG LÔ**: nguồn dựng `strKeyDetail = "|" + SpecCode + "|"` và ném
//    `…_DuplicateKeyDetail` nếu lặp — kiểm **trùng trong chính danh sách gửi lên**, không phải trùng DB.
// 🔴 Spec không tồn tại trong DB ⇒ `…_SpecCodeNotFound`.
// ⚠️ **Lô RỖNG = THÀNH CÔNG, không làm gì**: toàn bộ thân nằm trong
//    `if (Tables.Contains("Mst_CarSpec") && Rows.Count >= 1)`, và nhánh ném
//    `…_TableDetailBeBlank` **đã bị comment** (`:562-566`). Cùng khuôn #B76, **khác** #B82/#B86.
// ⚠️ **Lỗi NHÃN trong nguồn** (ghi nhận, không sửa): khi ném `…_VINExist`, tham số chẩn đoán vẫn
//    đặt tên **`"SpecCodeNotFound"`** (`:645`) — nhãn sai do copy-paste, **giá trị thì đúng**.
//    Port trả cả hai tên để đối chiếu được với log nguồn.
app.MapPost("/api/carspecs/update-check", async (
    List<CarSpecUpdateCheckDto> specs, AppDbContext db, ITenantContext t) =>
{
    // Lô rỗng ⇒ thành công, không làm gì (nhánh ném đã bị comment ở nguồn).
    var rows = (specs ?? new()).Where(s => !string.IsNullOrWhiteSpace(s.SpecCode)).ToList();
    if (rows.Count == 0)
        return Results.Ok(new
        {
            checkedCount = 0, ok = true, emptyInputAccepted = true,
            emptyInputNote = "Lo RONG = THANH CONG, khong lam gi: toan bo than nam trong 'if (Tables.Contains(\"Mst_CarSpec\") && Rows.Count >= 1)' va nhanh nem _TableDetailBeBlank DA BI COMMENT (:562-566). Cung khuon #B76, KHAC #B82/#B86."
        });

    var seen = new HashSet<string>(StringComparer.Ordinal);
    var results = new List<object>();

    foreach (var (s, i) in rows.Select((s, i) => (s, i)))
    {
        var specCode = (s.SpecCode ?? "").Trim();
        // 🔴 Trùng khoá TRONG LÔ (không phải trùng DB).
        var keyDetail = $"|{specCode}|";
        if (!seen.Add(keyDetail))
            return Results.BadRequest(new
            {
                error = "Mst_CarSpecUpdateCheck_DuplicateKeyDetail",
                check = new { Mst_CarSpec_Idx = i, strKeyDetail = keyDetail }
            });

        var dbSpec = await db.CarSpecs
            .FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SpecCode == specCode);
        if (dbSpec is null)
            return Results.BadRequest(new
            {
                error = "Mst_CarSpecUpdateCheck_SpecCodeNotFound",
                check = new { Mst_CarSpec_Idx = i, SpecCodeNotFound = specCode }
            });

        var flagNew = (s.FlagInvoiceFactory ?? "").Trim();
        var flagOld = (dbSpec.FlagInvoiceFactory ?? "").Trim();

        // 🔴 CHỈ dò VIN khi cờ THAY ĐỔI — điều kiện kép.
        string? vinExist = null;
        if (flagNew != flagOld)
        {
            // `INNER JOIN Car_VIN cv ON t.SpecCode = cv.SpecCode` — theo `SpecCode`, KHÔNG phải `ActualSpec`.
            vinExist = await db.CarVinMasters
                .Where(v => v.OrgId == t.OrgId && v.SpecCode == specCode)
                .Select(v => v.VIN).FirstOrDefaultAsync();
            if (vinExist is not null)
                return Results.BadRequest(new
                {
                    error = "Mst_CarSpecUpdateCheck_VINExist",
                    check = new
                    {
                        Mst_CarSpec_Idx = i,
                        // ⚠️ Nguồn đặt nhãn SAI là "SpecCodeNotFound"; trả cả hai để đối chiếu log nguồn.
                        SpecCodeNotFound = specCode,
                        SpecCode = specCode,
                        VINExist = vinExist
                    },
                    labelQuirk = "Nguon dat nhan tham so chan doan la 'SpecCodeNotFound' ngay trong nhanh nem _VINExist (:645) - NHAN SAI do copy-paste, GIA TRI thi dung. Port tra ca hai ten."
                });
        }

        results.Add(new
        {
            idx = i, specCode,
            flagInvoiceFactoryOld = flagOld, flagInvoiceFactoryNew = flagNew,
            flagChanged = flagNew != flagOld,
            vinChecked = flagNew != flagOld,
            ok = true
        });
    }

    return Results.Ok(new
    {
        checkedCount = results.Count, ok = true, items = results,
        readOnlyNote = "CHI KIEM, KHONG GHI - ham nguon khong co SaveData/update nao; no la CONG CHAN chay TRUOC lenh sua spec.",
        coreGuardNote = "GUARD LOI CO DIEU KIEN KEP: 'if (FlagInvoiceFactory MOI != CU) { if (da co VIN dung SpecCode nay) throw _VINExist }'. => CHI chan khi DOI co FlagInvoiceFactory VA spec DA phat sinh VIN. Sua truong KHAC tren spec da co VIN VAN DUOC; doi co tren spec CHUA co VIN cung VAN DUOC. Port thanh 'spec da co VIN thi cam sua' la CHAT HON NGUON.",
        vinLookupNote = "Cach tim 'da co VIN': #tbl_Mst_CarSpec_Filter theo SpecCode roi INNER JOIN Car_VIN cv ON t.SpecCode = cv.SpecCode - do theo Car_VIN.SpecCode, KHONG phai ActualSpec. Hai cot nay khac nhau o nhieu man khac; dung dung lan.",
        duplicateKeyNote = "Khoa trung TRONG LO: nguon dung strKeyDetail = '|' + SpecCode + '|' va nem _DuplicateKeyDetail neu lap - kiem trung trong CHINH DANH SACH GUI LEN, khong phai trung DB."
    });
}).RequireAuthorization();

// ===== #B89 DANH MỤC VÙNG — `Mst_Zone_Get` + `Mst_Zone_Update` =====
// Trace LIVE: WS `:99922` → `_biz.Mst_Zone_Get` (`BizHTC.MasterData.cs:4141`, thân ở
//   **`Mst_Zone_GetX`** `:4265`) · WS `:100001` → `_biz.Mst_Zone_Update` (`:4431`).
//   3B đo thật, **khớp cả 2 máy**: `4265/207ad15202991ad10621599e58cc211e` ·
//   `4431/62f7e5d22c9eb3fa63863af1caf6ce4a`.
// 🔴 **`Mst_Zone` là BẢNG DANH MỤC RIÊNG, KHÔNG phải `Mst_DealerZone`**. Port cũ chỉ có bảng **GHÉP**
//    đại lý↔vùng (`/api/dealerzones`) ⇒ **không có nơi khai báo vùng**, mọi `ZoneCode` trên toàn hệ
//    thống là **chuỗi tự do** không đối chiếu được. Đã thêm entity + bảng ở §12.
//    ⚠️ Nhiều báo cáo phiên B (#B70/#B72/#B78…) lọc theo `Mst_DealerZone.FlagActive` — đó là cờ của
//      **bản GHÉP**, khác `Mst_Zone.FlagActive` (cờ của **chính vùng**). Hai cờ độc lập.
// 🔴 **`Mst_Zone_Update` CHỈ đổi được `FlagActive`** — `zzB_Update_Mst_Zone_ClauseSet_zzE` chỉ có
//    `LogLUDTime`, `LogLUBy`, **`FlagActive`** (`:4657-4660`). **Không** sửa được `ZoneName`, và
//    **không** có đường THÊM/XOÁ vùng qua WS này ⇒ vùng phải được tạo bằng con đường khác.
//    Port đúng phạm vi đó: endpoint là **toggle**, không phải upsert.
// ⚠️ **Tên cột dấu vết là `LogLUDTime`** (KHÔNG có "ate") — khác `LogLUDateTime` dùng ở hầu hết bảng
//    khác của 2010.HTC. Giữ đúng tên nguồn để đối chiếu dữ liệu thật về sau.
// 🔴 Nguồn ghi **cả `_dbMain` và `_dbWH`** (hai lần `MyBuildDBDT_Common` + cùng một câu update).
// 🔴 `Mst_Zone_CheckDB(…, TConst.Flag.Yes, **""**, …)` — vùng **phải tồn tại**, nhưng tham số
//    `strFlagActiveListToCheck` truyền **chuỗi RỖNG** ⇒ **cố ý KHÔNG kiểm** vùng đang bật hay tắt
//    (nếu không thì không bao giờ bật lại được vùng đã tắt). Xem `C0-…sexagesimusprimus`.
// 🔴 Phân trang khuôn chung: `identity(bigint, 0, 1) MyIdxSeq` + `select Count(0) MyCount` **TRƯỚC**
//    khi cắt trang; nguồn `order by mz.ZoneCode asc`.
app.MapGet("/api/zones", async (
    AppDbContext db, ITenantContext t, int? recordStart, int? recordCount, string? zoneCode, string? flagActive) =>
{
    var start = Math.Max(0, recordStart ?? 0);
    var count = Math.Clamp(recordCount ?? 200, 1, 1000);
    var q = db.MstZones.Where(z => z.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(zoneCode)) q = q.Where(z => z.ZoneCode.Contains(zoneCode.Trim()));
    if (!string.IsNullOrWhiteSpace(flagActive)) q = q.Where(z => z.FlagActive == flagActive.Trim());
    var all = await q.OrderBy(z => z.ZoneCode).ToListAsync();     // `order by mz.ZoneCode asc`
    var myCount = all.Count;                                       // `MyCount` đếm TRƯỚC khi cắt trang
    var items = all.Skip(start).Take(count).Select(z => new
    {
        mzZoneCode = z.ZoneCode, mzZoneName = z.ZoneName, mzFlagActive = z.FlagActive,
        mzLogLUDTime = z.LogLUDTime, mzLogLUBy = z.LogLUBy
    }).ToList();
    return Results.Ok(new
    {
        myCount, recordStart = start, recordCount = count, count = items.Count, items,
        tableNote = "Mst_Zone la BANG DANH MUC RIENG, KHONG phai Mst_DealerZone (bang GHEP dai ly<->vung). Port cu chi co bang ghep => khong co noi khai bao vung, moi ZoneCode la chuoi tu do.",
        twoFlagsNote = "Nhieu bao cao (#B70/#B72/#B78...) loc theo Mst_DealerZone.FlagActive - do la co cua BAN GHEP, KHAC Mst_Zone.FlagActive (co cua CHINH VUNG). Hai co DOC LAP.",
        columnNameQuirk = "Cot dau vet ten la LogLUDTime (KHONG co 'ate') - khac LogLUDateTime dung o hau het bang khac cua 2010.HTC.",
        pagingNote = "identity(bigint,0,1) MyIdxSeq + 'select Count(0) MyCount' TRUOC khi cat trang; nguon order by mz.ZoneCode asc."
    });
}).RequireAuthorization();

// ===== #B96 HAI DANH MỤC HỆ THỐNG — `SysGetPartner` + `SysGetObjectType` =====
// Trace LIVE: WS → `_biz.SysGetPartner_New20181115` (`BizHTC.System.cs:807`) và
//   `_biz.SysGetObjectType_New20181115` (`:927`). 3B đo thật, **khớp cả 2 máy**:
//   `807/55047c83c310ec5e935ea54589d43b00` · `927/b0bf9b3e38733915e9b88eb38a43a49f`.
// 🔴 **`BuildClauseConditionList(…, "|")` — DẤU NGĂN LÀ ỐNG `|`, KHÔNG PHẢI DẤU PHẨY.**
//    Cả hai hàm truyền tham số thứ tư là `"|"`. Client gửi `"A,B"` sẽ được hiểu là **MỘT mã**
//    tên `"A,B"` ⇒ trả về **rỗng**, không báo lỗi. Port nhận **cả hai** dấu ngăn và ghi rõ.
// 🔴 **`Sys_ObjectType` là BẢNG, không phải hằng**: port cũ để **CỨNG trong C#**
//    (`string[] SysObjectTypes = { "WS", "WSFUNC", "APP", "MENU", "SCR", "BTN" }`) ⇒ **mất cột
//    `ObjectTypeName`** (tên hiển thị cho người dùng) và **không thêm/bớt loại được**.
//    Đã thêm entity `SysObjectTypeMst` (§12); mảng cứng **giữ lại** làm giá trị mặc định khi bảng rỗng,
//    để không phá màn phân quyền đang chạy — trả cờ `fallbackToHardCoded` cho biết đang dùng bản nào.
// 🔴 `Sys_Partner` cũng chưa có ⇒ `PartnerCode` (tham số **bắt buộc của MỌI lời gọi WS** 2010.HTC)
//    là chuỗi tự do không đối chiếu được. Đã thêm entity `SysPartner`.
// ✅ Hai hàm **không có RBAC nào** — danh mục hệ thống, đọc chung; đây là **thiết kế** chứ không phải
//    điều kiện bị bỏ quên (phân biệt theo `C0-…quinquagesimus`).
app.MapGet("/api/syspartners", async (AppDbContext db, ITenantContext t, string? partnerCodeList) =>
{
    var q = db.SysPartners.Where(p => p.OrgId == t.OrgId);
    var codes = SplitConditionList(partnerCodeList);
    if (codes.Count > 0) q = q.Where(p => codes.Contains(p.PartnerCode));
    var items = await q.OrderBy(p => p.PartnerCode)
        .Select(p => new { tPartnerCode = p.PartnerCode, tPartnerName = p.PartnerName }).ToListAsync();
    return Results.Ok(new
    {
        count = items.Count, items,
        separatorNote = "BuildClauseConditionList(..., '|') - DAU NGAN LA ONG '|', KHONG PHAI DAU PHAY. Client gui 'A,B' se duoc hieu la MOT ma ten 'A,B' => tra ve RONG, khong bao loi. Port nhan CA HAI dau ngan.",
        tableNote = "Sys_Partner chua co trong port cu => PartnerCode (tham so BAT BUOC cua MOI loi goi WS 2010.HTC) la chuoi tu do khong doi chieu duoc. Da them entity SysPartner.",
        rbacNote = "Ham KHONG co RBAC nao - danh muc he thong, doc chung. Day la THIET KE, khong phai dieu kien bi bo quen (C0-...quinquagesimus)."
    });
}).RequireAuthorization();

// ===== #B101 TRA KHÁCH HÀNG ĐẠI LÝ — KÊNH `OS_` — `OS_DLS_DealerCustomer_Get` =====
// Trace LIVE: WS → **`_biz.OS_DLS_DealerCustomer_Get`** (`BizHTC.DealerSales.cs:1260`).
//   3B đo thật, **khớp cả 2 máy**: start=1260 md5 `f01a6eaa3af03ca8295bab10bc11b303`.
// 🔴🔴🔴 **LỖ HỔNG RBAC — BIẾN THỂ THỨ NĂM, NẶNG NHẤT CỦA CẢ PHIÊN B:
//    `@strBUPatternOfUser` ĐƯỢC DỰNG TỪ THAM SỐ DO CHÍNH CLIENT GỬI LÊN.**
//    `BizHTC.DealerSales.cs:1332-1346`:
//      `if (strDealerCodeConditionList != null && != "" && != "HTC")`
//          `strBUPatternGet = "HTC." + **strDealerCodeConditionList** + "%";`
//      `if (strDealerCodeConditionList == "HTC" || == null || == "")`
//          `strBUPatternGet = **"HTC%"**;`
//      `alParamsCoupleSql.AddRange(new object[] { "@strBUPatternOfUser", strBUPatternGet`
//          `//**drAbilityOfUser["BUPattern"]** //HTC.VC006 % });`  ← quyền THẬT bị comment tại chỗ bind
//    rồi dùng nguyên trong `inner join Mst_Dealer md on … and (md.BUCode like @strBUPatternOfUser)`
//    — **kèm đúng chú thích** *"Must inner join to filter AbilityOfUser"*.
//    ⇒ **CLIENT TỰ CHỌN PHẠM VI DỮ LIỆU MÌNH ĐƯỢC XEM**: gửi `dealerCode` rỗng / `"HTC"` ⇒ pattern
//      thành **`"HTC%"`** = **TOÀN BỘ khách hàng của MỌI đại lý nhóm HTC**.
//    ⚠️ Nặng hơn #B84 (hằng cứng `'HTC%'`): ở #B84 phạm vi **sai nhưng CỐ ĐỊNH**; ở đây phạm vi
//      **do client điều khiển**. Và tiền tố **`OS_`** cho thấy đây là **kênh ngoài**.
//    📌 **XẾP ƯU TIÊN SỐ 1** trong hồ sơ gửi nghiệp vụ/bảo mật, trên cả #B84.
//    Port **giữ đúng hành vi nguồn** (để đối chiếu số liệu) nhưng: trả `buPatternApplied` +
//    `buPatternFromClient = true`, và mở cờ **`enforceBuScope=1`** để ép về phạm vi thật khi cần.
//    **KHÔNG tự bịt** — quyết định là của nghiệp vụ/bảo mật.
// 🔴 `GenderText` là cột **SUY RA trong SQL**: `case when Gender='0' then N'Nam' when '1' then N'Nữ' end`
//    — **KHÔNG có nhánh `else`** ⇒ giá trị khác "0"/"1" (kể cả NULL) ⇒ **`GenderText` = NULL**.
// 🔴 `left join Mst_District` nối bằng **CẶP `(DistrictCode, ProvinceCode)`**, không chỉ mã huyện —
//    mã huyện của 2010.HTC **không duy nhất toàn quốc**.
// 🔴 Phân trang: `MyRowIdx_Start = nResultRecordStart + 1` — nguồn ghi rõ *"C# based from 0 but
//    SqlIdx based from 1"*; `MyCount` đếm **TRƯỚC** khi cắt trang.
app.MapGet("/api/os/dealercustomers", async (
    AppDbContext db, ITenantContext t,
    string? dealerCode, string? fullNamePattern, string? phoneNoPattern,
    int? recordStart, int? recordCount, string? enforceBuScope, string? buPatternOfUser) =>
{
    var start = Math.Max(0, recordStart ?? 0);
    var count = Math.Clamp(recordCount ?? 200, 1, 1000);

    // 🔴 Dựng pattern ĐÚNG như nguồn — từ tham số CLIENT.
    var dlrParam = (dealerCode ?? "").Trim();
    var buPatternFromClient = (dlrParam.Length == 0 || dlrParam.Equals("HTC", StringComparison.OrdinalIgnoreCase))
        ? "HTC%"
        : "HTC." + dlrParam + "%";
    // Phạm vi THẬT của người dùng (nguồn đã comment) — chỉ dùng khi bật cờ.
    var realPattern = (buPatternOfUser ?? "").Trim();
    var applied = (enforceBuScope == "1" && realPattern.Length > 0) ? realPattern : buPatternFromClient;
    var prefix = applied.TrimEnd('%').ToUpperInvariant();

    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId)
        .Select(d => new { d.DealerCode, d.BUCode }).ToListAsync();
    // `inner join Mst_Dealer md … and (md.BUCode like @strBUPatternOfUser)` — inner join, loại thẳng.
    var inScope = dealers.Where(d => (d.BUCode ?? "").ToUpperInvariant().StartsWith(prefix))
        .Select(d => d.DealerCode).ToHashSet();

    var all = await db.DealerCustomers.Where(c => c.OrgId == t.OrgId).ToListAsync();
    var beforeScope = all.Count;
    all = all.Where(c => inScope.Contains(c.DealerCode)).ToList();
    var droppedOutOfScope = beforeScope - all.Count;

    if (!string.IsNullOrWhiteSpace(fullNamePattern))
        all = all.Where(c => (c.FullName ?? "").Contains(fullNamePattern.Trim(), StringComparison.OrdinalIgnoreCase)).ToList();
    if (!string.IsNullOrWhiteSpace(phoneNoPattern))
        all = all.Where(c => (c.PhoneNo ?? "").Contains(phoneNoPattern.Trim(), StringComparison.OrdinalIgnoreCase)).ToList();

    var myCount = all.Count;                        // `MyCount` đếm TRƯỚC khi cắt trang
    var page = all.OrderBy(c => c.CustomerCode, StringComparer.Ordinal).Skip(start).Take(count).ToList();

    var provinces = (await db.Masters.Where(m => m.OrgId == t.OrgId && m.Category == "Province")
        .Select(m => new { m.Code, m.Name, m.ParentCode }).ToListAsync())
        .GroupBy(p => p.Code).ToDictionary(g => g.Key!, g => g.First());
    // `left join Mst_District` theo CẶP (DistrictCode, ProvinceCode).
    var districts = (await db.Masters.Where(m => m.OrgId == t.OrgId && m.Category == "District")
        .Select(m => new { m.Code, m.Name, m.ParentCode }).ToListAsync())
        .GroupBy(d => (d.Code ?? "", d.ParentCode ?? "")).ToDictionary(g => g.Key, g => g.First());

    var items = page.Select(c =>
    {
        provinces.TryGetValue(c.ProvinceCode ?? "", out var mp);
        districts.TryGetValue((c.DistrictCode ?? "", c.ProvinceCode ?? ""), out var md);
        return new
        {
            dlsdcCustomerCode = c.CustomerCode, dlsdcDealerCode = c.DealerCode,
            dlsdcFullName = c.FullName, dlsdcFullNameEN = c.FullNameEN,
            dlsdcAddress = c.Address, dlsdcPhoneNo = c.PhoneNo, dlsdcEmail = c.Email,
            dlsdcTaxCode = c.TaxCode, dlsdcGender = c.Gender,
            // 🔴 `case … end` KHÔNG có `else` ⇒ giá trị khác "0"/"1" (kể cả NULL) ⇒ NULL.
            GenderText = c.Gender == "0" ? "Nam" : c.Gender == "1" ? "Nữ" : null,
            mp_AreaCode = mp?.ParentCode, mp_ProvinceCode = mp?.Code, mp_ProvinceName = mp?.Name,
            md_DistrictCode = md?.Code, md_DistrictName = md?.Name
        };
    }).ToList();

    return Results.Ok(new
    {
        myCount, recordStart = start, recordCount = count, count = items.Count, items,
        buPatternApplied = applied,
        buPatternFromClient,
        buPatternIsClientControlled = enforceBuScope != "1",
        droppedOutOfScope,
        rbacHoleVariant5 = "LO HONG RBAC - BIEN THE THU NAM, NANG NHAT CUA CA PHIEN B: @strBUPatternOfUser DUOC DUNG TU THAM SO DO CHINH CLIENT GUI LEN (BizHTC.DealerSales.cs:1332-1346). Neu strDealerCodeConditionList khac rong/khac 'HTC' => pattern = 'HTC.' + <gia tri client> + '%'; neu rong hoac 'HTC' => pattern = 'HTC%'. Dong lay quyen that drAbilityOfUser['BUPattern'] BI COMMENT NGAY TAI CHO BIND. Sau do dung nguyen trong inner join Mst_Dealer ... and (md.BUCode like @strBUPatternOfUser), KEM DUNG chu thich 'Must inner join to filter AbilityOfUser'.",
        rbacImpact = "CLIENT TU CHON PHAM VI DU LIEU MINH DUOC XEM: gui dealerCode rong hoac 'HTC' => thay TOAN BO khach hang cua MOI dai ly nhom HTC. NANG HON #B84: o #B84 pham vi SAI nhung CO DINH; o day pham vi DO CLIENT DIEU KHIEN. Tien to 'OS_' cho thay day la KENH NGOAI. => XEP UU TIEN SO 1 trong ho so gui nghiep vu/bao mat, tren ca #B84.",
        rbacPortNote = "Port GIU DUNG hanh vi nguon de doi chieu so lieu; mo co enforceBuScope=1 (kem buPatternOfUser) de ep ve pham vi that khi nghiep vu quyet dinh. KHONG tu bit.",
        genderTextNote = "GenderText la cot SUY RA trong SQL: case when Gender='0' then N'Nam' when '1' then N'Nu' end - KHONG co nhanh else => gia tri khac '0'/'1' (ke ca NULL) => GenderText = NULL.",
        districtJoinNote = "left join Mst_District noi bang CAP (DistrictCode, ProvinceCode), khong chi ma huyen - ma huyen cua 2010.HTC KHONG duy nhat toan quoc.",
        pagingNote = "MyRowIdx_Start = nResultRecordStart + 1 - nguon ghi ro 'C# based from 0 but SqlIdx based from 1'; MyCount dem TRUOC khi cat trang."
    });
}).RequireAuthorization();

// ===== #B102 BÁO CÁO SSI CHO ĐỐI TÁC BẢO HIỂM — `RptSSI_ICIC_New2011119` =====
// Trace LIVE: WS → **`_biz.RptSSI_ICIC_New2011119`** (`BizHTC.DealerSales.cs:6504`).
//   ⚠️ Hậu tố **`_New2011119`** — **9 chữ số**, thiếu/thừa so với khuôn `_NewYYYYMMDD` (8).
//     Giữ nguyên khi tra cứu (cùng loại quirk với `_New2021601` ở #B71).
//   3B đo thật, **khớp cả 2 máy**: start=6504 md5 `2c7ed5b6f621da6bd77342f43a9fd213`.
// 🔴🔴 **RBAC — biến thể 4 (HẰNG CỨNG), KÊNH ĐỐI TÁC BẢO HIỂM `ICIC`** (`:6573`):
//    `alParamsCoupleSql.AddRange(new object[] { "@strBUPatternOfUser", **"HTC%"** });`
//    rồi `inner join Mst_Dealer md … and (md.BUCode like @strBUPatternOfUser)` **kèm đúng** chú thích
//    *"Must inner join to filter AbilityOfUser"*. ⇒ quyền thật của người gọi **không hề được dùng**;
//    đối tác bảo hiểm nhận **toàn bộ nhóm HTC**. Cùng khuôn #B84, **ca thứ 17**.
// 🔴 **BA điều kiện lọc VIẾT CỨNG trong `where`** (nghiệp vụ, không phải tham số):
//    · `dd.DealerCodeBuyer is null` — chú thích nguồn: *"Không tính giao dịch bán ngang 20170703"*;
//    · `dd.FlagInitDeal = '0'`;
//    · ⚠️ `-- and dd.CtmCareFlag = '1'` **ĐÃ BỊ COMMENT**, kèm giải thích dài: *"Báo cáo SSI: hiện
//      nay dữ liệu chỉ hiển thị các kiểm chứng trạng thái A → yêu cầu: dữ liệu hiển thị **cả** các
//      kiểm chứng trạng thái P"* ⇒ **cố ý nới**, port thêm lại điều kiện này là **chặt hơn nguồn**.
// 🔴 **BA VAI KHÁCH HÀNG tách riêng**, mỗi vai một `left join DLS_DealerCustomer` + một
//    `left join Mst_Province`: **Buyer** (sở hữu) · **Holder** (giao dịch) · **Driver** (quản lý xe).
//    Bí danh có tiền tố `dlsdc_Buyer_` / `_Holder_` / `_Driver_` để không đè nhau (khuôn #B93/#B97).
// 🔴 **`dlsd_Previous`** — `left join DLS_Deal on ddd.DealNoPrevious = dlsd_Previous.DealNo`:
//    trả **đại lý NGUỒN** (`DLSDPDealerCode`) bên cạnh **đại lý kiểm chứng** (`dd.DealerCode`).
//    Hai cột đại lý khác nhau trong cùng một dòng — đừng gộp.
// 🔴 `ColorName = ColorExtNameVN + '/' + ColorIntNameVN` — nối chuỗi SQL: **một vế NULL ⇒ NULL**
//    (cùng bẫy #B94).
// 🔴 Phân trang bằng **`Row_Number() over (order by ddd.DealNo desc)`** (khác `identity(bigint,0,1)`
//    của các hàm khác); `MyRowIdx_Start = start + 1`; `MyCount` đếm **trước** khi cắt trang.
app.MapGet("/api/icic/rpt-ssi", async (
    AppDbContext db, ITenantContext t,
    string? dealerCode, DateTime? deliveryFrom, DateTime? deliveryTo,
    DateTime? ctmCareUpdFrom, DateTime? ctmCareUpdTo,
    int? recordStart, int? recordCount, string? enforceBuScope, string? buPatternOfUser) =>
{
    var start = Math.Max(0, recordStart ?? 0);
    var count = Math.Clamp(recordCount ?? 200, 1, 1000);

    // 🔴 Nguồn ĐÓNG CỨNG "HTC%"; giữ làm mặc định, cho ép phạm vi thật bằng cờ.
    const string Hardcoded = "HTC%";
    var realPattern = (buPatternOfUser ?? "").Trim();
    var applied = (enforceBuScope == "1" && realPattern.Length > 0) ? realPattern : Hardcoded;
    var prefix = applied.TrimEnd('%').ToUpperInvariant();

    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId)
        .Select(d => new { d.DealerCode, d.BUCode }).ToListAsync();
    var inScope = dealers.Where(d => (d.BUCode ?? "").ToUpperInvariant().StartsWith(prefix))
        .Select(d => d.DealerCode).ToHashSet();

    // `#tbl_DLS_DealDetail_Filter` — BA điều kiện viết cứng (một cái đã bị comment ở nguồn).
    var deals = await db.DealerDeals.Where(d => d.OrgId == t.OrgId
            && (d.DealerCodeBuyer == null || d.DealerCodeBuyer == "")   // "Không tính giao dịch bán ngang"
            && d.FlagInitDeal == "0")
        .ToListAsync();
    deals = deals.Where(d => d.DealerCode != null && inScope.Contains(d.DealerCode)).ToList();
    if (!string.IsNullOrWhiteSpace(dealerCode))
        deals = deals.Where(d => d.DealerCode == dealerCode.Trim().ToUpperInvariant()).ToList();
    if (ctmCareUpdFrom is not null) deals = deals.Where(d => d.CtmCareUpdDate >= ctmCareUpdFrom).ToList();
    if (ctmCareUpdTo is not null) deals = deals.Where(d => d.CtmCareUpdDate <= ctmCareUpdTo).ToList();
    var dealById = deals.ToDictionary(d => d.Id);

    var lines = await db.DealerDealDetails.Where(l => l.OrgId == t.OrgId).ToListAsync();
    lines = lines.Where(l => dealById.ContainsKey(l.DealId)).ToList();
    if (deliveryFrom is not null) lines = lines.Where(l => l.DeliveryDate >= deliveryFrom).ToList();
    if (deliveryTo is not null) lines = lines.Where(l => l.DeliveryDate <= deliveryTo).ToList();

    var myCount = lines.Count;                        // `MyCount` đếm TRƯỚC khi cắt trang
    // `Row_Number() over (order by ddd.DealNo desc)`
    var page = lines
        .OrderByDescending(l => dealById[l.DealId].DealNo, StringComparer.Ordinal)
        .Skip(start).Take(count).ToList();

    var vins = page.Select(l => l.CarId).Where(x => x != null).Distinct().ToList()!;
    var cars = (await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && vins.Contains(c.VIN)).ToListAsync())
        .GroupBy(c => c.VIN).ToDictionary(g => g.Key, g => g.First());
    var specs = (await db.CarSpecs.Where(s => s.OrgId == t.OrgId)
        .Select(s => new { s.SpecCode, s.SpecDesc, s.GradeCode }).ToListAsync())
        .GroupBy(s => s.SpecCode).ToDictionary(g => g.Key, g => g.First());
    var colors = (await db.MstCarColors.Where(c => c.OrgId == t.OrgId)
        .Select(c => new { c.ModelCode, c.ColorCode, c.ColorExtNameVN, c.ColorIntNameVN }).ToListAsync())
        .GroupBy(c => (c.ModelCode ?? "", c.ColorCode ?? "")).ToDictionary(g => g.Key, g => g.First());
    var custs = (await db.DealerCustomers.Where(c => c.OrgId == t.OrgId).ToListAsync())
        .GroupBy(c => (c.DealerCode, c.CustomerCode)).ToDictionary(g => g.Key, g => g.First());
    var provinces = (await db.Masters.Where(m => m.OrgId == t.OrgId && m.Category == "Province")
        .Select(m => new { m.Code, m.Name }).ToListAsync())
        .GroupBy(p => p.Code).ToDictionary(g => g.Key!, g => g.First().Name);
    var dealsByNo = (await db.DealerDeals.Where(d => d.OrgId == t.OrgId)
        .Select(d => new { d.DealNo, d.DealerCode, d.DealerCodeBuyer }).ToListAsync())
        .GroupBy(d => d.DealNo).ToDictionary(g => g.Key, g => g.First());

    var items = page.Select(l =>
    {
        var dd = dealById[l.DealId];
        cars.TryGetValue(l.CarId ?? "", out var cv);
        specs.TryGetValue(cv?.SpecCode ?? "", out var mcs);
        colors.TryGetValue((cv?.ModelCode ?? "", cv?.ColorCode ?? ""), out var mcc);
        // 🔴 nối chuỗi SQL: một vế NULL ⇒ CẢ CHUỖI NULL.
        string? colorName = (mcc?.ColorExtNameVN is null || mcc?.ColorIntNameVN is null)
            ? null : mcc.ColorExtNameVN + "/" + mcc.ColorIntNameVN;
        // BA vai khách hàng, mỗi vai một left join.
        custs.TryGetValue((dd.DealerCode ?? "", dd.CustomerCodeBuyer ?? ""), out var buyer);
        custs.TryGetValue((dd.DealerCode ?? "", dd.CustomerCodeHolder ?? ""), out var holder);
        custs.TryGetValue((dd.DealerCode ?? "", dd.CustomerCodeDriver ?? ""), out var driver);
        // `dlsd_Previous` — đại lý NGUỒN, khác đại lý KIỂM CHỨNG.
        dealsByNo.TryGetValue(l.DealNoPrevious ?? "", out var prev);
        return new
        {
            dddDealNo = dd.DealNo, dddCarId = l.CarId, dddDeliveryDate = l.DeliveryDate,
            DLSDPDealerCode = prev?.DealerCode, DLSDPDealerCodeBuyer = prev?.DealerCodeBuyer,
            ddDealerCode = dd.DealerCode, ddDlrContractNo = dd.DlrContractNo, ddSalesType = dd.SalesType,
            ddCtmCareFlag = dd.CtmCareFlag, ddCtmCareUpdDate = dd.CtmCareUpdDate,
            ddCtmCareUpdBy = dd.CtmCareUpdBy, ddCtmCareRemark = dd.CtmCareRemark,
            cvModelCode = cv?.ModelCode, mcsSpecDescription = mcs?.SpecDesc, mcsGradeCode = mcs?.GradeCode,
            mccColorCode = mcc?.ColorCode, ColorName = colorName, cvVIN = cv?.VIN,
            dlsdc_Buyer_FullName = buyer?.FullName, dlsdc_Buyer_PhoneNo = buyer?.PhoneNo,
            dlsdc_Buyer_Address = buyer?.Address, dlsdc_Buyer_ProvinceCode = buyer?.ProvinceCode,
            dlsdc_Buyer_Email = buyer?.Email,
            dlsdc_Holder_FullName = holder?.FullName, dlsdc_Holder_PhoneNo = holder?.PhoneNo,
            dlsdc_Holder_Address = holder?.Address, dlsdc_Holder_ProvinceCode = holder?.ProvinceCode,
            dlsdc_Holder_Email = holder?.Email,
            dlsdc_Driver_FullName = driver?.FullName, dlsdc_Driver_PhoneNo = driver?.PhoneNo,
            dlsdc_Driver_Address = driver?.Address, dlsdc_Driver_ProvinceCode = driver?.ProvinceCode,
            dlsdc_Driver_Email = driver?.Email,
            mp_Buyer_ProvinceName = provinces.TryGetValue(buyer?.ProvinceCode ?? "", out var pb) ? pb : null,
            mp_Holder_ProvinceName = provinces.TryGetValue(holder?.ProvinceCode ?? "", out var ph) ? ph : null,
            mp_Driver_ProvinceName = provinces.TryGetValue(driver?.ProvinceCode ?? "", out var pd) ? pd : null
        };
    }).ToList();

    return Results.Ok(new
    {
        myCount, recordStart = start, recordCount = count, count = items.Count, items,
        buPatternApplied = applied, buPatternHardcoded = Hardcoded,
        rbacHole = "RBAC bien the 4 (HANG CUNG), KENH DOI TAC BAO HIEM ICIC (:6573): alParamsCoupleSql bind '@strBUPatternOfUser' = 'HTC%' roi dung trong inner join Mst_Dealer ... and (md.BUCode like @strBUPatternOfUser), KEM DUNG chu thich 'Must inner join to filter AbilityOfUser'. Quyen that cua nguoi goi KHONG HE duoc dung => doi tac bao hiem nhan TOAN BO nhom HTC. Cung khuon #B84, ca thu 17.",
        hardFiltersNote = "BA dieu kien loc VIET CUNG trong where (nghiep vu, khong phai tham so): dd.DealerCodeBuyer is null ('Khong tinh giao dich ban ngang 20170703') va dd.FlagInitDeal = '0'. Dieu kien thu ba '-- and dd.CtmCareFlag = 1' DA BI COMMENT kem giai thich: 'Bao cao SSI: hien nay du lieu chi hien thi cac kiem chung trang thai A -> yeu cau: du lieu hien thi CA cac kiem chung trang thai P'. => CO Y NOI; port them lai dieu kien nay la CHAT HON NGUON.",
        threeRolesNote = "BA VAI KHACH HANG tach rieng, moi vai mot left join DLS_DealerCustomer + mot left join Mst_Province: Buyer (so huu) | Holder (giao dich) | Driver (quan ly xe). Bi danh co tien to dlsdc_Buyer_/_Holder_/_Driver_ de khong de nhau (khuon #B93/#B97).",
        previousDealNote = "dlsd_Previous: left join DLS_Deal on ddd.DealNoPrevious = dlsd_Previous.DealNo => tra DAI LY NGUON (DLSDPDealerCode) ben canh DAI LY KIEM CHUNG (dd.DealerCode). HAI cot dai ly khac nhau trong cung mot dong - dung gop.",
        nullConcatNote = "ColorName = ColorExtNameVN + '/' + ColorIntNameVN - noi chuoi SQL: MOT VE NULL => CA CHUOI NULL (cung bay #B94).",
        pagingNote = "Phan trang bang Row_Number() over (order by ddd.DealNo desc) - KHAC identity(bigint,0,1) cua cac ham khac; MyRowIdx_Start = start + 1; MyCount dem TRUOC khi cat trang.",
        suffixQuirk = "Hau to _New2011119 co 9 chu so (khuon chuan la 8: _NewYYYYMMDD). Giu nguyen khi tra cuu - cung loai quirk voi _New2021601 o #B71."
    });
}).RequireAuthorization();

// ===== #B103 TÌM KHÁCH HÀNG ĐẠI LÝ — KÊNH BẢO HIỂM `ICIC` =====
//        `DealerSalesDealerCustomerGet_ICIC_New20181115`
// Trace LIVE: WS → `_biz.…_ICIC_New20181115` (`BizHTC.DealerSales.cs:1003`).
//   3B đo thật, **khớp cả 2 máy**: start=1003 md5 `9be5a322a6b719efaf8ffe8d81b1d41c`.
// 🔴🔴 **RBAC — BIẾN THỂ 5 (client điều khiển phạm vi), GIỐNG HỆT #B101** (`:1068-1080`):
//    `dealerCode` khác rỗng/khác `"HTC"` ⇒ pattern = `"HTC." + <giá trị client> + "%"`;
//    rỗng hoặc `"HTC"` ⇒ **`"HTC%"`**; dòng `drAbilityOfUser["BUPattern"]` **bị comment tại chỗ bind**.
//    ⇒ **ca thứ 18**, và là **ca thứ HAI** cùng biến thể 5 — chứng tỏ đây là **khuôn lặp lại**
//      trên các kênh đối tác, không phải sơ suất đơn lẻ. 📌 Cùng mức ưu tiên với #B101.
// 🔴 **`AND (1=2 …)` — HẠT GIỐNG cho chuỗi `OR`, và là guard "CẤM TÌM RỖNG"**:
//    nguồn bọc toàn bộ mệnh đề tìm kiếm trong `AND (1=2  <các clause nối bằng OR> )`.
//      · `1=2` là **hạt giống sai** để các clause sau đều mở đầu bằng `or` mà vẫn hợp lệ cú pháp;
//      · ⇒ **không nhập gì thì `AND (1=2)` ⇒ TRẢ VỀ RỖNG**, **không** phải trả tất cả.
//    Port bỏ hạt giống này ⇒ tìm rỗng trả **toàn bộ khách hàng** — vừa sai nghiệp vụ vừa **khuếch đại**
//    lỗ hổng RBAC ở trên.
// 🔴 **MỘT ô tìm kiếm áp vào CHÍN cột bằng `OR`**: `strDLSDSearchConditonList` được `BuildClause("or",…)`
//    trên `CustomerCode`, `FullName`, `FullNameEN`, `Address`, `PhoneNo`, `TaxCode`, `ProvinceCode`,
//    `CreatedDate`, `CreatedBy`. ⚠️ Kể cả `CreatedDate` — nên gõ chữ vào ô tìm vẫn so với cột ngày.
// 🔴 Phân trang **`Row_Number() over (order by dlsdc.FullName asc)`** — sắp theo **TÊN**, khác #B101
//    (sắp theo mã) và khác #B102 (`DealNo desc`). `MyCount` đếm **trước** khi cắt trang.
app.MapGet("/api/icic/dealercustomers", async (
    AppDbContext db, ITenantContext t,
    string? dealerCode, string? search, int? recordStart, int? recordCount,
    string? enforceBuScope, string? buPatternOfUser) =>
{
    var start = Math.Max(0, recordStart ?? 0);
    var count = Math.Clamp(recordCount ?? 200, 1, 1000);

    // 🔴 Biến thể 5 — pattern dựng TỪ THAM SỐ CLIENT (y hệt #B101).
    var dlrParam = (dealerCode ?? "").Trim();
    var buPatternFromClient = (dlrParam.Length == 0 || dlrParam.Equals("HTC", StringComparison.OrdinalIgnoreCase))
        ? "HTC%" : "HTC." + dlrParam + "%";
    var realPattern = (buPatternOfUser ?? "").Trim();
    var applied = (enforceBuScope == "1" && realPattern.Length > 0) ? realPattern : buPatternFromClient;
    var prefix = applied.TrimEnd('%').ToUpperInvariant();

    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId)
        .Select(d => new { d.DealerCode, d.BUCode }).ToListAsync();
    var inScope = dealers.Where(d => (d.BUCode ?? "").ToUpperInvariant().StartsWith(prefix))
        .Select(d => d.DealerCode).ToHashSet();

    // 🔴 `AND (1=2 …)` — không nhập gì ⇒ TRẢ RỖNG, KHÔNG phải trả tất cả.
    var term = (search ?? "").Trim();
    if (term.Length == 0)
        return Results.Ok(new
        {
            myCount = 0, recordStart = start, recordCount = count, count = 0,
            items = Array.Empty<object>(),
            emptySearchReturnsEmpty = true,
            seedNote = "Nguon boc menh de tim kiem trong 'AND (1=2 <cac clause noi bang OR>)'. '1=2' la HAT GIONG SAI de cac clause sau deu mo dau bang 'or' ma van hop le cu phap => KHONG NHAP GI thi AND (1=2) => TRA VE RONG, khong phai tra tat ca. Port bo hat giong nay se lam tim rong tra TOAN BO khach hang - vua sai nghiep vu vua KHUECH DAI lo hong RBAC.",
            buPatternApplied = applied, buPatternFromClient
        });

    var all = await db.DealerCustomers.Where(c => c.OrgId == t.OrgId).ToListAsync();
    all = all.Where(c => inScope.Contains(c.DealerCode)).ToList();

    // 🔴 MỘT ô tìm áp vào CHÍN cột bằng OR (kể cả CreatedDate/CreatedBy).
    bool Hit(string? s) => s is not null && s.Contains(term, StringComparison.OrdinalIgnoreCase);
    all = all.Where(c =>
        Hit(c.CustomerCode) || Hit(c.FullName) || Hit(c.FullNameEN) || Hit(c.Address)
        || Hit(c.PhoneNo) || Hit(c.TaxCode) || Hit(c.ProvinceCode)
        || Hit(c.CreatedAt.ToString("yyyy-MM-dd")) || Hit(c.CreatedBy)).ToList();

    var myCount = all.Count;                       // `MyCount` đếm TRƯỚC khi cắt trang
    // `Row_Number() over (order by dlsdc.FullName asc)` — sắp theo TÊN.
    var page = all.OrderBy(c => c.FullName, StringComparer.Ordinal).Skip(start).Take(count).ToList();

    var provinces = (await db.Masters.Where(m => m.OrgId == t.OrgId && m.Category == "Province")
        .Select(m => new { m.Code, m.Name, m.ParentCode }).ToListAsync())
        .GroupBy(p => p.Code).ToDictionary(g => g.Key!, g => g.First());

    var items = page.Select(c =>
    {
        provinces.TryGetValue(c.ProvinceCode ?? "", out var mpv);
        return new
        {
            dlsdcCustomerCode = c.CustomerCode, dlsdcDealerCode = c.DealerCode,
            dlsdcFullName = c.FullName, dlsdcFullNameEN = c.FullNameEN,
            dlsdcAddress = c.Address, dlsdcPhoneNo = c.PhoneNo, dlsdcEmail = c.Email,
            dlsdcTaxCode = c.TaxCode, dlsdcProvinceCode = c.ProvinceCode,
            dlsdcCreatedDate = c.CreatedAt, dlsdcCreatedBy = c.CreatedBy,
            MPVProvinceCode = mpv?.Code, MPVAreaCode = mpv?.ParentCode, MPVProvinceName = mpv?.Name
        };
    }).ToList();

    return Results.Ok(new
    {
        myCount, recordStart = start, recordCount = count, count = items.Count, items,
        buPatternApplied = applied, buPatternFromClient,
        buPatternIsClientControlled = enforceBuScope != "1",
        emptySearchReturnsEmpty = false,
        rbacHole = "RBAC BIEN THE 5 (client dieu khien pham vi), GIONG HET #B101 (:1068-1080): dealerCode khac rong/khac 'HTC' => pattern = 'HTC.' + <gia tri client> + '%'; rong hoac 'HTC' => 'HTC%'; dong drAbilityOfUser['BUPattern'] BI COMMENT TAI CHO BIND. CA THU 18, va la CA THU HAI cung bien the 5 => day la KHUON LAP LAI tren cac kenh doi tac, khong phai so suat don le. Cung muc uu tien voi #B101.",
        seedNote = "'AND (1=2 <clause noi bang OR>)' - 1=2 la HAT GIONG SAI de chuoi OR hop le cu phap, DONG THOI la guard CAM TIM RONG: khong nhap gi => tra RONG. Port bo hat giong nay se lam tim rong tra TOAN BO khach hang.",
        searchColumnsNote = "MOT o tim kiem ap vao CHIN cot bang OR: CustomerCode, FullName, FullNameEN, Address, PhoneNo, TaxCode, ProvinceCode, CreatedDate, CreatedBy. Ke ca CreatedDate - go chu vao o tim van so voi cot ngay.",
        pagingNote = "Row_Number() over (order by dlsdc.FullName asc) - sap theo TEN, khac #B101 (theo ma) va #B102 (DealNo desc). MyCount dem TRUOC khi cat trang."
    });
}).RequireAuthorization();

// ===== #B105 TRA LƯỢT LÁI THỬ — KÊNH BẢO HIỂM `ICIC` — `DLR_DriveTest_ICIC` =====
// Trace LIVE: WS → **`_biz.DLR_DriveTest_ICIC`** (`Biz.HTC.WH.cs:182012`), SQL dùng chung
//   `CommonSQLQuery.mySql_DLR_DriveTest_ICIC()` (`:3747`). **Không có hậu tố `_NewYYYYMMDD`**.
//   3B đo thật, **khớp cả 2 máy** (start lệch 182012/182017): md5 `399f2e20e5a0799ddad6ad8b75f8c819`.
// 🔴 **SỬA LẠI KẾT LUẬN CỦA BẢNG QUÉT #B104**: hàm này KHÔNG phải biến thể 4 (hằng cứng) như tôi
//    ghi lúc quét, mà là **BIẾN THỂ 2 — khai mà KHÔNG dùng**:
//      `alParamsCoupleSql.AddRange(new object[] { "@strBUPatternOfUser", "HTC%" });`  ← bind
//      nhưng **`mySql_DLR_DriveTest_ICIC()` KHÔNG hề chứa `@strBUPatternOfUser`** — `inner join
//      Mst_Dealer md` chỉ nối `on md.DealerCode = t.DealerCode`, **không có** `md.BUCode like …`.
//    ⇒ Đúng theo luật đếm của chính mình (`C0-…nonagesimusquartus`): `count = 1` = **chỉ dòng bind**
//      ⇒ biến thể 2. Lúc quét tôi suy từ **giá trị bind** thay vì kiểm **SQL có dùng không** —
//      ghi lại để lượt sau không lặp lại (xem luật `C0-…nonagesimusseptimus`).
//    Hệ quả thực tế: **KHÔNG có bất kỳ lọc phạm vi nào**, kể cả lọc sai — kênh ICIC thấy **mọi đại lý**.
// 🔴 **THỨ THẬT SỰ GIỚI HẠN LỘ DỮ LIỆU LÀ GUARD "CẤM TÌM RỖNG"**, không phải RBAC:
//    `if (IsNullOrEmpty(strPhoneNoConditionList)) throw DLR_DriveTest_ICIC_**Conditon**ListIsEmpty`
//    (⚠️ tên hằng lỗi chính tả **"Conditon"** — giữ nguyên để đối chiếu log), kèm
//    `"ErrDesc", "Điều kiện tìm kiếm trống!"`.
//    ⇒ Đối tác **bắt buộc** phải biết **số điện thoại** mới tra được — đây mới là ranh giới thật.
//      Cùng ý đồ với hạt giống `AND (1=2 …)` ở #B103, nhưng làm bằng **guard ở tầng C#**.
// 🔴 **`inner join DLS_DealerCustomer` ở CẢ HAI bước** (lọc và lấy dữ liệu) ⇒ lượt lái thử **không
//    gắn khách hàng** bị **loại hẳn**. Còn `left join Mst_CarDriverTest` nối bằng **CẶP
//    `(DrvTestPlateNo, DealerCode)`** — biển số xe lái thử **không duy nhất toàn hệ thống**.
// 🔴 Trả **cột trùng tên từ hai bảng**: `mcm.ModelCode` (model của lượt lái thử) **và**
//    `mcdt.ModelCode` (model của **xe** lái thử) — nguồn **không** đổi bí danh ⇒ trong `DataTable`
//    cột sau **đè** cột trước. Port tách rõ `ddtModelCode` / `mcdtModelCode`, ghi ở `dupColumnNote`.
app.MapGet("/api/icic/drivetests", async (
    AppDbContext db, ITenantContext t, string? dealerCode, string? phoneNo) =>
{
    // 🔴 GUARD "CẤM TÌM RỖNG" — ranh giới thật của kênh này.
    var phone = (phoneNo ?? "").Trim();
    if (phone.Length == 0)
        return Results.BadRequest(new
        {
            error = "DLR_DriveTest_ICIC_ConditonListIsEmpty",   // giữ nguyên lỗi chính tả của nguồn
            ErrDesc = "Điều kiện tìm kiếm trống!",
            guardNote = "Doi tac BAT BUOC phai biet SO DIEN THOAI moi tra duoc - day moi la ranh gioi that, KHONG phai RBAC. Cung y do voi hat giong 'AND (1=2 ...)' o #B103 nhung lam bang guard o tang C#."
        });

    var custs = await db.DealerCustomers.Where(c => c.OrgId == t.OrgId).ToListAsync();
    var custByCode = custs.GroupBy(c => c.CustomerCode).ToDictionary(g => g.Key, g => g.First());
    // `inner join DLS_DealerCustomer` + lọc theo số điện thoại.
    var matchCust = custs.Where(c => (c.PhoneNo ?? "").Contains(phone, StringComparison.OrdinalIgnoreCase))
        .Select(c => c.CustomerCode).ToHashSet();

    var q = db.DriveTests.Where(d => d.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealerCode))
        q = q.Where(d => d.DealerCode == dealerCode.Trim().ToUpperInvariant());
    var all = await q.ToListAsync();
    var beforeCust = all.Count;
    // `inner join` ở CẢ HAI bước ⇒ lượt không gắn khách hàng bị LOẠI HẲN.
    all = all.Where(d => d.CustomerCode != null && matchCust.Contains(d.CustomerCode)).ToList();
    var droppedNoCustomer = beforeCust - all.Count;

    var dealers = (await db.Dealers.Where(x => x.OrgId == t.OrgId)
        .Select(x => new { x.DealerCode, x.DealerName }).ToListAsync())
        .GroupBy(x => x.DealerCode).ToDictionary(g => g.Key, g => g.First().DealerName);
    var models = (await db.CarModelStds.Where(m => m.OrgId == t.OrgId)
        .Select(m => new { m.ModelCode, m.ModelName }).ToListAsync())
        .GroupBy(m => m.ModelCode).ToDictionary(g => g.Key, g => g.First().ModelName);
    // `left join Mst_CarDriverTest` theo CẶP (DrvTestPlateNo, DealerCode).
    var drvCars = (await db.CarDriverTests.Where(x => x.OrgId == t.OrgId).ToListAsync())
        .GroupBy(x => (x.DrvTestPlateNo, x.DealerCode)).ToDictionary(g => g.Key, g => g.First());

    // `inner join Mst_Dealer` + `inner join Mst_CarModel` ⇒ thiếu danh mục là LOẠI dòng.
    var beforeCat = all.Count;
    all = all.Where(d => d.DealerCode != null && dealers.ContainsKey(d.DealerCode)
                         && models.ContainsKey(d.TestModelCode)).ToList();
    var droppedNoCatalog = beforeCat - all.Count;

    var items = all.OrderBy(d => d.DealerCode).ThenBy(d => d.DriveTestCode, StringComparer.Ordinal)
        .Select(d =>
        {
            custByCode.TryGetValue(d.CustomerCode ?? "", out var ddc);
            drvCars.TryGetValue((d.DrvTestPlateNo ?? "", d.DealerCode ?? ""), out var mcdt);
            return new
            {
                ddtDriveTestCode = d.DriveTestCode, ddtDealerCode = d.DealerCode,
                mdDealerName = dealers.TryGetValue(d.DealerCode ?? "", out var dn) ? dn : null,
                // 🔴 Nguồn trả HAI cột cùng tên `ModelCode` — tách rõ ở port.
                ddtModelCode = d.TestModelCode,
                mcmModelName = models.TryGetValue(d.TestModelCode, out var mn) ? mn : null,
                ddtDriveDate = d.DriveDate, ddtDriverTestType = d.DriverTestType,
                ddcFullName = ddc?.FullName, ddcFullNameEN = ddc?.FullNameEN,
                ddcAddress = ddc?.Address, ddcPhoneNo = ddc?.PhoneNo, ddcTaxCode = ddc?.TaxCode,
                ddcEmail = ddc?.Email, ddcIDCardNo = ddc?.IDCardNo, ddcIDCardType = ddc?.IDCardType,
                ddcProvinceCode = ddc?.ProvinceCode,
                mcdtDrvTestPlateNo = mcdt?.DrvTestPlateNo, mcdtSpecCode = mcdt?.SpecCode,
                mcdtModelCode = mcdt?.ModelCode, mcdtColorCode = mcdt?.ColorCode,
                mcdtDrvTestVIN = mcdt?.DrvTestVIN, mcdtDrvTestEngineNo = mcdt?.DrvTestEngineNo
            };
        }).ToList();

    return Results.Ok(new
    {
        count = items.Count, items, droppedNoCustomer, droppedNoCatalog,
        rbacCorrection = "SUA LAI KET LUAN CUA BANG QUET #B104: ham nay KHONG phai bien the 4 (hang cung) ma la BIEN THE 2 - khai ma KHONG dung. Nguon bind '@strBUPatternOfUser' = 'HTC%' NHUNG mySql_DLR_DriveTest_ICIC() KHONG he chua @strBUPatternOfUser (inner join Mst_Dealer md chi noi on md.DealerCode = t.DealerCode). Dung theo luat dem cua chinh minh: count = 1 = chi dong bind => bien the 2. Luc quet toi suy tu GIA TRI BIND thay vi kiem SQL CO DUNG KHONG.",
        rbacImpact = "He qua thuc te: KHONG co bat ky loc pham vi nao, ke ca loc sai - kenh ICIC thay MOI dai ly. Nhung xem guardNote: ranh gioi that la bat buoc phai biet SO DIEN THOAI.",
        emptySearchGuard = "if (IsNullOrEmpty(strPhoneNoConditionList)) throw DLR_DriveTest_ICIC_ConditonListIsEmpty (ten hang LOI CHINH TA 'Conditon' - giu nguyen de doi chieu log), kem ErrDesc 'Dieu kien tim kiem trong!'.",
        joinShapeNote = "inner join DLS_DealerCustomer o CA HAI buoc (loc va lay du lieu) => luot lai thu KHONG gan khach hang bi LOAI HAN. inner join Mst_Dealer + inner join Mst_CarModel cung loai dong thieu danh muc. left join Mst_CarDriverTest noi bang CAP (DrvTestPlateNo, DealerCode) - bien so xe lai thu KHONG duy nhat toan he thong.",
        dupColumnNote = "Nguon tra HAI cot cung ten 'ModelCode' - mcm.ModelCode (model cua LUOT lai thu) va mcdt.ModelCode (model cua XE lai thu) - va KHONG doi bi danh => trong DataTable cot sau DE cot truoc. Port tach ro ddtModelCode / mcdtModelCode."
    });
}).RequireAuthorization();

// ===== #B106 TRA KHẢO SÁT THEO VIN — KÊNH BẢO HIỂM `ICIC` — `DLSVINSurveyGet_ICIC_New20181115` =====
// Trace LIVE: WS → `_biz.DLSVINSurveyGet_ICIC_New20181115` (`BizHTC.DealerSales.cs:5330`).
//   3B đo thật, **khớp cả 2 máy**: start=5330 md5 `c99db90ad301711ea155f09d21c03a0d`.
// 🔴 **RBAC — BIẾN THỂ 1 (`left join` MANG ĐIỀU KIỆN), 5 CHỖ TRONG CÙNG HÀM**; **sửa tiếp** bảng quét
//    #B104 (tôi ghi là biến thể 4 vì thấy bind hằng `"HTC%"`, nhưng bước 3 cho kết quả khác):
//      `**left** join Mst_Dealer md --//[mylock] -- **Must inner join** to filter AbilityOfUser`
//      `    on cc.DealerCode = md.DealerCode`
//      `    and (md.BUCode like @strBUPatternOfUser)`
//    ⇒ điều kiện BU nằm trong `on` của **`left join`** ⇒ **chỉ BỎ GHÉP**, **KHÔNG loại dòng**.
//      Chú thích ngay trên **nói rõ phải `inner join`** — đây là ca giống hệt **#B45**.
//    Cộng thêm: giá trị bind là **hằng `"HTC%"`** ⇒ **hai lỗi chồng nhau** (sai giá trị **và** sai
//      loại join). Dù có đổi thành `inner join` thì vẫn lọc theo hằng, không theo quyền thật.
// 🔴 **ĐIỀU KIỆN "CHƯA CÓ GIAO DỊCH" VIẾT SAI PHẠM VI** (`:5552`):
//      `and ( (DealNo is not null … and ddFlagInitDeal = '0' and ddDealerCodeBuyer is null)`
//      `      or ( (select count(*) from #tbl_Car_VIN dd) = 1 )  -- Chưa có giao dịch  )`
//    Ý đồ: VIN **chưa có giao dịch** thì vẫn trả về. Nhưng vế `or` **đếm TOÀN BẢNG TẠM**, không đếm
//    theo VIN ⇒ **chỉ đúng khi tra ĐÚNG MỘT VIN**; tra nhiều VIN thì vế này **không bao giờ đúng**
//    và xe chưa có giao dịch **bị loại**. Port giữ nguyên ngữ nghĩa, trả `singleVinFallbackApplied`.
// 🔴 Hai điều kiện `-- and (dd.FlagInitDeal='0')` / `-- and (dd.DealerCodeBuyer is null)` **bị comment**
//    ở khối `#tbl_Car_VIN` nhưng lại **xuất hiện lại** trong `where` của câu select sau ⇒ **không mất**,
//    chỉ **dời chỗ**. Đọc thiếu một trong hai chỗ là kết luận sai về bộ lọc.
// 🔴 Kết quả ghép bằng **`union all`** (không distinct) giữa nhánh "có giao dịch" và nhánh khác.
app.MapGet("/api/icic/vinsurveys", async (
    AppDbContext db, ITenantContext t,
    string? carId, string? vin, string? dealNo, string? dealerCode,
    string? enforceBuScope, string? buPatternOfUser) =>
{
    const string Hardcoded = "HTC%";
    var realPattern = (buPatternOfUser ?? "").Trim();
    var applied = (enforceBuScope == "1" && realPattern.Length > 0) ? realPattern : Hardcoded;
    var prefix = applied.TrimEnd('%').ToUpperInvariant();

    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId)
        .Select(d => new { d.DealerCode, d.BUCode, d.DealerName }).ToListAsync();
    var inScope = dealers.Where(d => (d.BUCode ?? "").ToUpperInvariant().StartsWith(prefix))
        .Select(d => d.DealerCode).ToHashSet();

    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId).ToListAsync();
    if (!string.IsNullOrWhiteSpace(vin)) cars = cars.Where(c => c.VIN == vin.Trim().ToUpperInvariant()).ToList();
    if (!string.IsNullOrWhiteSpace(carId)) cars = cars.Where(c => c.VIN == carId.Trim().ToUpperInvariant()).ToList();

    var deals = await db.DealerDeals.Where(d => d.OrgId == t.OrgId).ToListAsync();
    var dealById = deals.ToDictionary(d => d.Id);
    var lines = await db.DealerDealDetails.Where(l => l.OrgId == t.OrgId).ToListAsync();
    var lineByCar = lines.GroupBy(l => l.CarId).ToDictionary(g => g.Key, g => g.First());

    // 🔴 `left join Mst_Dealer` mang điều kiện BU ⇒ CHỈ BỎ GHÉP, KHÔNG loại dòng.
    //    Đếm được số dòng "đáng lẽ bị loại nếu đúng là inner join".
    var outOfScopeCount = 0;
    var rows = cars.Select(c =>
    {
        lineByCar.TryGetValue(c.VIN, out var ln);
        DealerDeal? dd = null;
        if (ln is not null) dealById.TryGetValue(ln.DealId, out dd);
        var dlrOk = c.DealerCode != null && inScope.Contains(c.DealerCode);
        if (!dlrOk) outOfScopeCount++;
        return new
        {
            Car = c, Line = ln, Deal = dd,
            // md.* chỉ có khi ghép được — đúng ngữ nghĩa left join.
            DealerName = dlrOk ? dealers.FirstOrDefault(d => d.DealerCode == c.DealerCode)?.DealerName : null
        };
    }).ToList();

    if (!string.IsNullOrWhiteSpace(dealNo))
        rows = rows.Where(x => x.Deal?.DealNo == dealNo.Trim()).ToList();
    if (!string.IsNullOrWhiteSpace(dealerCode))
        rows = rows.Where(x => x.Car.DealerCode == dealerCode.Trim().ToUpperInvariant()).ToList();

    // 🔴 Vế `or (count(*) = 1)` — chỉ đúng khi bảng tạm có ĐÚNG MỘT dòng.
    var singleVinFallbackApplied = rows.Count == 1;
    var filtered = rows.Where(x =>
        (x.Deal is not null && x.Deal.FlagInitDeal == "0"
            && string.IsNullOrEmpty(x.Deal.DealerCodeBuyer))
        || singleVinFallbackApplied).ToList();

    var surveys = (await db.DlsVinSurveys.Where(s => s.OrgId == t.OrgId).ToListAsync())
        .GroupBy(s => s.VIN).ToDictionary(g => g.Key, g => g.First());
    var models = (await db.CarModelStds.Where(m => m.OrgId == t.OrgId)
        .Select(m => new { m.ModelCode, m.ModelName }).ToListAsync())
        .GroupBy(m => m.ModelCode).ToDictionary(g => g.Key, g => g.First().ModelName);

    var items = filtered.Select(x =>
    {
        surveys.TryGetValue(x.Car.VIN, out var sv);
        return new
        {
            cvVIN = x.Car.VIN, ccCarId = x.Car.VIN,
            cvModelCode = x.Car.ModelCode,
            mcmModelName = models.TryGetValue(x.Car.ModelCode ?? "", out var mn) ? mn : null,
            cvSpecCode = x.Car.SpecCode, cvColorCode = x.Car.ColorCode,
            ccDealerCode = x.Car.DealerCode, mdDealerName = x.DealerName,
            ddDealNo = x.Deal?.DealNo, ddFlagInitDeal = x.Deal?.FlagInitDeal,
            ddDealerCodeBuyer = x.Deal?.DealerCodeBuyer,
            dddDeliveryDate = x.Line?.DeliveryDate,
            dvContactDate = sv?.ContactDate, dvSurveyGmail = sv?.SurveyGmail, dvNote = sv?.Note,
            dvSurvey1 = sv?.Survey1, dvSurvey2 = sv?.Survey2, dvSurvey3 = sv?.Survey3,
            dvSurvey4 = sv?.Survey4, dvSurvey5 = sv?.Survey5, dvSurvey6 = sv?.Survey6
        };
    }).ToList();

    return Results.Ok(new
    {
        count = items.Count, items,
        buPatternApplied = applied, buPatternHardcoded = Hardcoded,
        outOfScopeCount, singleVinFallbackApplied,
        rbacCorrection = "SUA TIEP bang quet #B104: ham nay la BIEN THE 1 (left join MANG DIEU KIEN), khong phai bien the 4. Nguon viet 'LEFT join Mst_Dealer md ... on cc.DealerCode = md.DealerCode and (md.BUCode like @strBUPatternOfUser)' - 5 CHO trong cung ham - kem chu thich noi ro 'Must INNER join to filter AbilityOfUser'. Dieu kien BU nam trong 'on' cua LEFT JOIN => CHI BO GHEP, KHONG LOAI DONG. Ca giong het #B45.",
        rbacDoubleFaultNote = "HAI LOI CHONG NHAU: (1) sai LOAI JOIN (left thay vi inner) => khong loc gi; (2) sai GIA TRI BIND (hang 'HTC%' thay vi drAbilityOfUser['BUPattern']). Du co doi thanh inner join thi VAN loc theo hang, khong theo quyen that. => vi tri trong thang uu tien nam giua bien the 1 va bien the 4.",
        singleVinQuirk = "Dieu kien 'CHUA CO GIAO DICH' viet SAI PHAM VI (:5552): 'or ( (select count(*) from #tbl_Car_VIN dd) = 1 )'. Y do la VIN chua co giao dich thi van tra ve, nhung ve or DEM TOAN BANG TAM chu khong dem theo VIN => CHI DUNG khi tra DUNG MOT VIN; tra nhieu VIN thi ve nay KHONG BAO GIO dung va xe chua co giao dich BI LOAI. Da tra co singleVinFallbackApplied.",
        movedConditionNote = "Hai dieu kien '-- and (dd.FlagInitDeal=0)' / '-- and (dd.DealerCodeBuyer is null)' BI COMMENT o khoi #tbl_Car_VIN nhung XUAT HIEN LAI trong where cua cau select sau => KHONG MAT, chi DOI CHO. Doc thieu mot trong hai cho la ket luan sai ve bo loc.",
        unionAllNote = "Ket qua ghep bang union all (khong distinct) giua nhanh 'co giao dich' va nhanh khac."
    });
}).RequireAuthorization();

// ===== #B107 TRA GIAO DỊCH BÁN LẺ — KÊNH BẢO HIỂM `ICIC` — `DealerSalesDealGet_ICIC_New20181115` =====
// Trace LIVE: WS → `_biz.DealerSalesDealGet_ICIC_New20181115` (`BizHTC.DealerSales.cs:5833`).
//   3B đo thật, **khớp cả 2 máy**: start=5833 md5 `0f1316ef7da1365321016e8812e13722`.
// ✅ **BƯỚC 3 XÁC NHẬN: dòng này của bảng quét #B104 GHI ĐÚNG — thật sự là BIẾN THỂ 4** (khác #B105,
//    #B106 vốn bị tôi phân loại sai): `alParamsCoupleSql.AddRange({ "@strBUPatternOfUser", **"HTC%"** })`
//    và SQL **có dùng thật** trong **`INNER` join**:
//      `inner join Mst_Dealer md --//[mylock] -- Must inner join to filter AbilityOfUser`
//      `    on dlsd.DealerCode = md.DealerCode and (md.BUCode like @strBUPatternOfUser)`
//    ⇒ **có lọc, nhưng lọc theo HẰNG** ⇒ đối tác ICIC thấy **toàn bộ nhóm HTC**, và người dùng ngoài
//      nhóm HTC **không thấy gì**. Ca thứ 19, cùng khuôn #B84/#B102 — **ƯU TIÊN 2**.
//    ⚠️ Ngay trên đó, dòng lấy quyền thật **bị comment**: `//DataRow drAbilityOfUser =
//      myCommon_GetAbilityOfUser(strPartnerUserCode);//20150918` — có **dấu ngày 2015-09-18**,
//      cho thấy đây là **thay đổi CÓ CHỦ Ý** chứ không phải code dở dang.
// 🔴 **Phân trang: bản `Row_Number()` bị COMMENT, bản đang chạy dùng bảng tạm hai bước**
//    (`#tbl_DLS_Deal_Filter_Draft` → `#tbl_DLS_Deal_Filter` → `#tbl_DLS_Deal_Filter_Idx`).
//    `MyRowIdx_Start = start + 1` (*"C# based from 0 but SqlIdx based from 1"*); `MyCount` đếm
//    **trước** khi cắt trang.
// 🔴 Lọc gốc `#tbl_DLS_Deal_Filter_Draft` nối tới **`DLS_VINSurvey`** qua `Car_Car → Car_VIN → VIN`
//    ⇒ kênh bảo hiểm tra giao dịch **theo trạng thái khảo sát**. Ba vai khách hàng (Buyer/Holder/
//    Driver) + `Dlr_Contract` + `Mst_SalesMan` được ghép ở bước lấy dữ liệu, tất cả **`left join`**.
// 🔴 Bảng đính kèm `DLS_DealAttachFile` nối bằng **`inner join`** ⇒ chỉ ra giao dịch **CÓ file**.
app.MapGet("/api/icic/deals", async (
    AppDbContext db, ITenantContext t,
    string? dealNo, string? dealerCode, string? customerCodeBuyer, string? vin,
    DateTime? dealDateFrom, DateTime? dealDateTo, string? statusAnswer,
    int? recordStart, int? recordCount, string? enforceBuScope, string? buPatternOfUser) =>
{
    var start = Math.Max(0, recordStart ?? 0);
    var count = Math.Clamp(recordCount ?? 200, 1, 1000);

    const string Hardcoded = "HTC%";
    var realPattern = (buPatternOfUser ?? "").Trim();
    var applied = (enforceBuScope == "1" && realPattern.Length > 0) ? realPattern : Hardcoded;
    var prefix = applied.TrimEnd('%').ToUpperInvariant();

    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId)
        .Select(d => new { d.DealerCode, d.DealerName, d.BUCode }).ToListAsync();
    // `INNER join Mst_Dealer … and (md.BUCode like @strBUPatternOfUser)` — CÓ lọc, nhưng theo HẰNG.
    var inScope = dealers.Where(d => (d.BUCode ?? "").ToUpperInvariant().StartsWith(prefix))
        .Select(d => d.DealerCode).ToHashSet();

    var deals = await db.DealerDeals.Where(d => d.OrgId == t.OrgId).ToListAsync();
    var beforeScope = deals.Count;
    deals = deals.Where(d => d.DealerCode != null && inScope.Contains(d.DealerCode)).ToList();
    var droppedOutOfScope = beforeScope - deals.Count;

    if (!string.IsNullOrWhiteSpace(dealNo)) deals = deals.Where(d => d.DealNo == dealNo.Trim()).ToList();
    if (!string.IsNullOrWhiteSpace(dealerCode)) deals = deals.Where(d => d.DealerCode == dealerCode.Trim().ToUpperInvariant()).ToList();
    if (!string.IsNullOrWhiteSpace(customerCodeBuyer)) deals = deals.Where(d => d.CustomerCodeBuyer == customerCodeBuyer.Trim().ToUpperInvariant()).ToList();
    if (dealDateFrom is not null) deals = deals.Where(d => d.DealDate >= dealDateFrom).ToList();
    if (dealDateTo is not null) deals = deals.Where(d => d.DealDate <= dealDateTo).ToList();
    var dealById = deals.ToDictionary(d => d.Id);

    var lines = (await db.DealerDealDetails.Where(l => l.OrgId == t.OrgId).ToListAsync())
        .Where(l => dealById.ContainsKey(l.DealId)).ToList();
    if (!string.IsNullOrWhiteSpace(vin))
        lines = lines.Where(l => l.CarId == vin.Trim().ToUpperInvariant()).ToList();

    // Nối tới khảo sát VIN — lý do kênh bảo hiểm dùng hàm này.
    var surveys = (await db.DlsVinSurveys.Where(s => s.OrgId == t.OrgId).ToListAsync())
        .GroupBy(s => s.VIN).ToDictionary(g => g.Key, g => g.First());
    if (!string.IsNullOrWhiteSpace(statusAnswer))
    {
        var sa = statusAnswer.Trim();
        lines = lines.Where(l => l.CarId != null && surveys.TryGetValue(l.CarId, out var s)
                                 && (s.StatusAnswer ?? "") == sa).ToList();
    }

    var keepDealIds = lines.Select(l => l.DealId).ToHashSet();
    var frame = deals.Where(d => keepDealIds.Contains(d.Id))
        .OrderByDescending(d => d.DealNo, StringComparer.Ordinal).ToList();

    var myCount = frame.Count;                        // `MyCount` đếm TRƯỚC khi cắt trang
    var page = frame.Skip(start).Take(count).ToList();

    var custs = (await db.DealerCustomers.Where(c => c.OrgId == t.OrgId).ToListAsync())
        .GroupBy(c => (c.DealerCode, c.CustomerCode)).ToDictionary(g => g.Key, g => g.First());
    var contracts = (await db.DlrContracts.Where(c => c.OrgId == t.OrgId)
        .Select(c => new { c.DlrContractNo, c.SalesManCode }).ToListAsync())
        .GroupBy(c => c.DlrContractNo).ToDictionary(g => g.Key, g => g.First());
    var salesmen = (await db.SalesMen.Where(s => s.OrgId == t.OrgId)
        .Select(s => new { s.SalesManCode, s.SalesManName }).ToListAsync())
        .GroupBy(s => s.SalesManCode).ToDictionary(g => g.Key, g => g.First().SalesManName);

    var items = page.Select(d =>
    {
        custs.TryGetValue((d.DealerCode ?? "", d.CustomerCodeBuyer ?? ""), out var buyer);
        custs.TryGetValue((d.DealerCode ?? "", d.CustomerCodeHolder ?? ""), out var holder);
        custs.TryGetValue((d.DealerCode ?? "", d.CustomerCodeDriver ?? ""), out var driver);
        contracts.TryGetValue(d.DlrContractNo ?? "", out var ctr);
        var myLines = lines.Where(l => l.DealId == d.Id).ToList();
        return new
        {
            dlsdDealNo = d.DealNo, dlsdDealNoUser = d.DealNoUser, dlsdDealDate = d.DealDate,
            dlsdDealerCode = d.DealerCode,
            mdDealerName = dealers.FirstOrDefault(x => x.DealerCode == d.DealerCode)?.DealerName,
            dlsdDealerCodeBuyer = d.DealerCodeBuyer, dlsdSalesType = d.SalesType,
            dlsdFlagInitDeal = d.FlagInitDeal, dlsdCtmCareFlag = d.CtmCareFlag,
            dlsdc_Buyer_FullName = buyer?.FullName, dlsdc_Buyer_PhoneNo = buyer?.PhoneNo,
            dlsdc_Holder_FullName = holder?.FullName, dlsdc_Holder_PhoneNo = holder?.PhoneNo,
            dlsdc_Driver_FullName = driver?.FullName, dlsdc_Driver_PhoneNo = driver?.PhoneNo,
            dctDlrContractNo = d.DlrContractNo,
            dsmSMCode = ctr?.SalesManCode,
            dsmSMName = ctr?.SalesManCode is not null && salesmen.TryGetValue(ctr.SalesManCode, out var sn) ? sn : null,
            cars = myLines.Select(l =>
            {
                surveys.TryGetValue(l.CarId ?? "", out var sv);
                return new
                {
                    dlsddCarId = l.CarId, dlsddPlateNo = l.PlateNo,
                    dlsddDeliveryDate = l.DeliveryDate, dlsddFlagCurrent = l.FlagCurrent,
                    dlsvsStatusAnswer = sv?.StatusAnswer, dlsvsContactDate = sv?.ContactDate
                };
            }).ToList()
        };
    }).ToList();

    return Results.Ok(new
    {
        myCount, recordStart = start, recordCount = count, count = items.Count, items,
        buPatternApplied = applied, buPatternHardcoded = Hardcoded, droppedOutOfScope,
        sweepRowConfirmed = "BUOC 3 XAC NHAN dong nay cua bang quet #B104 GHI DUNG - that su la BIEN THE 4 (khac #B105/#B106 von bi phan loai sai): bind hang 'HTC%' VA SQL CO DUNG THAT trong INNER join (on dlsd.DealerCode = md.DealerCode and (md.BUCode like @strBUPatternOfUser)). => CO loc, nhung loc theo HANG.",
        rbacImpact = "Doi tac ICIC thay TOAN BO nhom HTC; nguoi dung ngoai nhom HTC KHONG THAY GI. Ca thu 19, cung khuon #B84/#B102 - UU TIEN 2.",
        commentedAbilityNote = "Ngay tren dong bind, dong lay quyen that BI COMMENT: '//DataRow drAbilityOfUser = myCommon_GetAbilityOfUser(strPartnerUserCode);//20150918' - co DAU NGAY 2015-09-18, cho thay day la THAY DOI CO CHU Y chu khong phai code do dang.",
        pagingNote = "Ban Row_Number() BI COMMENT; ban dang chay dung bang tam HAI BUOC (#tbl_DLS_Deal_Filter_Draft -> #tbl_DLS_Deal_Filter -> #tbl_DLS_Deal_Filter_Idx). MyRowIdx_Start = start + 1; MyCount dem TRUOC khi cat trang.",
        surveyJoinNote = "Loc goc noi toi DLS_VINSurvey qua Car_Car -> Car_VIN -> VIN => kenh bao hiem tra giao dich THEO TRANG THAI KHAO SAT. Ba vai khach hang (Buyer/Holder/Driver) + Dlr_Contract + Mst_SalesMan ghep o buoc lay du lieu, tat ca LEFT JOIN.",
        attachFileNote = "Bang dinh kem DLS_DealAttachFile noi bang INNER JOIN => chi ra giao dich CO FILE. (Chua port bang dinh kem - MiniHTC thieu bang nay.)"
    });
}).RequireAuthorization();

// ===== #B104 KÊNH NGOÀI `OS_` GHI NGÀY XÁC NHẬN BẢO HÀNH — `OS_DLS_DealDetailUpdate` =====
// Trace LIVE: WS → **`_biz.OS_DLS_DealDetailUpdate`** (`Biz.HTC.WH.cs:94818`).
//   3B đo thật, **khớp cả 2 máy** (`start` lệch 94818/94823 — bình thường): md5
//   `25620f63ffb5175057f9b84af620f8c9`.
// 🔴🔴🔴 **CA GHI ĐẦU TIÊN TRONG HỒ SƠ RBAC — VÀ LÀ CA KHÔNG CÓ BẤT KỲ KIỂM PHẠM VI NÀO.**
//    18 ca trước đều là hàm **ĐỌC**. Hàm này **GHI**, trên **kênh ngoài `OS_`**, và:
//      · `//DataRow drAbilityOfUser = myCommon_GetAbilityOfUser(strPartnerUserCode);` ← **BỊ COMMENT**
//        ⇒ **không hề lấy quyền người gọi**;
//      · **không** có `myCommon_CheckHTCDirect` / `myCommon_CheckDealer` /
//        `myCommon_CheckAccessDealerData` / `myCommon_CheckUpdateDealerData` — **không guard nào**;
//      · `grep -c "strBUPatternOfUser"` trong thân = **0**;
//      · ghi thẳng theo `(DealNo, CarId)` **do client gửi lên**, vào **cả `_dbMain` và `_dbWH`**.
//    ⇒ **Ai gọi được kênh `OS_` đều ghi được `CusConfirmedWarrantyDate` lên BẤT KỲ giao dịch nào
//      của BẤT KỲ đại lý nào.** 📌 **Nâng lên ƯU TIÊN 0** — trên cả #B101/#B103 (vốn chỉ là ĐỌC).
//    Port **giữ đúng nguồn** nhưng mở cờ **`enforceBuScope=1`** (kèm `buPatternOfUser`) để ép phạm vi;
//    trả `rbacNoScopeCheck = true` để không ai hiểu nhầm là đã có kiểm. **KHÔNG tự bịt.**
// 🔴 **GUARD GHI-MỘT-LẦN (idempotent NGƯỢC)**: `if (!IsNullOrEmpty(Rows[0]["CusConfirmedWarrantyDate"]))
//    throw CommonAppData_CusConfirmedWarrantyDateFound` ⇒ **đã có giá trị thì KHÔNG ghi đè**, ném lỗi.
//    ⚠️ Khác hẳn khuôn "duyệt lại được" của #B81. Đây là **ghi một lần, vĩnh viễn** — và cũng là
//      thứ **duy nhất** hạn chế thiệt hại của lỗ hổng trên (chỉ ghi được lên dòng **chưa có** ngày).
// 🔴 `alColumnEffective` **đúng MỘT cột**: `CusConfirmedWarrantyDate`. Không `LogLU*`, không dấu vết
//    người ghi ⇒ **không truy được ai đã ghi** qua kênh ngoài. Ghi nhận, không tự thêm cột.
app.MapPost("/api/os/dealdetails/confirm-warranty", async (
    OsDealDetailConfirmWarrantyDto dto, AppDbContext db, ITenantContext t,
    string? enforceBuScope, string? buPatternOfUser) =>
{
    var dealNo = (dto.DealNo ?? "").Trim();
    var carId = (dto.CarId ?? "").Trim().ToUpperInvariant();
    if (dealNo.Length == 0 || carId.Length == 0)
        return Results.BadRequest(new { error = "OS_DLS_DealDetailUpdate_InvalidKey", check = new { DealNo = dealNo, CarId = carId } });
    if (dto.CusConfirmedWarrantyDate is null)
        return Results.BadRequest(new { error = "OS_DLS_DealDetailUpdate_InvalidCusConfirmedWarrantyDate" });

    var deal = await db.DealerDeals.FirstOrDefaultAsync(d => d.OrgId == t.OrgId && d.DealNo == dealNo);
    if (deal is null)
        return Results.NotFound(new { error = "DLS_Deal_NotExist", check = new { DealNo = dealNo } });

    // Nguồn KHÔNG kiểm phạm vi — chỉ ép khi bật cờ, và luôn ĐO được.
    var realPattern = (buPatternOfUser ?? "").Trim();
    var dealer = await db.Dealers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == deal.DealerCode);
    var inScope = realPattern.Length == 0
        || (dealer?.BUCode ?? "").ToUpperInvariant().StartsWith(realPattern.TrimEnd('%').ToUpperInvariant());
    if (enforceBuScope == "1" && !inScope)
        return Results.BadRequest(new
        {
            error = "Common_AccessDealerDataDenied",
            check = new { DealNo = dealNo, deal.DealerCode, BUCode = dealer?.BUCode, BUPatternOfUser = realPattern },
            note = "Nguon KHONG co kiem nay - day la co enforceBuScope=1 do MiniHTC mo them de bit duoc khi nghiep vu quyet dinh."
        });

    var line = await db.DealerDealDetails
        .FirstOrDefaultAsync(l => l.OrgId == t.OrgId && l.DealId == deal.Id && l.CarId == carId);
    if (line is null)
        return Results.NotFound(new { error = "DLS_DealDetail_NotExist", check = new { DealNo = dealNo, CarId = carId } });

    // 🔴 GUARD GHI-MỘT-LẦN: đã có giá trị ⇒ NÉM, không ghi đè.
    if (line.CusConfirmedWarrantyDate is not null)
        return Results.BadRequest(new
        {
            error = "CommonAppData_CusConfirmedWarrantyDateFound",
            check = new { strDealNo = dealNo, strCarId = carId, strCusConfirmedWarrantyDate = line.CusConfirmedWarrantyDate },
            writeOnceNote = "GUARD GHI-MOT-LAN: da co gia tri thi KHONG ghi de, nguon NEM loi. Khac han khuon 'duyet lai duoc' cua #B81."
        });

    // `alColumnEffective` đúng MỘT cột — không LogLU*, không dấu vết người ghi.
    line.CusConfirmedWarrantyDate = dto.CusConfirmedWarrantyDate;
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        dealNo, carId, line.CusConfirmedWarrantyDate,
        dealerCode = deal.DealerCode,
        rbacNoScopeCheck = enforceBuScope != "1",
        buScopeEnforced = enforceBuScope == "1",
        rbacHole = "CA GHI DAU TIEN TRONG HO SO RBAC - VA LA CA KHONG CO BAT KY KIEM PHAM VI NAO. 18 ca truoc deu la ham DOC. Ham nay GHI, tren KENH NGOAI 'OS_', va: (a) dong '//DataRow drAbilityOfUser = myCommon_GetAbilityOfUser(strPartnerUserCode);' BI COMMENT => khong he lay quyen nguoi goi; (b) KHONG co myCommon_CheckHTCDirect / CheckDealer / CheckAccessDealerData / CheckUpdateDealerData nao; (c) grep -c 'strBUPatternOfUser' trong than = 0; (d) ghi thang theo (DealNo, CarId) DO CLIENT GUI LEN, vao CA _dbMain va _dbWH.",
        rbacImpact = "Ai goi duoc kenh OS_ deu ghi duoc CusConfirmedWarrantyDate len BAT KY giao dich nao cua BAT KY dai ly nao. NANG LEN UU TIEN 0 - tren ca #B101/#B103 (von chi la DOC). Thiet hai bi han che DUY NHAT boi guard ghi-mot-lan (chi ghi duoc len dong CHUA co ngay).",
        writeOnceNote = "GUARD GHI-MOT-LAN (idempotent NGUOC): da co gia tri => NEM CommonAppData_CusConfirmedWarrantyDateFound, KHONG ghi de. Khac han khuon 'duyet lai duoc' cua #B81.",
        noAuditTrailNote = "alColumnEffective dung MOT cot: CusConfirmedWarrantyDate. KHONG LogLUDateTime/LogLUBy => KHONG TRUY DUOC AI DA GHI qua kenh ngoai. Ghi nhan; khong tu them cot.",
        portNote = "Port GIU DUNG nguon; co enforceBuScope=1 (kem buPatternOfUser) la MiniHTC MO THEM de bit duoc khi nghiep vu quyet dinh. KHONG tu bit."
    });
}).RequireAuthorization();

// ===== #B97 THÔNG TIN NGƯỜI DÙNG ĐANG ĐĂNG NHẬP — `SysGetUser_ForCurrentUser_New20181115` =====
// Trace LIVE: WS → `_biz.SysGetUser_ForCurrentUser_New20181115` (`BizHTC.System.cs:202`).
//   3B đo thật, **khớp cả 2 máy**: start=202 md5 `d8dfab486c1899d56f9e59cbf9c5a077`.
// 🔴🔴 **MẬT KHẨU KHÔNG BAO GIỜ TRẢ VỀ THẬT — luôn là hằng che**:
//    `mySql_GetClauseColumnForSysUserInfo` (`BizHTC.System.cs`) sinh cột
//    **`N'{TConst.HTCConst.PasswordTemplate}' UserPassword`** = **`"********"`** (`Const.Main.cs:321`)
//    ⇒ **hằng chuỗi trong SELECT**, KHÔNG đọc cột mật khẩu. Đây là **guard bảo mật của nguồn**;
//    port **tuyệt đối không** trả `UserPasswordHash`.
// 🔴 **`and t.PartnerCode not in (@strPartnerCode)` với `@strPartnerCode = TConst.Sys_Partner.Web`
//    = `"WEBHTC"`** (`Const.Main.cs:1250`) — **rất phản trực giác, đọc kỹ ba điểm**:
//      · tên tham số là `@strPartnerCode` nhưng dùng để **LOẠI TRỪ** (`not in`), không phải để lọc-theo;
//      · giá trị **KHÔNG** phải partner của phiên đăng nhập mà là **hằng `"WEBHTC"`**;
//      · ⇒ nếu chính người dùng hiện tại thuộc partner **`WEBHTC`** thì hàm trả **RỖNG** —
//        "thông tin người dùng hiện tại" **không có**. Đó là hành vi THẬT, không phải lỗi.
//    Port giữ nguyên và trả cờ `excludedByWebPartner` để phân biệt "không tìm thấy" với "bị loại".
// 🔴 **`left join Mst_Dealer md … , md.*`** — trả **TOÀN BỘ** cột đại lý kèm theo, và là `left join`
//    thật: người dùng **không gắn đại lý** vẫn ra dòng, phần `md.*` để trống.
// 🔴 Các cột người dùng được **đổi bí danh có tiền tố `SU`** (`SUDealerCode`, `SUBankCode`,
//    `SUFlagActive`, `SUTransporterCode`, `SUInsCompanyCode`) — **cố ý** để không đè cột cùng tên
//    của `md.*` khi ghép hai bảng. Port giữ đúng bí danh (cùng khuôn tiền tố `mcc_` ở #B93).
// ⚠️ `@strBUPatternOfUser` được bind nhưng **không dùng** — RBAC biến thể 2, ca thứ 14. Ở đây tác hại
//    bằng 0 vì mệnh đề `t.UserCode = @strPartnerUserCode` đã khoá về **đúng một** người dùng.
app.MapGet("/api/sysusers/current", async (
    AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal principal, string? userCode) =>
{
    var code = string.IsNullOrWhiteSpace(userCode)
        ? (principal.Identity?.Name ?? principal.FindFirst("email")?.Value ?? "")
        : userCode.Trim();
    if (code.Length == 0)
        return Results.BadRequest(new { error = "SysGetUser_ForCurrentUser_InvalidUserCode" });

    var u = await db.SysUsers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.UserCode == code);
    if (u is null)
        return Results.NotFound(new { error = "Sys_User_NotExist", check = new { UserCode = code } });

    // 🔴 `and t.PartnerCode not in ('WEBHTC')` — LOẠI, không phải lọc-theo.
    const string PartnerWeb = "WEBHTC";                      // `TConst.Sys_Partner.Web`
    if (string.Equals(u.PartnerCode ?? "", PartnerWeb, StringComparison.OrdinalIgnoreCase))
        return Results.Ok(new
        {
            count = 0, items = Array.Empty<object>(),
            excludedByWebPartner = true,
            excludeNote = "Nguon co 'and t.PartnerCode not in (@strPartnerCode)' voi @strPartnerCode = TConst.Sys_Partner.Web = 'WEBHTC' => nguoi dung thuoc partner WEBHTC bi LOAI, ham tra RONG. Hanh vi THAT, khong phai loi."
        });

    // `left join Mst_Dealer` — LEFT thật: không gắn đại lý vẫn ra dòng.
    var md = u.DealerCode is null ? null
        : await db.Dealers.FirstOrDefaultAsync(d => d.OrgId == t.OrgId && d.DealerCode == u.DealerCode);

    return Results.Ok(new
    {
        count = 1,
        items = new[] { new {
            tUserCode = u.UserCode,
            tUserName = u.UserName,
            // 🔴🔴 HẰNG CHE — KHÔNG BAO GIỜ trả mật khẩu thật.
            UserPassword = "********",
            SUDealerCode = u.DealerCode, SUBankCode = u.BankCode,
            tFlagSysAdmin = u.FlagSysAdmin, tFlagSysViewer = u.FlagSysViewer,
            SUFlagActive = u.FlagActive,
            SUTransporterCode = u.TransporterCode, SUInsCompanyCode = u.InsCompanyCode,
            // `md.*` — toàn bộ cột đại lý; null khi không gắn đại lý.
            mdDealerCode = md?.DealerCode, mdDealerName = md?.DealerName,
            mdBUCode = md?.BUCode, mdProvinceCode = md?.ProvinceCode,
            mdFlagActive = md?.FlagActive, mdFlagTCG = md?.FlagTCG
        } },
        excludedByWebPartner = false,
        passwordMaskNote = "MAT KHAU KHONG BAO GIO TRA VE THAT: mySql_GetClauseColumnForSysUserInfo sinh cot N'{PasswordTemplate}' UserPassword = '********' (Const.Main.cs:321) - HANG CHUOI trong SELECT, KHONG doc cot mat khau. Day la GUARD BAO MAT cua nguon; port TUYET DOI khong tra UserPasswordHash.",
        excludeRuleNote = "'and t.PartnerCode not in (@strPartnerCode)' voi @strPartnerCode = 'WEBHTC': ten tham so la @strPartnerCode nhung dung de LOAI TRU (not in), va gia tri KHONG phai partner cua phien dang nhap ma la HANG. Da tra co excludedByWebPartner de phan biet 'khong tim thay' voi 'bi loai'.",
        joinNote = "left join Mst_Dealer md ... , md.* - tra TOAN BO cot dai ly kem theo, va la LEFT THAT: nguoi dung khong gan dai ly VAN ra dong, phan md.* de trong.",
        aliasPrefixNote = "Cac cot nguoi dung doi bi danh co TIEN TO 'SU' (SUDealerCode, SUBankCode, SUFlagActive, SUTransporterCode, SUInsCompanyCode) - CO Y de khong de cot cung ten cua md.* khi ghep hai bang (cung khuon tien to 'mcc_' o #B93).",
        rbacHole = "RBAC bien the 2 (khai ma khong dung), ca thu 14: @strBUPatternOfUser bind nhung khong dung. Tac hai = 0 vi menh de t.UserCode = @strPartnerUserCode da khoa ve DUNG MOT nguoi dung."
    });
}).RequireAuthorization();

app.MapGet("/api/sysobjecttypes", async (AppDbContext db, ITenantContext t, string? objectTypeList) =>
{
    var codes = SplitConditionList(objectTypeList);
    var rows = await db.SysObjectTypeMsts.Where(o => o.OrgId == t.OrgId)
        .OrderBy(o => o.ObjectType).ToListAsync();
    var fallback = rows.Count == 0;
    // Bảng rỗng ⇒ dùng tạm mảng cứng của port cũ để không phá màn phân quyền đang chạy.
    var items = fallback
        ? SysObjectTypes.Where(x => codes.Count == 0 || codes.Contains(x))
            .Select(x => new { tObjectType = x, tObjectTypeName = (string?)null }).ToList()
        : rows.Where(o => codes.Count == 0 || codes.Contains(o.ObjectType))
            .Select(o => new { tObjectType = o.ObjectType, tObjectTypeName = o.ObjectTypeName }).ToList();
    return Results.Ok(new
    {
        count = items.Count, items,
        fallbackToHardCoded = fallback,
        tableNote = "Sys_ObjectType la BANG, khong phai hang: port cu de CUNG trong C# (string[] SysObjectTypes = { WS, WSFUNC, APP, MENU, SCR, BTN }) => MAT cot ObjectTypeName (ten hien thi) va KHONG them/bot loai duoc. Da them entity SysObjectTypeMst; mang cung GIU LAI lam gia tri mac dinh khi bang rong - xem co fallbackToHardCoded.",
        separatorNote = "BuildClauseConditionList(..., '|') - dau ngan la ONG '|', khong phai dau phay.",
        vocabNote = "Tu vung goc (Const.Main.cs:166, TConst.SysObjectType): WS · WSFUNC · APP · MENU · SCR · BTN. 'BIZFUNC' BI COMMENT trong nguon."
    });
}).RequireAuthorization();

// ===== #B98 DANH MỤC PHÒNG BAN — `Mst_Department_Get_New20181115` =====
// Trace LIVE: WS → `_biz.Mst_Department_Get_New20181115` (`BizHTC.zzzzCode.cs:6839`);
//   phía client là `DealerService.GetDepartment(strDepartmentCode)`.
//   3B đo thật, **khớp cả 2 máy**: start=6839 md5 `21e38c178f9a1e81c64c26e4119c2040`.
// ⚠️ **Caller-first (luật `C0-…septuagesimustertius`)**: hai hàm liền kề trong **cùng file**
//    `Mst_SalesManTypeCertificate_Get_New20181115` (`:7240`) và `Mst_Qualification_Get_New20181115`
//    (`:7465`) **KHÔNG CÓ caller nào** — grep toàn cây chỉ ra chính file đó + bản `Backup/`.
//    ⇒ **HÀM CHẾT, KHÔNG PORT** (cùng quyết định với `DiscountCreate`/`MstDiscountSave`).
// 🔴 **Khuôn "lọc rồi tự nối lại"**: `#tbl_Mst_Department_Filter` chỉ giữ **`DepartmentCode`**, rồi
//    `inner join Mst_Department` lấy `mdpm.*`. Cả hai bước đều `select distinct` — **hai lần** distinct.
//    ⇒ Bảng có hai dòng trùng `DepartmentCode` nhưng khác cột khác thì **vẫn ra hai dòng** (distinct
//    thứ hai xét TOÀN BỘ cột). Đừng port thành `DistinctBy(DepartmentCode)`.
// 🔴 `BuildClauseConditionList` — dấu ngăn **ống `|`** như #B96, không phải dấu phẩy.
// ⚠️ **RBAC biến thể 2 — ca thứ 15**: `@strBUPatternOfUser` bind nhưng SQL **không dùng**
//    (danh mục phòng ban không có cột đại lý). Tác hại ~0; ghi để đủ mẫu.
app.MapGet("/api/departments", async (AppDbContext db, ITenantContext t, string? departmentCodeList) =>
{
    var codes = SplitConditionList(departmentCodeList);
    var q = db.Departments.Where(d => d.OrgId == t.OrgId);
    if (codes.Count > 0) q = q.Where(d => codes.Contains(d.DepartmentCode));
    // Hai lần `select distinct`, lần sau xét TOÀN BỘ cột ⇒ KHÔNG gộp theo mã.
    var items = (await q.OrderBy(d => d.DepartmentCode).ToListAsync())
        .Select(d => new
        {
            mdpmDepartmentCode = d.DepartmentCode,
            mdpmDepartmentName = d.DepartmentName,
            mdpmFlagActive = d.FlagActive,
            mdpmRemark = d.Remark
        }).Distinct().ToList();
    return Results.Ok(new
    {
        count = items.Count, items,
        distinctNote = "Khuon 'loc roi tu noi lai': #tbl_Mst_Department_Filter chi giu DepartmentCode, roi inner join Mst_Department lay mdpm.*. CA HAI buoc deu 'select distinct' - HAI LAN distinct, va lan sau xet TOAN BO cot => hai dong trung DepartmentCode nhung khac cot khac VAN ra hai dong. Dung port thanh DistinctBy(DepartmentCode).",
        separatorNote = "BuildClauseConditionList dung dau ngan ONG '|' (nhu #B96), khong phai dau phay.",
        deadSiblingsNote = "Caller-first: hai ham lien ke trong CUNG FILE - Mst_SalesManTypeCertificate_Get_New20181115 (:7240) va Mst_Qualification_Get_New20181115 (:7465) - KHONG CO caller nao (chi file goc + Backup/) => HAM CHET, KHONG PORT.",
        rbacHole = "RBAC bien the 2 (khai ma khong dung), ca thu 15: @strBUPatternOfUser bind nhung SQL khong dung (danh muc phong ban khong co cot dai ly). Tac hai ~0; ghi de du mau."
    });
}).RequireAuthorization();

