// 🔴 Kiểm **từng dòng**, ném ngay ở dòng đầu tiên hỏng; danh sách rỗng ⇒ `…_TableBlank`.
//    `Mst_SalesMan_CheckDB(…, TConst.Flag.**No**, …)` — nhân viên **phải CHƯA tồn tại**.
app.MapPost("/api/salesmen/create-multi", async (
    List<SalesManCreateMultiDto> rows, AppDbContext db, ITenantContext t) =>
{
    if (rows is null || rows.Count == 0)
        return Results.BadRequest(new { error = "Mst_SalesMan_CreateMulti_TableBlank" });

    var today = DateTime.Now.Date;
    var created = new List<object>();

    foreach (var (r, i) in rows.Select((r, i) => (r, i)))
    {
        var smCode = (r.SMCode ?? "").Trim().ToUpperInvariant();
        var smName = (r.SMName ?? "").Trim();
        var dealerCode = (r.DealerCode ?? "").Trim().ToUpperInvariant();
        var smStatus = (r.SMStatus ?? "").Trim();
        var smHyundaiCode = (r.SMHyundaiCode ?? "").Trim();

        if (smName.Length == 0)
            return Results.BadRequest(new { error = "Mst_SalesMan_CreateMulti_InvalidSMName", check = new { Idx = i, SMCode = smCode } });
        if (smStatus != "0" && smStatus != "1" && smStatus != "2" && smStatus != "3")
            return Results.BadRequest(new { error = "Mst_SalesMan_CreateMulti_InvalidSMStatus", check = new { Idx = i, SMStatus = smStatus } });

        // `Mst_SalesMan_CheckDB(…, Flag.No, …)` — phải CHƯA tồn tại.
        if (await db.SalesMen.AnyAsync(x => x.OrgId == t.OrgId && x.SalesManCode == smCode))
            return Results.BadRequest(new { error = "Mst_SalesMan_CreateMulti_SMCodeExist", check = new { Idx = i, SMCode = smCode } });

        var dealer = await db.Dealers.FirstOrDefaultAsync(d => d.OrgId == t.OrgId && d.DealerCode == dealerCode);
        if (dealer is null)
            return Results.BadRequest(new { error = "Common_InvalidDealerCode", check = new { Idx = i, DealerCode = dealerCode } });

        // 🔴🔴 GUARD CHẾ TÀI: dò theo SMHyundaiCode (CÁ NHÂN), không phải SMCode (theo đại lý).
        if (smHyundaiCode.Length > 0)
        {
            var peers = await db.SalesMen
                .Where(x => x.OrgId == t.OrgId && x.SMHyundaiCode == smHyundaiCode)
                .Select(x => x.SalesManCode).ToListAsync();
            var latest = await db.SalesManViolates
                .Where(v => v.OrgId == t.OrgId && peers.Contains(v.SalesManCode))
                .OrderByDescending(v => v.ViolateNumber).FirstOrDefaultAsync();
            if (latest is not null
                && string.Equals(latest.ViolateTypeId, "TT", StringComparison.OrdinalIgnoreCase)
                && latest.ViolateDateEnd is not null && latest.ViolateDateEnd.Value.Date >= today)
                return Results.BadRequest(new
                {
                    error = "Mst_SalesMan_CreateMulti_SalesManViolate",
                    check = new
                    {
                        Idx = i, SMCode = smCode, SMHyundaiCode = smHyundaiCode,
                        latest.ViolateTypeId, latest.ViolateNumber, latest.ViolateDateEnd
                    },
                    violateNote = "Nhan vien dang bi DINH CHI TAM THOI (ViolateTypeId='TT' va ViolateDateEnd >= hom nay) => KHONG duoc tao lai. Khoa do la SMHyundaiCode (CA NHAN), khong phai SMCode (theo dai ly)."
                });
        }

        // 🔴 FlagActive do BIZ suy ra từ SMStatus, KHÔNG nhận từ client.
        var flagActive = smStatus == "0" ? "0" : "1";

        db.SalesMen.Add(new SalesMan
        {
            OrgId = t.OrgId, SalesManCode = smCode, SalesManName = smName, DealerCode = dealerCode,
            DepartmentCode = r.DepartmentCode, SalesType = r.SMType, Phone = r.SMPhoneNo, Email = r.SMEmail,
            Gender = r.SMGender, DateOfBirth = r.SMDateOfBirth, Address = r.SMAddress,
            ProvinceCode = r.ProvinceCode, QualificationCode = r.QualificationCode,
            Specialized = r.SMSpecialized, YearExperience = r.SMYearExperence,
            StartDate = r.SMStartDate, EndDate = r.SMEndDate,
            Position = r.SMPosition, PositionCode = r.SMPostionCode,
            CertificateCode = r.CertificateCode, SMHyundaiCode = smHyundaiCode,
            IdentityCardNo = r.IdentityCardNo,
            WebsiteLink = r.WebsiteLink, FacebookLink = r.FacebookLink, FanpageLink = r.FanpageLink,
            GroupLink = r.GroupLink, ZaloLink = r.ZaloLink,
            Status = flagActive
        });
        created.Add(new { smCode, dealerCode, smStatus, flagActive });
    }
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        createdCount = created.Count, created,
        deadSiblingsNote = "CALLER-FIRST: BizHTC.zzzzCode.cs co Mst_SalesMan_Create (:8020), _Update (:8484), _Get (:7667) trong rat giong 'cum CRUD can port' - nhung WS64 KHONG GOI CAI NAO. Ban LIVE la _CreateMulti_New20260323 / _Update_New20230306 / _UpdateMulti / _UpdateMultiByHTV_New20230306 / _UpdateStatus / _Delete_New20181119. Ba ham o zzzzCode.cs la CHET.",
        flagActiveNote = "FlagActive KHONG do client quyet dinh - biz TU SUY TU SMStatus: nguon XOA HAN cot FlagActive neu client gui len (Columns.Remove) roi MyForceNewColumn tao lai, gan theo luat: SMStatus == '0' (NGHIVIEC) => '0'; MOI gia tri khac => '1'. Nhan flagActive tu body la MO QUYEN GHI NGOAI NGUON.",
        smStatusVocab = "TConst.SMStatus (Const.Main.cs:1213-1219): '0' nghi viec | '1' chinh thuc | '2' thu viec | '3' cong tac vien.",
        violateGuardNote = "GUARD CHE TAI LIEN DAI LY: 'select top 1 ... from HR_SalesManViolate t left join Mst_SalesMan f on t.SMCode = f.SMCode where f.SMHyundaiCode = @strSMHyundaiCode order by t.ViolateNumber desc' => lay LAN VI PHAM MOI NHAT cua CON NGUOI DO (ma Hyundai theo ca nhan). Neu ViolateTypeId='TT' (tam thoi) VA ViolateDateEnd >= hom nay => CHAN tao moi. Y nghia: nhan vien dang bi dinh chi tam thoi KHONG duoc tao lai o DAI LY KHAC. Port do theo SMCode la VO HIEU HOA TOAN BO GUARD.",
        violateTypeVocab = "TConst.ViolateTypeId (Const.Main.cs:1242-1246): 'TT' tam thoi | 'VV' vinh vien. Guard nay CHI chan 'TT' con han hieu luc.",
        rowWiseNote = "Kiem TUNG DONG, nem ngay o dong dau tien hong; danh sach rong => _TableBlank. Mst_SalesMan_CheckDB(..., TConst.Flag.No, ...) - phai CHUA ton tai."
    });
}).RequireAuthorization();

// ===== #B100 ĐỔI TRẠNG THÁI NHÂN SỰ NVBH — `Mst_SalesMan_UpdateStatus` =====
// Trace LIVE: WS `:5366` → **`_biz.Mst_SalesMan_UpdateStatus`** (`Biz.HTC.WH.cs:19424`) —
//   **không có hậu tố `_NewYYYYMMDD`** (hiếm, như #B77). 3B đo thật, **khớp cả 2 máy**:
//   start=19424 md5 `5582245304d83752b4f4e2f17247b722`.
// 🔴 **HAI TRỤC TRẠNG THÁI TÁCH BIỆT — đừng gộp**:
//      `SMStatus`   = **trạng thái nhân sự**, 4 giá trị (`TConst.SMStatus`): **"0"** nghỉ việc ·
//                     **"1"** chính thức · **"2"** thử việc · **"3"** cộng tác viên;
//      `FlagActive` = **suy ra**, chỉ "1"/"0" — `SMStatus == "0"` ⇒ `"0"`, còn lại ⇒ `"1"`.
//    Client **không** gửi `FlagActive` (cùng khuôn #B99).
// 🔴 **MÁY TRẠNG THÁI CÓ HƯỚNG**: đang **"1" (chính thức)** thì **CHỈ** được về **"1"** hoặc **"0"**
//    — **không lùi** về thử việc/cộng tác viên. Trạng thái khác thì đi đâu cũng được.
// 🔴 **Khi chuyển sang NGHỈ VIỆC (`FlagActive` → "0")** — ba trường **BẮT BUỘC**:
//    `SMReason` (`…_InvalidSMReason`) · `SMDesc` (`…_InvalidSMDesc`) ·
//    `SMEndDate` (`…_SMEndDateNotNull`, và phải đúng định dạng ⇒ `…_InvalidSMEndDate`).
// 🔴 **Khi ĐI LÀM LẠI** (`FlagActive` → "1" **và** trạng thái CŨ là "0"): nguồn **XOÁ VỀ NULL**
//    `SMReason`, `SMDesc`, `SMEndDate` **và** đặt `SMStartDate` mới. ⇒ Đây là **reset hồ sơ nghỉ
//    việc**, không phải chỉ đổi cờ. Port bỏ bước xoá ⇒ nhân viên đang làm vẫn mang lý do nghỉ cũ.
// 🔴 **`SMStartDate` phải LỚN HƠN ngày nghỉ việc gần nhất**: `select max(t.SMEndDate) from
//    Mst_SalesManHistoryInactive t where t.**SMHyundaiCode** = @…` — lại dò theo **mã CÁ NHÂN**
//    (như guard chế tài #B99), không phải `SMCode`. So bằng **`string.CompareTo` trên chuỗi ngày**
//    `"yyyy-MM-dd"` (so chuỗi vẫn đúng thứ tự vì định dạng cố định) ⇒ `<= 0` là **chặn**.
// 🔴 **GHI LỊCH SỬ TRƯỚC KHI INACTIVE** — chỉ khi **thật sự chuyển** Active → Inactive
//    (`strFlagActive == "0"` **và** `FlagActive` **hiện tại trong DB** == `"1"`): chụp một dòng vào
//    `Mst_SalesManHistoryInactive` (`SMCode`, `SMHyundaiCode`, `DealerCode`, `SMStatus`,
//    `IdentityCardNo`, `SMFlagActive`, `SMStartDate`, `SMEndDate`, `SMReason`, `SMDesc`).
//    ⚠️ Chụp **giá trị CŨ** (`dt_Mst_SalesManCur`), không phải giá trị vừa gán.
// 🔴 Guard **chế tài** lặp lại như #B99 (`HR_SalesManViolate`, `ViolateTypeId='TT'` còn hạn).
// 🔴 `alColumnEffective` **thay đổi theo nhánh** — luôn có `FlagActive`/`SMStatus`/`UpdateStatusDtime`
//    /`UpdateStatusBy`; thêm `SMReason`/`SMDesc` khi nghỉ việc; thêm cả `SMStartDate`/`SMEndDate` khi
//    đi làm lại. Ghi **cả `_dbMain` và `_dbWH`**.
app.MapPost("/api/salesmen/{code}/update-status", async (
    string code, SalesManUpdateStatusDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    var smCode = (code ?? "").Trim().ToUpperInvariant();
    var sm = await db.SalesMen.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SalesManCode == smCode);
    if (sm is null) return Results.NotFound(new { error = "Mst_SalesMan_NotExist", check = new { SMCode = smCode } });

    var smStatus = (dto.SMStatus ?? "").Trim();
    if (smStatus != "0" && smStatus != "1" && smStatus != "2" && smStatus != "3")
        return Results.BadRequest(new { error = "Mst_SalesMan_UpdateStatus_InvalidSMStatus", check = new { SMCode = smCode, SMStatus = smStatus } });

    // 🔴 Máy trạng thái CÓ HƯỚNG: "1" chỉ về được "1" hoặc "0".
    var smStatusCur = sm.SMStatus ?? "";
    if (smStatusCur == "1" && !(smStatus == "1" || smStatus == "0"))
        return Results.BadRequest(new
        {
            error = "Mst_SalesMan_UpdateStatus_InvalidSMStatus",
            check = new { SMCode = smCode, SMStatus = smStatus, SMStatusCur = smStatusCur },
            transitionNote = "Dang CHINH THUC ('1') thi CHI duoc ve '1' hoac '0' - khong lui ve thu viec/cong tac vien."
        });

    var flagActive = smStatus == "0" ? "0" : "1";
    var smHyundaiCode = (dto.SMHyundaiCode ?? sm.SMHyundaiCode ?? "").Trim();
    var today = DateTime.Now.Date;

    // 🔴 SMStartDate phải LỚN HƠN ngày nghỉ việc gần nhất — dò theo SMHyundaiCode (CÁ NHÂN).
    if (dto.SMStartDate is not null && smHyundaiCode.Length > 0)
    {
        var lastEnd = await db.SalesManHistoryInactives
            .Where(h => h.OrgId == t.OrgId && h.SMHyundaiCode == smHyundaiCode && h.SMEndDate != null)
            .MaxAsync(h => (DateTime?)h.SMEndDate);
        if (lastEnd is not null && dto.SMStartDate.Value.Date <= lastEnd.Value.Date)
            return Results.BadRequest(new
            {
                error = "Mst_SalesMan_UpdateStatus_InvalidSMStartDate",
                check = new { SMCode = smCode, SMStartDate = dto.SMStartDate, SMEndDateLast = lastEnd },
                DESC = "Ngay bat dau phai lon hon ngay nghi viec gan nhat"
            });
    }

    // 🔴 Guard chế tài (như #B99): 'TT' còn hạn ⇒ chặn.
    if (smHyundaiCode.Length > 0)
    {
        var peers = await db.SalesMen.Where(x => x.OrgId == t.OrgId && x.SMHyundaiCode == smHyundaiCode)
            .Select(x => x.SalesManCode).ToListAsync();
        var v = await db.SalesManViolates.Where(x => x.OrgId == t.OrgId && peers.Contains(x.SalesManCode))
            .OrderByDescending(x => x.ViolateNumber).FirstOrDefaultAsync();
        if (v is not null && string.Equals(v.ViolateTypeId, "TT", StringComparison.OrdinalIgnoreCase)
            && v.ViolateDateEnd is not null && v.ViolateDateEnd.Value.Date >= today)
            return Results.BadRequest(new
            {
                error = "Mst_SalesMan_UpdateStatus_SalesManViolate",
                check = new { SMCode = smCode, SMHyundaiCode = smHyundaiCode, v.ViolateTypeId, v.ViolateNumber, v.ViolateDateEnd }
            });
    }

    var reason = (dto.SMReason ?? "").Trim();
    var desc = (dto.SMDesc ?? "").Trim();

    // 🔴 Nghỉ việc ⇒ BA trường bắt buộc.
    if (flagActive == "0")
    {
        if (reason.Length == 0) return Results.BadRequest(new { error = "Mst_SalesMan_UpdateStatus_InvalidSMReason", check = new { SMCode = smCode } });
        if (desc.Length == 0) return Results.BadRequest(new { error = "Mst_SalesMan_UpdateStatus_InvalidSMDesc", check = new { SMCode = smCode } });
        if (dto.SMEndDate is null)
            return Results.BadRequest(new { error = "Mst_SalesMan_UpdateStatus_SMEndDateNotNull", check = new { SMCode = smCode }, DESC = "Khi nhan vien nghi viec thi can phai nhap ngay ket thuc" });
    }

    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var flagActiveCur = sm.Status;                 // giá trị CŨ, dùng cho bước ghi lịch sử

    // 🔴 GHI LỊCH SỬ TRƯỚC KHI INACTIVE — chụp giá trị CŨ, chỉ khi THẬT SỰ chuyển "1" → "0".
    var historyWritten = false;
    if (flagActive == "0" && flagActiveCur == "1")
    {
        db.SalesManHistoryInactives.Add(new SalesManHistoryInactive
        {
            OrgId = t.OrgId,
            SMCode = sm.SalesManCode, SMHyundaiCode = sm.SMHyundaiCode, DealerCode = sm.DealerCode,
            SMStatus = sm.SMStatus, IdentityCardNo = sm.IdentityCardNo,
            SMFlagActive = sm.Status, SMStartDate = sm.StartDate,
            SMEndDate = dto.SMEndDate, SMReason = reason, SMDesc = desc,
            InactiveDateTime = now, InactiveBy = by
        });
        historyWritten = true;
    }

    // `alColumnEffective` — bốn cột luôn ghi.
    sm.Status = flagActive; sm.SMStatus = smStatus;
    sm.UpdateStatusDtime = now; sm.UpdateStatusBy = by;

    var resetOnRehire = false;
    if (flagActive == "0") { sm.SMReason = reason; sm.SMDesc = desc; sm.EndDate = dto.SMEndDate; }
    else if (smStatusCur == "0")
    {
        // 🔴 ĐI LÀM LẠI: XOÁ hồ sơ nghỉ việc về null + đặt SMStartDate mới.
        sm.SMReason = null; sm.SMDesc = null; sm.EndDate = null;
        sm.StartDate = dto.SMStartDate ?? sm.StartDate;
        resetOnRehire = true;
    }
    else sm.EndDate = dto.SMEndDate;

    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        smCode, smStatusBefore = smStatusCur, smStatus, flagActiveBefore = flagActiveCur, flagActive = sm.Status,
        historyWritten, resetOnRehire,
        sm.SMReason, sm.SMDesc, sm.StartDate, sm.EndDate, sm.UpdateStatusDtime, sm.UpdateStatusBy,
        twoAxisNote = "HAI TRUC TRANG THAI TACH BIET: SMStatus = trang thai NHAN SU (4 gia tri: 0 nghi viec | 1 chinh thuc | 2 thu viec | 3 cong tac vien); FlagActive = SUY RA, chi '1'/'0' (SMStatus=='0' => '0'). Client KHONG gui FlagActive (cung khuon #B99).",
        transitionNote = "MAY TRANG THAI CO HUONG: dang '1' (chinh thuc) thi CHI duoc ve '1' hoac '0' - KHONG lui ve thu viec/cong tac vien. Trang thai khac thi di dau cung duoc.",
        requiredOnQuitNote = "Khi chuyen sang NGHI VIEC: BA truong BAT BUOC - SMReason (_InvalidSMReason), SMDesc (_InvalidSMDesc), SMEndDate (_SMEndDateNotNull, sai dinh dang => _InvalidSMEndDate).",
        rehireResetNote = "Khi DI LAM LAI (FlagActive -> '1' VA trang thai CU la '0'): nguon XOA VE NULL SMReason/SMDesc/SMEndDate VA dat SMStartDate moi. Day la RESET HO SO NGHI VIEC, khong phai chi doi co. Port bo buoc xoa => nhan vien dang lam van mang ly do nghi cu.",
        startDateGuardNote = "SMStartDate phai LON HON ngay nghi viec gan nhat: 'select max(t.SMEndDate) from Mst_SalesManHistoryInactive t where t.SMHyundaiCode = @...' - do theo MA CA NHAN (nhu guard che tai #B99), khong phai SMCode. Nguon so bang string.CompareTo tren chuoi ngay 'yyyy-MM-dd' (dung thu tu vi dinh dang co dinh); <= 0 la CHAN.",
        historyNote = "GHI LICH SU TRUOC KHI INACTIVE - chi khi THAT SU chuyen Active -> Inactive (strFlagActive=='0' VA FlagActive HIEN TAI TRONG DB == '1'). Chup GIA TRI CU (dt_Mst_SalesManCur), khong phai gia tri vua gan.",
        effectiveColsNote = "alColumnEffective THAY DOI THEO NHANH: luon co FlagActive/SMStatus/UpdateStatusDtime/UpdateStatusBy; them SMReason/SMDesc khi nghi viec; them ca SMStartDate/SMEndDate khi di lam lai. Ghi CA _dbMain va _dbWH.",
        noSuffixNote = "Ten biz KHONG co hau to _NewYYYYMMDD (hiem, nhu #B77)."
    });
}).RequireAuthorization();

// Dấu ngăn của nguồn là `|`; chấp nhận thêm `,` để client hiện tại không vỡ (khác biệt CÓ Ý).
static List<string> SplitConditionList(string? s) =>
    string.IsNullOrWhiteSpace(s)
        ? new List<string>()
        : s.Split(new[] { '|', ',' }, StringSplitOptions.RemoveEmptyEntries)
           .Select(x => x.Trim()).Where(x => x.Length > 0).Distinct().ToList();

app.MapPost("/api/zones/{code}/toggle", async (
    string code, MstZoneToggleDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    var zoneCode = (code ?? "").Trim();
    // `Mst_Zone_CheckDB(…, Flag.Yes, "", …)` — phải TỒN TẠI; KHÔNG kiểm đang bật/tắt.
    var z = await db.MstZones.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ZoneCode == zoneCode);
    if (z is null)
        return Results.NotFound(new { error = "Mst_Zone_NotExist", check = new { ZoneCode = zoneCode } });

    var flag = (dto.FlagActive ?? "").Trim();
    if (flag != "0" && flag != "1")
        return Results.BadRequest(new { error = "Mst_Zone_Update_InvalidFlagActive", check = new { FlagActive = flag } });

    var before = z.FlagActive;
    // `zzB_Update_Mst_Zone_ClauseSet_zzE` — ĐÚNG BA cột, không hơn.
    z.FlagActive = flag;
    z.LogLUDTime = DateTime.Now;
    z.LogLUBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        zoneCode, flagActiveBefore = before, flagActive = z.FlagActive,
        z.LogLUDTime, z.LogLUBy,
        scopeNote = "Mst_Zone_Update CHI doi duoc FlagActive: menh de set cua nguon chi co LogLUDTime, LogLUBy, FlagActive (:4657-4660). KHONG sua duoc ZoneName va KHONG co duong THEM/XOA vung qua WS nay => endpoint la TOGGLE, khong phai upsert.",
        checkDbNote = "Mst_Zone_CheckDB(..., TConst.Flag.Yes, \"\", ...) - vung PHAI TON TAI nhung tham so strFlagActiveListToCheck truyen CHUOI RONG => CO Y KHONG kiem dang bat hay tat (neu khong thi khong bao gio bat lai duoc vung da tat).",
        twoDbNote = "Nguon ghi CA _dbMain va _dbWH (hai lan MyBuildDBDT_Common + cung mot cau update)."
    });
}).RequireAuthorization();

// Thân dùng chung — nguồn là HAI hàm gần như trùng khít, khác đúng giá trị trạng thái gán vào.
async Task<IResult> DlrContractCancelSetStatusMulti(
    List<string> contractCNos, string newStatus, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user, string? buPattern, string? enforceBuScope)
{
    // Bảng đầu vào rỗng BỊ TỪ CHỐI (khác #B76).
    if (contractCNos is null)
        return Results.BadRequest(new { error = "Dlr_ContractCancel_ApproveMulti_Input_ContractCancelTblNotFound" });
    var nos = contractCNos.Select(x => (x ?? "").Trim()).Where(x => x.Length > 0).Distinct().ToList();
    if (nos.Count == 0)
        return Results.BadRequest(new { error = "Dlr_ContractCancel_ApproveMulti_Input_ContractCancelTblInvalid" });

    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();
    var now = DateTime.Now;
    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";

    var heads = await db.DlrContractCancels
        .Where(c => c.OrgId == t.OrgId && nos.Contains(c.ContractCNo)).ToListAsync();
    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId)
        .Select(d => new { d.DealerCode, d.BUCode, d.FlagActive }).ToListAsync();

    // Kiểm TỪNG DÒNG, dừng ngay ở dòng đầu tiên hỏng (nguồn ném trong vòng lặp).
    var outOfScope = new List<string>();
    foreach (var no in nos)
    {
        var h = heads.FirstOrDefault(x => x.ContractCNo == no);
        if (h is null)
            return Results.BadRequest(new { error = "Dlr_ContractCancel_NotExist", check = new { ContractCNo = no } });
        // 🔴 Chỉ phiếu đang "P" — xem `vocabTimeBomb` về hằng nguồn dùng.
        if (h.ContractCancelStatus != "P")
            return Results.BadRequest(new
            {
                error = "Dlr_ContractCancel_InvalidStatus",
                check = new { ContractCNo = no, h.ContractCancelStatus, Expected = "P" }
            });
        var dl = dealers.FirstOrDefault(d => d.DealerCode == h.DealerCode);
        if (dl is null || dl.FlagActive != "1")
            return Results.BadRequest(new { error = "Common_InvalidDealerCode", check = new { ContractCNo = no, h.DealerCode } });
        // `myCommon_CheckAccessDealerData(BUPattern, BUCode)` — phạm vi BU THẬT.
        if (pattern is not null && !(dl.BUCode ?? "").ToUpperInvariant().StartsWith(pattern))
            outOfScope.Add(no);
    }
    if (outOfScope.Count > 0 && enforceBuScope != "0")
        return Results.BadRequest(new
        {
            error = "Common_AccessDealerDataDenied",
            check = new { ContractCNo = outOfScope[0] },
            outOfScope,
            note = "Nguon goi myCommon_CheckAccessDealerData(BUPattern, BUCode) cho TUNG dong va NEM ngay khi mot dong ngoai pham vi."
        });

    // Gán trạng thái + dấu vết. CẢ HAI hàm đều đóng dấu ApprovedDate/ApprovedBy.
    foreach (var h in heads.Where(x => nos.Contains(x.ContractCNo)))
    {
        h.ContractCancelStatus = newStatus;
        h.ApprovedDate = now.Date;
        h.ApprovedBy = by;
        h.LogLUDateTime = now;
        h.LogLUBy = by;
    }

    // CASCADE: trạng thái DÒNG bám theo trạng thái phiếu vừa gán.
    var dtls = await db.DlrContractCancelDtls
        .Where(d => d.OrgId == t.OrgId && nos.Contains(d.ContractCNo)).ToListAsync();
    foreach (var d in dtls)
    {
        d.ContractCancelDtlStatus = newStatus;
        d.LogLUDateTime = now;
        d.LogLUBy = by;
    }

    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        action = newStatus == "A" ? "ApproveMulti" : "CancelMulti",
        newStatus,
        headUpdated = heads.Count,
        dtlUpdated = dtls.Count,
        approvedDate = now.Date, approvedBy = by,
        twinDiffNote = "HAI HAM GIONG NHAU GAN NHU HOAN TOAN - KHAC DUNG MOT DONG: duyet gan ContractCancelStatus.Approved ('A'), huy gan ContractCancelStatus.Cancel ('C'). CA HAI deu dong dau vao ApprovedDate/ApprovedBy - ham HUY KHONG co cap CancelDate/CancelBy rieng. Nghe phan truc giac nhung la hanh vi THAT; port them cap Cancel* la DE COT NGOAI NGUON.",
        vocabTimeBomb = "BOM HEN GIO TU VUNG: guard cua nguon goi Dlr_ContractCancel_CheckDB(..., TConst.TestCarStatus.Pending, ...) - dang le phai la TConst.ContractCancelStatus.Pending. Hien CHAY DUNG vi ca hai hang deu = 'P' (Const.Main.DMS40.cs:127 va :142), nhung day la LIEN KET CHEO PHAN HE: doi TestCarStatus.Pending (xe chay thu) se AM THAM lam hong duyet/huy hop dong dai ly. Port dung tu vung ContractCancelStatus; KHONG tu sua nguon.",
        cascadeNote = "CASCADE xuong DONG: 'update Dlr_ContractCancelDtl set t.ContractCancelDtlStatus = f.ContractCancelStatus' - trang thai dong BAM THEO trang thai phieu vua gan, khong phai mot hang co dinh. Port thieu buoc nay => phieu 'A' ma dong van 'P'.",
        emptyInputNote = "Dau vao la BANG Dlr_ContractCancel (MyBuildDBDT_Common -> #input_Dlr_ContractCancel). Thieu bang => Input_ContractCancelTblNotFound; RONG => Input_ContractCancelTblInvalid. KHAC #B76: o day danh sach rong BI TU CHOI.",
        rbacNote = "RBAC BA TANG kiem THEO TUNG DONG (khong phai mot lan cho ca lo): myCommon_CheckHTCDirect(Active) + myCommon_CheckDealer(Active, Active) + myCommon_CheckAccessDealerData(BUPattern, BUCode). Pham vi BU DUOC THUC THI THAT - doi chung lanh thu hai sau #B78.",
        twoDbNote = "Nguon ghi CA _dbMain va _dbWH (hai lan MyBuildDBDT_Common + hai lan update)."
    });
}

// ===== Cập nhật giá xe thực tế theo VIN (CarActualPrice — port 1:1 FrmUpdateCar, DMSales.Foton) =====
app.MapGet("/api/caractualprices", async (AppDbContext db, ITenantContext t, string? car) =>
{
    var q = db.CarActualPrices.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(car)) q = q.Where(c => c.CarId.Contains(car.Trim().ToUpperInvariant()));
    var items = await q.OrderByDescending(c => c.UpdatedAt).Take(500)
        .Select(c => new { c.CarId, c.UnitPriceActual, c.UpdatedAt }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/caractualprices", async (List<CarPriceUpdateDto> dto, AppDbContext db, ITenantContext t) =>
{
    var rows = (dto ?? new()).Where(d => !string.IsNullOrWhiteSpace(d.CarId)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Mã xe bắt buộc nhập." });
    if (rows.Any(d => d.UnitPriceActual <= 0)) return Results.BadRequest(new { error = "Giá mới không hợp lệ (phải > 0)." });
    var dupe = rows.GroupBy(d => d.CarId.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"Mã xe {dupe.Key} bị trùng!" });
    int inserted = 0, updated = 0;
    foreach (var d in rows)
    {
        var car = d.CarId.Trim().ToUpperInvariant();
        var ex = await db.CarActualPrices.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.CarId == car);
        if (ex is null) { db.CarActualPrices.Add(new CarActualPrice { OrgId = t.OrgId, CarId = car, UnitPriceActual = d.UnitPriceActual }); inserted++; }
        else { ex.UnitPriceActual = d.UnitPriceActual; ex.UpdatedAt = DateTime.Now; updated++; }
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { total = rows.Count, inserted, updated });
}).RequireAuthorization();

// ===== Lệnh đặt xe từ nhà máy (POCommand — port 1:1 FrmNewHMCOrder/FrmMngHMCOrder, DMSales.Foton) =====
app.MapGet("/api/pocommands", async (AppDbContext db, ITenantContext t, string? status, string? month, string? flagActive) =>
{
    var q = db.POCommands.Where(o => o.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(o => o.Status == status);
    if (!string.IsNullOrWhiteSpace(month)) q = q.Where(o => o.OrderMonth == month);
    // Nguồn lọc theo cờ FlagActive (không có trạng thái); giữ tham số `status` cho tương thích cũ.
    if (!string.IsNullOrWhiteSpace(flagActive)) q = q.Where(o => o.FlagActive == flagActive);
    var items = await q.OrderByDescending(o => o.Id).Take(500).Select(o => new
    {
        o.PoCmdCode, o.OrderMonth, o.ProductionMonth, o.ExpectedMonth, o.FlagActive, o.CreatedBy, o.CreatedAt,
        lines = db.POCommandLines.Count(l => l.OrgId == t.OrgId && l.PoCmdId == o.Id),
        totalQty = db.POCommandLines.Where(l => l.OrgId == t.OrgId && l.PoCmdId == o.Id).Sum(l => (int?)l.Quantity) ?? 0
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/pocommands", async (POCommandDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    // ===== #173 port TRỌN `OrderPOCommandCreate_New20181119` (DataWH/Biz.HTC.WH.cs:28295, csproj 272) =====
    // BƯỚC 3B: hàm bắt đầu **cùng dòng 28295 ở CẢ HAI máy**, vùng 266 dòng md5 `076e3384` KHỚP.
    // TWIN: WS 32-bit (`App_Code/WSHTC.cs:5377`) và 64-bit (`WSHTC.asmx.cs:7286`) gọi **cùng** bản.
    // ⚠️ Lượt trước grep `_biz.Ord_POCommand` ra mỗi `_Get`/`_GetWH` rồi tưởng cụm chỉ có đọc —
    //    tên lệnh thật là `OrderPOCommandCreate` (KHÔNG có tiền tố `Ord_`). Lại đúng lớp "grep sai tên".
    //
    // 🔴 BỐN sai chiều của port cũ, sửa hết trong lượt này:
    //   1. **Số lệnh do NGƯỜI DÙNG nhập** (`strPOCommandCode`), guard `Length >= TConst.HTCConst.MinLengthCode` (=5).
    //      Port cũ tự sinh `"POC"+timestamp` ⇒ mã không khớp hệ nguồn (cùng lỗi đã gặp ở phiếu điều chỉnh).
    //   2. **Ba cột tháng do SERVER TỰ TÍNH**, không lấy input:
    //      `OrderMonth` = tháng hiện tại · `ProductionMonth` = +1 tháng · `ExpectedMonth` = +2 tháng.
    //   3. **`ModelCode` SUY RA từ `SpecCode`** qua `myCommon_CheckSpecCode` (`dr["ModelCode"] = dt_Mst_CarSpec...`),
    //      KHÔNG lấy từ input; và cặp model–màu phải khớp master (`myCommon_CheckMatchingModelAndColor`).
    //   4. Nguồn chỉ chặn `Quantity < 0` ⇒ **dòng số lượng 0 là HỢP LỆ**. Port cũ lọc `Quantity > 0`,
    //      tức âm thầm **vứt bỏ** các dòng đặt 0 xe — sai dữ liệu, không sai build.
    var code = (dto.PoCmdCode ?? "").Trim().ToUpperInvariant();
    if (code.Length < 5)
        return Results.BadRequest(new { error = "Số lệnh đặt xe phải có ít nhất 5 ký tự." });
    if (await db.POCommands.AnyAsync(x => x.OrgId == t.OrgId && x.PoCmdCode == code))
        return Results.BadRequest(new { error = $"Số lệnh {code} đã tồn tại!" });

    // `TableDetailBeBlank`
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.SpecCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Chưa có dòng chi tiết nào." });

    var now = DateTime.Now;
    // #B34 StandardizeMonth (Utils.cs:382-389) tra "yyyy-MM-01", KHONG phai "yyyyMM".
    var orderMonth = now.ToString("yyyy-MM") + "-01";
    var productionMonth = now.AddMonths(1).ToString("yyyy-MM") + "-01";
    var expectedMonth = now.AddMonths(2).ToString("yyyy-MM") + "-01";

    // Quét từng dòng: khoá trùng · số lượng · spec · cặp model–màu.
    var seen = new HashSet<string>();
    var built = new List<POCommandLine>();
    foreach (var l in lines)
    {
        var spec = l.SpecCode!.Trim().ToUpperInvariant();
        var color = (l.ColorCode ?? "").Trim().ToUpperInvariant();
        var lcTemp = (l.LCTemp ?? "").Trim().ToUpperInvariant();

        // `InvalidDetailQuantity`: nguồn chặn ÂM, cho phép 0.
        if (l.Quantity < 0)
            return Results.BadRequest(new { error = $"Spec {spec}: số lượng không hợp lệ.", specCode = spec });

        // `myCommon_CheckSpecCode(..., Flag.Active)` ⇒ lấy ModelCode TỪ MASTER.
        var sp = await db.CarSpecs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SpecCode == spec && x.FlagActive == "1");
        if (sp is null) return Results.BadRequest(new { error = $"Spec {spec} không tồn tại hoặc đã ngừng hoạt động.", specCode = spec });
        var model = sp.ModelCode;

        // `myCommon_CheckMatchingModelAndColor` — cặp model–màu phải có trong master màu.
        if (color.Length > 0)
        {
            var okColor = await db.MstCarColors.AnyAsync(x => x.OrgId == t.OrgId && x.ModelCode == model && x.ColorCode == color && x.FlagActive == "1");
            if (!okColor) return Results.BadRequest(new { error = $"Màu {color} không thuộc model {model}.", specCode = spec, colorCode = color });
        }

        // `DuplicateKeyDetail` — khoá NĂM phần của nguồn: |POCommandCode||LCTemp||SpecCode||ModelCode||ColorCode|
        var key = $"|{code}||{lcTemp}||{spec}||{model}||{color}|";
        if (!seen.Add(key))
            return Results.BadRequest(new { error = $"Dòng trùng khoá (LCTemp/Spec/Model/Màu): {lcTemp}/{spec}/{model}/{color}.", key });

        built.Add(new POCommandLine
        {
            OrgId = t.OrgId, SpecCode = spec, SpecDesc = sp.SpecDesc,
            ModelCode = model,          // suy ra từ master, KHÔNG lấy input
            ColorCode = color, PortCode = l.PortCode, PlantCode = l.PlantCode,
            LCTemp = lcTemp, Quantity = l.Quantity
        });
    }

    var o = new POCommand
    {
        OrgId = t.OrgId, PoCmdCode = code,
        OrderMonth = orderMonth, ProductionMonth = productionMonth, ExpectedMonth = expectedMonth,
        CreatedBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system",
        CreatedAt = now,
        FlagActive = "1", Status = "Draft",
    };
    db.POCommands.Add(o); await db.SaveChangesAsync();
    foreach (var b in built) { b.PoCmdId = o.Id; db.POCommandLines.Add(b); }
    await db.SaveChangesAsync();
    return Results.Ok(new { o.PoCmdCode, o.OrderMonth, o.ProductionMonth, o.ExpectedMonth, o.CreatedBy, o.FlagActive,
        lines = built.Count, totalQty = built.Sum(l => l.Quantity) });
}).RequireAuthorization();

app.MapGet("/api/pocommands/{no}/lines", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var o = await db.POCommands.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PoCmdCode == no);
    if (o is null) return Results.NotFound(new { no });
    var lines = await db.POCommandLines.Where(l => l.OrgId == t.OrgId && l.PoCmdId == o.Id)
        .Select(l => new { l.SpecCode, l.SpecDesc, l.ModelCode, l.ColorCode, l.PortCode, l.PlantCode, l.LCTemp, l.Quantity }).ToListAsync();
    return Results.Ok(new { o.PoCmdCode, o.OrderMonth, o.ProductionMonth, o.ExpectedMonth, o.FlagActive, o.CreatedBy, count = lines.Count, lines, totalQty = lines.Sum(x => x.Quantity) });
}).RequireAuthorization();

// ⚠️ ĐÃ BỎ `/send`: nguồn KHÔNG có bước "gửi hãng" — `Ord_POCommand` không có cột trạng thái nào.
// 🔴 HUỶ LỆNH — `OrderPOCommandCancel_New20181119` (Biz.HTC.WH.cs:28555-28640): guard
// `myOrder_CheckPOCommand(..., Flag.Active)` rồi gán `FlagActive = Flag.Inactive` ("0").
// Đây là **hành động đổi trạng thái DUY NHẤT** của cụm này.
app.MapPost("/api/pocommands/{no}/cancel", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var o = await db.POCommands.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PoCmdCode == no);
    if (o is null) return Results.NotFound(new { no });
    if (o.FlagActive != "1") return Results.BadRequest(new { error = "Lệnh đặt hàng đã huỷ." });
    o.FlagActive = "0";
    await db.SaveChangesAsync();
    return Results.Ok(new { o.PoCmdCode, o.FlagActive });
}).RequireAuthorization();

// ===== Hóa đơn dịch vụ (Ser_Invoice — port 1:1 FrmInvoice) =====
app.MapGet("/api/serviceinvoices", async (AppDbContext db, ITenantContext t, string? status, string? ro) =>
{
    var q = db.ServiceInvoices.Where(i => i.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(i => i.Status == status);
    if (!string.IsNullOrWhiteSpace(ro)) q = q.Where(i => i.RONo.Contains(ro.ToUpper()));
    var items = await q.OrderByDescending(i => i.Id).Take(500).Select(i => new
    {
        i.InvoiceNo, i.RONo, i.SubTotal, i.VatPercent, i.VatAmount, i.DiscountAmount, i.TotalAmount, i.PaymentType, i.Status, i.PaidAt,
        // GAP đã vá: 6 cột tiền/điểm trước đây không được trả về
        i.AmountFromMC, i.AmountDiscountOther, i.TotalBeforeTax, i.TotalAfterTax, i.PointTotal, i.CardTypeExpect
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, totalRevenue = items.Where(x => x.Status == "Paid").Sum(x => x.TotalAmount), items });
}).RequireAuthorization();

// Lập hóa đơn từ RO: kéo Σ tiền công + Σ (SL×đơn giá PT), áp VAT + chiết khấu
app.MapPost("/api/serviceinvoices", async (ServiceInvoiceDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.RONo)) return Results.BadRequest(new { error = "Cần RONo." });
    var roNo = dto.RONo.Trim().ToUpperInvariant();
    var ro = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == roNo);
    if (ro is null) return Results.NotFound(new { error = $"Không tìm thấy RO {roNo}." });
    if (ro.Status is "HasRO" or "InGarage") return Results.BadRequest(new { error = "RO chưa sửa xong, chưa lập hóa đơn được." });
    if (await db.ServiceInvoices.AnyAsync(x => x.OrgId == t.OrgId && x.RONo == roNo && x.Status == "Paid"))
        return Results.BadRequest(new { error = "RO đã có hóa đơn thanh toán." });
    var svcTotal = await db.RoServiceItems.Where(s => s.OrgId == t.OrgId && s.RoId == ro.Id).SumAsync(s => (decimal?)s.Amount) ?? 0;
    var partTotal = await db.RoPartItems.Where(p => p.OrgId == t.OrgId && p.RoId == ro.Id).SumAsync(p => (decimal?)(p.NeedQty * p.UnitPrice)) ?? 0;
    var subTotal = svcTotal + partTotal;
    var vatPercent = dto.VatPercent < 0 ? 0 : dto.VatPercent;
    var discount = dto.DiscountAmount < 0 ? 0 : dto.DiscountAmount;

    // GAP đã vá — luật txtAmountDiscountOther_EditValueChanging của FrmInvoice:
    // "chiết khấu khác" phải là SỐ NGUYÊN >= 0, form gốc CHẶN NHẬP (e.Cancel) nếu vi phạm.
    // API không có sự kiện gõ nên phải kiểm ở server, nếu không sẽ lọt số lẻ/số âm.
    var amountDiscountOther = dto.AmountDiscountOther;
    if (amountDiscountOther < 0 || amountDiscountOther != Math.Floor(amountDiscountOther))
        return Results.BadRequest(new { error = "Chiết khấu khác phải là số nguyên dương(>=0)!" });

    // Chiết khấu từ hãng (AmountFromMC) — nguồn tách RIÊNG với chiết khấu khác để còn đối soát.
    var amountFromMC = dto.AmountFromMC < 0 ? 0 : dto.AmountFromMC;

    var vatAmount = Math.Round(subTotal * vatPercent / 100m, 0);
    var totalBeforeTax = subTotal;
    var totalAfterTax = subTotal + vatAmount;
    // Tổng phải trả = sau thuế − (chiết khấu chung + chiết khấu hãng + chiết khấu khác)
    var total = totalAfterTax - discount - amountFromMC - amountDiscountOther;
    if (total < 0) total = 0;

    var no = "INV" + DateTime.Now.ToString("yyMMddHHmmss");
    var inv = new ServiceInvoice
    {
        OrgId = t.OrgId, InvoiceNo = no, RONo = roNo, SubTotal = subTotal, VatPercent = vatPercent, VatAmount = vatAmount,
        DiscountAmount = discount, TotalAmount = total, PaymentType = dto.PaymentType, Status = "Draft",
        // GAP đã vá: 6 cột tiền/điểm của FrmInvoice
        AmountFromMC = amountFromMC, AmountDiscountOther = amountDiscountOther,
        TotalBeforeTax = totalBeforeTax, TotalAfterTax = totalAfterTax,
        PointTotal = dto.PointTotal < 0 ? 0 : dto.PointTotal, CardTypeExpect = dto.CardTypeExpect
    };
    db.ServiceInvoices.Add(inv); await db.SaveChangesAsync();
    return Results.Ok(new
    {
        inv.InvoiceNo, inv.RONo, inv.SubTotal, inv.VatAmount, inv.DiscountAmount, inv.TotalAmount, status = inv.Status,
        inv.AmountFromMC, inv.AmountDiscountOther, inv.TotalBeforeTax, inv.TotalAfterTax, inv.PointTotal, inv.CardTypeExpect
    });
}).RequireAuthorization();

// Thanh toán → Paid; nếu RO đang CheckEnd thì đẩy sang Paid (tích hợp workflow RO)
app.MapPost("/api/serviceinvoices/{no}/pay", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var inv = await db.ServiceInvoices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.InvoiceNo == no);
    if (inv is null) return Results.NotFound(new { no });
    if (inv.Status != "Draft") return Results.BadRequest(new { error = "Hóa đơn đã thanh toán." });
    inv.Status = "Paid"; inv.PaidAt = DateTime.Now;
    var ro = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == inv.RONo);
    string? roAdvanced = null;
    if (ro is not null && ro.Status == "CheckEnd") { ro.Status = "Paid"; roAdvanced = "Paid"; }
    await db.SaveChangesAsync();
    return Results.Ok(new { inv.InvoiceNo, status = inv.Status, roAdvancedTo = roAdvanced });
}).RequireAuthorization();

