// ===== 🔴 #216 LỊCH HẸN BẢO DƯỠNG đã chốt ngày — `Ser_CustomerCareMaceApointDate_Get` =====
// Màn gốc: `Views/Customer/FrmCustomerCareMaceApointDate.cs` (369 dòng, DMSCarSv) —
//   ba nút `btnSearch` · `btnExportExcel` · `btnThoat` (grep KHÔNG phân biệt hoa/thường, luật #212).
// Nguồn: `TERP.BizCarSv/BizCarSv.Customer.cs:13429`. 3B: md5 CẢ FILE `44c7c87b` KHỚP 2 máy (đo ở #210).
//
// 🔴 HAI GUARD CỨNG trong chính câu SQL của nguồn (không phải tham số lọc):
//     `and t.Status = '1'`            — CHỈ lấy dòng **đã liên hệ**
//     `and t.ApointDate is not null`  — và **đã chốt ngày hẹn**
//   ⇒ đây là màn "lịch hẹn đã chốt", KHÔNG phải danh sách nhắc bảo dưỡng nói chung
//     (danh sách chung là `/api/customercaremaces` đã có, lọc status tuỳ ý).
//
// Bảng mã `TConst.SerCareMaceStatus` (Const.Main.cs:365): **0 chưa liên hệ · 1 đã liên hệ · 2 không liên hệ**
//   — nguồn dịch sang chữ ngay trong SELECT (`StatusText`); port trả kèm để khỏi map lại ở client.
// Bộ lọc của form: tên khách + biển số + khoảng `ApointDate` (from/to). Nguồn dựng bằng `BuildClause`,
//   chuỗi rỗng ⇒ **bỏ hẳn điều kiện** (luật `C0-trecentesimusvicesimusquartus`).
app.MapGet("/api/customercaremaces/appointments", async (AppDbContext db, ITenantContext t,
    string? cusName, string? plateNo, DateTime? fromDate, DateTime? toDate) =>
{
    // hai guard cứng của nguồn — luôn áp, không cho client tắt
    var qy = db.CustomerCareMaces.Where(c => c.OrgId == t.OrgId && c.Status == "1" && c.ApointDate != null);

    if (!string.IsNullOrWhiteSpace(cusName))
        qy = qy.Where(c => c.CusName != null && c.CusName.ToLower().Contains(cusName!.Trim().ToLower()));
    if (!string.IsNullOrWhiteSpace(plateNo))
        qy = qy.Where(c => c.Vin != null && c.Vin.ToLower().Contains(plateNo!.Trim().ToLower()));
    if (fromDate.HasValue) qy = qy.Where(c => c.ApointDate!.Value.Date >= fromDate.Value.Date);
    if (toDate.HasValue) qy = qy.Where(c => c.ApointDate!.Value.Date <= toDate.Value.Date);

    var items = await qy.OrderBy(c => c.ApointDate).Take(500)
        .Select(c => new
        {
            c.CareNo, c.MaceType, c.RONo, c.Vin, c.CusName,
            c.Status,
            statusText = c.Status == "0" ? "Chưa liên hệ" : c.Status == "1" ? "Đã liên hệ" : c.Status == "2" ? "Không liên hệ" : c.Status,
            c.ContactDate, c.ApointDate, c.MaceRecomentDate, c.Remark
        }).ToListAsync();

    return Results.Ok(new { count = items.Count, items,
        note = "Luôn lọc Status='1' (đã liên hệ) và ApointDate != null — hai điều kiện nằm CỨNG trong SQL nguồn.",
        skipped = "Nguồn còn join Ser_Car (FrameNo) + ser_mst_model + ser_ro để hiện khung/model/lệnh sửa chữa — MiniHTC lưu Vin trên chính dòng, chưa nối các bảng đó, KHÔNG bịa." });
}).RequireAuthorization();

app.MapPost("/api/customercaremaces", async (CustomerCareMaceDto dto, AppDbContext db, ITenantContext t) =>
{
    var maceType = (dto.MaceType ?? "").Trim();
    if (string.IsNullOrWhiteSpace(maceType)) return Results.BadRequest(new { error = "Chưa nhập MaceType." });
    if (string.IsNullOrWhiteSpace(dto.Vin) && string.IsNullOrWhiteSpace(dto.CusName))
        return Results.BadRequest(new { error = "Cần VIN hoặc tên khách." });
    var no = "MC" + DateTime.Now.ToString("yyMMddHHmmss");
    var c = new CustomerCareMace
    {
        OrgId = t.OrgId, CareNo = no, MaceType = maceType, RONo = dto.RONo, Vin = dto.Vin?.Trim().ToUpperInvariant(),
        CusName = dto.CusName, MaceRecomentDate = dto.MaceRecomentDate, Status = "Pending"
    };
    db.CustomerCareMaces.Add(c); await db.SaveChangesAsync();
    return Results.Ok(new { c.CareNo, c.MaceType, status = c.Status });
}).RequireAuthorization();

// Cập nhật trạng thái liên hệ (khớp FrmCustomerCareMaceUpdate: Contacted bắt buộc có ContactDate).
app.MapPost("/api/customercaremaces/{no}/contact", async (string no, CareMaceContactDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var c = await db.CustomerCareMaces.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CareNo == no);
    if (c is null) return Results.NotFound(new { no });
    var status = (dto.Status ?? "").Trim();
    if (!_maceStatuses.Contains(status)) return Results.BadRequest(new { error = "Status = Pending|Contacted|NotContacted" });
    if (status == "Contacted" && dto.ContactDate is null)
        return Results.BadRequest(new { error = "Bạn chưa nhập Ngày liên hệ. Hãy nhập Ngày liên hệ để cập nhật tình trạng liên hệ." });
    c.Status = status; c.Remark = dto.Remark;
    c.ContactDate = status == "Contacted" ? dto.ContactDate : null;
    c.ApointDate = status == "Contacted" ? dto.ApointDate : null;
    await db.SaveChangesAsync();
    return Results.Ok(new { c.CareNo, status = c.Status });
}).RequireAuthorization();

// ===== Xe của khách hàng (Ser_Car — port 1:1 FrmCustomerCar) =====
app.MapGet("/api/customercars", async (AppDbContext db, ITenantContext t, string? plate, string? vin, string? cus) =>
{
    var q = db.CustomerCars.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(plate)) q = q.Where(c => c.PlateNo.Contains(plate.ToUpper()));
    if (!string.IsNullOrWhiteSpace(vin)) q = q.Where(c => c.Vin.Contains(vin.ToUpper()));
    if (!string.IsNullOrWhiteSpace(cus)) q = q.Where(c => (c.CusName != null && c.CusName.Contains(cus)) || (c.CusPhone != null && c.CusPhone.Contains(cus)));
    var items = await q.OrderBy(c => c.PlateNo).Take(500).Select(c => new
    { c.Vin, c.PlateNo, c.FrameNo, c.EngineNo, c.ModelCode, c.ColorCode, c.PlateColorCode, c.CusCode, c.CusName, c.CusPhone, c.SaleDate }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/customercars", async (CustomerCarDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.Vin) && string.IsNullOrWhiteSpace(dto.PlateNo))
        return Results.BadRequest(new { error = "Cần VIN hoặc biển số." });
    var vin = (dto.Vin ?? "").Trim().ToUpperInvariant();
    var plate = (dto.PlateNo ?? "").Trim().ToUpperInvariant();
    // upsert theo VIN nếu có, ngược lại theo biển số
    CustomerCar? c = null;
    if (vin.Length > 0) c = await db.CustomerCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Vin == vin);
    if (c is null && plate.Length > 0) c = await db.CustomerCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Vin == "" && x.PlateNo == plate);
    if (c is null) { c = new CustomerCar { OrgId = t.OrgId, Vin = vin, PlateNo = plate }; db.CustomerCars.Add(c); }
    else { if (vin.Length > 0) c.Vin = vin; if (plate.Length > 0) c.PlateNo = plate; }
    c.FrameNo = dto.FrameNo; c.EngineNo = dto.EngineNo; c.ModelCode = dto.ModelCode; c.ColorCode = dto.ColorCode; c.PlateColorCode = dto.PlateColorCode;
    c.CusCode = dto.CusCode; c.CusName = dto.CusName; c.CusPhone = dto.CusPhone; c.SaleDate = dto.SaleDate; c.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { c.Vin, c.PlateNo, c.CusName });
}).RequireAuthorization();

// ===== Giá bán phụ tùng theo ngày hiệu lực (Ser_Inv_PartPrice — port 1:1 FrmPartPriceCreate) =====
app.MapGet("/api/partprices", async (AppDbContext db, ITenantContext t, string? part, string? onDate) =>
{
    var q = db.PartPrices.Where(p => p.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(part)) q = q.Where(p => p.PartCode.Contains(part.ToUpper()));
    var items = await q.OrderBy(p => p.PartCode).ThenByDescending(p => p.EffectiveDate).Take(1000).Select(p => new
    { p.PartCode, p.PartName, p.Price, p.VAT, p.PriceVAT, p.EffectiveDate, p.Status }).ToListAsync();
    object? applicable = null;
    if (!string.IsNullOrWhiteSpace(part) && DateTime.TryParse(onDate, out var od))
        applicable = items.Where(x => x.PartCode == part.Trim().ToUpperInvariant() && x.EffectiveDate <= od)
            .OrderByDescending(x => x.EffectiveDate).FirstOrDefault();
    return Results.Ok(new { count = items.Count, applicable, items });
}).RequireAuthorization();

app.MapPost("/api/partprices", async (PartPriceDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.PartCode)) return Results.BadRequest(new { error = "Cần PartCode." });
    if (dto.EffectiveDate is null) return Results.BadRequest(new { error = "Cần EffectiveDate." });
    var code = dto.PartCode.Trim().ToUpperInvariant();
    var ed = dto.EffectiveDate.Value.Date;
    var p = await db.PartPrices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PartCode == code && x.EffectiveDate == ed);
    if (p is null) { p = new PartPrice { OrgId = t.OrgId, PartCode = code, EffectiveDate = ed }; db.PartPrices.Add(p); }
    p.PartName = dto.PartName; p.Price = dto.Price; p.VAT = dto.VAT; p.PriceVAT = Math.Round(dto.Price * (1 + dto.VAT / 100m), 2);
    p.Status = dto.Status ?? "1"; p.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { p.PartCode, p.Price, p.VAT, p.PriceVAT, p.EffectiveDate });
}).RequireAuthorization();

