// ===== Cập nhật VIN thật FVIN→RVIN (Sto_TranspPlanMapVinReal — port 1:1 FrmUpdateFVINToRVIN) =====
// Map VIN kế hoạch (FVIN) sang VIN thật (RVIN) trên KH vận chuyển; batch như import Excel A1.
app.MapPost("/api/transplans/mapvin", async (MapVinDto dto, AppDbContext db, ITenantContext t) =>
{
    var pairs = (dto.Pairs ?? new List<VinPairDto>())
        .Where(p => !string.IsNullOrWhiteSpace(p.FVIN) && !string.IsNullOrWhiteSpace(p.RVIN)).ToList();
    if (pairs.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 cặp FVIN/RVIN." });
    var results = new List<object>(); int nOk = 0;
    int mapped = 0;
    foreach (var p in pairs)
    {
        var fv = p.FVIN.Trim().ToUpperInvariant();
        var rv = p.RVIN.Trim().ToUpperInvariant();
        var plan = await db.TransportPlans.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.VINPlan == fv);
        if (plan is null) { results.Add(new { fvin = fv, rvin = rv, ok = false, warning = $"VIN kế hoạch {fv} không tồn tại (không map được carId)." }); continue; }
        plan.Vin = rv; mapped++;
        results.Add(new { fvin = fv, rvin = rv, ok = true });
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { total = pairs.Count, mapped, results });
}).RequireAuthorization();

// ===== Yêu cầu vận chuyển thu hồi xe (StoTranspReq — port 1:1 FrmNewRetrieveTransReq/FrmMngRetrieveTransReq) =====
string[] _transpReqTypes = { "Retrieve", "StorageRearrCB", "StorageRearrange" };
string _transpReqPrefix(string type) => type switch { "StorageRearrCB" => "RCB", "StorageRearrange" => "RRG", _ => "RTR" };
app.MapGet("/api/retrievereqs", async (AppDbContext db, ITenantContext t, string? status, string? dealer, string? type) =>
{
    var q = db.RetrieveRequests.Where(r => r.OrgId == t.OrgId && r.TranspReqTypeHeaderOnly == (string.IsNullOrWhiteSpace(type) ? "Retrieve" : type));
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(r => r.Status == status);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(r => r.DealerCode == dealer);
    var items = await q.OrderByDescending(r => r.Id).Take(500).Select(r => new
    {
        r.TranspReqNo, r.DealerCode, r.TransporterCode, r.Reason, r.Status, r.CreatedAt, r.DecidedAt, r.TranspReqTypeHeaderOnly,
        // #156 parity Sto_TranspReq.
        r.TransportContractNo, r.CreatedBy, r.ApprovedBy, r.LogLUDateTime, r.LogLUBy,
        cars = db.RetrieveReqCars.Count(c => c.OrgId == t.OrgId && c.ReqId == r.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// type: Retrieve (mặc định, FrmNewRetrieveTransReq) | StorageRearrCB (FrmMngRearCBTranspReq — YC chuyển kho đóng thùng) | StorageRearrange (FrmMngRearrangeTranspReq).
app.MapPost("/api/retrievereqs", async (RetrieveReqDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode) || string.IsNullOrWhiteSpace(dto.TransporterCode))
        return Results.BadRequest(new { error = "Cần DealerCode và TransporterCode." });
    var type = string.IsNullOrWhiteSpace(dto.TranspReqType) ? "Retrieve" : dto.TranspReqType.Trim();
    if (!_transpReqTypes.Contains(type)) return Results.BadRequest(new { error = "TranspReqType = Retrieve|StorageRearrCB|StorageRearrange" });
    var vins = (dto.Cars ?? new List<RetrieveReqCarDto>()).Where(c => !string.IsNullOrWhiteSpace(c.Vin)).ToList();
    if (vins.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 VIN." });
    var dupe = vins.GroupBy(c => c.Vin.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });
    var no = _transpReqPrefix(type) + DateTime.Now.ToString("yyMMddHHmmss");
    var r = new RetrieveRequest { OrgId = t.OrgId, TranspReqNo = no, DealerCode = dto.DealerCode.Trim().ToUpperInvariant(), TransporterCode = dto.TransporterCode.Trim().ToUpperInvariant(), Reason = dto.Reason, Status = "Pending", TranspReqType = type ,
        // #156 parity Sto_TranspReq.
        TransportContractNo = dto.TransportContractNo, CreatedBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system",
        LogLUDateTime = DateTime.Now, LogLUBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system" };
    db.RetrieveRequests.Add(r); await db.SaveChangesAsync();
    foreach (var c in vins)
        db.RetrieveReqCars.Add(new RetrieveReqCar { OrgId = t.OrgId, ReqId = r.Id, Vin = c.Vin.Trim().ToUpperInvariant(), StorageCode = c.StorageCode, DtlStatus = "Pending" ,
            // #156 parity Sto_TranspReqDtl — loại nằm ở DÒNG; nếu client chưa gửi thì lấy loại của phiếu.
            TranspReqType = c.TranspReqType ?? type, RefOrdNo = c.RefOrdNo,
            // 🔴 luật nguồn (Biz.HTC.WH.cs:109610): điều chuyển kho ⇒ CarId để NULL.
            CarId = ((c.TranspReqType ?? type) is "STORAGEREARRANGE" or "STORAGEREARRCB") ? null : c.CarId,
            LogLUDateTime = DateTime.Now, LogLUBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system" });
    await db.SaveChangesAsync();
    return Results.Ok(new { r.TranspReqNo, r.DealerCode, r.TransporterCode, cars = vins.Count, status = r.Status });
}).RequireAuthorization();

